# Official Microsoft sources only. Do not add third-party or "all-in-one
# runtime pack" mirrors -- those are a common malware vector and exactly
# what this function is meant to avoid.
#
# 'urls' is tried in order (first is the stable aka.ms redirect, which
# Microsoft maintains long-term and is unlikely to ever go stale).
# 'discovery_page' is a LAST-RESORT fallback: if every direct URL fails,
# we fetch that official Microsoft page and look for a fresh .exe link
# on the same download.microsoft.com / aka.ms domains, so a future
# broken link doesn't leave users stuck.
_BT_REDIST_SOURCES = [
    {
        'name': 'VC++ Redistributable (x64)',
        'filename': 'vc_redist.x64.exe',
        'urls': ['https://aka.ms/vs/17/release/vc_redist.x64.exe'],
        'discovery_page': 'https://learn.microsoft.com/en-us/cpp/windows/latest-supported-vc-redist',
        'args': ['/install', '/quiet', '/norestart'],
    },
    {
        'name': 'DirectX End-User Runtime',
        'filename': 'dxwebsetup.exe',
        'urls': [
            'https://download.microsoft.com/download/1/7/1/1718CCC4-6315-4D8E-9543-8E28A4E18C4C/dxwebsetup.exe',
        ],
        'discovery_page': 'https://www.microsoft.com/en-us/download/details.aspx?id=35',
        'args': ['/Q'],
    },
]

_BT_TRUSTED_DOWNLOAD_HOSTS = ('download.microsoft.com', 'aka.ms', 'go.microsoft.com')


def _bt_download_file(url, dest_path, timeout=60):
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    with urllib.request.urlopen(req, timeout=timeout) as resp, open(dest_path, 'wb') as out:
        shutil.copyfileobj(resp, out)


def _bt_discover_installer_url(discovery_page, filename_hint):
    """
    Last-resort fallback used only when every known direct URL for a
    redistributable has failed. Fetches an official Microsoft page and
    looks for a .exe link that (a) points at a trusted Microsoft host
    and (b) matches the expected filename pattern. Never follows or
    returns a link to any non-Microsoft domain.
    """
    try:
        req = urllib.request.Request(discovery_page, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=30) as resp:
            html = resp.read().decode('utf-8', errors='ignore')
    except Exception:
        return None

    candidates = re.findall(r'https://[^\s"\'<>]+?\.exe', html, flags=re.IGNORECASE)
    stem = os.path.splitext(filename_hint)[0].lower()
    for link in candidates:
        parsed_host = urllib.parse.urlparse(link).netloc.lower()
        if not any(parsed_host == h or parsed_host.endswith('.' + h) for h in _BT_TRUSTED_DOWNLOAD_HOSTS):
            continue
        if stem in link.lower() or 'redist' in link.lower() or 'dxwebsetup' in link.lower() or 'vc_redist' in link.lower():
            return link
    # Fall back to first trusted-host .exe link found, if any.
    for link in candidates:
        parsed_host = urllib.parse.urlparse(link).netloc.lower()
        if any(parsed_host == h or parsed_host.endswith('.' + h) for h in _BT_TRUSTED_DOWNLOAD_HOSTS):
            return link
    return None


def _bt_download_with_fallback(item, dest_path, log):
    urls_to_try = list(item.get('urls', []))
    for url in urls_to_try:
        try:
            _bt_download_file(url, dest_path)
            log.write(f"{item['filename']}: downloaded from {url}\n")
            return True
        except Exception as exc:
            log.write(f"{item['filename']}: FAILED from {url} ({exc})\n")

    # All known direct links failed -- try to discover a fresh one.
    discovery_page = item.get('discovery_page')
    if discovery_page:
        log.write(f"{item['filename']}: trying link discovery via {discovery_page}\n")
        fresh_url = _bt_discover_installer_url(discovery_page, item['filename'])
        if fresh_url:
            try:
                _bt_download_file(fresh_url, dest_path)
                log.write(f"{item['filename']}: downloaded via discovered link {fresh_url}\n")
                return True
            except Exception as exc:
                log.write(f"{item['filename']}: discovered link also FAILED ({exc})\n")
        else:
            log.write(f"{item['filename']}: no trusted link found on discovery page\n")
    return False


def _bt_ensure_runtime_dependencies(progress_cb=None):
    """
    First-run bootstrap: downloads and silently installs common Windows
    runtime redistributables (VC++ runtime, DirectX) directly from
    Microsoft's own servers, then installs them. Nothing is bundled
    inside the exe -- everything is fetched fresh at install time.

    Each dependency has a primary (stable aka.ms) URL plus a discovery
    fallback: if the primary link ever goes stale, we fetch an official
    Microsoft page and extract a current link from it, restricted to
    Microsoft's own domains. This does NOT touch Vulkan/OpenGL: those
    come from GPU vendor drivers and cannot be safely silent-installed
    from a generic script. We never attempt to push a driver onto the
    user's system; if rendering init fails later, the app should just
    tell the user to update their graphics driver.

    Safe to call every launch: it exits immediately after the first
    successful run via a marker file, so it costs nothing later on.
    progress_cb(str), if given, is called with short status strings so
    the caller can show them in a splash/progress dialog.
    """
    if os.name != 'nt':
        return

    def _report(msg):
        if progress_cb:
            try:
                progress_cb(msg)
            except Exception:
                pass

    try:
        appdata = os.environ.get('APPDATA') or os.path.expanduser('~')
        state_dir = os.path.join(appdata, 'PS5Launcher')
        os.makedirs(state_dir, exist_ok=True)
        flag_path = os.path.join(state_dir, 'deps_installed.flag')
        if os.path.exists(flag_path):
            return

        tmp_dir = os.path.join(state_dir, 'redist_tmp')
        os.makedirs(tmp_dir, exist_ok=True)
        log_path = os.path.join(state_dir, 'deps_install.log')

        with open(log_path, 'a', encoding='utf-8') as log:
            for item in _BT_REDIST_SOURCES:
                installer_path = os.path.join(tmp_dir, item['filename'])
                _report(f"Downloading {item['name']}...")
                if not _bt_download_with_fallback(item, installer_path, log):
                    _report(f"Could not download {item['name']}, skipping")
                    continue

                _report(f"Installing {item['name']}...")
                try:
                    result = subprocess.run(
                        [installer_path] + item['args'],
                        check=False,
                        timeout=300,
                        capture_output=True,
                        creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0),
                    )
                    # Many redistributable installers return a nonzero code
                    # when the component is already installed/up to date --
                    # that's not a real failure, so we just log it.
                    log.write(f"{item['filename']}: exit={result.returncode}\n")
                except Exception as exc:
                    log.write(f"{item['filename']}: INSTALL FAILED ({exc})\n")
                finally:
                    try:
                        os.remove(installer_path)
                    except OSError:
                        pass

        # Auto-install optional requirements that used to be shown on a
        # separate "Requirements" settings page (PyQt6-WebEngine, ViGEmBus).
        # That page has been removed; installation now happens silently
        # here, on first run, alongside the other runtime dependencies.
        try:
            for req in _REQUIREMENTS_LIST:
                if importlib.util.find_spec(req['module']) is None:
                    _report(f"Installing {req['title']}...")
                    try:
                        subprocess.run(
                            [sys.executable, '-m', 'pip', 'install', req['pip_name']],
                            capture_output=True, text=True, timeout=600,
                            creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0),
                        )
                    except Exception:
                        pass
        except Exception:
            pass
        try:
            _dm = DriverManager.instance()
            if not _dm.is_installed():
                _report("Installing ViGEmBus driver...")
                _dm.download_and_install(status_cb=lambda state, msg: _report(msg))
        except Exception:
            pass

        # Mark done regardless of individual outcomes so we don't retry
        # (and re-freeze the UI, re-download, etc.) on every future launch.
        with open(flag_path, 'w', encoding='utf-8') as f:
            f.write('done\n')
        _report("Setup complete")
    except Exception:
        # Never let dependency bootstrapping crash the launcher itself.
        pass

