_BT_OPUS_FRAME_BYTES = 200
_BT_HAPTIC_FRAME_BYTES = 64
_BT_REPORT_PAYLOAD_LEN = 397
_BT_HAPTIC_RATE = 3000
_BT_HAPTIC_SAMPLES = 32
_BT_FRAME_DURATION = 480 / 45000
_BT_DUALSENSE_PIDS = (3302, 3570)

def _bt_make_crc_table():
    table = []
    for n in range(256):
        c = n
        for _ in range(8):
            c = 3988292384 ^ c >> 1 if c & 1 else c >> 1
        table.append(c & 4294967295)
    return table
_BT_CRC_TABLE = _bt_make_crc_table()

def _bt_crc32(prefix, data, suffix=b''):
    value = 4294967295
    for part in (prefix, data, suffix):
        for byte in part:
            value = value >> 8 ^ _BT_CRC_TABLE[(value ^ byte) & 255]
    return (value ^ 4294967295) & 4294967295

def _bt_stereo_resample(audio, original_rate, target_rate):
    if int(original_rate) == int(target_rate):
        return _bt_np.asarray(audio, dtype=_bt_np.float32).copy()
    from math import gcd
    divisor = gcd(int(original_rate), int(target_rate))
    up = int(target_rate) // divisor
    down = int(original_rate) // divisor
    pad_in = max(64, 2 * max(up, down))
    padded = _bt_np.zeros((audio.shape[0] + 2 * pad_in, 2), dtype=_bt_np.float32)
    padded[pad_in:pad_in + audio.shape[0]] = audio
    pad_out = int(round(pad_in * target_rate / original_rate))
    output = _bt_np.zeros((int(_bt_np.ceil(audio.shape[0] * target_rate / original_rate)), 2), dtype=_bt_np.float32)
    for channel in range(2):
        resampled = _bt_resample_poly(padded[:, channel], up, down)
        trimmed = resampled[pad_out:pad_out + output.shape[0]]
        limit = min(len(trimmed), len(output))
        output[:limit, channel] = trimmed[:limit]
    return output
_AUDIO_TARGET_RMS = 0.12
_AUDIO_PEAK_LIMIT = 0.88
_AUDIO_MIN_GAIN = 0.25
_AUDIO_MAX_GAIN = 8.0
_AUDIO_GAIN_CACHE = {}
_AUDIO_GAIN_CACHE_LOCK = threading.Lock()

def _audio_gain_from_stats(sum_squares, sample_count, peak):
    if sample_count <= 0 or peak <= 1e-07:
        return 1.0
    rms = math.sqrt(max(0.0, float(sum_squares)) / max(1, int(sample_count)))
    if rms <= 1e-06:
        return 1.0
    gain = max(_AUDIO_MIN_GAIN, min(_AUDIO_MAX_GAIN, _AUDIO_TARGET_RMS / rms))
    if peak * gain > _AUDIO_PEAK_LIMIT:
        gain = _AUDIO_PEAK_LIMIT / peak
    return max(0.05, min(_AUDIO_MAX_GAIN, float(gain)))

def _audio_normalization_gain(audio):
    if _bt_np is None:
        return 1.0
    values = _bt_np.asarray(audio, dtype=_bt_np.float32)
    if values.size == 0:
        return 1.0
    finite = values[_bt_np.isfinite(values)]
    if finite.size == 0:
        return 1.0
    return _audio_gain_from_stats(float(_bt_np.sum(finite * finite, dtype=_bt_np.float64)), int(finite.size), float(_bt_np.max(_bt_np.abs(finite))))

def _audio_apply_normalization(audio, gain=None):
    if _bt_np is None:
        return audio
    values = _bt_np.asarray(audio, dtype=_bt_np.float32)
    if gain is None:
        gain = _audio_normalization_gain(values)
    values = values * float(gain)
    return _bt_np.clip(values, -_AUDIO_PEAK_LIMIT, _AUDIO_PEAK_LIMIT).astype(_bt_np.float32, copy=False)

def _audio_normalize_pcm16(pcm, channels=2):
    if _bt_np is None or not pcm or channels < 1:
        return pcm
    sample_count = len(pcm) // 2
    if sample_count <= 0 or sample_count % channels:
        return pcm
    samples = _bt_np.frombuffer(pcm[:sample_count * 2], dtype='<i2').reshape(-1, channels)
    audio = samples.astype(_bt_np.float32) / 32768.0
    audio = _audio_apply_normalization(audio)
    normalized = _bt_np.rint(_bt_np.clip(audio, -1.0, 1.0) * 32767.0).astype('<i2')
    return normalized.tobytes()

def _audio_file_normalization_gain(path):
    if _bt_soundfile is None or _bt_np is None:
        return 1.0
    try:
        stat = os.stat(path)
        cache_key = (os.path.abspath(path), int(stat.st_mtime_ns), stat.st_size)
    except OSError:
        return 1.0
    with _AUDIO_GAIN_CACHE_LOCK:
        cached = _AUDIO_GAIN_CACHE.get(cache_key)
        if cached is not None:
            return cached
        abs_path = cache_key[0]
        for key in tuple(_AUDIO_GAIN_CACHE):
            if key[0] == abs_path and key != cache_key:
                _AUDIO_GAIN_CACHE.pop(key, None)
    sum_squares = 0.0
    sample_count = 0
    peak = 0.0
    try:
        with _bt_soundfile.SoundFile(path) as source:
            while True:
                block = source.read(frames=48000 * 4, dtype='float32', always_2d=True)
                if block is None or len(block) == 0:
                    break
                finite = _bt_np.asarray(block, dtype=_bt_np.float32)
                finite = finite[_bt_np.isfinite(finite)]
                if finite.size:
                    sum_squares += float(_bt_np.sum(finite * finite, dtype=_bt_np.float64))
                    sample_count += int(finite.size)
                    peak = max(peak, float(_bt_np.max(_bt_np.abs(finite))))
        gain = _audio_gain_from_stats(sum_squares, sample_count, peak)
    except Exception:
        gain = 1.0
    with _AUDIO_GAIN_CACHE_LOCK:
        _AUDIO_GAIN_CACHE[cache_key] = gain
    return gain


def _bt_int8(value):
    return int(round(max(-1.0, min(1.0, float(value))) * 127)) & 255

def _bt_build_report(opus_frame, haptic_frame, sequence, frame_counter, volume=75, target='speaker'):
    payload = bytearray(_BT_REPORT_PAYLOAD_LEN)
    payload[0] = (int(sequence) & 15) << 4
    payload[1], payload[2], payload[10] = (144, 63, 9)
    if target == 'headphone':
        payload[3], payload[7] = (144, int(volume) & 255)
    else:
        payload[3], payload[8] = (160, int(volume) & 255)
    payload[66:74] = bytes((145, 7, 254, 64, 64, 64, 64, 64))
    payload[74] = int(frame_counter) & 255
    payload[75] = 150 if target == 'headphone' else 147
    payload[76] = 200
    payload[77:277] = bytes(opus_frame[:_BT_OPUS_FRAME_BYTES]).ljust(_BT_OPUS_FRAME_BYTES, b'\x00')
    payload[277:279] = bytes((146, 64))
    payload[279:343] = bytes(haptic_frame[:_BT_HAPTIC_FRAME_BYTES]).ljust(_BT_HAPTIC_FRAME_BYTES, b'\x00')
    checksum = _bt_crc32(bytes((162, 54)), payload[:-4])
    payload[-4:] = checksum.to_bytes(4, 'little')
    return bytes(payload)

def _bt_device_candidates():
    if _bt_hid is None:
        return []
    try:
        devices = _bt_hid.enumerate(1356)
    except Exception:
        return []
    candidates = []
    for item in devices:
        if int(item.get('product_id', 0)) not in _BT_DUALSENSE_PIDS:
            continue
        path = str(item.get('path', ''))
        upper = path.upper()
        if any((token in upper for token in ('BTHENUM', 'BTHID', 'BLUETOOTH', 'BTHLE', '00001124', 'WIRELESS'))):
            candidates.append(item)
    return sorted(candidates, key=lambda item: (int(item.get('max_output_report_size', 0) or 0) < 398, -int(item.get('max_output_report_size', 0) or 0)))


