class DualSenseBTAudioEngine:
    GENRE_PROFILES = {'action': (180, 260, 0.19, 1.0), 'adventure': (294, 392, 0.25, 0.92), 'rpg': (220, 330, 0.34, 0.88), 'sports': (520, 780, 0.16, 1.0), 'racing': (380, 620, 0.14, 1.0), 'shooter': (150, 430, 0.12, 1.0), 'horror': (90, 135, 0.38, 0.82), 'strategy': (260, 520, 0.28, 0.88), 'simulation': (330, 440, 0.25, 0.82), 'platformer': (440, 660, 0.18, 0.95), 'fighting': (210, 560, 0.13, 1.0), 'puzzle': (600, 900, 0.22, 0.86), 'other': (300, 480, 0.2, 0.86)}

    def __init__(self, stream_state_cb=None):
        self._stream_state_cb = stream_state_cb
        self._dev = None
        self._connected = False
        # The Bluetooth audio endpoint and the Lightbar endpoint are the same
        # physical HID transport.  hidapi does not serialize writes made from
        # different Python threads, so every audio and external output report
        # must pass through this lock.
        self._hid_write_lock = threading.RLock()
        self._output_report_size = 0
        self._volume, self._gain, self._loudness = (127, 1.0, 100)
        self._target = 'speaker'
        self._seq = self._frame_counter = 0
        self._output_seq = 0
        self._lock = threading.RLock()
        self._playback_generation = 0
        self._playing = False
        self._active_file_source = None
        self._crossfade_request = None
        self._pending_file_request = None
        self._connect_lock = threading.Lock()
        self._connecting = False
        self._play_queue = queue.Queue()
        self._worker_thread = None
        self._closing = threading.Event()
        self._prepare_queue = queue.Queue()
        self._prepare_thread = None
        self._prepare_generations = {}
        # Which physical pad this engine belongs to. Without this, connect
        # would grab whichever candidate opened first out of every DualSense
        # currently paired system-wide -- fine with one pad, but with two
        # pads connected (or one swapped for another) an engine could bind
        # to the WRONG pad's HID path, leaving the pad it was meant for
        # silent. Set via set_target_path() before connecting.
        self._target_path = None
        self._target_family = None

    def set_target_path(self, path):
        """Pin this engine to a specific pad's HID audio path so connect()
        can only ever bind to that physical controller."""
        path = str(path or '')
        with self._lock:
            self._target_path = path or None
            self._target_family = _hid_family_key(path) if path else None

    @property
    def available(self):
        return all((x is not None for x in (_bt_np, _bt_opuslib, _bt_soundfile, _bt_resample_poly, _bt_hid)))

    @property
    def connected(self):
        return bool(self._connected and self._dev is not None)

    @property
    def playing(self):
        with self._lock:
            return bool(self._playing)

    @property
    def output_report_size(self):
        with self._lock:
            return max(78, int(self._output_report_size or 0))

    def _set_stream_active(self, active):
        callback = self._stream_state_cb
        if callback is not None:
            try:
                callback(bool(active))
            except Exception:
                pass

    def set_stream_state_callback(self, callback):
        """Replace the Lightbar stream callback after the LED controller is rebuilt."""
        self._stream_state_cb = callback

    def write_output_report(self, report, expected_device=None, context='external-output'):
        """Write a non-audio report through the audio hidapi handle.

        This is intentionally the same critical section used by audio packets.
        A caller may provide the device it observed before scheduling the write;
        that prevents a stale Lightbar job from writing to a newly reconnected
        handle.
        """
        raw_report = bytes(report)
        if not raw_report:
            return False
        with self._lock:
            with self._hid_write_lock:
                device = self._dev
                if device is None or not self._connected:
                    return False
                if expected_device is not None and device is not expected_device:
                    return False
                try:
                    # The report is already complete, including its own
                    # transport sequence and CRC.  Never rewrite it here:
                    # Bluetooth audio reports use a different sequence and
                    # CRC layout from Lightbar reports.
                    device.write(raw_report)
                    return True
                except Exception as exc:
                    _haptic_failure('hidapi shared write FAILED context=%s bytes=%d error=%r', context, len(raw_report), exc)
                    return False

    def _write_audio_report(self, device, report):
        """Write an untouched audio packet under the shared HID write lock."""
        raw_report = bytes(report)
        if not raw_report:
            return False
        with self._lock:
            with self._hid_write_lock:
                if self._dev is not device or not self._connected:
                    return False
                try:
                    # Do not rewrite the audio report, sequence, or CRC.
                    device.write(raw_report)
                    return True
                except Exception as exc:
                    _haptic_failure('hidapi audio write FAILED bytes=%d error=%r', len(raw_report), exc)
                    return False

    def connect(self):
        if not self._connect_lock.acquire(blocking=False):
            return False
        try:
            with self._lock:
                if self._connected and self._dev is not None:
                    return True
                self._connecting = True
            return self._connect_impl()
        finally:
            with self._lock:
                self._connecting = False
            self._connect_lock.release()

    def _log_connect_failure_throttled(self, msg):
        now = time.monotonic()
        last = getattr(self, '_last_connect_fail_log', 0.0)
        if now - last < 30.0:
            return
        self._last_connect_fail_log = now
        _haptic_failure('bt-audio connect failed (target_path=%r target_family=%r): %s', self._target_path, self._target_family, msg)

    def _connect_impl(self):
        if not self.available:
            return False
        candidates = _bt_device_candidates()
        if not candidates:
            self._log_connect_failure_throttled('no Bluetooth DualSense audio HID collection found at all (_bt_device_candidates() returned none)')
            return False
        with self._lock:
            target_path = self._target_path
            target_family = self._target_family
        if target_path or target_family:
            # Only ever bind to the candidate(s) that belong to THIS pad --
            # never fall back to "any open DualSense candidate", or this
            # engine can steal another pad's HID handle (or attach to a
            # stale/ghost path left behind by a pad that was just turned
            # off), leaving the intended pad silent.
            candidates = [c for c in candidates if str(c.get('path', '')) == target_path or (target_family and _hid_family_key(c.get('path', '')) == target_family)]
            if not candidates:
                self._log_connect_failure_throttled('audio collections were found, but none matched this pad')
                return False
        last_error = None
        device = None
        info = None
        for candidate in candidates:
            try:
                candidate_device = _bt_hid.device()
                candidate_device.open_path(candidate['path'])
                candidate_device.set_nonblocking(0)
                device, info = (candidate_device, candidate)
                break
            except Exception as exc:
                last_error = exc
                try:
                    candidate_device.close()
                except Exception:
                    pass
        if device is None:
            self._log_connect_failure_throttled(f'found {len(candidates)} matching candidate(s) but opening the HID handle failed: {last_error!r}')
            return False
        with self._lock:
            self._close_device_locked()
            self._dev, self._connected = (device, True)
            self._output_report_size = int(info.get('max_output_report_size', 0) or 0)
            # Sequence numbers belong to a physical HID session.  A newly
            # opened hidapi handle must not inherit the old handle's sequence.
            self._output_seq = 0
        path_text = str(info.get('path', ''))
        output_size = int(info.get('max_output_report_size', 0) or 0)
        return True

    def ensure_connected(self):
        if self.connected:
            return True
        return self.connect()

    def force_reconnect_async(self):
        """Drop any stale device handle and reconnect on a background thread.
        Needed because a physical power-off doesn't always surface as a write
        error, so self._connected can stay True even though the handle is dead."""
        with self._lock:
            self._close_device_locked()
            if self._closing.is_set():
                return False
        return self.connect_async()

    def connect_async(self):
        with self._lock:
            if self._connecting or self.connected or self._closing.is_set():
                return False
            self._connecting = True
        threading.Thread(target=self._connect_async_worker, daemon=True, name='dualsense-bt-audio-connect').start()
        return True

    def _connect_async_worker(self):
        if not self._connect_lock.acquire(blocking=False):
            with self._lock:
                self._connecting = False
            return False
        try:
            connected = self._connect_impl()
            if connected:
                with self._lock:
                    pending = self._pending_file_request
                    self._pending_file_request = None
                if pending:
                    self.play_file(*pending)
            return connected
        finally:
            with self._lock:
                self._connecting = False
            self._connect_lock.release()

    def _close_device_locked(self):
        # Callers already hold _lock.  Keep close in the same order as
        # write_output_report() so a reconnect cannot close a handle while a
        # report is being written.
        with self._hid_write_lock:
            if self._dev is not None:
                try:
                    self._dev.close()
                except Exception:
                    pass
            self._dev, self._connected = (None, False)
            self._output_report_size = 0

    def stop(self, clear_queue=True):
        with self._lock:
            self._playback_generation += 1
            was_playing = self._playing
            self._pending_file_request = None
            self._crossfade_request = None
        if clear_queue:
            try:
                while True:
                    self._play_queue.get_nowait()
            except queue.Empty:
                pass
        if was_playing:
            pass
        try:
            while True:
                self._prepare_queue.get_nowait()
        except queue.Empty:
            pass

    def crossfade_file(self, path, start_offset=0.0, duration=0.32):
        if not self.available:
            return False
        absolute = os.path.abspath(path)
        with self._lock:
            if not self._playing:
                return False
            self._crossfade_request = (absolute, max(0.0, float(start_offset or 0.0)), max(0.05, float(duration or 0.32)))
        return True

    def fade_out_and_stop(self, duration=0.32):
        with self._lock:
            active = bool(self._playing)
            if active:
                self._crossfade_request = (None, 0.0, max(0.05, float(duration or 0.32)))
        if not active:
            return False
        return True

    def close(self):
        self._closing.set()
        self.stop()
        with self._lock:
            self._close_device_locked()

    def set_target(self, target):
        with self._lock:
            self._target = 'headphone' if str(target).lower() == 'headphone' else 'speaker'

    def set_volume(self, value):
        self.set_loudness(value)

    def set_loudness(self, value):
        percent = max(0, min(100, int(value)))
        volume, gain = (round(percent / 100 * 127), 1.0)
        with self._lock:
            self._loudness, self._volume, self._gain = (percent, volume, round(gain, 3))
        self._push_live_volume()

    def _push_live_volume(self):
        """Send one silent audio+haptic report carrying the current
        volume/target right away.

        The DualSense's Bluetooth volume isn't a standalone control --
        the value only ever reaches the pad riding along inside an audio
        report (see _bt_build_report). set_loudness() above only updates
        our own _volume field; without this, that new value would sit
        unused until the next time a theme/UI sound actually starts
        playing, so adjusting volume while nothing is playing looked
        like it did nothing. Skipped while a real stream is already
        active -- that loop already carries the current volume on its
        very next frame, and writing here too would race it on the same
        HID handle.
        """
        if not self.available:
            return
        with self._lock:
            device = self._dev
            playing = self._playing
            connected = self._connected
            volume, target = (self._volume, self._target)
            sequence, counter = (self._seq, self._frame_counter)
        if device is None or playing:
            if _HAPTIC_DEBUG:
                _haptic_failure('bt-volume debug [live-push-skip]: device_present=%r playing=%r connected=%r', device is not None, playing, connected)
            return
        try:
            encoder = self._get_encoder()
            silence = _bt_np.zeros((480, 2), dtype=_bt_np.float32)
            opus_frame = self._opus_frame(encoder, silence)
        except Exception as exc:
            if _HAPTIC_DEBUG:
                _haptic_failure('bt-volume debug [live-push-encode-failed]: error=%r', exc)
            return
        haptic = bytes(_BT_HAPTIC_FRAME_BYTES)
        payload = _bt_build_report(opus_frame, haptic, sequence, counter, volume, target)
        ok = self._write_audio_report(device, bytes((54,)) + payload)
        if _HAPTIC_DEBUG:
            _haptic_failure('bt-volume debug [live-push]: volume=%s target=%s write_ok=%r', volume, target, ok)
        if ok:
            with self._lock:
                self._seq = sequence + 1 & 15
                self._frame_counter = counter + 1 & 255

    def _prepare_audio(self, audio, sample_rate):
        if audio.ndim == 1:
            audio = _bt_np.repeat(audio[:, None], 2, axis=1)
        audio = _bt_np.asarray(audio[:, :2], dtype=_bt_np.float32)
        audio = _audio_apply_normalization(audio)
        audio48 = _bt_stereo_resample(audio, sample_rate, 48000)
        return _BTPreparedAudio(audio48, _bt_stereo_resample(audio48, 48000, _BT_HAPTIC_RATE))

    @staticmethod
    def _encoder():
        opus_constants = getattr(_bt_opuslib, 'constants', None)
        application = getattr(_bt_opuslib, 'APPLICATION_AUDIO', getattr(opus_constants, 'APPLICATION_AUDIO', _bt_opuslib.APPLICATION_RESTRICTED_LOWDELAY))
        encoder = _bt_opuslib.Encoder(48000, 2, application)
        for name, value in (('bitrate', 160000), ('vbr', 0), ('complexity', 1), ('packet_loss_perc', 0), ('inband_fec', 0), ('useinbandfec', 0), ('dtx', 0)):
            try:
                setattr(encoder, name, value)
            except (AttributeError, TypeError, ValueError):
                pass
        return encoder

    def _get_encoder(self):
        return self._encoder()

    @staticmethod
    def _opus_frame(encoder, chunk):
        pcm = _bt_np.clip(chunk * 32767, -32768, 32767).astype(_bt_np.int16)
        try:
            encoded = encoder.encode(pcm.tobytes(), chunk.shape[0], _BT_OPUS_FRAME_BYTES)
        except TypeError:
            encoded = encoder.encode(pcm.tobytes(), chunk.shape[0])
        encoded = bytes(encoded)
        if len(encoded) > _BT_OPUS_FRAME_BYTES:
            raise ValueError(f'Opus packet exceeded DualSense cap: {len(encoded)} > {_BT_OPUS_FRAME_BYTES} bytes')
        return encoded.ljust(_BT_OPUS_FRAME_BYTES, b'\x00')

    @staticmethod
    def _haptic_frame(chunk):
        frame = bytearray(_BT_HAPTIC_FRAME_BYTES)
        for index in range(min(len(chunk), _BT_HAPTIC_SAMPLES)):
            frame[index * 2] = _bt_int8(chunk[index, 0])
            frame[index * 2 + 1] = _bt_int8(chunk[index, 1])
        return bytes(frame)

    def _play_prepared_blocking(self, prepared):
        with self._lock:
            device = self._dev
            playback_generation = self._playback_generation
            self._playing = True
        if device is None:
            with self._lock:
                self._playing = False
            return
        try:
            encoder = self._get_encoder()
        except Exception as exc:
            with self._lock:
                self._playing = False
            return
        audio48, audio3 = (prepared.raw_audio48k, prepared.raw_audio3k)
        frame_samples = 480
        audio_frames = max(1, (len(audio48) + frame_samples - 1) // frame_samples)
        post_roll_frames = 3
        total = audio_frames + post_roll_frames
        total_haptic = max(1, (len(audio3) + 31) // 32) if len(audio3) else 0
        with self._lock:
            sequence, counter = (self._seq, self._frame_counter)
        precompute_start = time.perf_counter()
        # Precompute the opus/haptic *audio* content only -- volume/target are
        # deliberately NOT baked in here, since a long playback (or a looping
        # background track) can run for a while and the gamepad volume
        # buttons need to affect it while it's already playing, not just the
        # next time a stream starts.
        frames = []
        try:
            for index in range(total):
                start = index * frame_samples
                if index < audio_frames:
                    chunk = audio48[start:start + frame_samples]
                else:
                    chunk = _bt_np.zeros((frame_samples, 2), dtype=_bt_np.float32)
                if len(chunk) < frame_samples:
                    padded = _bt_np.zeros((frame_samples, 2), dtype=_bt_np.float32)
                    padded[:len(chunk)] = chunk
                    chunk = padded
                opus_frame = self._opus_frame(encoder, chunk)
                if total_haptic and index < audio_frames:
                    hstart = min(index, total_haptic - 1) * _BT_HAPTIC_SAMPLES
                    hchunk = audio3[hstart:hstart + _BT_HAPTIC_SAMPLES]
                else:
                    hchunk = None
                seq_i, counter_i = (sequence + index & 15, counter + index & 255)
                frames.append((opus_frame, hchunk, seq_i, counter_i))
        except Exception as exc:
            import traceback
            with self._lock:
                self._playing = False
            return
        precompute_ms = (time.perf_counter() - precompute_start) * 1000
        self._set_stream_active(True)
        try:
            start_time = time.perf_counter()
            sent = 0
            for index, (opus_frame, hchunk, seq_i, counter_i) in enumerate(frames):
                with self._lock:
                    if self._dev is not device or playback_generation != self._playback_generation:
                        return
                    # Read live -- lets gamepad volume changes take effect
                    # within a single frame (~7.5ms), even mid-playback.
                    volume, target = (self._volume, self._target)
                haptic = self._haptic_frame(hchunk * (volume / 127)) if hchunk is not None else bytes(_BT_HAPTIC_FRAME_BYTES)
                out_bytes = bytes((54,)) + _bt_build_report(opus_frame, haptic, seq_i, counter_i, volume, target)
                try:
                    write_start = time.perf_counter()
                    if not self._write_audio_report(device, out_bytes):
                        return
                except Exception as exc:
                    return
                write_ms = (time.perf_counter() - write_start) * 1000
                if write_ms > 5:
                    pass
                sent += 1
                now = time.perf_counter()
                delay = start_time + (index + 1) * _BT_FRAME_DURATION - now
                if delay > 0:
                    time.sleep(delay)
                elif index > 0:
                    behind_ms = -delay * 1000
                    if behind_ms > 5:
                        pass
                    if behind_ms > _BT_FRAME_DURATION * 1000:
                        start_time = now - (index + 1) * _BT_FRAME_DURATION
        finally:
            time.sleep(_BT_FRAME_DURATION)
            self._set_stream_active(False)
            with self._lock:
                self._playing = False
        with self._lock:
            self._seq = sequence + sent & 15
            self._frame_counter = counter + sent & 255
        actual_ms = (time.perf_counter() - start_time) * 1000

    def _play_file_streaming_blocking(self, source):
        with self._lock:
            device = self._dev
            playback_generation = self._playback_generation
            sequence, frame_counter = (self._seq, self._frame_counter)
            self._playing = True
        if device is None:
            with self._lock:
                self._playing = False
            return
        payload_queue = queue.Queue(maxsize=6)
        producer_done = threading.Event()
        producer_error = []
        frame_samples = 480
        post_roll_frames = 3

        def put_payload(payload):
            while not self._closing.is_set():
                with self._lock:
                    if playback_generation != self._playback_generation:
                        return False
                try:
                    payload_queue.put(payload, timeout=0.05)
                    return True
                except queue.Full:
                    continue
            return False

        def produce():
            frame_index = 0
            try:
                encoder = self._get_encoder()
                current_file = _bt_soundfile.SoundFile(source.path)
                with self._lock:
                    self._active_file_source = source.path
                open_files = [current_file]
                current_path = source.path
                current_rate = int(current_file.samplerate)
                current_gain = _audio_file_normalization_gain(current_path)
                if source.start_offset:
                    current_file.seek(max(0, int(float(source.start_offset) * current_rate)))
                transition_file = None
                transition_path = ''
                transition_rate = current_rate
                transition_gain = 1.0
                transition_frames_left = 0
                transition_to_silence = False
                silenced = False
                fade_frames = max(1, int(round(current_rate * 0.32)))
                transition_elapsed_frames = 0
                read_frames = max(frame_samples, int(round(current_rate * 0.08)))
                try:
                    while not self._closing.is_set():
                        with self._lock:
                            if playback_generation != self._playback_generation:
                                return
                            requested = self._crossfade_request
                            self._crossfade_request = None
                        if requested and transition_file is None and (not transition_to_silence):
                            new_path, new_offset, requested_fade = requested
                            if new_path is None:
                                transition_to_silence = True
                                transition_frames_left = max(1, int(round(current_rate * float(requested_fade))))
                                fade_frames = transition_frames_left
                                transition_elapsed_frames = 0
                            else:
                                try:
                                    transition_file = _bt_soundfile.SoundFile(new_path)
                                    open_files.append(transition_file)
                                    transition_path = new_path
                                    transition_rate = int(transition_file.samplerate)
                                    transition_gain = _audio_file_normalization_gain(new_path)
                                    if new_offset:
                                        transition_file.seek(max(0, int(float(new_offset) * transition_rate)))
                                    transition_frames_left = max(1, int(round(current_rate * float(requested_fade))))
                                    fade_frames = transition_frames_left
                                    transition_elapsed_frames = 0
                                except Exception as exc:
                                    transition_file = None
                        if silenced:
                            audio = _bt_np.zeros((read_frames, 2), dtype=_bt_np.float32)
                        else:
                            audio = current_file.read(frames=read_frames, dtype='float32', always_2d=True)
                        if audio is None or len(audio) == 0:
                            if transition_to_silence:
                                silenced = True
                                transition_to_silence = False
                                break
                            if transition_file is None and (not transition_to_silence):
                                break
                            try:
                                current_file.close()
                            except Exception:
                                pass
                            current_file = transition_file
                            current_path = transition_path
                            current_rate = transition_rate
                            current_gain = transition_gain
                            transition_file = None
                            transition_path = ''
                            transition_frames_left = 0
                            read_frames = max(frame_samples, int(round(current_rate * 0.08)))
                            continue
                        audio = _bt_np.asarray(audio, dtype=_bt_np.float32)
                        if audio.ndim == 1:
                            audio = _bt_np.repeat(audio[:, None], 2, axis=1)
                        elif audio.shape[1] == 1:
                            audio = _bt_np.repeat(audio, 2, axis=1)
                        audio = audio[:, :2]
                        audio = _audio_apply_normalization(audio, current_gain)
                        if transition_file is not None or transition_to_silence:
                            blend_frames = min(len(audio), transition_frames_left)
                            if transition_to_silence:
                                incoming = _bt_np.zeros_like(audio)
                            else:
                                incoming = transition_file.read(frames=max(1, int(round(blend_frames * transition_rate / max(1, current_rate)))), dtype='float32', always_2d=True)
                            if incoming is None or len(incoming) == 0:
                                incoming = _bt_np.zeros_like(audio)
                            incoming = _bt_np.asarray(incoming, dtype=_bt_np.float32)
                            if incoming.ndim == 1:
                                incoming = _bt_np.repeat(incoming[:, None], 2, axis=1)
                            elif incoming.shape[1] == 1:
                                incoming = _bt_np.repeat(incoming, 2, axis=1)
                            incoming = incoming[:, :2]
                            if not transition_to_silence and transition_rate != current_rate:
                                incoming = _bt_stereo_resample(incoming, transition_rate, current_rate)
                            n = min(blend_frames, len(incoming))
                            if n > 0:
                                incoming = _audio_apply_normalization(incoming, transition_gain)
                                fade_position = _bt_np.arange(n, dtype=_bt_np.float32)
                                alpha = 0.5 - 0.5 * _bt_np.cos(_bt_np.pi * (transition_elapsed_frames + fade_position + 1) / max(1, fade_frames))
                                audio[:n] = audio[:n] * (1.0 - alpha[:, None]) + incoming[:n] * alpha[:, None]
                                transition_frames_left -= n
                                transition_elapsed_frames += n
                            if transition_frames_left <= 0:
                                if transition_to_silence:
                                    silenced = True
                                    transition_to_silence = False
                                    transition_frames_left = 0
                                try:
                                    current_file.close()
                                except Exception:
                                    pass
                                current_file = transition_file
                                current_path = transition_path
                                current_rate = transition_rate
                                current_gain = transition_gain
                                transition_file = None
                                transition_path = ''
                                transition_frames_left = 0
                                read_frames = max(frame_samples, int(round(current_rate * 0.08)))
                        with self._lock:
                            newer_request = self._crossfade_request
                        if newer_request and transition_file is not None:
                            try:
                                transition_file.close()
                            except Exception:
                                pass
                            transition_file = None
                            transition_path = ''
                            transition_frames_left = 0
                        audio48 = _bt_stereo_resample(audio, current_rate, 48000)
                        audio3 = _bt_stereo_resample(audio48, 48000, _BT_HAPTIC_RATE)
                        audio_frames = max(1, (len(audio48) + frame_samples - 1) // frame_samples)
                        haptic_frames = max(1, (len(audio3) + _BT_HAPTIC_SAMPLES - 1) // _BT_HAPTIC_SAMPLES)
                        for local_index in range(audio_frames):
                            start = local_index * frame_samples
                            chunk = audio48[start:start + frame_samples]
                            if len(chunk) < frame_samples:
                                padded = _bt_np.zeros((frame_samples, 2), dtype=_bt_np.float32)
                                padded[:len(chunk)] = chunk
                                chunk = padded
                            opus_frame = self._opus_frame(encoder, chunk)
                            hstart = min(local_index, haptic_frames - 1) * _BT_HAPTIC_SAMPLES
                            hchunk = audio3[hstart:hstart + _BT_HAPTIC_SAMPLES]
                            # Read live so gamepad volume changes reach a
                            # track that's already looping/playing, instead
                            # of only applying to the next track.
                            with self._lock:
                                volume, target = (self._volume, self._target)
                            haptic = self._haptic_frame(hchunk * (volume / 127))
                            report = _bt_build_report(opus_frame, haptic, sequence + frame_index & 15, frame_counter + frame_index & 255, volume, target)
                            if not put_payload(bytes((54,)) + report):
                                return
                            frame_index += 1
                        if silenced:
                            break
                finally:
                    for handle in open_files:
                        try:
                            handle.close()
                        except Exception:
                            pass
                    with self._lock:
                        self._active_file_source = None
                silent = _bt_np.zeros((frame_samples, 2), dtype=_bt_np.float32)
                for _ in range(post_roll_frames):
                    with self._lock:
                        volume, target = (self._volume, self._target)
                    opus_frame = self._opus_frame(encoder, silent)
                    report = _bt_build_report(opus_frame, bytes(_BT_HAPTIC_FRAME_BYTES), sequence + frame_index & 15, frame_counter + frame_index & 255, volume, target)
                    if not put_payload(bytes((54,)) + report):
                        return
                    frame_index += 1
            except Exception as exc:
                producer_error.append(exc)
                import traceback
            finally:
                producer_done.set()
                try:
                    payload_queue.put_nowait(None)
                except queue.Full:
                    pass
        threading.Thread(target=produce, daemon=True, name='dualsense-bt-audio-stream-producer').start()
        while payload_queue.qsize() < 6 and (not producer_done.wait(0.002)):
            with self._lock:
                if playback_generation != self._playback_generation:
                    break
        self._set_stream_active(True)
        sent = 0
        start_time = time.perf_counter()
        try:
            while not self._closing.is_set():
                try:
                    payload = payload_queue.get(timeout=0.1)
                except queue.Empty:
                    if producer_done.is_set():
                        break
                    continue
                if payload is None:
                    break
                with self._lock:
                    if self._dev is not device or playback_generation != self._playback_generation:
                        break
                try:
                    if not self._write_audio_report(device, payload):
                        producer_error.append(RuntimeError('hidapi audio output write failed'))
                        break
                except Exception as exc:
                    producer_error.append(exc)
                    break
                sent += 1
                delay = start_time + sent * _BT_FRAME_DURATION - time.perf_counter()
                if delay > 0:
                    time.sleep(delay)
        finally:
            time.sleep(_BT_FRAME_DURATION)
            self._set_stream_active(False)
            with self._lock:
                self._playing = False
                self._seq = sequence + sent & 15
                self._frame_counter = frame_counter + sent & 255
                self._active_file_source = None
            if producer_error:
                pass

    def _worker_loop(self):
        try:
            THREAD_PRIORITY_TIME_CRITICAL = 15
            ctypes.windll.kernel32.SetThreadPriority(ctypes.windll.kernel32.GetCurrentThread(), THREAD_PRIORITY_TIME_CRITICAL)
        except Exception:
            pass
        _timer_res_active = False
        try:
            ctypes.windll.winmm.timeBeginPeriod(1)
            _timer_res_active = True
        except Exception:
            pass
        try:
            while not self._closing.is_set():
                try:
                    item = self._play_queue.get(timeout=0.5)
                except queue.Empty:
                    continue
                if item is None:
                    continue
                prepared, _coalesce_key = item
                try:
                    if isinstance(prepared, _BTFilePlayback):
                        self._play_file_streaming_blocking(prepared)
                    else:
                        self._play_prepared_blocking(prepared)
                except Exception as exc:
                    pass
        finally:
            if _timer_res_active:
                try:
                    ctypes.windll.winmm.timeEndPeriod(1)
                except Exception:
                    pass

    def _ensure_worker(self):
        with self._lock:
            if self._worker_thread is None or not self._worker_thread.is_alive():
                self._worker_thread = threading.Thread(target=self._worker_loop, daemon=True, name='dualsense-bt-audio-worker')
                self._worker_thread.start()

    def _prepare_worker_loop(self):
        while not self._closing.is_set():
            try:
                job = self._prepare_queue.get(timeout=0.5)
            except queue.Empty:
                continue
            if job is None:
                continue
            build_fn, coalesce_key, label, generation, playback_generation = job
            with self._lock:
                if playback_generation != self._playback_generation:
                    continue
            if coalesce_key is not None:
                with self._lock:
                    if generation != self._prepare_generations.get(coalesce_key, generation):
                        continue
            try:
                prepared = build_fn()
                with self._lock:
                    if playback_generation != self._playback_generation:
                        continue
                if coalesce_key is not None:
                    with self._lock:
                        if generation != self._prepare_generations.get(coalesce_key, generation):
                            continue
                self._enqueue(prepared, coalesce_key=coalesce_key)
            except Exception as exc:
                pass

    def _ensure_prepare_worker(self):
        with self._lock:
            if self._prepare_thread is None or not self._prepare_thread.is_alive():
                self._prepare_thread = threading.Thread(target=self._prepare_worker_loop, daemon=True, name='dualsense-bt-audio-prepare-worker')
                self._prepare_thread.start()

    def _submit_prepare(self, build_fn, coalesce_key=None, label='event sound'):
        self._ensure_prepare_worker()
        with self._lock:
            generation = self._prepare_generations.get(coalesce_key, 0) + 1 if coalesce_key is not None else 0
            if coalesce_key is not None:
                self._prepare_generations[coalesce_key] = generation
            playback_generation = self._playback_generation
        self._prepare_queue.put((build_fn, coalesce_key, label, generation, playback_generation))

    def _enqueue(self, prepared, coalesce_key=None):
        self._ensure_worker()
        if coalesce_key is not None:
            pending = []
            try:
                while True:
                    item = self._play_queue.get_nowait()
                    if item[1] != coalesce_key:
                        pending.append(item)
            except queue.Empty:
                pass
            for item in pending:
                self._play_queue.put(item)
        self._play_queue.put((prepared, coalesce_key))

    def play_file(self, path, start_offset=0.0):
        if not self.available:
            return False
        with self._lock:
            if self.connected:
                play_now = True
            else:
                self._pending_file_request = (path, start_offset)
                play_now = False
        if play_now:
            self._ensure_worker()
            self._play_queue.put((_BTFilePlayback(os.path.abspath(path), max(0.0, float(start_offset or 0.0))), None))
            return True
        started = self.connect_async()
        if not started:
            with self._lock:
                if self.connected:
                    pending = self._pending_file_request
                    self._pending_file_request = None
                    do_play = pending is not None
                    still_connecting = False
                else:
                    pending = None
                    do_play = False
                    still_connecting = self._connecting
                    if not still_connecting:
                        self._pending_file_request = None
            if do_play:
                p_path, p_offset = pending
                self._ensure_worker()
                self._play_queue.put((_BTFilePlayback(os.path.abspath(p_path), max(0.0, float(p_offset or 0.0))), None))
                return True
            if not still_connecting:
                return False
        return True

    def play_test_tone(self, target='speaker'):
        if not self.available:
            return False
        if not self.connected:
            self.connect_async()
            return False
        frequency = 1000 if target == 'speaker' else 1200

        def build():
            return self._prepare_audio(self._tone((frequency,), 0.85, 0.72), 48000)
        self._submit_prepare(build, label='test tone')
        return True

    @staticmethod
    def _genre_key(genre):
        text = ' '.join(genre) if isinstance(genre, (list, tuple, set)) else str(genre or '')
        aliases = {'action': ('action', 'اکشن'), 'adventure': ('adventure', 'ماجراجویی'), 'rpg': ('rpg', 'role playing', 'نقش\u200cآفرینی', 'نقش افرینی'), 'sports': ('sport', 'sports', 'ورزشی'), 'racing': ('racing', 'race', 'مسابقه', 'رانندگی'), 'shooter': ('shooter', 'fps', 'تیراندازی'), 'horror': ('horror', 'ترسناک', 'وحشت'), 'strategy': ('strategy', 'استراتژی'), 'simulation': ('simulation', 'simulator', 'شبیه\u200cسازی'), 'platformer': ('platform', 'platformer', 'سکوبازی'), 'fighting': ('fighting', 'فایت', 'مبارزه'), 'puzzle': ('puzzle', 'معمایی', 'پازل')}
        text = text.lower()
        return next((key for key, words in aliases.items() if any((word in text for word in words))), 'other')

    @staticmethod
    def _round_duration_to_frame(duration):
        frames = max(1, math.ceil(duration / _BT_FRAME_DURATION))
        return frames * _BT_FRAME_DURATION

    @staticmethod
    def _tone(frequencies, duration, gain=0.9, sample_rate=48000):
        count = max(1, int(duration * sample_rate))
        time_axis = _bt_np.arange(count, dtype=_bt_np.float32) / sample_rate
        wave = _bt_np.zeros(count, dtype=_bt_np.float32)
        for index, frequency in enumerate(frequencies):
            wave += _bt_np.sin(2 * math.pi * frequency * time_axis) / (index + 1)
        if frequencies:
            wave += 0.15 * _bt_np.sin(2 * math.pi * frequencies[0] * 2 * time_axis)
        peak = float(_bt_np.max(_bt_np.abs(wave))) if len(wave) else 0.0
        if peak > 1.0:
            wave /= peak
        attack = max(1, min(int(sample_rate * 0.006), count // 5))
        release = max(1, min(int(sample_rate * 0.02), count // 4))
        envelope = _bt_np.ones(count, dtype=_bt_np.float32)
        envelope[:attack] = 0.5 * (1 - _bt_np.cos(_bt_np.linspace(0, math.pi, attack, dtype=_bt_np.float32)))
        envelope[-release:] *= 0.5 * (1 + _bt_np.cos(_bt_np.linspace(0, math.pi, release, dtype=_bt_np.float32)))
        wave *= envelope
        return _bt_np.column_stack((wave * gain, wave * gain)).astype(_bt_np.float32)

    def play_ui_event(self, event, genre=None):
        if not self.available:
            return False
        if not self.connected:
            self.connect_async()
            return False
        low, high, base_duration, base_gain = self.GENRE_PROFILES.get(self._genre_key(genre), self.GENRE_PROFILES['other'])
        if event == 'navigation':
            frequencies, duration, gain = ((high, high * 1.25), 0.18, 0.17)
        elif event == 'category':
            frequencies, duration, gain = ((low, high), 0.36, 0.17)
        elif event == 'launch':
            frequencies, duration, gain = ((low, high), 0.72, 0.17)
        else:
            frequencies, duration, gain = ((low,), 0.18, 0.17)
        duration = self._round_duration_to_frame(duration)
        coalesce_key = event if event in ('navigation', 'category') else None

        def build():
            return self._prepare_audio(self._tone(frequencies, duration, gain), 48000)
        self._submit_prepare(build, coalesce_key=coalesce_key, label=f'{event} cue')
        return True


_BT_AUDIO_AVAILABILITY_LOGGED = [False]

def _log_bt_audio_availability_once():
    """Logs, once, exactly which optional dependency that DualSense
    Bluetooth audio (theme-through-controller, haptics-over-BT) needs is
    missing. All 5 -- numpy, opuslib, soundfile, scipy (resample_poly) and
    hid (the hidapi package) -- must import successfully or the feature is
    silently unavailable and theme audio always falls back to the system
    output with no error shown anywhere."""
    if _BT_AUDIO_AVAILABILITY_LOGGED[0]:
        return
    _BT_AUDIO_AVAILABILITY_LOGGED[0] = True
    missing = [name for name, mod in (('numpy', _bt_np), ('opuslib', _bt_opuslib), ('soundfile', _bt_soundfile), ('scipy', _bt_resample_poly), ('hid', _bt_hid)) if mod is None]
    if missing:
        _haptic_failure('bt-audio unavailable: missing dependency/dependencies: %s', ', '.join(missing))
    else:
        _haptic_failure('bt-audio dependencies all present (numpy/opuslib/soundfile/scipy/hid) -- availability is not the blocker')


class DualSenseBTAudioHub:
    """Fans a single DualSenseBTAudioEngine out to every DualSense that is
    currently paired over Bluetooth, so theme/UI sounds play on all of them
    at once instead of only the one _bt_device_candidates() happens to open
    first. Exposes the same public surface as DualSenseBTAudioEngine
    (play_file, set_target, connect_async, playing, connected, etc.) so
    every existing `self._bt_audio.<method>(...)` call site keeps working
    unmodified -- this is a drop-in replacement for the single engine.

    Per-controller volume (for L3/R3 on a specific pad) goes through
    set_volume_for_path()/adjust_volume_for_path(), which only touch the
    engine for that one HID path. The broadcast set_volume() (used by the
    global settings slider) still updates every connected engine.
    """

    _RESCAN_INTERVAL_SEC = 4.0

    def __init__(self, stream_state_cb=None):
        self._stream_state_cb = stream_state_cb
        self._lock = threading.RLock()
        self._engines: dict = {}
        self._primary_path = None
        self._closing = threading.Event()
        self._rescan_thread = None
        self._last_broadcast_volume = None

    @property
    def available(self):
        return all((x is not None for x in (_bt_np, _bt_opuslib, _bt_soundfile, _bt_resample_poly, _bt_hid)))

    @property
    def connected(self):
        with self._lock:
            return any((e.connected for e in self._engines.values()))

    @property
    def has_pad(self):
        """True while at least one paired Bluetooth DualSense is visible to
        the hub (its engine may still be opening the HID handle)."""
        with self._lock:
            return bool(self._engines)

    @property
    def playing(self):
        with self._lock:
            return any((e.playing for e in self._engines.values()))

    @property
    def output_report_size(self):
        primary = self._primary_engine()
        return primary.output_report_size if primary is not None else 78

    def _primary_engine(self):
        with self._lock:
            if self._primary_path is not None:
                eng = self._engines.get(self._primary_path)
                if eng is not None and eng.connected:
                    return eng
            for eng in self._engines.values():
                if eng.connected:
                    return eng
            return next(iter(self._engines.values()), None)

    def set_stream_state_callback(self, callback):
        self._stream_state_cb = callback
        with self._lock:
            for eng in self._engines.values():
                eng.set_stream_state_callback(callback)

    def write_output_report(self, report, expected_device=None, context='external-output'):
        # Lightbar/haptics still target a single physical pad -- route
        # through whichever engine is currently "primary" rather than
        # writing the same report to every controller.
        primary = self._primary_engine()
        if primary is None:
            return False
        return primary.write_output_report(report, expected_device=expected_device, context=context)

    def _ensure_engine(self, keys, candidate=None):
        # `keys` is every correlation key this candidate is reachable under
        # (serial-based AND path-family-based, when both are known). Over
        # Bluetooth, hidapi's serial-number reporting is flaky -- the input
        # thread and the audio-collection scan can each independently get
        # or miss the serial on any given poll, so the two sides don't
        # reliably agree on which single key to use. Registering (aliasing)
        # the SAME engine object under every key we know about means a
        # lookup succeeds no matter which key the caller computed.
        with self._lock:
            eng = None
            for k in keys:
                eng = self._engines.get(k)
                if eng is not None:
                    break
            if eng is None:
                eng = DualSenseBTAudioEngine(stream_state_cb=self._stream_state_cb)
            if candidate is not None and not eng.connected:
                # Pin (or refresh, if not yet connected) this engine to its
                # own pad's HID path so connect() can never bind to a
                # different physical pad -- see set_target_path().
                eng.set_target_path(candidate.get('path', ''))
            for k in keys:
                self._engines[k] = eng
            if self._primary_path is None and keys:
                self._primary_path = keys[0]
            return eng

    @staticmethod
    def _candidate_keys(candidate):
        path = candidate.get('path', '')
        serial = str(candidate.get('serial_number', '') or '').strip()
        keys = []
        if serial:
            keys.append('serial:' + serial)
        family = _hid_family_key(path)
        if family:
            keys.append('family:' + family)
        return keys

    def _scan_and_connect(self):
        if self._closing.is_set() or not self.available:
            return
        try:
            candidates = _bt_device_candidates()
        except Exception:
            candidates = []
        seen_keys = set()
        for candidate in candidates:
            keys = self._candidate_keys(candidate)
            if not keys:
                continue
            seen_keys.update(keys)
            eng = self._ensure_engine(keys, candidate=candidate)
            if not eng.connected:
                eng.connect_async()
        # Drop engines for controllers that are no longer paired/visible so
        # a stale entry can't keep claiming the "primary" slot forever.
        with self._lock:
            stale = [k for k in self._engines if k not in seen_keys and not self._engines[k].connected]
            for k in stale:
                try:
                    self._engines[k].close()
                except Exception:
                    pass
                del self._engines[k]
                if self._primary_path == k:
                    self._primary_path = next(iter(self._engines), None)

    def _rescan_loop(self):
        while not self._closing.is_set():
            self._scan_and_connect()
            self._closing.wait(self._RESCAN_INTERVAL_SEC)

    def connect_async(self):
        self._scan_and_connect()
        with self._lock:
            already_running = self._rescan_thread is not None and self._rescan_thread.is_alive()
        if not already_running and not self._closing.is_set():
            self._rescan_thread = threading.Thread(target=self._rescan_loop, daemon=True, name='dualsense-bt-audio-hub-rescan')
            self._rescan_thread.start()
        return True

    def force_reconnect_async(self):
        with self._lock:
            engines = list(self._engines.values())
        ok = False
        for eng in engines:
            if eng.force_reconnect_async():
                ok = True
        self._scan_and_connect()
        return ok

    def _broadcast(self, method_name, *args, **kwargs):
        with self._lock:
            # The same physical controller's engine object is aliased under
            # multiple dict keys (serial: and family:) when both are known
            # -- see _ensure_engine(). Dedupe by identity here, or a single
            # connected DualSense gets every cue (including the launch
            # sound) played on it once per alias instead of once total.
            seen_ids = set()
            engines = []
            for eng in self._engines.values():
                if id(eng) not in seen_ids:
                    seen_ids.add(id(eng))
                    engines.append(eng)
        result = False
        for eng in engines:
            try:
                method = getattr(eng, method_name)
                if method(*args, **kwargs):
                    result = True
            except Exception:
                pass
        return result

    def set_target(self, target):
        with self._lock:
            engines = list(self._engines.values())
        for eng in engines:
            eng.set_target(target)

    def play_file(self, path, start_offset=0.0):
        return self._broadcast('play_file', path, start_offset=start_offset)

    def play_ui_event(self, event, genre=None):
        return self._broadcast('play_ui_event', event, genre=genre)

    def crossfade_file(self, path, start_offset=0.0, duration=0.32):
        return self._broadcast('crossfade_file', path, start_offset=start_offset, duration=duration)

    def fade_out_and_stop(self, duration=0.32):
        return self._broadcast('fade_out_and_stop', duration=duration)

    def stop(self, clear_queue=True):
        with self._lock:
            engines = list(self._engines.values())
        for eng in engines:
            eng.stop(clear_queue=clear_queue)

    def set_volume(self, value):
        """Broadcast volume -- used by the global 'audio theme volume' slider."""
        self._last_broadcast_volume = value
        with self._lock:
            engines = list(self._engines.values())
        for eng in engines:
            eng.set_volume(value)

    set_loudness = set_volume

    def set_volume_for_path(self, path, value):
        """Per-controller volume -- only touches the engine for that pad."""
        with self._lock:
            eng = self._engines.get(path)
        if eng is not None:
            eng.set_volume(value)
        return eng is not None

    def get_volume_for_path(self, path, default=85):
        with self._lock:
            eng = self._engines.get(path)
        if eng is None:
            return default
        with eng._lock:
            return int(eng._loudness)

    def adjust_volume_for_path(self, path, delta):
        """Nudge one controller's volume by `delta` percentage points,
        clamped to 0-100. Used for per-pad L3 (down) / R3 (up)."""
        with self._lock:
            eng = self._engines.get(path)
        if eng is None:
            return None
        with eng._lock:
            current = int(eng._loudness)
        new_value = max(0, min(100, current + int(delta)))
        eng.set_volume(new_value)
        return new_value

    def close(self):
        self._closing.set()
        with self._lock:
            engines = list(self._engines.values())
            self._engines.clear()
            self._primary_path = None
        for eng in engines:
            try:
                eng.close()
            except Exception:
                pass


_RESOURCE_SAMPLE = {'at': 0.0, 'idle': 0, 'total': 0}

def _system_resource_snapshot():
    result = {'cpu_percent': None, 'ram_used_percent': None, 'ram_total_bytes': 0, 'ram_available_bytes': 0, 'gpu_percent': None, 'status': 'Not Available'}
    if os.name != 'nt':
        return result
    try:

        class _MemStatus(ctypes.Structure):
            _fields_ = [('length', wintypes.DWORD), ('memory_load', wintypes.DWORD), ('total', ctypes.c_ulonglong), ('available', ctypes.c_ulonglong), ('total_page', ctypes.c_ulonglong), ('available_page', ctypes.c_ulonglong), ('total_virtual', ctypes.c_ulonglong), ('available_virtual', ctypes.c_ulonglong), ('available_extended', ctypes.c_ulonglong)]
        memory = _MemStatus()
        memory.length = ctypes.sizeof(_MemStatus)
        if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(memory)):
            result.update({'ram_used_percent': int(memory.memory_load), 'ram_total_bytes': int(memory.total), 'ram_available_bytes': int(memory.available), 'status': 'Healthy'})
        idle = wintypes.FILETIME()
        kernel = wintypes.FILETIME()
        user = wintypes.FILETIME()
        if ctypes.windll.kernel32.GetSystemTimes(ctypes.byref(idle), ctypes.byref(kernel), ctypes.byref(user)):

            def _filetime(value):
                return (int(value.dwHighDateTime) << 32) + int(value.dwLowDateTime)
            idle_value = _filetime(idle)
            total_value = _filetime(kernel) + _filetime(user)
            previous = dict(_RESOURCE_SAMPLE)
            _RESOURCE_SAMPLE.update({'at': time.monotonic(), 'idle': idle_value, 'total': total_value})
            delta_idle = idle_value - previous['idle']
            delta_total = total_value - previous['total']
            if previous['total'] and delta_total > 0:
                result['cpu_percent'] = round(max(0.0, min(100.0, 100.0 * (1.0 - delta_idle / delta_total))), 1)
        return result
    except Exception:
        return result

