def _managed_dir(name: str) -> str:
    managed = os.path.join(_APP_DATA_DIR, name)
    legacy = os.path.join(os.getcwd(), name)
    if os.path.isdir(legacy) and (not os.path.isdir(managed)):
        return legacy
    try:
        os.makedirs(managed, exist_ok=True)
    except Exception:
        return legacy
    return managed

