_KEY_PLATFORM_RE = re.compile('(?:[\\s\\-_:|/\\[\\]()]+|^)(?:ps\\s*[1-5]|psp|ps\\s+vita|psvita|playstation|xbox(?:\\s*(?:360|one|series\\s*[xs]))?|x360|xone|pc|steam|gog|switch|nintendo\\s+switch|wii\\s*u|wii|gamecube|gc)(?:[\\s\\-_:|/\\[\\]()]+)?$', re.IGNORECASE)

def _key(s: str) -> str:
    if not s:
        return ''
    s = re.sub('[_\\.]+', ' ', s)
    s = re.sub('(?<=[a-z])(?=[A-Z])', ' ', s)
    s = re.sub('(?<=[A-Z])(?=[A-Z][a-z])', ' ', s)
    s = re.sub('([A-Za-z])(\\d+)$', '\\1 \\2', s.strip())
    prev = None
    cur = s.strip()
    while cur and cur != prev:
        prev = cur
        cur = _KEY_PLATFORM_RE.sub('', cur).strip(' -_:|/[]()')
    s = cur or s
    s = s.lower()
    s = re.sub('[™®©]', '', s)
    s = re.sub('[^a-z0-9\\u0600-\\u06FF]+', ' ', s)
    s = re.sub('\\b(setup|launcher|game|repack|goty|remastered?|edition|deluxe|definitive|complete|ultimate|directors?\\s*cut|ps\\s*[1-5]|psp|ps\\s+vita|psvita|playstation|xbox|switch|wii\\s*u|wii|gamecube|steam|gog|pc|the)\\b', ' ', s)
    return re.sub('\\s+', ' ', s).strip()
