_TITLE_LOOKUP: dict[str, str] = {}
_CANONICAL_ALIASES: dict[str, list[str]] = {}

def _init():
    for raw_alias, canonical in _RAW_TITLE_MAP:
        k = _key(raw_alias)
        if not k:
            continue
        _TITLE_LOOKUP.setdefault(k, canonical)
        aliases = _CANONICAL_ALIASES.setdefault(canonical, [])
        if raw_alias not in aliases:
            aliases.append(raw_alias)
    for canonical in list(_CANONICAL_ALIASES.keys()):
        k = _key(canonical)
        _TITLE_LOOKUP.setdefault(k, canonical)
_init()

def canonical_title(raw_title: str) -> 'str | None':
    if not raw_title:
        return None
    k = _key(raw_title)
    return _TITLE_LOOKUP.get(k)

def is_known_game(raw_title: str) -> bool:
    return canonical_title(raw_title) is not None

def alternate_search_titles(raw_title: str) -> list:
    canonical = canonical_title(raw_title)
    if not canonical:
        return []
    out = [canonical]
    for alias in _CANONICAL_ALIASES.get(canonical, []):
        if alias.lower() not in (x.lower() for x in out):
            out.append(alias)
    return out

_db_canonical_title = canonical_title
_db_alternate_titles = alternate_search_titles
_db_is_known_game = is_known_game
__all__ = ['_safe_filename', '_normalize_title', '_expand_title_aliases', '_typo_correct_title', '_acronym_from_title', '_split_letter_digit_boundary', '_title_query_variants', '_split_camel_case_title', '_strip_platform_suffix_noise', '_TITLE_ALIAS_PATTERNS', '_GAME_WORD_DICTIONARY', '_ACRONYM_STOPWORDS', '_extract_sequel_number', '_sequel_numbers_match', '_canonical_from_db', '_db_alternate_titles']

def _canonical_from_db(title: str) -> 'str | None':
    return _db_canonical_title(title)

def _safe_filename(name: str) -> str:
    name = re.sub('[\\\\/:*?"<>|]+', '_', name or '').strip()
    return (name or 'game')[:80]

def _split_camel_case_title(title: str) -> str:
    title = re.sub('[_\\.]+', ' ', title or '').strip()
    # Only split a lower->UPPER transition when the uppercase letter is
    # actually starting a new capitalized word (i.e. it's followed by a
    # lowercase letter, like "myGame" -> "my Game"). A lower->UPPER
    # transition followed by MORE uppercase letters is a stylized brand
    # spelling (e.g. "inFAMOUS", "eFOOTBALL"), not a word boundary, and
    # splitting it broke title matching (e.g. "inFAMOUS First Light" was
    # turning into "in FAMOUS First Light", which no longer matched
    # "infamous first light" anywhere titles are looked up, including the
    # built-in YouTube-audio pin table).
    title = re.sub('(?<=[a-z])(?=[A-Z][a-z])', ' ', title)
    title = re.sub('(?<=[A-Z])(?=[A-Z][a-z])', ' ', title)
    return re.sub('\\s+', ' ', title).strip()
_PLATFORM_SUFFIX_RE = re.compile('(?:[\\s\\-_:|/\\[\\]()]+|^)(?:ps\\s*[1-5]|psp|ps\\s+vita|psvita|playstation|xbox(?:\\s*(?:360|one|series\\s*[xs]))?|x360|xone|pc|steam|gog|switch|nintendo\\s+switch|wii\\s*u|wii|gamecube|gc)(?:[\\s\\-_:|/\\[\\]()]+)?$', re.IGNORECASE)

def _strip_platform_suffix_noise(title: str) -> str:
    prev = None
    cur = (title or '').strip()
    while cur and cur != prev:
        prev = cur
        cur = _PLATFORM_SUFFIX_RE.sub('', cur).strip(' -_:|/[]()')
    return cur or (title or '').strip()

def _normalize_title(t: str) -> str:
    t = _split_letter_digit_boundary(_split_camel_case_title(t or ''))
    t = _strip_platform_suffix_noise(t)
    t = t.lower()
    t = re.sub('[™®©]', '', t)
    t = re.sub('[^a-z0-9\\u0600-\\u06FF]+', ' ', t)
    t = re.sub('\\b(setup|launcher|game|repack|goty|remastered?|edition|deluxe|definitive|complete|ultimate|directors?\\s*cut|ps\\s*[1-5]|psp|ps\\s+vita|psvita|playstation|xbox|switch|wii\\s*u|wii|gamecube|steam|gog|pc)\\b', ' ', t)
    return re.sub('\\s+', ' ', t).strip()

# Built-in per-title YouTube-audio pins: these are applied automatically
# (no manual URL entry needed) the first time a matching game is seen,
# and then saved onto that game's data so it sticks and never falls back
# to auto-search.
_BUILTIN_YOUTUBE_AUDIO_PINS = {
    'infamous first light': 'https://www.youtube.com/watch?v=PXnYo4q-Li0',
    'infamous second son': 'https://www.youtube.com/watch?v=fz5punC-39I',
    # NBA 2K27 has no single canonical "theme" (it ships a 50+ track
    # yearly soundtrack playlist), so the normal 'main theme'/'ost'
    # search just grabs unrelated results. Pinned to the specific
    # video the user picked. (The '&list=...' on the URL is a playlist
    # reference from where the user copied the link -- harmless here
    # since _fetch_youtube_audio_candidate always passes noplaylist=True,
    # so only this single video is ever downloaded, never the playlist.)
    'nba 2k27': 'https://youtu.be/fFtpY625mfE',
}

def _builtin_youtube_audio_pin_for(title: str):
    return _BUILTIN_YOUTUBE_AUDIO_PINS.get(_normalize_title(title))

_TITLE_ALIAS_PATTERNS = [('\\bBO6\\b', 'Black Ops 6'), ('\\bBO\\s*Cold\\s*War\\b', 'Black Ops Cold War'), ('\\bBO5\\b', 'Black Ops Cold War'), ('\\bBO4\\b', 'Black Ops 4'), ('\\bBO3\\b', 'Black Ops 3'), ('\\bBO2\\b', 'Black Ops 2'), ('\\bBO1\\b', 'Black Ops'), ('\\bMW2\\b', 'Modern Warfare 2'), ('\\bMW3\\b', 'Modern Warfare 3'), ('\\bMWII\\b', 'Modern Warfare 2'), ('\\bMWIII\\b', 'Modern Warfare 3'), ('\\bBFV\\b', 'Battlefield V'), ('\\bBF1\\b', 'Battlefield 1'), ('\\bBF4\\b', 'Battlefield 4'), ('\\bBF5\\b', 'Battlefield V'), ('\\bBF2042\\b', 'Battlefield 2042'), ('\\bGTA\\s*5\\b', 'Grand Theft Auto V'), ('\\bGTA\\s*V\\b', 'Grand Theft Auto V'), ('\\bGTA\\s*4\\b', 'Grand Theft Auto IV'), ('\\bRDR2\\b', 'Red Dead Redemption 2'), ('\\bRDR\\s*2\\b', 'Red Dead Redemption 2'), ('\\bFC6\\b', 'Far Cry 6'), ('\\bFC5\\b', 'Far Cry 5'), ('\\bACV\\b', 'Assassins Creed Valhalla'), ('\\bACO\\b', 'Assassins Creed Origins'), ('\\bMoto\\s+GP\\b', 'MotoGP'), ('^Bloodlines\\s*2$', 'Vampire The Masquerade Bloodlines 2'), ('\\bPES\\b', 'eFootball')]

def _expand_title_aliases(title: str) -> str:
    title = _strip_platform_suffix_noise(title)
    for pattern, replacement in _TITLE_ALIAS_PATTERNS:
        new = re.sub(pattern, replacement, title, flags=re.IGNORECASE)
        if new != title:
            return new
    return title
_GAME_WORD_DICTIONARY = {'grand', 'theft', 'auto', 'call', 'duty', 'black', 'ops', 'cold', 'war', 'modern', 'warfare', 'battlefield', 'red', 'dead', 'redemption', 'assassins', 'creed', 'valhalla', 'origins', 'odyssey', 'far', 'cry', 'watch', 'dogs', 'rainbow', 'six', 'siege', 'ghost', 'recon', 'splinter', 'cell', 'gears', 'halo', 'forza', 'horizon', 'minecraft', 'fortnite', 'valorant', 'overwatch', 'league', 'legends', 'dota', 'counter', 'strike', 'apex', 'destiny', 'diablo', 'warcraft', 'starcraft', 'doom', 'wolfenstein', 'resident', 'evil', 'silent', 'hill', 'metal', 'gear', 'solid', 'final', 'fantasy', 'kingdom', 'hearts', 'persona', 'dark', 'souls', 'elden', 'ring', 'sekiro', 'bloodborne', 'monster', 'hunter', 'tekken', 'street', 'fighter', 'mortal', 'kombat', 'fifa', 'madden', 'need', 'speed', 'gran', 'turismo', 'spider', 'man', 'batman', 'marvel', 'star', 'wars', 'lego', 'sims', 'cities', 'skylines', 'age', 'empires', 'civilization', 'total', 'xcom', 'divinity', 'baldurs', 'gate', 'pathfinder', 'hollow', 'knight', 'celeste', 'hades', 'terraria', 'stardew', 'valley', 'ori', 'cuphead', 'undertale', 'portal', 'half', 'life', 'left', 'borderlands', 'rocket', 'among', 'fall', 'guys', 'pubg', 'dayz', 'rust', 'ark', 'palworld', 'lethal', 'company', 'stellar', 'blade', 'uncharted', 'forbidden', 'west', 'tsushima', 'last', 'part', 'god', 'elder', 'scrolls', 'fallout', 'cyberpunk', 'witcher', 'plants', 'zombies', 'replanted', 'football', 'efootball', 'pes', 'crew', 'motogp', 'shadow', 'tomb', 'raider', 'dying', 'light', 'days', 'gone', 'death', 'stranding', 'sekiro', 'remnant', 'lies', 'frontier', 'hogwarts', 'legacy', 'jedi', 'fallen', 'order', 'survivor', 'bloodlines', 'bloodline', 'vampire', 'masquerade', 'plague', 'innocence', 'requiem', 'legacy', 'thief', 'thieves', 'drake', 'collection', 'club', 'drive', 'khiimori', 'farming', 'simulator', 'london'}

def _title_is_in_known_db(title: str) -> bool:
    try:
        return _db_is_known_game(title)
    except Exception:
        return False

def _typo_correct_title(title: str) -> str:
    if _title_is_in_known_db(title):
        return ''
    words = title.split()
    out, changed = ([], False)
    for w in words:
        core = re.sub('[^A-Za-z]', '', w)
        if len(core) < 4 or core.upper() == core:
            out.append(w)
            continue
        core_lower = core.lower()
        if core_lower in _GAME_WORD_DICTIONARY:
            out.append(w)
            continue
        match = difflib.get_close_matches(core_lower, _GAME_WORD_DICTIONARY, n=1, cutoff=0.75)
        if not match or match[0] == core_lower:
            out.append(w)
            continue
        candidate = match[0]
        if len(candidate) < len(core) - 2:
            out.append(w)
            continue
        fixed = candidate.capitalize() if core[0].isupper() else candidate
        out.append(w.replace(core, fixed, 1))
        changed = True
    return ' '.join(out) if changed else ''
_ACRONYM_STOPWORDS = {'of', 'the', 'and', 'a', 'an', 'in', 'for'}

def _acronym_from_title(title: str) -> str:
    words = re.findall('[A-Za-z0-9]+', title)
    letters = []
    real_word_count = 0
    for w in words:
        if w.lower() in _ACRONYM_STOPWORDS:
            continue
        if w.isdigit() or re.fullmatch('[IVXLCM]+', w, re.IGNORECASE):
            letters.append(w.upper())
        else:
            letters.append(w[0].upper())
            if len(w) >= 2:
                real_word_count += 1
    acro = ''.join(letters)
    if real_word_count < 3:
        return ''
    if len(acro) < 3:
        return ''
    return acro

def _split_letter_digit_boundary(title: str) -> str:
    return re.sub('([A-Za-z])(\\d+)$', '\\1 \\2', title.strip())
_SEQUEL_NUM_DIGIT_RE = re.compile('(\\d+)')
_SEQUEL_NUM_ROMAN_RE = re.compile('\\b([IVXLCM]{1,4})\\b')
_ROMAN_TO_INT = {'I': 1, 'II': 2, 'III': 3, 'IV': 4, 'V': 5, 'VI': 6, 'VII': 7, 'VIII': 8, 'IX': 9, 'X': 10, 'XI': 11, 'XII': 12}

def _extract_sequel_number(title: str) -> 'int | None':
    if not title:
        return None
    digits = _SEQUEL_NUM_DIGIT_RE.findall(title)
    if digits:
        return int(digits[-1])
    romans = _SEQUEL_NUM_ROMAN_RE.findall(title)
    if romans:
        return _ROMAN_TO_INT.get(romans[-1].upper())
    return None

def _sequel_numbers_match(queried: str, candidate: str) -> bool:
    a, b = (_extract_sequel_number(queried), _extract_sequel_number(candidate))
    if a is None or b is None:
        return True
    return a == b

def _title_query_variants(title: str) -> list:
    variants = [title]

    def _add(v: str):
        if v and v.lower() not in (x.lower() for x in variants):
            variants.append(v)
    try:
        for alt in _db_alternate_titles(title) or []:
            _add(alt)
    except Exception:
        pass
    split = _split_camel_case_title(title)
    split_num = _split_letter_digit_boundary(split or title)
    stripped = _strip_platform_suffix_noise(split_num or split or title)
    for base in (split, split_num, stripped):
        _add(base)
    for base in (title, split, split_num, stripped):
        if not base:
            continue
        corrected = _typo_correct_title(base)
        _add(corrected)
        expanded = _expand_title_aliases(base)
        _add(expanded)
        if corrected:
            _add(_expand_title_aliases(corrected))
    acro = _acronym_from_title(stripped or split_num or split or title)
    if acro and len(acro) >= 4:
        _add(acro)
    return variants
_REAL_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/136.0.0.0 Safari/537.36'
