def _check_for_block(html: str, engine: str) -> bool:
    if html and re.search('unusual traffic|captcha|/sorry/|anomaly', html, re.IGNORECASE):
        with _LAST_BLOCK_LOCK:
            _LAST_BLOCK_INFO['ts'] = time.time()
            _LAST_BLOCK_INFO['engine'] = engine
        return True
    return False

def _recent_block_engine(within_secs: float=25.0):
    with _LAST_BLOCK_LOCK:
        if time.time() - _LAST_BLOCK_INFO['ts'] <= within_secs:
            return _LAST_BLOCK_INFO['engine']
    return None
