_YTDLP_BOOTSTRAP_LOCK = threading.Lock()
_YTDLP_BOOTSTRAP_ERROR = ''
_AUDIO_AV_BOOTSTRAP_LOCK = threading.Lock()
_AUDIO_AV_BOOTSTRAP_ERROR = ''
_YTDLP_UPDATE_CHECK_INTERVAL = 20 * 60 * 60

def _ytdlp_update_state_path():
    return os.path.join(_managed_dir('python_packages'), 'ytdlp_update_check.json')

def _ytdlp_last_update_check():
    try:
        with open(_ytdlp_update_state_path(), 'r', encoding='utf-8') as f:
            return float(json.load(f).get('last_check') or 0)
    except Exception:
        return 0.0

def _ytdlp_record_update_check():
    try:
        with open(_ytdlp_update_state_path(), 'w', encoding='utf-8') as f:
            json.dump({'last_check': time.time()}, f)
    except Exception:
        pass

def _ytdlp_autoupdate_if_stale():
    """
    YouTube changes its player/signature logic often enough that a yt-dlp
    build even a week or two old commonly starts failing EVERY request with
    HTTP 403/503 across every player client -- that's an out-of-date
    extractor, not a real network problem, and no amount of retrying fixes
    it. This checks for a newer yt-dlp release at most once every
    _YTDLP_UPDATE_CHECK_INTERVAL seconds and, if one is installed, reloads
    it in place -- so a launcher install that's been sitting untouched for
    weeks keeps working without the user having to notice or reinstall
    anything.
    """
    global _yt_dlp, _YTDLP_BOOTSTRAP_ERROR
    if time.time() - _ytdlp_last_update_check() < _YTDLP_UPDATE_CHECK_INTERVAL:
        return
    with _YTDLP_BOOTSTRAP_LOCK:
        if time.time() - _ytdlp_last_update_check() < _YTDLP_UPDATE_CHECK_INTERVAL:
            return
        _ytdlp_record_update_check()
        package_dir = _managed_dir('python_packages')
        try:
            os.makedirs(package_dir, exist_ok=True)
            result = subprocess.run([sys.executable, '-m', 'pip', 'install', '--disable-pip-version-check', '--upgrade', '--target', package_dir, 'yt-dlp'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=180, check=False, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        except Exception:
            return
        if result.returncode != 0:
            return
        if package_dir in sys.path:
            sys.path.remove(package_dir)
        sys.path.insert(0, package_dir)
        sys.modules.pop('yt_dlp', None)
        importlib.invalidate_caches()
        try:
            _yt_dlp = importlib.import_module('yt_dlp')
            _YTDLP_BOOTSTRAP_ERROR = ''
        except Exception as exc:
            _YTDLP_BOOTSTRAP_ERROR = f'yt-dlp auto-update installed but could not be reloaded: {exc}'

def _ensure_ytdlp_available():
    global _yt_dlp, _YTDLP_BOOTSTRAP_ERROR
    if _yt_dlp is not None:
        _ytdlp_autoupdate_if_stale()
        return _yt_dlp
    with _YTDLP_BOOTSTRAP_LOCK:
        if _yt_dlp is not None:
            return _yt_dlp
        try:
            _yt_dlp = importlib.import_module('yt_dlp')
            _ytdlp_record_update_check()
            return _yt_dlp
        except Exception:
            pass
        package_dir = _managed_dir('python_packages')
        os.makedirs(package_dir, exist_ok=True)
        command = [sys.executable, '-m', 'pip', 'install', '--disable-pip-version-check', '--upgrade', '--target', package_dir, 'yt-dlp>=2026.7.4']
        try:
            result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=180, check=False, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        except Exception as exc:
            _YTDLP_BOOTSTRAP_ERROR = f'Could not start the Python package installer: {exc}'
            return None
        if result.returncode != 0:
            detail = (result.stderr or result.stdout or '').strip()
            if len(detail) > 1200:
                detail = detail[-1200:]
            _YTDLP_BOOTSTRAP_ERROR = 'Could not install yt-dlp automatically.' + (f'\n{detail}' if detail else '')
            return None
        if package_dir not in sys.path:
            sys.path.insert(0, package_dir)
        importlib.invalidate_caches()
        try:
            _yt_dlp = importlib.import_module('yt_dlp')
            _YTDLP_BOOTSTRAP_ERROR = ''
            _ytdlp_record_update_check()
            return _yt_dlp
        except Exception as exc:
            _YTDLP_BOOTSTRAP_ERROR = f'yt-dlp installation completed but could not be loaded: {exc}'
            return None

