def _rawg_candidate_urls(title: str) -> list:
    global _rawg_enabled
    if not _rawg_api_key or not _rawg_enabled:
        return []
    search_title = _canonical_from_db(title) or _expand_title_aliases(title)
    q = urllib.parse.urlencode({'key': _rawg_api_key, 'search': search_title, 'page_size': 5})
    url = f'https://api.rawg.io/api/games?{q}'
    try:
        req = urllib.request.Request(url, headers={'User-Agent': _REAL_UA, 'Accept': 'application/json'})
        with urllib.request.urlopen(req, timeout=10) as r:
            data = json.loads(r.read().decode('utf-8', 'ignore'))
    except urllib.error.HTTPError as e:
        if e.code == 401:
            _rawg_enabled = False
        return []
    except Exception:
        return []
    results = data.get('results') or []
    if not results:
        return []
    out = []
    norm = _normalize_title(search_title)
    for item in results[:5]:
        name = item.get('name', '')
        if not _sequel_numbers_match(search_title, name):
            continue
        s = difflib.SequenceMatcher(None, norm, _normalize_title(name)).ratio()
        if s < 0.55:
            continue
        bg = item.get('background_image')
        if bg and bg.startswith('http'):
            out.append((bg, 'RAWG'))
    return out

def _wallpaper_candidate_urls(title: str) -> list:
    search_title = _canonical_from_db(title) or _expand_title_aliases(title)
    if not search_title:
        return []
    queries = [f'"{search_title}" game 4k wallpaper landscape', f'"{search_title}" game hero art 1920x1080']
    out, seen = ([], set())
    lock = threading.Lock()

    def _one(q):
        try:
            urls = _bing_ddg_image_search_urls(q, limit=12)
        except Exception as e:
            return
        with lock:
            for u in urls:
                if u and u not in seen:
                    seen.add(u)
                    out.append(u)
    with concurrent.futures.ThreadPoolExecutor(max_workers=len(queries)) as ex:
        futs = [ex.submit(_one, q) for q in queries]
        done, not_done = concurrent.futures.wait(futs, timeout=12)
        for f in not_done:
            f.cancel()
    return [(u, 'Wallpaper Search') for u in out]

