def _save_override_image(urls: list, dest_path: str) -> bool:
    """Download the first working URL from a manual override list and save
    it as-is (PNG), with none of the aspect-ratio/sharpness/relevance
    gating the automated pipeline applies -- a manual override is already
    known-correct, so it shouldn't be able to fail those checks and fall
    through to the automated search."""
    for url in urls:
        try:
            raw = _http_get_bytes(url, timeout=10)
        except Exception:
            continue
        if not raw or len(raw) < 200:
            continue
        img = QImage()
        if not img.loadFromData(raw):
            continue
        os.makedirs(os.path.dirname(dest_path) or '.', exist_ok=True)
        if img.save(dest_path, 'PNG'):
            _remember_download_src_hash(dest_path, raw)
            return True
    return False

def _steamgriddb_log_failure(fn_label: str, title: str, exc: Exception):
    try:
        with open(_asset_search_log_path(), 'a', encoding='utf-8') as f:
            f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {title!r}: {fn_label} lookup FAILED (not just 'no match'): {type(exc).__name__}: {exc}\n")
    except Exception:
        pass

def _steamgriddb_resolve_game_id(search_title: str, log_label: str) -> 'int | None':
    """
    Fuzzy autocomplete-based game-id lookup. Raises on network/HTTP
    errors instead of swallowing them, so callers can log the *real*
    reason a lookup failed (bad/expired key, rate limit, etc.) instead
    of it looking identical to "genuinely no match found". This is a
    best-effort fallback only -- prefer adding a _LOGO_URL_OVERRIDES
    entry when a title is known to trip this up, since that doesn't
    depend on this matching logic (or the API) working at all.
    """
    headers = {'User-Agent': _REAL_UA, 'Authorization': f'Bearer {_steamgriddb_api_key}'}
    q = urllib.parse.quote(search_title)
    search_url = f'https://www.steamgriddb.com/api/v2/search/autocomplete/{q}'
    req = urllib.request.Request(search_url, headers=headers)
    with urllib.request.urlopen(req, timeout=8) as r:
        data = json.loads(r.read().decode('utf-8', 'ignore'))
    results = data.get('data') or []
    if not results:
        return None
    norm = _normalize_title(search_title)
    best, best_score = (None, 0.0)
    for item in results[:10]:
        cand_name = item.get('name', '')
        if not _sequel_numbers_match(search_title, cand_name):
            continue
        s = difflib.SequenceMatcher(None, norm, _normalize_title(cand_name)).ratio()
        if s > best_score:
            best_score, best = (s, item)
    if not best or not best.get('id'):
        return None
    if best_score < _LAST_RESORT_MATCH_THRESHOLD:
        return None
    return best['id']

def _steamgriddb_wordmark_candidates(title: str) -> list:
    if not _steamgriddb_api_key:
        return []
    search_title = _expand_title_aliases(title)
    try:
        game_id = _steamgriddb_resolve_game_id(search_title, 'SteamGridDB-Logo')
        if not game_id:
            return []
        headers = {'User-Agent': _REAL_UA, 'Authorization': f'Bearer {_steamgriddb_api_key}'}
        logos_url = f"https://www.steamgriddb.com/api/v2/logos/game/{game_id}?nsfw=false&humor=false&styles=official,white,black,material"
        req2 = urllib.request.Request(logos_url, headers=headers)
        with urllib.request.urlopen(req2, timeout=8) as r2:
            ldata = json.loads(r2.read().decode('utf-8', 'ignore'))
        out = []
        for logo in ldata.get('data') or []:
            if logo.get('humor') or logo.get('nsfw'):
                continue
            url = logo.get('url')
            if url:
                out.append((url, 'SteamGridDB-Logo'))
        return out
    except Exception as e:
        _steamgriddb_log_failure('SteamGridDB-Logo', title, e)
        return []

def _igdb_cover_candidates(title: str) -> list:
    """
    Looks up the game on IGDB (the same database that powers
    igdb.com's own game pages) and returns its official cover art.
    Unlike a plain web image search, this disambiguates by matching
    against IGDB's actual catalog of games (with sequel-number
    checking, same as the background-art IGDB lookup), so it still
    works for titles that are common English words -- e.g. "Routine"
    -- where a generic image search mostly returns unrelated results
    (daily/workout routines etc.) instead of the game.
    """
    token = ''
    try:
        token = _igdb_ensure_token()
    except Exception:
        return []
    if not token:
        return []
    search_title = _canonical_from_db(title) or _expand_title_aliases(title)
    body = f'search "{search_title.replace(chr(34), chr(39))}"; fields name,cover.image_id,cover.width,cover.height; limit 10;'.encode('utf-8')
    req = urllib.request.Request('https://api.igdb.com/v4/games', data=body, headers={'Client-ID': _igdb_client_id, 'Authorization': f'Bearer {token}', 'User-Agent': _REAL_UA, 'Accept': 'application/json'}, method='POST')
    try:
        with urllib.request.urlopen(req, timeout=10) as r:
            results = json.loads(r.read().decode('utf-8', 'ignore'))
    except Exception:
        return []
    if not isinstance(results, list) or not results:
        return []
    norm = _normalize_title(search_title)
    best, best_score = (None, 0.0)
    for item in results[:10]:
        name = item.get('name', '')
        if not _sequel_numbers_match(search_title, name):
            continue
        s = difflib.SequenceMatcher(None, norm, _normalize_title(name)).ratio()
        if s > best_score and s >= 0.62:
            best_score, best = (s, item)
    if not best:
        return []
    cover = best.get('cover') or {}
    image_id = cover.get('image_id')
    if not image_id:
        return []
    return [(f'https://images.igdb.com/igdb/image/upload/t_cover_big_2x/{image_id}.jpg', 'IGDB (cover)')]

