def _wikimedia_logo_candidates(title: str) -> list:
    try:
        search_title = _expand_title_aliases(title)
        q = urllib.parse.quote(f'{search_title} game logo')
        search_url = f'https://commons.wikimedia.org/w/api.php?action=query&list=search&srsearch={q}+filetype:bitmap&srnamespace=6&srlimit=8&format=json'
        req = urllib.request.Request(search_url, headers={'User-Agent': _REAL_UA})
        with urllib.request.urlopen(req, timeout=8) as r:
            data = json.loads(r.read().decode('utf-8', 'ignore'))
        hits = (data.get('query') or {}).get('search') or []
        if not hits:
            return []
        titles_param = '|'.join((urllib.parse.quote(h['title']) for h in hits[:6]))
        info_url = f'https://commons.wikimedia.org/w/api.php?action=query&titles={titles_param}&prop=imageinfo&iiprop=url|size|mime&format=json'
        req2 = urllib.request.Request(info_url, headers={'User-Agent': _REAL_UA})
        with urllib.request.urlopen(req2, timeout=8) as r2:
            idata = json.loads(r2.read().decode('utf-8', 'ignore'))
        pages = (idata.get('query') or {}).get('pages') or {}
        out = []
        for page in pages.values():
            for ii in page.get('imageinfo') or []:
                mime = ii.get('mime', '')
                if 'png' not in mime and 'svg' not in mime:
                    continue
                url = ii.get('url', '')
                if url:
                    out.append((url, 'Wikimedia'))
        return out
    except Exception as e:
        return []

def _round_query_suffix(round_num: int) -> str:
    suffixes = ['', ' hd', ' high resolution', ' official art', ' wallpaper', ' fan art', ' artwork', ' wiki', ' cover art']
    return suffixes[round_num % len(suffixes)]

def _logo_search_loosening(round_num: int):
    if round_num < 3:
        return (True, True)
    if round_num < 6:
        return (False, True)
    return (False, False)
_CAPTCHA_PROMPT_LOCK = threading.Lock()
_CAPTCHA_NEXT_PROMPT_OK_AT = 0.0

def _maybe_prompt_captcha_solver_ex():
    global _CAPTCHA_NEXT_PROMPT_OK_AT
    if not _HAS_WEBENGINE:
        return (False, 'PyQt6-WebEngine not installed (or installed but the launcher was not restarted since) — install/verify it from Settings → Requirements → Prerequisites, then restart the launcher')
    engine = _recent_block_engine()
    if engine is None:
        return (False, 'no anti-bot block detected recently — the search engines are returning empty results, not a CAPTCHA, so there is nothing to solve')
    with _CAPTCHA_PROMPT_LOCK:
        if time.time() < _CAPTCHA_NEXT_PROMPT_OK_AT:
            return (False, f'{engine} block detected, but a CAPTCHA prompt was already shown recently and is on cooldown')
        _CAPTCHA_NEXT_PROMPT_OK_AT = time.time() + 20
    try:
        solved = _solve_captcha_interactively(engine)
    except Exception as e:
        solved = False
        reason = f'{engine} CAPTCHA dialog failed to open: {type(e).__name__}: {e}'
    else:
        reason = f'{engine} CAPTCHA solved by user' if solved else f'{engine} CAPTCHA prompt shown but not solved/declined'
    with _CAPTCHA_PROMPT_LOCK:
        _CAPTCHA_NEXT_PROMPT_OK_AT = time.time() + (5 if solved else 300)
    return (solved, reason)

def _maybe_prompt_captcha_solver() -> bool:
    solved, _reason = _maybe_prompt_captcha_solver_ex()
    return solved

def _fetch_candidates_with_escalation(fetch_fn, title: str, exclude_hashes: set=None, max_rounds: int=None, progress_cb=None) -> list:
    exclude = exclude_hashes or set()
    round_num = 0
    while True:
        last_error = None
        try:
            candidates = fetch_fn(title, exclude_hashes=exclude, round_num=round_num)
        except Exception as e:
            candidates = []
            last_error = f'{type(e).__name__}: {e}'
        if candidates:
            return candidates
        solved, captcha_reason = _maybe_prompt_captcha_solver_ex()
        if progress_cb is not None:
            try:
                if last_error:
                    combined_error = f'{last_error} | captcha: {captcha_reason}'
                elif solved or 'no anti-bot block detected' not in captcha_reason:
                    combined_error = f'captcha: {captcha_reason}'
                else:
                    combined_error = 'no candidates found (search returned empty results)'
                progress_cb(round_num, combined_error)
            except Exception:
                pass
        if not solved and max_rounds is not None and (round_num + 1) >= max_rounds:
            return []
        if solved:
            round_num += 1
            continue
        if round_num < 5:
            delay = min(0.4 + round_num * 0.3, 2)
        else:
            delay = min(_BG_RETRY_BACKOFF_BASE_SECS * 2 ** min(round_num - 5, 7), _BG_RETRY_BACKOFF_MAX_SECS)
        time.sleep(delay)
        round_num += 1

def _asset_search_progress_cb(self_ref, title: str, kind_label: str):

    def _cb(round_num: int, last_error):
        slow_phase = round_num >= 5
        if not slow_phase and round_num % 4 != 0:
            return
        try:
            with open(_asset_search_log_path(), 'a', encoding='utf-8') as f:
                f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {title!r}: {kind_label} still searching (round {round_num + 1})" + (f' — last error: {last_error}' if last_error else '') + '\n')
        except Exception:
            pass

        def _notify():
            ref = self_ref()
            if ref is None or not hasattr(ref, '_tray'):
                return
            extra = '\nSearch engines may be temporarily rate-limiting us — still retrying with longer delays.' if slow_phase else ''
            ref._tray.showMessage('Game Station', f"“{title}”: still searching for {kind_label}, won't stop until found..." + extra, QSystemTrayIcon.MessageIcon.Information, 3000)
        _UI_INVOKER.invoke(_notify)
    return _cb

def _name_logo_search_queries(title: str, round_num: int=0) -> list:
    t = (title or '').strip()
    if not t:
        return []
    suf = _round_query_suffix(round_num)
    if round_num < 3:
        return [f'{t} game logo transparent png{suf}', f'{t} game title logo png{suf}']
    if round_num < 6:
        return [f'{t} game logo{suf}', f'{t} game title logo{suf}']
    return [f'{t} game logo{suf}']

def _multi_engine_image_candidates(query: str, shape: str='wide', transparent: bool=False, limit: int=15, large_only: bool=True) -> list:
    out = []
    q = urllib.parse.quote(query)
    _BING_ASPECT = {'wide': 'aspect-wide', 'portrait': 'aspect-tall', 'square': 'aspect-square'}.get(shape, '')
    _DDG_LAYOUT = {'wide': 'Wide', 'portrait': 'Tall', 'square': 'Square'}.get(shape, '')
    _GOOGLE_SIZE = 'isz:l' if large_only else ''
    tbs_parts = ([_GOOGLE_SIZE] if _GOOGLE_SIZE else []) + (['itp:clipart'] if transparent else [])
    tbs = ','.join(tbs_parts)
    google_endpoints = [f'https://www.google.com/search?q={q}&tbm=isch&tbs={tbs}&hl=en', f'https://www.google.com/search?q={q}&tbm=isch&tbs={_GOOGLE_SIZE}&hl=en', f'https://www.google.com/search?q={q}&udm=2&tbs={_GOOGLE_SIZE}&hl=en']

    def _bad_google(u: str) -> bool:
        return 'gstatic.com' in u or ('google.com' in u and 'googleusercontent.com' not in u)
    for gurl in google_endpoints:
        try:
            req = urllib.request.Request(gurl, headers={'User-Agent': _REAL_UA, 'Accept-Language': 'en-US,en;q=0.9', 'Referer': 'https://www.google.com/'})
            with _urlopen_search(req, timeout=8) as r:
                html = r.read().decode('utf-8', 'ignore')
            if _check_for_block(html, 'Google'):
                break
            before = len(out)
            for m in re.finditer('\\["(https?://[^"]+?)",\\s*(\\d+),\\s*(\\d+)\\]', html):
                u = m.group(1)
                if not _bad_google(u):
                    out.append((u, 'Google'))
                if len(out) >= limit:
                    break
            if len(out) < limit:
                for m in re.finditer('"ou":"(https?:[^"]+?)"', html):
                    u = m.group(1).replace('\\/', '/').replace('\\u003d', '=').replace('\\u0026', '&')
                    if not _bad_google(u):
                        out.append((u, 'Google'))
                    if len(out) >= limit:
                        break
            if len(out) > before:
                break
        except Exception as e:
            pass
    if len(out) < limit:
        try:
            bing_bits = [f'filterui:{_BING_ASPECT}'] if _BING_ASPECT else []
            if transparent:
                bing_bits.append('filterui:photo-transparent')
            filt = '&qft=+' + '+'.join(bing_bits) if bing_bits else ''
            url = f'https://www.bing.com/images/async?q={q}&first=1&count={limit}&mmasync=1{filt}'
            req = urllib.request.Request(url, headers={'User-Agent': _REAL_UA, 'Accept-Language': 'en-US,en;q=0.9', 'X-Requested-With': 'XMLHttpRequest'})
            with urllib.request.urlopen(req, timeout=6) as r:
                html = r.read().decode('utf-8', 'ignore')
            for m in re.finditer('&quot;murl&quot;:&quot;([^&]+)', html):
                out.append((m.group(1), 'Bing'))
                if len(out) >= limit * 2:
                    break
        except Exception as e:
            pass
    if len(out) < limit:
        try:
            token_url = f'https://duckduckgo.com/?q={q}&iar=images&iax=images&ia=images'
            req1 = urllib.request.Request(token_url, headers={'User-Agent': _REAL_UA})
            with _urlopen_search(req1, timeout=5) as r:
                token_html = r.read().decode('utf-8', 'ignore')
            vqd_match = re.search('vqd=[\\\'"]?([\\d-]+)[\\\'"]?', token_html) or re.search('vqd=([\\d-]+)&', token_html)
            if vqd_match:
                vqd = vqd_match.group(1)
                f_parts = ['', '', '', 'type:transparent' if transparent else '', f'layout:{_DDG_LAYOUT}' if _DDG_LAYOUT else '']
                f_field = ','.join(f_parts)
                api_url = f'https://duckduckgo.com/i.js?l=us-en&o=json&q={q}&vqd={vqd}&f={f_field}&p=1'
                req2 = urllib.request.Request(api_url, headers={'User-Agent': _REAL_UA, 'Referer': 'https://duckduckgo.com/', 'Accept': 'application/json'})
                with _urlopen_search(req2, timeout=5) as r:
                    data = json.loads(r.read().decode('utf-8', 'ignore'))
                for item in data.get('results') or []:
                    u = item.get('image') or ''
                    if u:
                        out.append((u, 'DDG'))
                    if len(out) >= limit * 2:
                        break
        except Exception as e:
            pass
    return out

def _transparent_wide_logo_candidates(query: str, limit: int=15, transparent: bool=True, large_only: bool=True) -> list:
    return _multi_engine_image_candidates(query, shape='wide', transparent=transparent, limit=limit, large_only=large_only)

def _url_is_relevant(url: str, title: str) -> bool:
    if not title or not url:
        return True
    _TRUSTED = ('store.playstation.com', 'image.api.playstation.com', 'store.steampowered.com', 'cdn.cloudflare.steamstatic.com', 'steamcdn-a.akamaihd.net', 'images.igdb.com', 'igdb.com', 'media.rawg.io', 'rawg.io', 'giantbomb.com', 'static.giantbomb.com', 'mobygames.com', 'www.mobygames.com', 'psnine.com', 'playstationtrophies.org', 'thegamesdb.net', 'cdn.thegamesdb.net', 'steamgriddb.com', 'cdn2.steamgriddb.com')
    try:
        host = urllib.parse.urlparse(url).netloc.lower().lstrip('www.')
    except Exception:
        host = ''
    if any((host == d or host.endswith('.' + d) for d in _TRUSTED)):
        return True
    SKIP = {'the', 'and', 'for', 'with', 'of', 'in', 'on', 'at', 'to', 'a', 'an', 'de', 'la', 'le', 'los', 'las', 'png', 'logo', 'icon', 'img', 'image', 'thumb', 'transparent', 'wide', 'sports', 'games', 'entertainment', 'interactive', 'studios', 'presents', 'software', 'studio'}
    title_tokens = [w for w in re.findall('[a-z0-9]+', title.lower()) if len(w) >= 3 and w not in SKIP]
    if not title_tokens:
        return True
    try:
        path = urllib.parse.urlparse(url).path
        filename = re.sub('\\.[a-z]{2,4}$', '', path.split('/')[-1]).lower()
        filename = re.sub('[^a-z0-9]+', ' ', filename)
    except Exception:
        filename = url.lower()
    matched = sum((1 for tok in title_tokens if tok in filename))
    required = 1
    if matched >= required:
        return True
    if len(title_tokens) == 1:
        ratio = difflib.SequenceMatcher(None, title_tokens[0], filename).ratio()
        if ratio >= 0.72:
            return True
    return False

def _is_valid_transparent_logo(img: 'QImage') -> bool:
    if img.isNull():
        return False
    w, h = (img.width(), img.height())
    if w < _MIN_LOGO_WIDTH or h <= 0:
        return False
    if w / h < _MIN_LOGO_ASPECT:
        return False
    if not img.hasAlphaChannel():
        return False
    STEPS = 5
    border_pixels = []
    for i in range(STEPS):
        t = (i + 1) / (STEPS + 1)
        bx = int(t * (w - 1))
        by = int(t * (h - 1))
        border_pixels += [(bx, 0), (bx, h - 1), (0, by), (w - 1, by)]
    transparent = 0
    for x, y in border_pixels:
        x = max(0, min(w - 1, x))
        y = max(0, min(h - 1, y))
        alpha = img.pixelColor(x, y).alpha()
        if alpha < 20:
            transparent += 1
    return transparent / len(border_pixels) >= 0.6

def _is_valid_game_icon(img: 'QImage', allow_non_square: bool=False) -> bool:
    if img.isNull():
        return False
    w, h = (img.width(), img.height())
    if w < _MIN_ICON_SIZE or h < _MIN_ICON_SIZE:
        return False
    if allow_non_square:
        return True
    aspect = w / h
    if aspect < 1 - _ICON_ASPECT_TOLERANCE or aspect > 1 + _ICON_ASPECT_TOLERANCE:
        return False
    return True

def _is_valid_tile_art(img: 'QImage') -> bool:
    if img.isNull():
        return False
    w, h = (img.width(), img.height())
    if min(w, h) < 200:
        return False
    aspect = w / h
    if aspect > 1.1:
        return False
    return True

@_network_limited
def _download_icon(title: str, dest_path: str, force: bool=False, exclude_hashes: set=None) -> str:
    if not force and os.path.exists(dest_path):
        return dest_path
    if not force:
        _wait_while_manual_priority_active()
    _exclude = exclude_hashes or set()
    override_urls = _ICON_URL_OVERRIDES.get(_normalize_title(title)) or []
    if override_urls:
        return dest_path if _save_override_image(override_urls, dest_path) else ''
    candidates = _steamgriddb_icon_candidates(title)
    if not candidates:
        candidates = _igdb_cover_candidates(title)
    if not candidates:
        for query in [f'{title} game icon square transparent png', f'{title} app icon']:
            try:
                candidates.extend(_multi_engine_image_candidates(query, shape='square', transparent=True, limit=25))
            except Exception:
                pass
    seen, uniq = (set(), [])
    for url, label in candidates:
        if url and url not in seen:
            seen.add(url)
            if _url_is_relevant(url, title):
                uniq.append((url, label))
    if not uniq:
        return ''
    best = None
    lock = threading.Lock()

    def _try(url, label):
        nonlocal best
        try:
            raw = _http_get_bytes(url, timeout=6)
        except Exception:
            return
        if len(raw) < 500:
            return
        if _exclude and hashlib.md5(raw).hexdigest() in _exclude:
            return
        img = QImage()
        if not img.loadFromData(raw):
            return
        if not _is_valid_game_icon(img, allow_non_square=label.startswith('IGDB')):
            return
        area = img.width() * img.height()
        with lock:
            if best is None or area > best[0]:
                best = (area, raw, img)
    with concurrent.futures.ThreadPoolExecutor(max_workers=min(16, len(uniq))) as ex:
        futs = [ex.submit(_try, u, l) for u, l in uniq]
        done, not_done = concurrent.futures.wait(futs, timeout=20)
        for f in not_done:
            f.cancel()
    if best is None:
        return ''
    os.makedirs(os.path.dirname(dest_path) or '.', exist_ok=True)
    ok = best[2].save(dest_path, 'PNG')
    if ok:
        _remember_download_src_hash(dest_path, best[1])
    return dest_path if ok else ''

