    # See _fetch_all_icon_candidates: trusted sources ranked ahead of
    # generic image-search scrapes, largest first within each tier.
    results.sort(key=lambda x: (x[0], x[1]), reverse=True)
    return [(area, raw, img) for _trusted, area, raw, img in results]

