def _is_plausible_logo_shape(img: 'QImage') -> bool:
    if img.isNull():
        return False
    w, h = (img.width(), img.height())
    if w < _MIN_LOGO_WIDTH or h <= 0:
        return False
    return w / h >= _MIN_LOGO_ASPECT
_LOGO_URL_HINT_RE = re.compile('logo|wordmark|titleart|title[-_]?art|namelogo', re.IGNORECASE)

def _url_suggests_logo(url: str) -> bool:
    return bool(_LOGO_URL_HINT_RE.search(url or ''))

def _fetch_all_logo_candidates(title: str, exclude_hashes: set=None, round_num: int=0) -> list:
    _exclude = exclude_hashes or set()
    # Manual overrides are already known-correct art, so they bypass the
    # transparency/shape gating that automated candidates go through, and
    # short-circuit the automated search entirely (same guarantee as
    # _save_override_image / _fetch_all_icon_candidates, now wired into
    # the candidate-list path that the UI's manual "browse logo
    # candidates" picker actually uses).
    #
    # IMPORTANT: once a title has an override list, this function must
    # NEVER fall through to the automated SteamGridDB/Wikimedia/web-search
    # path below, even if every override URL fails to fetch (dead link,
    # network hiccup, etc). Falling through defeats the entire point of
    # an override -- it's there specifically for titles where automated
    # search finds the wrong game/branding. A transient/dead override
    # should surface as "no candidates" (empty list), never as a silent
    # slide into a mismatched auto-search result, and never as just one
    # option competing for rank against unrelated scraped images.
    override_urls = _LOGO_URL_OVERRIDES.get(_normalize_title(title)) or []
    if override_urls:
        override_results = []
        for url in override_urls:
            try:
                raw = _http_get_bytes(url, timeout=10)
            except Exception:
                continue
            if not raw or len(raw) < 200:
                continue
            h = hashlib.md5(raw).hexdigest()
            if _exclude and h in _exclude:
                continue
            img = QImage()
            if not img.loadFromData(raw):
                continue
            override_results.append((img.width() * img.height(), raw, img))
        return override_results
    _transparent, _large_only = _logo_search_loosening(round_num)

    def _tag(fn, trusted: bool, query_scoped: bool=False):

        def _wrapped(t):
            return [(u, l, trusted, query_scoped) for u, l in fn(t) or []]
        return _wrapped
    jobs = [_tag(_steamgriddb_wordmark_candidates, True, False), _tag(_wikimedia_logo_candidates, True, False)]
    jobs += [_tag(lambda t, q=q: _transparent_wide_logo_candidates(q, transparent=_transparent, large_only=_large_only), False, True) for q in _name_logo_search_queries(title, round_num=round_num)]
    raw_candidates = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=len(jobs)) as ex:
        futs = [ex.submit(fn, title) for fn in jobs]
        done, not_done = concurrent.futures.wait(futs, timeout=25)
        for f in not_done:
            f.cancel()
        for fut in futs:
            if not fut.done():
                continue
            try:
                raw_candidates.extend(fut.result() or [])
            except Exception:
                pass
    seen, uniq = (set(), [])
    for url, label, trusted, query_scoped in raw_candidates:
        if url and url not in seen:
            seen.add(url)
            if trusted or _url_is_relevant(url, title):
                uniq.append((url, label, trusted))
    if not uniq:
        return []
    strict_results = []
    lock = threading.Lock()

    def _try(url, label, trusted):
        try:
            raw = _http_get_bytes(url, timeout=6)
        except Exception:
            return
        if len(raw) < 1000:
            return
        h = hashlib.md5(raw).hexdigest()
        if _exclude and h in _exclude:
            return
        img = QImage()
        if not img.loadFromData(raw):
            return
        # Name logos MUST have a transparent background -- no fallback to
        # "plausible shape + trusted/logo-ish URL" for opaque images. That
        # fallback used to accept anything wide-ish whose URL merely
        # contained the word "logo" (or came from a "trusted" source that
        # happened to only have a boxed/opaque version), which is exactly
        # how solid-background junk kept slipping through. If nothing here
        # is actually transparent, this round simply finds nothing and the
        # caller retries -- that's correct; a logo with a background is
        # not an acceptable result, not a "good enough" one.
        if not _is_valid_transparent_logo(img):
            return
        area = img.width() * img.height()
        with lock:
            strict_results.append((trusted, area, raw, img))
    with concurrent.futures.ThreadPoolExecutor(max_workers=min(16, len(uniq))) as ex:
        futs = [ex.submit(_try, u, l, t) for u, l, t in uniq]
        done, not_done = concurrent.futures.wait(futs, timeout=20)
        for f in not_done:
            f.cancel()
    results = strict_results
    # Trusted (SteamGridDB/Wikimedia) results first, largest first within
    # each tier -- see _is_trusted_source_label. This is the actual fix
    # for "have to reject dozens of candidates before the real logo shows
    # up": previously this only sorted by pixel area, so a huge unrelated
    # image scraped from Google/Bing/DDG could rank above the correct,
    # official-but-modest-resolution logo.
    results.sort(key=lambda x: (x[0], x[1]), reverse=True)
    return [(area, raw, img) for _trusted, area, raw, img in results]

@_network_limited
def _download_official_background(title: str, dest_path: str, exe_path: str='', only_labels: set=None, exclude_hashes: set=None) -> str:
    override = _manual_bg_override_candidates(title)
    if override:
        override_urls = [u for u, _label in override]
        if _save_override_image(override_urls, dest_path):
            return dest_path
        raise RuntimeError(f'Manual-Override background for "{title}" failed: could not download or decode any of the override URLs.')
    labels_to_use = only_labels if only_labels else _ENABLED_SOURCE_LABELS
    active = [(fn, label) for fn, label in _CANDIDATE_SOURCES if label in labels_to_use]
    all_candidates = []
    cusa_candidates = []
    reasons = []
    broken_sources = []
    lock = threading.Lock()
    cusa_id = _extract_cusa_id(exe_path, dest_path, title)
    if cusa_id:
        try:
            cusa_candidates = _ps4_cusa_candidate_urls(cusa_id) or []
        except Exception as e:
            pass

    def _lookup_one(fn, label):
        cands = []
        last_err = None
        for variant in _title_query_variants(title):
            try:
                cands = _cached_source_lookup(label, variant, fn)
            except urllib.error.HTTPError as e:
                last_err = f'HTTP error {e.code}'
                continue
            except urllib.error.URLError as e:
                last_err = f'internet connection dropped / request blocked ({e.reason})'
                continue
            except Exception as e:
                last_err = f'{type(e).__name__}: {e}'
                continue
            if cands:
                break
        with lock:
            if cands:
                all_candidates.extend(cands)
                _note_source_result(label, structural_failure=False)
            else:
                reasons.append(f"{label}: {last_err or 'game not found'}")
                _note_source_result(label, structural_failure=last_err is not None)
                if last_err is not None and _source_looks_broken(label):
                    broken_sources.append(label)
    if active:
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(16, len(active))) as ex:
            futs = [ex.submit(_lookup_one, fn, label) for fn, label in active]
            done, not_done = concurrent.futures.wait(futs, timeout=60)
            for f in not_done:
                f.cancel()
    all_candidates = [(u, l) for u, l in all_candidates if _url_is_relevant(u, title)]
    # PS4-CUSA Bing results have no game-title text in their search query
    # (just the CUSA id), so _url_is_relevant can't meaningfully vet them
    # against the title -- they're kept as a last-resort pool only, always
    # ranked below every title-matched/verified candidate above (see
    # _is_unverified_source_label). This is what used to let a generic
    # "PS4 console" photo win the pick for PS4 games.
    all_candidates.extend(cusa_candidates)
    if broken_sources:
        pass
    broken_note = f"\n⚠️ Warning: sources {', '.join(broken_sources)} have rejected several games in a row with the same error — likely a systemic failure/API change on that source's end, not that this particular game can't be found." if broken_sources else ''

    def _try_google_fallback(existing_candidates: list):
        try:
            g_candidates = _google_candidate_urls(title)
        except Exception as e:
            reasons.append(f'Google Images: {e}')
            return None
        g_candidates = [(u, l) for u, l in g_candidates if _url_is_relevant(u, title)]
        if not g_candidates:
            reasons.append('Google Images: no results found')
            return None
        ok, reason = _download_best_of_candidates(existing_candidates + g_candidates, dest_path, exclude_hashes=exclude_hashes)
        if ok:
            return dest_path
        why = _BEST_OF_CANDIDATES_REASON_FA.get(reason, 'Unknown reason')
        reasons.append(f'Google Images: found but not saved ({why})')
        return None
    if not all_candidates:
        result = _try_google_fallback([])
        if result:
            return result
        raise RuntimeError('Downloading the official image failed from all sources (Google Images was also tried as a last resort):\n' + '\n'.join(reasons) + broken_note)
    ok, reason = _download_best_of_candidates(all_candidates, dest_path, exclude_hashes=exclude_hashes)
    if ok:
        return dest_path
    result = _try_google_fallback(all_candidates)
    if result:
        return result
    why = _BEST_OF_CANDIDATES_REASON_FA.get(reason, 'Unknown reason')
    raise RuntimeError(f'The game was checked against {len(_CANDIDATE_SOURCES)} sources + Google Images and {len(all_candidates)} image link(s) were found, but none were saved: {why}.' + broken_note)

class _BackgroundDownloadWorker(QThread):
    finished_ok = pyqtSignal(str)
    failed = pyqtSignal(str)

    def __init__(self, title: str, dest_path: str, parent=None, store: str=None, exe_path: str='', exclude_hashes: set=None):
        super().__init__(parent)
        self._title = title
        self._dest_path = dest_path
        self._store = store
        self._exe_path = exe_path
        self._exclude_hashes = exclude_hashes

    def run(self):
        try:
            only_labels = None
            if self._store:
                entry = _CANDIDATE_SOURCES_BY_KEY.get(self._store)
                label = entry[1] if entry else self._store
                only_labels = {label}
            path = _download_official_background(self._title, self._dest_path, self._exe_path, only_labels=only_labels, exclude_hashes=self._exclude_hashes)
        except Exception as e:
            self.failed.emit(str(e))
            return
        self.finished_ok.emit(path)

class _SmartPreloadWorker(QThread):
    item_ready = pyqtSignal(object)
    item_failed = pyqtSignal(str, str)

    def __init__(self, apps, generation, parent=None):
        super().__init__(parent)
        self._apps = list(apps or [])
        self._generation = int(generation)
        self._cancelled = threading.Event()

    def cancel(self):
        self._cancelled.set()

    def run(self):
        seen = set()
        for app in self._apps:
            if self._cancelled.is_set():
                return
            title = str(app.get('title') or '')
            payload = {'generation': self._generation, 'title': title, 'metadata': {'exe': str(app.get('exe') or ''), 'emulator': _sanitize_export(app.get('emulator') or {}), 'safe_mode': str(app.get('safe_mode') or 'normal'), 'profile_schema_version': int(app.get('profile_schema_version', GAME_PROFILE_SCHEMA) or GAME_PROFILE_SCHEMA)}, 'images': {}}
            for kind, key in (('cover', 'icon'), ('cover', 'cover'), ('background', 'background'), ('icon', 'icon')):
                path = str(app.get(key) or '')
                if not path or path in seen or (not os.path.isfile(path)):
                    continue
                seen.add(path)
                try:
                    reader = QImageReader(path)
                    reader.setAutoTransform(True)
                    image = reader.read()
                    if image.isNull():
                        raise ValueError(reader.errorString() or 'invalid image')
                    payload['images'][kind] = (path, image)
                except Exception as exc:
                    self.item_failed.emit(title, str(exc))
            self.item_ready.emit(payload)
_LAST_DOWNLOAD_SRC_HASH: dict = {}
_LAST_DOWNLOAD_SRC_HASH_LOCK = threading.Lock()

def _remember_download_src_hash(dest_path: str, raw: bytes):
    try:
        h = hashlib.md5(raw).hexdigest()
    except Exception:
        return
    with _LAST_DOWNLOAD_SRC_HASH_LOCK:
        _LAST_DOWNLOAD_SRC_HASH[dest_path] = h

def _pop_download_src_hash(dest_path: str) -> str:
    with _LAST_DOWNLOAD_SRC_HASH_LOCK:
        return _LAST_DOWNLOAD_SRC_HASH.pop(dest_path, None)

def _peek_download_src_hash(dest_path: str) -> str:
    with _LAST_DOWNLOAD_SRC_HASH_LOCK:
        return _LAST_DOWNLOAD_SRC_HASH.get(dest_path)
_MANUAL_DL_PRIORITY_LOCK = threading.Lock()
_MANUAL_DL_PRIORITY_COUNT = 0
_MANUAL_DL_PRIORITY_LAST_BEGIN = 0.0
_BG_QUEUE_MANUAL_DEFER_MAX_SECS = 60

def _manual_priority_begin():
    global _MANUAL_DL_PRIORITY_COUNT, _MANUAL_DL_PRIORITY_LAST_BEGIN
    with _MANUAL_DL_PRIORITY_LOCK:
        _MANUAL_DL_PRIORITY_COUNT += 1
        _MANUAL_DL_PRIORITY_LAST_BEGIN = time.time()

def _manual_priority_end():
    global _MANUAL_DL_PRIORITY_COUNT
    with _MANUAL_DL_PRIORITY_LOCK:
        _MANUAL_DL_PRIORITY_COUNT = max(0, _MANUAL_DL_PRIORITY_COUNT - 1)

def _manual_priority_active() -> bool:
    with _MANUAL_DL_PRIORITY_LOCK:
        return _MANUAL_DL_PRIORITY_COUNT > 0

def _manual_priority_watchdog_reset_if_stuck(max_idle_secs: float=180):
    global _MANUAL_DL_PRIORITY_COUNT
    with _MANUAL_DL_PRIORITY_LOCK:
        if _MANUAL_DL_PRIORITY_COUNT > 0 and time.time() - _MANUAL_DL_PRIORITY_LAST_BEGIN > max_idle_secs:
            _MANUAL_DL_PRIORITY_COUNT = 0

def _manual_priority_force_reset():
    global _MANUAL_DL_PRIORITY_COUNT
    with _MANUAL_DL_PRIORITY_LOCK:
        _MANUAL_DL_PRIORITY_COUNT = 0

def _wait_while_manual_priority_active(poll_secs: float=0.15, max_wait_secs: float=120):
    waited = 0.0
    while _manual_priority_active() and waited < max_wait_secs:
        time.sleep(poll_secs)
        waited += poll_secs

def _file_md5(path: str) -> str:
    h = hashlib.md5()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(65536), b''):
            h.update(chunk)
    return h.hexdigest()

def _asset_backup_path(path: str) -> str:
    return path + '.reject_backup'

def _backup_asset_file(path: str) -> bool:
    if path and os.path.exists(path):
        try:
            shutil.copy2(path, _asset_backup_path(path))
            return True
        except Exception:
            return False
    return False

def _restore_asset_backup(path: str):
    bak = _asset_backup_path(path)
    if os.path.exists(bak):
        try:
            shutil.move(bak, path)
            return
        except Exception:
            pass
    try:
        if os.path.exists(path):
            os.remove(path)
    except Exception:
        pass

def _discard_asset_backup(path: str):
    bak = _asset_backup_path(path)
    try:
        if os.path.exists(bak):
            os.remove(bak)
    except Exception:
        pass

class _MiniSpinner(QWidget):

    def __init__(self, parent=None, diameter: int=26, color: str='#8f9dff'):
        super().__init__(parent)
        self._angle = 0
        self._diameter = diameter
        self._color = QColor(color)
        self.setFixedSize(diameter, diameter)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground)
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._tick)
        self._timer.start(35)

    def _tick(self):
        self._angle = (self._angle + 18) % 360
        self.update()

    def stop(self):
        try:
            self._timer.stop()
        except Exception:
            pass
        self.hide()
        self.deleteLater()

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        track_pen = QPen(QColor(255, 255, 255, 40))
        track_pen.setWidth(3)
        p.setPen(track_pen)
        m = 4
        p.drawEllipse(m, m, self._diameter - 2 * m, self._diameter - 2 * m)
        pen = QPen(self._color)
        pen.setWidth(3)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(pen)
        p.drawArc(m, m, self._diameter - 2 * m, self._diameter - 2 * m, int(-self._angle * 16), int(100 * 16))
        p.end()
_ICON_PROVIDER_TLS = threading.local()
_ICON_CACHE: 'collections.OrderedDict' = collections.OrderedDict()
_ICON_CACHE_MAX = 384
_IMG_EXTS = {'.png', '.jpg', '.jpeg', '.bmp', '.gif', '.webp', '.ico', '.svg', '.tif', '.tiff', '.avif'}

def _decode_image_avif_via_pillow(path: str) -> 'QImage':
    try:
        from PIL import Image
    except ImportError:
        return QImage()
    try:
        import pillow_avif
    except ImportError:
        pass
    try:
        with Image.open(path) as im:
            im = im.convert('RGBA')
            w, h = (im.width, im.height)
            data = im.tobytes('raw', 'RGBA')
        qimg = QImage(data, w, h, QImage.Format.Format_RGBA8888)
        return qimg.copy()
    except Exception:
        return QImage()

def _decode_image_any_format(path: str) -> 'QImage':
    if not path:
        return QImage()
    ext = os.path.splitext(path)[1].lower()
    if ext == '.svg':
        if threading.current_thread() is not threading.main_thread():
            return _decode_svg_on_gui_thread(path)
        return _decode_svg_image(path)
    try:
        img = QImage(path)
    except Exception:
        img = QImage()
    if img.isNull() and ext == '.avif':
        img = _decode_image_avif_via_pillow(path)
    return img

def _decode_svg_on_gui_thread(path: str) -> 'QImage':
    # QSvgRenderer (فونت/متن و موتور رندر) روی thread غیر-GUI امن نیست؛
    # رندر را به thread اصلی می‌سپاریم و اینجا منتظر می‌مانیم.
    fut = concurrent.futures.Future()

    def _job():
        try:
            fut.set_result(_decode_svg_image(path))
        except BaseException as exc:
            try:
                fut.set_exception(exc)
            except Exception:
                pass
    try:
        _UI_INVOKER.invoke(_job)
        return fut.result(timeout=5.0)
    except Exception:
        return QImage()

def _decode_svg_image(path: str) -> 'QImage':
    if True:
        try:
            from PyQt6.QtSvg import QSvgRenderer
            renderer = QSvgRenderer(path)
            if not renderer.isValid():
                return QImage()
            size = renderer.defaultSize()
            if size.width() <= 0 or size.height() <= 0:
                size = QSize(512, 512)
            else:
                scale = 512 / max(size.width(), size.height())
                if scale < 1:
                    size = QSize(max(1, int(size.width() * scale)), max(1, int(size.height() * scale)))
            img = QImage(size, QImage.Format.Format_ARGB32_Premultiplied)
            img.fill(Qt.GlobalColor.transparent)
            painter = QPainter(img)
            renderer.render(painter)
            painter.end()
            return img
        except Exception:
            return QImage()

def _icon_provider() -> 'QFileIconProvider':
    # IMPORTANT: QFileIconProvider.icon() calls into Windows shell/COM
    # under the hood, and COM interfaces are apartment (thread) affine.
    # A single instance shared between the UI thread and the
    # icon-extract worker thread (which runs its own STA apartment --
    # see _icon_extract_thread_main) causes cross-apartment COM calls.
    # That poisons COM state on whichever thread touches it "wrong",
    # and surfaces later as RPC_E_WRONG_THREAD (0x8001010e) on the next
    # unrelated COM call from that thread -- e.g. QFileDialog's native
    # dialog on the UI thread. Fix: give each thread its own provider
    # instance (thread-local) instead of one global singleton.
    inst = getattr(_ICON_PROVIDER_TLS, 'inst', None)
    if inst is None:
        inst = QFileIconProvider()
        _ICON_PROVIDER_TLS.inst = inst
    return inst

# These small pixmap/icon caches were only ever touched from the UI
# thread until now. The dedicated icon-extraction thread introduced
# below also reads/writes them (via _get_prescaled_art), so every
# access goes through this lock to avoid concurrent-mutation
# corruption (e.g. move_to_end/popitem racing with another thread's
# get). RLock because _lru_put calls _enforce_cache_memory_limit,
# which needs the same lock.
_LRU_CACHE_LOCK = threading.RLock()

def _lru_get(cache: 'collections.OrderedDict', key):
    with _LRU_CACHE_LOCK:
        try:
            val = cache[key]
        except KeyError:
            return None
        cache.move_to_end(key)
        return val

# Running byte total per cache (keyed by id(cache)), kept in sync by
# _lru_put/_evict_cached_art/_evict_cached_bg_pixmap/_purge_all_caches
# below. This lets _total_cache_bytes() answer in O(number of caches)
# instead of O(total cached pixmaps) -- see _total_cache_bytes().
_CACHE_BYTE_TOTALS: dict = {}

def _lru_put(cache: 'collections.OrderedDict', key, value, max_size: int):
    with _LRU_CACHE_LOCK:
        cid = id(cache)
        old = cache.get(key)
        if old is not None:
            _CACHE_BYTE_TOTALS[cid] = _CACHE_BYTE_TOTALS.get(cid, 0) - _pixmap_bytes(old)
        cache[key] = value
        cache.move_to_end(key)
        _CACHE_BYTE_TOTALS[cid] = _CACHE_BYTE_TOTALS.get(cid, 0) + _pixmap_bytes(value)
        while len(cache) > max_size:
            _, evicted = cache.popitem(last=False)
            _CACHE_BYTE_TOTALS[cid] = _CACHE_BYTE_TOTALS.get(cid, 0) - _pixmap_bytes(evicted)
        _enforce_cache_memory_limit()

def _evict_cached_art(path: str):
    if not path:
        return
    with _LRU_CACHE_LOCK:
        for cache in (_ICON_CACHE, _ART_SCALED_CACHE, _TILE_ROUND_CACHE):
            cid = id(cache)
            for key in [k for k in cache if k[0] == path]:
                v = cache.pop(key, None)
                _CACHE_BYTE_TOTALS[cid] = _CACHE_BYTE_TOTALS.get(cid, 0) - _pixmap_bytes(v)

def _get_cached_pixmap(path: str, w: int, h: int) -> 'QPixmap':
    key = (path, w, h)
    cached = _lru_get(_ICON_CACHE, key)
    if cached is not None:
        return cached
    pix = QPixmap()
    if path:
        ext = os.path.splitext(path)[1].lower()
        if ext in _IMG_EXTS and os.path.exists(path):
            img = _decode_image_any_format(path)
            if not img.isNull():
                pix = QPixmap.fromImage(img)
        elif os.path.exists(path):
            icon = _icon_provider().icon(QFileInfo(path))
            sizes = icon.availableSizes()
            if sizes:
                best = max(sizes, key=lambda s: s.width() * s.height())
                pix = icon.pixmap(best)
            else:
                pix = icon.pixmap(w, h)
    _lru_put(_ICON_CACHE, key, pix, _ICON_CACHE_MAX)
    return pix
_ICON_PENDING: dict = {}

def _prefetch_pixmap_async(path: str, w: int, h: int, callback) -> bool:
    key = (path, w, h)
    cached = _lru_get(_ICON_CACHE, key)
    if cached is not None:
        callback(cached)
        return True
    ext = os.path.splitext(path)[1].lower() if path else ''
    if not path or not os.path.exists(path) or ext not in _IMG_EXTS:
        callback(_get_cached_pixmap(path, w, h))
        return True
    if key in _ICON_PENDING:
        _ICON_PENDING[key].append(callback)
        return False
    _ICON_PENDING[key] = [callback]

    def _worker():
        try:
            img = _decode_image_any_format(path)
            img = img if not img.isNull() else None
        except Exception:
            img = None

        def _finish():
            callbacks = _ICON_PENDING.pop(key, [])
            pix = QPixmap.fromImage(img) if img is not None else QPixmap()
            if not pix.isNull() and w > 0 and (h > 0):
                pix = pix.scaled(w, h, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
            _lru_put(_ICON_CACHE, key, pix, _ICON_CACHE_MAX)
            for cb in callbacks:
                try:
                    cb(pix)
                except Exception:
                    pass
        _UI_INVOKER.invoke(_finish)
    _IMAGE_DECODE_POOL.submit(_worker)
    return False
_ART_SCALED_CACHE: 'collections.OrderedDict' = collections.OrderedDict()
_ART_SCALED_CACHE_MAX = 384

def _trim_transparent_margins_img(img: 'QImage', alpha_threshold: int=12) -> 'QImage':
    if img.isNull():
        return img
    w, h = (img.width(), img.height())
    if w <= 0 or h <= 0:
        return img
    # Sample the alpha channel as raw bytes instead of calling
    # QImage.pixelColor() per sample. pixelColor() allocates a QColor
    # and goes through Qt's per-pixel accessor machinery, which for a
    # 128x128 sample grid means ~16k Python<->C++ calls -- easily a
    # visible stall when this runs synchronously on the UI thread.
    # Format_Alpha8 gives one alpha byte per pixel with a known stride,
    # so the same sampling loop becomes plain bytes indexing.
    try:
        alpha_img = img.convertToFormat(QImage.Format.Format_Alpha8)
        stride = alpha_img.bytesPerLine()
        ptr = alpha_img.constBits()
        ptr.setsize(stride * h)
        buf = bytes(ptr)
    except Exception:
        # Fall back to the slow-but-correct path if the fast conversion
        # ever fails on some platform/format combination.
        return _trim_transparent_margins_img_slow(img, alpha_threshold)
    max_samples = 128
    step_x = max(1, math.ceil(w / max_samples))
    step_y = max(1, math.ceil(h / max_samples))
    top = bottom = -1
    left, right = (w, -1)
    for y in range(0, h, step_y):
        row_off = y * stride
        for x in range(0, w, step_x):
            if buf[row_off + x] <= alpha_threshold:
                continue
            if top == -1:
                top = y
            bottom = max(bottom, y)
            left = min(left, x)
            right = max(right, x)
    for x, y in ((w - 1, 0), (w - 1, h - 1), (0, h - 1)):
        if buf[y * stride + x] > alpha_threshold:
            if top == -1:
                top = y
            bottom = max(bottom, y)
            left = min(left, x)
            right = max(right, x)
    if top == -1 or right < left:
        return img
    rect = QRect(left, top, right - left + 1, bottom - top + 1)
    if rect == QRect(0, 0, w, h):
        return img
    return img.copy(rect)

def _trim_transparent_margins_img_slow(img: 'QImage', alpha_threshold: int=12) -> 'QImage':
    """Original pixelColor()-based scan, kept only as a fallback for
    when the fast Format_Alpha8 path above can't be used."""
    w, h = (img.width(), img.height())
    max_samples = 128
    step_x = max(1, math.ceil(w / max_samples))
    step_y = max(1, math.ceil(h / max_samples))
    top = bottom = -1
    left, right = (w, -1)
    for y in range(0, h, step_y):
        for x in range(0, w, step_x):
            if img.pixelColor(x, y).alpha() <= alpha_threshold:
                continue
            if top == -1:
                top = y
            bottom = max(bottom, y)
            left = min(left, x)
            right = max(right, x)
    for x, y in ((w - 1, 0), (w - 1, h - 1), (0, h - 1)):
        if img.pixelColor(x, y).alpha() > alpha_threshold:
            if top == -1:
                top = y
            bottom = max(bottom, y)
            left = min(left, x)
            right = max(right, x)
    if top == -1 or right < left:
        return img
    rect = QRect(left, top, right - left + 1, bottom - top + 1)
    if rect == QRect(0, 0, w, h):
        return img
    return img.copy(rect)

def _trim_transparent_margins(pix: 'QPixmap', alpha_threshold: int=12) -> 'QPixmap':
    if pix.isNull():
        return pix
    trimmed = _trim_transparent_margins_img(pix.toImage(), alpha_threshold)
    return QPixmap.fromImage(trimmed)

def _get_prescaled_art(path: str, max_size: int) -> 'QPixmap':
    if not path:
        return QPixmap()
    key = (path, max_size)
    cached = _lru_get(_ART_SCALED_CACHE, key)
    if cached is not None:
        return cached
    raw = _get_cached_pixmap(path, max_size, max_size)
    if raw.isNull():
        _lru_put(_ART_SCALED_CACHE, key, raw, _ART_SCALED_CACHE_MAX)
        return raw
    raw.setDevicePixelRatio(1.0)
    raw = _trim_transparent_margins(raw)
    pre = raw.scaled(max_size, max_size, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
    _lru_put(_ART_SCALED_CACHE, key, pre, _ART_SCALED_CACHE_MAX)
    return pre
_ART_SCALED_PENDING: dict = {}

def _finish_prescaled_art(key, pixmap: 'QPixmap'):
    """Shared completion path for both branches of
    _get_prescaled_art_async below: caches the result and fires every
    on_ready callback that queued up while it was pending. Always
    invoked on the UI thread (see both branches below)."""
    callbacks = _ART_SCALED_PENDING.pop(key, [])
    _lru_put(_ART_SCALED_CACHE, key, pixmap, _ART_SCALED_CACHE_MAX)
    for cb in callbacks:
        try:
            cb(pixmap)
        except Exception:
            pass

# --- Dedicated background thread for shell icon extraction ---------
#
# The "no dedicated art, fall back to the file's own icon" path
# (typically pulling the icon straight off a .exe/.lnk via
# QFileIconProvider) turned out to just be slow on its own -- 0.4 to
# 1+ seconds per never-before-seen exe, presumably shell/AV overhead
# on first access. Deferring it by one event-loop tick (previous fix)
# stopped a whole scroll burst of these from stacking into one
# multi-second stall, but each individual call still blocked the UI
# thread for its own ~0.5-1s when it ran.
#
# Moving it off the UI thread is the actual fix, but it touches the
# Windows shell/COM, which is only safe to call from a thread that has
# COM initialized. So instead of spinning up a new thread per icon (or
# reusing the general-purpose image-decode pool), this uses one
# long-lived worker thread that initializes COM exactly once and
# processes extraction jobs from a queue for the lifetime of the app.
# All cache reads/writes it does go through _LRU_CACHE_LOCK (see
# above) since they're now shared with the UI thread. The actual
# QPixmap handoff back to the UI still only happens inside
# _finish_prescaled_art, invoked via _UI_INVOKER on the UI thread.
_ICON_EXTRACT_QUEUE: 'queue.Queue' = queue.Queue()
_ICON_EXTRACT_THREAD = None
_ICON_EXTRACT_THREAD_LOCK = threading.Lock()

# --- Raw Win32 icon extraction (no Qt objects touched off the GUI
# thread) --------------------------------------------------------
#
# Round 1 of this fix moved trimming/scaling/caching off the
# icon-extract thread but still called icon.pixmap()/.toImage() on
# it to get the raw art -- and the crash kept happening at the exact
# same paintEvent line. Turns out "a private, uncached QPixmap" isn't
# a safe exception: Qt's rule is that QPixmap/QIcon must never be
# constructed or touched on any thread but the GUI thread, period --
# there's no such thing as a safe one-off use elsewhere. So this
# thread no longer creates a QPixmap, QImage, or QIcon at all. It
# talks to Shell32/GDI32 directly via ctypes to pull the icon's raw
# pixel bytes, and hands those plain bytes back to the UI thread,
# which is the first and only place any Qt image object gets built.
class _ICONINFO(ctypes.Structure):
    _fields_ = [('fIcon', wintypes.BOOL), ('xHotspot', wintypes.DWORD), ('yHotspot', wintypes.DWORD), ('hbmMask', wintypes.HANDLE), ('hbmColor', wintypes.HANDLE)]

class _GDI_BITMAP(ctypes.Structure):
    _fields_ = [('bmType', wintypes.LONG), ('bmWidth', wintypes.LONG), ('bmHeight', wintypes.LONG), ('bmWidthBytes', wintypes.LONG), ('bmPlanes', wintypes.WORD), ('bmBitsPixel', wintypes.WORD), ('bmBits', wintypes.LPVOID)]

class _BITMAPINFOHEADER(ctypes.Structure):
    _fields_ = [('biSize', wintypes.DWORD), ('biWidth', wintypes.LONG), ('biHeight', wintypes.LONG), ('biPlanes', wintypes.WORD), ('biBitCount', wintypes.WORD), ('biCompression', wintypes.DWORD), ('biSizeImage', wintypes.DWORD), ('biXPelsPerMeter', wintypes.LONG), ('biYPelsPerMeter', wintypes.LONG), ('biClrUsed', wintypes.DWORD), ('biClrImportant', wintypes.DWORD)]

class _BITMAPINFO(ctypes.Structure):
    _fields_ = [('bmiHeader', _BITMAPINFOHEADER), ('bmiColors', wintypes.DWORD * 3)]

class _SHFILEINFOW(ctypes.Structure):
    _fields_ = [('hIcon', wintypes.HANDLE), ('iIcon', ctypes.c_int), ('dwAttributes', wintypes.DWORD), ('szDisplayName', ctypes.c_wchar * 260), ('szTypeName', ctypes.c_wchar * 80)]

_SHGFI_ICON = 0x000000100
_SHGFI_LARGEICON = 0x000000000

if os.name == 'nt':
    ctypes.windll.shell32.SHGetFileInfoW.restype = ctypes.c_void_p
    ctypes.windll.shell32.SHGetFileInfoW.argtypes = [wintypes.LPCWSTR, wintypes.DWORD, ctypes.POINTER(_SHFILEINFOW), wintypes.UINT, wintypes.UINT]
    ctypes.windll.user32.GetIconInfo.restype = wintypes.BOOL
    ctypes.windll.user32.GetIconInfo.argtypes = [wintypes.HANDLE, ctypes.POINTER(_ICONINFO)]
    ctypes.windll.gdi32.GetObjectW.restype = ctypes.c_int
    ctypes.windll.gdi32.GetObjectW.argtypes = [wintypes.HANDLE, ctypes.c_int, ctypes.c_void_p]
    ctypes.windll.gdi32.GetDIBits.restype = ctypes.c_int
    ctypes.windll.gdi32.GetDIBits.argtypes = [wintypes.HANDLE, wintypes.HANDLE, wintypes.UINT, wintypes.UINT, ctypes.c_void_p, ctypes.POINTER(_BITMAPINFO), wintypes.UINT]
    ctypes.windll.user32.DestroyIcon.restype = wintypes.BOOL
    ctypes.windll.user32.DestroyIcon.argtypes = [wintypes.HANDLE]
    ctypes.windll.gdi32.DeleteObject.restype = wintypes.BOOL
    ctypes.windll.gdi32.DeleteObject.argtypes = [wintypes.HANDLE]
    ctypes.windll.user32.GetDC.restype = wintypes.HANDLE
    ctypes.windll.user32.GetDC.argtypes = [wintypes.HANDLE]
    ctypes.windll.user32.ReleaseDC.restype = ctypes.c_int
    ctypes.windll.user32.ReleaseDC.argtypes = [wintypes.HANDLE, wintypes.HANDLE]

def _win32_extract_icon_rgba(path: str, max_size: int):
    """Runs on the icon-extract thread. Shell32/GDI32 only -- no Qt
    classes (QIcon/QPixmap/QImage) are touched here at all, so there's
    nothing for this thread to race with the UI thread's own pixmap
    work in paintEvent over. Returns (width, height, raw_bgra_bytes)
    or None. raw_bgra_bytes is a plain Python bytes object -- safe to
    hand to another thread -- laid out exactly as QImage.Format_ARGB32
    expects in memory on little-endian (BGRA byte order), so the UI
    thread can build the QImage directly from it with no conversion.
    """
    try:
        shinfo = _SHFILEINFOW()
        res = ctypes.windll.shell32.SHGetFileInfoW(path, 0, ctypes.byref(shinfo), ctypes.sizeof(shinfo), _SHGFI_ICON | _SHGFI_LARGEICON)
        if not res or not shinfo.hIcon:
            return None
        hicon = shinfo.hIcon
        try:
            iconinfo = _ICONINFO()
            if not ctypes.windll.user32.GetIconInfo(hicon, ctypes.byref(iconinfo)):
                return None
            hbm_color, hbm_mask = (iconinfo.hbmColor, iconinfo.hbmMask)
            try:
                if not hbm_color:
                    return None
                bmp = _GDI_BITMAP()
                if not ctypes.windll.gdi32.GetObjectW(hbm_color, ctypes.sizeof(bmp), ctypes.byref(bmp)):
                    return None
                w, h = (bmp.bmWidth, bmp.bmHeight)
                if w <= 0 or h <= 0 or w > 1024 or (h > 1024):
                    return None
                bmi = _BITMAPINFO()
                bmi.bmiHeader.biSize = ctypes.sizeof(_BITMAPINFOHEADER)
                bmi.bmiHeader.biWidth = w
                bmi.bmiHeader.biHeight = -h  # negative = top-down DIB
                bmi.bmiHeader.biPlanes = 1
                bmi.bmiHeader.biBitCount = 32
                bmi.bmiHeader.biCompression = 0  # BI_RGB
                buf = (ctypes.c_ubyte * (w * h * 4))()
                hdc = ctypes.windll.user32.GetDC(0)
                try:
                    if not ctypes.windll.gdi32.GetDIBits(hdc, hbm_color, 0, h, buf, ctypes.byref(bmi), 0):
                        return None
                finally:
                    ctypes.windll.user32.ReleaseDC(0, hdc)
                raw = bytes(buf)
                if not any(raw[3::4]):
                    # Older/legacy icons without real per-pixel alpha come
                    # back with an all-zero alpha channel here, which would
                    # render as fully invisible -- treat as opaque instead.
                    raw = bytearray(raw)
                    raw[3::4] = b'\xff' * (len(raw) // 4)
                    raw = bytes(raw)
                return (w, h, raw)
            finally:
                if hbm_color:
                    ctypes.windll.gdi32.DeleteObject(hbm_color)
                if hbm_mask:
                    ctypes.windll.gdi32.DeleteObject(hbm_mask)
        finally:
            ctypes.windll.user32.DestroyIcon(hicon)
    except Exception:
        return None

def _icon_extract_raw_image_fallback(path: str, max_size: int) -> 'QImage':
    """Non-Windows fallback only -- this app is Windows-only in
    practice (DualSense/XInput/hidapi throughout), so _win32_extract_
    icon_rgba above always handles the real Windows case. This exists
    solely so the thread doesn't hard-fail during off-Windows dev/
    testing. It IS still theoretically subject to the same off-GUI-
    thread QPixmap restriction described above; it's kept only as a
    last resort where the raw Win32 path isn't available at all."""
    if not path or not os.path.exists(path):
        return QImage()
    icon = _icon_provider().icon(QFileInfo(path))
    sizes = icon.availableSizes()
    if sizes:
        best = max(sizes, key=lambda s: s.width() * s.height())
        pix = icon.pixmap(best)
    else:
        pix = icon.pixmap(max_size, max_size)
    if pix.isNull():
        return QImage()
    return pix.toImage()

def _icon_extract_thread_main():
    if os.name == 'nt':
        try:
            ctypes.windll.ole32.CoInitializeEx(None, 0x2)  # COINIT_APARTMENTTHREADED
        except Exception:
            pass
    try:
        while True:
            job = _ICON_EXTRACT_QUEUE.get()
            if job is None:
                break
            path, max_size, key = job
            win32_rgba = None
            fallback_img = QImage()
            try:
                if os.name == 'nt' and path and os.path.exists(path):
                    win32_rgba = _win32_extract_icon_rgba(path, max_size)
                elif os.name != 'nt':
                    fallback_img = _icon_extract_raw_image_fallback(path, max_size)
            except Exception:
                win32_rgba = None
                fallback_img = QImage()

            def _finish(win32_rgba=win32_rgba, fallback_img=fallback_img, path=path, max_size=max_size, key=key):
                # First (and only) point any QImage/QPixmap is built
                # from this icon's pixels -- deliberately on the GUI
                # thread. See _win32_extract_icon_rgba's docstring.
                if win32_rgba is not None:
                    w, h, raw = win32_rgba
                    raw_img = QImage(raw, w, h, w * 4, QImage.Format.Format_ARGB32)
                    raw_img = raw_img.copy()  # detach before `raw` goes out of scope
                else:
                    raw_img = fallback_img
                if raw_img.isNull():
                    pre = QPixmap()
                else:
                    raw_pix = QPixmap.fromImage(raw_img)
                    _lru_put(_ICON_CACHE, (path, max_size, max_size), raw_pix, _ICON_CACHE_MAX)
                    trimmed = _trim_transparent_margins_img(raw_img)
                    pre = QPixmap.fromImage(trimmed)
                    pre.setDevicePixelRatio(1.0)
                    pre = pre.scaled(max_size, max_size, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
                _finish_prescaled_art(key, pre)
            _UI_INVOKER.invoke(_finish)
    finally:
        if os.name == 'nt':
            try:
                ctypes.windll.ole32.CoUninitialize()
            except Exception:
                pass

def _ensure_icon_extract_thread():
    global _ICON_EXTRACT_THREAD
    if _ICON_EXTRACT_THREAD is not None and _ICON_EXTRACT_THREAD.is_alive():
        return
    with _ICON_EXTRACT_THREAD_LOCK:
        if _ICON_EXTRACT_THREAD is not None and _ICON_EXTRACT_THREAD.is_alive():
            return
        _ICON_EXTRACT_THREAD = threading.Thread(target=_icon_extract_thread_main, name='icon-extract', daemon=True)
        _ICON_EXTRACT_THREAD.start()

def _get_prescaled_art_async(path: str, max_size: int, on_ready=None) -> 'QPixmap':
    if not path:
        return QPixmap()
    key = (path, max_size)
    cached = _lru_get(_ART_SCALED_CACHE, key)
    if cached is not None:
        return cached
    if not os.path.exists(path):
        # Nothing to decode -- resolving this synchronously is cheap
        # (no disk I/O, no decode), unlike the two cases below.
        result = _get_prescaled_art(path, max_size)
        if on_ready is not None:
            try:
                on_ready(result)
            except Exception:
                pass
        return result
    if key in _ART_SCALED_PENDING:
        if on_ready is not None:
            _ART_SCALED_PENDING[key].append(on_ready)
        return QPixmap()
    _ART_SCALED_PENDING[key] = [on_ready] if on_ready is not None else []

    ext = os.path.splitext(path)[1].lower()
    if ext in _IMG_EXTS:
        # Plain image file (box art, cached thumbnail, etc.) -- decode
        # and scale off the UI thread. QImage work is thread-safe; the
        # QPixmap itself only gets built back on the UI thread in
        # _finish, same as before.
        def _worker():
            try:
                img = _decode_image_any_format(path)
                if img.isNull():
                    img = None
                else:
                    img = _trim_transparent_margins_img(img)
                    img = img.scaled(max_size, max_size, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
            except Exception:
                img = None

            def _finish():
                pre = QPixmap.fromImage(img) if img is not None else QPixmap()
                if not pre.isNull():
                    pre.setDevicePixelRatio(1.0)
                _finish_prescaled_art(key, pre)
            _UI_INVOKER.invoke(_finish)
        _IMAGE_DECODE_POOL.submit(_worker)
    else:
        # Non-standard extension -- the icon-extraction case described
        # above. Hand it to the dedicated COM-initialized thread
        # instead of running it on the UI thread at all.
        _ensure_icon_extract_thread()
        _ICON_EXTRACT_QUEUE.put((path, max_size, key))
    return QPixmap()

def _art_repaint_cb(widget):
    ref = weakref.ref(widget)

    def _cb(_pix):
        w = ref()
        if w is not None:
            try:
                w.update()
            except RuntimeError:
                pass
    return _cb

def _looks_like_circular_badge(pix: 'QPixmap') -> bool:
    img = pix.toImage()
    w, h = (img.width(), img.height())
    if w < 8 or h < 8:
        return False
    patch = max(2, min(6, w // 12, h // 12))

    def _avg(x0, y0):
        r = g = b = n = 0
        for dx in range(patch):
            for dy in range(patch):
                c = img.pixelColor(x0 + dx, y0 + dy)
                r += c.red()
                g += c.green()
                b += c.blue()
                n += 1
        return (r / n, g / n, b / n)
    corners = [_avg(0, 0), _avg(w - patch, 0), _avg(0, h - patch), _avg(w - patch, h - patch)]
    br, bg_, bb = corners[0]
    for r, g, b in corners[1:]:
        if abs(br - r) + abs(bg_ - g) + abs(bb - b) > 70:
            return False
    return True

def _crop_inner_square(pix: 'QPixmap', frac: float=0.72) -> 'QPixmap':
    w, h = (pix.width(), pix.height())
    side = max(1, int(min(w, h) * frac))
    x = (w - side) // 2
    y = (h - side) // 2
    return pix.copy(x, y, side, side)

def _rounded_pixmap(pix: 'QPixmap', radius: int) -> 'QPixmap':
    if pix.isNull():
        return pix
    w, h = (pix.width(), pix.height())
    if w <= 0 or h <= 0:
        return pix
    try:
        canvas = QImage(QSize(int(w), int(h)), QImage.Format.Format_ARGB32_Premultiplied)
    except TypeError:
        return pix
    canvas.fill(Qt.GlobalColor.transparent)
    p = QPainter(canvas)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    path = QPainterPath()
    path.addRoundedRect(0, 0, w, h, radius, radius)
    p.setClipPath(path)
    p.drawPixmap(0, 0, pix)
    p.end()
    return QPixmap.fromImage(canvas)

def _scale_crop_to_rect(pix: 'QPixmap', width: int, height: int) -> 'QPixmap':
    if pix.isNull() or width <= 0 or height <= 0:
        return pix
    w, h = (pix.width(), pix.height())
    if w <= 0 or h <= 0:
        return pix
    scale = max(width / w, height / h)
    sw = max(1, round(w * scale))
    sh = max(1, round(h * scale))
    scaled = pix.scaled(sw, sh, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.FastTransformation)
    x = min(max(0, (scaled.width() - width) // 2), max(0, scaled.width() - width))
    y = min(max(0, (scaled.height() - height) // 2), max(0, scaled.height() - height))
    out = QPixmap(width, height)
    out.fill(Qt.GlobalColor.transparent)
    p = QPainter(out)
    p.drawPixmap(0, 0, scaled, x, y, width, height)
    p.end()
    return out

_SCALE_CROP_CACHE: 'collections.OrderedDict' = collections.OrderedDict()
_SCALE_CROP_CACHE_MAX = 192

def _scale_crop_to_rect_cached(pix: 'QPixmap', width: int, height: int) -> 'QPixmap':
    """Bucketed cache around _scale_crop_to_rect for widgets that call it
    every repaint during a size animation (e.g. a tile growing/shrinking
    on selection), so consecutive animation frames of nearly the same
    size reuse one scaled pixmap instead of rescaling from scratch."""
    if pix.isNull() or width <= 0 or height <= 0:
        return pix
    bucket_w = max(4, round(width / 4) * 4)
    bucket_h = max(4, round(height / 4) * 4)
    key = (pix.cacheKey(), bucket_w, bucket_h)
    cached = _lru_get(_SCALE_CROP_CACHE, key)
    if cached is not None:
        return cached
    result = _scale_crop_to_rect(pix, width, height)
    _lru_put(_SCALE_CROP_CACHE, key, result, _SCALE_CROP_CACHE_MAX)
    return result

def _scale_crop_to_square(pix: 'QPixmap', size: int) -> 'QPixmap':
    return _scale_crop_to_rect(pix, size, size)
_CORNER_RADIUS_FRACTION = 0.12
_CORNER_RADIUS_MIN = 6
_CORNER_RADIUS_MAX = 40
_BADGE_DETECT_CACHE: dict = {}
_TILE_ROUND_CACHE: 'collections.OrderedDict' = collections.OrderedDict()
_TILE_ROUND_CACHE_MAX = 384
_TILE_FADE_MASK_CACHE: 'collections.OrderedDict' = collections.OrderedDict()
_TILE_FADE_MASK_CACHE_MAX = 128

def _get_faded_tile_art(path: str, filled: 'QPixmap', img_w: int, img_h: int, fade_start: float) -> 'QImage':
    """Bottom-gradient-faded version of a selected tile's art, cached.

    The size animation on a selected tile repaints every frame (up to
    60x/sec) while img_w/img_h change continuously, and this used to
    rebuild the whole gradient mask (a fresh QImage alloc + composited
    QPainter pass) from scratch on every single frame. Bucketing the
    size the same way _get_rounded_tile_art does means most consecutive
    animation frames land on the same cache entry instead of repeating
    that work every repaint.
    """
    bucket_w = max(4, round(img_w / 4) * 4)
    bucket_h = max(4, round(img_h / 4) * 4)
    key = (path, filled.cacheKey(), bucket_w, bucket_h)
    cached = _lru_get(_TILE_FADE_MASK_CACHE, key)
    if cached is not None:
        return cached
    tmp = QImage(QSize(img_w, img_h), QImage.Format.Format_ARGB32_Premultiplied)
    tmp.fill(0)
    mp = QPainter(tmp)
    mp.drawPixmap(0, 0, filled)
    fade_y = int(img_h * fade_start)
    mg = QLinearGradient(0, fade_y, 0, img_h)
    mg.setColorAt(0.0, QColor(0, 0, 0, 255))
    mg.setColorAt(0.1, QColor(0, 0, 0, 244))
    mg.setColorAt(0.2, QColor(0, 0, 0, 215))
    mg.setColorAt(0.3, QColor(0, 0, 0, 174))
    mg.setColorAt(0.4, QColor(0, 0, 0, 128))
    mg.setColorAt(0.5, QColor(0, 0, 0, 81))
    mg.setColorAt(0.6, QColor(0, 0, 0, 40))
    mg.setColorAt(0.7, QColor(0, 0, 0, 11))
    mg.setColorAt(0.8, QColor(0, 0, 0, 0))
    mg.setColorAt(1.0, QColor(0, 0, 0, 0))
    mp.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationIn)
    mp.fillRect(0, fade_y, img_w, img_h - fade_y, QBrush(mg))
    mp.end()
    _lru_put(_TILE_FADE_MASK_CACHE, key, tmp, _TILE_FADE_MASK_CACHE_MAX)
    return tmp

def _looks_like_circular_badge_cached(pix: 'QPixmap') -> bool:
    if pix.isNull():
        return False
    key = pix.cacheKey()
    cached = _BADGE_DETECT_CACHE.get(key)
    if cached is not None:
        return cached
    result = _looks_like_circular_badge(pix)
    _BADGE_DETECT_CACHE[key] = result
    return result

def _get_rounded_tile_art(path: str, pix: 'QPixmap', tile_sz: int, crop_badge: bool=False) -> 'QPixmap':
    if pix.isNull() or tile_sz <= 0:
        return pix
    bucket = max(4, round(tile_sz / 4) * 4)
    key = (path, bucket, crop_badge)
    cached = _lru_get(_TILE_ROUND_CACHE, key)
    if cached is not None:
        return cached
    is_badge = _looks_like_circular_badge_cached(pix)
    src = _crop_inner_square(pix, 0.72) if crop_badge and is_badge else pix
    filled = _scale_crop_to_square(src, bucket)
    filled = _round_corners_by_size(filled, already_round=is_badge)
    _lru_put(_TILE_ROUND_CACHE, key, filled, _TILE_ROUND_CACHE_MAX)
    return filled

def _already_has_round_corners(pix: 'QPixmap') -> bool:
    w, h = (pix.width(), pix.height())
    if w < 2 or h < 2:
        return False
    img = pix.toImage()
    corners = (img.pixelColor(0, 0), img.pixelColor(w - 1, 0), img.pixelColor(0, h - 1), img.pixelColor(w - 1, h - 1))
    return all((color.alpha() < 20 for color in corners))

def _round_corners_by_size(pix: 'QPixmap', already_round: bool=False) -> 'QPixmap':
    if pix.isNull():
        return pix
    w, h = (pix.width(), pix.height())
    if w <= 0 or h <= 0:
        return pix
    if already_round or _already_has_round_corners(pix):
        return pix
    radius = max(_CORNER_RADIUS_MIN, min(_CORNER_RADIUS_MAX, round(min(w, h) * _CORNER_RADIUS_FRACTION)))
    return _rounded_pixmap(pix, radius)
_BLUR_CACHE: 'collections.OrderedDict' = collections.OrderedDict()
_BLUR_CACHE_MAX = 96

def _blurred_pixmap(pix: 'QPixmap', radius: int=14) -> 'QPixmap':
    if pix.isNull():
        return pix
    key = (pix.cacheKey(), pix.width(), pix.height(), radius)
    cached = _lru_get(_BLUR_CACHE, key)
    if cached is not None:
        return cached
    scene = QGraphicsScene()
    item = QGraphicsPixmapItem(pix)
    effect = QGraphicsBlurEffect()
    effect.setBlurRadius(radius)
    item.setGraphicsEffect(effect)
    scene.addItem(item)
    result = QImage(pix.size(), QImage.Format.Format_ARGB32_Premultiplied)
    result.fill(Qt.GlobalColor.transparent)
    painter = QPainter(result)
    scene.render(painter, QRectF(0, 0, pix.width(), pix.height()), QRectF(0, 0, pix.width(), pix.height()))
    painter.end()
    blurred = QPixmap.fromImage(result)
    _lru_put(_BLUR_CACHE, key, blurred, _BLUR_CACHE_MAX)
    return blurred
_BG_PIXMAP_CACHE: 'collections.OrderedDict' = collections.OrderedDict()
_BG_PIXMAP_CACHE_MAX = 24
_CACHE_REGISTRY: list = [(_ICON_CACHE, 'icon'), (_ART_SCALED_CACHE, 'art_scaled'), (_TILE_ROUND_CACHE, 'tile_round'), (_BLUR_CACHE, 'blur'), (_BG_PIXMAP_CACHE, 'bg_pixmap')]
_CACHE_MEMORY_LIMIT_BYTES = 768 * 1024 * 1024

def _pixmap_bytes(pix) -> int:
    try:
        if pix is None or pix.isNull():
            return 0
        return pix.width() * pix.height() * 4
    except Exception:
        return 0

def _total_cache_bytes() -> int:
    # O(number of registered caches), not O(total cached pixmaps) --
    # this used to re-walk every pixmap in every cache on every single
    # _lru_put call (i.e. every time a new tile/icon got cached during
    # scrolling), which is what showed up in the freeze log as
    # multi-hundred-ms UI stalls inside paintEvent.
    return sum((_CACHE_BYTE_TOTALS.get(id(cache), 0) for cache, _label in _CACHE_REGISTRY))

def _set_cache_memory_limit_mb(mb):
    global _CACHE_MEMORY_LIMIT_BYTES
    try:
        mb = max(0, int(mb))
    except (TypeError, ValueError):
        mb = 0
    _CACHE_MEMORY_LIMIT_BYTES = mb * 1024 * 1024
    _enforce_cache_memory_limit()

def _enforce_cache_memory_limit():
    with _LRU_CACHE_LOCK:
        limit = _CACHE_MEMORY_LIMIT_BYTES
        if not limit:
            return
        total = _total_cache_bytes()
        guard = 0
        while total > limit and guard < 200000:
            guard += 1
            evicted_any = False
            for cache, _label in _CACHE_REGISTRY:
                if not cache:
                    continue
                _, v = cache.popitem(last=False)
                b = _pixmap_bytes(v)
                total -= b
                _CACHE_BYTE_TOTALS[id(cache)] = _CACHE_BYTE_TOTALS.get(id(cache), 0) - b
                evicted_any = True
                if total <= limit:
                    break
            if not evicted_any:
                break

_BG_VIDEO_EXTS = ('.mp4', '.mov', '.mkv', '.webm', '.avi', '.m4v', '.wmv')

def _is_video_bg_path(path: str) -> bool:
    return bool(path) and os.path.splitext(path)[1].lower() in _BG_VIDEO_EXTS

def _purge_all_caches():
    with _LRU_CACHE_LOCK:
        for cache, _label in _CACHE_REGISTRY:
            cache.clear()
            _CACHE_BYTE_TOTALS[id(cache)] = 0
        _BADGE_DETECT_CACHE.clear()

def _evict_cached_bg_pixmap(path: str):
    if path:
        with _LRU_CACHE_LOCK:
            v = _BG_PIXMAP_CACHE.pop(path, None)
            _CACHE_BYTE_TOTALS[id(_BG_PIXMAP_CACHE)] = _CACHE_BYTE_TOTALS.get(id(_BG_PIXMAP_CACHE), 0) - _pixmap_bytes(v)

def _get_cached_bg_pixmap(path: str) -> 'QPixmap':
    if not path or not os.path.exists(path):
        return QPixmap()
    cached = _lru_get(_BG_PIXMAP_CACHE, path)
    if cached is not None:
        return cached
    pix = QPixmap.fromImage(_decode_image_any_format(path))
    _lru_put(_BG_PIXMAP_CACHE, path, pix, _BG_PIXMAP_CACHE_MAX)
    return pix

class _UiInvoker(QObject):
    _sig = pyqtSignal(object)

    def __init__(self):
        super().__init__()
        self._sig.connect(self._run, Qt.ConnectionType.QueuedConnection)

    def invoke(self, fn):
        self._sig.emit(fn)

    @staticmethod
    def _run(fn):
        try:
            fn()
        except Exception as exc:
            try:
                import traceback
                with open(_asset_search_log_path(), 'a', encoding='utf-8') as log:
                    log.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] UI callback failed: {type(exc).__name__}: {exc}\n{traceback.format_exc()}\n")
            except Exception:
                pass
