SONY_VID = 1356
DUALSENSE_PIDS = {3302, 3570}
DUALSHOCK4_PIDS = {1476, 2508}
SONY_ALL_PIDS = DUALSENSE_PIDS | DUALSHOCK4_PIDS
_VENDOR_NAMES = {1118: 'Xbox', 1406: 'Nintendo', 11720: '8BitDo', 9414: 'PowerA', 8406: 'PowerA', 3695: 'PDP', 4152: 'SteelSeries', 1133: 'Logitech', 1356: 'Sony', 121: 'Generic USB', 2064: 'Generic USB'}
_NATIVE_XINPUT_VIDS = frozenset((1118, 3695, 9414, 8406, 5426, 11812, 5227))

def _brand_from_vid(vid: 'int | None') -> str:
    return _VENDOR_NAMES.get(vid, '')

def _looks_like_xinput_hid(item: dict) -> bool:
    """Return True for the HID-side mirror of an XInput controller.

    A controller exposed through ViGEm/another Xbox wrapper can appear twice:
    once through XInput and once as a generic HID collection.  Reading both
    collections and creating a virtual pad for each one makes every physical
    press reach the game twice.  The VID catches normal Xbox-compatible
    devices; the path markers cover virtual XUSB/ViGEm interfaces whose VID is
    not one of the known hardware vendors.
    """
    try:
        vid = int(item.get('vid', 0) or 0)
    except (TypeError, ValueError):
        vid = 0
    if vid in _NATIVE_XINPUT_VIDS:
        return True
    path = str(item.get('path', '') or '').upper()
    return any(marker in path for marker in ('&IG_', '#IG_', 'XUSB', 'VIGEMBUS'))
GENERIC_READ = 2147483648
FILE_SHARE_READ = 1
FILE_SHARE_WRITE = 2
OPEN_EXISTING = 3
DIGCF_PRESENT = 2
DIGCF_DEVICEIFACE = 16
INVALID_HANDLE = wintypes.HANDLE(-1).value
HIDP_STATUS_SUCCESS = 1114112
_DPAD = {0: (True, False, False, False), 1: (True, False, False, True), 2: (False, False, False, True), 3: (False, True, False, True), 4: (False, True, False, False), 5: (False, True, True, False), 6: (False, False, True, False), 7: (True, False, True, False), 8: (False, False, False, False)}


def _pid_from_path(path_upper: str) -> 'int | None':
    import re
    m = re.search('PID[_&]([0-9A-F]{4})', path_upper)
    if m:
        try:
            return int(m.group(1), 16)
        except ValueError:
            pass
    return None

def _hidapi_find_sony():
    # Same duplicate-collection issue as _hid_find_all_sony (see its
    # docstring): this was the path actually in effect whenever the
    # optional `hidapi` package is installed, since it's preferred over
    # the native Win32 fallback whenever it returns anything -- so fixing
    # only the native fallback previously left this one's duplicates
    # (deduped only by exact path, never by PID) still spawning a second
    # Xbox-emulation bridge for a second collection of the same physical
    # pad, still doubling every button press.
    if _bt_hid is None:
        return []
    try:
        devices = _bt_hid.enumerate(SONY_VID)
    except Exception as exc:
        return []
    raw = []
    seen = set()
    for item in devices or ():
        try:
            pid = int(item.get('product_id', 0) or 0)
        except (TypeError, ValueError):
            pid = 0
        if pid not in SONY_ALL_PIDS:
            continue
        usage_page = int(item.get('usage_page', 0) or 0)
        usage = int(item.get('usage', 0) or 0)
        input_size = int(item.get('max_input_report_size', 0) or 0)
        output_size = int(item.get('max_output_report_size', 0) or 0)
        raw_path = item.get('path')
        if not raw_path:
            continue
        explicit_gamepad = usage_page == 1 and usage in (4, 5)
        explicit_non_gamepad = usage_page not in (0, 1) or (usage_page == 1 and usage not in (4, 5))
        size_looks_like_gamepad = input_size >= 48 and output_size < 398
        if not explicit_gamepad and (explicit_non_gamepad or not size_looks_like_gamepad):
            continue
        path = raw_path if isinstance(raw_path, bytes) else os.fsencode(raw_path)
        if path in seen:
            continue
        seen.add(path)
        raw.append((path, pid, explicit_gamepad))
    by_pid = {}
    for path, pid, strict in raw:
        existing = by_pid.get(pid)
        if existing is None or (strict and not existing[2]):
            by_pid[pid] = (path, pid, strict)
    return [(path, pid) for path, pid, _strict in by_pid.values()]

class _HIDP_BUTTON_CAPS(ctypes.Structure):

    class _Range(ctypes.Structure):
        _fields_ = [('UsageMin', wintypes.USHORT), ('UsageMax', wintypes.USHORT), ('StringMin', wintypes.USHORT), ('StringMax', wintypes.USHORT), ('DesignatorMin', wintypes.USHORT), ('DesignatorMax', wintypes.USHORT), ('DataIndexMin', wintypes.USHORT), ('DataIndexMax', wintypes.USHORT)]
    _fields_ = [('UsagePage', wintypes.USHORT), ('ReportID', ctypes.c_ubyte), ('IsAlias', ctypes.c_ubyte), ('BitField', wintypes.USHORT), ('LinkCollection', wintypes.USHORT), ('LinkUsage', wintypes.USHORT), ('LinkUsagePage', wintypes.USHORT), ('IsRange', ctypes.c_ubyte), ('IsStringRange', ctypes.c_ubyte), ('IsDesignatorRange', ctypes.c_ubyte), ('IsAbsolute', ctypes.c_ubyte), ('Reserved', ctypes.c_ulong * 10), ('Range', _Range)]

class _HIDP_VALUE_CAPS(ctypes.Structure):

    class _Range(ctypes.Structure):
        _fields_ = [('UsageMin', wintypes.USHORT), ('UsageMax', wintypes.USHORT), ('StringMin', wintypes.USHORT), ('StringMax', wintypes.USHORT), ('DesignatorMin', wintypes.USHORT), ('DesignatorMax', wintypes.USHORT), ('DataIndexMin', wintypes.USHORT), ('DataIndexMax', wintypes.USHORT)]
    _fields_ = [('UsagePage', wintypes.USHORT), ('ReportID', ctypes.c_ubyte), ('IsAlias', ctypes.c_ubyte), ('BitField', wintypes.USHORT), ('LinkCollection', wintypes.USHORT), ('LinkUsage', wintypes.USHORT), ('LinkUsagePage', wintypes.USHORT), ('IsRange', ctypes.c_ubyte), ('IsStringRange', ctypes.c_ubyte), ('IsDesignatorRange', ctypes.c_ubyte), ('IsAbsolute', ctypes.c_ubyte), ('HasNull', ctypes.c_ubyte), ('Reserved1', ctypes.c_ubyte), ('BitSize', wintypes.USHORT), ('ReportCount', wintypes.USHORT), ('Reserved2', wintypes.USHORT * 5), ('UnitsExp', ctypes.c_ulong), ('Units', ctypes.c_ulong), ('LogicalMin', ctypes.c_long), ('LogicalMax', ctypes.c_long), ('PhysicalMin', ctypes.c_long), ('PhysicalMax', ctypes.c_long), ('Range', _Range)]
HIDP_INPUT = 0
GENERIC_DESKTOP_PAGE = 1
BUTTON_PAGE = 9
USAGE_HAT_SWITCH = 57
USAGE_X = 48
USAGE_Y = 49
_HAT = {0: (True, False, False, False), 1: (True, False, False, True), 2: (False, False, False, True), 3: (False, True, False, True), 4: (False, True, False, False), 5: (False, True, True, False), 6: (False, False, True, False), 7: (True, False, True, False)}

def _hid_open_preparsed(path):
    hid_dll = _HID_DLL
    k32 = _KERNEL32_DLL
    h = INVALID_HANDLE
    for access, flags in [(GENERIC_READ, 0), (GENERIC_READ, 1073741824), (0, 0)]:
        h = k32.CreateFileW(path, access, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, flags, None)
        if h != INVALID_HANDLE:
            break
    if h == INVALID_HANDLE:
        return None
    preparsed = ctypes.c_void_p(0)
    if not hid_dll.HidD_GetPreparsedData(h, ctypes.byref(preparsed)):
        k32.CloseHandle(h)
        return None
    caps = _HIDP_CAPS()
    if hid_dll.HidP_GetCaps(preparsed, ctypes.byref(caps)) != HIDP_STATUS_SUCCESS:
        hid_dll.HidD_FreePreparsedData(preparsed)
        k32.CloseHandle(h)
        return None
    return (h, preparsed, caps)

def _hid_generic_layout(preparsed):
    hid_dll = _HID_DLL
    layout = {'button_page': BUTTON_PAGE, 'button_min': 1, 'button_count': 16, 'has_hat': False, 'axes': {}}
    n = wintypes.USHORT(64)
    btn_caps = (_HIDP_BUTTON_CAPS * 64)()
    if hid_dll.HidP_GetButtonCaps(HIDP_INPUT, btn_caps, ctypes.byref(n), preparsed) == HIDP_STATUS_SUCCESS and n.value:
        layout['button_page'] = btn_caps[0].UsagePage
        layout['button_min'] = btn_caps[0].Range.UsageMin or 1
        layout['button_count'] = min(64, max(1, sum((int(c.Range.UsageMax) - int(c.Range.UsageMin) + 1 if c.IsRange else 1 for c in btn_caps[:n.value]))))
    n = wintypes.USHORT(64)
    val_caps = (_HIDP_VALUE_CAPS * 64)()
    if hid_dll.HidP_GetValueCaps(HIDP_INPUT, val_caps, ctypes.byref(n), preparsed) == HIDP_STATUS_SUCCESS:
        for i in range(n.value):
            vc = val_caps[i]
            u = vc.Range.UsageMin
            if vc.UsagePage != GENERIC_DESKTOP_PAGE:
                continue
            if u == USAGE_HAT_SWITCH:
                layout['has_hat'] = True
                layout['hat_max'] = vc.LogicalMax
                layout['hat_min'] = vc.LogicalMin
            elif u in (USAGE_X, USAGE_Y, 50, 51, 52, 53, 54, 55):
                layout['axes'].setdefault(u, []).append({'min': int(vc.LogicalMin), 'max': int(vc.LogicalMax), 'usage': u})
    if USAGE_X in layout['axes']:
        layout['has_stick'] = True
        layout['x_min'] = layout['axes'][USAGE_X][0]['min']
        layout['x_max'] = layout['axes'][USAGE_X][0]['max']
    if USAGE_Y in layout['axes']:
        layout['y_min'] = layout['axes'][USAGE_Y][0]['min']
        layout['y_max'] = layout['axes'][USAGE_Y][0]['max']
    return layout

def _hid_value(preparsed, report_buffer, reportlen, usage, layout):
    caps_list = layout.get('axes', {}).get(usage) or ()
    if not caps_list:
        return None
    raw = wintypes.ULONG(0)
    status = _HID_DLL.HidP_GetUsageValue(HIDP_INPUT, GENERIC_DESKTOP_PAGE, 0, usage, ctypes.byref(raw), preparsed, report_buffer, reportlen)
    if status != HIDP_STATUS_SUCCESS:
        return None
    cap = caps_list[0]
    lo, hi = (cap['min'], cap['max'])
    if hi <= lo:
        return 0.0
    value = max(lo, min(hi, int(raw.value)))
    return (value - lo) / float(hi - lo)

def _read_generic_state(preparsed, report_bytes, layout) -> dict:
    hid_dll = _HID_DLL
    buf = ctypes.create_string_buffer(report_bytes, len(report_bytes))
    reportlen = wintypes.ULONG(len(report_bytes))
    buttons: set = set()
    usages = (wintypes.USHORT * 64)()
    n = wintypes.ULONG(64)
    status = hid_dll.HidP_GetUsages(HIDP_INPUT, layout['button_page'], 0, usages, ctypes.byref(n), preparsed, buf, reportlen)
    if status == HIDP_STATUS_SUCCESS:
        idx_to_name = {0: 'cross', 1: 'circle', 2: 'square', 3: 'triangle', 4: 'l1', 5: 'r1', 6: 'back', 7: 'options', 8: 'l3', 9: 'r3', 10: 'ps'}
        base = layout['button_min']
        for i in range(n.value):
            idx = usages[i] - base
            name = idx_to_name.get(idx)
            if name:
                buttons.add(name)
    if layout.get('has_hat'):
        val = wintypes.ULONG(0)
        if hid_dll.HidP_GetUsageValue(HIDP_INPUT, GENERIC_DESKTOP_PAGE, 0, USAGE_HAT_SWITCH, ctypes.byref(val), preparsed, buf, reportlen) == HIDP_STATUS_SUCCESS:
            v = int(val.value) - int(layout.get('hat_min', 0))
            if v in _HAT:
                u, d, l, r = _HAT[v]
                if u:
                    buttons.add('up')
                if d:
                    buttons.add('down')
                if l:
                    buttons.add('left')
                if r:
                    buttons.add('right')

    def signed_axis(usage):
        normalized = _hid_value(preparsed, buf, reportlen, usage, layout)
        if normalized is None:
            return 0.0
        return max(-1.0, min(1.0, normalized * 2.0 - 1.0))
    lx = signed_axis(USAGE_X)
    ly = signed_axis(USAGE_Y)
    rx = signed_axis(51) if 51 in layout.get('axes', {}) else 0.0
    ry = signed_axis(52) if 52 in layout.get('axes', {}) else 0.0

    def trigger_value(usages_to_try):
        for usage in usages_to_try:
            normalized = _hid_value(preparsed, buf, reportlen, usage, layout)
            if normalized is None:
                continue
            caps = layout.get('axes', {}).get(usage, [{}])[0]
            if caps.get('min', 0) < 0:
                return max(0.0, min(1.0, normalized * 2.0 - 1.0))
            return max(0.0, min(1.0, normalized))
        return 0.0
    lt = trigger_value((50, 54))
    rt = trigger_value((53, 55))
    return {'buttons': frozenset(buttons), 'lx': lx, 'ly': ly, 'rx': rx, 'ry': ry, 'lt': lt, 'rt': rt}


def _stick_nav_from_lx(lx: float) -> frozenset:
    _STICK_NAV_DEADZONE = 0.47
    if lx <= -_STICK_NAV_DEADZONE:
        return frozenset({'l3_left'})
    if lx >= _STICK_NAV_DEADZONE:
        return frozenset({'l3_right'})
    return frozenset()

def _sony_report_payload(data: bytes) -> bytes:
    """Remove an optional zero byte that some HID backends prepend.

    hidapi normally returns the report ID as byte zero. A few Windows HID
    paths return a leading zero followed by the actual report, which otherwise
    shifts every stick/button/IMU offset by one byte.
    """
    if data and data[0] == 0 and len(data) > 1 and data[1] in (1, 17, 49):
        return data[1:]
    return data


def _parse_sony_state(data: bytes, pid: int) -> dict:
    if not data:
        return {}
    data = _sony_report_payload(data)
    rid = data[0]
    try:
        gyro_ax = accel_ax = None
        if rid == 49 and len(data) >= 8:
            result = {'lx': (data[2] - 128) / 127.0, 'ly': (data[3] - 128) / 127.0, 'rx': (data[4] - 128) / 127.0, 'ry': (data[5] - 128) / 127.0, 'lt': data[6] / 255.0, 'rt': data[7] / 255.0}
            if pid in DUALSENSE_PIDS and len(data) >= 29:
                gyro_ax, accel_ax = (17, 23)
        elif rid == 17 and len(data) >= 13:
            result = {'lx': (data[3] - 128) / 127.0, 'ly': (data[4] - 128) / 127.0, 'rx': (data[5] - 128) / 127.0, 'ry': (data[6] - 128) / 127.0, 'lt': data[11] / 255.0, 'rt': data[12] / 255.0}
            if len(data) >= 27:
                gyro_ax, accel_ax = (15, 21)
        elif rid == 1 and pid in DUALSENSE_PIDS and (len(data) >= 7):
            # Some Windows HID paths expose the Bluetooth packet with report
            # id 0x01 instead of 0x31.  It is still the Bluetooth layout:
            # one sequence byte precedes the four axes, triggers and buttons.
            # Treating it as the short USB layout shifts every value and
            # makes a connected controller appear unresponsive.
            if len(data) >= 78:
                result = {'lx': (data[2] - 128) / 127.0, 'ly': (data[3] - 128) / 127.0, 'rx': (data[4] - 128) / 127.0, 'ry': (data[5] - 128) / 127.0, 'lt': data[6] / 255.0, 'rt': data[7] / 255.0}
                gyro_ax, accel_ax = (17, 23)
            else:
                result = {'lx': (data[1] - 128) / 127.0, 'ly': (data[2] - 128) / 127.0, 'rx': (data[3] - 128) / 127.0, 'ry': (data[4] - 128) / 127.0, 'lt': data[5] / 255.0, 'rt': data[6] / 255.0}
                if len(data) >= 64:
                    gyro_ax, accel_ax = (16, 22)
        elif rid == 1 and len(data) >= 5:
            result = {'lx': (data[1] - 128) / 127.0, 'ly': (data[2] - 128) / 127.0, 'rx': (data[3] - 128) / 127.0, 'ry': (data[4] - 128) / 127.0, 'lt': data[3] / 255.0 if pid in DUALSHOCK4_PIDS else 0.0, 'rt': data[4] / 255.0 if pid in DUALSHOCK4_PIDS else 0.0}
            if pid in DUALSHOCK4_PIDS and len(data) >= 25:
                gyro_ax, accel_ax = (13, 19)
        else:
            return {}
        if gyro_ax is not None and accel_ax is not None:

            def _i16(offset):
                return int.from_bytes(data[offset:offset + 2], 'little', signed=True)
            gyro = [_i16(gyro_ax + i * 2) / 16.4 for i in range(3)]
            accel = [_i16(accel_ax + i * 2) / 8192.0 * 9.80665 for i in range(3)]
            result.update({'gyro_pitch': gyro[0], 'gyro_yaw': gyro[1], 'gyro_roll': gyro[2], 'accel_x': accel[0], 'accel_y': accel[1], 'accel_z': accel[2]})
        return result
    except (IndexError, TypeError):
        pass
    return {}

def _parse_sony_audio_presence(data: bytes, pid: int) -> dict:
    if not data or pid not in DUALSENSE_PIDS:
        return {}
    try:
        rid = data[0]
        if rid == 1 and len(data) >= 55:
            # A 78-byte report carrying id 0x01 is the Bluetooth layout.
            status1 = data[55] if len(data) >= 78 else data[54]
        elif rid == 49 and len(data) >= 56:
            status1 = data[55]
        else:
            return {}
        return {'headphone_connected': bool(status1 & 1), 'mic_connected': bool(status1 & 2)}
    except (IndexError, TypeError):
        return {}

def _parse_hid(data: bytes, pid: int) -> frozenset:
    if not data or len(data) < 2:
        return frozenset()
    rid = data[0]
    if rid == 0 and len(data) > 3 and (data[1] in (1, 17, 49)):
        return _parse_hid(data[1:], pid)
    buttons: set = set()
    try:
        b2 = 0
        if rid == 1:
            if pid in DUALSENSE_PIDS:
                if len(data) >= 78:
                    if len(data) < 8:
                        return frozenset()
                    # Bluetooth-sized DualSense packets can carry report id
                    # 0x01.  Keep the Bluetooth offsets in that case; the
                    # old code read trigger/axis bytes as the button bytes.
                    lx, ly = (data[2] - 128, data[3] - 128)
                    b0, b1 = (data[9], data[10])
                    b2 = data[11] if len(data) > 11 else 0
                else:
                    if len(data) < 10:
                        return frozenset()
                    lx, ly = (data[1] - 128, data[2] - 128)
                    b0, b1 = (data[8], data[9])
                    b2 = data[10] if len(data) > 10 else 0
            else:
                if len(data) < 8:
                    return frozenset()
                lx, ly = (data[1] - 128, data[2] - 128)
                b0, b1 = (data[5], data[6])
                b2 = data[7] if len(data) > 7 else 0
        elif rid == 49:
            if len(data) < 11:
                return frozenset()
            lx, ly = (data[2] - 128, data[3] - 128)
            b0, b1 = (data[9], data[10])
            b2 = data[11] if len(data) > 11 else 0
        elif rid == 17:
            if len(data) < 16:
                return frozenset()
            lx, ly = (data[3] - 128, data[4] - 128)
            b0, b1 = (data[13], data[14])
            b2 = data[15]
        else:
            return frozenset()
        if b0 & 16:
            buttons.add('square')
        if b0 & 32:
            buttons.add('cross')
        if b0 & 64:
            buttons.add('circle')
        if b0 & 128:
            buttons.add('triangle')
        if b2 & 1:
            buttons.add('ps')
        if b2 & 2:
            buttons.add('touchpad')
        if b2 & 4:
            buttons.add('mute')
        u, d, l, r = _DPAD.get(b0 & 15, (False,) * 4)
        if u:
            buttons.add('up')
        if d:
            buttons.add('down')
        if l:
            buttons.add('left')
        if r:
            buttons.add('right')
        if b1 & 1:
            buttons.add('l1')
        if b1 & 2:
            buttons.add('r1')
        if b1 & 64:
            buttons.add('l3')
        if b1 & 128:
            buttons.add('r3')
        if b1 & 16:
            buttons.add('back')
        if b1 & 32:
            buttons.add('options')
        _L2_THRESH = 128
        try:
            if rid == 1 and pid in DUALSENSE_PIDS:
                if len(data) >= 78:
                    if data[6] > _L2_THRESH:
                        buttons.add('l2')
                    if data[7] > _L2_THRESH:
                        buttons.add('r2')
                elif len(data) > 6:
                    if data[5] > _L2_THRESH:
                        buttons.add('l2')
                    if data[6] > _L2_THRESH:
                        buttons.add('r2')
            elif rid == 49 and len(data) > 7:
                if data[6] > _L2_THRESH:
                    buttons.add('l2')
                if data[7] > _L2_THRESH:
                    buttons.add('r2')
            elif rid == 17 and len(data) > 12:
                if data[11] > _L2_THRESH:
                    buttons.add('l2')
                if data[12] > _L2_THRESH:
                    buttons.add('r2')
            elif rid == 1 and len(data) > 4:
                if data[3] > _L2_THRESH:
                    buttons.add('l2')
                if data[4] > _L2_THRESH:
                    buttons.add('r2')
        except (IndexError, TypeError):
            pass
    except (IndexError, TypeError):
        return frozenset()
    return frozenset(buttons)

def _parse_battery_pct(data: bytes, pid: int) -> 'tuple[int, bool] | None':
    if not data or len(data) < 2:
        return None
    rid = data[0]

    def _split(byte_val: int) -> 'tuple[int, bool]':
        level = byte_val & 15
        status = byte_val >> 4 & 15
        pct = min(level * 10 + 5, 100) if status in (0, 1) else 100 if status == 2 else min(level * 10, 100)
        charging = status in (1, 2)
        return (pct, charging)
    try:
        if pid in DUALSENSE_PIDS:
            if rid == 49 and len(data) >= 55:
                return _split(data[54])
            elif rid == 1 and len(data) >= 64:
                return _split(data[54] if len(data) >= 78 else data[53])
        elif pid in DUALSHOCK4_PIDS:
            if rid == 17 and len(data) >= 32:
                return _split(data[30])
            elif rid == 1 and len(data) >= 32:
                return _split(data[30])
    except (IndexError, TypeError):
        pass
    return None

def _parse_touchpad(data: bytes, pid: int) -> 'list[tuple[int,int]]':
    if not data or pid not in DUALSENSE_PIDS:
        return []
    data = _sony_report_payload(data)
    rid = data[0]

    def _unpack_point(base: int) -> 'tuple[int,int] | None':
        if len(data) < base + 4:
            return None
        flags = data[base]
        inactive = bool(flags & 128)
        if inactive:
            return None
        x = data[base + 1] | (data[base + 2] & 15) << 8
        y = data[base + 2] >> 4 & 15 | data[base + 3] << 4
        if x > 1920 or y > 1080:
            return None
        return (x, y)
    contacts: list = []
    try:
        if rid == 1 and pid in DUALSENSE_PIDS:
            # Full Bluetooth reports are occasionally exposed with report ID
            # 0x01 instead of 0x31. They use the same touch layout as the
            # 0x31 report, one byte later than the short USB report.
            bases = (34, 38) if len(data) >= 78 else (33, 37)
            for base in bases:
                pt = _unpack_point(base)
                if pt is not None:
                    contacts.append(pt)
        elif rid == 49 and len(data) >= 42:
            for base in (34, 38):
                pt = _unpack_point(base)
                if pt is not None:
                    contacts.append(pt)
    except (IndexError, TypeError):
        pass
    return contacts

class _MOUSEINPUT(ctypes.Structure):
    _fields_ = [('dx', wintypes.LONG), ('dy', wintypes.LONG), ('mouseData', wintypes.DWORD), ('dwFlags', wintypes.DWORD), ('time', wintypes.DWORD), ('dwExtraInfo', ctypes.POINTER(ctypes.c_ulong))]

class _INPUT_UNION_TP(ctypes.Union):
    _fields_ = [('mi', _MOUSEINPUT)]

class _INPUT_TP(ctypes.Structure):
    _fields_ = [('type', wintypes.DWORD), ('_', _INPUT_UNION_TP)]
_INPUT_MOUSE_T = 0
_MOUSEEVENTF_MOVE = 1
_MOUSEEVENTF_LEFTDOWN = 2
_MOUSEEVENTF_LEFTUP = 4
_MOUSEEVENTF_RIGHTDOWN = 8
_MOUSEEVENTF_RIGHTUP = 16
_TP_MOUSE_SENSITIVITY: float = 1.8
_tp_cursor_shown: bool = False

def _tp_send_input(flags: int, dx: int=0, dy: int=0) -> None:
    try:
        inp = _INPUT_TP()
        inp.type = _INPUT_MOUSE_T
        inp._.mi.dx = int(dx)
        inp._.mi.dy = int(dy)
        inp._.mi.dwFlags = flags
        _USER32_DLL.SendInput(1, ctypes.byref(inp), ctypes.sizeof(inp))
    except Exception:
        pass








def _hid_output_report_len(h) -> 'int | None':
    preparsed = ctypes.c_void_p(0)
    if not _HID_DLL.HidD_GetPreparsedData(h, ctypes.byref(preparsed)):
        return None
    try:
        caps = _HIDP_CAPS()
        if _HID_DLL.HidP_GetCaps(preparsed, ctypes.byref(caps)) != HIDP_STATUS_SUCCESS:
            return None
        return caps.OutputReportByteLength
    finally:
        _HID_DLL.HidD_FreePreparsedData(preparsed)

def _ds_kick_full_report_mode(h, pid: int) -> None:
    try:
        out_len = _hid_output_report_len(h)
    except Exception:
        out_len = None
    try:
        if pid in DUALSHOCK4_PIDS:
            buf = ctypes.create_string_buffer(64)
            buf[0] = 2
            _HID_DLL.HidD_GetFeature(h, buf, 64)
        elif pid in DUALSENSE_PIDS and out_len and (out_len >= 78):
            import binascii as _bc
            kick = bytearray(out_len)
            kick[0] = 49
            kick[2] = 16
            crc = _bc.crc32(bytes([162]) + bytes(kick[:74])) & 4294967295
            kick[74] = crc & 255
            kick[75] = crc >> 8 & 255
            kick[76] = crc >> 16 & 255
            kick[77] = crc >> 24 & 255
            raw = (ctypes.c_ubyte * len(kick))(*kick)
            written = wintypes.DWORD(0)
            _KERNEL32_DLL.WriteFile(h, raw, len(kick), ctypes.byref(written), None)
    except Exception as exc:
        pass

def _ds_kick_full_report_mode_hidapi(device, pid: int) -> None:
    """hidapi equivalent of _ds_kick_full_report_mode. hidapi devices don't
    expose a Win32 HANDLE, so the WriteFile/HidD_* calls the native path
    uses aren't available here -- this sends the same output report via
    device.write() instead. Without this kick, some Bluetooth stacks leave
    the DualSense in its short/basic input report (buttons still work,
    but stick axes/gyro/touchpad stay at their zero default), which is why
    button-based features could look fine while anything reading
    lx/ly/rx/ry silently never left the deadzone."""
    if pid not in DUALSENSE_PIDS:
        return
    try:
        import binascii as _bc
        kick = bytearray(78)
        kick[0] = 49
        kick[2] = 16
        crc = _bc.crc32(bytes([162]) + bytes(kick[:74])) & 4294967295
        kick[74] = crc & 255
        kick[75] = crc >> 8 & 255
        kick[76] = crc >> 16 & 255
        kick[77] = crc >> 24 & 255
        device.write(bytes(kick))
    except Exception:
        pass

def _open_sony_rumble_handle(path: str):
    if not path:
        return (None, False)
    try:
        h = _KERNEL32_DLL.CreateFileW(path, 1073741824, 1 | 2, None, OPEN_EXISTING, 0, None)
        if h == INVALID_HANDLE:
            return (None, False)
        out_len = _hid_output_report_len(h)
        return (h, bool(out_len and out_len >= 78))
    except Exception:
        return (None, False)

def _send_sony_rumble(h, is_bt: bool, pid: int, sequence: int, right_motor: int, left_motor: int) -> int:
    if h in (None, INVALID_HANDLE):
        return sequence
    try:
        import binascii as _bc
        right_motor = max(0, min(255, int(right_motor)))
        left_motor = max(0, min(255, int(left_motor)))
        if is_bt:
            buf = bytearray(78)
            buf[0] = 17 if pid in DUALSHOCK4_PIDS else 49
            buf[1] = (sequence & 15) << 4
            buf[2] = 16
            buf[3] = 2
            buf[5] = right_motor
            buf[6] = left_motor
            crc = _bc.crc32(bytes([162]) + bytes(buf[:74])) & 4294967295
            buf[74] = crc & 255
            buf[75] = crc >> 8 & 255
            buf[76] = crc >> 16 & 255
            buf[77] = crc >> 24 & 255
            next_sequence = sequence + 1 & 15
        else:
            buf = bytearray(64)
            buf[0] = 2
            buf[1] = 2
            buf[3] = right_motor
            buf[4] = left_motor
            next_sequence = sequence
        raw = (ctypes.c_ubyte * len(buf))(*buf)
        written = wintypes.DWORD(0)
        _KERNEL32_DLL.WriteFile(h, raw, len(buf), ctypes.byref(written), None)
        return next_sequence
    except Exception as exc:
        return sequence
_TH32CS_SNAPPROCESS = 2

class _PROCESSENTRY32W(ctypes.Structure):
    _fields_ = [('dwSize', wintypes.DWORD), ('cntUsage', wintypes.DWORD), ('th32ProcessID', wintypes.DWORD), ('th32DefaultHeapID', ctypes.POINTER(ctypes.c_ulong)), ('th32ModuleID', wintypes.DWORD), ('cntThreads', wintypes.DWORD), ('th32ParentProcessID', wintypes.DWORD), ('pcPriClassBase', ctypes.c_long), ('dwFlags', wintypes.DWORD), ('szExeFile', ctypes.c_wchar * 260)]
_CONFLICTING_PROCESS_NAMES = {'steam.exe', 'ds4windows.exe', 'dsx.exe', 'dsxue.exe'}

def _running_conflicting_tool():
    try:
        snap = _KERNEL32_DLL.CreateToolhelp32Snapshot(_TH32CS_SNAPPROCESS, 0)
        if snap == INVALID_HANDLE:
            return None
        try:
            entry = _PROCESSENTRY32W()
            entry.dwSize = ctypes.sizeof(entry)
            if not _KERNEL32_DLL.Process32FirstW(snap, ctypes.byref(entry)):
                return None
            while True:
                name = entry.szExeFile.lower()
                if name in _CONFLICTING_PROCESS_NAMES:
                    return name
                if not _KERNEL32_DLL.Process32NextW(snap, ctypes.byref(entry)):
                    return None
        finally:
            _KERNEL32_DLL.CloseHandle(snap)
    except Exception as e:
        return None

def _process_running_by_name(exe_name: str) -> bool:
    target = (exe_name or '').lower()
    if not target:
        return False
    try:
        snap = _KERNEL32_DLL.CreateToolhelp32Snapshot(_TH32CS_SNAPPROCESS, 0)
        if snap == INVALID_HANDLE:
            return False
        try:
            entry = _PROCESSENTRY32W()
            entry.dwSize = ctypes.sizeof(entry)
            if not _KERNEL32_DLL.Process32FirstW(snap, ctypes.byref(entry)):
                return False
            while True:
                if entry.szExeFile.lower() == target:
                    return True
                if not _KERNEL32_DLL.Process32NextW(snap, ctypes.byref(entry)):
                    return False
        finally:
            _KERNEL32_DLL.CloseHandle(snap)
    except Exception as e:
        return False

def _capture_process_image_paths_by_names(exe_names: set[str]) -> dict[str, list[str]]:
    names = {str(name or '').lower() for name in (exe_names or set()) if str(name or '').strip()}
    found: dict[str, list[str]] = {}
    if os.name != 'nt' or not names:
        return found
    try:
        snap = _KERNEL32_DLL.CreateToolhelp32Snapshot(_TH32CS_SNAPPROCESS, 0)
        if snap == INVALID_HANDLE:
            return found
        try:
            entry = _PROCESSENTRY32W()
            entry.dwSize = ctypes.sizeof(entry)
            if not _KERNEL32_DLL.Process32FirstW(snap, ctypes.byref(entry)):
                return found
            seen: set[str] = set()
            while True:
                name = (entry.szExeFile or '').lower()
                if name in names:
                    full = _process_image_name(int(entry.th32ProcessID)) or ''
                    if full:
                        key = os.path.normcase(os.path.normpath(full))
                        if key not in seen:
                            found.setdefault(name, []).append(full)
                            seen.add(key)
                if not _KERNEL32_DLL.Process32NextW(snap, ctypes.byref(entry)):
                    return found
        finally:
            _KERNEL32_DLL.CloseHandle(snap)
    except Exception:
        return found


def _close_conflicting_controller_apps(allow_elevation_prompt: bool=True) -> list[str]:
    """Temporarily closes background apps that also hook the controller
    (Steam / DS4Windows / DSX / similar) so PS/Home and other buttons are
    seen only by this launcher while it is active. Returns executable paths
    that should be relaunched when the launcher exits."""
    target_names = {str(name or '').lower() for name in (_CONFLICTING_PROCESS_NAMES or set()) if str(name or '').strip()}
    if os.name != 'nt' or not target_names:
        return []
    relaunch_map = _capture_process_image_paths_by_names(target_names)
    closed_names: list[str] = []
    for exe_name in sorted(target_names):
        if not _process_running_by_name(exe_name):
            continue
        try:
            ok = force_kill_process_by_name(exe_name, timeout=3.0, allow_elevation_prompt=allow_elevation_prompt)
        except Exception:
            ok = False
        if ok or (not _process_running_by_name(exe_name)):
            closed_names.append(exe_name)
    relaunch_paths: list[str] = []
    seen_paths: set[str] = set()
    for exe_name in closed_names:
        for full in relaunch_map.get(exe_name, ()):
            if not full:
                continue
            key = os.path.normcase(os.path.normpath(full))
            if key in seen_paths:
                continue
            seen_paths.add(key)
            relaunch_paths.append(full)
    return relaunch_paths


def _find_any_new_process(exclude_names: set=None, min_start_time: float=None):
    """Process-table analogue of _find_any_foreground_window(), used as a
    fallback for watching shortcut (.lnk) launches whose real target exe
    name couldn't be pinned down. For .lnk launches, _launch_watch_exe
    comes from _resolve_lnk() parsing the shortcut ahead of time -- when
    that fails to find a usable target (unusual link layout, a target
    that no longer matches what actually ends up running, etc.) watch_exe
    silently fell back to the .lnk file's own name, which can never
    match a real running process. That meant _launch_exe_seen_alive could
    never become True, and the "game crashed/closed itself within the
    first few seconds" auto-relaunch (_poll_game_fullscreen ->
    _relaunch_after_early_exit) could never fire for that shortcut at
    all, no matter how many times it actually crashed. This scans the
    live process list (not windows -- an early crash by definition may
    never show one) for anything new, non-shell, and not the launcher
    itself, exactly like the existing window-matching fallback already
    does for handoff, and returns its (name, pid) so the caller can
    adopt it as the real watch_exe empirically instead of statically."""
    exclude = {n.lower() for n in exclude_names or ()}
    try:
        snap = _KERNEL32_DLL.CreateToolhelp32Snapshot(_TH32CS_SNAPPROCESS, 0)
        if snap == INVALID_HANDLE:
            return (None, None)
        try:
            entry = _PROCESSENTRY32W()
            entry.dwSize = ctypes.sizeof(entry)
            if not _KERNEL32_DLL.Process32FirstW(snap, ctypes.byref(entry)):
                return (None, None)
            while True:
                pid = entry.th32ProcessID
                name = (entry.szExeFile or '').lower()
                if pid and name and name not in exclude and (name not in _SHELL_PROCESS_NAMES) and (not _is_helper_process_pid(pid)) and (not _is_lossless_scaling_image_name(name)):
                    if min_start_time is None:
                        return (name, pid)
                    started = _process_start_time(pid)
                    if started is not None and started >= min_start_time - 1.0:
                        return (name, pid)
                if not _KERNEL32_DLL.Process32NextW(snap, ctypes.byref(entry)):
                    return (None, None)
        finally:
            _KERNEL32_DLL.CloseHandle(snap)
    except Exception:
        return (None, None)

def _hid_find_all_sony(collect_generic=None):
    # Collected as (path, pid, is_strict) and deduped by pid at the end --
    # a single DualSense/DualShock4 commonly exposes more than one HID
    # top-level collection (the real Generic-Desktop/Gamepad one, plus
    # vendor-defined collections used for the touchpad/gyro/lightbar on
    # some firmware/connection combos). Appending every collection as its
    # own "device" used to spawn one Xbox-emulation bridge per collection,
    # each independently mirroring the same physical button presses onto
    # its own virtual pad -- which is what made every press reach the game
    # twice while a controller was being emulated as Xbox. Only the
    # confident match (UsagePage 1 / Usage 4 or 5, i.e. Joystick/Gamepad)
    # is trusted when more than one collection is found for the same PID;
    # the looser fallback matches below exist only to avoid missing a
    # controller entirely on firmware where the confident match fails for
    # every one of its collections.
    raw = []
    try:
        hid_dll = _HID_DLL
        setupapi = _SETUPAPI_DLL
        kernel32 = _KERNEL32_DLL
        guid = _GUID()
        hid_dll.HidD_GetHidGuid(ctypes.byref(guid))
        hdevinfo = setupapi.SetupDiGetClassDevsW(ctypes.byref(guid), None, None, DIGCF_PRESENT | DIGCF_DEVICEIFACE)
        if hdevinfo == INVALID_HANDLE:
            return []
        iface = _SP_DEVICE_INTERFACE_DATA()
        iface.cbSize = ctypes.sizeof(iface)
        ptr_sz = ctypes.sizeof(ctypes.c_void_p)
        idx = 0
        seen_paths: set = set()
        while True:
            if not setupapi.SetupDiEnumDeviceInterfaces(hdevinfo, None, ctypes.byref(guid), idx, ctypes.byref(iface)):
                break
            idx += 1
            detail = _SP_DETAIL()
            detail.cbSize = 6 if ptr_sz == 4 else 8
            needed = wintypes.DWORD(0)
            setupapi.SetupDiGetDeviceInterfaceDetailW(hdevinfo, ctypes.byref(iface), ctypes.byref(detail), ctypes.sizeof(detail), ctypes.byref(needed), None)
            path = detail.DevicePath
            if not path:
                continue
            path_up = path.upper()
            is_sony_path = '054C' in path_up
            path_pid = _pid_from_path(path_up) if is_sony_path else None
            h = kernel32.CreateFileW(path, GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, 0, None)
            if h == INVALID_HANDLE:
                h = kernel32.CreateFileW(path, 0, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, 0, None)
                if h == INVALID_HANDLE:
                    if is_sony_path:
                        pid_guess = _pid_from_path(path_up)
                        if pid_guess and pid_guess in SONY_ALL_PIDS and (path not in seen_paths):
                            raw.append((path, pid_guess, False))
                            seen_paths.add(path)
                    continue
                attr = _HIDD_ATTRIBUTES()
                attr.Size = ctypes.sizeof(attr)
                hid_dll.HidD_GetAttributes(h, ctypes.byref(attr))
                kernel32.CloseHandle(h)
                effective_pid = attr.ProductID if attr.ProductID in SONY_ALL_PIDS else path_pid
                if (attr.VendorID == SONY_VID and attr.ProductID in SONY_ALL_PIDS or (is_sony_path and effective_pid in SONY_ALL_PIDS)) and path not in seen_paths:
                    raw.append((path, effective_pid, False))
                    seen_paths.add(path)
                elif is_sony_path:
                    pid_guess = _pid_from_path(path_up)
                    if pid_guess and pid_guess in SONY_ALL_PIDS and (path not in seen_paths):
                        raw.append((path, pid_guess, False))
                        seen_paths.add(path)
                continue
            try:
                attr = _HIDD_ATTRIBUTES()
                attr.Size = ctypes.sizeof(attr)
                hid_dll.HidD_GetAttributes(h, ctypes.byref(attr))
                effective_pid = attr.ProductID if attr.ProductID in SONY_ALL_PIDS else path_pid
                is_sony = attr.VendorID == SONY_VID and attr.ProductID in SONY_ALL_PIDS or (is_sony_path and effective_pid in SONY_ALL_PIDS)
                if not is_sony:
                    if collect_generic is not None and attr.VendorID != SONY_VID:
                        preparsed = ctypes.c_void_p(0)
                        if hid_dll.HidD_GetPreparsedData(h, ctypes.byref(preparsed)):
                            try:
                                caps = _HIDP_CAPS()
                                if hid_dll.HidP_GetCaps(preparsed, ctypes.byref(caps)) == HIDP_STATUS_SUCCESS and caps.UsagePage == 1 and (caps.Usage in (4, 5)):
                                    collect_generic.append({'path': path, 'vid': attr.VendorID, 'pid': attr.ProductID, 'usage': caps.Usage})
                            finally:
                                hid_dll.HidD_FreePreparsedData(preparsed)
                    continue
                preparsed = ctypes.c_void_p(0)
                if not hid_dll.HidD_GetPreparsedData(h, ctypes.byref(preparsed)):
                    if path not in seen_paths:
                        raw.append((path, effective_pid, False))
                        seen_paths.add(path)
                    continue
                caps = _HIDP_CAPS()
                status = hid_dll.HidP_GetCaps(preparsed, ctypes.byref(caps))
                hid_dll.HidD_FreePreparsedData(preparsed)
                if status != HIDP_STATUS_SUCCESS:
                    if path not in seen_paths:
                        raw.append((path, effective_pid, False))
                        seen_paths.add(path)
                    continue
                pg, us = (caps.UsagePage, caps.Usage)
                if pg == 1 and us in (4, 5):
                    if path not in seen_paths:
                        raw.append((path, effective_pid, True))
                        seen_paths.add(path)
                elif pg not in (12, 13):
                    if path not in seen_paths:
                        raw.append((path, effective_pid, False))
                        seen_paths.add(path)
            finally:
                kernel32.CloseHandle(h)
        setupapi.SetupDiDestroyDeviceInfoList(hdevinfo)
    except Exception as e:
        pass
    by_pid = {}
    for path, pid, strict in raw:
        existing = by_pid.get(pid)
        if existing is None or (strict and not existing[2]):
            by_pid[pid] = (path, pid, strict)
    return [(path, pid) for path, pid, _strict in by_pid.values()]

class GamepadWorker(QObject):
    button_pressed = pyqtSignal(str)
    home_pressed = pyqtSignal()
    pad_mute_pressed = pyqtSignal(str)
    controller_status = pyqtSignal(int)
    pad_list_changed = pyqtSignal(object)
    pad_battery_changed = pyqtSignal(object)
    controller_state = pyqtSignal(object)
    REPEAT_DELAY = 0.35
    REPEAT_RATE = 0.12
    _NAV = frozenset(('left', 'right', 'up', 'down', 'l3_left', 'l3_right'))
    _MUTE_DEBOUNCE_SEC = 0.15

    def __init__(self):
        super().__init__()
        self._running = False
        self._lock = threading.Lock()
        self._state_slots: dict = {}
        self._state_tokens: set = set()
        self._held: dict = {}
        self._evt_q: queue.SimpleQueue = queue.SimpleQueue()
        self._active_paths: set = set()
        self._path_pid: dict = {}
        self._active_generic: set = set()
        self._xinput_thread_alive = False
        self._pad_battery: dict = {}

    def _queue_controller_state(self, source: str, state: dict):
        with self._lock:
            self._state_slots[source] = state
            if source in self._state_tokens:
                return
            self._state_tokens.add(source)
        self._evt_q.put_nowait(('__state__', source))

    def start_polling(self):
        self._running = True
        last_count = -1
        while self._running:
            conflict_tool = _running_conflicting_tool()
            xinput_present = self._poll_xinput_check()
            virtual_xinput = bool(_virtual_xinput_emulation_active[0])
            if xinput_present and (not virtual_xinput) and (not self._xinput_thread_alive):
                brand = 'Xbox'
                if not conflict_tool:
                    tmp = []
                    _hid_find_all_sony(collect_generic=tmp)
                    if tmp:
                        brand = _brand_from_vid(tmp[0]['vid']) or brand
                via = f' via {conflict_tool}' if conflict_tool else ''
                t = threading.Thread(target=self._xinput_thread_body, name='GamepadWorker-xinput', daemon=True)
                self._xinput_thread_alive = True
                t.start()
            generic_candidates: list = []
            native_sony_devices = _hid_find_all_sony(collect_generic=generic_candidates)
            if xinput_present:
                # XInput wrappers also expose a generic HID/XUSB collection.
                # The XInput thread is the authoritative route for that
                # controller; otherwise the same press enters the queue twice.
                generic_candidates = [item for item in generic_candidates if not _looks_like_xinput_hid(item)]
            hidapi_sony_devices = _hidapi_find_sony()
            if hidapi_sony_devices:
                sony_devices = hidapi_sony_devices
            else:
                sony_devices = native_sony_devices
                if sony_devices:
                    pass
            for raw_path, pid in sony_devices:
                path = raw_path
                if isinstance(path, (bytes, bytearray)):
                    try:
                        path = path.decode('utf-8')
                    except Exception:
                        path = path.decode('latin-1', errors='replace')
                with self._lock:
                    already = path in self._active_paths
                if not already:
                    pid_name = 'DualSense' if pid in DUALSENSE_PIDS else 'DualShock 4'
                    with self._lock:
                        self._active_paths.add(path)
                        self._path_pid[path] = pid
                        self._held[path] = {}
                    use_hidapi = isinstance(raw_path, (bytes, bytearray))
                    t = threading.Thread(target=self._hidapi_thread_for if use_hidapi else self._hid_thread_for, args=(raw_path, pid), name=f"GamepadWorker-{('hidapi' if use_hidapi else 'hid')}", daemon=True)
                    t.start()
            for dev in generic_candidates:
                gpath = dev['path']
                with self._lock:
                    already = gpath in self._active_generic
                if not already:
                    with self._lock:
                        self._active_generic.add(gpath)
                        self._held[gpath] = {}
                    t = threading.Thread(target=self._generic_thread_for, args=(gpath,), name=f'GamepadWorker-generic-{gpath[-20:]}', daemon=True)
                    t.start()
            with self._lock:
                n_sony = len(self._active_paths)
                n_generic = len(self._active_generic)
                cur_list = list(self._path_pid.items())
            n_ctrl = n_sony + n_generic + (1 if self._xinput_thread_alive and not virtual_xinput else 0)
            if n_ctrl != last_count:
                last_count = n_ctrl
                self.controller_status.emit(n_ctrl)
            if cur_list != getattr(self, '_last_pad_list', None):
                self._last_pad_list = cur_list
                self.pad_list_changed.emit(cur_list)
            if n_ctrl == 0:
                nap_total = 0.5 if conflict_tool else 1.5
                slept = 0.0
                while self._running and slept < nap_total:
                    time.sleep(0.05)
                    slept += 0.05
                continue
            deadline = time.monotonic() + 1.5
            while self._running and time.monotonic() < deadline:
                try:
                    event, payload = self._evt_q.get(timeout=0.05)
                    # Drop events that were queued just before the virtual
                    # XInput route was disabled.  Without this small drain,
                    # one stale XInput press could still arrive alongside
                    # the authoritative physical-HID press.
                    if _virtual_xinput_emulation_active[0] and isinstance(payload, str) and payload.startswith('xinput:'):
                        continue
                    if event == '__battery__':
                        self.pad_battery_changed.emit(payload)
                    elif event == '__state__':
                        with self._lock:
                            state = self._state_slots.pop(payload, None)
                            self._state_tokens.discard(payload)
                        if state is not None:
                            self.controller_state.emit(state)
                    elif event == 'mute':
                        self.pad_mute_pressed.emit(payload.decode('utf-8', errors='replace') if isinstance(payload, (bytes, bytearray)) else payload)
                    elif event == '__rescan__':
                        break
                    else:
                        button = {'home': 'ps', 'guide': 'ps', 'xbox': 'ps'}.get(event, event)
                        if button == 'ps':
                            self.home_pressed.emit()
                        else:
                            self.button_pressed.emit(button)
                except queue.Empty:
                    pass

    def _hid_thread_for(self, path: str, pid: int):
        k32 = _KERNEL32_DLL
        FILE_FLAG_OVERLAPPED = 1073741824
        h = INVALID_HANDLE
        for access, flags in [(GENERIC_READ, 0), (GENERIC_READ, FILE_FLAG_OVERLAPPED), (0, 0)]:
            h = k32.CreateFileW(path, access, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, flags, None)
            if h != INVALID_HANDLE:
                break
        if h == INVALID_HANDLE:
            err = ctypes.get_last_error()
            with self._lock:
                self._active_paths.discard(path)
                self._held.pop(path, None)
                self._state_slots.pop(path, None)
                self._state_tokens.discard(path)
            return
        _ds_kick_full_report_mode(h, pid)
        buf = ctypes.create_string_buffer(256)
        rdw = wintypes.DWORD(0)
        prev = frozenset()
        mute_press_t = None
        mute_fired = False
        _tp_last: 'tuple[int,int] | None' = None
        _tp_prev_count: int = 0
        _tp1_accum_x: int = 0
        _tp1_accum_y: int = 0
        _tp2_accum_x: int = 0
        _TP_SWIPE_THRESHOLD: int = 150
        _TP_SWIPE_COOLDOWN: float = 0.2
        _tp1_last_t: float = 0.0
        _tp1_up_last_t: float = 0.0
        _tp2_last_t: float = 0.0
        try:
            while self._running:
                ok = k32.ReadFile(h, buf, 256, ctypes.byref(rdw), None)
                if not ok:
                    break
                if rdw.value == 0:
                    continue
                raw = buf.raw[:rdw.value]
                current = _parse_hid(raw, pid)
                touch_points = _parse_touchpad(raw, pid)
                state = dict(_parse_sony_state(raw, pid), **_parse_sony_audio_presence(raw, pid), touch_points=touch_points, buttons=list(current), type='DualSense' if pid in DUALSENSE_PIDS else 'DualShock 4', path=path, transport='Bluetooth' if _is_bluetooth_hid_path(path) else 'USB')
                self._queue_controller_state(path, state)
                now = time.time()
                nav_current = current | _stick_nav_from_lx(state.get('lx', 0.0))
                batt_info = _parse_battery_pct(raw, pid)
                if batt_info is not None:
                    with self._lock:
                        prev_batt = self._pad_battery.get(path)
                    if prev_batt != batt_info:
                        with self._lock:
                            self._pad_battery[path] = batt_info
                            batt_snap = [(p, pct, chg) for p, (pct, chg) in self._pad_battery.items()]
                        self._evt_q.put_nowait(('__battery__', batt_snap))
                with self._lock:
                    held = self._held.get(path, {})
                _tp_contacts = touch_points
                _tp_count = len(_tp_contacts)
                if _tp_contacts:
                    _tp_pos = _tp_contacts[0]
                    if _tp_count != _tp_prev_count:
                        _tp_last = _tp_pos
                        _tp1_accum_x = 0
                        _tp1_accum_y = 0
                        _tp2_accum_x = 0
                    if _tp_last is not None:
                        _dx = _tp_pos[0] - _tp_last[0]
                        _dy = _tp_pos[1] - _tp_last[1]
                        if abs(_dx) < 300:
                            if _tp_count == 1:
                                _tp1_accum_x += _dx
                                if abs(_tp1_accum_x) >= _TP_SWIPE_THRESHOLD:
                                    if now - _tp1_last_t >= _TP_SWIPE_COOLDOWN:
                                        _ev1 = 'tp_right' if _tp1_accum_x > 0 else 'tp_left'
                                        self._evt_q.put_nowait((_ev1, path))
                                        _tp1_last_t = now
                                    _tp1_accum_x = 0
                            elif _tp_count >= 2:
                                _tp2_accum_x += _dx
                                if abs(_tp2_accum_x) >= _TP_SWIPE_THRESHOLD:
                                    if now - _tp2_last_t >= _TP_SWIPE_COOLDOWN:
                                        _ev2 = 'tp2_right' if _tp2_accum_x > 0 else 'tp2_left'
                                        self._evt_q.put_nowait((_ev2, path))
                                        _tp2_last_t = now
                                    _tp2_accum_x = 0
                        if abs(_dy) < 300 and _tp_count == 1 and (abs(_dy) > abs(_dx) * 2):
                            _tp1_accum_y += _dy
                            if _tp1_accum_y <= -_TP_SWIPE_THRESHOLD:
                                if now - _tp1_up_last_t >= _TP_SWIPE_COOLDOWN:
                                    self._evt_q.put_nowait(('tp_launch', path))
                                    _tp1_up_last_t = now
                                _tp1_accum_y = 0
                            elif _tp1_accum_y >= _TP_SWIPE_THRESHOLD:
                                _tp1_accum_y = 0
                    _tp_last = _tp_pos
                    _tp_prev_count = _tp_count
                else:
                    _tp_last = None
                    _tp_prev_count = 0
                    _tp1_accum_x = 0
                    _tp1_accum_y = 0
                    _tp2_accum_x = 0
                for btn in nav_current - prev - {'mute'}:
                    self._evt_q.put_nowait((btn, path))
                if 'mute' in nav_current:
                    if mute_press_t is None:
                        mute_press_t = now
                    elif not mute_fired and now - mute_press_t >= self._MUTE_DEBOUNCE_SEC:
                        _haptic_failure('mute HOLD DETECTED path=%s -> queuing turn-off event', path)
                        self._evt_q.put_nowait(('mute', path))
                        mute_fired = True
                else:
                    mute_press_t = None
                    mute_fired = False
                for btn in nav_current & self._NAV:
                    if btn not in held:
                        held[btn] = (now, now)
                    else:
                        t0, tr = held[btn]
                        if now - t0 > self.REPEAT_DELAY and now - tr > self.REPEAT_RATE:
                            held[btn] = (t0, now)
                            self._evt_q.put_nowait((btn, path))
                for btn in list(held):
                    if btn not in nav_current:
                        del held[btn]
                with self._lock:
                    if path in self._held:
                        self._held[path] = held
                prev = nav_current
        except Exception as e:
            pass
        finally:
            k32.CloseHandle(h)
            with self._lock:
                self._active_paths.discard(path)
                self._path_pid.pop(path, None)
                self._held.pop(path, None)
                self._state_slots.pop(path, None)
                self._state_tokens.discard(path)
                had_batt = self._pad_battery.pop(path, None) is not None
                if had_batt:
                    batt_snap = [(p, pct, chg) for p, (pct, chg) in self._pad_battery.items()]
            if had_batt:
                self._evt_q.put_nowait(('__battery__', batt_snap))

    def _hidapi_thread_for(self, path, pid: int):
        if _bt_hid is None:
            return
        device = None
        _raw_path = path
        if isinstance(path, (bytes, bytearray)):
            try:
                path = path.decode('utf-8')
            except Exception:
                path = path.decode('latin-1', errors='replace')
        try:
            device = _bt_hid.device()
            device.open_path(_raw_path)
            try:
                device.set_nonblocking(False)
            except Exception:
                pass
            try:
                # Same physical DualSense exposes several HID collections
                # (input, audio, ...) each with its OWN hidapi `path`, but
                # they all share the same serial number -- use that to
                # correlate an input event with this pad's audio engine.
                _pad_serial = device.get_serial_number_string() or ''
            except Exception:
                _pad_serial = ''
            _remember_pad_serial(path, _pad_serial)
            _ds_kick_full_report_mode_hidapi(device, pid)
            prev = frozenset()
            _tp_last: 'tuple[int,int] | None' = None
            _tp_prev_count: int = 0
            _tp1_accum_x: int = 0
            _tp1_accum_y: int = 0
            _tp2_accum_x: int = 0
            _TP_SWIPE_THRESHOLD: int = 150
            _TP_SWIPE_COOLDOWN: float = 0.2
            _tp1_last_t: float = 0.0
            _tp1_up_last_t: float = 0.0
            _tp2_last_t: float = 0.0
            mute_press_t = None
            mute_fired = False
            while self._running:
                try:
                    raw = device.read(256, 1000)
                except TypeError:
                    raw = device.read(256)
                except OSError as e:
                    break
                if not raw:
                    continue
                raw = bytes(raw)
                current = _parse_hid(raw, pid)
                touch_points = _parse_touchpad(raw, pid)
                _sony_state = _parse_sony_state(raw, pid)
                self._queue_controller_state(path, dict(_sony_state, **_parse_sony_audio_presence(raw, pid), touch_points=touch_points, buttons=list(current), type='DualSense' if pid in DUALSENSE_PIDS else 'DualShock 4', path=path, serial=_pad_serial, transport='Bluetooth' if _is_bluetooth_hid_path(path) else 'USB'))
                now = time.time()
                nav_current = current | _stick_nav_from_lx(_sony_state.get('lx', 0.0))
                _tp_contacts = touch_points
                _tp_count = len(_tp_contacts)
                if _tp_contacts:
                    _tp_pos = _tp_contacts[0]
                    if _tp_count != _tp_prev_count:
                        _tp_last = _tp_pos
                        _tp1_accum_x = 0
                        _tp1_accum_y = 0
                        _tp2_accum_x = 0
                    if _tp_last is not None:
                        _dx = _tp_pos[0] - _tp_last[0]
                        _dy = _tp_pos[1] - _tp_last[1]
                        if abs(_dx) < 300:
                            if _tp_count == 1:
                                _tp1_accum_x += _dx
                                if abs(_tp1_accum_x) >= _TP_SWIPE_THRESHOLD:
                                    if now - _tp1_last_t >= _TP_SWIPE_COOLDOWN:
                                        _ev1 = 'tp_right' if _tp1_accum_x > 0 else 'tp_left'
                                        self._evt_q.put_nowait((_ev1, path))
                                        _tp1_last_t = now
                                    _tp1_accum_x = 0
                            elif _tp_count >= 2:
                                _tp2_accum_x += _dx
                                if abs(_tp2_accum_x) >= _TP_SWIPE_THRESHOLD:
                                    if now - _tp2_last_t >= _TP_SWIPE_COOLDOWN:
                                        _ev2 = 'tp2_right' if _tp2_accum_x > 0 else 'tp2_left'
                                        self._evt_q.put_nowait((_ev2, path))
                                        _tp2_last_t = now
                                    _tp2_accum_x = 0
                        if abs(_dy) < 300 and _tp_count == 1 and (abs(_dy) > abs(_dx) * 2):
                            _tp1_accum_y += _dy
                            if _tp1_accum_y <= -_TP_SWIPE_THRESHOLD:
                                if now - _tp1_up_last_t >= _TP_SWIPE_COOLDOWN:
                                    self._evt_q.put_nowait(('tp_launch', path))
                                    _tp1_up_last_t = now
                                _tp1_accum_y = 0
                            elif _tp1_accum_y >= _TP_SWIPE_THRESHOLD:
                                _tp1_accum_y = 0
                    _tp_last = _tp_pos
                    _tp_prev_count = _tp_count
                else:
                    _tp_last = None
                    _tp_prev_count = 0
                    _tp1_accum_x = 0
                    _tp1_accum_y = 0
                    _tp2_accum_x = 0
                for btn in nav_current - prev:
                    if btn != 'mute':
                        self._evt_q.put_nowait((btn, path))
                if 'mute' in nav_current:
                    if mute_press_t is None:
                        mute_press_t = now
                    elif not mute_fired and now - mute_press_t >= self._MUTE_DEBOUNCE_SEC:
                        _haptic_failure('mute HOLD DETECTED (hidapi) path=%s -> queuing turn-off event', path)
                        self._evt_q.put_nowait(('mute', path))
                        mute_fired = True
                else:
                    mute_press_t = None
                    mute_fired = False
                prev = nav_current
                batt_info = _parse_battery_pct(raw, pid)
                if batt_info is not None:
                    with self._lock:
                        prev_batt = self._pad_battery.get(path)
                    if prev_batt != batt_info:
                        with self._lock:
                            self._pad_battery[path] = batt_info
                            batt_snap = [(p, pct, chg) for p, (pct, chg) in self._pad_battery.items()]
                        self._evt_q.put_nowait(('__battery__', batt_snap))
        finally:
            try:
                if device is not None:
                    device.close()
            except Exception:
                pass
            with self._lock:
                self._active_paths.discard(path)
                self._path_pid.pop(path, None)
                self._held.pop(path, None)
                self._state_slots.pop(path, None)
                self._state_tokens.discard(path)
                had_batt = self._pad_battery.pop(path, None) is not None
                if had_batt:
                    batt_snap = [(p, pct, chg) for p, (pct, chg) in self._pad_battery.items()]
            if had_batt:
                self._evt_q.put_nowait(('__battery__', batt_snap))

    def _xinput_thread_body(self):
        if _XINPUT is None:
            self._xinput_thread_alive = False
            return
        state = _XI_STATE()
        _get_state = _XINPUT_EX if _XINPUT_EX is not None else _XINPUT.XInputGetState
        XI_BUTTON_MAP = {XI_A: 'cross', XI_B: 'circle', XI_X: 'square', XI_Y: 'triangle', XI_DPAD_UP: 'up', XI_DPAD_DOWN: 'down', XI_DPAD_LEFT: 'left', XI_DPAD_RIGHT: 'right', XI_START: 'options', XI_BACK: 'back', XI_LEFT_SHOULDER: 'l1', XI_RIGHT_SHOULDER: 'r1', XI_LEFT_THUMB: 'l3', XI_RIGHT_THUMB: 'r3', XI_GUIDE: 'ps'}
        port_held: dict = {p: {} for p in range(4)}
        try:
            while self._running:
                # A virtual Xbox pad is created from the same physical HID
                # reports that the worker already reads.  It belongs to the
                # game, not to launcher navigation, so stop this route as
                # soon as emulation becomes active.
                if _virtual_xinput_emulation_active[0]:
                    break
                any_found = False
                for port in range(4):
                    if _get_state(port, ctypes.byref(state)) != 0:
                        port_held[port] = {}
                        continue
                    any_found = True
                    gp = state.Gamepad
                    now = time.time()
                    current: set = set()
                    for mask, name in XI_BUTTON_MAP.items():
                        if gp.wButtons & mask:
                            current.add(name)
                    dpad_active = bool(gp.wButtons & (XI_DPAD_UP | XI_DPAD_DOWN | XI_DPAD_LEFT | XI_DPAD_RIGHT))
                    if not dpad_active:
                        if gp.sThumbLX > XI_DEADZONE:
                            current.add('right')
                        if gp.sThumbLX < -XI_DEADZONE:
                            current.add('left')
                        if gp.sThumbLY > XI_DEADZONE:
                            current.add('up')
                        if gp.sThumbLY < -XI_DEADZONE:
                            current.add('down')
                    if gp.bLeftTrigger > 128:
                        current.add('l2')
                    if gp.bRightTrigger > 128:
                        current.add('r2')
                    current = frozenset(current)
                    self._queue_controller_state(f'xinput:{port}', {'lx': max(-1.0, min(1.0, gp.sThumbLX / 32767.0)), 'ly': max(-1.0, min(1.0, -gp.sThumbLY / 32767.0)), 'rx': max(-1.0, min(1.0, gp.sThumbRX / 32767.0)), 'ry': max(-1.0, min(1.0, -gp.sThumbRY / 32767.0)), 'lt': gp.bLeftTrigger / 255.0, 'rt': gp.bRightTrigger / 255.0, 'buttons': list(current), 'type': 'Xbox/XInput', 'path': f'xinput:{port}', 'transport': 'XInput'})
                    held = port_held[port]
                    prev_f = frozenset(held.keys()) & current
                    for btn in current:
                        if btn not in held:
                            self._evt_q.put_nowait((btn, f'xinput:{port}'))
                            held[btn] = (now, now)
                    for btn in current & self._NAV:
                        if btn in held:
                            t0, tr = held[btn]
                            if now - t0 > self.REPEAT_DELAY and now - tr > self.REPEAT_RATE:
                                held[btn] = (t0, now)
                                self._evt_q.put_nowait((btn, f'xinput:{port}'))
                    for btn in list(held):
                        if btn not in current:
                            del held[btn]
                if not any_found:
                    break
                time.sleep(0.016)
        except Exception as e:
            pass
        finally:
            self._xinput_thread_alive = False
            with self._lock:
                for source in tuple(self._state_slots):
                    if str(source).startswith('xinput:'):
                        self._state_slots.pop(source, None)
                        self._state_tokens.discard(source)

    def _generic_thread_for(self, path: str):
        opened = _hid_open_preparsed(path)
        if not opened:
            with self._lock:
                self._active_generic.discard(path)
                self._held.pop(path, None)
                self._state_slots.pop(path, None)
                self._state_tokens.discard(path)
            return
        h, preparsed, caps = opened
        hid_dll = _HID_DLL
        k32 = _KERNEL32_DLL
        try:
            layout = _hid_generic_layout(preparsed)
            rpt_len = max(caps.InputReportByteLength, 1)
            buf = ctypes.create_string_buffer(rpt_len)
            rdw = wintypes.DWORD(0)
            prev = frozenset()
            while self._running:
                ok = k32.ReadFile(h, buf, rpt_len, ctypes.byref(rdw), None)
                if not ok:
                    break
                if rdw.value == 0:
                    continue
                generic_state = _read_generic_state(preparsed, buf.raw[:rdw.value], layout)
                current = frozenset(generic_state.get('buttons', ()))
                self._queue_controller_state(path, dict(generic_state, type='Generic HID', path=path, transport='Bluetooth' if _is_bluetooth_hid_path(path) else 'USB'))
                now = time.time()
                with self._lock:
                    held = self._held.get(path, {})
                for btn in current - prev:
                    self._evt_q.put_nowait((btn, path))
                for btn in current & self._NAV:
                    if btn not in held:
                        held[btn] = (now, now)
                    else:
                        t0, tr = held[btn]
                        if now - t0 > self.REPEAT_DELAY and now - tr > self.REPEAT_RATE:
                            held[btn] = (t0, now)
                            self._evt_q.put_nowait((btn, path))
                for btn in list(held):
                    if btn not in current:
                        del held[btn]
                with self._lock:
                    if path in self._held:
                        self._held[path] = held
                prev = current
        except Exception as e:
            pass
        finally:
            hid_dll.HidD_FreePreparsedData(preparsed)
            k32.CloseHandle(h)
            with self._lock:
                self._active_generic.discard(path)
                self._held.pop(path, None)
                self._state_slots.pop(path, None)
                self._state_tokens.discard(path)

    def _poll_xinput_check(self) -> bool:
        if _XINPUT is None:
            return False
        st = _XI_STATE()
        for port in range(4):
            if _XINPUT.XInputGetState(port, ctypes.byref(st)) == 0:
                return True
        return False

    def stop(self):
        self._running = False
        try:
            self._evt_q.put_nowait(('__stop__', ''))
        except Exception:
            pass

    def request_rescan(self):
        try:
            self._evt_q.put_nowait(('__rescan__', None))
        except Exception:
            pass

