import tempfile as _tempfile
_VGAMEPAD_INSTALL_LOCK = threading.Lock()
_VGAMEPAD_INSTALLING = False
_VGAMEPAD_INSTALL_ATTEMPTED = False
_VGAMEPAD_INSTALL_CALLBACKS = []

def _install_vgamepad_package():
    if os.name != 'nt':
        return (False, 'vgamepad is a Windows-only controller bridge.')
    interpreters = []
    if not getattr(sys, 'frozen', False):
        interpreters.append([sys.executable])
    for executable in ('py', 'python'):
        resolved = shutil.which(executable)
        if resolved:
            candidate = [resolved, '-3'] if executable == 'py' else [resolved]
            if candidate not in interpreters:
                interpreters.append(candidate)
    if not interpreters:
        return (False, 'No Python interpreter was found for automatic installation.')
    creationflags = getattr(subprocess, 'CREATE_NO_WINDOW', 0)
    errors = []
    for interpreter in interpreters:
        for user_scope in (True, False):
            command = interpreter + ['-m', 'pip', 'install', '--disable-pip-version-check', '--no-input']
            if user_scope:
                command.append('--user')
            command.append('vgamepad')
            try:
                result = subprocess.run(command, capture_output=True, text=True, timeout=300, check=False, creationflags=creationflags)
            except Exception as exc:
                errors.append(f'{type(exc).__name__}: {exc}')
                continue
            if result.returncode == 0:
                return (True, 'vgamepad was installed automatically.')
            detail = (result.stderr or result.stdout or '').strip()
            errors.append(f'exit {result.returncode}: {detail[-600:]}' if detail else f'exit {result.returncode}')
    return (False, 'Automatic vgamepad installation failed:\n' + '\n'.join(errors[-4:]))

def _refresh_vgamepad_import():
    global _vg, _vg_com, _VGAMEPAD_OK, _VGAMEPAD_IMPORT_ERROR
    global _VGAMEPAD_INSTALLED
    importlib.invalidate_caches()
    _vg, _vg_com, _VGAMEPAD_OK, _VGAMEPAD_IMPORT_ERROR = _try_import_vgamepad()
    _VGAMEPAD_INSTALLED = _VGAMEPAD_OK or importlib.util.find_spec('vgamepad') is not None
    return _VGAMEPAD_OK
_VIGEM_GITHUB_API = 'https://api.github.com/repos/nefarius/ViGEmBus/releases/latest'
_VIGEM_INSTALL_TIMEOUT = 180
CONTROLLER_PROFILES = ['auto', 'xbox360', 'xboxone', 'ps4', 'native', 'disabled']
CONTROLLER_PROFILE_LABELS = {'auto': 'Auto', 'xbox360': 'Xbox 360', 'xboxone': 'Xbox One', 'ps4': 'PlayStation 4', 'native': 'Native DualSense', 'disabled': 'Disabled'}
_CTRL_PROFILE_ICONS = {'auto': '🔄', 'xbox360': '🎮', 'xboxone': '🎮', 'ps4': '🕹️', 'native': '🟦', 'disabled': '🚫'}

class DriverManager:
    _instance = None

    def __init__(self):
        self._lock = threading.Lock()
        self._latest_ver: str = ''
        self._latest_url: str = ''
        self._cache_ts: float = 0.0

    @classmethod
    def instance(cls) -> 'DriverManager':
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    def is_installed(self) -> bool:
        try:
            import winreg
            k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, 'SYSTEM\\CurrentControlSet\\Services\\ViGEmBus')
            winreg.CloseKey(k)
            return True
        except Exception:
            pass
        if _VGAMEPAD_OK:
            try:
                pad = _vg.VX360Gamepad()
                del pad
                return True
            except Exception:
                pass
        return False

    def get_installed_version(self) -> 'str | None':
        try:
            import winreg
            k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, 'SOFTWARE\\Nefarius Software Solutions e.U.\\ViGEmBus')
            ver, _ = winreg.QueryValueEx(k, 'Version')
            winreg.CloseKey(k)
            return str(ver)
        except Exception:
            return None

    def fetch_latest_release(self, timeout: int=10) -> 'tuple[str, str] | None':
        now = time.time()
        with self._lock:
            if self._latest_ver and now - self._cache_ts < 3600:
                return (self._latest_ver, self._latest_url)
        try:
            req = urllib.request.Request(_VIGEM_GITHUB_API, headers={'User-Agent': _REAL_UA, 'Accept': 'application/vnd.github+json'})
            with urllib.request.urlopen(req, timeout=timeout) as r:
                data = json.loads(r.read().decode('utf-8', 'ignore'))
            tag = data.get('tag_name', '')
            assets = data.get('assets', [])
            url = None
            for asset in assets:
                name = asset.get('name', '').lower()
                if name.endswith('.exe') and ('setup' in name or 'install' in name):
                    url = asset.get('browser_download_url')
                    break
            if not url:
                for asset in assets:
                    if asset.get('name', '').lower().endswith('.exe'):
                        url = asset.get('browser_download_url')
                        break
            if not url or not tag:
                return None
            with self._lock:
                self._latest_ver = tag
                self._latest_url = url
                self._cache_ts = now
            return (tag, url)
        except Exception as e:
            return None

    def download_and_install(self, progress_cb=None, status_cb=None) -> bool:
        result = self.fetch_latest_release()
        if not result:
            if status_cb:
                status_cb('error', 'Cannot reach GitHub -- check internet connection')
            return False
        version, url = result
        if status_cb:
            status_cb('downloading', f'Downloading ViGEmBus {version}...')
        try:
            tmp_dir = _tempfile.mkdtemp(prefix='vigem_')
            installer_path = os.path.join(tmp_dir, 'ViGEmBusSetup.exe')
            req = urllib.request.Request(url, headers={'User-Agent': _REAL_UA})
            with urllib.request.urlopen(req, timeout=90) as r:
                total = int(r.headers.get('Content-Length') or 0)
                downloaded = 0
                with open(installer_path, 'wb') as f:
                    while True:
                        chunk = r.read(65536)
                        if not chunk:
                            break
                        f.write(chunk)
                        downloaded += len(chunk)
                        if progress_cb and total:
                            progress_cb(int(downloaded * 100 / total))
            if status_cb:
                status_cb('verifying', 'Verifying download...')
            if os.path.getsize(installer_path) < 50000:
                if status_cb:
                    status_cb('error', 'Downloaded file is too small -- possibly corrupt')
                return False
            if status_cb:
                status_cb('installing', 'Installer launched -- please approve the UAC prompt...')
            proc = subprocess.Popen([installer_path, '/quiet', '/norestart'], shell=False)
            deadline = time.time() + _VIGEM_INSTALL_TIMEOUT
            while time.time() < deadline:
                if proc.poll() is not None:
                    break
                if status_cb:
                    status_cb('installing', 'Waiting for installer to finish...')
                time.sleep(2)
            if proc.poll() is None:
                proc.wait(timeout=120)
            returncode = proc.returncode
            if returncode not in (0, None) and returncode != 3010:
                if status_cb:
                    reason = {1602: 'the UAC prompt was dismissed or cancelled', 1603: 'the installer reported a fatal error', 5: 'access was denied -- try running the launcher as Administrator'}.get(returncode, f'the installer exited with code {returncode}')
                    status_cb('error', f'Install failed -- {reason}')
                return False
            if self.is_installed():
                if status_cb:
                    status_cb('installed', f'ViGEmBus {version} installed!')
                return True
            else:
                if returncode == 3010:
                    if status_cb:
                        status_cb('error', 'ViGEmBus installed successfully but requires a reboot before it will be detected -- please restart your PC and check again')
                elif status_cb:
                    status_cb('error', "Installer finished but driver not detected -- a reboot may be required. If it's still missing after rebooting, check Device Manager under 'System devices' for a Nefarius Virtual USB Adapter entry with a warning icon")
                return False
        except Exception as e:
            if status_cb:
                status_cb('error', str(e))
            return False

