SAFE_MODE_OPTIONS = (('normal', 'Normal'), ('safe_controller', 'Safe Controller Mode'), ('no_controller_emulation', 'No Controller Emulation'), ('native_input_only', 'Native Input Only'), ('no_overlay', 'No Overlay'), ('minimal_services', 'Minimal Background Services'), ('compatibility', 'Compatibility Mode'))

def _safe_slug(value: str) -> str:
    value = re.sub('[^A-Za-z0-9._-]+', '_', str(value or '').strip())
    return value.strip('._')[:80] or 'game'

def _controller_device_key(path: str='', vid: int=0, pid: int=0, name: str='') -> str:
    path = str(path or '')
    return '|'.join((path, f'{int(vid or 0):04X}', f'{int(pid or 0):04X}', str(name or ''))).strip('|') or 'auto'

def _controller_profile_for(settings: dict, path: str='', vid: int=0, pid: int=0, name: str='') -> dict:
    profiles = (settings or {}).get('controller_profiles', {}) or {}
    exact = _controller_device_key(path, vid, pid, name)
    if exact in profiles:
        return dict(profiles[exact] or {})
    candidates = [_controller_device_key('', vid, pid, name), _controller_device_key('', vid, pid, ''), _controller_device_key('', 0, pid, name), _controller_device_key('', 0, 0, name)]
    for candidate in candidates:
        if candidate in profiles:
            return dict(profiles[candidate] or {})
    for profile in profiles.values():
        if not isinstance(profile, dict):
            continue
        if path and profile.get('path') == path:
            return dict(profile)
        if pid and int(profile.get('pid', 0) or 0) == int(pid):
            if not vid or int(profile.get('vid', 0) or 0) == int(vid):
                return dict(profile)
        if name and str(profile.get('name', '')).lower() == name.lower():
            return dict(profile)
    return {}

def _save_backup_root(app: dict, settings: dict) -> str:
    configured = str((app.get('save_backup') or {}).get('backup_dir') or settings.get('save_backup_root') or '').strip()
    if configured:
        root = os.path.expandvars(os.path.expanduser(configured))
    else:
        root = _managed_dir('save_backups')
    return os.path.join(root, _safe_slug(app.get('title') or 'game'))

def _save_source_root(app: dict, settings: dict) -> str:
    cfg = app.get('save_backup') or {}
    mode = str(cfg.get('path_mode') or 'auto').lower()
    manual = str(cfg.get('save_dir') or '').strip()
    if mode == 'manual' and manual:
        return os.path.expandvars(os.path.expanduser(manual))
    exe = str(app.get('exe') or '').strip()
    if mode in ('next_to_exe', 'auto') and exe:
        return os.path.dirname(os.path.abspath(exe))
    if mode == 'documents':
        return os.path.join(os.path.expanduser('~'), 'Documents')
    if mode == 'appdata':
        return _APP_DATA_DIR
    emu = app.get('emulator')
    if mode == 'emulator' and isinstance(emu, dict):
        p = str(emu.get('path') or '').strip()
        if p:
            return os.path.dirname(os.path.abspath(p))
    if mode == 'auto':
        for candidate in (os.path.join(os.path.expanduser('~'), 'Documents'), os.environ.get('APPDATA', ''), _APP_DATA_DIR):
            if candidate and os.path.isdir(candidate):
                return candidate
    return os.path.dirname(os.path.abspath(exe)) if exe else ''

def _iter_save_files(root: str) -> list:
    if not root or not os.path.isdir(root):
        return []
    ignored = {'.git', 'node_modules', '__pycache__', 'save_backups', 'bin', 'binaries', 'engine', 'content', 'pak', 'packages'}
    save_dir_names = {'save', 'saves', 'savedata', 'savegame', 'userdata', 'profiles', 'profile', 'config', 'configs', 'documents', 'settings'}
    found = []
    try:
        for base, dirs, files in os.walk(root):
            dirs[:] = [d for d in dirs if d not in ignored and (not d.startswith('.'))]
            for name in files:
                if name.lower().endswith(('.json', '.tmp', '.bak', '.log')):
                    if name.lower() in ('my_apps.json', 'statistics.json'):
                        continue
                path = os.path.join(base, name)
                try:
                    rel_parts = {part.lower() for part in os.path.relpath(path, root).split(os.sep)}
                    lower_name = name.lower()
                    is_save_named = any((token in lower_name for token in ('save', 'profile', 'userdata', 'settings', 'config')))
                    is_save_tree = bool(rel_parts & save_dir_names)
                    if os.path.isfile(path) and (is_save_tree or is_save_named):
                        if os.path.getsize(path) > 256 * 1024 * 1024:
                            continue
                        found.append(path)
                except OSError:
                    pass
    except OSError:
        return []
    return found

def _create_save_backup(app: dict, settings: dict, reason: str='manual') -> tuple:
    source = _save_source_root(app, settings)
    files = _iter_save_files(source)
    if not files:
        return (False, 'No save files were found in the configured location.')
    target = _save_backup_root(app, settings)
    os.makedirs(target, exist_ok=True)
    stamp = time.strftime('%Y%m%d_%H%M%S')
    final_path = os.path.join(target, f'{stamp}_{_safe_slug(reason)}.zip')
    tmp_path = final_path + '.tmp'
    try:
        compression = zipfile.ZIP_DEFLATED if bool((app.get('save_backup') or {}).get('compress', settings.get('save_backup_compress', True))) else zipfile.ZIP_STORED
        with zipfile.ZipFile(tmp_path, 'w', compression=compression) as archive:
            manifest = {'title': app.get('title', ''), 'source_root': source, 'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'), 'reason': reason, 'files': []}
            for path in files:
                try:
                    rel = os.path.relpath(path, source)
                    archive.write(path, rel)
                    manifest['files'].append({'path': rel, 'size': os.path.getsize(path)})
                except OSError:
                    continue
            archive.writestr('manifest.json', json.dumps(manifest, ensure_ascii=False, indent=2))
        os.replace(tmp_path, final_path)
        keep = max(1, int((app.get('save_backup') or {}).get('retention', settings.get('save_backup_keep_count', 10)) or 10))
        backups = sorted((os.path.join(target, p) for p in os.listdir(target) if p.lower().endswith('.zip')), key=lambda p: os.path.getmtime(p) if os.path.exists(p) else 0, reverse=True)
        for stale in backups[keep:]:
            try:
                os.remove(stale)
            except OSError:
                pass
        return (True, final_path)
    except Exception as exc:
        try:
            if os.path.exists(tmp_path):
                os.remove(tmp_path)
        except OSError:
            pass
        return (False, str(exc))

def _list_save_backups(app: dict, settings: dict) -> list:
    root = _save_backup_root(app, settings)
    try:
        return sorted([os.path.join(root, p) for p in os.listdir(root) if p.lower().endswith('.zip')], key=lambda p: os.path.getmtime(p), reverse=True)
    except OSError:
        return []

def _save_backup_info(path: str) -> dict:
    try:
        stat = os.stat(path)
        with zipfile.ZipFile(path, 'r') as archive:
            manifest = json.loads(archive.read('manifest.json').decode('utf-8'))
        return {'path': path, 'name': os.path.basename(path), 'created_at': manifest.get('created_at', ''), 'reason': manifest.get('reason', 'manual'), 'files': len(manifest.get('files', []) or []), 'size': int(stat.st_size)}
    except Exception as exc:
        try:
            return {'path': path, 'name': os.path.basename(path), 'created_at': '', 'reason': 'unknown', 'files': 0, 'size': os.path.getsize(path)}
        except OSError:
            return {'path': path, 'name': os.path.basename(path), 'created_at': '', 'reason': 'unknown', 'files': 0, 'size': 0}

def _delete_save_backup(path: str) -> tuple:
    try:
        os.remove(path)
        return (True, '')
    except OSError as exc:
        return (False, str(exc))

def _record_stat_event(data: dict, key: str, amount: int=1):
    stats = data.setdefault('statistics', {})
    stats[key] = max(0, int(stats.get(key, 0) or 0) + int(amount))
GAME_PROFILE_SCHEMA = 2
PORTABLE_SCHEMA = 1
_SENSITIVE_EXPORT_KEYS = {'token', 'secret', 'password', 'credential', 'api_key', 'client_secret', 'session', 'authorization'}

def _default_game_profile(app: dict) -> dict:
    nested = app.get('game_profile') if isinstance(app.get('game_profile'), dict) else {}
