def _apply_game_profile(app: dict, profile: dict) -> dict:
    if not isinstance(profile, dict):
        return app
    current = _default_game_profile(app)
    current.update(profile)
    app['game_profile'] = dict(current)
    app['profile_schema_version'] = GAME_PROFILE_SCHEMA
    field_map = {'title': 'title', 'alias': 'alias', 'game_root': 'game_root', 'exe': 'exe', 'args': 'args', 'working_directory': 'working_directory', 'input_type': 'input_type', 'controller_profile': 'controller_profile', 'safe_mode': 'safe_mode', 'controller_output': 'controller_output', 'language': 'language', 'resolution': 'resolution', 'display_mode': 'display_mode', 'fullscreen': 'fullscreen', 'borderless': 'borderless', 'vsync': 'vsync', 'fps_limit': 'fps_limit', 'overlay': 'overlay', 'run_as_admin': 'run_as_admin', 'process_priority': 'process_priority', 'affinity': 'affinity', 'preload_enabled': 'preload_enabled', 'tags': 'tags', 'genre': 'genre', 'description': 'description', 'cover': 'cover', 'background': 'background', 'controller_routing': 'controller_routing'}
    for source, target in field_map.items():
        if source in current:
            app[target] = current[source]
    routing = app.setdefault('controller_routing', {})
    routing.update({'delay_ms': max(0, int(current.get('routing_delay_ms', 0) or 0)), 'player_slot': max(1, min(4, int(current.get('player_slot', 1) or 1))), 'physical_controller': str(current.get('physical_controller', '') or ''), 'rumble_enabled': bool(current.get('rumble_enabled', True))})
    if isinstance(current.get('emulator'), dict):
        app['emulator'] = dict(current['emulator'])
    emulator = app.setdefault('emulator', {})
    if current.get('emulator_name'):
        emulator['name'] = str(current['emulator_name'])
    if 'emulator_path' in current:
        emulator['path'] = str(current.get('emulator_path') or '')
    if 'emulator_args' in current:
        emulator['args'] = str(current.get('emulator_args') or '{game}')
    content = app.setdefault('content_paths', {})
    content['active_dlc'] = list(current.get('active_dlc') or [])
    content['active_mods'] = list(current.get('active_mods') or [])
    content['active_patches'] = list(current.get('active_patches') or [])
    backup = app.setdefault('save_backup', {})
    if current.get('save_dir'):
        backup['save_dir'] = current['save_dir']
    if current.get('backup_dir'):
        backup['backup_dir'] = current['backup_dir']
    backup['retention'] = max(1, int(current.get('backup_retention', 10) or 10))
    return app

def _sanitize_export(value):
    if isinstance(value, dict):
        return {key: _sanitize_export(item) for key, item in value.items() if not any((token in str(key).lower() for token in _SENSITIVE_EXPORT_KEYS))}
    if isinstance(value, list):
        return [_sanitize_export(item) for item in value]
    if isinstance(value, str):
        lowered = value.lower()
        if any((token in lowered for token in ('password=', 'token=', 'secret='))):
            return '[redacted]'
    return value

def _validate_path(path: str, kind: str='path', want: str='any', require_nonempty: bool=False) -> dict:
    raw = str(path or '').strip()
    result = {'path': raw, 'kind': kind, 'exists': False, 'is_file': False, 'is_dir': False, 'readable': False, 'writable': False, 'executable': False, 'network': raw.startswith('\\\\'), 'status': 'Missing', 'reason': ''}
    if not raw:
        result['reason'] = 'Path is empty'
        return result
    if '\x00' in raw or len(raw) > 32760 or any((part == '..' for part in raw.replace('\\', '/').split('/'))):
        result['status'] = 'Unsafe Path'
        result['reason'] = 'Unsafe or invalid path'
        return result
    expanded = os.path.abspath(os.path.expanduser(raw))
    result['path'] = expanded
    result['exists'] = os.path.exists(expanded)
    result['is_file'] = os.path.isfile(expanded)
    result['is_dir'] = os.path.isdir(expanded)
    result['readable'] = os.access(expanded, os.R_OK)
    result['writable'] = os.access(expanded, os.W_OK)
    result['executable'] = bool(result['is_file'] and os.access(expanded, os.X_OK))
    if not result['exists']:
        result['status'] = 'Missing'
    elif want == 'file' and (not result['is_file']):
        result['status'] = 'Invalid Format'
    elif want == 'dir' and (not result['is_dir']):
        result['status'] = 'Invalid Format'
    elif not result['readable']:
        result['status'] = 'Permission Denied'
    elif result['is_file'] and want == 'executable' and (not result['executable']):
        result['status'] = 'Not Executable'
    elif not result['writable'] and kind not in ('exe', 'game'):
        result['status'] = 'Read-only'
    elif require_nonempty and result['is_dir'] and (not os.listdir(expanded)):
        result['status'] = 'Missing'
        result['reason'] = 'Directory is empty'
    else:
        result['status'] = 'Valid'
    return result

def _content_metadata(app: dict, kind: str) -> list:
    content = app.setdefault('content_paths', {})
    key = kind.lower()
    raw = list(content.get(key, []) or [])
    entries = content.setdefault(f'{key}_metadata', [])
    by_path = {str(item.get('path')): item for item in entries if isinstance(item, dict) and item.get('path')}
    normalized = []
    for index, value in enumerate(raw):
        path = str(value.get('path') if isinstance(value, dict) else value)
        item = dict(by_path.get(path, {}))
        item.update({'name': item.get('name') or os.path.basename(path) or path, 'version': item.get('version', ''), 'author': item.get('author', ''), 'description': item.get('description', ''), 'installed_at': item.get('installed_at', ''), 'last_used': item.get('last_used', ''), 'path': path, 'hash': item.get('hash', ''), 'enabled': bool(item.get('enabled', content.get('enabled', {}).get(path, True))), 'load_order': int(item.get('load_order', index)), 'dependencies': list(item.get('dependencies', []) or []), 'incompatibilities': list(item.get('incompatibilities', []) or []), 'required_game_version': item.get('required_game_version', ''), 'required_emulator_version': item.get('required_emulator_version', ''), 'source_url': item.get('source_url', ''), 'kind': key})
        normalized.append(item)
    content[f'{key}_metadata'] = normalized
    return normalized

def _portable_data_snapshot(data: dict, include_cache=True, include_saves=True, selected_titles=None, scope='all') -> dict:
    snapshot = _sanitize_export(dict(data or {}))
    apps = snapshot.get('apps', [])
    if selected_titles:
        selected = {str(value) for value in selected_titles}
        snapshot['apps'] = [app for app in apps if str(app.get('title', '')) in selected]
    scope = str(scope or 'all').lower()
    if scope == 'emulators':
        snapshot['apps'] = []
        snapshot['controller_profiles'] = {}
    elif scope == 'controllers':
        snapshot['apps'] = []
        snapshot['emulator_profiles'] = {}
    elif scope == 'selected' and (not selected_titles):
        snapshot['apps'] = []
    if not include_cache:
        snapshot.pop('cache', None)
    if not include_saves:
        for app in snapshot.get('apps', []):
            app.pop('save_backup', None)
    snapshot.setdefault('portable_manifest', {})
    snapshot['portable_manifest'].update({'schema_version': PORTABLE_SCHEMA, 'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'), 'relative_paths': True, 'includes_cache': bool(include_cache), 'includes_saves': bool(include_saves), 'scope': scope})
    portable_root = str((data.get('settings') or {}).get('portable_root') or _APP_DATA_DIR).strip()
    portable_root = os.path.abspath(os.path.expanduser(portable_root))

    def _relativize(value):
        if not isinstance(value, str) or not value:
            return value
        expanded = os.path.abspath(os.path.expanduser(value))
        try:
            rel = os.path.relpath(expanded, portable_root)
        except ValueError:
            return value
        if rel != os.pardir and (not rel.startswith(os.pardir + os.sep)):
            return '$PORTABLE_ROOT/' + rel.replace(os.sep, '/')
        return value
    path_key_tokens = ('path', 'root', 'dir', 'directory', 'exe', 'cover', 'background', 'cache', 'firmware', 'bios', 'shader', 'config', 'cwd', 'working', 'controller')

    def _walk(value, key=''):
        if isinstance(value, dict):
            return {child_key: _walk(item, str(child_key).lower()) for child_key, item in value.items()}
        if isinstance(value, list):
            return [_walk(item, key) for item in value]
        if any((token in str(key).lower() for token in path_key_tokens)):
            return _relativize(value)
        return value
    snapshot = _walk(snapshot)
    snapshot.setdefault('portable_manifest', {})['portable_root'] = '$PORTABLE_ROOT'
    return snapshot

def _export_portable_data(data: dict, path: str, include_cache=True, include_saves=True, selected_titles=None, scope='all') -> tuple:
    if not path:
        return (False, 'Export path is empty.')
    target = os.path.abspath(os.path.expanduser(path))
    tmp = target + '.tmp'
    try:
        payload = _portable_data_snapshot(data, include_cache, include_saves, selected_titles, scope)
        raw = json.dumps(payload, ensure_ascii=False, indent=2).encode('utf-8')
        manifest = {'schema_version': PORTABLE_SCHEMA, 'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'), 'sha256': hashlib.sha256(raw).hexdigest(), 'payload': 'launcher.json'}
        with zipfile.ZipFile(tmp, 'w', zipfile.ZIP_DEFLATED) as archive:
            archive.writestr('manifest.json', json.dumps(manifest, indent=2))
            archive.writestr('launcher.json', raw)
        os.replace(tmp, target)
        return (True, target)
    except Exception as exc:
        try:
            os.remove(tmp)
        except OSError:
            pass
        return (False, str(exc))

def _import_portable_data(path: str, current: dict, mode='merge') -> tuple:
    try:
        with zipfile.ZipFile(path, 'r') as archive:
            manifest = json.loads(archive.read('manifest.json'))
            raw = archive.read(str(manifest.get('payload', 'launcher.json')))
        if hashlib.sha256(raw).hexdigest() != manifest.get('sha256'):
            return (False, 'Portable archive integrity check failed.')
        incoming = json.loads(raw.decode('utf-8'))
        if not isinstance(incoming, dict) or not isinstance(incoming.get('apps'), list):
            return (False, 'Portable archive has an invalid schema.')
        import_root = os.path.abspath(os.path.dirname(path))
        configured_root = str((current.get('settings') or {}).get('portable_root') or import_root).strip()
        configured_root = os.path.abspath(os.path.expanduser(configured_root))

        def _resolve(value):
            if isinstance(value, dict):
                return {key: _resolve(item) for key, item in value.items()}
            if isinstance(value, list):
                return [_resolve(item) for item in value]
            if isinstance(value, str) and value.startswith('$PORTABLE_ROOT/'):
                return os.path.normpath(os.path.join(configured_root, value[len('$PORTABLE_ROOT/'):].replace('/', os.sep)))
            return value
        incoming = _resolve(incoming)
        incoming.pop('portable_manifest', None)
        if mode == 'replace':
            merged = incoming
        else:
            merged = dict(current or {})
            for key, value in incoming.items():
                if key == 'apps':
                    old = {str(app.get('title')): app for app in merged.get('apps', [])}
                    for app in value:
                        old[str(app.get('title'))] = app
                    merged['apps'] = list(old.values())
                elif isinstance(value, dict) and isinstance(merged.get(key), dict):
                    merged[key] = {**merged[key], **value}
                else:
                    merged[key] = value
        merged.setdefault('apps', [])
        merged.setdefault('folders', {})
        merged.setdefault('folder_order', [])
        merged.setdefault('settings', {})
        return (True, merged)
    except Exception as exc:
        return (False, str(exc))

class SaveBackupWorker(QThread):
    completed = pyqtSignal(bool, str)

    def __init__(self, app: dict, settings: dict, reason: str, parent=None):
        super().__init__(parent)
        self._app = app
        self._settings = dict(settings or {})
        self._reason = reason

    def run(self):
        try:
            ok, detail = _create_save_backup(self._app, self._settings, self._reason)
            self.completed.emit(bool(ok), str(detail))
        except Exception as exc:
            self.completed.emit(False, str(exc))

class ContentApplyWorker(QThread):
    completed = pyqtSignal(bool, str, object)

    def __init__(self, app, mode='apply', parent=None):
        super().__init__(parent)
        self._app = app
        self._mode = mode

    def run(self):
        try:
            content = dict(self._app.get('content_paths') or {})
            backup_dir = os.path.join(_APP_DATA_DIR, 'content_backups')
            os.makedirs(backup_dir, exist_ok=True)
            if self._mode == 'rollback':
                backup_path = str(content.get('last_apply_backup', '') or '')
                if not backup_path or not os.path.isfile(backup_path):
                    self.completed.emit(False, 'No content apply backup is available.', {})
                    return
                with open(backup_path, 'r', encoding='utf-8') as stream:
                    restored = json.load(stream)
                self.completed.emit(True, 'Content routing rolled back.', restored)
                return
            entries = []
            for kind in ('dlc', 'mods', 'patches'):
                for item in _content_metadata(self._app, kind):
                    check = _validate_path(item.get('path'), kind, 'dir')
                    item['status'] = check['status']
                    if item.get('enabled', True) and check['status'] != 'Valid':
                        self.completed.emit(False, f"{kind.upper()} path is {check['status']}: {item.get('path')}", {})
                        return
                    entries.append(item)
            stamp = time.strftime('%Y%m%d_%H%M%S')
            backup_path = os.path.join(backup_dir, f"{_safe_slug(self._app.get('title', 'game'))}_{stamp}.json")
            payload = _sanitize_export(content)
            fd, tmp = _tempfile.mkstemp(prefix='.content_', suffix='.tmp', dir=backup_dir)
            with os.fdopen(fd, 'w', encoding='utf-8') as stream:
                json.dump(payload, stream, ensure_ascii=False, indent=2)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(tmp, backup_path)
            result = {'last_apply_backup': backup_path, 'last_apply_at': time.strftime('%Y-%m-%dT%H:%M:%S'), 'entries': len(entries), 'statuses': [item.get('status') for item in entries]}
            self.completed.emit(True, 'Content routing applied safely.', result)
        except Exception as exc:
            try:
                if 'tmp' in locals() and os.path.exists(tmp):
                    os.remove(tmp)
            except OSError:
                pass
            self.completed.emit(False, str(exc), {})

class PortableExportWorker(QThread):
    completed = pyqtSignal(bool, str)

    def __init__(self, data, path, include_cache, include_saves, selected_titles=None, scope='all', parent=None):
        super().__init__(parent)
        self._data = data
        self._path = path
        self._include_cache = include_cache
        self._include_saves = include_saves
        self._selected_titles = selected_titles
        self._scope = scope
        self._cancelled = threading.Event()

    def cancel(self):
        self._cancelled.set()

    def run(self):
        if self._cancelled.is_set():
            self.completed.emit(False, 'Export cancelled.')
            return
        ok, detail = _export_portable_data(self._data, self._path, self._include_cache, self._include_saves, self._selected_titles, self._scope)
        self.completed.emit(bool(ok), str(detail))

def _restore_save_backup(app: dict, settings: dict, archive_path: str) -> tuple:
    source = _save_source_root(app, settings)
    if not source or not os.path.isdir(source):
        return (False, 'The configured save folder does not exist.')
    emergency_ok, emergency = _create_save_backup(app, settings, reason='before_restore')
    if not emergency_ok:
        return (False, 'Emergency backup failed; restore was cancelled.')
    stage = _tempfile.mkdtemp(prefix='gamestation_save_restore_')
    try:
        with zipfile.ZipFile(archive_path, 'r') as archive:
            members = archive.namelist()
            for member in members:
                normalized = os.path.normpath(member)
                if not member or normalized in ('.', '..') or os.path.isabs(member) or normalized.startswith('..' + os.sep) or normalized.startswith('../') or (':' in normalized.split(os.sep)[0]):
                    return (False, 'Unsafe path in backup; restore was cancelled.')
            for member in members:
                if member.endswith('/'):
                    continue
                destination = os.path.join(stage, os.path.normpath(member))
                os.makedirs(os.path.dirname(destination), exist_ok=True)
                with archive.open(member, 'r') as source_stream, open(destination, 'wb') as destination_stream:
                    shutil.copyfileobj(source_stream, destination_stream)
        manifest_path = os.path.join(stage, 'manifest.json')
        if not os.path.isfile(manifest_path):
            return (False, 'This backup has no manifest and was not restored.')
        with open(manifest_path, 'r', encoding='utf-8') as stream:
            manifest = json.load(stream)
        files = manifest.get('files', [])
        if not isinstance(files, list) or not files:
            return (False, 'This backup contains no save files.')
        rollback = _tempfile.mkdtemp(prefix='gamestation_save_rollback_')
        replaced = []
        try:
            validated = []
            for item in files:
                rel = str(item.get('path') or '')
                if not rel or os.path.isabs(rel) or rel.startswith(('..', '../')):
                    return (False, 'Unsafe path in backup; restore was cancelled.')
                src = os.path.join(stage, rel)
                dst = os.path.abspath(os.path.join(source, rel))
                if os.path.commonpath((os.path.abspath(source), dst)) != os.path.abspath(source):
                    return (False, 'Unsafe destination path; restore was cancelled.')
                if not os.path.isfile(src):
                    return (False, 'A file in the backup is missing.')
                validated.append((rel, src, dst))
            for rel, src, dst in validated:
                old = os.path.join(rollback, rel)
                old_exists = os.path.isfile(dst)
                if old_exists:
                    os.makedirs(os.path.dirname(old), exist_ok=True)
                    shutil.copy2(dst, old)
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                staged = dst + '.restore_tmp'
                shutil.copy2(src, staged)
                os.replace(staged, dst)
                replaced.append((dst, old, old_exists))
        except Exception:
            for dst, old, old_exists in reversed(replaced):
                try:
                    if old_exists and os.path.isfile(old):
                        os.replace(old, dst)
                    elif not old_exists and os.path.exists(dst):
                        os.remove(dst)
                except OSError:
                    pass
            raise
        finally:
            shutil.rmtree(rollback, ignore_errors=True)
        return (True, f'Restored {len(files)} files. Emergency backup: {emergency}')
    except Exception as exc:
        return (False, str(exc))
    finally:
        shutil.rmtree(stage, ignore_errors=True)
_CTRL_DEBUG: bool = False


def _ctrl_axis(v: int) -> int:
    if v < 128:
        return max(-32768, round((v - 128) * (32768 / 128)))
    elif v > 128:
        return min(32767, round((v - 128) * (32767 / 127)))
    return 0

class XInputBridge(QThread):
    error_occurred = pyqtSignal(str)
    _DPAD = {0: (True, False, False, False), 1: (True, False, False, True), 2: (False, False, False, True), 3: (False, True, False, True), 4: (False, True, False, False), 5: (False, True, True, False), 6: (False, False, True, False), 7: (True, False, True, False), 8: (False, False, False, False)}
    _DPAD_U = 1
    _DPAD_D = 2
    _DPAD_L = 4
    _DPAD_R = 8
    _START = 16
    _BACK = 32
    _LS = 64
    _RS = 128
    _LB = 256
    _RB = 512
    _GUIDE = 1024
    _A = 4096
    _B = 8192
    _X = 16384
    _Y = 32768

    def __init__(self, mode: str='xbox360', config=None, path: str='', pid: int=0, parent=None):
        super().__init__(parent)
        self._mode = mode
        self._config = dict(config or {})
        self._path = path or self._config.get('path', '')
        self._pid = pid or int(self._config.get('pid', 0) or 0)
        self._gamepad = None
        self._rumble_h = None
        self._rumble_is_bt = False
        self._rumble_seq = 0
        self._stop_event = None
        self._lock = threading.Lock()
        self._prev_mask = 0
        self._poll_count = 0
        self._t0 = 0.0
        self._crashed: bool = False
        self._stop_reason: str = ''
        self._feed_q: 'queue.SimpleQueue[bytes | None]' = queue.SimpleQueue()
        # Set once the ViGEm virtual pad has actually been created (or
        # creation has failed) -- lets ControllerEmulationManager serialize
        # session startup so XInput assigns player slots in the order the
        # user configured, instead of whichever thread's OS scheduling
        # happens to win the race to register with ViGEmBus first.
        self._gamepad_ready = threading.Event()
        # PS/Home-button hold-to-close-game tracking (see _track_ps_hold).
        self._ps_press_t = None
        self._ps_hold_fired = False
    _PS_HOLD_CLOSE_SEC = 2.0

    def _track_ps_hold(self, pressed: bool):
        """Holding PS/Home for _PS_HOLD_CLOSE_SEC force-closes the running
        game, regardless of any button remapping the user has configured
        (this reads the physical PS button directly, not the mapped
        output) -- a hardware-level safety hotkey, independent of in-game
        button remaps."""
        now = time.time()
        if pressed:
            if self._ps_press_t is None:
                self._ps_press_t = now
            elif not self._ps_hold_fired and now - self._ps_press_t >= self._PS_HOLD_CLOSE_SEC:
                self._ps_hold_fired = True
                callback = self._config.get('force_close_callback')
                if callback:
                    _UI_INVOKER.invoke(callback)
        else:
            self._ps_press_t = None
            self._ps_hold_fired = False

    def _tune_axis(self, value: int, sensitivity=None) -> int:
        cfg = self._config
        normalized = max(-1.0, min(1.0, float(value) / 32767.0))
        deadzone = max(0.0, min(0.95, float(cfg.get('deadzone', 0.08))))
        if abs(normalized) <= deadzone:
            normalized = 0.0
        else:
            sign = -1.0 if normalized < 0 else 1.0
            normalized = sign * ((abs(normalized) - deadzone) / max(1.0 - deadzone, 0.01))
        if sensitivity is None:
            sensitivity = cfg.get('sensitivity', 1.0)
        normalized = max(-1.0, min(1.0, normalized * max(0.1, min(3.0, float(sensitivity)))))
        return max(-32768, min(32767, int(normalized * 32767)))

    def _tune_trigger(self, value: int) -> int:
        deadzone = max(0.0, min(0.95, float(self._config.get('trigger_deadzone', 0.04))))
        normalized = max(0.0, min(1.0, float(value) / 255.0))
        if normalized <= deadzone:
            return 0
        return max(0, min(255, int((normalized - deadzone) / max(1.0 - deadzone, 0.01) * 255)))

    def _tune_buttons(self, buttons: set) -> set:
        mapping = self._config.get('mapping') or {}
        if not mapping:
            return buttons
        return {str(mapping.get(name, name)) for name in buttons if mapping.get(name, name) not in (None, 'default')}

    def _send_rumble(self, right_motor: int, left_motor: int):
        if not bool(self._config.get('rumble', True)):
            return
        self._rumble_seq = _send_sony_rumble(self._rumble_h, self._rumble_is_bt, self._pid, self._rumble_seq, right_motor, left_motor)

    def tap_start_button(self, hold_ms: int=80):
        """Synthesizes a brief Options/Start press+release on the virtual
        pad, independent of any physical input. Used to make the game open
        its own pause menu (which typically also mutes game audio) right
        before the launcher minimizes it to the background."""
        with self._lock:
            gp = self._gamepad
            if gp is None:
                return
            try:
                gp.press_button(button=_vg.XUSB_BUTTON.XUSB_GAMEPAD_START)
                gp.update()
            except Exception:
                return

        def _release():
            with self._lock:
                gp2 = self._gamepad
                if gp2 is None:
                    return
                try:
                    gp2.release_button(button=_vg.XUSB_BUTTON.XUSB_GAMEPAD_START)
                    gp2.update()
                except Exception:
                    pass
        QTimer.singleShot(max(0, int(hold_ms)), _release)

    @property
    def crashed(self) -> bool:
        return self._crashed

    @property
    def stop_reason(self) -> str:
        return self._stop_reason

    def feed(self, data: bytes):
        try:
            self._feed_q.put_nowait(data)
        except Exception:
            pass

    def stop(self):
        k32 = _KERNEL32_DLL
        try:
            self._feed_q.put_nowait(None)
        except Exception:
            pass
        if self._stop_event:
            k32.SetEvent(self._stop_event)

    def run(self):
        k32 = _KERNEL32_DLL
        if not _VGAMEPAD_OK:
            self.error_occurred.emit('vgamepad automatic setup did not complete; controller emulation is unavailable')
            self._crashed = True
            self._stop_reason = 'vgamepad not installed'
            return
        self._stop_event = k32.CreateEventW(None, True, False, None)
        if not self._stop_event:
            self._crashed = True
            self._stop_reason = 'could not create Windows stop event'
            return
        try:
            self._run_session()
        finally:
            k32.CloseHandle(self._stop_event)
            self._stop_event = None
            if self._rumble_h not in (None, INVALID_HANDLE):
                try:
                    k32.CloseHandle(self._rumble_h)
                except Exception:
                    pass
                self._rumble_h = None
            with self._lock:
                try:
                    if self._gamepad:
                        self._gamepad.reset()
                        self._gamepad.update()
                except Exception:
                    pass
                self._gamepad = None

    def _run_session(self):
        with self._lock:
            try:
                self._gamepad = _vg.VX360Gamepad()
                self._prev_mask = 0
                if self._config.get('rumble', True):
                    self._rumble_h, self._rumble_is_bt = _open_sony_rumble_handle(self._path)
                    if self._rumble_h is not None:
                        try:
                            self._gamepad.register_notification(callback=lambda client, target, large_motor, small_motor, led_number, user_data: self._send_rumble(small_motor, large_motor))
                        except Exception:
                            pass
            except Exception as e:
                msg = f'ViGEmBus failure: could not create virtual pad -- {e}'
                self.error_occurred.emit(msg)
                self._crashed = True
                self._gamepad_ready.set()
                self._stop_reason = msg
                return
            self._gamepad_ready.set()
        if _CTRL_DEBUG:
            self._poll_count = 0
            self._t0 = time.perf_counter()
        while True:
            try:
                data = self._feed_q.get(timeout=0.1)
            except queue.Empty:
                if self._stop_event:
                    k32 = _KERNEL32_DLL
                    if k32.WaitForSingleObject(self._stop_event, 0) == 0:
                        self._crashed = False
                        self._stop_reason = 'clean stop requested'
                        break
                continue
            if data is None:
                self._crashed = False
                self._stop_reason = 'clean stop requested'
                break
            t_in = time.perf_counter() if _CTRL_DEBUG else 0.0
            self._forward(data)
            if _CTRL_DEBUG:
                self._poll_count += 1
                elapsed = time.perf_counter() - self._t0
                if elapsed >= 5.0:
                    rate = self._poll_count / elapsed
                    self._poll_count = 0
                    self._t0 = time.perf_counter()
    _source_pid: int = 0

    def set_source_pid(self, pid: int):
        self._source_pid = pid

    def _forward(self, data: bytes):
        if len(data) < 10:
            return
        try:
            rid = data[0]
            is_ds4 = self._source_pid in DUALSHOCK4_PIDS
            if rid == 1 and is_ds4:
                if len(data) < 10:
                    return
                lx = data[1]
                ly = data[2]
                rx = data[3]
                ry = data[4]
                b0 = data[5]
                b1 = data[6]
                b2 = data[7] if len(data) > 7 else 0
                l2 = data[8] if len(data) > 8 else 0
                r2 = data[9] if len(data) > 9 else 0
            elif rid == 17 and is_ds4:
                if len(data) < 12:
                    return
                lx = data[3]
                ly = data[4]
                rx = data[5]
                ry = data[6]
                b0 = data[7]
                b1 = data[8]
                b2 = data[9] if len(data) > 9 else 0
                l2 = data[10] if len(data) > 10 else 0
                r2 = data[11] if len(data) > 11 else 0
            elif rid == 1:
                if len(data) >= 78:
                    lx = data[1]
                    ly = data[2]
                    rx = data[3]
                    ry = data[4]
                    b0 = data[5]
                    b1 = data[6]
                    b2 = data[7] if len(data) > 7 else 0
                    l2 = 255 if b1 & 4 else 0
                    r2 = 255 if b1 & 8 else 0
                elif len(data) >= 64:
                    lx = data[1]
                    ly = data[2]
                    rx = data[3]
                    ry = data[4]
                    l2 = data[5]
                    r2 = data[6]
                    b0 = data[8]
                    b1 = data[9]
                    b2 = data[10] if len(data) > 10 else 0
                elif len(data) >= 10:
                    lx = data[1]
                    ly = data[2]
                    rx = data[3]
                    ry = data[4]
                    l2 = 0
                    r2 = 0
                    b0 = data[5] if len(data) > 5 else 0
                    b1 = data[6] if len(data) > 6 else 0
                    b2 = data[7] if len(data) > 7 else 0
                else:
                    return
            elif rid == 49:
                if len(data) < 11:
                    return
                lx = data[2]
                ly = data[3]
                rx = data[4]
                ry = data[5]
                l2 = data[6]
                r2 = data[7]
                b0 = data[9]
                b1 = data[10]
                b2 = data[11] if len(data) > 11 else 0
            else:
                return
            dp_n, dp_s, dp_w, dp_e = self._DPAD.get(b0 & 15, (False, False, False, False))
            sq = bool(b0 & 16)
            cr = bool(b0 & 32)
            ci = bool(b0 & 64)
            tr = bool(b0 & 128)
            l1 = bool(b1 & 1)
            r1 = bool(b1 & 2)
            shr = bool(b1 & 16)
            opt = bool(b1 & 32)
            l3 = bool(b1 & 64)
            r3 = bool(b1 & 128)
            ps = bool(b2 & 1)
            self._track_ps_hold(ps)
            btn_mask = (self._DPAD_U if dp_n else 0) | (self._DPAD_D if dp_s else 0) | (self._DPAD_L if dp_w else 0) | (self._DPAD_R if dp_e else 0) | (self._START if opt else 0) | (self._BACK if shr else 0) | (self._LS if l3 else 0) | (self._RS if r3 else 0) | (self._LB if l1 else 0) | (self._RB if r1 else 0) | (self._GUIDE if ps else 0) | (self._A if cr else 0) | (self._B if ci else 0) | (self._X if sq else 0) | (self._Y if tr else 0)
            button_names = {self._DPAD_U: 'up', self._DPAD_D: 'down', self._DPAD_L: 'left', self._DPAD_R: 'right', self._START: 'options', self._BACK: 'back', self._LS: 'l3', self._RS: 'r3', self._LB: 'l1', self._RB: 'r1', self._GUIDE: 'ps', self._A: 'cross', self._B: 'circle', self._X: 'square', self._Y: 'triangle'}
            pressed_names = {name for bit, name in button_names.items() if btn_mask & bit}
            left_trigger = self._tune_trigger(l2)
            right_trigger = self._tune_trigger(r2)
            if left_trigger >= 128:
                pressed_names.add('l2')
            if right_trigger >= 128:
                pressed_names.add('r2')
            mapped_names = self._tune_buttons(pressed_names)
            btn_mask = sum((bit for bit, name in button_names.items() if name in mapped_names))
            mapping = self._config.get('mapping') or {}
            if mapping.get('l2') not in (None, 'default', 'l2'):
                left_trigger = 0
            if mapping.get('r2') not in (None, 'default', 'r2'):
                right_trigger = 0
            if 'l2' in mapped_names and left_trigger == 0:
                left_trigger = 255
            if 'r2' in mapped_names and right_trigger == 0:
                right_trigger = 255
            if _CTRL_DEBUG:
                pass
            with self._lock:
                gp = self._gamepad
                if gp is None:
                    return
                left_sensitivity = self._config.get('left_sensitivity', self._config.get('sensitivity', 1.0))
                right_sensitivity = self._config.get('right_sensitivity', self._config.get('sensitivity', 1.0))
                lx_value = self._tune_axis(_ctrl_axis(lx), left_sensitivity)
                ly_value = self._tune_axis(_ctrl_axis(255 - ly), left_sensitivity)
                rx_value = self._tune_axis(_ctrl_axis(rx), right_sensitivity)
                ry_value = self._tune_axis(_ctrl_axis(255 - ry), right_sensitivity)
                if self._config.get('invert_x', False):
                    rx_value = -rx_value
                if self._config.get('invert_y', False):
                    ry_value = -ry_value
                gp.left_joystick(x_value=lx_value, y_value=ly_value)
                gp.right_joystick(x_value=rx_value, y_value=ry_value)
                gp.left_trigger(value=left_trigger)
                gp.right_trigger(value=right_trigger)
                changed = btn_mask ^ self._prev_mask
                if changed:
                    B = _vg.XUSB_BUTTON
                    BTN_MAP = ((self._DPAD_U, B.XUSB_GAMEPAD_DPAD_UP), (self._DPAD_D, B.XUSB_GAMEPAD_DPAD_DOWN), (self._DPAD_L, B.XUSB_GAMEPAD_DPAD_LEFT), (self._DPAD_R, B.XUSB_GAMEPAD_DPAD_RIGHT), (self._START, B.XUSB_GAMEPAD_START), (self._BACK, B.XUSB_GAMEPAD_BACK), (self._LS, B.XUSB_GAMEPAD_LEFT_THUMB), (self._RS, B.XUSB_GAMEPAD_RIGHT_THUMB), (self._LB, B.XUSB_GAMEPAD_LEFT_SHOULDER), (self._RB, B.XUSB_GAMEPAD_RIGHT_SHOULDER), (self._GUIDE, B.XUSB_GAMEPAD_GUIDE), (self._A, B.XUSB_GAMEPAD_A), (self._B, B.XUSB_GAMEPAD_B), (self._X, B.XUSB_GAMEPAD_X), (self._Y, B.XUSB_GAMEPAD_Y))
                    for bit, btn in BTN_MAP:
                        if changed & bit:
                            if btn_mask & bit:
                                gp.press_button(button=btn)
                            else:
                                gp.release_button(button=btn)
                    self._prev_mask = btn_mask
                gp.update()
        except Exception as e:
            import traceback

class GenericHIDBridge(QThread):
    error_occurred = pyqtSignal(str)
    _BUTTONS = ((1, 'DPAD_UP'), (2, 'DPAD_DOWN'), (4, 'DPAD_LEFT'), (8, 'DPAD_RIGHT'), (16, 'START'), (32, 'BACK'), (64, 'LEFT_THUMB'), (128, 'RIGHT_THUMB'), (256, 'LEFT_SHOULDER'), (512, 'RIGHT_SHOULDER'), (1024, 'GUIDE'), (4096, 'A'), (8192, 'B'), (16384, 'X'), (32768, 'Y'))

    def __init__(self, config=None, parent=None):
        super().__init__(parent)
        self._feed_q: 'queue.SimpleQueue[dict | None]' = queue.SimpleQueue()
        self._stop_event = None
        self._gamepad = None
        self._prev_mask = 0
        self._lock = threading.Lock()
        self._crashed = False
        self._stop_reason = ''
        self._config = dict(config or {})
        self._gamepad_ready = threading.Event()

    def _prepare_state(self, state: dict) -> dict:
        cfg = self._config
        deadzone = max(0.0, min(0.95, float(cfg.get('deadzone', 0.08))))
        sensitivity = max(0.1, min(3.0, float(cfg.get('sensitivity', 1.0))))
        trigger_deadzone = max(0.0, min(0.95, float(cfg.get('trigger_deadzone', 0.04))))

        def axis(value, invert=False):
            value = max(-1.0, min(1.0, float(value)))
            if abs(value) <= deadzone:
                value = 0.0
            else:
                sign = -1.0 if value < 0 else 1.0
                value = sign * ((abs(value) - deadzone) / max(1.0 - deadzone, 0.01))
            value = max(-1.0, min(1.0, value * sensitivity))
            return -value if invert else value

        def trigger(value):
            value = max(0.0, min(1.0, float(value)))
            if value <= trigger_deadzone:
                return 0.0
            return min(1.0, (value - trigger_deadzone) / max(1.0 - trigger_deadzone, 0.01))
        prepared = dict(state)
        prepared['lx'] = axis(state.get('lx', 0.0))
        prepared['ly'] = axis(state.get('ly', 0.0))
        prepared['rx'] = axis(state.get('rx', 0.0), bool(cfg.get('invert_x', False)))
        prepared['ry'] = axis(state.get('ry', 0.0), bool(cfg.get('invert_y', False)))
        prepared['lt'] = trigger(state.get('lt', 0.0))
        prepared['rt'] = trigger(state.get('rt', 0.0))
        buttons = set(state.get('buttons', ()))
        if prepared['lt'] >= 0.5:
            buttons.add('l2')
        if prepared['rt'] >= 0.5:
            buttons.add('r2')
        mapping = cfg.get('mapping') or {}
        if mapping:
            remapped = set()
            for name in buttons:
                target = mapping.get(name, name)
                if target and target != 'default':
                    remapped.add(str(target))
            prepared['buttons'] = frozenset(remapped)
            if mapping.get('l2') not in (None, 'default', 'l2'):
                prepared['lt'] = 0.0
            if mapping.get('r2') not in (None, 'default', 'r2'):
                prepared['rt'] = 0.0
            if 'l2' in prepared['buttons']:
                prepared['lt'] = 1.0
            if 'r2' in prepared['buttons']:
                prepared['rt'] = 1.0
        else:
            prepared['buttons'] = frozenset(buttons)
        return prepared

    @property
    def crashed(self):
        return self._crashed

    @property
    def stop_reason(self):
        return self._stop_reason

    def feed(self, state: dict):
        try:
            self._feed_q.put_nowait(state)
        except Exception:
            pass

    def stop(self):
        try:
            self._feed_q.put_nowait(None)
        except Exception:
            pass
        if self._stop_event:
            _KERNEL32_DLL.SetEvent(self._stop_event)

    @staticmethod
    def _axis(value) -> int:
        return max(-32768, min(32767, int(float(value) * 32767)))

    @staticmethod
    def _trigger(value) -> int:
        return max(0, min(255, int(float(value) * 255)))

    def tap_start_button(self, hold_ms: int=80):
        """See XInputBridge.tap_start_button -- same idea, generic-HID
        bridge also drives a VX360Gamepad under the hood."""
        with self._lock:
            gp = self._gamepad
            if gp is None:
                return
            try:
                gp.press_button(button=_vg.XUSB_BUTTON.XUSB_GAMEPAD_START)
                gp.update()
            except Exception:
                return

        def _release():
            with self._lock:
                gp2 = self._gamepad
                if gp2 is None:
                    return
                try:
                    gp2.release_button(button=_vg.XUSB_BUTTON.XUSB_GAMEPAD_START)
                    gp2.update()
                except Exception:
                    pass
        QTimer.singleShot(max(0, int(hold_ms)), _release)

    def run(self):
        if not _VGAMEPAD_OK:
            self.error_occurred.emit('vgamepad automatic setup did not complete; generic controller emulation is unavailable')
            self._crashed = True
            self._stop_reason = 'vgamepad unavailable'
            self._gamepad_ready.set()
            return
        self._stop_event = _KERNEL32_DLL.CreateEventW(None, True, False, None)
        if not self._stop_event:
            self._crashed = True
            self._stop_reason = 'could not create stop event'
            self._gamepad_ready.set()
            return
        try:
            self._gamepad = _vg.VX360Gamepad()
            B = _vg.XUSB_BUTTON
            bit_to_button = {1: B.XUSB_GAMEPAD_DPAD_UP, 2: B.XUSB_GAMEPAD_DPAD_DOWN, 4: B.XUSB_GAMEPAD_DPAD_LEFT, 8: B.XUSB_GAMEPAD_DPAD_RIGHT, 16: B.XUSB_GAMEPAD_START, 32: B.XUSB_GAMEPAD_BACK, 64: B.XUSB_GAMEPAD_LEFT_THUMB, 128: B.XUSB_GAMEPAD_RIGHT_THUMB, 256: B.XUSB_GAMEPAD_LEFT_SHOULDER, 512: B.XUSB_GAMEPAD_RIGHT_SHOULDER, 1024: B.XUSB_GAMEPAD_GUIDE, 4096: B.XUSB_GAMEPAD_A, 8192: B.XUSB_GAMEPAD_B, 16384: B.XUSB_GAMEPAD_X, 32768: B.XUSB_GAMEPAD_Y}
            self._gamepad_ready.set()
            while True:
                try:
                    state = self._feed_q.get(timeout=0.1)
                except queue.Empty:
                    if _KERNEL32_DLL.WaitForSingleObject(self._stop_event, 0) == 0:
                        break
                    continue
                if state is None:
                    break
                state = self._prepare_state(state)
                gp = self._gamepad
                if gp is None:
                    break
                gp.left_joystick(x_value=self._axis(state.get('lx', 0)), y_value=self._axis(-state.get('ly', 0)))
                gp.right_joystick(x_value=self._axis(state.get('rx', 0)), y_value=self._axis(-state.get('ry', 0)))
                gp.left_trigger(value=self._trigger(state.get('lt', 0)))
                gp.right_trigger(value=self._trigger(state.get('rt', 0)))
                mask = 0
                buttons = state.get('buttons', ())
                button_names = {'up': 1, 'down': 2, 'left': 4, 'right': 8, 'options': 16, 'back': 32, 'l3': 64, 'r3': 128, 'l1': 256, 'r1': 512, 'ps': 1024, 'cross': 4096, 'circle': 8192, 'square': 16384, 'triangle': 32768}
                for name, bit in button_names.items():
                    if name in buttons:
                        mask |= bit
                changed = mask ^ self._prev_mask
                for bit, btn in bit_to_button.items():
                    if changed & bit:
                        if mask & bit:
                            gp.press_button(button=btn)
                        else:
                            gp.release_button(button=btn)
                self._prev_mask = mask
                gp.update()
        except Exception as exc:
            self._crashed = True
            self._stop_reason = str(exc)
            self.error_occurred.emit(f'Generic controller bridge failed: {exc}')
        finally:
            self._gamepad_ready.set()
            try:
                if self._gamepad:
                    self._gamepad.reset()
                    self._gamepad.update()
            except Exception:
                pass
            self._gamepad = None
            if self._stop_event:
                _KERNEL32_DLL.CloseHandle(self._stop_event)
                self._stop_event = None

class DS4Bridge(QThread):
    error_occurred = pyqtSignal(str)

    def __init__(self, mode: str='ps4', pid: int=0, path: str='', config=None, parent=None):
        super().__init__(parent)
        self._mode = mode
        self._pid = pid
        self._path = path
        self._config = dict(config or {})
        self._gamepad = None
        self._ex_report = None
        self._stop_event = None
        self._lock = threading.Lock()
        self._crashed: bool = False
        self._stop_reason: str = ''
        self._feed_q: 'queue.SimpleQueue[bytes | None]' = queue.SimpleQueue()
        self._touch_down = [False, False]
        self._touch_id = [0, 0]
        self._touch_pkt = 0
        self._rumble_h = None
        self._rumble_is_bt = False
        self._rumble_seq = 0
        self._rumble_lock = threading.Lock()
        self._gamepad_ready = threading.Event()

    def _tune_axis(self, value: int, invert=False, sensitivity=None) -> int:
        normalized = max(-1.0, min(1.0, (float(value) - 128.0) / 127.0))
        deadzone = max(0.0, min(0.95, float(self._config.get('deadzone', 0.08))))
        if abs(normalized) <= deadzone:
            normalized = 0.0
        else:
            sign = -1.0 if normalized < 0 else 1.0
            normalized = sign * ((abs(normalized) - deadzone) / max(1.0 - deadzone, 0.01))
        if sensitivity is None:
            sensitivity = self._config.get('sensitivity', 1.0)
        normalized = max(-1.0, min(1.0, normalized * max(0.1, min(3.0, float(sensitivity)))))
        if invert:
            normalized = -normalized
        return max(0, min(255, int(round(128.0 + normalized * 127.0))))

    def _tune_trigger(self, value: int) -> int:
        deadzone = max(0.0, min(0.95, float(self._config.get('trigger_deadzone', 0.04))))
        normalized = max(0.0, min(1.0, float(value) / 255.0))
        if normalized <= deadzone:
            return 0
        return max(0, min(255, int(round((normalized - deadzone) / max(1.0 - deadzone, 0.01) * 255))))

    def _mapped_names(self, names: set) -> set:
        mapping = self._config.get('mapping') or {}
        if not mapping:
            return names
        return {str(mapping.get(name, name)) for name in names if mapping.get(name, name) not in (None, 'default')}

    @property
    def crashed(self) -> bool:
        return self._crashed

    @property
    def stop_reason(self) -> str:
        return self._stop_reason

    def feed(self, data: bytes):
        try:
            self._feed_q.put_nowait(data)
        except Exception:
            pass

    def stop(self):
        k32 = _KERNEL32_DLL
        try:
            self._feed_q.put_nowait(None)
        except Exception:
            pass
        if self._stop_event:
            k32.SetEvent(self._stop_event)

    def run(self):
        k32 = _KERNEL32_DLL
        if not _VGAMEPAD_OK:
            self.error_occurred.emit('vgamepad automatic setup did not complete; controller emulation is unavailable')
            self._crashed = True
            self._stop_reason = 'vgamepad not installed'
            return
        self._stop_event = k32.CreateEventW(None, True, False, None)
        if not self._stop_event:
            self._crashed = True
            self._stop_reason = 'could not create Windows stop event'
            return
        try:
            self._run_session()
        finally:
            k32.CloseHandle(self._stop_event)
            self._stop_event = None
            self._close_rumble_handle()
            with self._lock:
                try:
                    if self._gamepad:
                        self._gamepad.reset()
                        self._gamepad.update()
                except Exception:
                    pass
                self._gamepad = None
                self._ex_report = None

    def _open_rumble_handle(self):
        if not self._path:
            return
        k32 = _KERNEL32_DLL
        GENERIC_WRITE = 1073741824
        FILE_SHARE_READ = 1
        FILE_SHARE_WRITE = 2
        OPEN_EXISTING = 3
        h = k32.CreateFileW(self._path, GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, 0, None)
        if h == INVALID_HANDLE:
            return
        out_len = _hid_output_report_len(h)
        self._rumble_is_bt = bool(out_len and out_len >= 78)
        self._rumble_h = h

    def _close_rumble_handle(self):
        with self._rumble_lock:
            if self._rumble_h is not None:
                try:
                    _KERNEL32_DLL.CloseHandle(self._rumble_h)
                except Exception:
                    pass
                self._rumble_h = None

    def tap_options_button(self, hold_ms: int=80):
        """DS4-mode equivalent of XInputBridge.tap_start_button: this
        bridge writes wButtons directly on the extended report rather than
        going through press_button/release_button, so OR/AND the OPTIONS
        bit in ourselves and push an update()."""
        with self._lock:
            gp = self._gamepad
            rep = self._ex_report
            if gp is None or rep is None:
                return
            try:
                bit = _vg_com.DS4_BUTTONS.DS4_BUTTON_OPTIONS
                rep.Report.wButtons |= bit
                gp.update()
            except Exception:
                return

        def _release():
            with self._lock:
                gp2 = self._gamepad
                rep2 = self._ex_report
                if gp2 is None or rep2 is None:
                    return
                try:
                    bit2 = _vg_com.DS4_BUTTONS.DS4_BUTTON_OPTIONS
                    rep2.Report.wButtons &= ~bit2
                    gp2.update()
                except Exception:
                    pass
        QTimer.singleShot(max(0, int(hold_ms)), _release)

    def _send_rumble(self, right_motor: int, left_motor: int):
        with self._rumble_lock:
            h = self._rumble_h
        if h is None:
            return
        try:
            import binascii as _bc
            k32 = _KERNEL32_DLL
            if self._rumble_is_bt:
                buf = bytearray(78)
                buf[0] = 49
                buf[1] = (self._rumble_seq & 15) << 4
                buf[2] = 16
                buf[3] = 2
                buf[5] = right_motor
                buf[6] = left_motor
                crc = _bc.crc32(bytes([162]) + bytes(buf[:74])) & 4294967295
                buf[74] = crc & 255
                buf[75] = crc >> 8 & 255
                buf[76] = crc >> 16 & 255
                buf[77] = crc >> 24 & 255
                self._rumble_seq = self._rumble_seq + 1 & 15
            else:
                buf = bytearray(64)
                buf[0] = 2
                buf[1] = 2
                buf[3] = right_motor
                buf[4] = left_motor
            raw = (ctypes.c_ubyte * len(buf))(*buf)
            written = wintypes.DWORD(0)
            k32.WriteFile(h, raw, len(buf), ctypes.byref(written), None)
        except Exception as e:
            pass

    def _run_session(self):
        with self._lock:
            try:
                self._gamepad = _vg.VDS4Gamepad()
                self._ex_report = _vg_com.DS4_REPORT_EX()
                ctypes.memset(ctypes.byref(self._ex_report), 0, ctypes.sizeof(self._ex_report))
                self._ex_report.Report.bThumbLX = 128
                self._ex_report.Report.bThumbLY = 128
                self._ex_report.Report.bThumbRX = 128
                self._ex_report.Report.bThumbRY = 128
                _vg_com.DS4_SET_DPAD(self._ex_report.Report, _vg_com.DS4_DPAD_DIRECTIONS.DS4_BUTTON_DPAD_NONE)
                self._open_rumble_handle()

                def _on_ds4_notification(client, target, large_motor, small_motor, led_number, user_data):
                    if self._config.get('rumble', True):
                        self._send_rumble(small_motor, large_motor)
                self._gamepad.register_notification(callback=_on_ds4_notification)
            except Exception as e:
                msg = f'ViGEmBus failure: could not create virtual DS4 pad -- {e}'
                self.error_occurred.emit(msg)
                self._crashed = True
                self._gamepad_ready.set()
                self._stop_reason = msg
                return
            self._gamepad_ready.set()
        while True:
            try:
                data = self._feed_q.get(timeout=0.1)
            except queue.Empty:
                if self._stop_event:
                    k32 = _KERNEL32_DLL
                    if k32.WaitForSingleObject(self._stop_event, 0) == 0:
                        self._crashed = False
                        self._stop_reason = 'clean stop requested'
                        break
                continue
            if data is None:
                self._crashed = False
                self._stop_reason = 'clean stop requested'
                break
            self._forward(data)

    def _forward(self, data: bytes):
        if len(data) < 10:
            return
        try:
            rid = data[0]
            gyro_ax = accel_ax = None
            touch_ax = None
            is_ds4 = self._pid in DUALSHOCK4_PIDS
            if rid == 1 and is_ds4:
                if len(data) < 10:
                    return
                lx = data[1]
                ly = data[2]
                rx = data[3]
                ry = data[4]
                b0 = data[5]
                b1 = data[6]
                b2 = data[7] if len(data) > 7 else 0
                l2 = data[8] if len(data) > 8 else 0
                r2 = data[9] if len(data) > 9 else 0
                if len(data) >= 42:
                    gyro_ax, accel_ax, touch_ax = (13, 19, 35)
            elif rid == 17 and is_ds4:
                if len(data) < 12:
                    return
                lx = data[3]
                ly = data[4]
                rx = data[5]
                ry = data[6]
                b0 = data[7]
                b1 = data[8]
                b2 = data[9] if len(data) > 9 else 0
                l2 = data[10] if len(data) > 10 else 0
                r2 = data[11] if len(data) > 11 else 0
                if len(data) >= 44:
                    gyro_ax, accel_ax, touch_ax = (15, 21, 37)
            elif rid == 1:
                if len(data) >= 78:
                    lx = data[1]
                    ly = data[2]
                    rx = data[3]
                    ry = data[4]
                    b0 = data[5]
                    b1 = data[6]
                    b2 = data[7] if len(data) > 7 else 0
                    l2 = 255 if b1 & 4 else 0
                    r2 = 255 if b1 & 8 else 0
                elif len(data) >= 64:
                    lx = data[1]
                    ly = data[2]
                    rx = data[3]
                    ry = data[4]
                    l2 = data[5]
                    r2 = data[6]
                    b0 = data[8]
                    b1 = data[9]
                    b2 = data[10] if len(data) > 10 else 0
                    if self._pid in DUALSENSE_PIDS:
                        gyro_ax, accel_ax, touch_ax = (16, 22, 33)
                elif len(data) >= 10:
                    lx = data[1]
                    ly = data[2]
                    rx = data[3]
                    ry = data[4]
                    l2 = 0
                    r2 = 0
                    b0 = data[5] if len(data) > 5 else 0
                    b1 = data[6] if len(data) > 6 else 0
                    b2 = data[7] if len(data) > 7 else 0
                else:
                    return
            elif rid == 49:
                if len(data) < 42:
                    return
                lx = data[2]
                ly = data[3]
                rx = data[4]
                ry = data[5]
                l2 = data[6]
                r2 = data[7]
                b0 = data[9]
                b1 = data[10]
                b2 = data[11] if len(data) > 11 else 0
                if self._pid in DUALSENSE_PIDS:
                    gyro_ax, accel_ax, touch_ax = (17, 23, 34)
            else:
                return
            dpad_nibble = b0 & 15
            sq = bool(b0 & 16)
            cr = bool(b0 & 32)
            ci = bool(b0 & 64)
            tr = bool(b0 & 128)
            l1 = bool(b1 & 1)
            r1 = bool(b1 & 2)
            shr = bool(b1 & 16)
            opt = bool(b1 & 32)
            l3 = bool(b1 & 64)
            r3 = bool(b1 & 128)
            ps = bool(b2 & 1)
            tpc = bool(b2 & 2)
            l2_digital = l2 > 128
            r2_digital = r2 > 128
            DB = _vg_com.DS4_BUTTONS
            SB = _vg_com.DS4_SPECIAL_BUTTONS
            button_names = {'square': sq, 'cross': cr, 'circle': ci, 'triangle': tr, 'l1': l1, 'r1': r1, 'l3': l3, 'r3': r3, 'back': shr, 'options': opt, 'l2': l2_digital, 'r2': r2_digital}
            dpad_names = {name for pressed, name in ((bool(dpad_nibble in (0, 1, 7)), 'up'), (bool(dpad_nibble in (3, 4, 5)), 'down'), (bool(dpad_nibble in (5, 6, 7)), 'left'), (bool(dpad_nibble in (1, 2, 3)), 'right')) if pressed}
            pressed_names = {name for name, pressed in button_names.items() if pressed} | dpad_names
            if ps:
                pressed_names.add('ps')
            mapped_names = self._mapped_names({name for name in pressed_names})
            ds4_button_map = {'square': DB.DS4_BUTTON_SQUARE, 'cross': DB.DS4_BUTTON_CROSS, 'circle': DB.DS4_BUTTON_CIRCLE, 'triangle': DB.DS4_BUTTON_TRIANGLE, 'l1': DB.DS4_BUTTON_SHOULDER_LEFT, 'r1': DB.DS4_BUTTON_SHOULDER_RIGHT, 'l3': DB.DS4_BUTTON_THUMB_LEFT, 'r3': DB.DS4_BUTTON_THUMB_RIGHT, 'back': DB.DS4_BUTTON_SHARE, 'options': DB.DS4_BUTTON_OPTIONS, 'l2': DB.DS4_BUTTON_TRIGGER_LEFT, 'r2': DB.DS4_BUTTON_TRIGGER_RIGHT}
            btn = sum((bit for name, bit in ds4_button_map.items() if name in mapped_names))
            dpad_flags = ('up' in mapped_names, 'down' in mapped_names, 'left' in mapped_names, 'right' in mapped_names)
            dpad_lookup = {(True, False, False, False): 0, (True, False, False, True): 1, (False, False, False, True): 2, (False, True, False, True): 3, (False, True, False, False): 4, (False, True, True, False): 5, (False, False, True, False): 6, (True, False, True, False): 7}
            mapped_dpad = dpad_lookup.get(dpad_flags, 8)
            special = 0
            if 'ps' in mapped_names:
                special |= SB.DS4_SPECIAL_BUTTON_PS
            if tpc:
                special |= SB.DS4_SPECIAL_BUTTON_TOUCHPAD
            with self._lock:
                gp = self._gamepad
                rep = self._ex_report
                if gp is None or rep is None:
                    return
                r = rep.Report
                r.bThumbLX = self._tune_axis(lx)
                r.bThumbLY = self._tune_axis(ly)
                r.bThumbRX = self._tune_axis(rx, bool(self._config.get('invert_x', False)))
                r.bThumbRY = self._tune_axis(ry, bool(self._config.get('invert_y', False)))
                r.bTriggerL = self._tune_trigger(l2)
                r.bTriggerR = self._tune_trigger(r2)
                r.wButtons = mapped_dpad & 15 | btn & ~15
                r.bSpecial = special
                if gyro_ax is not None:
                    try:
                        r.wGyroX = ctypes.c_short(int.from_bytes(data[gyro_ax:gyro_ax + 2], 'little', signed=True)).value
                        r.wGyroY = ctypes.c_short(int.from_bytes(data[gyro_ax + 2:gyro_ax + 4], 'little', signed=True)).value
                        r.wGyroZ = ctypes.c_short(int.from_bytes(data[gyro_ax + 4:gyro_ax + 6], 'little', signed=True)).value
                        r.wAccelX = ctypes.c_short(int.from_bytes(data[accel_ax:accel_ax + 2], 'little', signed=True)).value
                        r.wAccelY = ctypes.c_short(int.from_bytes(data[accel_ax + 2:accel_ax + 4], 'little', signed=True)).value
                        r.wAccelZ = ctypes.c_short(int.from_bytes(data[accel_ax + 4:accel_ax + 6], 'little', signed=True)).value
                    except Exception:
                        pass
                else:
                    r.wGyroX = r.wGyroY = r.wGyroZ = 0
                    r.wAccelX = r.wAccelY = r.wAccelZ = 0
                self._touch_pkt = self._touch_pkt + 1 & 255
                r.bTouchPacketsN = 1
                cur = r.sCurrentTouch
                cur.bPacketCounter = self._touch_pkt
                touch_slots = [(cur, 'bIsUpTrackingNum1'), (None, None)]
                for slot in (0, 1):
                    active = False
                    tx = ty = 0
                    if touch_ax is not None:
                        base = touch_ax + slot * 4
                        if len(data) >= base + 4:
                            flags = data[base]
                            active = not bool(flags & 128)
                            if active:
                                tx = data[base + 1] | (data[base + 2] & 15) << 8
                                ty_raw = data[base + 2] >> 4 & 15 | data[base + 3] << 4
                                ty = min(942, round(ty_raw * 943 / 1080))
                    if active and (not self._touch_down[slot]):
                        self._touch_id[slot] = self._touch_id[slot] + 1 & 127
                    self._touch_down[slot] = active
                    up_byte = (self._touch_id[slot] & 127) << 1 | (0 if active else 1)
                    data1 = (tx & 255, tx >> 8 & 15 | (ty & 15) << 4, ty >> 4 & 255)
                    if slot == 0:
                        cur.bIsUpTrackingNum1 = up_byte
                        cur.bTouchData1[0] = data1[0]
                        cur.bTouchData1[1] = data1[1]
                        cur.bTouchData1[2] = data1[2]
                    else:
                        cur.bIsUpTrackingNum2 = up_byte
                        cur.bTouchData2[0] = data1[0] | data1[1] << 8
                        cur.bTouchData2[1] = data1[2]
                gp.update_extended_report(rep)
        except Exception as e:
            import traceback

# ---------------------------------------------------------------------
# Hold PS/Home for N seconds while a game is running -> force-close it.
# A quick tap (press+release under that threshold) instead toggles the
# minimize-game-to-launcher view (see _toggle_game_launcher_focus).
# Fed from ControllerSession._hid_loop (Sony pads) and
# GenericHIDSession._hid_loop (generic/Xbox-style pads) since those are
# the threads that see live button state while a game is running (the
# menu-only GamepadWorker is stopped for the duration of the game). The
# main window registers the actual close/toggle callbacks via
# _register_ps_hold_close_callback() / _register_ps_toggle_callback()
# when it starts up.
# ---------------------------------------------------------------------
PS_HOLD_CLOSE_SECONDS = 1.2
# Minimum press duration for a release to count as a "quick tap" (toggle
# minimize). Below this, it's treated as an accidental brush of the button
# and ignored entirely -- neither a tap-toggle nor a hold-close.
PS_TAP_MIN_SECONDS = 0.20
_ps_hold_state: 'dict[str, float]' = {}
_ps_hold_fired: set = set()
_ps_hold_lock = threading.Lock()
_ps_hold_close_callback = [None]
_ps_toggle_callback = [None]
# Set while a game is minimized-to-launcher (see PS5Launcher._minimize_game_to_launcher).
# The game's ControllerEmulationManager session is deliberately kept running
# during that time (so PS-hold-to-close keeps working), but with this flag
# set it stops forwarding raw HID reports to the game's virtual pad --
# otherwise stick/button input would double up: driving the backgrounded
# game AND navigating the launcher menu at the same time.
_game_input_paused = [False]
# When a physical controller is being mirrored into a virtual Xbox pad,
# GamepadWorker must not also poll the virtual XInput device for launcher
# navigation.  The physical HID path is already the authoritative source for
# the launcher's UI; reading both paths turns one press into two actions.
_virtual_xinput_emulation_active = [False]


def _set_game_input_paused(paused: bool):
    _game_input_paused[0] = bool(paused)


def _register_ps_hold_close_callback(callback):
    _ps_hold_close_callback[0] = callback


def _register_ps_toggle_callback(callback):
    _ps_toggle_callback[0] = callback


def _check_ps_hold_and_maybe_close(path: str, ps_pressed: bool):
    fire = False
    tap = False
    with _ps_hold_lock:
        if not ps_pressed:
            start = _ps_hold_state.pop(path, None)
            was_fired = path in _ps_hold_fired
            _ps_hold_fired.discard(path)
            # A press that started and released without ever reaching the
            # hold threshold is a quick tap. If it DID already fire the
            # hold-close, the release is just the end of that hold and
            # should not also register as a tap.
            # While the game is minimized-to-launcher, restoring it should
            # feel instant -- skip the min-hold-duration gate entirely in
            # that case (it exists only to filter accidental brushes of
            # the button while a game is actively running/foregrounded).
            min_seconds = 0.0 if _game_input_paused[0] else PS_TAP_MIN_SECONDS
            if start is not None and not was_fired and (time.monotonic() - start) >= min_seconds:
                tap = True
        else:
            now = time.monotonic()
            start = _ps_hold_state.get(path)
            if start is None:
                _ps_hold_state[path] = now
            elif path not in _ps_hold_fired and now - start >= PS_HOLD_CLOSE_SECONDS:
                _ps_hold_fired.add(path)
                fire = True
    if tap:
        callback = _ps_toggle_callback[0]
        if callback is not None:
            threading.Thread(target=callback, daemon=True, name='PSQuickTapToggle').start()
    elif fire:
        callback = _ps_hold_close_callback[0]
        if callback is not None:
            threading.Thread(target=callback, daemon=True, name='PSHoldForceClose').start()


class ControllerSession:
    MAX_WATCHDOG_RESTARTS = 10

    def __init__(self, path: str, pid: int, mode: str='xbox360', config=None, status_callback=None, passive: bool=False):
        self.path = path
        self.pid = pid
        self._mode = mode
        self._config = dict(config or {})
        self._status_callback = status_callback
        # passive=True: no virtual-pad bridge is created at all (no vgamepad
        # / ViGEmBus dependency, no rumble/LED writes) -- the HID report
        # thread still runs and still feeds _check_ps_hold_and_maybe_close,
        # so PS/Home tap-to-minimize and hold-to-close keep working for a
        # controller that's running in "Native" mode (talking to the game
        # directly), which previously had no launcher-side monitoring at
        # all. See ControllerEmulationManager.start_for_game/_sync_sessions.
        self._passive = bool(passive)
        self._bridge: 'XInputBridge | DS4Bridge | None' = None
        self._hid_thread: 'threading.Thread | None' = None
        self._grab_h: 'int | None' = None
        self._running = False
        self._restart_cnt = 0
        self._watchdog: 'QTimer | None' = None
        self._lock = threading.Lock()

    def start(self):
        with self._lock:
            if self._running:
                return
            self._running = True
            self._restart_cnt = 0
        if not self._passive:
            self._start_bridge()
        self._start_hid_thread()
        if not self._passive:
            self._start_watchdog()
        pid_name = 'DualSense' if self.pid in DUALSENSE_PIDS else 'DualShock 4'

    def stop(self):
        with self._lock:
            if not self._running:
                return
            self._running = False
        self._stop_watchdog()
        self._stop_bridge()
        t = self._hid_thread
        self._release_grab()

    @property
    def is_alive(self) -> bool:
        t = self._hid_thread
        return t is not None and t.is_alive()

    def wait_ready(self, timeout: float=1.5) -> bool:
        """Block until this session's virtual pad has been registered with
        ViGEmBus (or creation has failed). Used by ControllerEmulationManager
        to serialize session startup so XInput assigns player slots in the
        configured player_slot order instead of in whatever order the
        underlying threads happen to win the race to register."""
        bridge = self._bridge
        if bridge is None:
            return False
        return bridge._gamepad_ready.wait(timeout)

    def _start_bridge(self):
        if self._bridge is not None and self._bridge.isRunning():
            self._stop_bridge()
        bridge_config = dict(self._config)
        bridge_config['path'] = self.path
        bridge_config['pid'] = self.pid
        if self._mode == 'ps4':
            self._bridge = DS4Bridge(mode=self._mode, pid=self.pid, path=self.path, config=bridge_config)
        else:
            self._bridge = XInputBridge(mode=self._mode, config=bridge_config)
            try:
                self._bridge.set_source_pid(self.pid)
            except Exception:
                pass
        self._bridge.error_occurred.connect(self._on_bridge_error)
        self._bridge.start()

    def _stop_bridge(self):
        bridge = self._bridge
        self._bridge = None
        if bridge is None:
            return
        bridge.stop()
        if not bridge.wait(3000):
            bridge.terminate()
            bridge.wait(1000)

    def _start_hid_thread(self):
        # Passive (Native-mode) sessions never write to the device (no
        # rumble/LED, no virtual pad to drive) -- skip requesting a write
        # handle at all so the launcher touches the device in a strictly
        # read-only capacity while the game owns it.
        if not self._passive:
            self._grab_h = self._open_write_grab()
        t = threading.Thread(target=self._hid_loop, name=f'ControllerSession-hid-{self.path[-20:]}', daemon=True)
        self._hid_thread = t
        t.start()

    def _hid_loop(self):
        k32 = _KERNEL32_DLL
        FILE_FLAG_OVERLAPPED = 1073741824
        h = INVALID_HANDLE
        GENERIC_WRITE = 1073741824
        open_attempts = [(GENERIC_READ, 0), (GENERIC_READ, FILE_FLAG_OVERLAPPED), (0, 0)] if self._passive else [(GENERIC_READ | GENERIC_WRITE, 0), (GENERIC_READ, 0), (GENERIC_READ, FILE_FLAG_OVERLAPPED), (0, 0)]
        for access, flags in open_attempts:
            h = k32.CreateFileW(self.path, access, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, flags, None)
            if h != INVALID_HANDLE:
                break
        if h == INVALID_HANDLE:
            err = ctypes.get_last_error()
            for retry in range(8):
                time.sleep(0.1)
                for access, flags in open_attempts:
                    h = k32.CreateFileW(self.path, access, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, flags, None)
                    if h != INVALID_HANDLE:
                        break
                if h != INVALID_HANDLE:
                    break
            if h == INVALID_HANDLE:
                err = ctypes.get_last_error()
                return
        # Passive (Native-profile) sessions must NOT write anything to the
        # device -- the whole point of Native is that the game owns the
        # controller directly and gets its raw, untouched report stream.
        # _ds_kick_full_report_mode() sends a WriteFile output report
        # (report 0x31, "enable extended features") to force the pad into
        # its full/extended HID report mode purely so *this launcher* can
        # read stick/gyro/touchpad data -- but _parse_hid() already
        # understands the short report (0x01) fine for everything this
        # passive thread actually needs (the PS/Home bit, for tap/hold
        # minimize-close). Sending that kick anyway was fighting the game
        # for the controller's report mode: with a game that itself
        # negotiates/expects a particular report format, this launcher's
        # write could flip it out from under the game mid-session -- and
        # with two controllers connected, both sessions do this
        # concurrently, doubling the chance of a mode flip landing while
        # the game is mid-read. That's what was shifting/losing L1/L2/R1/R2
        # (their bits/bytes sit at different offsets between report
        # formats) while other buttons kept working.
        if not self._passive:
            _ds_kick_full_report_mode(h, self.pid)
        buf = ctypes.create_string_buffer(256)
        rdw = wintypes.DWORD(0)
        try:
            while self._running:
                ok = k32.ReadFile(h, buf, 256, ctypes.byref(rdw), None)
                if not ok:
                    err = ctypes.get_last_error()
                    break
                if rdw.value == 0:
                    continue
                raw = buf.raw[:rdw.value]
                bridge = self._bridge
                if bridge is not None and not _game_input_paused[0]:
                    try:
                        bridge.feed(raw)
                    except Exception:
                        pass
                try:
                    _check_ps_hold_and_maybe_close(self.path, 'ps' in _parse_hid(raw, self.pid))
                except Exception:
                    pass
        except Exception as e:
            pass
        finally:
            k32.CloseHandle(h)

    def _open_write_grab(self) -> 'int | None':
        k32 = _KERNEL32_DLL
        GENERIC_WRITE = 1073741824
        FILE_SHARE_READ = 1
        FILE_SHARE_WRITE = 2
        OPEN_EXISTING = 3
        _prev = k32.CreateFileW.restype
        k32.CreateFileW.restype = ctypes.c_void_p
        try:
            h = k32.CreateFileW(self.path, GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, 0, None)
        finally:
            k32.CreateFileW.restype = _prev
        invalid = ctypes.c_void_p(-1).value
        if h is None or h == invalid:
            err = k32.GetLastError()
            return None
        return h

    def _release_grab(self):
        if self._grab_h is not None:
            _KERNEL32_DLL.CloseHandle(self._grab_h)
            self._grab_h = None

    def _start_watchdog(self):
        self._watchdog = QTimer()
        self._watchdog.setInterval(5000)
        self._watchdog.timeout.connect(self._check_bridge)
        self._watchdog.start()

    def _stop_watchdog(self):
        if self._watchdog:
            self._watchdog.stop()
            self._watchdog = None

    def _check_bridge(self):
        if self._bridge is None or not self._running:
            return
        if self._bridge.isRunning():
            return
        reason = self._bridge.stop_reason or 'unknown'
        crashed = self._bridge.crashed
        if not crashed:
            self._emit_status('Bridge Stopped')
            self._stop_watchdog()
            return
        if self._restart_cnt >= self.MAX_WATCHDOG_RESTARTS:
            self._emit_status('Bridge Stopped: restart limit reached')
            self._stop_watchdog()
            return
        self._restart_cnt += 1
        self._emit_status(f'Bridge Restarting ({self._restart_cnt}/{self.MAX_WATCHDOG_RESTARTS})')
        self._bridge = None
        self._start_bridge()

    def _on_bridge_error(self, msg: str):
        self._emit_status(str(msg))

    def _emit_status(self, message: str):
        callback = self._status_callback
        if callback is not None:
            try:
                callback(self.path, str(message))
            except Exception:
                pass

    def tap_options(self) -> bool:
        """Sends a synthetic Options tap through this session's virtual
        pad (whatever kind of bridge it happens to be). Returns True if a
        tap was actually sent."""
        bridge = self._bridge
        if bridge is None or self._passive:
            return False
        try:
            if isinstance(bridge, DS4Bridge):
                bridge.tap_options_button()
            else:
                bridge.tap_start_button()
            return True
        except Exception:
            return False

class GenericHIDSession:

    def __init__(self, path: str, vid: int, pid: int, config=None, status_callback=None, passive: bool=False):
        self.path = path
        self.vid = vid
        self.pid = pid
        self.config = dict(config or {})
        self._status_callback = status_callback
        # See ControllerSession.__init__ for what passive mode means: no
        # GenericHIDBridge/virtual pad is created, just the read-only report
        # loop that keeps PS/Home tap-and-hold detection alive for a
        # controller running in "Native" mode.
        self._passive = bool(passive)
        self._bridge = None
        self._thread = None
        self._handle = None
        self._preparsed = None
        self._running = False
        self._lock = threading.Lock()

    def start(self):
        with self._lock:
            if self._running:
                return
            self._running = True
        if not self._passive:
            self._bridge = GenericHIDBridge(config=self.config)
        if self._status_callback:
            try:
                self._status_callback(self.path, 'Reading Input' if not self._passive else 'Native Input')
            except Exception:
                pass
        if self._bridge is not None:
            self._bridge.start()
        self._thread = threading.Thread(target=self._hid_loop, name=f'GenericHIDSession-{self.path[-20:]}', daemon=True)
        self._thread.start()

    def stop(self):
        with self._lock:
            self._running = False
            h = self._handle
            self._handle = None
        if self._bridge is not None:
            self._bridge.stop()
        if h not in (None, INVALID_HANDLE):
            try:
                _KERNEL32_DLL.CloseHandle(h)
            except Exception:
                pass
        thread = self._thread
        if thread is not None and thread is not threading.current_thread():
            thread.join(timeout=1.0)
        bridge = self._bridge
        if bridge is not None and bridge.isRunning():
            bridge.wait(1000)
        self._bridge = None

    @property
    def is_alive(self):
        thread = self._thread
        return bool(thread is not None and thread.is_alive())

    def wait_ready(self, timeout: float=1.5) -> bool:
        bridge = self._bridge
        if bridge is None:
            return False
        return bridge._gamepad_ready.wait(timeout)

    def _hid_loop(self):
        opened = _hid_open_preparsed(self.path)
        if not opened:
            with self._lock:
                self._running = False
            if self._status_callback:
                self._status_callback(self.path, 'Device Disconnected')
            return
        h, preparsed, caps = opened
        with self._lock:
            self._handle = h
            self._preparsed = preparsed
        try:
            layout = _hid_generic_layout(preparsed)
            report_len = max(int(caps.InputReportByteLength), 1)
            buf = ctypes.create_string_buffer(report_len)
            read_count = wintypes.DWORD(0)
            while True:
                with self._lock:
                    running = self._running
                if not running:
                    break
                ok = _KERNEL32_DLL.ReadFile(h, buf, report_len, ctypes.byref(read_count), None)
                if not ok or read_count.value == 0:
                    break
                state = _read_generic_state(preparsed, buf.raw[:read_count.value], layout)
                bridge = self._bridge
                if bridge is not None and not _game_input_paused[0]:
                    bridge.feed(state)
                try:
                    _check_ps_hold_and_maybe_close(self.path, 'ps' in state.get('buttons', ()))
                except Exception:
                    pass
        except Exception as exc:
            if self._status_callback:
                self._status_callback(self.path, f'Bridge Error: {exc}')
        finally:
            try:
                _HID_DLL.HidD_FreePreparsedData(preparsed)
            except Exception:
                pass
            with self._lock:
                self._preparsed = None
                self._running = False
            with self._lock:
                handle_owned = self._handle is h
                if handle_owned:
                    self._handle = None
            if handle_owned:
                try:
                    _KERNEL32_DLL.CloseHandle(h)
                except Exception:
                    pass

    def tap_options(self) -> bool:
        """See ControllerSession.tap_options."""
        bridge = self._bridge
        if bridge is None or self._passive:
            return False
        try:
            bridge.tap_start_button()
            return True
        except Exception:
            return False

class ControllerEmulationManager:
    _instance: 'ControllerEmulationManager | None' = None
    debug: bool = False

    def __init__(self):
        self._sessions: 'dict[str, ControllerSession]' = {}
        self._generic_sessions: 'dict[str, GenericHIDSession]' = {}
        self._sessions_lock = threading.Lock()
        self._mode: str = 'xbox360'
        self._active_app: 'dict | None' = None
        self._scan_timer: 'QTimer | None' = None
        self._vgamepad_retry_failed_this_session = False
        self._controller_profiles = {}
        self._bridge_status = {}
        self._bridge_error_count = 0
        self._restore_count = 0
        # True while the active game's controller profile is "Native" (no
        # virtual-pad emulation at all). Sessions started while this is set
        # are passive/read-only monitors: see start_for_game/_sync_sessions.
        self._passive_mode = False

    @classmethod
    def instance(cls) -> 'ControllerEmulationManager':
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    def _emulation_candidates(self):
        generic_candidates = []
        sony_devices = _hid_find_all_sony(collect_generic=generic_candidates)
        if self._xinput_device_present():
            generic_candidates = [item for item in generic_candidates if not _looks_like_xinput_hid(item)]
        return (sony_devices, generic_candidates)

    def _generic_bridge_config(self):
        values = dict(getattr(self, '_gamepad_settings', {}) or {})
        return {'deadzone': float(values.get('gamepad_deadzone', 8)) / 100.0, 'sensitivity': float(values.get('gamepad_sensitivity', 100)) / 100.0, 'trigger_deadzone': float(values.get('gamepad_trigger_deadzone', 4)) / 100.0, 'invert_x': bool(values.get('gamepad_invert_x', False)), 'invert_y': bool(values.get('gamepad_invert_y', False)), 'mapping': dict(values.get('gamepad_mapping', {}) or {}), 'rumble': bool(values.get('gamepad_rumble', True)), 'device': str(values.get('gamepad_device', 'auto'))}

    def _device_config(self, path='', vid=0, pid=0, name='controller'):
        source_data = getattr(self, '_launcher_data', {}) or {}
        self._controller_profiles = dict(source_data.get('controller_profiles', {}) or {})
        config = self._generic_bridge_config()
        profile = _controller_profile_for({'controller_profiles': self._controller_profiles}, path, vid, pid, name)
        if profile:
            config.update({'deadzone': float(profile.get('deadzone', config['deadzone'] * 100)) / 100.0, 'sensitivity': float(profile.get('sensitivity', config['sensitivity'] * 100)) / 100.0, 'trigger_deadzone': float(profile.get('trigger_deadzone', config['trigger_deadzone'] * 100)) / 100.0, 'invert_x': bool(profile.get('invert_x', config['invert_x'])), 'invert_y': bool(profile.get('invert_y', config['invert_y'])), 'mapping': dict(profile.get('mapping') or config['mapping']), 'rumble': bool(profile.get('rumble', config['rumble'])), 'output': profile.get('output', config.get('output', 'auto'))})
        routing = dict((getattr(self, '_active_app', {}) or {}).get('controller_routing') or {})
        selected_controller = str(routing.get('physical_controller', '') or '')
        if selected_controller and selected_controller != path:
            config['output'] = 'disabled'
        if routing.get('input_type') in ('native', 'xinput', 'directinput', 'generic_hid', 'disabled', 'custom'):
            config['input_type'] = routing['input_type']
        if routing.get('output') in ('native', 'xbox360', 'ps4', 'disabled', 'custom'):
            config['output'] = routing['output']
        if 'rumble_enabled' in routing:
            config['rumble'] = bool(routing['rumble_enabled'])
        config['routing_delay_ms'] = max(0, int(routing.get('delay_ms', 0) or 0))
        config['player_slot'] = max(1, min(4, int(routing.get('player_slot', 1) or 1)))
        return config

    def _on_session_status(self, path, message):
        self._bridge_status[str(path)] = str(message)
        if 'error' in str(message).lower() or 'missing' in str(message).lower():
            self._bridge_error_count += 1

    def status_snapshot(self):
        with self._sessions_lock:
            active = len(self._sessions) + len(self._generic_sessions)
        values = list(self._bridge_status.values())
        if not active:
            state = 'Bridge Stopped'
        elif not _VGAMEPAD_OK:
            state = 'vgamepad Missing'
        elif any(('error' in value.lower() for value in values)):
            state = values[-1]
        else:
            state = values[-1] if values else 'Virtual Xbox Active'
        return {'state': state, 'active_sessions': active, 'vgamepad': bool(_VGAMEPAD_OK), 'vigembus': bool(DriverManager.instance().is_installed()), 'errors': int(self._bridge_error_count)}

    def tap_options_for_active_game(self) -> bool:
        """Sends a synthetic Options button tap through every active
        virtual pad session. Most games open their pause menu (and mute
        their own audio) in response to Options/Start, so calling this
        right before the launcher minimizes a running game gets both
        effects "for free" without needing to know anything about the
        specific game. Returns True if at least one session actually sent
        a tap (i.e. there's something worth waiting for before minimizing)."""
        with self._sessions_lock:
            sessions = list(self._sessions.values()) + list(self._generic_sessions.values())
        tapped_any = False
        for session in sessions:
            try:
                if session.tap_options():
                    tapped_any = True
            except Exception:
                pass
        return tapped_any

    def prepare_vgamepad_for_game(self, app: dict, callback) -> bool:
        profile = ProfileManager.get(app)
        if profile in ('disabled', 'native') or _VGAMEPAD_OK:
            return True
        try:
            sony_devices, generic_candidates = self._emulation_candidates()
            if not sony_devices and (not generic_candidates):
                return True
        except Exception as exc:
            pass
        try:
            package_present = importlib.util.find_spec('vgamepad') is not None
        except Exception:
            package_present = False
        if package_present:
            return True
        global _VGAMEPAD_INSTALLING, _VGAMEPAD_INSTALL_ATTEMPTED
        with _VGAMEPAD_INSTALL_LOCK:
            if _VGAMEPAD_INSTALLING:
                _VGAMEPAD_INSTALL_CALLBACKS.append(callback)
                return False
            if _VGAMEPAD_INSTALL_ATTEMPTED:
                callback(False, 'Automatic vgamepad installation already failed during this session.')
                return False
            _VGAMEPAD_INSTALLING = True
            _VGAMEPAD_INSTALL_ATTEMPTED = True
            _VGAMEPAD_INSTALL_CALLBACKS.append(callback)

        def _worker():
            global _VGAMEPAD_INSTALLING
            ok, message = _install_vgamepad_package()
            if ok:
                ok = _refresh_vgamepad_import()
                if not ok:
                    message = 'vgamepad was installed, but its native ViGEm binding could not be loaded. The ViGEmBus driver may be missing or may require a restart.'
            with _VGAMEPAD_INSTALL_LOCK:
                callbacks = list(_VGAMEPAD_INSTALL_CALLBACKS)
                _VGAMEPAD_INSTALL_CALLBACKS.clear()
                _VGAMEPAD_INSTALLING = False
            for pending_callback in callbacks:
                _UI_INVOKER.invoke(lambda cb=pending_callback, ready=ok, msg=message: cb(ready, msg))
        threading.Thread(target=_worker, daemon=True, name='vgamepad-auto-install').start()
        return False

    def start_for_game(self, app: dict):
        self.stop_for_game()
        profile = ProfileManager.get(app)
        title = app.get('title', '')
        settings = dict(getattr(self, '_gamepad_settings', {}) or {})
        if profile == 'auto':
            global_output = str(settings.get('gamepad_output', 'auto'))
            if global_output in ('native', 'disabled', 'ps4', 'xbox360', 'xboxone'):
                profile = global_output
        global _CTRL_DEBUG, _vg, _vg_com, _VGAMEPAD_OK, _VGAMEPAD_IMPORT_ERROR
        _CTRL_DEBUG = True
        ControllerEmulationManager.debug = True
        self._passive_mode = False
        if profile == 'disabled':
            return
        if profile == 'native':
            # No virtual-pad emulation for this game -- the physical
            # controller talks to the game directly. We still start
            # read-only "passive" HID sessions here (no vgamepad/ViGEmBus
            # dependency at all) purely so PS/Home tap-to-minimize and
            # hold-to-close keep working, exactly as they do for
            # emulated/bridged games. Without this, native-input games got
            # no PS/Home monitoring whatsoever.
            self._passive_mode = True
            self._mode = 'xbox360'
            self._active_app = app
            self._launcher_data = getattr(self, '_launcher_data', {}) or {}
            self._sync_sessions()
            self._start_scan_timer()
            return
        try:
            sony_preview, generic_preview = self._emulation_candidates()
        except Exception as exc:
            sony_preview, generic_preview = ([], [])

        def _fall_back_to_passive():
            # Full virtual-pad emulation isn't available right now (no
            # vgamepad / no ViGEmBus / import failed / no controller
            # detected yet), but PS/Home tap-to-minimize and hold-to-close
            # are a safety hotkey, not an emulation feature -- they must
            # not depend on ViGEm succeeding. Fall back to the same
            # passive, read-only monitoring used for the Native profile
            # instead of returning with zero monitoring. If a controller
            # is plugged in later, or emulation becomes available on a
            # later launch, the periodic scan (_sync_sessions, via the
            # timer we still start here) picks it up.
            self._passive_mode = True
            _virtual_xinput_emulation_active[0] = False
            self._mode = 'xbox360'
            self._active_app = app
            self._launcher_data = getattr(self, '_launcher_data', {}) or {}
            self._sync_sessions()
            self._start_scan_timer()

        if not _VGAMEPAD_OK and self._vgamepad_retry_failed_this_session:
            _fall_back_to_passive()
            return
        if not _VGAMEPAD_OK:
            try:
                importlib.invalidate_caches()
            except Exception:
                pass
            _vg, _vg_com, _VGAMEPAD_OK, _VGAMEPAD_IMPORT_ERROR = _try_import_vgamepad()
            if not _VGAMEPAD_OK:
                self._vgamepad_retry_failed_this_session = True
                _fall_back_to_passive()
                return
        if not DriverManager.instance().is_installed():
            _fall_back_to_passive()
            return
        if profile == 'auto':
            self._mode = 'xbox360'
        elif profile == 'ps4':
            self._mode = 'ps4'
        elif profile == 'xboxone':
            self._mode = 'xboxone'
        else:
            self._mode = 'xbox360'
        # Xbox emulation creates a virtual XInput device while the physical
        # HID device remains readable by GamepadWorker.  Use only the physical
        # source for launcher navigation; the virtual source belongs to the
        # game and must not be fed back into the launcher.
        _virtual_xinput_emulation_active[0] = self._mode in ('xbox360', 'xboxone')
        self._active_app = app
        self._launcher_data = getattr(self, '_launcher_data', {}) or {}
        self._sync_sessions()
        self._start_scan_timer()
        with self._sessions_lock:
            n_sessions = len(self._sessions) + len(self._generic_sessions)

    def stop_for_game(self):
        self._stop_scan_timer()
        self._active_app = None
        _virtual_xinput_emulation_active[0] = False
        self._bridge_status = {}
        self._passive_mode = False
        with self._sessions_lock:
            sessions = dict(self._sessions)
            self._sessions.clear()
            generic_sessions = dict(self._generic_sessions)
            self._generic_sessions.clear()
        for path, session in sessions.items():
            try:
                session.stop()
            except Exception as e:
                pass
        for path, session in generic_sessions.items():
            try:
                session.stop()
            except Exception as e:
                pass

    def close(self):
        self.stop_for_game()

    def _sync_sessions(self):
        if self._active_app is None:
            return
        generic_candidates = []
        connected = _hid_find_all_sony(collect_generic=generic_candidates)
        # A single physical DualSense/DualShock can expose more than one HID
        # collection that passes the gamepad-usage filter (e.g. multiple
        # `colNN` collections of the same Bluetooth device). Without
        # collapsing those back to one entry per physical pad, each extra
        # collection got its own ControllerSession -> its own virtual
        # ViGEm pad mirroring the same physical button presses, so every
        # key press showed up twice once more than one pad's worth of
        # sessions were active. _hid_family_key() strips the `colNN`
        # suffix, so collections of the same physical device collapse to
        # the same key; sort first so the chosen representative path is
        # stable across scans instead of flip-flopping.
        seen_families = set()
        deduped = []
        for path, pid in sorted(connected, key=lambda item: item[0]):
            family = _hid_family_key(path) or path
            if family in seen_families:
                continue
            seen_families.add(family)
            deduped.append((path, pid))
        connected = deduped
        connected_paths = {path for path, _ in connected}
        generic_map = {item['path']: item for item in generic_candidates if item.get('path')}
        selected_device = str((getattr(self, '_gamepad_settings', {}) or {}).get('gamepad_device', 'auto'))
        if '|' in selected_device:
            device_kind, selected_path = selected_device.split('|', 1)
            if device_kind == 'sony':
                connected = [(path, pid) for path, pid in connected if path == selected_path]
                connected_paths = {path for path, _ in connected}
                generic_map.clear()
            elif device_kind == 'hid':
                connected = []
                connected_paths = set()
                generic_map = {path: item for path, item in generic_map.items() if path == selected_path}
        with self._sessions_lock:
            existing_paths = set(self._sessions.keys())
            existing_generic_paths = set(self._generic_sessions.keys())
        removed = existing_paths - connected_paths
        for path in removed:
            with self._sessions_lock:
                session = self._sessions.pop(path, None)
            if session:
                try:
                    session.stop()
                except Exception as e:
                    pass
        removed_generic = existing_generic_paths - set(generic_map)
        for path in removed_generic:
            with self._sessions_lock:
                session = self._generic_sessions.pop(path, None)
            if session:
                try:
                    session.stop()
                except Exception as e:
                    pass
        with self._sessions_lock:
            dead = [p for p, s in self._sessions.items() if not s.is_alive]
        for path in dead:
            with self._sessions_lock:
                session = self._sessions.pop(path, None)
            if session:
                try:
                    session.stop()
                except Exception as e:
                    pass
        with self._sessions_lock:
            dead_generic = [path for path, session in self._generic_sessions.items() if not session.is_alive]
        for path in dead_generic:
            with self._sessions_lock:
                session = self._generic_sessions.pop(path, None)
            if session:
                try:
                    session.stop()
                except Exception:
                    pass
        # Build the list of newly-connected pads that need a session, but
        # don't start them yet -- XInput hands out player slots (1..4) in
        # the order each virtual pad is registered with ViGEmBus, which
        # happens on each session's own worker thread. If we just fire all
        # sessions off together (as this used to do, sony pads first and
        # generic pads second, each in arbitrary dict-iteration order), the
        # OS thread scheduler decides who wins the race to register first --
        # not the "Player slot" the user configured per controller/game.
        # That's what caused controllers to come up "mixed" once a game
        # actually started (wrong pad driving player 1, wrong face-button
        # layout for that player, etc.). We now resolve every candidate's
        # config up front, sort by the configured player_slot, and start
        # sessions one at a time -- waiting for each virtual pad to finish
        # registering (plus any configured handoff delay) before starting
        # the next -- so slots come up in the intended order.
        added = connected_paths - existing_paths
        xinput_present = self._xinput_device_present()
        generic_added = set(generic_map) - existing_generic_paths
        pending = []
        for path, pid in connected:
            if path not in added:
                continue
            device_config = self._device_config(path, 0, pid, 'DualSense' if pid in DUALSENSE_PIDS else 'DualShock 4')
            device_output = str(device_config.get('output', 'auto') or 'auto')
            if device_output == 'disabled':
                self._on_session_status(path, 'Bridge Disabled by Profile')
                continue
            if device_output == 'native' or self._passive_mode:
                # This specific pad is routed to Native output (or the
                # whole game is in Native profile) -- start a passive,
                # read-only session so PS/Home tap+hold still works,
                # without creating any virtual pad for it.
                self._on_session_status(path, 'Native Input')
                session = ControllerSession(path=path, pid=pid, mode=self._mode, config=device_config, status_callback=self._on_session_status, passive=True)
                with self._sessions_lock:
                    self._sessions[path] = session
                try:
                    session.start()
                except Exception:
                    with self._sessions_lock:
                        self._sessions.pop(path, None)
                continue
            pending.append({'kind': 'sony', 'path': path, 'pid': pid, 'config': device_config, 'slot': int(device_config.get('player_slot', 1) or 1)})
        for path, item in generic_map.items():
            if path not in generic_added:
                continue
            if xinput_present and _looks_like_xinput_hid(item):
                continue
            device_config = self._device_config(path, int(item.get('vid', 0)), int(item.get('pid', 0)), str(item.get('name') or 'Generic HID'))
            device_output = str(device_config.get('output', 'auto') or 'auto')
            if device_output == 'disabled':
                self._on_session_status(path, 'Bridge Disabled by Profile')
                continue
            if device_output == 'native' or self._passive_mode:
                self._on_session_status(path, 'Native Input')
                session = GenericHIDSession(path, int(item.get('vid', 0)), int(item.get('pid', 0)), config=device_config, status_callback=self._on_session_status, passive=True)
                with self._sessions_lock:
                    self._generic_sessions[path] = session
                try:
                    session.start()
                except Exception:
                    with self._sessions_lock:
                        self._generic_sessions.pop(path, None)
                continue
            pending.append({'kind': 'generic', 'path': path, 'vid': int(item.get('vid', 0)), 'pid': int(item.get('pid', 0)), 'config': device_config, 'slot': int(device_config.get('player_slot', 1) or 1)})
        pending.sort(key=lambda entry: entry['slot'])
        for entry in pending:
            device_config = entry['config']
            path = entry['path']
            if entry['kind'] == 'sony':
                pid = entry['pid']
                device_output = str(device_config.get('output', 'auto') or 'auto')
                session_mode = 'ps4' if device_output == 'ps4' else self._mode
                session = ControllerSession(path=path, pid=pid, mode=session_mode, config=device_config, status_callback=self._on_session_status)
                with self._sessions_lock:
                    self._sessions[path] = session
                try:
                    session.start()
                except Exception:
                    with self._sessions_lock:
                        self._sessions.pop(path, None)
                    continue
            else:
                session = GenericHIDSession(path, entry['vid'], entry['pid'], config=device_config, status_callback=self._on_session_status)
                with self._sessions_lock:
                    self._generic_sessions[path] = session
                try:
                    session.start()
                except Exception:
                    with self._sessions_lock:
                        self._generic_sessions.pop(path, None)
                    continue
            # Wait for this pad to actually register with ViGEmBus before
            # moving on to the next one, so the next session's pad claims
            # the next XInput slot instead of racing this one for it.
            session.wait_ready(timeout=1.5)
            extra_delay = max(0, int(device_config.get('routing_delay_ms', 0) or 0)) / 1000.0
            if extra_delay:
                time.sleep(min(extra_delay, 2.0))
        with self._sessions_lock:
            n = len(self._sessions) + len(self._generic_sessions)
        if n > 0:
            pass

    def _start_scan_timer(self):
        self._scan_timer = QTimer()
        self._scan_timer.setInterval(2000)
        self._scan_timer.timeout.connect(self._sync_sessions)
        self._scan_timer.start()

    def _stop_scan_timer(self):
        if self._scan_timer:
            self._scan_timer.stop()
            self._scan_timer = None

    def _xinput_device_present(self) -> bool:
        if _XINPUT is None:
            return False
        try:
            st = _XI_STATE()
            for port in range(4):
                if _XINPUT.XInputGetState(port, ctypes.byref(st)) == 0:
                    return True
        except Exception:
            pass
        return False
_NORMAL_GP_KEY_MAP = {'up': (Qt.Key.Key_Backtab, Qt.KeyboardModifier.ShiftModifier), 'down': (Qt.Key.Key_Tab, Qt.KeyboardModifier.NoModifier), 'left': (Qt.Key.Key_Left, Qt.KeyboardModifier.NoModifier), 'right': (Qt.Key.Key_Right, Qt.KeyboardModifier.NoModifier), 'cross': (Qt.Key.Key_Return, Qt.KeyboardModifier.NoModifier), 'circle': (Qt.Key.Key_Escape, Qt.KeyboardModifier.NoModifier), 'square': (Qt.Key.Key_Space, Qt.KeyboardModifier.NoModifier)}

def _send_normal_gamepad_key(dialog: QWidget, btn: str):
    mapping = _NORMAL_GP_KEY_MAP.get(btn)
    if mapping is None:
        return
    widget = QApplication.focusWidget() or dialog
    key, mods = mapping
    press = QKeyEvent(QEvent.Type.KeyPress, key, mods)
    release = QKeyEvent(QEvent.Type.KeyRelease, key, mods)
    QApplication.sendEvent(widget, press)
    QApplication.sendEvent(widget, release)
