def _paint_shared_dialog_surface(p: QPainter, rect: QRectF, radius: float=_DIALOG_GLASS_RADIUS, dark: bool=False, source_widget=None, black_tint_alpha: int=58):
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    path = QPainterPath()
    path.addRoundedRect(rect, radius, radius)
    # Every dialog uses the same opaque, near-black rounded surface.  The
    # old glass/frosted variants made settings, popups and message windows
    # look like two different themes and also drew a faint outline.
    p.fillPath(path, QColor(9, 12, 20, 255))
    p.setBrush(Qt.BrushStyle.NoBrush)

def _first_non_popup_ancestor(win):
    seen = set()
    while win is not None and id(win) not in seen:
        seen.add(id(win))
        is_popup = isinstance(win, QMenu) or bool(win.windowFlags() & Qt.WindowType.Popup)
        if not is_popup:
            return win
        nxt_parent = win.parentWidget()
        win = nxt_parent.window() if nxt_parent is not None else None
    return win

def _frosted_source_window(widget):
    if widget is None:
        return None
    popup_window = widget.window()
    if popup_window is not widget:
        parent = popup_window.parentWidget()
        if parent is not None and parent.window() is not popup_window:
            return _first_non_popup_ancestor(parent.window())
        return popup_window
    parent = widget.parentWidget()
    while parent is not None:
        if parent.window() is not popup_window:
            return _first_non_popup_ancestor(parent.window())
        parent = parent.parentWidget()
    if popup_window.parentWidget() is not None:
        parent_window = popup_window.parentWidget().window()
        if parent_window is not popup_window:
            return _first_non_popup_ancestor(parent_window)
    app = QApplication.instance()
    if app is not None:
        active = app.activeWindow()
        if active is not None and active is not popup_window:
            return _first_non_popup_ancestor(active.window())
        for candidate in app.topLevelWidgets():
            if candidate is not popup_window and candidate.isVisible():
                return _first_non_popup_ancestor(candidate.window())
    return None
_FROSTED_CAPTURE_BUSY = [False]

def _capture_frosted_backdrop(widget, rect: QRectF, blur: bool=True):
    source = _frosted_source_window(widget)
    if source is None or source.width() <= 0 or source.height() <= 0:
        return None
    if _FROSTED_CAPTURE_BUSY[0] or source.property('_frosted_capture_active'):
        return None
    _FROSTED_CAPTURE_BUSY[0] = True
    source.setProperty('_frosted_capture_active', True)
    hidden_widget = False
    try:
        if source is widget.window() and widget is not source and widget.isVisible():
            widget.setVisible(False)
            hidden_widget = True
        shot = source.grab()
        if shot.isNull():
            return None
        popup_pos = widget.mapToGlobal(QPoint(0, 0))
        source_pos = source.mapToGlobal(QPoint(0, 0))
        dpr = max(1.0, float(shot.devicePixelRatio()))
        x = max(0, int((popup_pos.x() - source_pos.x()) * dpr))
        y = max(0, int((popup_pos.y() - source_pos.y()) * dpr))
        w = max(1, int(rect.width() * dpr))
        h = max(1, int(rect.height() * dpr))
        if x >= shot.width() or y >= shot.height():
            return None
        crop = shot.copy(x, y, min(w, shot.width() - x), min(h, shot.height() - y))
        crop.setDevicePixelRatio(dpr)
        return _blurred_pixmap(crop, radius=18) if blur else crop
    except Exception:
        return None
    finally:
        if hidden_widget:
            widget.setVisible(True)
        source.setProperty('_frosted_capture_active', False)
        _FROSTED_CAPTURE_BUSY[0] = False


def _paint_pre_settings_dialog_surface(p: QPainter, rect: QRectF, radius: float=_DIALOG_GLASS_RADIUS, source_widget=None, black_tint_alpha: int=58, flat_glass_alpha: int=None):
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    path = QPainterPath()
    path.addRoundedRect(rect, radius, radius)
    # Glassy surface: draw a blurred capture of whatever is behind this
    # widget (the app background/wallpaper), then lay a translucent dark
    # tint over it so text stays readable but a faint halo of the image
    # behind still shows through. Falls back to the old solid fill if a
    # backdrop capture isn't available (e.g. widget not yet on screen).
    p.save()
    p.setClipPath(path)
    backdrop = _capture_frosted_backdrop(source_widget, rect, blur=True) if source_widget is not None else None
    if backdrop is not None:
        p.drawPixmap(rect.toRect(), backdrop)
    else:
        p.fillPath(path, QColor(9, 12, 20, 255))
    p.fillPath(path, QColor(9, 12, 20, black_tint_alpha))
    if flat_glass_alpha:
        p.fillPath(path, QColor(255, 255, 255, flat_glass_alpha))
    p.restore()
    p.setBrush(Qt.BrushStyle.NoBrush)

