def _apply_shared_dialog_shape(widget, radius: int=_DIALOG_GLASS_RADIUS):
    if widget.width() <= 0 or widget.height() <= 0:
        return
    path = QPainterPath()
    path.addRoundedRect(QRectF(widget.rect()), radius, radius)
    widget.setMask(QRegion(path.toFillPolygon().toPolygon()))

class _SharedGlassFrame(QFrame):

    def __init__(self, parent=None, radius: int=_DIALOG_GLASS_RADIUS):
        super().__init__(parent)
        self._glass_radius = radius
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setStyleSheet('QFrame{background:transparent;border:none;}')

    def paintEvent(self, event):
        p = QPainter(self)
        _paint_shared_dialog_surface(p, QRectF(self.rect()), radius=self._glass_radius, source_widget=self)
        p.end()
        _apply_shared_dialog_shape(self, self._glass_radius)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        _apply_shared_dialog_shape(self, self._glass_radius)

