    def _build(self, current_text: str):
        outer = QVBoxLayout(self)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(0)
        top = QFrame()
        top.setFixedHeight(44)
        top.setStyleSheet('QFrame{background:transparent;border:none;}')
