        self._list = QListWidget()
        self._list.setFont(QFont('Segoe UI', 11))
        self._list.setFixedHeight(200)
        self._list.setVerticalScrollMode(QListWidget.ScrollMode.ScrollPerPixel)
        self._list.setStyleSheet(_dialog_list_qss())
        self._list.addItem('🏠  ' + self._NO_FOLDER_LABEL)
        for fn in folder_names:
            self._list.addItem(fn)
        if current_folder:
            for i in range(self._list.count()):
                if self._list.item(i).text() == current_folder:
                    self._list.setCurrentRow(i)
                    break
        if self._list.currentRow() < 0:
            self._list.setCurrentRow(0)
        self._list.currentRowChanged.connect(self._on_row_changed)
        self._on_row_changed(self._list.currentRow())
