        outer_scroll.setStyleSheet('QScrollArea{background:transparent;border:none;}QScrollBar:vertical{background:rgba(255,255,255,8);width:6px;border-radius:3px;}QScrollBar::handle:vertical{background:rgba(255,255,255,55);border-radius:3px;}QScrollBar::add-line:vertical,QScrollBar::sub-line:vertical{height:0px;}')
