    def _build_driver_row(self) -> QFrame:
        dm = DriverManager.instance()
        installed = dm.is_installed()
        ver = dm.get_installed_version() if installed else None
        card = QFrame()
        card.setStyleSheet('QFrame{background:rgba(255,255,255,7);border-radius:10px;border:1px solid rgba(255,255,255,34);}')
