        self._device_combo.addItem('1/1  No controller', None)
        self._device_combo.setStyleSheet('QComboBox{color:#d8e1ff;background:#02050c;border:1px solid #174fba;border-radius:16px;padding:6px 9px;}QComboBox::drop-down{border:none;}')
        self._device_combo.currentIndexChanged.connect(lambda _index: self._update_device_metadata())
