        for label in (self._status, self._device, self._output, self._bridge_status):
            label.setStyleSheet('color:#7790bd;background:transparent;border:none;font-size:10px;')
            label.setWordWrap(True)
            device_layout.addWidget(label)
        for key, label_text in (('sequence', 'Sequence No.'), ('charge', 'Charge Status'), ('battery', 'Battery Level'), ('mic', 'Microphone'), ('headphone', 'Headphone')):
            row = QHBoxLayout()
