        left.addWidget(device_card)
        output_card, output_layout = card('Output')
        self._add_output_choice(output_layout, 'Mic status light', ['Off', 'On', 'Blink'], 'Off', self._apply_mic_led)
        self._add_output_choice(output_layout, 'Lightbar color', ['Green', 'Blue', 'Red', 'White', 'Custom'], 'Green', self._apply_lightbar_color)
        self._add_output_choice(output_layout, 'Lightbar effect', ['Static', 'Rainbow'], 'Static', self._apply_lightbar_effect)
        self._add_output_choice(output_layout, 'Player light', ['Off', '1', '2', '3', '4', 'All'], 'Off', self._apply_player_led)
        self._add_output_choice(output_layout, 'Brightness', ['High', 'Medium', 'Low'], 'High', self._apply_lightbar_brightness)
        self._rumble_heavy = self._add_slider_row(output_layout, 'Rumble (heavy)', 'rumble_heavy', self._apply_rumble_levels)
