        def summary_item(row, column, label, attr, initial='—', visible=True):
            title = QLabel(label.upper(), summary)
            title.setProperty('class', 'kicker')
            value = QLabel(initial, summary)
            value.setProperty('class', 'value')
            if visible:
                summary_grid.addWidget(title, row * 2, column)
