        header_git = QPushButton('⌘')
        header_git.setFixedSize(28, 28)
        header_git.setStyleSheet('QPushButton{color:#2f81f7;background:#fff;border:none;font-size:18px;}')
        header_layout.addWidget(header_git)
        shell_layout.addWidget(header)
        main_row = QHBoxLayout()
        main_row.setContentsMargins(0, 0, 0, 0)
        main_row.setSpacing(12)
        shell_layout.addLayout(main_row, 1)
        rail = QWidget()
        rail.setFixedWidth(400)
        rail_layout = QVBoxLayout(rail)
        rail_layout.setContentsMargins(0, 0, 0, 0)
        rail_layout.setSpacing(8)
