def _paint_faded_card(w, event):
    # Soft translucent rim on all four sides -- no crisp line. The edge is a
    # stack of low-alpha rounded strokes that fade inwards, so every side
    # reads as a pale, blurred rim.
    p = QPainter(w)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    r = QRectF(w.rect()).adjusted(2.0, 2.0, -2.0, -2.0)
    radius = 12.0
    focused = bool(w.property('gpFocused'))
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor(19, 28, 48, 255) if focused else QColor(14, 21, 36, 252))
    p.drawRoundedRect(r, radius, radius)
    if focused:
        layers = ((7.0, 4, 150, 180, 255), (5.0, 7, 150, 180, 255), (3.2, 12, 150, 185, 255), (2.0, 20, 155, 195, 255), (1.2, 36, 165, 205, 255))
    else:
        layers = ((6.5, 3, 108, 142, 214), (4.8, 5, 108, 142, 214), (3.2, 8, 108, 142, 214), (2.1, 12, 112, 148, 220), (1.3, 18, 116, 152, 224))
    # Selection is communicated by the slightly lighter fill above, without
    # drawing a decorative frame around every settings card.
    p.end()


def _panel_target(w):
    if isinstance(w, QComboBox) or isinstance(w, QAbstractButton) or isinstance(w, QLineEdit) or (hasattr(w, 'value') and hasattr(w, 'setValue')):
        return w
    for ch in w.findChildren((QComboBox, QAbstractButton, QLineEdit, QSlider)):
        return ch
    return w


def _safe_call(fn):
    try:
        fn()
    except RuntimeError:
        pass


class _FlowLayout(QLayout):
    """Left-to-right flow layout that wraps to the next row when the
    current one fills up."""

    def __init__(self, parent=None, margin=0, hspacing=14, vspacing=10):
        super().__init__(parent)
        self._items = []
        self._hspacing = hspacing
        self._vspacing = vspacing
        self.setContentsMargins(margin, margin, margin, margin)

    def addItem(self, item):
        self._items.append(item)

    def count(self):
        return len(self._items)

    def itemAt(self, i):
        return self._items[i] if 0 <= i < len(self._items) else None

    def takeAt(self, i):
        if 0 <= i < len(self._items):
            return self._items.pop(i)
        return None

    def expandingDirections(self):
        return Qt.Orientation(0)

    def hasHeightForWidth(self):
        return True

    def heightForWidth(self, width):
        return self._do_layout(QRect(0, 0, width, 0), True)

    def setGeometry(self, rect):
        super().setGeometry(rect)
        self._do_layout(rect, False)

    def sizeHint(self):
        return self.minimumSize()

    def minimumSize(self):
        s = QSize()
        m = self.contentsMargins()
        for it in self._items:
            w = it.widget()
            if w is not None:
                s = s.expandedTo(w.sizeHint())
        return QSize(s.width() + m.left() + m.right(), s.height() + m.top() + m.bottom())

    def natural_width(self):
        """Total width needed to lay out every item in a single row
        (sum of each item's own width plus the spacing between them),
        so a container can shrink itself to fit its content instead of
        always stretching to the full available width."""
        m = self.contentsMargins()
        total = m.left() + m.right()
        n = 0
        for it in self._items:
            w = it.widget()
            if w is None:
                continue
            total += w.sizeHint().width()
            n += 1
        if n > 1:
            total += self._hspacing * (n - 1)
        return total

    def _do_layout(self, rect, test_only):
        m = self.contentsMargins()
        x = rect.x() + m.left()
        y = rect.y() + m.top()
        line_h = 0
        max_x = rect.right() - m.right()
        start_x = x
        for it in self._items:
            w = it.widget()
            if w is None:
                continue
            hint = w.sizeHint()
            full = bool(w.property('fullWidth'))
            if full:
                if x != start_x:
                    x = start_x
                    y += line_h + self._vspacing
                    line_h = 0
                hint = QSize(max(1, max_x - x), hint.height())
            elif x != start_x and x + hint.width() > max_x:
                x = start_x
                y += line_h + self._vspacing
                line_h = 0
            if not test_only:
                it.setGeometry(QRect(QPoint(x, y), hint))
            x += hint.width() + self._hspacing
            line_h = max(line_h, hint.height())
        return y + line_h + m.bottom() - rect.y()


class _LibraryActionButton(QPushButton):
    """A real, self-contained mouse/keyboard action for the Library panel.

    These controls used to depend only on the generic settings-panel click
    path.  That path can lose a press while the drawer/panel is animating or
    while the application-wide outside-click filter is inspecting the event.
    The button now owns its complete activation path: mouse release, Enter,
    Space, and the normal Qt ``clicked`` signal all reach the same guarded
    dispatcher.  There is deliberately no delayed lambda or shared panel
    action state here.
    """

    def __init__(self, text, callback, parent=None):
        super().__init__(text, parent)
        self._callback = callback
        self._dispatching = False
        self.setObjectName('libraryActionButton')
        self.setFixedHeight(42)
        self.setMinimumWidth(max(72, QFontMetrics(self.font()).horizontalAdvance(text) + 28))
        self.setFont(QFont('Segoe UI', 10))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setAutoDefault(False)
        self.setDefault(False)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, False)
        self.setStyleSheet(
            "QPushButton#libraryActionButton{color:#e4e8ff;background:rgba(255,255,255,7);"
            "border:1px solid rgba(255,255,255,18);border-radius:10px;padding:0 14px;}"
            "QPushButton#libraryActionButton:hover{background:rgba(255,255,255,20);color:#fff;}"
            "QPushButton#libraryActionButton:pressed{background:rgba(255,255,255,34);color:#fff;}"
            + _BTN_GP_FOCUS_QSS
        )
        self.clicked.connect(self._dispatch)

    def _dispatch(self, checked=False):
        if self._dispatching or not self.isEnabled():
            return
        self._dispatching = True
        try:
            self._callback()
        except RuntimeError:
            # The panel can be rebuilt/closed while a modal action is ending.
            # A deleted Qt object must not turn a button press into a crash.
            pass
        finally:
            self._dispatching = False

    def mouseReleaseEvent(self, event):
        # Own the release rather than relying on QAbstractButton's hit-test
        # state.  The panel may have moved one layout pass between press and
        # release; if the release is still inside this button, it is a valid
        # click and must not be discarded.
        if event.button() == Qt.MouseButton.LeftButton:
            pos = event.position().toPoint() if hasattr(event, 'position') else event.pos()
            if self.rect().contains(pos):
                self.setDown(False)
                self._dispatch()
                event.accept()
                return
        super().mouseReleaseEvent(event)

    def keyPressEvent(self, event):
        if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Space):
            self._dispatch()
            event.accept()
            return
        super().keyPressEvent(event)


class _SettingsGlassPanel(QFrame):
    closeRequested = pyqtSignal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName('settingsGlassPanel')
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self._items = []
        self._idx = 0
        self._sub = 0
        outer = QVBoxLayout(self)
        outer.setContentsMargins(20, 14, 20, 16)
        outer.setSpacing(8)
        self._title_lbl = QLabel('')
        self._title_lbl.setFont(QFont('Segoe UI', 14, QFont.Weight.Bold))
        self._title_lbl.setStyleSheet('color:#f0f2ff;background:transparent;border:none;letter-spacing:1px;')
        outer.addWidget(self._title_lbl)
        self._scroll = QScrollArea()
        self._scroll.setWidgetResizable(True)
        self._scroll.setFrameShape(QFrame.Shape.NoFrame)
        self._scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self._scroll.setStyleSheet('QScrollArea{background:transparent;border:none;}QScrollBar:vertical{background:rgba(255,255,255,8);width:5px;border-radius:3px;}QScrollBar::handle:vertical{background:rgba(255,255,255,55);border-radius:3px;}QScrollBar::add-line:vertical,QScrollBar::sub-line:vertical{height:0px;}')
        self._content = QWidget()
        self._content.setStyleSheet("background:transparent;QWidget[gpFocused='true']{background:rgba(255,255,255,7);border-radius:10px;}QComboBox[gpFocused='true']{border:1px solid rgba(255,255,255,55);background:rgba(255,255,255,12);}")
        self._flow = _FlowLayout(self._content, margin=0, hspacing=14, vspacing=10)
        self._scroll.setWidget(self._content)
        outer.addWidget(self._scroll, 1)

    def paintEvent(self, event):
        p = QPainter(self)
        _paint_pre_settings_dialog_surface(p, QRectF(self.rect()), radius=18, source_widget=self, black_tint_alpha=120, flat_glass_alpha=18)
        p.end()

    def rebuild(self, category, launcher):
        while self._flow.count():
            it = self._flow.takeAt(0)
            w = it.widget()
            if w is not None:
                w.deleteLater()
        self._items = []
        self._idx = 0
        self._sub = 0
        launcher._build_panel_category(self, category)
        titles = {'library': '', 'gamepad': '', 'audio': '', 'system': ''}
        self._title_lbl.setText(titles.get(category, ''))
        if self._items:
            self._highlight(0, 0)

    def add(self, w, section=None):
        if section is not None:
            lbl = QLabel(section)
            lbl.setFont(QFont('Segoe UI', 9, QFont.Weight.Bold))
            lbl.setStyleSheet('color:rgba(150,170,240,215);background:transparent;border:none;letter-spacing:1px;padding-top:14px;')
            # Every section header starts its own row. Without this, a
            # header (and the group under it) could end up sharing a row
            # with the tail end of the previous, unrelated group whenever
            # there happened to be leftover horizontal space -- which is
            # what made pages like System look like one jumbled grid
            # instead of clearly separated sections.
            lbl.setProperty('fullWidth', True)
            self._flow.addWidget(lbl)
        self._flow.addWidget(w)
        self._items.append(w)

    def current_widget(self):
        if 0 <= self._idx < len(self._items):
            return self._items[self._idx]
        return None

    def _sub_blocks(self, item):
        """The individually-focusable rows inside one column (top-level
        item): its direct child widgets (skipping plain caption labels),
        or just the item itself if it has no such children (a leaf
        control like a single toggle or button)."""
        if item is None:
            return []
        lay = item.layout()
        if lay is None or lay.count() == 0:
            return [item]
        blocks = []
        for i in range(lay.count()):
            w = lay.itemAt(i).widget()
            if w is None or isinstance(w, QLabel):
                continue
            blocks.append(w)
        return blocks or [item]

    def _highlight(self, idx, sub=None):
        if not self._items:
            return
        self._idx = max(0, min(idx, len(self._items) - 1))
        blocks = self._sub_blocks(self.current_widget())
        self._sub = max(0, min(sub if sub is not None else getattr(self, '_sub', 0), len(blocks) - 1))
        # Clear focus styling from every row in every column, then mark
        # only the current column's current row.
        for it in self._items:
            for b in self._sub_blocks(it):
                b.setProperty('gpFocused', False)
                b.style().unpolish(b)
                b.style().polish(b)
                b.update()
        cur = blocks[self._sub] if blocks else None
        if cur is not None:
            cur.setProperty('gpFocused', True)
            cur.style().unpolish(cur)
            cur.style().polish(cur)
            cur.update()
        try:
            self._scroll.ensureWidgetVisible(cur or self._items[self._idx], 30, 30)
        except RuntimeError:
            pass

    def gamepad_button(self, btn):
        if btn in ('circle', 'options'):
            self.closeRequested.emit()
            return
        if not self._items:
            return
        # L1/R1 jump between columns (top-level items); the D-pad in any
        # of the four directions steps through the options inside the
        # currently selected column.
        if btn == 'l1':
            self._highlight(self._idx - 1, 0)
            return
        if btn == 'r1':
            self._highlight(self._idx + 1, 0)
            return
        if btn in ('up', 'left'):
            self._highlight(self._idx, self._sub - 1)
            return
        if btn in ('down', 'right'):
            self._highlight(self._idx, self._sub + 1)
            return
        blocks = self._sub_blocks(self.current_widget())
        cur = blocks[self._sub] if blocks else None
        w = _panel_target(cur)
        if w is None:
            return
        if btn == 'cross':
            if isinstance(w, QComboBox):
                w.showPopup()
            elif hasattr(w, 'click'):
                w.click()
            elif isinstance(w, QLineEdit):
                w.setFocus(Qt.FocusReason.OtherFocusReason)

class LauncherSettingsDialog(QDialog):
    _FOCUS_ROW_QSS = 'QCheckBox:focus,QRadioButton:focus{  background:rgba(255,255,255,14);border-radius:8px;  border:none;outline:none;}QLineEdit:focus,QSpinBox:focus{  border:none;background:rgba(255,255,255,16);outline:none;}QSlider:focus{outline:none;}QSlider:focus::handle:horizontal{  background:#88a2ff;border:none;}'
    _GP_FOCUS_QSS = "QCheckBox[gpFocused='true'],QRadioButton[gpFocused='true']{  background:rgba(255,255,255,14);border-radius:8px;  border:none;padding:4px 10px;}QLineEdit[gpFocused='true'],QSpinBox[gpFocused='true']{  border:none !important;  background:rgba(255,255,255,16) !important;}QSlider[gpFocused='true']::groove:horizontal{  background:transparent;}QSlider[gpFocused='true']::handle:horizontal{  background:#88a2ff;border:none;}QPushButton[gpFocused='true']{  border:none !important;  background:rgba(255,255,255,34) !important;}"

    def __init__(self, launcher, parent=None, open_page: int=None):
        super().__init__(parent)
        self._launcher = launcher
        self.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.Dialog)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setModal(True)
        self.setFixedWidth(560)
        self.setMinimumHeight(0)
        self._pad_level = 'menu'
        self._menu_sel = 0
        self._build()
        target_page = open_page if open_page is not None else self._general_page_idx
        self._open_page(max(0, min(target_page, len(self._content_pages) - 1)))

    def paintEvent(self, ev):
        p = QPainter(self)
        _paint_pre_settings_dialog_surface(p, QRectF(self.rect()), source_widget=self, black_tint_alpha=150, flat_glass_alpha=20)
        p.end()
        _apply_shared_dialog_shape(self)

    def _build(self):
        outer = QVBoxLayout(self)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(0)
        self._master = QStackedWidget()
        self._master.setStyleSheet('QStackedWidget{background:transparent;border:none;}')
        self._master.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Ignored)
        self._menu_page = self._build_menu_page()
        self._master.addWidget(self._menu_page)
        self._pages_def = [('📚', 'Library', '', self._build_library_page), ('🔊', 'Switching Audio', '', self._build_switching_audio_page), ('💻', 'System', '', self._build_system_page), ('🎮', 'Trainer', '', self._build_trainer_page)]
        self._trainer_page_idx = next((i for i, p in enumerate(self._pages_def) if p[1] == 'Trainer'))
        # General was merged into System. Keep this compatibility name so
        # older callers that open the default settings page still land there.
        self._general_page_idx = next((i for i, p in enumerate(self._pages_def) if p[1] == 'System'))
        self._content_pages = []
        for icon, label, hint, builder in self._pages_def:
            wrap = self._wrap_content_page(icon, label, builder)
            self._content_pages.append(wrap)
            self._master.addWidget(wrap)
        outer.addWidget(self._master)
        self._master.setCurrentIndex(0)
        self.adjustSize()
        menu_tile_h = 72
        menu_height = 44 + 1 + 8 + 12 + menu_tile_h + 24
        self._menu_height = max(180, menu_height)
        self._content_height = 620
        self.setFixedHeight(self._menu_height)
        self._recenter_on_parent()

    def _recenter_on_parent(self):
        if self.parent():
            c = self.parent().window().frameGeometry().center()
            self.move(c - QPoint(self.width() // 2, self.height() // 2))

    def _build_menu_page(self) -> QWidget:
        page = QWidget()
        page.setStyleSheet('background:transparent;')
        vl = QVBoxLayout(page)
        vl.setContentsMargins(0, 0, 0, 0)
        vl.setSpacing(0)
        hdr = QFrame()
        hdr.setFixedHeight(44)
        hdr.setStyleSheet('QFrame{background:transparent;border:none;}')
        hl = QHBoxLayout(hdr)
        hl.setContentsMargins(14, 4, 10, 0)
        title_lbl = QLabel('Settings')
        title_lbl.setFont(QFont('Segoe UI', 11, QFont.Weight.Bold))
        title_lbl.setStyleSheet('color:#dde0ff;background:transparent;border:none;')
        hl.addWidget(title_lbl)
        hl.addStretch(1)
        close_btn = QPushButton('✕')
        close_btn.setFixedSize(38, 38)
        close_btn.setFont(QFont('Segoe UI', 14))
        close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        close_btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        close_btn.setStyleSheet('QPushButton{color:#aaaacc;background:transparent;border:none;border-radius:9px;}QPushButton:hover{color:#fff;background:rgba(210,50,50,180);}')
        close_btn.clicked.connect(self.reject)
        hl.addWidget(close_btn)
        vl.addWidget(hdr)
        sep = QFrame()
        sep.setFrameShape(QFrame.Shape.HLine)
        sep.setStyleSheet('background:rgba(255,255,255,18);border:none;max-height:1px;')
        vl.addWidget(sep)
        vl.addSpacing(8)
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setStyleSheet('QScrollArea{background:transparent;border:none;}QScrollBar:vertical{background:rgba(255,255,255,8);width:5px;border-radius:3px;}QScrollBar::handle:vertical{background:rgba(255,255,255,55);border-radius:3px;}QScrollBar::add-line:vertical,QScrollBar::sub-line:vertical{height:0px;}')
        inner = QWidget()
        inner.setStyleSheet('background:transparent;')
        ibl = QHBoxLayout(inner)
        ibl.setContentsMargins(24, 12, 24, 24)
        ibl.setSpacing(10)
        entries = [('📚', 'Library', ''), ('🔊', 'Switching Audio', ''), ('💻', 'System', '')]
        self._menu_btns = []
        for idx2, (icon, label, hint) in enumerate(entries):
            item = self._make_menu_item(icon, label, hint, idx2)
            ibl.addWidget(item)
            self._menu_btns.append(item)
        ibl.addStretch(1)
        scroll.setWidget(inner)
        vl.addWidget(scroll, 0)
        self._highlight_menu(0)
        return page

    def _make_menu_item(self, icon: str, label: str, hint: str, idx: int) -> QFrame:
        row = QFrame()
        row.setObjectName(f'lsd_mi_{idx}')
        row.setFixedSize(78, 72)
        row.setCursor(Qt.CursorShape.PointingHandCursor)
        row.setStyleSheet(_dialog_row_qss(f'lsd_mi_{idx}'))
        vl2 = QVBoxLayout(row)
        vl2.setContentsMargins(6, 8, 6, 8)
        vl2.setSpacing(4)
        icon_lbl = QLabel(icon)
        icon_lbl.setFont(QFont('Segoe UI', 18))
        icon_lbl.setAlignment(Qt.AlignmentFlag.AlignHCenter)
        icon_lbl.setStyleSheet('color:#dde0ff;background:transparent;border:none;')
        vl2.addWidget(icon_lbl)
        tl = QLabel(label)
        tl.setFont(QFont('Segoe UI', 8, QFont.Weight.Bold))
        tl.setAlignment(Qt.AlignmentFlag.AlignHCenter)
        tl.setWordWrap(True)
        tl.setStyleSheet('color:#dde0ff;background:transparent;border:none;')
        vl2.addWidget(tl)
        row.mousePressEvent = lambda ev, i=idx: self._open_page(i)
        row.enterEvent = lambda ev, i=idx: self._highlight_menu(i)
        return row

    def _highlight_menu(self, idx: int):
        self._menu_sel = idx
        for i, row in enumerate(self._menu_btns):
            nm = f'lsd_mi_{i}'
            if i == idx:
                row.setStyleSheet(_dialog_row_qss(nm, selected=True))
            else:
                row.setStyleSheet(_dialog_row_qss(nm))

    def _open_page(self, idx: int):
        self._pad_level = 'page'
        wrap = self._content_pages[idx]
        if wrap._content is None:
            content = wrap._builder()
            wrap._content_vl.addWidget(content, 1)
            wrap._content = content
        self._master.setCurrentIndex(idx + 1)
        self.setFixedHeight(self._content_height)
        self._recenter_on_parent()

    def _wrap_content_page(self, icon: str, label: str, builder) -> QWidget:
        wrap = QWidget()
        wrap.setStyleSheet('background:transparent;')
        vl = QVBoxLayout(wrap)
        vl.setContentsMargins(0, 0, 0, 0)
        vl.setSpacing(0)
        top = QFrame()
        top.setFixedHeight(44)
        top.setStyleSheet('QFrame{background:transparent;border:none;}')
        thl = QHBoxLayout(top)
        thl.setContentsMargins(14, 4, 10, 0)
        thl.setSpacing(10)
        back_btn = QPushButton('‹')
        back_btn.setFixedSize(36, 36)
        back_btn.setFont(QFont('Segoe UI', 16, QFont.Weight.Bold))
        back_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        back_btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        back_btn.setStyleSheet('QPushButton{color:#aaaacc;background:transparent;border:none;border-radius:8px;}QPushButton:hover{color:#fff;background:rgba(80,100,200,120);}')
        back_btn.clicked.connect(self._go_back_to_menu)
        thl.addWidget(back_btn)
        title_lbl = QLabel(label)
        title_lbl.setFont(QFont('Segoe UI', 11, QFont.Weight.Bold))
        title_lbl.setStyleSheet('color:#dde0ff;background:transparent;border:none;')
        thl.addWidget(title_lbl)
        thl.addStretch(1)
        cl = QPushButton('✕')
        cl.setFixedSize(36, 36)
        cl.setFont(QFont('Segoe UI', 14))
        cl.setCursor(Qt.CursorShape.PointingHandCursor)
        cl.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        cl.setStyleSheet('QPushButton{color:#aaaacc;background:transparent;border:none;border-radius:8px;}QPushButton:hover{color:#fff;background:rgba(210,50,50,180);}')
        cl.clicked.connect(self.reject)
        thl.addWidget(cl)
        if label in ('Library', 'Switching Audio', 'System'):
            back_btn.hide()
            title_lbl.hide()
        vl.addWidget(top)
        sep = QFrame()
        sep.setFrameShape(QFrame.Shape.HLine)
        sep.setStyleSheet('background:rgba(255,255,255,18);border:none;max-height:1px;')
        vl.addWidget(sep)
        wrap._builder = builder
        wrap._content = None
        wrap._content_vl = vl
        return wrap

    def _go_back_to_menu(self):
        self.reject()

    def _nav_style(self, active: bool) -> str:
        if active:
            return 'QPushButton{color:#ffffff;background:rgba(255,255,255,28);border:none;border-radius:9px;text-align:left;padding-left:6px;}'
        return 'QPushButton{color:rgba(200,210,255,170);background:transparent;border:none;border-radius:9px;text-align:left;padding-left:6px;}QPushButton:hover{color:#ffffff;background:rgba(255,255,255,14);}'

    def _switch_page(self, idx: int):
        self._open_page(idx)

    def gamepad_button(self, btn):
        if btn == 'circle':
            self.reject()
            return
        if self._pad_level == 'menu':
            if btn in ('up', 'down', 'left', 'right'):
                n = len(self._menu_btns)
                if n:
                    step = 1 if btn in ('down', 'right') else -1
                    self._highlight_menu((self._menu_sel + step) % n)
            elif btn == 'cross':
                self._open_page(self._menu_sel)
            return
        page_wrap = self._master.currentWidget()
        content = getattr(page_wrap, '_content', None)
        if content is not None and hasattr(content, 'gamepad_button'):
            handled = content.gamepad_button(btn)
            if handled is not False:
                return
        key_map = {'up': (Qt.Key.Key_Backtab, Qt.KeyboardModifier.ShiftModifier), 'down': (Qt.Key.Key_Tab, Qt.KeyboardModifier.NoModifier), 'left': (Qt.Key.Key_Left, Qt.KeyboardModifier.NoModifier), 'right': (Qt.Key.Key_Right, Qt.KeyboardModifier.NoModifier), 'cross': (Qt.Key.Key_Return, Qt.KeyboardModifier.NoModifier), 'square': (Qt.Key.Key_Space, Qt.KeyboardModifier.NoModifier)}
        mapping = key_map.get(btn)
        if mapping is None:
            return
        key, mods = mapping
        page = self._master.currentWidget()
        widget = QApplication.focusWidget()
        if widget is None or page is None or (not page.isAncestorOf(widget)):
            if page is not None:
                self._focus_first_in_page()
            return
        press = QKeyEvent(QEvent.Type.KeyPress, key, mods)
        release = QKeyEvent(QEvent.Type.KeyRelease, key, mods)
        QApplication.sendEvent(widget, press)
        QApplication.sendEvent(widget, release)

    def controller_test_active(self):
        """Expose the active controller-test subpage to the main window."""
        page_wrap = self._master.currentWidget()
        content = getattr(page_wrap, '_content', None)
        checker = getattr(content, 'controller_test_active', None)
        return bool(callable(checker) and checker())

    def route_controller_test_button(self, btn):
        """Route a tester press without falling through to settings input."""
        page_wrap = self._master.currentWidget()
        content = getattr(page_wrap, '_content', None)
        handler = getattr(content, 'route_controller_test_button', None)
        if callable(handler):
            return bool(handler(btn))
        return False

    def exit_controller_test(self):
        """Leave only the tester, keeping the game-pad settings dialog open."""
        page_wrap = self._master.currentWidget()
        content = getattr(page_wrap, '_content', None)
        handler = getattr(content, 'exit_controller_test', None)
        if callable(handler):
            return bool(handler())
        return False

    def keyPressEvent(self, event):
        key_map = {Qt.Key.Key_Up: 'up', Qt.Key.Key_Down: 'down', Qt.Key.Key_Left: 'left', Qt.Key.Key_Right: 'right', Qt.Key.Key_Return: 'cross', Qt.Key.Key_Enter: 'cross', Qt.Key.Key_Escape: 'circle'}
        btn = key_map.get(event.key())
        if btn:
            self.gamepad_button(btn)
            event.accept()
            return
        super().keyPressEvent(event)

    def _current_page_index(self) -> int:
        return max(0, self._master.currentIndex() - 1)

    def _focus_first_in_page(self):
        page = self._master.currentWidget()
        if page is None:
            return
        for w in page.findChildren(QWidget):
            if w.focusPolicy() != Qt.FocusPolicy.NoFocus and w.isVisible() and w.isEnabled():
                w.setFocus(Qt.FocusReason.OtherFocusReason)
                return

    @staticmethod
    def _section_hdr(text: str) -> QLabel:
        lbl = QLabel(text)
        lbl.setFont(QFont('Segoe UI', 15, QFont.Weight.Bold))
        lbl.setStyleSheet('color:#dde0ff;background:transparent;')
        return lbl

    @staticmethod
    def _section_sep() -> QFrame:
        sep = QFrame()
        sep.setFrameShape(QFrame.Shape.HLine)
        sep.setStyleSheet('background:rgba(255,255,255,18);border:none;max-height:1px;margin:4px 0;')
        return sep

    @staticmethod
    def _action_btn(icon: str, text: str, danger: bool=False) -> QPushButton:
        btn = QPushButton(f'   {text}')
        btn.setFixedHeight(46)
        btn.setFont(QFont('Segoe UI', 11))
        btn.setCursor(Qt.CursorShape.PointingHandCursor)
        if danger:
            ss = 'QPushButton{color:#ffaaaa;background:rgba(170,35,35,40);border:none;border-radius:10px;text-align:left;padding-left:14px;}QPushButton:hover{background:rgba(200,45,45,120);color:#ffffff;}QPushButton:pressed{background:rgba(150,25,25,180);}'
        else:
            ss = 'QPushButton{color:#dde0ff;background:rgba(255,255,255,5);border:none;border-radius:10px;text-align:left;padding-left:14px;}QPushButton:hover{background:rgba(255,255,255,18);color:#ffffff;}QPushButton:pressed{background:rgba(255,255,255,10);}'
        btn.setStyleSheet(ss + _BTN_GP_FOCUS_QSS)
        return btn

    def _build_library_page(self) -> QWidget:
        w = _SettingsFocusPage()
        w.setStyleSheet(f'background:transparent;{self._GP_FOCUS_QSS}')
        vl = QVBoxLayout(w)
        vl.setContentsMargins(26, 22, 26, 22)
        vl.setSpacing(10)
        vl.addSpacing(6)
        add_game_btn = self._action_btn('➕', 'Add Game')
        add_folder_btn = self._action_btn('📁', 'Category')
        scan_btn = self._action_btn('🔍', 'Scan for Games')
        trainer_btn = self._action_btn('🎮', 'Trainer')
        add_game_btn.clicked.connect(self._do_add_game)
        add_folder_btn.clicked.connect(self._do_add_folder)
        scan_btn.clicked.connect(self._do_scan_games)
        trainer_btn.clicked.connect(lambda: self._open_page(self._trainer_page_idx))
        vl.addWidget(add_game_btn)
        vl.addWidget(add_folder_btn)
        vl.addWidget(scan_btn)
        vl.addWidget(trainer_btn)
        vl.addStretch(1)
        w._set_items(w.findChildren(QPushButton))
        if w._items:
            w._highlight(0)
        return w

    def _build_general_page(self) -> QWidget:
        s = self._launcher.data.get('settings', {})
        outer_w = QWidget()
        outer_w.setStyleSheet('background:transparent;')
        outer_vl = QVBoxLayout(outer_w)
        outer_vl.setContentsMargins(0, 0, 0, 0)
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setStyleSheet('QScrollArea{background:transparent;border:none;}QScrollBar:vertical{background:rgba(255,255,255,8);width:6px;border-radius:3px;}QScrollBar::handle:vertical{background:rgba(255,255,255,55);border-radius:3px;}QScrollBar::add-line:vertical,QScrollBar::sub-line:vertical{height:0px;}')
        inner = _SettingsFocusPage()
        inner.setMinimumWidth(0)
        inner.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
        inner.setStyleSheet(self._GP_FOCUS_QSS + self._FOCUS_ROW_QSS + "QWidget{background:transparent;}QLabel{color:#ddddff;}QCheckBox,QRadioButton{color:#ddddff;font-family:'Segoe UI';font-size:12px;padding:6px 4px;}QLineEdit,QSpinBox{  background:rgba(255,255,255,10);color:#dde0ff;  border:none;border-radius:10px;  padding:8px 12px;font-family:'Segoe UI';font-size:12px;}QLineEdit:focus,QSpinBox:focus{  border:1px solid rgba(255,255,255,105);background:rgba(255,255,255,15);}QSpinBox::up-button,QSpinBox::down-button{width:18px;border:none;}")
        vl = QVBoxLayout(inner)
        vl.setContentsMargins(24, 20, 24, 22)
        vl.setSpacing(14)

        def _sec(text):
            lbl = QLabel(text)
            lbl.setFont(QFont('Segoe UI', 10, QFont.Weight.Bold))
            lbl.setStyleSheet('color:#8899ee;background:transparent;padding:0 0 2px;')
            return lbl

        def _card(*widgets) -> QWidget:
            card = QWidget()
            card.setStyleSheet('background:transparent;border:none;')
            cl = QVBoxLayout(card)
            cl.setContentsMargins(12, 10, 12, 10)
            cl.setSpacing(6)
            for w in widgets:
                if isinstance(w, QLayout):
                    cl.addLayout(w)
                else:
                    cl.addWidget(w)
            return card

        def _hide_general_control(widget):
            # Keep the controls alive for backwards-compatible settings
            # loading/saving, but remove them from the visible page and
            # gamepad focus order.
            widget.setProperty('_hidden_by_user', True)
            widget.hide()
            return widget

        self._source_enabled_set = set(s.get('enabled_sources', DEFAULT_SETTINGS['enabled_sources']))
        self._source_btn = QPushButton()
        self._source_btn.setFixedHeight(46)
        self._source_btn.setFont(QFont('Segoe UI', 10))
