        def add_cue(key, title):
            enabled_key = f'switching_audio_{key}_enabled'
            file_key = f'switching_audio_{key}_file'
            block = QWidget()
            bl = QVBoxLayout(block)
            bl.setContentsMargins(0, 4, 0, 4)
            bl.setSpacing(6)
