            path_label = QLabel()
            path_label.setWordWrap(True)
            path_label.setMinimumWidth(0)
            path_label.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
            path_label.setMinimumHeight(30)
            path_label.setStyleSheet('color:#9eabd8;background:rgba(255,255,255,4);border:none;border-radius:8px;padding:6px 9px;')

            def refresh_path():
                path = str(self._switching_audio_fields[key]['path'] or '').strip()
                if path:
                    full_text = f'Custom file: {path}'
                    metrics = path_label.fontMetrics()
                    elided = metrics.elidedText(full_text, Qt.TextElideMode.ElideMiddle, max(120, path_label.width() - 18))
                    path_label.setText(elided)
                    path_label.setToolTip(full_text)
                else:
                    path_label.setText("No custom file selected — using DualSense's built-in tone")
                    path_label.setToolTip('')
            choose = make_button('Choose File', lambda _checked=False, cue_key=key, label=path_label: self._choose_switching_audio_file(cue_key, label))
            preview = make_button('Preview', lambda _checked=False, cue_key=key: self._preview_switching_audio(cue_key))
            clear = make_button('Remove File', lambda _checked=False, cue_key=key, label=path_label: self._clear_switching_audio_file(cue_key, label))
            bl.addWidget(path_label)
            button_grid = QGridLayout()
            button_grid.setContentsMargins(0, 0, 0, 0)
            button_grid.setHorizontalSpacing(8)
            button_grid.setVerticalSpacing(8)
            button_grid.addWidget(choose, 0, 0)
            button_grid.addWidget(preview, 0, 1)
            button_grid.addWidget(clear, 1, 0, 1, 2)
            bl.addLayout(button_grid)
            vl.addWidget(block)
            self._switching_audio_fields[key] = {'enabled': toggle, 'path': str(s.get(file_key, '') or '').strip(), 'label': path_label}
            refresh_path()
