    def _choose_switching_audio_file(self, key: str, label: QLabel):
        path, _ = QFileDialog.getOpenFileName(self, 'Select Switching Audio', '', 'Audio files (*.wav *.mp3 *.ogg *.oga *.flac *.aiff *.aif)')
        if not path:
            return
        try:
            if os.path.getsize(path) > AUDIO_MAX_BYTES:
                raise ValueError('The audio file is larger than the allowed limit.')
            with open(path, 'rb') as stream:
                decoded = _decode_audio_to_wav(stream.read(), path)
            if not decoded:
                raise ValueError('The selected audio file could not be decoded.')
            wav_bytes, _duration, _rate = decoded
            os.makedirs(AUDIO_CACHE_DIR, exist_ok=True)
            normalized_path = os.path.join(AUDIO_CACHE_DIR, f'_switching_{key}.wav')
            part_path = normalized_path + f'.{os.getpid()}.part'
            with open(part_path, 'wb') as stream:
                stream.write(wav_bytes)
            os.replace(part_path, normalized_path)
        except (OSError, ValueError) as exc:
            _GlassMessageDialog.warning(self, 'Switching Audio', str(exc))
            return
        self._switching_audio_fields[key]['path'] = normalized_path
        label.setText(f'Custom file: {normalized_path}')

    def _preview_switching_audio(self, key: str):
        fields = self._switching_audio_fields.get(key)
        if not fields:
            return
        path = str(fields.get('path') or '').strip()
        if not path or not os.path.exists(path):
            return
        engine = getattr(self._launcher, '_bt_audio', None)
        if engine is None or not getattr(engine, 'available', False):
            return
        try:
            if getattr(self, '_switching_audio_preview_key', None) == key:
                engine.stop()
                self._switching_audio_preview_key = None
            else:
                engine.stop()
                if engine.play_file(path):
                    self._switching_audio_preview_key = key
        except Exception:
            self._switching_audio_preview_key = None

    def _clear_switching_audio_file(self, key: str, label: QLabel):
        old_path = str(self._switching_audio_fields.get(key, {}).get('path') or '').strip()
        if getattr(self, '_switching_audio_preview_key', None) == key:
            engine = getattr(self._launcher, '_bt_audio', None)
            if engine is not None:
                try:
                    engine.stop()
                except Exception:
                    pass
            self._switching_audio_preview_key = None
        if old_path.startswith(os.path.abspath(AUDIO_CACHE_DIR) + os.sep):
            try:
                os.remove(old_path)
            except OSError:
                pass
        self._switching_audio_fields[key]['path'] = ''
        label.setText("No custom file selected — using DualSense's built-in tone")

    def _save_switching_audio(self):
        settings = dict(self._launcher.data.get('settings', {}))
        for key, fields in self._switching_audio_fields.items():
            settings[f'switching_audio_{key}_enabled'] = fields['enabled'].isChecked()
            settings[f'switching_audio_{key}_file'] = str(fields['path'] or '').strip()
        self._launcher._apply_settings(settings)
        self._launcher._show_slide_toast('Switching Audio saved!', hold_ms=1750)

