def _scan_guess_category(exe_path: str) -> str:
    low = exe_path.lower()
    for marker, label in _SCAN_CATEGORY_MARKERS:
        if marker in low:
            return label
    return 'Other Games'

def _scan_is_probable_game(exe_path: str) -> bool:
    if _scan_guess_category(exe_path) != 'Other Games':
        return True
    folder_name = os.path.basename(os.path.dirname(exe_path))
    exe_name = os.path.splitext(os.path.basename(exe_path))[0]
    return is_known_game(folder_name) or is_known_game(exe_name)
_ROOT_CONTAINER_MARKERS = ['steamapps/common', 'epic games', 'gog games', 'gog galaxy/games', 'origin games', 'ea games', 'ubisoft game launcher/games', 'xboxgames', 'xbox games', 'xbox 360', 'xbox360', 'battle.net', 'ps5', 'ps5/games', 'ps5 games', 'ps4', 'ps4/games', 'ps4 games', 'ps3', 'ps3/games', 'ps3 games', 'ps2', 'ps2/games', 'ps2 games', 'psp', 'psp/games', 'psp games', 'ps1', 'ps1/games', 'ps1 games', 'psx', 'psx/games', 'psx games', 'ps vita', 'ps vita/games', 'psvita', 'psvita/games', 'switch', 'switch/games', 'switch games', 'nintendo switch', 'wii', 'wii/games', 'wii games', 'wii u', 'wiiu', 'wii u/games', 'gamecube', 'gamecube/games', 'roms', 'emulators']
