def _looks_like_internal_subfolder(name: str) -> bool:
    n = name.strip().lower()
    if not n:
        return True
    if n in _INTERNAL_SUBFOLDER_NAMES:
        return True
    if len(n) <= 4 and re.fullmatch('[a-z0-9_]+', n):
        return True
    return False
_PS_CONTENT_ID_RE = re.compile('^(CUSA\\d{5}|PPSA\\d{5}|PPSB\\d{5}|PCS[A-Z]\\d{5}|BLES\\d{5}|BLUS\\d{5}|BLJM\\d{5}|BLAS\\d{5}|BCES\\d{5}|BCUS\\d{5}|BCAS\\d{5}|BCJS\\d{5}|SLES\\d{5}|SLUS\\d{5}|SLPS\\d{5}|SLPM\\d{5}|SCES\\d{5}|SCUS\\d{5}|SCPS\\d{5}|SCAJ\\d{5}|ULES\\d{5}|ULUS\\d{5}|ULJM\\d{5}|UCES\\d{5}|UCUS\\d{5}|UCAS\\d{5}|NPEB\\d{5}|NPUB\\d{5}|NPHB\\d{5}|NPJB\\d{5}|NPEA\\d{5}|NPUA\\d{5}|NPHA\\d{5}|NPJA\\d{5})$', re.IGNORECASE)

def _looks_like_ps_content_id(name: str) -> bool:
    return bool(_PS_CONTENT_ID_RE.match(name.strip()))

def _rebuild_abs_path(exe_abs: str, upto_index: int) -> str:
    parts = os.path.normpath(exe_abs).split(os.sep)
    if parts and parts[0].endswith(':'):
        rebuilt = parts[0] + os.sep
    else:
        rebuilt = os.sep
    for comp in parts[1:upto_index]:
        if comp:
            rebuilt = os.path.join(rebuilt, comp)
    return rebuilt
_KNOWN_PS4_EMULATOR_EXE_NAMES = {'shadps4.exe', 'shadps4', 'gpcs4.exe', 'gpcs4', 'orbis.exe', 'kyty.exe', 'ps4emu.exe', 'ps4 emulator.exe'}

def _looks_like_shared_launcher_target(target_path: str, target_counts: dict) -> bool:
    name = os.path.basename(target_path).strip().lower()
    if name in _KNOWN_PS4_EMULATOR_EXE_NAMES:
        return True
    return target_counts.get(target_path, 0) > 1

def _real_path_for_root_detection(exe_path: str) -> str:
    if exe_path.lower().endswith('.lnk'):
        target, _args, _work_dir = _resolve_lnk(exe_path)
        if target and os.path.exists(target):
            return target
    return exe_path

def _find_game_root_folder(exe_path: str, scan_root: str=None) -> str:
    exe_abs = os.path.normpath(os.path.abspath(exe_path))
    parts = exe_abs.split(os.sep)
    parts_lower = [p.lower() for p in parts]
    for i in range(len(parts_lower)):
        for marker in _ROOT_CONTAINER_MARKERS_BY_LEN:
            marker_parts = marker.split('/')
            mlen = len(marker_parts)
            if i + mlen > len(parts_lower):
                continue
            if parts_lower[i:i + mlen] == marker_parts:
                cut = i + mlen + 1
                if cut < len(parts):
                    return _rebuild_abs_path(exe_abs, cut)
                break
    root_abs = os.path.abspath(scan_root) if scan_root else None
    cur = os.path.dirname(exe_abs)
    for _ in range(8):
        if root_abs and (cur == root_abs or len(cur) <= len(root_abs)):
            break
        parent = os.path.dirname(cur)
        if not parent or parent == cur or (not os.path.basename(parent)):
            break
        cur_name = os.path.basename(cur).strip()
        if _looks_like_internal_subfolder(cur_name):
            cur = parent
            continue
        return cur
    return cur

def _bin_content_id_root(exe_path: str, game_root: str) -> 'tuple[str, str] | None':
    """
    For .bin executables (raw PS4/PS5 dumps run via emulator), the
    content-ID folder (PPSA03647, CUSA01234, ...) is often one level
    ABOVE the folder _find_game_root_folder() lands on. If exe_path
    is a .bin and the parent of game_root looks like a PS content ID,
    step back one folder and use that as the root -- no param.sfo
    lookup needed, the ID itself is enough to resolve the title online.
    Returns (id_root, id_name) or None if no such parent is found.
    """
    if not exe_path.lower().endswith('.bin'):
        return None
    parent = os.path.dirname(os.path.normpath(game_root).rstrip('\\/'))
    parent_name = os.path.basename(parent).strip()
    if parent_name and _looks_like_ps_content_id(parent_name):
        return (parent, parent_name)
    return None

