EMULATOR_PRESETS = {'Custom': '{game}', 'RPCS3': '--no-gui "{game}"', 'PCSX2': '--batch "{game}"', 'DuckStation': 'run "{game}"', 'Ryujinx': '-r "{game}"', 'Yuzu': '-f -g "{game}"', 'Cemu': '-f -g "{game}"', 'PPSSPP': '"{game}"', 'Vita3K': '"{game}"'}

def _format_emulator_args(template: str, game_path: str) -> str:
    quoted_path = '"' + game_path.replace('"', '\\"') + '"'
    pattern = '(["\\\'])\\{game\\}\\1'
    formatted = re.sub(pattern, quoted_path, str(template or ''))
    return formatted.replace('{game}', quoted_path)

class _ImageCropWidget(QWidget):

    def __init__(self, display_pix: 'QPixmap', orig_pix: 'QPixmap', parent=None):
        super().__init__(parent)
        self._disp = display_pix
        self._orig = orig_pix
        self._start = None
        self._end = None
        self._drag = False
        # Synthetic on-screen cursor marker, used only while the DualSense
        # touchpad is driving this widget as a relative mouse (see
        # _AssetConfirmDialog.touchpad_state). The real OS cursor doesn't
        # move on its own in that case, so without this the user has no
        # visual feedback of where a touchpad drag would start. Left as
        # None (nothing drawn) for ordinary real-mouse use.
        self._virtual_cursor = None
        dw = display_pix.width() if not display_pix.isNull() else 300
        dh = display_pix.height() if not display_pix.isNull() else 200
        self.setFixedSize(dw, dh)
        self.setCursor(Qt.CursorShape.CrossCursor)
        self.setToolTip('برای کراپ کردن تصویر، روی آن کلیک کنید و بکشید.\nدکمه «حذف کراپ» را برای بازنشانی انتخاب بزنید.')

    def set_virtual_cursor(self, pos: 'QPoint | None'):
        """Show (or hide, if pos is None) the synthetic touchpad cursor
        marker at `pos` (widget-local coordinates)."""
        self._virtual_cursor = pos
        self.update()

    def paintEvent(self, ev):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        if not self._disp.isNull():
            p.drawPixmap(0, 0, self._disp)
        if self.has_crop():
            sel = QRect(self._start, self._end).normalized()
            p.fillRect(0, 0, sel.left(), self.height(), QColor(0, 0, 0, 120))
            p.fillRect(sel.right() + 1, 0, self.width() - sel.right() - 1, self.height(), QColor(0, 0, 0, 120))
            p.fillRect(sel.left(), 0, sel.width(), sel.top(), QColor(0, 0, 0, 120))
            p.fillRect(sel.left(), sel.bottom() + 1, sel.width(), self.height() - sel.bottom() - 1, QColor(0, 0, 0, 120))
            if not self._disp.isNull():
                p.drawPixmap(sel, self._disp, sel)
            pen = QPen(QColor(120, 180, 255, 240), 2, Qt.PenStyle.DashLine)
            p.setPen(pen)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRect(sel.adjusted(0, 0, -1, -1))
            p.setBrush(QBrush(QColor(200, 220, 255, 230)))
            p.setPen(Qt.PenStyle.NoPen)
            s = 6
            for cx, cy in [(sel.left(), sel.top()), (sel.right(), sel.top()), (sel.left(), sel.bottom()), (sel.right(), sel.bottom())]:
                p.drawRect(cx - s // 2, cy - s // 2, s, s)
            if sel.width() > 40 and sel.height() > 18:
                sx = self._orig.width() / self._disp.width() if not self._disp.isNull() and self._disp.width() else 1
                sy = self._orig.height() / self._disp.height() if not self._disp.isNull() and self._disp.height() else 1
                iw = round(sel.width() * sx)
                ih = round(sel.height() * sy)
                info = f' {iw} x {ih} '
                p.setPen(QColor(220, 230, 255, 230))
                p.setFont(QFont('Segoe UI', 8))
                p.fillRect(sel.left(), sel.top(), p.fontMetrics().horizontalAdvance(info) + 2, 14, QColor(0, 0, 0, 140))
                p.drawText(sel.left() + 1, sel.top() + 11, info)
        if self._virtual_cursor is not None:
            vc = self._virtual_cursor
            r = 6
            p.setPen(QPen(QColor(10, 14, 20, 220), 3))
            p.drawLine(vc.x() - r - 5, vc.y(), vc.x() + r + 5, vc.y())
            p.drawLine(vc.x(), vc.y() - r - 5, vc.x(), vc.y() + r + 5)
            p.setPen(QPen(QColor(140, 200, 255, 240), 1.5))
            p.drawLine(vc.x() - r - 5, vc.y(), vc.x() + r + 5, vc.y())
            p.drawLine(vc.x(), vc.y() - r - 5, vc.x(), vc.y() + r + 5)
            p.setBrush(QBrush(QColor(140, 200, 255, 230)))
            p.setPen(QPen(QColor(10, 14, 20, 220), 1.5))
            p.drawEllipse(vc, r, r)
        p.end()

    def mousePressEvent(self, ev):
        if ev.button() == Qt.MouseButton.LeftButton:
            # A real mouse is now in control -- drop the synthetic
            # touchpad cursor marker so the two don't sit on top of
            # each other.
            self._virtual_cursor = None
            self._press_at(ev.pos())

    def mouseMoveEvent(self, ev):
        if self._drag:
            self._move_at(ev.pos())

    def mouseReleaseEvent(self, ev):
        if ev.button() == Qt.MouseButton.LeftButton and self._drag:
            self._release_at(ev.pos())

    def _press_at(self, pos: 'QPoint'):
        """Start a crop drag at `pos` (widget-local coordinates). Shared by
        the real mouse handlers above and by the gamepad-touchpad mouse
        emulation in _AssetConfirmDialog, so both drive the exact same
        selection logic."""
        x = max(0, min(pos.x(), self.width() - 1))
        y = max(0, min(pos.y(), self.height() - 1))
        self._start = QPoint(x, y)
        self._end = QPoint(x, y)
        self._drag = True
        self.update()

    def _move_at(self, pos: 'QPoint'):
        if not self._drag:
            return
        x = max(0, min(pos.x(), self.width() - 1))
        y = max(0, min(pos.y(), self.height() - 1))
        self._end = QPoint(x, y)
        self.update()

    def _release_at(self, pos: 'QPoint'):
        if not self._drag:
            return
        x = max(0, min(pos.x(), self.width() - 1))
        y = max(0, min(pos.y(), self.height() - 1))
        self._end = QPoint(x, y)
        self._drag = False
        if not self.has_crop():
            self._start = self._end = None
        self.update()

    def has_crop(self) -> bool:
        if not (self._start and self._end):
            return False
        r = QRect(self._start, self._end).normalized()
        return r.width() >= 5 and r.height() >= 5

    def reset_crop(self):
        self._start = self._end = None
        self._drag = False
        self.update()

    def crop_original(self):
        if not self.has_crop() or self._orig.isNull() or self._disp.isNull():
            return None
        sel = QRect(self._start, self._end).normalized()
        sx = self._orig.width() / self._disp.width()
        sy = self._orig.height() / self._disp.height()
        ox = round(sel.x() * sx)
        oy = round(sel.y() * sy)
        ow = round(sel.width() * sx)
        oh = round(sel.height() * sy)
        ox = max(0, min(ox, self._orig.width() - 1))
        oy = max(0, min(oy, self._orig.height() - 1))
        ow = max(1, min(ow, self._orig.width() - ox))
        oh = max(1, min(oh, self._orig.height() - oy))
        cropped_pix = self._orig.copy(ox, oy, ow, oh)
        return cropped_pix.toImage()

_PS_CROSS_COLOR = QColor(72, 149, 239)
_PS_CIRCLE_COLOR = QColor(233, 69, 96)
_PS_TRIANGLE_COLOR = QColor(66, 199, 148)
_PS_SQUARE_COLOR = QColor(224, 108, 199)

def _ps_glyph_icon(glyph: str, color: 'QColor', diameter: int=22) -> 'QIcon':
    """Renders a small filled circle with a PlayStation face-button glyph
    (X / O / triangle / square) in that button's real color, so on-screen
    action buttons read as actual DualSense buttons instead of generic
    checkmarks -- part of giving confirmation dialogs a console look."""
    pm = QPixmap(diameter, diameter)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setPen(QPen(QColor(10, 10, 20, 160), 1))
    p.setBrush(QBrush(color))
    p.drawEllipse(1, 1, diameter - 2, diameter - 2)
    p.setPen(QColor(12, 14, 22, 235))
    p.setFont(QFont('Segoe UI', max(8, int(diameter * 0.48)), QFont.Weight.Bold))
    p.drawText(QRectF(0, 0, diameter, diameter), Qt.AlignmentFlag.AlignCenter, glyph)
    p.end()
    return QIcon(pm)

