class GameScanResultsDialog(_GlassDialogBase):

    def __init__(self, candidates: list, parent=None):
        super().__init__(parent)
        self._init_glass(min_width=560)
        self._checks = []
        self._gp_scroll = None
        self._gp_items = []
        self._gp_close_btn = None
        self._build(candidates)

    def _build(self, candidates):
        outer = QVBoxLayout(self)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(0)
        outer.addWidget(self._make_header())
        body = QWidget()
        body.setStyleSheet('background:transparent;')
        fl = QVBoxLayout(body)
        fl.setContentsMargins(20, 4, 20, 18)
        fl.setSpacing(8)
        if not candidates:
            hdr = QLabel('🔍  No new games found.')
            hdr.setFont(QFont('Segoe UI', 12, QFont.Weight.Bold))
            hdr.setStyleSheet('color:#dde0ff;background:transparent;')
            fl.addWidget(hdr)
            sub = QLabel('All the games found are likely already in the library,\nor no games were found in the scanned paths.')
            sub.setStyleSheet('color:rgba(200,210,255,150);background:transparent;')
            fl.addWidget(sub)
            close_btn = QPushButton('OK')
            close_btn.setFixedHeight(42)
            close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
            close_btn.setStyleSheet(self._OK_QSS)
            close_btn.clicked.connect(self.reject)
            fl.addWidget(close_btn)
            self._gp_items = None
            self._gp_close_btn = close_btn
            outer.addWidget(body, 1)
            self._center_on_parent()
            return
        hdr = QLabel(f'🔍  {len(candidates)} game(s) found — choose the ones you want')
        hdr.setFont(QFont('Segoe UI', 12, QFont.Weight.Bold))
        hdr.setStyleSheet('color:#dde0ff;background:transparent;')
        fl.addWidget(hdr)
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll.setFixedHeight(360)
        scroll.setStyleSheet('QScrollArea{background:transparent;border:none;}QScrollBar:vertical{background:rgba(255,255,255,8);width:6px;border-radius:3px;}QScrollBar::handle:vertical{background:rgba(255,255,255,55);border-radius:3px;}')
        inner = QWidget()
        inner.setStyleSheet('background:transparent;')
        ivl = QVBoxLayout(inner)
        ivl.setContentsMargins(4, 4, 4, 4)
        ivl.setSpacing(4)
        by_cat = {}
        for c in candidates:
            by_cat.setdefault(c['category'], []).append(c)
        for cat in sorted(by_cat.keys()):
            cat_lbl = QLabel(f'📁 {cat}  ({len(by_cat[cat])})')
            cat_lbl.setFont(QFont('Segoe UI', 10, QFont.Weight.Bold))
            cat_lbl.setStyleSheet('color:#8899ee;background:transparent;padding-top:6px;')
            ivl.addWidget(cat_lbl)
            for c in by_cat[cat]:
                cb = QCheckBox(c['title'])
                cb.setChecked(True)
                cb.setToolTip(c['exe'])
                cb._base_qss = "QCheckBox{color:#ddddff;font-family:'Segoe UI';font-size:11px;padding:2px 4px;}"
                cb.setStyleSheet(cb._base_qss)
                ivl.addWidget(cb)
                self._checks.append((cb, c))
        ivl.addStretch(1)
        scroll.setWidget(inner)
        fl.addWidget(scroll)
        btn_row = QHBoxLayout()
        select_all_btn = QPushButton('Select All')
        select_none_btn = QPushButton('Select None')
        for b in (select_all_btn, select_none_btn):
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b._base_qss = self._SMALL_QSS
            b.setStyleSheet(self._SMALL_QSS)
        select_all_btn.clicked.connect(lambda: self._set_all(True))
        select_none_btn.clicked.connect(lambda: self._set_all(False))
        btn_row.addWidget(select_all_btn)
        btn_row.addWidget(select_none_btn)
        btn_row.addStretch(1)
        cancel_btn = QPushButton('Cancel')
        add_btn = QPushButton('Add to Library')
        for b in (cancel_btn, add_btn):
            b.setFixedHeight(40)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
        cancel_btn._base_qss = self._CANCEL_QSS
        add_btn._base_qss = self._OK_QSS
        cancel_btn.setStyleSheet(cancel_btn._base_qss)
        add_btn.setStyleSheet(add_btn._base_qss)
        cancel_btn.clicked.connect(self.reject)
        add_btn.clicked.connect(self.accept)
        btn_row.addWidget(cancel_btn)
        btn_row.addWidget(add_btn)
        fl.addLayout(btn_row)
        self._gp_scroll = scroll
        self._gp_items = [cb for cb, _ in self._checks] + [select_all_btn, select_none_btn, cancel_btn, add_btn]
        self._gp_sel = 0
        self._gp_highlight(0)
        outer.addWidget(body, 1)
        self._center_on_parent()

    def _set_all(self, val: bool):
        for cb, _ in self._checks:
            cb.setChecked(val)

    def _gp_highlight(self, idx: int):
        if not self._gp_items:
            return
        self._gp_sel = max(0, min(idx, len(self._gp_items) - 1))
        for i, w in enumerate(self._gp_items):
            on = i == self._gp_sel
            overlay = self._GP_CB_OVERLAY if isinstance(w, QCheckBox) else self._GP_BTN_OVERLAY
            w.setStyleSheet(w._base_qss + (overlay if on else ''))
        if self._gp_scroll is not None:
            try:
                self._gp_scroll.ensureWidgetVisible(self._gp_items[self._gp_sel])
            except RuntimeError:
                pass

    def gamepad_button(self, btn: str):
        if self._gp_items is None:
            if btn in ('cross', 'circle'):
                self._gp_close_btn.click()
            return
        if btn == 'circle':
            self.reject()
        elif btn in ('up', 'down'):
            self._gp_highlight(self._gp_sel + (1 if btn == 'down' else -1))
        elif btn == 'cross':
            w = self._gp_items[self._gp_sel]
            if isinstance(w, QCheckBox):
                w.setChecked(not w.isChecked())
            else:
                w.click()

    def selected_candidates(self) -> list:
        return [c for cb, c in self._checks if cb.isChecked()]

class FolderGameTile(QWidget):
    clicked_signal = pyqtSignal(int)
    edit_signal = pyqtSignal(int, str)

    def __init__(self, app_data, index, selected=False):
        super().__init__()
        self.app_data = app_data
        self.index = index
        self._selected = selected
        self._hovered = False
        self.setFixedSize(150, 200)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)

    def set_selected(self, val):
        self._selected = val
        self.update()

    def enterEvent(self, e):
        self._hovered = True
        self.update()

    def leaveEvent(self, e):
        self._hovered = False
        self.update()

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked_signal.emit(self.index)
        elif event.button() == Qt.MouseButton.RightButton:
            self._ctx()

    def _ctx(self):
        menu = _styled_menu(self)
        menu.addAction('FPS', lambda: self.edit_signal.emit(self.index, 'launch_fps'))
        menu.addAction('Super Frame', lambda: self.edit_signal.emit(self.index, 'launch_super_frame'))
        ch_menu = _styled_submenu(menu, 'Change')
        ch_menu.addAction('Name', lambda: self.edit_signal.emit(self.index, 'rename'))
        ch_menu.addAction('Icon', lambda: self.edit_signal.emit(self.index, 'change_icon'))
        ch_menu.addAction('Background', lambda: self.edit_signal.emit(self.index, 'change_background'))
        ch_menu.addAction('Name Logo', lambda: self.edit_signal.emit(self.index, 'change_name_logo'))
        ch_menu.addAction('Game Run', lambda: self.edit_signal.emit(self.index, 'change_game_run'))
        ch_menu.addAction('Run With', lambda: self.edit_signal.emit(self.index, 'run_with'))
        dl_menu = _styled_submenu(menu, 'Download')
        dl_menu.addAction('Icon', lambda: self.edit_signal.emit(self.index, 'download_icon'))
        dl_menu.addAction('BG', lambda: self.edit_signal.emit(self.index, 'auto_background'))
        dl_menu.addAction('Name Logo', lambda: self.edit_signal.emit(self.index, 'download_name_logo'))
        menu.addAction('Path', lambda: self.edit_signal.emit(self.index, 'open_file_location'))
        menu.addAction('Move to Folder', lambda: self.edit_signal.emit(self.index, 'move_to_folder'))
        menu.addAction('Delete', lambda: self.edit_signal.emit(self.index, 'delete'))
        menu.exec(QCursor.pos())

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        path = QPainterPath()
        path.addRoundedRect(2, 2, 146, 196, 12, 12)
        p.setClipPath(path)
        if self._selected:
            g = QLinearGradient(0, 0, 0, 200)
            g.setColorAt(0, QColor(255, 255, 255, 26))
            g.setColorAt(1, QColor(255, 255, 255, 12))
            p.fillPath(path, QBrush(g))
        elif self._hovered:
            p.fillPath(path, QBrush(QColor(255, 255, 255, 16)))
        else:
            p.fillPath(path, QBrush(QColor(255, 255, 255, 8)))
        icon_path = self.app_data.get('icon') or self.app_data.get('exe', '')
        pix = _get_prescaled_art_async(icon_path, 96, _art_repaint_cb(self))
        if not pix.isNull():
            pix = _round_corners_by_size(pix, already_round=_looks_like_circular_badge(pix))
            p.drawPixmap(27, 18, 96, 96, pix)
            plat = _detect_game_platform_cached(self.app_data.get('exe', ''))
            plat_label = _PLATFORM_BADGE_LABELS.get(plat)
            if plat_label:
                _draw_platform_badge(p, 27, 18, 96, 96, plat_label)
        p.setPen(QColor('#ffffff'))
        p.setFont(QFont('Segoe UI', 9, QFont.Weight.Bold))
        p.drawText(0, 125, 150, 65, Qt.AlignmentFlag.AlignCenter | Qt.TextFlag.TextWordWrap, self.app_data.get('title', ''))

class FolderOverlay(QWidget):
    closed = pyqtSignal()
    game_launched = pyqtSignal(dict)
    game_edit = pyqtSignal(dict, str)
    COLS = 6

    def __init__(self, folder_name, apps, parent=None):
        super().__init__(parent)
        self.folder_name = folder_name
        self.apps = apps
        self.selected_index = 0
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setGeometry(parent.rect())
        self._build_ui()
        self._fade_in()

    def _build_ui(self):
        self.bg = QWidget(self)
        self.bg.setStyleSheet('background:rgba(2,2,15,0.90);')
        self.bg.setGeometry(self.rect())
        self.panel = _SharedGlassFrame(radius=22, parent=self)
        self.panel.setObjectName('fp')
        pl = QVBoxLayout(self.panel)
        pl.setContentsMargins(34, 26, 34, 28)
        pl.setSpacing(16)
        hr = QHBoxLayout()
        ico = QLabel('📁')
        ico.setFont(QFont('Segoe UI Emoji', 22))
        ico.setStyleSheet('color:#9999ff; background:transparent;')
        nm = QLabel(self.folder_name)
        nm.setFont(QFont('Segoe UI', 20, QFont.Weight.Bold))
        nm.setStyleSheet('color:#ffffff; background:transparent; letter-spacing:2px;')
        cnt = QLabel(f'{len(self.apps)} Games')
        cnt.setFont(QFont('Segoe UI', 11))
        cnt.setStyleSheet('color:#5555aa; background:transparent;')
        cnt.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        hr.addWidget(ico)
        hr.addWidget(nm)
        hr.addStretch()
        hr.addWidget(cnt)
        sep = QFrame()
        sep.setFrameShape(QFrame.Shape.HLine)
        sep.setStyleSheet('background:rgba(255,255,255,18); border:none; max-height:1px;')
        self.scroll = QScrollArea()
        self.scroll.setWidgetResizable(True)
        self.scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.setStyleSheet('QScrollArea{border:none;background:transparent;}')
        self.gw = QWidget()
        self.gw.setStyleSheet('background:transparent;')
        self.gl = QGridLayout(self.gw)
        self.gl.setSpacing(16)
        self.gl.setContentsMargins(0, 0, 0, 0)
        self.scroll.setWidget(self.gw)
        hint = QLabel('  ○ Back     ✕ Run     □ Edit')
        hint.setAlignment(Qt.AlignmentFlag.AlignCenter)
        hint.setStyleSheet('color:#333355; font-size:11px; background:transparent;')
        pl.addLayout(hr)
        pl.addWidget(sep)
        pl.addWidget(self.scroll)
        pl.addWidget(hint)
        self._populate()
        self._reposition()

    def _populate(self):
        while self.gl.count():
            it = self.gl.takeAt(0)
            if it.widget():
                it.widget().deleteLater()
        for i, app in enumerate(self.apps):
            tile = FolderGameTile(app, i, i == self.selected_index)
            tile.clicked_signal.connect(self._on_click)
            tile.edit_signal.connect(self._on_edit)
            self.gl.addWidget(tile, i // self.COLS, i % self.COLS)

    def _on_click(self, idx):
        self.selected_index = idx
        if idx < len(self.apps):
            self.game_launched.emit(self.apps[idx])

    def _on_edit(self, idx, action):
        if idx < len(self.apps):
            self.game_edit.emit(self.apps[idx], action)

    def navigate(self, direction):
        n = len(self.apps)
        if n == 0:
            return
        old = self.selected_index
        if direction == 'right':
            self.selected_index = (self.selected_index + 1) % n
        elif direction == 'left':
            self.selected_index = (self.selected_index - 1) % n
        elif direction == 'down':
            self.selected_index = min(self.selected_index + self.COLS, n - 1)
        elif direction == 'up':
            self.selected_index = max(self.selected_index - self.COLS, 0)
        if old != self.selected_index:
            self._update_sel()

    def _update_sel(self):
        for i in range(self.gl.count()):
            w = self.gl.itemAt(i).widget()
            if isinstance(w, FolderGameTile):
                w.set_selected(w.index == self.selected_index)

    def confirm_selected(self):
        if 0 <= self.selected_index < len(self.apps):
            self.game_launched.emit(self.apps[self.selected_index])

    def edit_selected(self):
        if 0 <= self.selected_index < len(self.apps):
            app = self.apps[self.selected_index]
            dlg = EditMenu(app, self)
            dlg.action_selected.connect(lambda a: self._on_edit(self.selected_index, a))
            dlg.exec()

    def _reposition(self):
        pw = int(self.width() * 0.78)
        ph = int(self.height() * 0.72)
        px = (self.width() - pw) // 2
        py = (self.height() - ph) // 2
        self.panel.setGeometry(px, py, pw, ph)

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self.bg.setGeometry(self.rect())
        self._reposition()

    def mousePressEvent(self, e):
        if not self.panel.geometry().contains(e.pos()):
            self.closed.emit()

    def _fade_in(self):
        self.setWindowOpacity(0.0)
        self._anim = QPropertyAnimation(self, b'windowOpacity')
        self._anim.setDuration(200)
        self._anim.setStartValue(0.0)
        self._anim.setEndValue(1.0)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._anim.start()


def _apply_glass_popup_shape(widget, radius: int=_DIALOG_GLASS_RADIUS):
    if widget.width() <= 0 or widget.height() <= 0:
        return
    path = QPainterPath()
    path.addRoundedRect(QRectF(widget.rect()), radius, radius)
    widget.setMask(QRegion(path.toFillPolygon().toPolygon()))

def _start_live_menu_backdrop(widget):
    _stop_live_menu_backdrop(widget)
    _push_menu_arrow_cursor(widget)

def _stop_live_menu_backdrop(widget):
    _pop_menu_arrow_cursor(widget)

# QApplication's override-cursor stack is a single global LIFO shared by the
# whole app. Two independent subsystems push/pop onto it here -- the
# gamepad "hide the OS cursor" logic (BlankCursor) and the "keep an arrow
# visible over an open menu" backdrop (ArrowCursor) -- with no knowledge of
# each other's push/pop order. If they interleave out of order (e.g. a menu
# opens while the pad has the cursor hidden, then the mouse moves while the
# menu is still open), a plain restoreOverrideCursor() pops whatever
# currently happens to be on *top*, not necessarily the entry the caller
# thinks it's removing -- silently corrupting the stack and, in the worst
# case, leaving a BlankCursor permanently stuck with nothing left able to
# pop it. _cursor_override_push/_pop below track pushes by name and, when
# asked to remove one that isn't on top, pop everything above it off the
# real Qt stack and re-push those on top again -- so callers can push/pop
# in any order and the net set of active overrides (and their original
# relative order) stays correct.
_CURSOR_OVERRIDE_STACK = []

def _cursor_override_push(name, shape):
    if any((n == name for n, _ in _CURSOR_OVERRIDE_STACK)):
        return
    _CURSOR_OVERRIDE_STACK.append((name, shape))
    QApplication.setOverrideCursor(shape)

def _cursor_override_pop(name):
    idx = next((i for i, (n, _s) in enumerate(_CURSOR_OVERRIDE_STACK) if n == name), None)
    if idx is None:
        return
    above = _CURSOR_OVERRIDE_STACK[idx + 1:]
    for _ in range(len(_CURSOR_OVERRIDE_STACK) - idx):
        QApplication.restoreOverrideCursor()
    del _CURSOR_OVERRIDE_STACK[idx:]
    for n, shape in above:
        _CURSOR_OVERRIDE_STACK.append((n, shape))
        QApplication.setOverrideCursor(shape)

def _push_menu_arrow_cursor(widget):
    if getattr(widget, '_menu_cursor_pushed', False):
        return
    widget._menu_cursor_pushed = True
    app = QApplication.instance()
    if app is not None:
        _cursor_override_push(f'menu_arrow_{id(widget)}', Qt.CursorShape.ArrowCursor)

def _pop_menu_arrow_cursor(widget):
    if not getattr(widget, '_menu_cursor_pushed', False):
        return
    widget._menu_cursor_pushed = False
    app = QApplication.instance()
    if app is not None:
        _cursor_override_pop(f'menu_arrow_{id(widget)}')

def _paint_menu_surface(widget):
    p = QPainter(widget)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    w, h = (max(1, widget.width()), max(1, widget.height()))
    rect = QRectF(0.0, 0.0, float(w), float(h))
    path = QPainterPath()
    path.addRoundedRect(rect, _DIALOG_GLASS_RADIUS, _DIALOG_GLASS_RADIUS)
    # Context menus belong to the same dark rounded visual system as every
    # other window; do not let the old frosted backdrop introduce a second
    # (lighter) theme.
    p.setClipPath(path)
    p.fillPath(path, QColor(9, 12, 20, 255))
    p.end()
    return
    try:
        surface = QImage(QSize(int(w), int(h)), QImage.Format.Format_ARGB32_Premultiplied)
    except TypeError:
        p.setClipPath(path)
        p.fillPath(path, QColor(10, 10, 14, 92))
        glass = QLinearGradient(0.0, 0.0, 0.0, float(h))
        glass.setColorAt(0.0, QColor(255, 255, 255, 58))
        glass.setColorAt(0.45, QColor(255, 255, 255, 22))
        glass.setColorAt(0.5, QColor(255, 255, 255, 12))
        glass.setColorAt(1.0, QColor(255, 255, 255, 34))
        p.fillPath(path, QBrush(glass))
        p.end()
        return
    surface.fill(0)
    sp = QPainter(surface)
    sp.setRenderHint(QPainter.RenderHint.Antialiasing)
    sp.setClipPath(path)
    sp.fillPath(path, QColor(10, 10, 14, 92))
    glass = QLinearGradient(0.0, 0.0, 0.0, float(h))
    glass.setColorAt(0.0, QColor(255, 255, 255, 58))
    glass.setColorAt(0.45, QColor(255, 255, 255, 22))
    glass.setColorAt(0.5, QColor(255, 255, 255, 12))
    glass.setColorAt(1.0, QColor(255, 255, 255, 34))
    sp.fillPath(path, QBrush(glass))
    fade_alpha = 235
    fade_w = min(64.0, w / 2.0)
    fade_h = min(40.0, h / 2.0)
    sp.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationOut)
    left = QLinearGradient(0.0, 0.0, fade_w, 0.0)
    left.setColorAt(0.0, QColor(0, 0, 0, fade_alpha))
    left.setColorAt(1.0, QColor(0, 0, 0, 0))
    sp.fillRect(QRectF(0.0, 0.0, fade_w, h), QBrush(left))
    right = QLinearGradient(w - fade_w, 0.0, w, 0.0)
    right.setColorAt(0.0, QColor(0, 0, 0, 0))
    right.setColorAt(1.0, QColor(0, 0, 0, fade_alpha))
    sp.fillRect(QRectF(w - fade_w, 0.0, fade_w, h), QBrush(right))
    top = QLinearGradient(0.0, 0.0, 0.0, fade_h)
    top.setColorAt(0.0, QColor(0, 0, 0, fade_alpha))
    top.setColorAt(1.0, QColor(0, 0, 0, 0))
    sp.fillRect(QRectF(0.0, 0.0, w, fade_h), QBrush(top))
    bottom = QLinearGradient(0.0, h - fade_h, 0.0, h)
    bottom.setColorAt(0.0, QColor(0, 0, 0, 0))
    bottom.setColorAt(1.0, QColor(0, 0, 0, fade_alpha))
    sp.fillRect(QRectF(0.0, h - fade_h, w, fade_h), QBrush(bottom))
    corner_r = max(fade_w, fade_h) * 1.15
    for cx, cy in ((0.0, 0.0), (w, 0.0), (0.0, h), (w, h)):
        corner = QRadialGradient(cx, cy, corner_r)
        corner.setColorAt(0.0, QColor(0, 0, 0, fade_alpha))
        corner.setColorAt(1.0, QColor(0, 0, 0, 0))
        sp.fillRect(QRectF(cx - corner_r, cy - corner_r, corner_r * 2.0, corner_r * 2.0), QBrush(corner))
    sp.end()
    p.drawImage(0, 0, surface)
    p.end()

class _TransparentMenuSurface(QWidget):

    def paintEvent(self, event):
        _paint_menu_surface(self)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.setCursor(Qt.CursorShape.ArrowCursor)

    def showEvent(self, event):
        super().showEvent(event)
        _start_live_menu_backdrop(self)

    def hideEvent(self, event):
        _stop_live_menu_backdrop(self)
        super().hideEvent(event)


class _AudioDownloadProgressCard(QFrame):
    _RADIUS = _DIALOG_GLASS_RADIUS

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setObjectName('audioProgressCard')
        self.setStyleSheet('#audioProgressCard{background:transparent;border:none;}')

    def paintEvent(self, event):
        painter = QPainter(self)
        _paint_dark_status_popup_surface(painter, self)
        painter.end()
        _apply_shared_dialog_shape(self, self._RADIUS)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        _apply_shared_dialog_shape(self, self._RADIUS)

def _paint_dark_status_popup_surface(painter: QPainter, widget):
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    rect = QRectF(widget.rect())
    radius = _DIALOG_GLASS_RADIUS
    path = QPainterPath()
    path.addRoundedRect(rect, radius, radius)
    painter.fillPath(path, QColor(9, 12, 20, 255))
    return
    painter.fillPath(path, QColor(4, 5, 12, 214))
    glass = QLinearGradient(0.0, 0.0, 0.0, max(1.0, rect.height()))
    glass.setColorAt(0.0, QColor(255, 255, 255, 26))
    glass.setColorAt(0.42, QColor(255, 255, 255, 8))
    glass.setColorAt(0.5, QColor(255, 255, 255, 6))
    glass.setColorAt(1.0, QColor(255, 255, 255, 14))
    painter.fillPath(path, QBrush(glass))
    painter.save()
    painter.setClipPath(path)
    diagonal = (rect.width() ** 2 + rect.height() ** 2) ** 0.5 / 2
    vignette = QRadialGradient(rect.center(), diagonal)
    vignette.setColorAt(0.0, QColor(0, 0, 0, 0))
    vignette.setColorAt(0.68, QColor(0, 0, 0, 0))
    vignette.setColorAt(1.0, QColor(0, 0, 0, 145))
    painter.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationOut)
    painter.fillRect(rect, QBrush(vignette))
    painter.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceOver)
    painter.restore()
    painter.setBrush(Qt.BrushStyle.NoBrush)
    for width, alpha in ((3.6, 5), (2.4, 9), (1.4, 14), (0.8, 16)):
        pen = QPen(QColor(255, 255, 255, alpha))
        pen.setWidthF(width)
        painter.setPen(pen)
        painter.drawPath(path)

class _GlassMenu(QMenu):

    def _sync_glass_shape(self):
        self.setContentsMargins(0, 0, 0, 0)
        self.setCursor(Qt.CursorShape.ArrowCursor)
        self.update()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._sync_glass_shape()

    def showEvent(self, event):
        super().showEvent(event)
        parent_menu = self.parentWidget()
        if self.property('_match_parent_menu_width') and isinstance(parent_menu, _GlassMenu) and (parent_menu.width() > 0):
            self.setFixedWidth(parent_menu.width())
        self._sync_glass_shape()
        _start_live_menu_backdrop(self)

    def hideEvent(self, event):
        _stop_live_menu_backdrop(self)
        super().hideEvent(event)

    def paintEvent(self, event):
        _paint_menu_surface(self)
        super().paintEvent(event)

class _OutsideClickCloser(QObject):

    def __init__(self, menu):
        super().__init__(menu)
        self._menu = menu

    def eventFilter(self, obj, event):
        et = event.type()
        if et in (QEvent.Type.MouseButtonPress, QEvent.Type.MouseButtonDblClick):
            if not self._menu.isVisible():
                return False
            gp = event.globalPosition().toPoint() if hasattr(event, 'globalPosition') else event.globalPos()
            m = self._menu
            while m is not None:
                if m.geometry().contains(gp):
                    return False
                active = m.activeAction()
                nxt = active.menu() if active else None
                m = nxt if nxt is not None and nxt.isVisible() else None
            self._menu.hide()
            return False
        return False

def _styled_menu(parent):
    menu = _GlassMenu(parent)
    menu.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
    menu.setAutoFillBackground(False)
    menu.setWindowFlags(menu.windowFlags() | Qt.WindowType.FramelessWindowHint | Qt.WindowType.NoDropShadowWindowHint)
    menu.setStyleSheet("\n        QMenu {\n            background: transparent;\n            border: none;\n            border-radius: 0px;\n            padding: 0px;\n        }\n        QMenu::item {\n            color: rgba(215,220,255,215);\n            padding: 10px 24px;\n            font-size: 12px;\n            border-radius: 10px;\n            margin: 0px;\n            background: transparent;\n            font-family: 'Segoe UI';\n        }\n        QMenu::item:selected {\n            background: rgba(255,255,255,42);\n            border: 1px solid rgba(255,255,255,82);\n            color: #ffffff;\n        }\n        QMenu::separator { background: rgba(255,255,255,18); height:1px; margin:4px 18px; }\n    ")
    menu._sync_glass_shape()
    _closer = _OutsideClickCloser(menu)
    app = QApplication.instance()

    def _install():
        app.installEventFilter(_closer)

    def _remove():
        app.removeEventFilter(_closer)
    menu.aboutToShow.connect(_install)
    menu.aboutToHide.connect(_remove)
    return menu

def _styled_submenu(parent_menu, title):
    sub = _GlassMenu(title, parent_menu)
    sub.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
    sub.setAutoFillBackground(False)
    sub.setWindowFlags(sub.windowFlags() | Qt.WindowType.FramelessWindowHint | Qt.WindowType.NoDropShadowWindowHint)
    sub.setStyleSheet(parent_menu.styleSheet())
    sub.setProperty('_match_parent_menu_width', True)
    sub._sync_glass_shape()
    parent_menu.addMenu(sub)
    return sub

# Custom drag-and-drop MIME format used to reorder folder/game tiles within
# the main library row by dragging one tile onto another. Kept separate
# from the plain-text 'game:<idx>' payload (below) which is used for the
# older, unrelated "drag a game onto a folder to file it into that folder"
# feature -- a PS5GameTile drag carries both formats at once so either
# drop target (another tile, to reorder; or a folder, to categorize) can
# pick out the one it understands.
_ROW_REORDER_MIME = 'application/x-ps5launcher-row-reorder'

class PS5FolderTile(QWidget):
    clicked_signal = pyqtSignal(str)
    edit_signal = pyqtSignal(str, str)
    drop_game = pyqtSignal(int, str)
    reorder_signal = pyqtSignal(int, int)
    # Fixed-size tile (200x310, set in __init__) -- the clip path and fonts
    # below never change between repaints, only the fill color/gradient
    # does. Building them fresh every paintEvent call was pure waste: at
    # 60fps during the tilt animation that's a QPainterPath rebuild + up
    # to 4 QFont constructions per tile per frame, times however many
    # tiles are visible. Caching them as class-level constants keeps the
    # exact same visual output at zero extra per-frame cost.
    _CLIP_PATH = None
    _INNER_PATH = None
    _FONT_EMPTY = None
    _FONT_DROP_HINT = None
    _FONT_COUNT = None
    _FONT_NAME = None

    @classmethod
    def _shared_paint_resources(cls):
        if cls._CLIP_PATH is None:
            p = QPainterPath()
            p.addRoundedRect(2, 2, 196, 306, 16, 16)
            cls._CLIP_PATH = p
            ia = QPainterPath()
            ia.addRoundedRect(7, 56, 187, 169, 10, 10)
            cls._INNER_PATH = ia
            cls._FONT_EMPTY = QFont('Segoe UI Emoji', 34)
            cls._FONT_DROP_HINT = QFont('Segoe UI', 10)
            cls._FONT_COUNT = QFont('Segoe UI', 8)
            cls._FONT_NAME = QFont('Segoe UI', 11, QFont.Weight.Bold)
        return (cls._CLIP_PATH, cls._INNER_PATH, cls._FONT_EMPTY, cls._FONT_DROP_HINT, cls._FONT_COUNT, cls._FONT_NAME)

    def __init__(self, folder_name, apps, index, selected=False, parent=None):
        super().__init__(parent)
        self.folder_name = folder_name
        self.apps = apps
        self.folder_index = index
        self._selected = selected
        self._hovered = False
        self._drag_over = False
        self.setFixedSize(200, 310)
        self.setAcceptDrops(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.setMouseTracking(True)
        self._tilt_dx_target, self._tilt_dx_cur = (0.0, 0.0)
        self._tilt_dy_target, self._tilt_dy_cur = (0.0, 0.0)
        self._tilt_timer = QTimer(self)
        self._tilt_timer.setInterval(16)
        self._tilt_timer.timeout.connect(self._tick_tilt)
        self._entrance_alpha = 1.0
        self._drag_start = QPoint()

    def _get_entrance_alpha(self):
        return self._entrance_alpha

    def _set_entrance_alpha(self, value):
        self._entrance_alpha = float(value)
        self.update()
    entranceAlpha = pyqtProperty(float, _get_entrance_alpha, _set_entrance_alpha)

    def set_selected(self, val):
        self._selected = val
        self.update()

    def enterEvent(self, e):
        self._hovered = True
        if not self._tilt_timer.isActive():
            self._tilt_timer.start()
        self.update()

    def leaveEvent(self, e):
        self._hovered = False
        self._tilt_dx_target = 0.0
        self._tilt_dy_target = 0.0
        if not self._tilt_timer.isActive():
            self._tilt_timer.start()
        self.update()

    def _tick_tilt(self):
        settled = True
        for cur_attr, target_attr in (('_tilt_dx_cur', '_tilt_dx_target'), ('_tilt_dy_cur', '_tilt_dy_target')):
            cur, target = (getattr(self, cur_attr), getattr(self, target_attr))
            if abs(cur - target) < 0.003:
                setattr(self, cur_attr, target)
                if target != 0.0:
                    settled = False
            else:
                setattr(self, cur_attr, cur + (target - cur) * 0.22)
                settled = False
        if settled:
            self._tilt_timer.stop()
        self.update()

    def mouseMoveEvent(self, event):
        pos = event.position() if hasattr(event, 'position') else event.pos()
        w, h = (self.width(), self.height())
        if w > 0:
            self._tilt_dx_target = max(-1.0, min(1.0, (pos.x() - w / 2.0) / (w / 2.0)))
        if h > 0:
            self._tilt_dy_target = max(-1.0, min(1.0, (pos.y() - h / 2.0) / (h / 2.0)))
        if not self._tilt_timer.isActive():
            self._tilt_timer.start()
        if not event.buttons() & Qt.MouseButton.LeftButton:
            super().mouseMoveEvent(event)
            return
        if (event.pos() - self._drag_start).manhattanLength() < 12:
            super().mouseMoveEvent(event)
            return
        # Picked up past the click threshold -- start a real drag so the
        # folder can be dropped onto another folder tile to reorder it.
        # (Qt's own DnD machinery takes the mouse from here; a plain click
        # never reaches this branch since it returns above.)
        drag = QDrag(self)
        mime = QMimeData()
        mime.setData(_ROW_REORDER_MIME, str(self.folder_index).encode())
        drag.setMimeData(mime)
        pix = self.grab().scaled(100, 100, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
        drag.setPixmap(pix)
        drag.setHotSpot(QPoint(pix.width() // 2, pix.height() // 2))
        drag.exec(Qt.DropAction.MoveAction)

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self._drag_start = event.pos()
        elif event.button() == Qt.MouseButton.RightButton:
            menu = _styled_menu(self)
            menu.addAction('Rename Folder', lambda: self.edit_signal.emit(self.folder_name, 'rename'))
            menu.addAction('Delete Folder', lambda: self.edit_signal.emit(self.folder_name, 'delete'))
            menu.exec(QCursor.pos())

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            if (event.pos() - self._drag_start).manhattanLength() < 12:
                self.clicked_signal.emit(self.folder_name)
        super().mouseReleaseEvent(event)

    def dragEnterEvent(self, e):
        md = e.mimeData()
        if md.hasFormat(_ROW_REORDER_MIME) or (md.hasText() and md.text().startswith('game:')):
            self._drag_over = True
            self.update()
            e.accept()
        else:
            e.ignore()

    def dragLeaveEvent(self, e):
        self._drag_over = False
        self.update()

    def dropEvent(self, e):
        self._drag_over = False
        self.update()
        md = e.mimeData()
        # A dragged game always carries plain-text 'game:<idx>' -- check
        # that first so an in-progress game reorder-drag dropped on a
        # folder still files the game into that folder as before, rather
        # than being swallowed by the newer reorder path below.
        if md.hasText() and md.text().startswith('game:'):
            self.drop_game.emit(int(md.text().split(':')[1]), self.folder_name)
            e.accept()
            return
        if md.hasFormat(_ROW_REORDER_MIME):
            try:
                src_idx = int(bytes(md.data(_ROW_REORDER_MIME)).decode())
            except (ValueError, UnicodeDecodeError):
                e.ignore()
                return
            self.reorder_signal.emit(src_idx, self.folder_index)
            e.accept()
            return
        e.ignore()

    def paintEvent(self, event):
        p = QPainter(self)
        if self._entrance_alpha < 0.999:
            p.setOpacity(max(0.0, min(1.0, self._entrance_alpha)))
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        W, H = (self.width(), self.height())
        tdx, tdy = (self._tilt_dx_cur, self._tilt_dy_cur)
        if tdx * tdx + tdy * tdy > 0.0001:
            _TILT_MAX_ANGLE = 16.0
            _TILT_DEPTH = 220.0
            theta = -_TILT_MAX_ANGLE * tdx
            phi = _TILT_MAX_ANGLE * tdy
            p.setTransform(_tile_seesaw_transform(W, H, theta, phi, _TILT_DEPTH))
        path, ia, font_empty, font_drop_hint, font_count, font_name = self._shared_paint_resources()
        p.setClipPath(path)
        if self._drag_over:
            g = QLinearGradient(0, 0, 0, 310)
            g.setColorAt(0, QColor(80, 80, 180, 60))
            g.setColorAt(1, QColor(30, 30, 90, 40))
            p.fillPath(path, QBrush(g))
        elif self._selected:
            g = QLinearGradient(0, 0, 0, 310)
            g.setColorAt(0, QColor(255, 255, 255, 28))
            g.setColorAt(1, QColor(255, 255, 255, 12))
            p.fillPath(path, QBrush(g))
        elif self._hovered:
            p.fillPath(path, QBrush(QColor(255, 255, 255, 18)))
        else:
            p.fillPath(path, QBrush(QColor(255, 255, 255, 10)))
        p.fillPath(ia, QBrush(QColor(255, 255, 255, 20 if self._drag_over else 12)))
        pos4 = [(20, 62, 78, 72), (102, 62, 78, 72), (20, 139, 78, 72), (102, 139, 78, 72)]
        for i, app in enumerate(self.apps[:4]):
            x, y, w, h = pos4[i]
            icon_path = app.get('icon') or app.get('exe', '')
            pix = _get_prescaled_art_async(icon_path, 78, _art_repaint_cb(self))
            if not pix.isNull():
                p.drawPixmap(x, y, w, h, pix)
        if not self.apps:
            p.setPen(QColor('#333355'))
            p.setFont(font_empty)
            p.drawText(7, 56, 187, 169, Qt.AlignmentFlag.AlignCenter, '📁')
        if self._drag_over:
            p.setPen(QColor('#aaaaff'))
            p.setFont(font_drop_hint)
            p.drawText(7, 56, 187, 169, Qt.AlignmentFlag.AlignCenter, '+ Drop Here')
        p.setPen(QColor('#555577'))
        p.setFont(font_count)
        p.drawText(0, 232, 200, 20, Qt.AlignmentFlag.AlignCenter, f'{len(self.apps)} Games')
        p.setPen(QColor('#ffffff' if self._selected or self._hovered else '#ccccee'))
        p.setFont(font_name)
        p.drawText(8, 253, 184, 52, Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignTop | Qt.TextFlag.TextWordWrap, self.folder_name)

def _tile_seesaw_transform(w: float, h: float, theta_deg: float, phi_deg: float, depth: float) -> 'QTransform':
    from PyQt6.QtGui import QTransform
    theta = math.radians(theta_deg)
    phi = math.radians(phi_deg)
    d = depth
    cx, cy = (w / 2.0, h / 2.0)

    def _mat_mul(a, b):
        a11, a12, a13, a21, a22, a23, a31, a32, a33 = a
        b11, b12, b13, b21, b22, b23, b31, b32, b33 = b
        return (a11 * b11 + a12 * b21 + a13 * b31, a11 * b12 + a12 * b22 + a13 * b32, a11 * b13 + a12 * b23 + a13 * b33, a21 * b11 + a22 * b21 + a23 * b31, a21 * b12 + a22 * b22 + a23 * b32, a21 * b13 + a22 * b23 + a23 * b33, a31 * b11 + a32 * b21 + a33 * b31, a31 * b12 + a32 * b22 + a33 * b32, a31 * b13 + a32 * b23 + a33 * b33)
    to_origin = (1, 0, 0, 0, 1, 0, -cx, -cy, 1)
    perspective = (math.cos(theta), math.sin(theta) * math.sin(phi), -math.sin(theta) * math.cos(phi) / d, 0.0, math.cos(phi), math.sin(phi) / d, 0.0, 0.0, 1.0)
    back = (1, 0, 0, 0, 1, 0, cx, cy, 1)
    m = _mat_mul(to_origin, perspective)
    m = _mat_mul(m, back)
    return QTransform(*m)

class PS5GameTile(QWidget):
    clicked_signal = pyqtSignal(int)
    edit_signal = pyqtSignal(int, str)
    reorder_signal = pyqtSignal(int, int)
    _TILE_BASE = 153
    _TILE_SEL = int(153 * 1.3)

    def __init__(self, app_data, index, selected=False, parent=None):
        super().__init__(parent)
        self.app_data = app_data
        self.index = index
        # Set by the launcher only for tiles in the main library row
        # (folders + uncategorized games), to this tile's position among
        # *all* row columns -- used solely as the drag-reorder payload, so
        # it can be dropped on any other tile in that row to move here.
        # Left None for tiles elsewhere (e.g. the offscreen preview row),
        # which makes reorder-dragging a no-op there.
        self.row_col = None
        self._selected = selected
        self._hovered = False
        self._drag_start = QPoint()
        self._anim_sz = float(self._TILE_SEL if selected else self._TILE_BASE)
        sz = int(self._anim_sz)
        self.setFixedSize(sz, sz)
        self.setAcceptDrops(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setMouseTracking(True)
        self._tilt_dx_target, self._tilt_dx_cur = (0.0, 0.0)
        self._tilt_dy_target, self._tilt_dy_cur = (0.0, 0.0)
        self._tilt_timer = QTimer(self)
        self._tilt_timer.setInterval(16)
        self._tilt_timer.timeout.connect(self._tick_tilt)
        self._size_anim = QPropertyAnimation(self, b'anim_size', self)
        self._size_anim.setDuration(220)
        self._size_anim.setEasingCurve(QEasingCurve.Type.OutQuart)
        self._dim_alpha = float(0 if selected else 35)
        self._dim_anim = QPropertyAnimation(self, b'dim_alpha_prop', self)
        self._dim_anim.setDuration(200)
        self._dim_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._entrance_alpha = 1.0
        self._clip_cache_key = None
        self._clip_cache_path = None
        if selected:
            QTimer.singleShot(0, self.raise_)

    @pyqtProperty(float)
    def anim_size(self):
        return self._anim_sz

    @anim_size.setter
    def anim_size(self, val):
        self._anim_sz = val
        sz = int(val)
        self.setFixedSize(sz, sz)
        self.update()

    @pyqtProperty(float)
    def dim_alpha_prop(self):
        return self._dim_alpha

    @dim_alpha_prop.setter
    def dim_alpha_prop(self, val):
        self._dim_alpha = val
        self.update()

    def _get_entrance_alpha(self):
        return self._entrance_alpha

    def _set_entrance_alpha(self, value):
        self._entrance_alpha = float(value)
        self.update()
    entranceAlpha = pyqtProperty(float, _get_entrance_alpha, _set_entrance_alpha)

    def set_selected(self, val):
        self._selected = val
        target_sz = float(self._TILE_SEL if val else self._TILE_BASE)
        self._size_anim.stop()
        self._size_anim.setStartValue(self._anim_sz)
        self._size_anim.setEndValue(target_sz)
        self._size_anim.start()
        target_dim = float(0 if val else 35)
        self._dim_anim.stop()
        self._dim_anim.setStartValue(self._dim_alpha)
        self._dim_anim.setEndValue(target_dim)
        self._dim_anim.start()
        if val:
            self.raise_()
        self.update()

    def enterEvent(self, e):
        self._hovered = True
        if not self._tilt_timer.isActive():
            self._tilt_timer.start()
        self.update()

    def leaveEvent(self, e):
        self._hovered = False
        self._tilt_dx_target = 0.0
        self._tilt_dy_target = 0.0
        if not self._tilt_timer.isActive():
            self._tilt_timer.start()
        self.update()

    def _tick_tilt(self):
        settled = True
        for cur_attr, target_attr in (('_tilt_dx_cur', '_tilt_dx_target'), ('_tilt_dy_cur', '_tilt_dy_target')):
            cur, target = (getattr(self, cur_attr), getattr(self, target_attr))
            if abs(cur - target) < 0.003:
                setattr(self, cur_attr, target)
                if target != 0.0:
                    settled = False
            else:
                setattr(self, cur_attr, cur + (target - cur) * 0.22)
                settled = False
        if settled:
            self._tilt_timer.stop()
        self.update()

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self._drag_start = event.pos()
        elif event.button() == Qt.MouseButton.RightButton:
            self._show_ctx()

    def _show_ctx(self):
        menu = _styled_menu(self)
        menu.addAction('FPS', lambda: self.edit_signal.emit(self.index, 'launch_fps'))
        menu.addAction('Super Frame', lambda: self.edit_signal.emit(self.index, 'launch_super_frame'))
        ch_menu = _styled_submenu(menu, 'Change')
        ch_menu.addAction('Name', lambda: self.edit_signal.emit(self.index, 'rename'))
        ch_menu.addAction('Icon', lambda: self.edit_signal.emit(self.index, 'change_icon'))
        ch_menu.addAction('Background', lambda: self.edit_signal.emit(self.index, 'change_background'))
        ch_menu.addAction('Name Logo', lambda: self.edit_signal.emit(self.index, 'change_name_logo'))
        ch_menu.addAction('Audio Theme', lambda: self.edit_signal.emit(self.index, 'change_audio_theme'))
        ch_menu.addAction('Audio from File', lambda: self.edit_signal.emit(self.index, 'change_audio_file'))
        ch_menu.addAction('Trim', lambda: self.edit_signal.emit(self.index, 'trim_audio_theme'))
        ch_menu.addAction('Game Run', lambda: self.edit_signal.emit(self.index, 'change_game_run'))
        ch_menu.addAction('Run With', lambda: self.edit_signal.emit(self.index, 'run_with'))
        dl_menu = _styled_submenu(menu, 'Download')
        dl_menu.addAction('Icon', lambda: self.edit_signal.emit(self.index, 'download_icon'))
        dl_menu.addAction('BG', lambda: self.edit_signal.emit(self.index, 'auto_background'))
        dl_menu.addAction('Name Logo', lambda: self.edit_signal.emit(self.index, 'download_name_logo'))
        menu.addAction('Path', lambda: self.edit_signal.emit(self.index, 'open_file_location'))
        menu.addAction('Move to Folder', lambda: self.edit_signal.emit(self.index, 'move_to_folder'))
        menu.addAction('Delete', lambda: self.edit_signal.emit(self.index, 'delete'))
        menu.exec(QCursor.pos())

    def mouseMoveEvent(self, event):
        pos = event.position() if hasattr(event, 'position') else event.pos()
        w, h = (self.width(), self.height())
        if w > 0:
            self._tilt_dx_target = max(-1.0, min(1.0, (pos.x() - w / 2.0) / (w / 2.0)))
        if h > 0:
            self._tilt_dy_target = max(-1.0, min(1.0, (pos.y() - h / 2.0) / (h / 2.0)))
        if not self._tilt_timer.isActive():
            self._tilt_timer.start()
        if not event.buttons() & Qt.MouseButton.LeftButton:
            return
        if (event.pos() - self._drag_start).manhattanLength() < 12:
            return
        drag = QDrag(self)
        mime = QMimeData()
        mime.setText(f'game:{self.index}')
        if self.row_col is not None:
            # This tile is in the main library row -- also carry the
            # generic row-reorder payload alongside the existing
            # 'game:<idx>' text, so dropping it on another tile there
            # reorders instead of (or as well as) the folder-filing drop
            # already handled by PS5FolderTile.
            mime.setData(_ROW_REORDER_MIME, str(self.row_col).encode())
        drag.setMimeData(mime)
        pix = self.grab().scaled(100, 100, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
        drag.setPixmap(pix)
        drag.setHotSpot(QPoint(pix.width() // 2, pix.height() // 2))
        drag.exec(Qt.DropAction.MoveAction)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            if (event.pos() - self._drag_start).manhattanLength() < 12:
                self.clicked_signal.emit(self.index)

    def dragEnterEvent(self, e):
        md = e.mimeData()
        e.accept() if (md.hasText() or md.hasFormat(_ROW_REORDER_MIME)) else e.ignore()

    def dropEvent(self, e):
        md = e.mimeData()
        if md.hasFormat(_ROW_REORDER_MIME) and self.row_col is not None:
            try:
                src_idx = int(bytes(md.data(_ROW_REORDER_MIME)).decode())
            except (ValueError, UnicodeDecodeError):
                e.ignore()
                return
            self.reorder_signal.emit(src_idx, self.row_col)
            e.accept()
            return
        e.ignore()

    def paintEvent(self, event):
        p = QPainter(self)
        if self._entrance_alpha < 0.999:
            p.setOpacity(max(0.0, min(1.0, self._entrance_alpha)))
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        W, H = (self.width(), self.height())
        tdx, tdy = (self._tilt_dx_cur, self._tilt_dy_cur)
        if tdx * tdx + tdy * tdy > 0.0001:
            _TILT_MAX_ANGLE = 16.0
            _TILT_DEPTH = 220.0
            theta = -_TILT_MAX_ANGLE * tdx
            phi = _TILT_MAX_ANGLE * tdy
            p.setTransform(_tile_seesaw_transform(W, H, theta, phi, _TILT_DEPTH))
        RADIUS = max(_CORNER_RADIUS_MIN, min(_CORNER_RADIUS_MAX, round(min(W, H) * _CORNER_RADIUS_FRACTION)))
        if self._selected:
            scale_w, scale_h = (W, H)
            art_x = 0
            art_y = 0
            dim_alpha = int(self._dim_alpha)
        elif self._hovered:
            scale_w = int((W - 4) * 1.0)
            scale_h = int((H - 4) * 1.0)
            art_x = (W - scale_w) // 2
            art_y = (H - scale_h) // 2
            dim_alpha = max(int(self._dim_alpha), 10)
        else:
            scale_w = int((W - 4) * 0.99)
            scale_h = int((H - 4) * 0.99)
            art_x = (W - scale_w) // 2
            art_y = (H - scale_h) // 2
            dim_alpha = max(int(self._dim_alpha), 0)
        FADE_START = 0.6
        # The tilt animation (mouse move while hovering) repaints at 60fps
        # but only changes tdx/tdy -- art_x/art_y/scale_w/scale_h/RADIUS
        # stay identical frame-to-frame in that case (they only change on
        # the separate, much rarer selection-size animation). Rebuilding
        # this QPainterPath from scratch every single tilt frame was pure
        # waste; cache it per-instance and only rebuild when the actual
        # clip geometry changes.
        clip_key = (art_x, art_y, scale_w, scale_h, RADIUS)
        if getattr(self, '_clip_cache_key', None) != clip_key:
            full_clip = QPainterPath()
            full_clip.addRoundedRect(art_x, art_y, scale_w, scale_h, RADIUS, RADIUS)
            self._clip_cache_key = clip_key
            self._clip_cache_path = full_clip
        full_clip = self._clip_cache_path
        p.setClipPath(full_clip)
        icon_path = self.app_data.get('icon', '')
        exe_path = self.app_data.get('exe', '')
        art_path = icon_path
        pix = _get_prescaled_art_async(icon_path, self._TILE_SEL, _art_repaint_cb(self))
        if pix.isNull():
            art_path = exe_path
            pix = _get_prescaled_art_async(exe_path, self._TILE_SEL, _art_repaint_cb(self))
        img_x, img_y, img_w, img_h = (art_x, art_y, 0, 0)
        if not pix.isNull():
            filled = _get_rounded_tile_art(art_path, pix, max(scale_w, scale_h), crop_badge=True)
            if scale_w != scale_h:
                filled = _scale_crop_to_rect_cached(filled, scale_w, scale_h)
            img_w, img_h = (filled.width(), filled.height())
            img_x = art_x
            img_y = art_y
            if self._selected:
                tmp = _get_faded_tile_art(art_path, filled, img_w, img_h, FADE_START)
                p.drawImage(img_x, img_y, tmp)
            else:
                p.drawPixmap(img_x, img_y, filled)
            plat = _detect_game_platform_cached(exe_path)
            plat_label = _PLATFORM_BADGE_LABELS.get(plat)
            if plat_label:
                _draw_platform_badge(p, img_x, img_y, img_w, img_h, plat_label)
        p.setClipping(False)

class _WidgetOutsideClickFilter(QObject):

    def __init__(self, popup):
        super().__init__(popup)
        self._popup = popup
        self._closing = False

    def eventFilter(self, obj, event):
        if self._closing:
            return False
        et = event.type()
        if et in (QEvent.Type.MouseButtonPress, QEvent.Type.MouseButtonDblClick):
            if not self._popup.isVisible():
                return False
            gp = event.globalPosition().toPoint() if hasattr(event, 'globalPosition') else event.globalPos()
            w = QApplication.widgetAt(gp)
            inside_main = w is not None and (w is self._popup or self._popup.isAncestorOf(w))
            sub_panel = getattr(self._popup, '_sub_panel', None)
            inside_sub = bool(sub_panel is not None and sub_panel.isVisible() and (w is not None) and (w is sub_panel or sub_panel.isAncestorOf(w)))
            if not (inside_main or inside_sub):
                self._closing = True
                self._popup._fade_out()
        return False

class _ContextPopup(QWidget):
    _SUBMENUS = {'download': [('Icon', 'icon_download'), ('BG', 'auto_bg'), ('Name Logo', 'name_logo_download'), ('Auto YouTube Audio', 'youtube_audio_download')], 'change': [('Name', 'rename'), ('Icon', 'icon'), ('Background', 'background'), ('Name Logo', 'name_logo'), ('Audio Theme', 'audio_theme'), ('Audio from File', 'audio_file'), ('Trim', 'audio_trim'), ('Game Run', 'game_run'), ('Run With', 'run_with')]}
    _SUBMENU_ARROW = '  ▸'
    run_with_trainer_requested = pyqtSignal()
    run_with_requested = pyqtSignal()
    launch_fps_requested = pyqtSignal()
    launch_super_frame_requested = pyqtSignal()
    rename_requested = pyqtSignal()
    icon_requested = pyqtSignal()
    icon_download_requested = pyqtSignal()
    background_requested = pyqtSignal()
    name_logo_requested = pyqtSignal()
    audio_theme_requested = pyqtSignal()
    audio_file_requested = pyqtSignal()
    audio_trim_requested = pyqtSignal()
    name_logo_download_requested = pyqtSignal()
    youtube_audio_download_requested = pyqtSignal()
    auto_bg_requested = pyqtSignal()
    path_requested = pyqtSignal()
    move_to_folder_requested = pyqtSignal()
    game_run_requested = pyqtSignal()
    delete_requested = pyqtSignal()
    controller_profile_requested = pyqtSignal()
    folder_delete_requested = pyqtSignal()
    _ITEM_H = 46
    _MENU_W = 264
    _MENU_PAD = 8
    _MENU_GAP = 2
    _HEADER_H = 0
    _FOOTER_H = 0

    @classmethod
    def _menu_height(cls, item_count: int) -> int:
        item_gaps = max(0, item_count - 1) * cls._MENU_GAP
        return cls._HEADER_H + cls._FOOTER_H + item_count * cls._ITEM_H + item_gaps

    def __init__(self, kind, item, anchor: QRect, parent=None):
        super().__init__(parent)
        self.kind = kind
        self.item = item
        self._items: list = []
        self._sel = 0
        self._sub_entries: list = []
        self._sub_sel: int = 0
        self._submenu_focused = False
        self._sub_panel = None
        self._sub_row_widgets: list = []
        self._sub_open_for_idx = None
        self._sub_close_timer_alive = True
        self._sub_close_timer = QTimer(self)
        self._sub_close_timer.setSingleShot(True)
        self._sub_close_timer.setInterval(220)
        self._sub_close_timer.timeout.connect(self._timer_close_submenu)
        self._sub_close_timer.destroyed.connect(self._on_sub_close_timer_destroyed)
        self._closing = False
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAutoFillBackground(False)
        self.setStyleSheet('background: transparent;')
        self.setCursor(Qt.CursorShape.ArrowCursor)
        self.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self._build(anchor)
        _start_live_menu_backdrop(self)
        self._fade_in()
        self.setFocus()
        self._outside_filter = _WidgetOutsideClickFilter(self)
        app = QApplication.instance()
        if app:
            app.installEventFilter(self._outside_filter)

    def closeEvent(self, event):
        _stop_live_menu_backdrop(self)
        app = QApplication.instance()
        if app and getattr(self, '_outside_filter', None):
            try:
                app.removeEventFilter(self._outside_filter)
            except RuntimeError:
                pass
        self._close_submenu(immediate=True)
        super().closeEvent(event)

    def resizeEvent(self, event):
        super().resizeEvent(event)

    def paintEvent(self, event):
        _paint_menu_surface(self)

    def _build(self, anchor: QRect):
        title_text = self.item.get('title', '') if isinstance(self.item, dict) else str(self.item)
        if isinstance(self.item, dict):
            entries = [('Run With Trainer', 'run_with_trainer'), ('FPS', 'launch_fps'), ('Super Frame', 'launch_super_frame'), ('Path', 'open_file_location'), ('Change', 'change'), ('Download', 'download'), ('Move to Folder', 'move_to_folder'), ('Controller Profile', 'controller_profile'), ('Delete', 'delete')]
        else:
            entries = [('Rename', 'rename'), ('Delete', 'folder_delete')]
        self._items = entries
        self._main_entries = entries
        self._confirming = False
        self._pending_delete_action = None
        n = len(entries)
        total_h = self._menu_height(n)
        px = anchor.left()
        py = anchor.top() - total_h - 8
        if (parent := self.parent()):
            pw, ph = (parent.width(), parent.height())
            if px + self._MENU_W > pw:
                px = pw - self._MENU_W - 8
            if px < 8:
                px = 8
            if py < 8:
                py = anchor.bottom() + 8
        self.setGeometry(px, py, self._MENU_W, total_h)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(self._MENU_GAP)
        self._row_widgets = []
        self._danger_actions = {'delete', 'folder_delete'}
        for idx, (label, action) in enumerate(entries):
            has_sub = action in self._SUBMENUS
            row = QLabel(label + (self._SUBMENU_ARROW if has_sub else ''))
            row.setFixedHeight(self._ITEM_H)
            row.setCursor(Qt.CursorShape.ArrowCursor)
            row.setFont(QFont('Segoe UI', 11))
            row.setContentsMargins(16, 0, 12, 0)
            row.setProperty('_action', action)
            row.enterEvent = lambda ev, i=idx: self._on_row_hover(i)
            self._row_widgets.append(row)
            layout.addWidget(row)
        self._refresh_rows()

    def _on_row_hover(self, idx):
        self._submenu_focused = False
        self._sel = idx
        self._refresh_rows()
        action = self._items[idx][1] if idx < len(self._items) else None
        if action in self._SUBMENUS:
            self._safe_stop_sub_close_timer()
            self._open_submenu(idx)
            self._refresh_sub_rows()
        else:
            self._safe_stop_sub_close_timer()
            if self._sub_panel is not None:
                self._close_submenu()

    def _refresh_rows(self):
        try:
            for i, row in enumerate(self._row_widgets):
                is_danger = row.property('_action') in self._danger_actions
                if i == self._sel and (not self._submenu_focused):
                    bg = 'rgba(170,35,35,180)' if is_danger else 'rgba(255,255,255,42)'
                    row.setStyleSheet(f'\n                    color: #ffffff;\n                    background: {bg};\n                    border-radius: 10px;\n                    margin: 0px;\n                ')
                else:
                    color = '#ff9d9d' if is_danger else 'rgba(235,235,235,215)'
                    row.setStyleSheet(f'\n                    color: {color};\n                    background: transparent;\n                    border-radius: 10px;\n                    margin: 0px;\n                ')
        except RuntimeError:
            # Row QLabels (or this popup itself) were already torn down by
            # a close that happened while a stray/queued hover event for
            # one of these rows was still in flight -- nothing left to
            # style, safe to drop.
            pass
    _SIGNAL_MAP = {'run_with_trainer': 'run_with_trainer_requested', 'run_with': 'run_with_requested', 'launch_fps': 'launch_fps_requested', 'launch_super_frame': 'launch_super_frame_requested', 'rename': 'rename_requested', 'icon': 'icon_requested', 'icon_download': 'icon_download_requested', 'background': 'background_requested', 'name_logo': 'name_logo_requested', 'audio_theme': 'audio_theme_requested', 'audio_file': 'audio_file_requested', 'audio_trim': 'audio_trim_requested', 'name_logo_download': 'name_logo_download_requested', 'youtube_audio_download': 'youtube_audio_download_requested', 'auto_bg': 'auto_bg_requested', 'open_file_location': 'path_requested', 'move_to_folder': 'move_to_folder_requested', 'game_run': 'game_run_requested', 'delete': 'delete_requested', 'controller_profile': 'controller_profile_requested', 'folder_delete': 'folder_delete_requested'}

    def _confirm(self):
        if self._closing:
            return
        if self._submenu_focused:
            self._confirm_sub()
            return
        action = self._items[self._sel][1]
        if action in self._SUBMENUS:
            self._enter_submenu()
            return
        self._closing = True
        app = QApplication.instance()
        if app and getattr(self, '_outside_filter', None):
            try:
                app.removeEventFilter(self._outside_filter)
            except RuntimeError:
                pass
        action = self._items[self._sel][1]
        sig_name = self._SIGNAL_MAP.get(action)
        if sig_name:
            getattr(self, sig_name).emit()
        try:
            self.close()
        except RuntimeError:
            pass

    def _confirm_sub(self):
        if self._closing or not self._sub_entries:
            return
        self._closing = True
        app = QApplication.instance()
        if app and getattr(self, '_outside_filter', None):
            try:
                app.removeEventFilter(self._outside_filter)
            except RuntimeError:
                pass
        action = self._sub_entries[self._sub_sel][1]
        sig_name = self._SIGNAL_MAP.get(action)
        if sig_name:
            getattr(self, sig_name).emit()
        try:
            self.close()
        except RuntimeError:
            pass

    def _enter_submenu(self):
        action = self._items[self._sel][1]
        if action not in self._SUBMENUS:
            return
        self._sub_close_timer.stop()
        self._open_submenu(self._sel)
        self._submenu_focused = True
        self._sub_sel = 0
        self._refresh_sub_rows()
        self._refresh_rows()

    def _leave_submenu(self):
        if not self._submenu_focused:
            return
        self._submenu_focused = False
        self._sub_sel = 0
        self._refresh_rows()
        self._refresh_sub_rows()

    def _on_sub_close_timer_destroyed(self):
        # The C/C++ QTimer object is gone (e.g. this popup was closed and
        # deleted). Flip a plain-Python flag so any stray panel event
        # (leaveEvent/enterEvent firing on a submenu panel that outlived
        # us, since it's parented to `host`, not to this popup) can no
        # longer touch the dead QTimer and crash with "wrapped C/C++
        # object of type QTimer has been deleted".
        self._sub_close_timer_alive = False

    def _safe_stop_sub_close_timer(self):
        if not self._sub_close_timer_alive:
            return
        try:
            self._sub_close_timer.stop()
        except RuntimeError:
            self._sub_close_timer_alive = False

    def _safe_start_sub_close_timer(self):
        if not self._sub_close_timer_alive:
            return
        try:
            self._sub_close_timer.start()
        except RuntimeError:
            self._sub_close_timer_alive = False

    def _open_submenu(self, idx):
        action = self._items[idx][1]
        sub_entries = self._SUBMENUS.get(action)
        if not sub_entries:
            return
        if self._sub_panel is not None and self._sub_open_for_idx == idx:
            return
        self._close_submenu(immediate=True)
        self._sub_entries = sub_entries
        self._sub_open_for_idx = idx
        self._sub_sel = 0
        n = len(sub_entries)
        panel_w = self._MENU_W
        panel_h = self._menu_height(n)
        host = self.parent()
        panel = _TransparentMenuSurface(host)
        panel.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        panel.setAutoFillBackground(False)
        panel.setStyleSheet('background: transparent;')
        panel.setCursor(Qt.CursorShape.ArrowCursor)
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(self._MENU_GAP)
        self._sub_row_widgets = []
        for i, (label, act) in enumerate(sub_entries):
            row = QLabel(label)
            row.setFixedHeight(self._ITEM_H)
            row.setCursor(Qt.CursorShape.ArrowCursor)
            row.setFont(QFont('Segoe UI', 11))
            row.setContentsMargins(16, 0, 12, 0)
            row.setProperty('_action', act)
            row.enterEvent = lambda ev, i=i: self._on_sub_row_hover(i)
            self._sub_row_widgets.append(row)
            lay.addWidget(row)
        panel.setFixedSize(panel_w, panel_h)
        row_widget = self._row_widgets[idx]
        row_center_y_local = row_widget.y() + row_widget.height() // 2
        self_pos = self.pos()
        center_y_in_parent = self_pos.y() + row_center_y_local
        target_y = center_y_in_parent - panel_h // 2
        gap = 8
        target_x = self_pos.x() + self.width() + gap
        if host is not None:
            if target_x + panel_w > host.width():
                target_x = self_pos.x() - panel_w - gap
            target_x = max(4, target_x)
            target_y = max(4, min(target_y, max(4, host.height() - panel_h - 4)))
        start_x = target_x - 34
        panel.move(start_x, target_y)
        anim_pos = QPropertyAnimation(panel, b'pos', panel)
        anim_pos.setDuration(180)
        anim_pos.setStartValue(QPoint(start_x, target_y))
        anim_pos.setEndValue(QPoint(target_x, target_y))
        anim_pos.setEasingCurve(QEasingCurve.Type.OutCubic)
        anim_pos.start()
        panel._open_anims = anim_pos
        panel.enterEvent = lambda ev: self._safe_stop_sub_close_timer()
        panel.leaveEvent = lambda ev: self._safe_start_sub_close_timer()
        panel.mousePressEvent = self._on_sub_panel_click
        panel.show()
        panel.raise_()
        self._sub_panel = panel
        self._refresh_sub_rows()

    def _close_submenu(self, immediate=False):
        self._sub_close_timer.stop()
        was_focused = self._submenu_focused
        self._submenu_focused = False
        panel = self._sub_panel
        self._sub_panel = None
        self._sub_open_for_idx = None
        self._sub_entries = []
        # Break the row-level closures too, same reason as the panel
        # closures below: rows are children of `panel`, which can
        # outlive `self` during its close animation / pending
        # deleteLater, so a stray hover could still fire into
        # `self._on_sub_row_hover` -> `self._sub_close_timer.stop()`
        # after `self` (and its QTimer) are destroyed.
        for row in self._sub_row_widgets:
            row.enterEvent = lambda ev: None
        self._sub_row_widgets = []
        if was_focused:
            self._refresh_rows()
        if panel is None:
            return
        # Break the closure back to `self`: panel is parented to `host`,
        # not to this popup, so it can outlive `self` while its
        # deleteLater/close-animation is pending. Without this, a stray
        # enter/leaveEvent could still fire on it after `self` (and its
        # QTimer) are destroyed.
        panel.enterEvent = lambda ev: None
        panel.leaveEvent = lambda ev: None
        if immediate:
            panel.hide()
            panel.deleteLater()
            return
        from PyQt6.QtCore import QParallelAnimationGroup
        cur_pos = panel.pos()
        anim_pos = QPropertyAnimation(panel, b'pos', panel)
        anim_pos.setDuration(130)
        anim_pos.setStartValue(cur_pos)
        anim_pos.setEndValue(QPoint(cur_pos.x() - 24, cur_pos.y()))
        anim_pos.setEasingCurve(QEasingCurve.Type.InCubic)
        group = QParallelAnimationGroup(panel)
        group.addAnimation(anim_pos)
        group.finished.connect(panel.deleteLater)
        group.start()
        panel._close_anim = group

    def _maybe_close_submenu(self):
        if not self._submenu_focused:
            self._close_submenu()

    def _timer_close_submenu(self):
        if self._sub_panel is None:
            return
        gp = QCursor.pos()
        w = QApplication.widgetAt(gp)
        if w is not None and (w is self or self.isAncestorOf(w) or w is self._sub_panel or self._sub_panel.isAncestorOf(w)):
            return
        self._close_submenu()

    def _on_sub_row_hover(self, i):
        self._safe_stop_sub_close_timer()
        focus_just_entered = not self._submenu_focused
        self._submenu_focused = True
        self._sub_sel = i
        self._refresh_sub_rows()
        if focus_just_entered:
            self._refresh_rows()

    def _on_sub_panel_click(self, e):
        pos = e.position().toPoint() if hasattr(e, 'position') else e.pos()
        for i, row in enumerate(self._sub_row_widgets):
            if row.geometry().contains(pos):
                self._sub_sel = i
                self._submenu_focused = True
                self._refresh_sub_rows()
                self._confirm_sub()
                return

    def _refresh_sub_rows(self):
        try:
            for i, row in enumerate(self._sub_row_widgets):
                if i == self._sub_sel and self._submenu_focused:
                    row.setStyleSheet('\n                    color: #ffffff;\n                    background: rgba(255,255,255,48);\n                    border-radius: 10px;\n                    margin: 0px;\n                ')
                else:
                    row.setStyleSheet('\n                    color: rgba(235,235,235,215);\n                    background: transparent;\n                    border-radius: 10px;\n                    margin: 0px;\n                ')
        except RuntimeError:
            # Same as _refresh_rows: the submenu panel (or its rows) was
            # already deleted by a close that raced a queued hover event.
            pass

    def keyPressEvent(self, e):
        k = e.key()
        if k in (Qt.Key.Key_Escape, Qt.Key.Key_Backspace):
            if self._submenu_focused:
                self._leave_submenu()
            else:
                self.close()
        elif k in (Qt.Key.Key_Up, Qt.Key.Key_W):
            if self._submenu_focused:
                self._sub_sel = (self._sub_sel - 1) % len(self._sub_entries)
                self._refresh_sub_rows()
            else:
                self._move_main_sel(-1)
        elif k in (Qt.Key.Key_Down, Qt.Key.Key_S):
            if self._submenu_focused:
                self._sub_sel = (self._sub_sel + 1) % len(self._sub_entries)
                self._refresh_sub_rows()
            else:
                self._move_main_sel(1)
        elif k in (Qt.Key.Key_Right, Qt.Key.Key_D):
            self._enter_submenu()
        elif k in (Qt.Key.Key_Left, Qt.Key.Key_A):
            self._leave_submenu()
        elif k in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
            self._confirm()

    def mousePressEvent(self, e):
        pos = e.position().toPoint() if hasattr(e, 'position') else e.pos()
        for i, row in enumerate(self._row_widgets):
            if row.geometry().contains(pos):
                self._sel = i
                self._refresh_rows()
                self._confirm()
                return

    def _move_main_sel(self, delta):
        self._sel = (self._sel + delta) % len(self._items)
        self._refresh_rows()
        # Just moving the selection (keyboard/gamepad up-down) should
        # never open the Change/Download submenu on its own -- only an
        # explicit enter action (Right / Cross on gamepad, mouse click)
        # should do that. Close any panel left open from a previous
        # hover/enter so it doesn't linger over the wrong row.
        if self._sub_panel is not None:
            self._close_submenu()

    def navigate_pad(self, direction):
        if self._submenu_focused:
            if not self._sub_entries:
                return
            if direction == 'up':
                self._sub_sel = (self._sub_sel - 1) % len(self._sub_entries)
            else:
                self._sub_sel = (self._sub_sel + 1) % len(self._sub_entries)
            self._refresh_sub_rows()
            return
        self._move_main_sel(-1 if direction == 'up' else 1)

    def confirm_pad(self):
        self._confirm()

    def enter_submenu_pad(self):
        if not self._closing:
            self._enter_submenu()

    def exit_submenu_pad(self):
        if not self._closing:
            self._leave_submenu()

    def back_pad(self):
        if self._submenu_focused:
            self._leave_submenu()
        else:
            self.close()

    def _fade_in(self):
        self.setWindowOpacity(0.0)
        a = QPropertyAnimation(self, b'windowOpacity', self)
        a.setDuration(140)
        a.setStartValue(0.0)
        a.setEndValue(1.0)
        a.setEasingCurve(QEasingCurve.Type.OutCubic)
        a.start()
        self._anim = a

    def _fade_out(self):
        a = QPropertyAnimation(self, b'windowOpacity', self)
        a.setDuration(120)
        a.setStartValue(self.windowOpacity())
        a.setEndValue(0.0)
        a.setEasingCurve(QEasingCurve.Type.InCubic)
        a.finished.connect(self.close)
        a.start()
        self._anim = a
import math as _math

def _t3d_ease(t):
    t = max(0.0, min(1.0, t))
    return -(_math.cos(_math.pi * t) - 1.0) / 2.0

def _t3d_draw_flat(p, pix, w, h, alpha=1.0):
    if not pix or pix.isNull():
        return
    ox = (w - pix.width()) // 2
    oy = (h - pix.height()) // 2
    p.setOpacity(alpha)
    p.drawPixmap(ox, oy, pix)
    p.setOpacity(1.0)

def _tr_crossfade(p, fp, tp, w, h, t):
    # Previous background is always drawn fully opaque first, then the new one
    # fades in on top. Because fp alone already covers the entire widget, the
    # composite is 100% opaque at every point throughout the whole transition --
    # nothing beneath (e.g. the launcher's own idle/default background) can ever
    # peek through, unlike blending both layers at complementary partial alphas.
    alpha = _t3d_ease(t)
    _t3d_draw_flat(p, fp, w, h, 1.0)
    _t3d_draw_flat(p, tp, w, h, alpha)

_ds_color_cache: dict = {}

def _extract_dominant_color(image_path: str) -> 'tuple[int,int,int]':
    if image_path in _ds_color_cache:
        return _ds_color_cache[image_path]
    default = (0, 60, 120)
    try:
        # Decode straight to thumbnail size instead of decoding the (often full-screen
        # background) image at full resolution and scaling down afterward -- for JPEG/PNG
        # this lets Qt's codec do the downscale during decode, which is far cheaper than a
        # full decode followed by a separate scale. This is the difference between a
        # request_color() call costing low single-digit ms vs tens-to-hundreds of ms on an
        # uncached game, which is what made the lightbar visibly lag behind selection when
        # paging through several never-before-selected games.
        thumb = QImage()
        if os.path.splitext(image_path)[1].lower() != '.svg':
            try:
                reader = QImageReader(image_path)
                reader.setAutoTransform(True)
                size = reader.size()
                if size.isValid() and (not size.isEmpty()):
                    reader.setScaledSize(QSize(48, 27))
                thumb = reader.read()
            except Exception:
                thumb = QImage()
        if thumb.isNull():
            img = _decode_image_any_format(image_path)
            if img.isNull():
                _ds_color_cache[image_path] = default
                return default
            thumb = img.scaled(48, 27, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
        samples = []
        for y in range(thumb.height()):
            for x in range(thumb.width()):
                c = QColor(thumb.pixel(x, y))
                r2, g2, b2 = (c.red(), c.green(), c.blue())
                luma = 0.299 * r2 + 0.587 * g2 + 0.114 * b2
                if luma < 40 or luma > 215:
                    continue
                h2, s2, v2, _ = c.getHsvF()
                if s2 < 0.08 or h2 < 0:
                    continue
                samples.append((h2, s2, v2, r2, g2, b2))
        if not samples:
            _ds_color_cache[image_path] = default
            return default
        samples.sort(key=lambda x: x[1], reverse=True)
        keep = max(1, len(samples) // 4)
        top = samples[:keep]
        buckets: dict = {}
        for h2, s2, v2, r2, g2, b2 in top:
            bk = int(h2 * 8) % 8
            buckets.setdefault(bk, []).append((r2, g2, b2))
        best = max(buckets.values(), key=len)
        avg_r = int(sum((p[0] for p in best)) / len(best))
        avg_g = int(sum((p[1] for p in best)) / len(best))
        avg_b = int(sum((p[2] for p in best)) / len(best))
        cout = QColor(avg_r, avg_g, avg_b)
        h2, s2, v2, _ = cout.getHsvF()
        s2 = min(0.85, max(s2, 0.55))
        v2 = min(0.9, max(v2, 0.55))
        cout.setHsvF(h2, s2, v2)
        result = (cout.red(), cout.green(), cout.blue())
        _ds_color_cache[image_path] = result
        return result
    except Exception:
        _ds_color_cache[image_path] = default
        return default

def _controller_led_image_for_app(app) -> str:
    if not isinstance(app, dict):
        return ''
    for key in ('background', 'tile_art', 'icon', 'exe'):
        candidate = str(app.get(key, '') or '').strip()
        if candidate and os.path.exists(candidate):
            return candidate
    return ''

def _haptic_trace(message: str, *args):
    if _HAPTIC_DEBUG:
        pass

_PAD_LOG_LOCK = threading.Lock()
_PAD_LOG_PATH = os.path.join(os.environ.get('APPDATA') or os.path.expanduser('~'), 'PS5Launcher', 'pad_debug.log')

def _haptic_failure(message: str, *args):
    try:
        line = message % args if args else message
    except Exception:
        line = message
    try:
        with _PAD_LOG_LOCK:
            os.makedirs(os.path.dirname(_PAD_LOG_PATH), exist_ok=True)
            with open(_PAD_LOG_PATH, 'a', encoding='utf-8') as _lf:
                _lf.write(f'[{time.strftime("%H:%M:%S")}] {line}\n')
    except Exception:
        pass

def _ds_enumerate_all_sony() -> 'list[dict]':
    try:
        hid = _HID_DLL
        setupapi = _SETUPAPI_DLL
        k32 = _KERNEL32_DLL
        guid = _GUID()
        hid.HidD_GetHidGuid(ctypes.byref(guid))
        hdevinfo = setupapi.SetupDiGetClassDevsW(ctypes.byref(guid), None, None, DIGCF_PRESENT | DIGCF_DEVICEIFACE)
        if hdevinfo == INVALID_HANDLE:
            return []
        results = []
        iface = _SP_DEVICE_INTERFACE_DATA()
        iface.cbSize = ctypes.sizeof(iface)
        idx = 0
        while True:
            if not setupapi.SetupDiEnumDeviceInterfaces(hdevinfo, None, ctypes.byref(guid), idx, ctypes.byref(iface)):
                break
            idx += 1
            detail = _SP_DETAIL()
            detail.cbSize = 6 if ctypes.sizeof(ctypes.c_void_p) == 4 else 8
            needed = wintypes.DWORD(0)
            setupapi.SetupDiGetDeviceInterfaceDetailW(hdevinfo, ctypes.byref(iface), ctypes.byref(detail), ctypes.sizeof(detail), ctypes.byref(needed), None)
            path = detail.DevicePath
            if not path or '054C' not in path.upper():
                continue
            pid = _pid_from_path(path.upper())
            if pid not in DUALSENSE_PIDS:
                continue
            h = k32.CreateFileW(path, GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, 0, None)
            if h == INVALID_HANDLE:
                continue
            try:
                preparsed = ctypes.c_void_p(0)
                if not hid.HidD_GetPreparsedData(h, ctypes.byref(preparsed)):
                    continue
                caps = _HIDP_CAPS()
                ok = hid.HidP_GetCaps(preparsed, ctypes.byref(caps))
                hid.HidD_FreePreparsedData(preparsed)
                if ok != HIDP_STATUS_SUCCESS:
                    continue
                results.append({'path': path, 'pid': pid, 'usage_page': caps.UsagePage, 'usage': caps.Usage, 'rpt_out': caps.OutputReportByteLength})
            finally:
                k32.CloseHandle(h)
        setupapi.SetupDiDestroyDeviceInfoList(hdevinfo)
        return results
    except Exception as exc:
        return []

def _ds_build_usb_report(rpt_size: int, r: int, g: int, b: int) -> bytearray:
    buf = bytearray(max(48, rpt_size))
    buf[0] = 2
    buf[1] = 0
    buf[2] = 247
    buf[3] = 0
    buf[4] = 0
    buf[45] = r
    buf[46] = g
    buf[47] = b
    return buf

def _ds_build_bt_report(r: int, g: int, b: int, seq: int=0, rpt_size: int=78) -> bytearray:
    import binascii as _bc
    buf = bytearray(max(78, rpt_size))
    buf[0] = 49
    buf[1] = (seq & 15) << 4
    buf[2] = 16
    buf[3] = 0
    buf[4] = 247
    buf[5] = 0
    buf[6] = 0
    buf[47] = r
    buf[48] = g
    buf[49] = b
    crc = _bc.crc32(bytes([162]) + bytes(buf[:74])) & 4294967295
    buf[74] = crc & 255
    buf[75] = crc >> 8 & 255
    buf[76] = crc >> 16 & 255
    buf[77] = crc >> 24 & 255
    return buf

def _ds_build_usb_led_reset_report(rpt_size: int) -> bytearray:
    # DS_OUTPUT_VALID_FLAG2_LIGHTBAR_SETUP_CONTROL_ENABLE (0x02) + DS_OUTPUT_LIGHTBAR_SETUP_LIGHT_OUT (0x02).
    # On connect the DualSense runs its own firmware lightbar animation (most noticeable over
    # Bluetooth) and silently ignores plain color updates until this setup packet explicitly
    # hands lightbar control back to the host -- see dualsense_reset_leds() in the Linux
    # kernel's hid-playstation driver, which every subsequent color write in this file relies on.
    buf = bytearray(max(48, rpt_size))
    buf[0] = 2
    buf[39] = 2
    buf[42] = 2
    return buf

def _ds_build_bt_led_reset_report(seq: int=0, rpt_size: int=78) -> bytearray:
    import binascii as _bc
    buf = bytearray(max(78, rpt_size))
    buf[0] = 49
    buf[1] = (seq & 15) << 4
    buf[2] = 16
    buf[41] = 2
    buf[44] = 2
    crc = _bc.crc32(bytes([162]) + bytes(buf[:74])) & 4294967295
    buf[74] = crc & 255
    buf[75] = crc >> 8 & 255
    buf[76] = crc >> 16 & 255
    buf[77] = crc >> 24 & 255
    return buf

def _ds_write_report(h, buf: bytearray, *, context: str='output') -> bool:
    try:
        n = len(buf)
        raw = (ctypes.c_ubyte * n)(*buf)
        written = wintypes.DWORD(0)
        ok = _KERNEL32_DLL.WriteFile(h, raw, n, ctypes.byref(written), None)
        if ok and written.value == n:
            _haptic_trace('HID report OK context=%s bytes=%d report_id=0x%02X', context, n, buf[0] if buf else 0)
            return True
        write_err = ctypes.get_last_error()
        ok2 = _HID_DLL.HidD_SetOutputReport(h, raw, n)
        if ok2:
            _haptic_trace('HID fallback OK context=%s bytes=%d report_id=0x%02X', context, n, buf[0] if buf else 0)
        else:
            fallback_err = ctypes.get_last_error()
            _haptic_failure('HID report FAILED context=%s bytes=%d report_id=0x%02X WriteFile=%s/%d err=%d fallback_err=%d', context, n, buf[0] if buf else 0, bool(ok), written.value, write_err, fallback_err)
        return bool(ok2)
    except Exception as exc:
        _haptic_failure('HID report EXCEPTION context=%s error=%r', context, exc)
        return False

class _BT_ADDRESS(ctypes.Structure):
    _fields_ = [('ullLong', ctypes.c_ulonglong)]
_BT_MAX_NAME = 248

class _BT_DEVICE_INFO(ctypes.Structure):

    class _SYSTEMTIME(ctypes.Structure):
        _fields_ = [('wYear', wintypes.WORD), ('wMonth', wintypes.WORD), ('wDayOfWeek', wintypes.WORD), ('wDay', wintypes.WORD), ('wHour', wintypes.WORD), ('wMinute', wintypes.WORD), ('wSecond', wintypes.WORD), ('wMilliseconds', wintypes.WORD)]
    _fields_ = [('dwSize', wintypes.DWORD), ('Address', _BT_ADDRESS), ('ulClassofDevice', wintypes.ULONG), ('fConnected', wintypes.BOOL), ('fRemembered', wintypes.BOOL), ('fAuthenticated', wintypes.BOOL), ('stLastSeen', _SYSTEMTIME), ('stLastUsed', _SYSTEMTIME), ('szName', ctypes.c_wchar * _BT_MAX_NAME)]

class _BT_DEVICE_SEARCH_PARAMS(ctypes.Structure):
    _fields_ = [('dwSize', wintypes.DWORD), ('fReturnAuthenticated', wintypes.BOOL), ('fReturnRemembered', wintypes.BOOL), ('fReturnUnknown', wintypes.BOOL), ('fReturnConnected', wintypes.BOOL), ('fIssueInquiry', wintypes.BOOL), ('cTimeoutMultiplier', ctypes.c_ubyte), ('hRadio', wintypes.HANDLE)]

class _BT_FIND_RADIO_PARAMS(ctypes.Structure):
    _fields_ = [('dwSize', wintypes.DWORD)]
_BT_HID_GUID = _GUID()
_BT_HID_GUID.Data1 = 4388
_BT_HID_GUID.Data2 = 0
_BT_HID_GUID.Data3 = 4096
_BT_HID_GUID.Data4 = (ctypes.c_ubyte * 8)(128, 0, 0, 128, 95, 155, 52, 251)

def _hid_family_key(path) -> str:
    """A physical DualSense exposes several HID collections over Bluetooth
    (the input/gamepad one, the audio one, ...) and each gets its OWN
    hidapi `path` string -- but on Windows those paths are identical
    except for the "&colNN" / "#colNN" interface-collection segment.
    Stripping that segment gives a key that's the same for every
    collection of one physical pad, so it can correlate an input-thread
    path with the separate path _bt_device_candidates() opened for audio,
    without depending on hidapi's (often-empty, over Bluetooth)
    serial-number reporting.
    """
    if not path:
        return ''
    if isinstance(path, (bytes, bytearray)):
        try:
            path = path.decode('utf-8')
        except Exception:
            path = path.decode('latin-1', errors='replace')
    return re.sub(r'[&#]col0*[0-9a-f]+', '', str(path), flags=re.IGNORECASE).lower()


# hidapi's `enumerate()` metadata often reports an empty serial_number for
# Bluetooth HID collections on Windows (see _hid_family_key / _ensure_engine
# docstrings above). The input-polling thread, however, reads a reliable
# serial directly off the *opened* device handle (get_serial_number_string())
# every time it starts reading a pad -- see _hidapi_thread_for(). We cache
# that known-good serial here, keyed by family so any collection's path can
# look it up, so _pad_own_bt_addr() has a reliable fallback instead of
# depending solely on a fresh (and often empty) enumerate() call.
_PAD_SERIAL_CACHE: dict = {}
_PAD_SERIAL_CACHE_LOCK = threading.Lock()


def _remember_pad_serial(path, serial: str):
    family = _hid_family_key(path)
    serial = str(serial or '').strip()
    if not family or not serial:
        return
    with _PAD_SERIAL_CACHE_LOCK:
        _PAD_SERIAL_CACHE[family] = serial


def _cached_pad_serial(path) -> str:
    family = _hid_family_key(path)
    if not family:
        return ''
    with _PAD_SERIAL_CACHE_LOCK:
        return _PAD_SERIAL_CACHE.get(family, '')


def _bt_pad_correlation_key(path='', serial='') -> str:
    """Preferred key for correlating a pad's input HID path with its audio
    HID path: real serial number if hidapi reported one, otherwise the
    path family-key (see _hid_family_key)."""
    serial = str(serial or '').strip()
    if serial:
        return 'serial:' + serial
    family = _hid_family_key(path)
    return ('family:' + family) if family else ''


def _is_bluetooth_hid_path(path: str) -> bool:
    upper = str(path or '').upper()
    return any((token in upper for token in ('BTHENUM', 'BTHID', 'BTHLE', 'BLUETOOTH', '00001124', 'WIRELESS')))

def _pad_is_bt(path: str) -> bool:
    return _is_bluetooth_hid_path(path)

def _bt_addr_int_from_serial(serial: str):
    """Parse a hidapi serial-number string for a BT HID device into the
    same integer representation Windows uses for BLUETOOTH_ADDRESS.ullLong
    (i.e. the 6 address bytes read as one big hex number, in the same
    left-to-right order they're normally printed in, e.g. 'AA:BB:CC:DD:EE:FF'
    -> 0xAABBCCDDEEFF). Returns None if serial doesn't look like a MAC."""
    if not serial:
        return None
    hexonly = re.sub(r'[^0-9A-Fa-f]', '', str(serial))
    if len(hexonly) != 12:
        return None
    try:
        return int(hexonly, 16)
    except Exception:
        return None

def _pad_own_bt_addr(path: str):
    """Best-effort lookup of the specific physical pad's own Bluetooth
    address (as an int comparable to BLUETOOTH_ADDRESS.ullLong), so that
    powering off one controller doesn't disconnect every DualSense/DS4
    that happens to be paired. Returns None if it can't be determined,
    in which case the caller should NOT blindly disconnect every matching
    device."""
    if _bt_hid is None:
        return None
    family = _hid_family_key(path)
    try:
        items = _bt_hid.enumerate()
    except Exception:
        items = []
    for item in items:
        ipath = str(item.get('path', '') or '')
        if ipath == path or (family and _hid_family_key(ipath) == family):
            addr = _bt_addr_int_from_serial(item.get('serial_number', ''))
            if addr is not None:
                return addr
    # enumerate()'s serial_number is frequently empty for BT HID collections
    # on Windows (see _PAD_SERIAL_CACHE comment above) -- fall back to the
    # serial the input-polling thread already read off this pad's opened
    # handle, if we have one cached for this pad's family.
    cached_serial = _cached_pad_serial(path)
    return _bt_addr_int_from_serial(cached_serial) if cached_serial else None

def _pad_turn_off(path: str, pid: int) -> str:
    if not _pad_is_bt(path):
        return 'usb_only'
    k32 = _KERNEL32_DLL
    hid = _HID_DLL
    _GR = 2147483648
    _GW = 1073741824
    _SR = 1
    _SW = 2
    _OE = 3
    if pid in DUALSHOCK4_PIDS:
        h = k32.CreateFileW(path, _GR | _GW, _SR | _SW, None, _OE, 0, None)
        if h == INVALID_HANDLE:
            err = ctypes.get_last_error()
            _haptic_failure('turn-off FAILED (DS4) CreateFileW error=%d path=%s', err, path)
            return 'error'
        try:
            buf = (ctypes.c_ubyte * 6)(20, 2, 0, 0, 0, 0)
            ok = bool(hid.HidD_SetFeature(h, buf, 6))
            if not ok:
                _haptic_failure('turn-off FAILED (DS4) HidD_SetFeature error=%d path=%s', ctypes.get_last_error(), path)
        finally:
            k32.CloseHandle(h)
        return 'ok' if ok else 'error'
    IOCTL_BTH_DISCONNECT_DEVICE = 4259852
    target_addr = _pad_own_bt_addr(path)
    if target_addr is None:
        _haptic_failure('turn-off FAILED could not resolve this pad\'s own bluetooth address for path=%s -- refusing to disconnect (would risk turning off every paired pad)', path)
        return 'not_found'
    try:
        bt = ctypes.windll.LoadLibrary('BluetoothApis.dll')
    except OSError as exc:
        _haptic_failure('turn-off FAILED could not load BluetoothApis.dll error=%r', exc)
        return 'error'
    rfind_params = _BT_FIND_RADIO_PARAMS(dwSize=ctypes.sizeof(_BT_FIND_RADIO_PARAMS))
    radio_h = wintypes.HANDLE(0)
    hfind_radio = bt.BluetoothFindFirstRadio(ctypes.byref(rfind_params), ctypes.byref(radio_h))
    if not hfind_radio:
        _haptic_failure('turn-off FAILED no bluetooth radio found error=%d', ctypes.get_last_error())
        return 'error'
    _DS_NAMES = ('dualsense', 'wireless controller')
    found = False
    matched_any_name = False
    matched_target = False
    ioctl_failed = False
    try:
        while True:
            search = _BT_DEVICE_SEARCH_PARAMS(dwSize=ctypes.sizeof(_BT_DEVICE_SEARCH_PARAMS), fReturnAuthenticated=True, fReturnRemembered=True, fReturnUnknown=False, fReturnConnected=True, fIssueInquiry=False, cTimeoutMultiplier=0, hRadio=radio_h)
            dev = _BT_DEVICE_INFO(dwSize=ctypes.sizeof(_BT_DEVICE_INFO))
            hfind_dev = bt.BluetoothFindFirstDevice(ctypes.byref(search), ctypes.byref(dev))
            if hfind_dev:
                try:
                    while True:
                        if dev.fConnected:
                            nm = dev.szName.lower()
                            if any((ds in nm for ds in _DS_NAMES)):
                                matched_any_name = True
                                if int(dev.Address.ullLong) == target_addr:
                                    matched_target = True
                                    bt_addr = ctypes.c_ulonglong(dev.Address.ullLong)
                                    bytes_ok = wintypes.DWORD(0)
                                    ioctl_ok = bool(k32.DeviceIoControl(radio_h, IOCTL_BTH_DISCONNECT_DEVICE, ctypes.byref(bt_addr), ctypes.sizeof(bt_addr), None, 0, ctypes.byref(bytes_ok), None))
                                    if not ioctl_ok:
                                        ioctl_err = ctypes.get_last_error()
                                        ioctl_failed = True
                                        _haptic_failure('turn-off IOCTL_BTH_DISCONNECT_DEVICE FAILED error=%d name=%s (likely needs admin privileges)', ioctl_err, nm)
                                        bt.BluetoothSetServiceState(radio_h, ctypes.byref(dev), ctypes.byref(_BT_HID_GUID), 0)
                                    else:
                                        bt.BluetoothSetServiceState(radio_h, ctypes.byref(dev), ctypes.byref(_BT_HID_GUID), 1)
                                    found = True
                        if not bt.BluetoothFindNextDevice(hfind_dev, ctypes.byref(dev)):
                            break
                finally:
                    bt.BluetoothFindDeviceClose(hfind_dev)
            if not bt.BluetoothFindNextRadio(hfind_radio, ctypes.byref(radio_h)):
                break
    finally:
        bt.BluetoothFindRadioClose(hfind_radio)
        if radio_h:
            k32.CloseHandle(radio_h)
    if not matched_any_name or not matched_target:
        _haptic_failure('turn-off FAILED no connected bluetooth device matched target address=%012X (name filter %r)', target_addr, _DS_NAMES)
        return 'not_found'
    if ioctl_failed:
        return 'no_privilege'
    return 'ok' if found else 'error'

class DualSenseLEDController(QObject):
    # Must stay comfortably under GamepadWorker.REPEAT_RATE (0.12s / 120ms): while the
    # player holds a D-pad/stick direction to page through games, GamepadWorker re-fires
    # a nav event -- and this controller gets a fresh request_color() -- every
    # REPEAT_RATE seconds. _begin_fade() restarts the animation from wherever it
    # currently is toward the new target every time it's called, so with the old 300ms
    # duration (longer than the 120ms gap between selections) each fade was interrupted
    # before it could ever finish. The physical lightbar was therefore always chasing a
    # blend of the last 2-3 selections and only settled on the right color ~300ms after
    # the player stopped scrolling, even though the on-screen tile highlight had already
    # moved on instantly -- this mismatch is what made switching games feel slow to
    # update. 100ms comfortably finishes inside one repeat interval, so the lightbar now
    # keeps pace with selection instead of lagging behind it, while still crossfading
    # smoothly rather than snapping.
    _FADE_MS = 100
    _TICK_MS = 16
    _DIM_MID = 0.7
    # The audio stream and lightbar reports share the DualSense Bluetooth HID
    # transport.  During audio playback Lightbar reports are sent through the
    # audio engine's hidapi handle and its shared write lock; the cooldown is
    # only needed for the transition after the stream stops.
    _AUDIO_HANDOFF_COOLDOWN_S = 0.1
    # Mirror image of the cooldown above, but for the OPENING of a stream instead of its
    # end. A lightbar report landing on the shared HID pipe right as the first opus frames
    # go out steals a time slot from them, which is what produced the crackle at the start
    # of playback: the pipe has no priority concept, so whichever report is queued first
    # simply delays the other by its own transfer time. Blocking lightbar sends for this
    # short window after set_audio_stream_active(True) lets those opening frames go out
    # uncontested; nothing is lost, since a blocked send is simply retried by the normal
    # resend loop (_on_tick_send_done / _retry_resend) once the window closes.
    _AUDIO_START_PRIORITY_S = 0.15
    _color_ready = pyqtSignal(int, int, int)
    _reprobe_requested = pyqtSignal()
    _probe_connected = pyqtSignal()
    _audio_gap_opened = pyqtSignal()
    # Reports the outcome of a single fade-tick HID write (see _submit_tick_send /
    # _tick) back to the GUI thread. The write itself now runs on self._pool's worker
    # thread instead of inline in _tick(), so this can't just be a return value --
    # it has to cross threads the same way _color_ready/_audio_gap_opened already do.
    _tick_send_done = pyqtSignal(bool, bool, int)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._color_ready.connect(self._begin_fade)
        self._reprobe_requested.connect(lambda: QTimer.singleShot(200, self._probe))
        self._probe_connected.connect(self._on_probe_connected)
        self._audio_gap_opened.connect(self._on_audio_gap_opened)
        self._tick_send_done.connect(self._on_tick_send_done)
        self._h = INVALID_HANDLE
        self._rpt_size = 48
        self._is_bt = False
        self._cur = [0, 60, 120]
        self._src = [0, 60, 120]
        self._tgt = [0, 60, 120]
        self._fade_generation = 0
        self._elapsed = 0.0
        self._fading = False
        self._pending = None
        self._bt_seq = 0
        self._suspended = False
        self._atrig_reset_gen: int = 0
        self._audio_stream_active = threading.Event()
        self._audio_stream_block_until = 0.0
        self._audio_start_priority_until = 0.0
        self._audio_transport = None
        self._cur_r_motor: int = 0
        self._cur_l_motor: int = 0
        self._cur_r2: tuple = (0, bytes(9))
        self._cur_l2: tuple = (0, bytes(9))
        self._audio_headphone = 0
        self._audio_speaker = 0
        self._audio_flags2 = 0
        self._audio_target = 'speaker'
        self._mute_led_control = 0
        self._player_indicator = 0
        self._player_led_brightness = 0
        self._valid_flag2 = 0
        self._lightbar_setup = 0
        self._force_resend = False
        self._resend_confirmed = True
        self._resend_attempts = 0
        self._send_lock = threading.Lock()
        self._pool = concurrent.futures.ThreadPoolExecutor(max_workers=1, thread_name_prefix='ds-led')
        self._probe_pool = concurrent.futures.ThreadPoolExecutor(max_workers=1, thread_name_prefix='ds-probe')
        # Dedicated pool for dominant-color extraction (request_color), kept separate from
        # self._pool (which handles real-time HID output writes: rumble, adaptive triggers,
        # audio volume). Color extraction decodes an image and is comparatively slow; sharing
        # a single worker with output writes let a backlog of extraction jobs delay both the
        # lightbar update *and* unrelated controller output whenever the user paged through
        # several games quickly. self._color_fut tracks the most recently queued extraction so
        # a newer request can cancel it before it starts (see request_color()).
        self._color_pool = concurrent.futures.ThreadPoolExecutor(max_workers=1, thread_name_prefix='ds-color')
        self._color_fut = None
        # Mirrors self._pool_last_submit/self._pool_last_done below -- lets _probe() notice
        # if this pool's single worker ever gets wedged (see the stuck-pool recycle check
        # added to _probe()) instead of only the LED-write pool being watched for that.
        self._color_pool_last_submit = 0.0
        self._color_pool_last_done = 0.0
        # Tracks the single outstanding fade-tick HID write (see _submit_tick_send). Same
        # role as self._color_fut above: lets a newer tick cancel a not-yet-started older
        # one instead of letting both run. If the older write has already started, the
        # newest tick is kept here and submitted immediately when that write completes;
        # this prevents the single-worker pool from accumulating stale colors.
        self._tick_fut = None
        self._tick_pending = None
        self._probe_started_at = 0.0
        self._pool_last_submit = 0.0
        self._pool_last_done = 0.0
        self._fade_timer = QTimer(self)
        self._fade_timer.setInterval(self._TICK_MS)
        self._fade_timer.timeout.connect(self._tick)
        self._nav_haptic_gen: int = 0
        self._probing: bool = False
        self._probe_timer = QTimer(self)
        self._probe_timer.setInterval(1500)
        self._probe_timer.timeout.connect(self._probe)
        self._probe_timer.start()
        self._fast_probe_timer = QTimer(self)
        self._fast_probe_timer.setInterval(250)
        self._fast_probe_timer.timeout.connect(self._probe)
        self._fast_probe_deadline = 0.0
        self._probe()

    def attach_audio_transport(self, audio_engine):
        """Use the audio engine's hidapi handle while its stream is active."""
        self._audio_transport = audio_engine

    def _active_audio_transport(self):
        transport = self._audio_transport
        if transport is None or not self._audio_stream_active.is_set():
            return None
        return transport

    def _pool_submit(self, fn, *args, **kwargs):
        self._pool_last_submit = time.monotonic()
        fut = self._pool.submit(fn, *args, **kwargs)
        fut.add_done_callback(lambda f: setattr(self, '_pool_last_done', time.monotonic()))
        return fut

    def _color_pool_submit(self, fn, *args, **kwargs):
        self._color_pool_last_submit = time.monotonic()
        fut = self._color_pool.submit(fn, *args, **kwargs)
        fut.add_done_callback(lambda f: setattr(self, '_color_pool_last_done', time.monotonic()))
        return fut

    def _submit_color_job(self, image_path: str):
        # Shared by request_color() and by _probe()'s color-pool recovery below, so both
        # paths report the result the same way: only apply it if image_path is still what
        # the current selection is waiting on (self._pending may have moved on by the time
        # this finishes).
        fut = self._color_pool_submit(_extract_dominant_color, image_path)
        self._color_fut = fut

        def _done(f, path=image_path):
            try:
                color = f.result()
            except Exception:
                color = (0, 60, 120)
            if self._pending == path:
                self._color_ready.emit(color[0], color[1], color[2])
        fut.add_done_callback(_done)

    def _probe(self):
        if self._pool_last_submit and self._pool_last_submit > self._pool_last_done and (time.monotonic() - self._pool_last_submit > 3.0):
            # ACTUAL ROOT CAUSE OF THE LIGHTBAR PERMANENTLY FREEZING AFTER A SMALL, FIXED
            # NUMBER OF SELECTIONS: this recycle used to only replace the *pool*, never
            # self._h. That's enough to recover from a worker thread that's merely
            # backlogged, but it does nothing for the more literal way a write can wedge
            # this class: a single _ds_write_report() call inside _send() -- running on
            # this pool's one worker -- that blocks forever instead of returning. That's a
            # real, known failure mode for a synchronous WriteFile()/HidD_SetOutputReport()
            # call against a Bluetooth HID handle when the link stalls (as opposed to the
            # write cleanly failing, which _send()'s own close_on_failure/_reprobe_requested
            # path already handled).
            #
            # A blocked syscall never raises and never returns, so: the Future for that job
            # never completes; its done-callback -- the only thing that ever bumps
            # self._pool_last_done or schedules a resend via _tick_send_done -- never runs;
            # and self._h itself is left looking perfectly "valid" the whole time, so
            # nothing downstream ever thinks to reopen it. Rebuilding self._pool alone just
            # means a fresh worker thread issues its next write against that same wedged
            # handle and is liable to hang on it exactly the same way -- which is why this
            # used to look like it "sometimes" recovered (a lucky write to the same handle
            # could still land) but, once the handle was genuinely stuck, never did.
            #
            # The fix is to treat this exactly like _send()'s own failure path: close the
            # handle and let the reconnect logic below open a brand new one.
            # CloseHandle() on a handle with a pending synchronous I/O call is the standard
            # way to force that stuck call to abort on Windows -- it's what actually frees
            # the zombie worker thread instead of leaving it blocked in the background
            # forever, still holding a handle nothing else can safely reuse.
            if self._h != INVALID_HANDLE:
                _haptic_failure('LED pool watchdog: write pending %.1fs with no completion -- closing handle and forcing reconnect', time.monotonic() - self._pool_last_submit)
                try:
                    _KERNEL32_DLL.CloseHandle(self._h)
                except Exception:
                    pass
                self._h = INVALID_HANDLE
            self._force_resend = True
            try:
                self._pool.shutdown(wait=False, cancel_futures=True)
            except Exception:
                pass
            self._pool = concurrent.futures.ThreadPoolExecutor(max_workers=1, thread_name_prefix='ds-led')
            self._pool_last_submit = 0.0
            self._pool_last_done = 0.0
        # ROOT CAUSE OF THE LIGHTBAR PERMANENTLY FREEZING AFTER A HANDFUL OF SELECTIONS:
        # self._color_pool (request_color()'s dominant-color extraction pool, see its
        # constructor comment) has exactly one worker and, unlike self._pool above, nothing
        # was ever watching it for a wedged worker. _extract_dominant_color()'s try/except
        # only catches exceptions -- it does nothing for a call that blocks instead of
        # raising (a stalled network/removable drive path, a misbehaving image codec
        # plugin, an oversized/corrupt file the decoder chokes on, etc). The moment that
        # happens once, every request_color() call made afterward still gets queued behind
        # the wedged job -- cancel() in request_color() is a no-op for a job that has
        # already started -- so _color_ready never fires again for the rest of the session.
        # From the player's side that looks exactly like "changes color a couple of times
        # while paging through games, then just stays on whatever it last showed" -- the
        # selection keeps moving, but nothing is left to notice or unstick the frozen pool.
        # This mirrors the self._pool recycle above: if the color pool's single worker has
        # had a job outstanding for longer than any real decode should ever take, tear the
        # pool down and rebuild it.
        if self._color_pool_last_submit and self._color_pool_last_submit > self._color_pool_last_done and (time.monotonic() - self._color_pool_last_submit > 3.0):
            try:
                self._color_pool.shutdown(wait=False, cancel_futures=True)
            except Exception:
                pass
            self._color_pool = concurrent.futures.ThreadPoolExecutor(max_workers=1, thread_name_prefix='ds-color')
            self._color_pool_last_submit = 0.0
            self._color_pool_last_done = 0.0
            self._color_fut = None
            # The selection that was waiting on the wedged job never got its color applied.
            # Without this, the lightbar would stay stuck on the last color that *did* land
            # until the player happened to move to yet another game and trigger a fresh
            # request_color() call on their own. Re-request the currently-selected game's
            # color right now on the rebuilt pool so it catches up immediately instead of
            # waiting on the next navigation event.
            if self._pending and (not self._suspended):
                cached = _ds_color_cache.get(self._pending)
                if cached is not None:
                    self._begin_fade(*cached)
                else:
                    self._submit_color_job(self._pending)
        if self._suspended:
            return
        if self._h != INVALID_HANDLE:
            if self._fast_probe_timer.isActive():
                self._fast_probe_timer.stop()
            return
        if self._fast_probe_timer.isActive() and time.monotonic() > self._fast_probe_deadline:
            self._fast_probe_timer.stop()
        if self._probing:
            if self._probe_started_at and time.monotonic() - self._probe_started_at > 6.0:
                try:
                    self._probe_pool.shutdown(wait=False, cancel_futures=True)
                except Exception:
                    pass
                self._probe_pool = concurrent.futures.ThreadPoolExecutor(max_workers=1, thread_name_prefix='ds-probe')
                self._probing = False
            else:
                return
        self._probing = True
        self._probe_started_at = time.monotonic()
        self._probe_pool.submit(self._probe_worker)

    def _probe_worker(self):
        try:
            ifaces = _ds_enumerate_all_sony()
            if not ifaces:
                return
            _iface_info = ', '.join(('usage=' + str(i['usage']) + ' rpt_out=' + str(i['rpt_out']) for i in ifaces))
            gamepad_ifaces = [i for i in ifaces if i.get('usage_page') == 1 and i.get('usage') in (4, 5)]
            if gamepad_ifaces:
                ifaces = gamepad_ifaces
            ifaces = sorted(ifaces, key=lambda i: i['rpt_out'], reverse=True)
            for iface in ifaces:
                path = iface['path']
                rpt_size = iface['rpt_out']
                is_bt = rpt_size >= 78
                h = INVALID_HANDLE
                for access in (3221225472, 2147483648):
                    h = _KERNEL32_DLL.CreateFileW(path, access, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, 0, None)
                    if h != INVALID_HANDLE:
                        break
                if h == INVALID_HANDLE:
                    continue
                if is_bt:
                    test_buf = _ds_build_bt_report(0, 0, 0, 0, rpt_size)
                else:
                    sz = rpt_size if rpt_size >= 47 else 48
                    test_buf = _ds_build_usb_report(sz, 0, 0, 0)
                if not _ds_write_report(h, test_buf):
                    _KERNEL32_DLL.CloseHandle(h)
                    continue
                self._h = h
                self._rpt_size = rpt_size if rpt_size >= 47 else 48
                self._is_bt = is_bt
                conn = 'BT' if is_bt else 'USB'
                try:
                    reset_buf = _ds_build_bt_led_reset_report(self._bt_seq, self._rpt_size) if is_bt else _ds_build_usb_led_reset_report(self._rpt_size)
                    _ds_write_report(h, reset_buf, context='led-reset')
                    if is_bt:
                        self._bt_seq = self._bt_seq + 1 & 15
                    time.sleep(0.05)
                except Exception:
                    pass
                self._send(*self._cur, close_on_failure=True)
                # Don't gate this on self._tgt != self._cur alone: _tick() sets self._cur
                # to the color it's *attempting* to send before it knows whether the write
                # actually succeeded (see _tick() below), so a send that silently fails
                # can still leave self._cur == self._tgt even though the controller never
                # actually received that color. self._resend_confirmed is only ever set
                # True by a send that itself returned success, so it's the reliable signal
                # for whether the last requested color still needs to go out after a
                # reconnect -- without it, a failed send right as the handle drops could
                # make the color look "already applied" and never get resent, which is
                # indistinguishable from the lightbar simply not updating anymore.
                if self._tgt != self._cur or self._force_resend or not self._resend_confirmed:
                    self._probe_connected.emit()
                return
        except Exception as exc:
            pass
        finally:
            self._probing = False

    def _on_probe_connected(self):
        self._force_resend = False
        self._fade_generation += 1
        self._tick_pending = None
        # Always run this through the fade loop (never a single one-shot _send), so a
        # reconnect reliably reapplies the latest requested color and participates in the
        # same retry/bookkeeping path as a normal selection change.
        self._resend_confirmed = False
        self._resend_attempts = 0
        if self._tgt == self._cur:
            self._src = [max(0, c - 1) for c in self._cur]
        else:
            self._src = list(self._cur)
        self._elapsed = 0.0
        self._fading = True
        if not self._fade_timer.isActive():
            self._fade_timer.start()

    def set_audio_stream_active(self, active: bool):
        if active:
            with self._send_lock:
                self._audio_stream_block_until = 0.0
                self._audio_start_priority_until = time.monotonic() + self._AUDIO_START_PRIORITY_S
                self._audio_stream_active.set()
        else:
            self._audio_stream_block_until = time.monotonic() + self._AUDIO_HANDOFF_COOLDOWN_S
            self._audio_stream_active.clear()
            # Called from the BT audio engine's own streaming thread, not the GUI thread.
            # Emit rather than touching QTimer/self._fading directly here. Qt queues this
            # onto the GUI thread and retries the newest pending color after the handoff.
            self._audio_gap_opened.emit()

    def _on_audio_gap_opened(self):
        # A clip just finished. Aim a retry just after the handoff cooldown so the latest
        # selected game's color is applied without writing into the audio stream.
        if self._suspended:
            return
        QTimer.singleShot(int(self._AUDIO_HANDOFF_COOLDOWN_S * 1000) + 15, self._retry_resend)

    def _send(self, r: int, g: int, b, *, close_on_failure: bool=False, context: str='output') -> bool:
        audio_transport = self._active_audio_transport()
        if self._h == INVALID_HANDLE and audio_transport is None:
            _haptic_failure('send skipped context=%s reason=no_valid_handle suspended=%s', context, self._suspended)
            return False
        with self._send_lock:
            handoff_blocked = time.monotonic() < self._audio_stream_block_until
            audio_transport = self._active_audio_transport()
            if (audio_transport is None and self._audio_stream_active.is_set()) or (audio_transport is None and handoff_blocked):
                # If the audio engine is unavailable, do not send a competing
                # report during the stream or handoff window.  When it is
                # available, _send below uses its shared hidapi writer.
                _haptic_failure('send skipped context=%s reason=audio_stream_handoff active=%s handoff_blocked=%s', context, self._audio_stream_active.is_set(), handoff_blocked)
                return False
            if audio_transport is not None and time.monotonic() < self._audio_start_priority_until:
                # Even though the shared transport is available and the write would be
                # safely serialized with audio packets, still hold off: serialization only
                # guarantees the two reports don't corrupt each other, not that either one
                # arrives on time. Sending here would simply queue behind/ahead of the
                # opening opus frames and delay them, which is what caused the crackle at
                # the start of playback. The normal resend loop retries this shortly after
                # the window closes, so the color still lands -- just a beat later.
                _haptic_failure('send deferred context=%s reason=audio_start_priority', context)
                return False
            import binascii as _bc
            r2_type, r2_params = self._cur_r2
            l2_type, l2_params = self._cur_l2
            vf0 = 255
            use_bt_report = bool(self._is_bt or audio_transport is not None)
            if use_bt_report:
                shared_report_size = audio_transport.output_report_size if audio_transport is not None else 0
                buf = bytearray(max(78, self._rpt_size, shared_report_size))
                buf[0] = 49
                if audio_transport is not None:
                    # Lightbar reports keep their own 4-bit Bluetooth
                    # sequence.  Audio reports retain the independent
                    # sequence generated by _bt_build_report().
                    bt_sequence = self._bt_seq & 15
                    self._bt_seq = (self._bt_seq + 1) & 15
                else:
                    bt_sequence = self._bt_seq & 15
                    self._bt_seq = (self._bt_seq + 1) & 15
                buf[1] = bt_sequence << 4
                buf[2] = 16
                buf[3] = vf0
                buf[4] = 247
                buf[5] = self._cur_r_motor
                buf[6] = self._cur_l_motor
                buf[13] = r2_type
                buf[14:23] = r2_params
                buf[24] = l2_type
                buf[25:34] = l2_params
                buf[7] = self._audio_headphone
                buf[8] = self._audio_speaker
                buf[10] = 0 if self._audio_target == 'headphone' else 48
                buf[11] = self._mute_led_control
                buf[40] = self._audio_flags2
                buf[41] = self._valid_flag2
                buf[44] = self._lightbar_setup
                buf[45] = self._player_led_brightness
                buf[46] = self._player_indicator
                buf[47] = r
                buf[48] = g
                buf[49] = b
                crc = _bc.crc32(bytes([162]) + bytes(buf[:74])) & 4294967295
                buf[74] = crc & 255
                buf[75] = crc >> 8 & 255
                buf[76] = crc >> 16 & 255
                buf[77] = crc >> 24 & 255
            else:
                buf = bytearray(max(63, self._rpt_size))
                buf[0] = 2
                buf[1] = vf0
                buf[2] = 247
                buf[3] = self._cur_r_motor
                buf[4] = self._cur_l_motor
                buf[11] = r2_type
                buf[12:21] = r2_params
                buf[22] = l2_type
                buf[23:32] = l2_params
                buf[5] = self._audio_headphone
                buf[6] = self._audio_speaker
                buf[8] = 0 if self._audio_target == 'headphone' else 48
                buf[9] = self._mute_led_control
                buf[38] = self._audio_flags2
                buf[39] = self._valid_flag2
                buf[42] = self._lightbar_setup
                buf[43] = self._player_led_brightness
                buf[44] = self._player_indicator
                buf[45] = r
                buf[46] = g
                buf[47] = b
            if audio_transport is not None:
                # hidapi expects the report ID as the first byte.  `buf` is
                # already a complete DualSense Bluetooth report (0x31 + 77
                # bytes), unlike the raw Win32 WriteFile path.
                write_ok = audio_transport.write_output_report(bytes(buf), context=context)
                used_shared_audio_handle = True
            else:
                write_ok = _ds_write_report(self._h, buf, context=context)
                used_shared_audio_handle = False
        if not write_ok:
            if used_shared_audio_handle:
                # The audio engine owns this hidapi handle.  Never close or
                # reprobe it from the Lightbar controller after a failed
                # shared write; the audio worker will observe the same failure
                # and the normal reconnect path will replace the handle.
                _haptic_failure('shared Lightbar write FAILED context=%s; audio handle left to audio engine', context)
            elif close_on_failure:
                _KERNEL32_DLL.CloseHandle(self._h)
                self._h = INVALID_HANDLE
            else:
                _KERNEL32_DLL.CloseHandle(self._h)
                self._h = INVALID_HANDLE
                self._reprobe_requested.emit()
            _haptic_failure('send FAILED context=%s motors=(%d,%d) transport=%s player_led=0x%02X brightness=%d mic_led=%d rgb=(%d,%d,%d); handle closed and re-probe scheduled', context, self._cur_r_motor, self._cur_l_motor, 'BT' if self._is_bt else 'USB', self._player_indicator, self._player_led_brightness, self._mute_led_control, r, g, b)
            return False
        else:
            _haptic_trace('send OK context=%s motors=(%d,%d) transport=%s', context, self._cur_r_motor, self._cur_l_motor, 'BT' if self._is_bt else 'USB')
            return True

    def suspend(self):
        if self._suspended:
            return
        self._pending = None
        self._fade_generation += 1
        self._tick_pending = None
        self._fading = False
        self._fade_timer.stop()
        self._probe_timer.stop()
        if self._fast_probe_timer.isActive():
            self._fast_probe_timer.stop()
        if self._h != INVALID_HANDLE:
            try:
                self._send(0, 0, 0)
                _KERNEL32_DLL.CloseHandle(self._h)
            except Exception:
                pass
            self._h = INVALID_HANDLE
        self._suspended = True

    def resume(self):
        if not self._suspended:
            return
        self._suspended = False
        self._cur_r_motor = 0
        self._cur_l_motor = 0
        self._cur_r2 = (0, bytes(9))
        self._cur_l2 = (0, bytes(9))
        self._probe_timer.start()
        self._fast_probe_deadline = time.monotonic() + 4.0
        if not self._fast_probe_timer.isActive():
            self._fast_probe_timer.start()
        self._probe()

    def force_reprobe(self):
        """Invalidate any stale output handle and immediately hunt for a (re)connected pad.
        Call this whenever the input-reading side detects the controller went away or came
        back, since a stale CreateFileW handle can otherwise look 'valid' forever even after
        the physical device disconnects, silently blocking all future _probe() calls."""
        if self._h != INVALID_HANDLE:
            try:
                _KERNEL32_DLL.CloseHandle(self._h)
            except Exception:
                pass
            self._h = INVALID_HANDLE
        if self._suspended:
            return
        self._force_resend = True
        self._fast_probe_deadline = time.monotonic() + 4.0
        if not self._fast_probe_timer.isActive():
            self._fast_probe_timer.start()
        self._probe()

    def request_color(self, image_path: str):
        if self._suspended:
            return
        if self._color_fut is not None:
            # Drop whatever is still sitting in the queue behind the last request. If that
            # job already started, cancel() is a harmless no-op and it simply finishes and
            # gets ignored by the _pending check inside _submit_color_job()'s _done()
            # callback -- but if it *hasn't* started yet (the common case while paging
            # through several games quickly),
            # this prevents it from ever running at all, instead of burning a full image
            # decode on a selection the user has already left.
            self._color_fut.cancel()
            self._color_fut = None
        if not image_path or not os.path.exists(image_path):
            self._pending = None
            self._begin_fade(0, 60, 120)
            return
        self._pending = image_path
        cached = _ds_color_cache.get(image_path)
        if cached is not None:
            self._begin_fade(*cached)
            return
        self._submit_color_job(image_path)

    def set_output_color(self, r: int, g: int, b: int):
        if self._suspended:
            return
        self._pending = None
        self._begin_fade(max(0, min(255, int(r))), max(0, min(255, int(g))), max(0, min(255, int(b))))

    def set_rumble_levels(self, right: int=0, left: int=0, context: str='controller-test-rumble'):
        if self._suspended or self._h == INVALID_HANDLE:
            return
        self._cur_r_motor = max(0, min(255, int(right)))
        self._cur_l_motor = max(0, min(255, int(left)))
        try:
            self._pool_submit(self._send, self._cur[0], self._cur[1], self._cur[2], context=context)
        except Exception:
            pass

    def set_audio_volumes(self, speaker: int=0, headphone: int=0, target: str='speaker'):
        # `speaker`/`headphone` arrive here as 0-255 (callers do percent*2.55) --
        # keep that as the external API, but the two DualSense HID fields behind
        # them do NOT share that range, which is why the on-pad volume used to
        # feel like it barely moved:
        #
        # - headphone_audio_volume is a 7-bit field (0-0x7f). Sending anything
        #   with bit 7 set (i.e. any 0-255 value above 127) is out of spec and
        #   the firmware does not clamp it sanely, so the top half of the slider
        #   was landing on effectively random/garbage volumes.
        # - speaker_audio_volume is nominally 0-0xff, but on real hardware the
        #   audible range only spans roughly 0x3d-0x64 (61-100): below that it's
        #   silent, above it it doesn't get any louder (see the Linux
        #   HID: playstation driver's DS_OUTPUT_VALID_FLAG0_SPEAKER_VOLUME_ENABLE
        #   handling). A naive 0-255 mapping squashed the whole useful range
        #   into ~15% of the slider's travel.
        # - loudness beyond that digital register is set by a separate analog
        #   preamp gain stage (audio_flags2 / DS_OUTPUT_AUDIO_FLAGS2_SP_PREAMP_GAIN,
        #   a 3-bit 0-7 field) which this code never used to send at all, so it
        #   stayed pinned at its lowest value regardless of the slider.
        speaker_pct = max(0, min(255, int(speaker))) / 255.0
        headphone_pct = max(0, min(255, int(headphone))) / 255.0
        self._audio_headphone = round(headphone_pct * 0x7f)
        self._audio_speaker = round(0x3d + (0x64 - 0x3d) * speaker_pct)
        self._audio_flags2 = round(7 * speaker_pct) & 7
        self._audio_target = 'headphone' if str(target).lower() == 'headphone' else 'speaker'
        if self._suspended or self._h == INVALID_HANDLE:
            return
        try:
            self._pool_submit(self._send, self._cur[0], self._cur[1], self._cur[2], context='controller-test-audio')
        except Exception:
            pass

    def set_mic_led(self, value: int):
        self._mute_led_control = max(0, min(2, int(value)))
        if self._suspended or self._h == INVALID_HANDLE:
            return
        try:
            self._pool_submit(self._send, self._cur[0], self._cur[1], self._cur[2], context='controller-test-mic-led')
        except Exception:
            pass

    def set_player_led(self, value: int, brightness: int | None=None):
        self._player_indicator = max(0, min(31, int(value)))
        if brightness is not None:
            self._player_led_brightness = max(0, min(2, int(brightness)))
        self._valid_flag2 |= 1
        if self._suspended or self._h == INVALID_HANDLE:
            return
        try:
            self._pool_submit(self._send, self._cur[0], self._cur[1], self._cur[2], context='controller-test-player-led')
        except Exception:
            pass

    def _begin_fade(self, tr: int, tg: int, tb: int):
        # Every selection gets its own generation. Completion callbacks from an older
        # selection may arrive after navigation has already moved on; they must not mark
        # the newer selection as successfully delivered.
        self._fade_generation += 1
        self._tick_pending = None
        if self._h == INVALID_HANDLE:
            # This used to be a completely silent no-op: the new color is only remembered
            # in self._tgt, nothing is sent, and nothing is logged. It gets applied once
            # (and only once) _on_probe_connected() next fires -- if the handle never
            # becomes valid again (see the _probe() watchdog above), this is exactly the
            # point where color updates stop having any visible effect at all. Logging it
            # unconditionally (not gated behind --haptic-debug) means pad_debug.log will
            # show a run of these lines starting right at the selection where the lightbar
            # stopped tracking, instead of the freeze being unexplainable after the fact.
            _haptic_failure('color update dropped: no valid handle rgb=(%d,%d,%d)', tr, tg, tb)
            self._tgt = [tr, tg, tb]
            return
        self._src = list(self._cur)
        self._tgt = [tr, tg, tb]
        self._elapsed = 0.0
        self._fading = True
        self._resend_confirmed = False
        self._resend_attempts = 0
        if not self._fade_timer.isActive():
            self._fade_timer.start()

    def _tick(self):
        # ROOT CAUSE OF THE LAGGING LIGHTBAR: this used to call self._send(...) directly,
        # right here, on the GUI thread -- _tick() is a QTimer callback, so it always runs
        # on the GUI thread. self._send() ends in _ds_write_report(), a *blocking* Win32
        # WriteFile()/HidD_SetOutputReport() call. Every other real-time write in this class
        # (rumble, adaptive triggers, player LED, mic LED, haptics) is routed through
        # self._pool_submit() for exactly this reason -- see the comment on self._pool's
        # construction above. _tick() was the one path that never got that treatment: it
        # wrote straight from the timer callback, up to 7 times (one per _TICK_MS) for every
        # single color change.
        #
        # Normally that write takes low single-digit ms and nothing is visibly wrong. But
        # the moment it doesn't -- USB/BT scheduling hiccup, contention on self._send_lock
        # with a pool-submitted write from set_rumble_levels/set_player_led/etc, or simply
        # landing inside the audio-stream handoff window -- that one slow tick stalls the
        # GUI thread for however long the write takes. While the GUI thread is stalled nothing
        # else can run either: no further ticks, no repaint, and critically no keyboard/gamepad
        # input is processed, so the *next* nav event (and the request_color() it would have
        # triggered) is delayed right along with it. That is indistinguishable from "the
        # lightbar doesn't keep up when paging through games quickly" -- it's the same symptom
        # the old 300ms fade duration produced, just reintroduced through blocking I/O instead
        # of a too-long animation. It also defeats self._probe()'s own watchdog, which can only
        # recycle a stuck self._pool because it runs on a QTimer on this same GUI thread --
        # a hang inside a direct _tick() write has no such recovery path at all.
        #
        # Submitting the write here instead keeps _tick() itself to pure arithmetic (sub-ms),
        # so the fade timer keeps firing on schedule regardless of how long any individual
        # write takes, and a slow/blocked write can no longer stall navigation or later color
        # updates. self._pool has exactly one worker, so writes submitted here still execute
        # in the same order they're submitted -- ordering is preserved, only the blocking is
        # removed.
        if not self._fading:
            self._fade_timer.stop()
            return
        self._elapsed += self._TICK_MS
        t = min(1.0, self._elapsed / self._FADE_MS)
        t_e = (1.0 - _math.cos(_math.pi * t)) * 0.5
        dim = 1.0 - (1.0 - self._DIM_MID) * _math.sin(_math.pi * t)

        def ch(s, e):
            return max(0, min(255, int((s + (e - s) * t_e) * dim)))
        is_final = t >= 1.0
        if is_final:
            r, g, b = self._tgt
        else:
            r = ch(self._src[0], self._tgt[0])
            g = ch(self._src[1], self._tgt[1])
            b = ch(self._src[2], self._tgt[2])
        self._cur = [r, g, b]
        self._submit_tick_send(r, g, b, is_final, self._fade_generation)
        if is_final:
            self._fading = False
            self._fade_timer.stop()

    def _submit_tick_send(self, r: int, g: int, b: int, is_final: bool, generation: int):
        # Cap outstanding fade-tick writes at ONE in flight. self._pool has a single worker,
        # and a real HID write can occasionally take longer than the 16ms gap between ticks
        # (USB/BT scheduling, lock contention with a rumble/player-LED write also going
        # through self._pool, etc). Without this cap, each tick still submits unconditionally,
        # so during fast repeated navigation (holding a direction, or paging through several
        # games quickly) submissions land faster than the single worker can drain them: the
        # queue backs up with a growing pile of now-stale intermediate colors from selections
        # the player has already moved past, and the write for whatever is *currently*
        # selected has to wait its turn behind all of them. The lightbar then spends the next
        # several seconds working through that backlog instead of tracking the current
        # selection -- which looks exactly like "changes a couple of times, then the rest just
        # doesn't update." (This is also why the direct, blocking self._send() call this
        # replaced never had the problem: each tick was forcibly serialized with the write
        # that preceded it, so a backlog was never possible -- see the comment on _tick()
        # above. Moving the write off the GUI thread removed that accidental throttle, so it
        # has to be replaced with a real one.)
        #
        # Only the FINAL color of a fade is ever written to the pad. Writing every
        # intermediate step used to mean up to _FADE_MS/_TICK_MS (~6-7) separate physical
        # HID reports for a single tile movement, each one taking a turn on the shared
        # Bluetooth transport against the audio engine's opus frames -- that repeated
        # contention, not just the handoff/priority windows above, was the other half of
        # what produced the crackle at the start of playback. The fade math in _tick() is
        # still run every _TICK_MS so self._cur/self._src/self._tgt stay correct and any
        # code depending on them keeps working, but nothing goes out over HID until the
        # fade settles, so one selection now costs exactly one write instead of several.
        if not is_final:
            return
        # If the previous tick's write has not started yet, cancel it and replace it with this
        # newer color instead of letting both run -- same pattern as self._color_fut in
        # request_color() above. If it already started, cancel() returns False: never queue
        # another write behind it, because that creates a backlog of stale colors while the
        # HID call is slow. Keep only the newest tick and submit it from _on_tick_send_done().
        prev = self._tick_fut
        if prev is not None and not prev.done():
            if not prev.cancel():
                self._tick_pending = (r, g, b, is_final, generation)
                return
        self._tick_pending = None
        try:
            fut = self._pool_submit(self._send, r, g, b, context='fade-final' if is_final else 'fade-tick')
        except Exception:
            # Pool is gone/shutting down (e.g. mid _probe() recycle) -- treat exactly like a
            # failed write so the final-tick resend/give-up bookkeeping still runs.
            self._tick_fut = None
            self._tick_send_done.emit(False, is_final, generation)
            return
        self._tick_fut = fut

        def _done(f, final=is_final, gen=generation):
            if f.cancelled():
                # Superseded by a newer tick before the worker got to it -- that newer one
                # owns the resend/give-up bookkeeping now, so don't double-report here.
                return
            if self._tick_fut is f:
                self._tick_fut = None
            try:
                ok = bool(f.result())
            except Exception:
                ok = False
            self._tick_send_done.emit(ok, final, gen)
        fut.add_done_callback(_done)

    def _on_tick_send_done(self, ok: bool, is_final: bool, generation: int):
        # Runs on the GUI thread (queued automatically, same as _color_ready/
        # _audio_gap_opened) even though the write that produced this result ran on the
        # pool's worker thread.
        # A slow write may have caused several timer ticks to arrive while it was in
        # progress. Only the newest one is retained; send it now, after the worker is free.
        # Do this before retry bookkeeping so an older failed final tick cannot schedule a
        # retry for a color that has already been superseded.
        pending = self._tick_pending
        self._tick_pending = None
        if pending is not None and pending[4] == self._fade_generation and (not self._suspended) and self._h != INVALID_HANDLE:
            self._submit_tick_send(*pending)
            return
        # Only a successful final write for the current selection confirms that target.
        # Intermediate colors are merely fade steps, and a callback from an old selection
        # must not affect the resend state of the current one.
        if generation != self._fade_generation:
            return
        if ok and is_final:
            self._resend_confirmed = True
        if not is_final:
            return
        if self._resend_confirmed:
            if self._resend_attempts:
                _haptic_failure('lightbar resend CONFIRMED after %d retries rgb=(%d,%d,%d)', self._resend_attempts, *self._cur)
            return
        # Keep retrying indefinitely instead of abandoning the latest target after a fixed
        # number of attempts. This also covers a transient HID failure or a reconnect that
        # takes longer than the initial retry window.
        # self._cur/self._tgt are shared, live instance state, so a retry chain started for
        # an old selection naturally ends up sending whatever color is current by the time
        # it actually lands -- it never applies a stale color.
        self._resend_attempts += 1
        delay = 40 if self._resend_attempts <= 25 else 300
        QTimer.singleShot(delay, self._retry_resend)

    def _retry_resend(self):
        if self._resend_confirmed or self._suspended or self._h == INVALID_HANDLE:
            return
        self._src = [max(0, c - 1) for c in self._cur]
        self._elapsed = 0.0
        self._fading = True
        if not self._fade_timer.isActive():
            self._fade_timer.start()

    def haptic_pulse(self, right: int=160, left: int=200, duration_ms: int=350, context: str='haptic-pulse'):
        _haptic_trace('request context=%s motors=(%d,%d) duration=%dms suspended=%s handle_valid=%s transport=%s', context, right, left, duration_ms, self._suspended, self._h != INVALID_HANDLE, 'BT' if self._is_bt else 'USB')
        if self._suspended or self._h == INVALID_HANDLE:
            _haptic_failure('request skipped context=%s reason=%s suspended=%s handle_valid=%s', context, 'suspended' if self._suspended else 'no_valid_handle', self._suspended, self._h != INVALID_HANDLE)
            return
        self._cur_r_motor = right
        self._cur_l_motor = left
        try:
            sent = self._send(self._cur[0], self._cur[1], self._cur[2], context=context)
            _haptic_trace('request result context=%s sent=%s motors=(%d,%d)', context, sent, right, left)

            def _stop_rumble():
                time.sleep(duration_ms / 1000.0)
                self._cur_r_motor = 0
                self._cur_l_motor = 0
                if self._h != INVALID_HANDLE and (not self._suspended):
                    try:
                        self._pool_submit(self._send, self._cur[0], self._cur[1], self._cur[2], context=context + '-off')
                    except Exception:
                        pass
                _haptic_trace('motor state cleared context=%s', context)
            threading.Thread(target=_stop_rumble, daemon=True, name='ds-haptic-off').start()
        except Exception as exc:
            self._cur_r_motor = 0
            self._cur_l_motor = 0
            _haptic_failure('request exception context=%s error=%r', context, exc)

    def _maybe_restart_fade_timer(self):
        if not self._suspended and self._fading and (not self._fade_timer.isActive()):
            self._fade_timer.start()

    def haptic_play_pattern(self, pattern: str='single', right: int=160, left: int=200, duration_ms: int=350, context: str='haptic-pattern'):
        if pattern == 'double':
            burst = max(60, duration_ms // 3)
            gap = max(80, duration_ms // 3)
            self.haptic_pulse(right=right, left=left, duration_ms=burst, context=context)
            delay_ms = burst + gap
            h_self = self

            def _second():
                time.sleep(delay_ms / 1000.0)
                h_self.haptic_pulse(right=right, left=left, duration_ms=burst, context=context + '-second')
            threading.Thread(target=_second, daemon=True, name='ds-haptic-double').start()
        elif pattern == 'triple':
            burst = max(50, duration_ms // 4)
            gap = max(60, duration_ms // 4)
            h_self = self

            def _sequence():
                h_self.haptic_pulse(right=right, left=left, duration_ms=burst, context=context + '-first')
                time.sleep((burst + gap) / 1000.0)
                h_self.haptic_pulse(right=right, left=left, duration_ms=burst, context=context + '-second')
                time.sleep((burst + gap) / 1000.0)
                h_self.haptic_pulse(right=right, left=left, duration_ms=burst, context=context + '-third')
            threading.Thread(target=_sequence, daemon=True, name='ds-haptic-triple').start()
        else:
            self.haptic_pulse(right=right, left=left, duration_ms=duration_ms, context=context)

    def set_adaptive_triggers(self, r2_mode: str='off', r2_strength: int=160, l2_mode: str='off', l2_strength: int=160):
        if self._suspended or self._h == INVALID_HANDLE:
            return

        def _encode(mode: str, strength: int):
            s8 = max(0, min(8, strength >> 5))
            s = max(0, min(255, strength))
            if mode == 'resistance':
                return (1, bytes([0, 255, s, 0, 0, 0, 0, 0, 0]))
            elif mode == 'weapon':
                return (2, bytes([4, 8, s8, 0, 0, 0, 0, 0, 0]))
            elif mode == 'vibration':
                return (5, bytes([0, s, 10, 0, 0, 0, 0, 0, 0]))
            else:
                return (0, bytes(9))
        r2_type, r2_params = _encode(r2_mode, r2_strength)
        l2_type, l2_params = _encode(l2_mode, l2_strength)
        self._cur_r2 = (r2_type, r2_params)
        self._cur_l2 = (l2_type, l2_params)
        try:
            self._pool_submit(self._send, self._cur[0], self._cur[1], self._cur[2], context='adaptive-trigger')
        except Exception:
            pass

    def _nav_haptic_off(self, gen: int, context: str='nav'):
        if gen != self._nav_haptic_gen:
            return
        self._cur_r_motor = 0
        self._cur_l_motor = 0
        if self._h != INVALID_HANDLE and (not self._suspended):
            try:
                self._pool_submit(self._send, self._cur[0], self._cur[1], self._cur[2], context=context + '-off')
            except Exception:
                pass

    def _nav_rumble_tick(self, right: int, left: int, duration_ms: int, context: str='nav'):
        if self._suspended:
            return
        right = max(0, min(255, int(right)))
        left = max(0, min(255, int(left)))
        duration_ms = max(20, min(1000, int(duration_ms)))
        self._nav_haptic_gen += 1
        _gen = self._nav_haptic_gen
        self._cur_r_motor = right
        self._cur_l_motor = left
        if self._h != INVALID_HANDLE:
            try:
                self._pool_submit(self._send, self._cur[0], self._cur[1], self._cur[2], context=context)
            except Exception:
                self._cur_r_motor = 0
                self._cur_l_motor = 0
        threading.Thread(target=self._nav_haptic_off_watchdog, args=(_gen, duration_ms, context), daemon=True, name='ds-nav-haptic-off').start()

    def _nav_haptic_off_watchdog(self, gen: int, duration_ms: int, context: str):
        time.sleep(max(0, duration_ms) / 1000.0)
        self._nav_haptic_off(gen, context=context)

    def close(self):
        try:
            self._suspended = True
            self._probe_timer.stop()
            self._fade_timer.stop()
            self._pool.shutdown(wait=False)
            self._color_pool.shutdown(wait=False, cancel_futures=True)
            if self._h != INVALID_HANDLE:
                self._send(0, 0, 0)
            if self._h != INVALID_HANDLE:
                _KERNEL32_DLL.CloseHandle(self._h)
                self._h = INVALID_HANDLE
        except Exception:
            pass

class _BackgroundWidget(QWidget):
    _TICK_MS = 12
    _DURATION_MS = 900
    _bg_decoded = pyqtSignal(str, object)

    def __init__(self, image_path='', parent=None, on_video_bg_start=None):
        super().__init__(parent)
        self._bg_pixmap = QPixmap()
        self._prev_pixmap = QPixmap()
        self._bg_scaled = QPixmap()
        self._prev_scaled = QPixmap()
        self._default_scaled = QPixmap()
        self._fade_alpha = 0
        self._default_path = image_path
        self._pending_bg_path = ''
        self._pending_bg_force = False
        self._current_bg_path = ''
        self._last_requested_game_path = ''
        self._default_video_player = None
        self._default_video_output = None
        self._default_video_sink = None
        self._default_video_frame_pixmap = QPixmap()
        self._on_video_bg_start = on_video_bg_start
        self._video_bg_playing = False
        self._tr_fn = None
        self._tr_elapsed = 0.0
        self._tr_duration_ms = self._DURATION_MS
        self._tr_name = ''
        self._tr_timer = QTimer(self)
        self._tr_timer.timeout.connect(self._tr_tick)
        self._bg_decoded.connect(self._on_bg_decoded)
        if image_path and os.path.exists(image_path):
            if _is_video_bg_path(image_path):
                self._ensure_default_video_player()
                self._current_bg_path = image_path
            else:
                self._bg_pixmap = _get_cached_bg_pixmap(image_path)
                self._current_bg_path = image_path

    def _ensure_default_video_player(self):
        if QMediaPlayer is None or QAudioOutput is None or QVideoSink is None:
            return
        path = self._default_path
        if not path or not os.path.exists(path):
            return
        if self._default_video_player is not None:
            try:
                if self._default_video_player.source().toLocalFile() == path:
                    self._default_video_player.play()
                    self._notify_video_bg_start()
                    return
            except Exception:
                pass
            self._stop_default_video_player()
        try:
            self._default_video_output = QAudioOutput(self)
            self._default_video_output.setMuted(True)
            self._default_video_output.setVolume(0.0)
            self._default_video_sink = QVideoSink(self)
            self._default_video_sink.videoFrameChanged.connect(self._on_default_video_frame)
            self._default_video_player = QMediaPlayer(self)
            self._default_video_player.setAudioOutput(self._default_video_output)
            self._default_video_player.setVideoSink(self._default_video_sink)
            self._default_video_player.setLoops(QMediaPlayer.Loops.Infinite)
            self._default_video_player.setSource(QUrl.fromLocalFile(path))
            self._default_video_player.play()
            self._notify_video_bg_start()
        except Exception:
            self._default_video_player = None
            self._default_video_output = None
            self._default_video_sink = None

    def _notify_video_bg_start(self):
        if self._video_bg_playing:
            return
        self._video_bg_playing = True
        cb = self._on_video_bg_start
        if not callable(cb):
            return

        def _fire(cb=cb, widget=self):
            try:
                played = cb()
            except Exception:
                played = False
            if not played:
                widget._video_bg_playing = False
        try:
            QTimer.singleShot(0, _fire)
        except Exception:
            self._video_bg_playing = False

    def _stop_default_video_player(self):
        player = self._default_video_player
        if player is not None:
            try:
                player.stop()
                player.setSource(QUrl())
            except Exception:
                pass
        self._default_video_player = None
        self._default_video_output = None
        self._default_video_sink = None
        self._video_bg_playing = False

    def _on_default_video_frame(self, frame):
        if not frame.isValid():
            return
        img = frame.toImage()
        if img.isNull():
            return
        self._default_video_frame_pixmap = QPixmap.fromImage(img)
        if self._current_bg_path == self._default_path:
            self._bg_scaled = self._scale_to_widget(self._default_video_frame_pixmap)
            self._default_scaled = self._bg_scaled
            self.update()

    def set_default_path(self, path: str):
        self._stop_default_video_player()
        self._default_path = path or ''
        self._default_scaled = QPixmap()
        self._default_video_frame_pixmap = QPixmap()
        if _is_video_bg_path(self._default_path) and self._default_path and os.path.exists(self._default_path):
            self._ensure_default_video_player()
        self.set_background(self._last_requested_game_path, force=True)

    def _scale_to_widget(self, pix: QPixmap) -> QPixmap:
        if pix.isNull() or self.width() == 0 or self.height() == 0:
            return pix
        return pix.scaled(self.width(), self.height(), Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)

    def _rebuild_scaled(self):
        self._bg_scaled = self._scale_to_widget(self._bg_pixmap)
        self._prev_scaled = self._scale_to_widget(self._prev_pixmap)
        if self._default_path and _is_video_bg_path(self._default_path):
            if not self._default_video_frame_pixmap.isNull():
                self._default_scaled = self._scale_to_widget(self._default_video_frame_pixmap)
        elif self._default_path:
            default_pix = _get_cached_bg_pixmap(self._default_path)
            self._default_scaled = self._scale_to_widget(default_pix)

    def _request_bg_async(self, path: str):
        if path in _BG_LOADING_PATHS:
            return
        _BG_LOADING_PATHS.add(path)

        def _worker(p=path):
            img = _decode_bg_image(p)
            self._bg_decoded.emit(p, img)
        try:
            _IMAGE_DECODE_POOL.submit(_worker)
        except RuntimeError:
            # Pool was already shut down (app closing) between this call
            # being queued and now -- drop the request instead of crashing.
            _BG_LOADING_PATHS.discard(path)

    def _on_bg_decoded(self, path: str, img):
        _BG_LOADING_PATHS.discard(path)
        if img is not None:
            pix = QPixmap.fromImage(img)
            _lru_put(_BG_PIXMAP_CACHE, path, pix, _BG_PIXMAP_CACHE_MAX)
        if self._pending_bg_path == path:
            self._pending_bg_path = ''
            force = self._pending_bg_force
            self._pending_bg_force = False
            self.set_background(path, force=force)

    def _tr_tick(self):
        self._tr_elapsed += self._TICK_MS
        duration = getattr(self, '_tr_duration_ms', self._DURATION_MS)
        if self._tr_elapsed >= duration:
            self._tr_elapsed = duration
            self._tr_timer.stop()
            self._tr_fn = None
            self._tr_name = ''
            self._fade_alpha = 0
            self._prev_pixmap = QPixmap()
            self._prev_scaled = QPixmap()
        self.update()

    def _start_transition(self):
        # Only one background transition model: a plain crossfade. The old
        # background smoothly dissolves while the new one fades in over it, with
        # no gaps or transform-style motion, so the launcher's own idle
        # background never shows through between the two.
        self._tr_duration_ms = self._DURATION_MS
        self._tr_name = 'crossfade'
        self._tr_fn = _tr_crossfade
        self._tr_elapsed = 0.0
        if not self._tr_timer.isActive():
            self._tr_timer.start(self._TICK_MS)

    def set_background(self, game_bg_path: str='', force: bool=False):
        self._last_requested_game_path = game_bg_path
        showing_default = not (game_bg_path and os.path.exists(game_bg_path))
        path = game_bg_path if not showing_default else self._default_path
        if showing_default and _is_video_bg_path(path) and path and os.path.exists(path):
            self._ensure_default_video_player()
            if path == self._current_bg_path and (not force):
                return
            self._tr_timer.stop()
            self._prev_pixmap = QPixmap()
            self._prev_scaled = QPixmap()
            if not self._default_video_frame_pixmap.isNull():
                self._bg_pixmap = self._default_video_frame_pixmap
                self._bg_scaled = self._scale_to_widget(self._bg_pixmap)
                self._default_scaled = self._bg_scaled
            self._current_bg_path = path
            self.update()
            return
        if self._default_video_player is not None:
            try:
                self._default_video_player.pause()
            except Exception:
                pass
            self._video_bg_playing = False
        if path == self._current_bg_path and (not force) and (not self._bg_pixmap.isNull()):
            return
        cached = _lru_get(_BG_PIXMAP_CACHE, path) if path else None
        if path and cached is None:
            self._pending_bg_path = path
            self._pending_bg_force = force
            self._request_bg_async(path)
            return
        self._pending_bg_path = ''
        new_pix = cached if cached is not None else QPixmap()
        if not self._bg_pixmap.isNull():
            self._tr_timer.stop()
            self._prev_pixmap = self._bg_pixmap
            self._prev_scaled = self._bg_scaled
            self._bg_pixmap = new_pix
            self._bg_scaled = self._scale_to_widget(self._bg_pixmap)
            self._start_transition()
        else:
            self._bg_pixmap = new_pix
            self._rebuild_scaled()
            self.update()
        self._current_bg_path = path

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._rebuild_scaled()

    def _draw_overlay_veil(self, p):
        veil = QLinearGradient(0, 0, 0, self.height())
        veil.setColorAt(0.0, QColor(2, 2, 14, 235))
        veil.setColorAt(0.12, QColor(3, 3, 18, 130))
        veil.setColorAt(0.38, QColor(3, 3, 16, 48))
        veil.setColorAt(0.6, QColor(3, 3, 18, 75))
        veil.setColorAt(0.8, QColor(2, 2, 16, 160))
        veil.setColorAt(1.0, QColor(1, 1, 10, 245))
        p.fillRect(self.rect(), QBrush(veil))
        lv = QLinearGradient(0, 0, self.width() * 0.16, 0)
        lv.setColorAt(0, QColor(0, 0, 8, 190))
        lv.setColorAt(1, QColor(0, 0, 0, 0))
        p.fillRect(self.rect(), QBrush(lv))
        rv = QLinearGradient(self.width() * 0.84, 0, self.width(), 0)
        rv.setColorAt(0, QColor(0, 0, 0, 0))
        rv.setColorAt(1, QColor(0, 0, 8, 190))
        p.fillRect(self.rect(), QBrush(rv))

    def paint_default_region(self, painter, region: QRect):
        if region.isNull() or region.width() <= 0 or region.height() <= 0:
            return
        default_pix = self._default_scaled
        if default_pix.isNull() and self._default_path:
            source = _get_cached_bg_pixmap(self._default_path)
            if not source.isNull():
                default_pix = self._scale_to_widget(source)
        if default_pix.isNull():
            painter.fillRect(self.rect(), QColor(5, 5, 24, 220))
            return
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        x = (self.width() - default_pix.width()) // 2 - region.x()
        y = (self.height() - default_pix.height()) // 2 - region.y()
        painter.drawPixmap(x, y, default_pix)
        veil = QLinearGradient(0, -region.y(), 0, self.height() - region.y())
        veil.setColorAt(0.0, QColor(2, 2, 14, 115))
        veil.setColorAt(0.5, QColor(2, 2, 14, 45))
        veil.setColorAt(1.0, QColor(1, 1, 10, 125))
        painter.fillRect(QRect(0, 0, region.width(), region.height()), QBrush(veil))
        painter.restore()

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        w, h = (self.width(), self.height())
        has_bg = not self._bg_scaled.isNull() or not self._prev_scaled.isNull()
        in_trans = self._tr_fn is not None
        if has_bg:
            if in_trans:
                # No base layer of the launcher's own default/idle background is
                # painted here anymore: _start_transition() only ever begins a
                # transition when there's already a real previous background
                # (_prev_scaled), and the crossfade always draws that previous
                # background fully opaque first (see _tr_crossfade), so the
                # entire widget is covered by real game art for the whole
                # transition -- the launcher's own background is never visible.
                duration = getattr(self, '_tr_duration_ms', self._DURATION_MS)
                t = min(1.0, self._tr_elapsed / max(1, duration))
                try:
                    self._tr_fn(p, self._prev_scaled, self._bg_scaled, w, h, t)
                except Exception:
                    _t3d_draw_flat(p, self._prev_scaled, w, h, 1.0)
                    _t3d_draw_flat(p, self._bg_scaled, w, h, t)
            else:
                _t3d_draw_flat(p, self._bg_scaled, w, h, 1.0)
            self._draw_overlay_veil(p)
        else:
            g = QLinearGradient(0, 0, 0, h)
            g.setColorAt(0, QColor('#050518'))
            g.setColorAt(0.5, QColor('#030310'))
            g.setColorAt(1, QColor('#010108'))
            p.fillRect(self.rect(), QBrush(g))

class _SettingsDrawerWidget(QWidget):

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAutoFillBackground(False)
        self.setStyleSheet('background:transparent;border:none;')

    def paintEvent(self, event):
        pass

_LNK_RESOLVE_CACHE: 'dict[str, tuple]' = {}
_LNK_RESOLVE_CACHE_LOCK = threading.Lock()


def _resolve_lnk_binary(lnk_path: str):
    """Parse a .lnk (MS-SHLLINK) file directly to get its target path,
    arguments, and working directory, without shelling out to
    powershell. Spawning a fresh powershell.exe process for every
    single launch (the old approach) is slow and, under load or on a
    cold first run, can occasionally exceed its own timeout or
    otherwise fail -- when that happened, the launcher silently fell
    back to watching the .lnk file's own name (which never matches a
    running process), so the game got force-closed a few seconds after
    actually starting. Reading the binary format directly is
    effectively instant and has nothing to time out, so it doesn't
    have that failure mode. Only covers the common absolute-local-path
    case (LinkInfo -> LocalBasePath); anything unusual (network
    shortcuts, IDList-only links with no LinkInfo) falls back to the
    powershell resolver below."""
    with open(lnk_path, 'rb') as f:
        data = f.read()
    if len(data) < 76 or data[0:4] != b'\x4c\x00\x00\x00':
        raise ValueError('not a .lnk file')
    link_flags = int.from_bytes(data[20:24], 'little')
    HAS_LINK_TARGET_ID_LIST = 1 << 0
    HAS_LINK_INFO = 1 << 1
    HAS_NAME = 1 << 2
    HAS_RELATIVE_PATH = 1 << 3
    HAS_WORKING_DIR = 1 << 4
    HAS_ARGUMENTS = 1 << 5
    HAS_ICON_LOCATION = 1 << 6
    IS_UNICODE = 1 << 7
    pos = 76
    if link_flags & HAS_LINK_TARGET_ID_LIST:
        id_list_size = int.from_bytes(data[pos:pos + 2], 'little')
        pos += 2 + id_list_size
    target = ''
    if link_flags & HAS_LINK_INFO:
        li_start = pos
        li_size = int.from_bytes(data[li_start:li_start + 4], 'little')
        li_header_size = int.from_bytes(data[li_start + 4:li_start + 8], 'little')
        li_flags = int.from_bytes(data[li_start + 8:li_start + 12], 'little')
        local_base_off = int.from_bytes(data[li_start + 16:li_start + 20], 'little')
        suffix_off = int.from_bytes(data[li_start + 20:li_start + 24], 'little')
        local_base_off_u = 0
        suffix_off_u = 0
        if li_header_size >= 0x24:
            local_base_off_u = int.from_bytes(data[li_start + 28:li_start + 32], 'little')
            suffix_off_u = int.from_bytes(data[li_start + 32:li_start + 36], 'little')

        def _cstr_ansi(off):
            if not off:
                return ''
            end = data.index(b'\x00', li_start + off)
            return data[li_start + off:end].decode('mbcs', errors='replace')

        def _cstr_unicode(off):
            if not off:
                return ''
            end = data.index(b'\x00\x00', li_start + off)
            if (end - (li_start + off)) % 2:
                end += 1
            return data[li_start + off:end].decode('utf-16-le', errors='replace')
        if li_flags & 1:
            if local_base_off_u:
                base = _cstr_unicode(local_base_off_u)
                suffix = _cstr_unicode(suffix_off_u) if suffix_off_u else ''
            else:
                base = _cstr_ansi(local_base_off)
                suffix = _cstr_ansi(suffix_off) if suffix_off else ''
            target = base + suffix
        pos = li_start + li_size

    def _read_string_data(pos):
        count = int.from_bytes(data[pos:pos + 2], 'little')
        pos += 2
        if link_flags & IS_UNICODE:
            n = count * 2
            s = data[pos:pos + n].decode('utf-16-le', errors='replace')
        else:
            n = count
            s = data[pos:pos + n].decode('mbcs', errors='replace')
        return (s, pos + n)
    args = ''
    work_dir = ''
    if link_flags & HAS_NAME:
        _, pos = _read_string_data(pos)
    if link_flags & HAS_RELATIVE_PATH:
        _, pos = _read_string_data(pos)
    if link_flags & HAS_WORKING_DIR:
        work_dir, pos = _read_string_data(pos)
    if link_flags & HAS_ARGUMENTS:
        args, pos = _read_string_data(pos)
    if not target:
        raise ValueError('no LinkInfo/LocalBasePath in .lnk')
    return (target, args, work_dir)


def _resolve_lnk_via_powershell(lnk_path: str):
    try:
        safe_path = lnk_path.replace('"', '`"')
        ps_cmd = f'try {{  $s=(New-Object -ComObject WScript.Shell).CreateShortcut("{safe_path}");  Write-Output $s.TargetPath;  Write-Output $s.Arguments;  Write-Output $s.WorkingDirectory}} catch {{ Write-Output ""; Write-Output ""; Write-Output "" }}'
        result = subprocess.run(['powershell', '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-Command', ps_cmd], capture_output=True, text=True, timeout=8, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        lines = result.stdout.strip().splitlines()
        target = lines[0].strip() if len(lines) > 0 else ''
        args = lines[1].strip() if len(lines) > 1 else ''
        work_dir = lines[2].strip() if len(lines) > 2 else ''
        return (target, args, work_dir)
    except Exception as e:
        return ('', '', '')


def _resolve_lnk(lnk_path: str):
    try:
        st = os.stat(lnk_path)
        cache_key = f'{lnk_path}|{st.st_mtime_ns}|{st.st_size}'
    except Exception:
        cache_key = None
    if cache_key is not None:
        with _LNK_RESOLVE_CACHE_LOCK:
            cached = _LNK_RESOLVE_CACHE.get(lnk_path)
        if cached is not None and cached[0] == cache_key:
            return cached[1]
    result = ('', '', '')
    try:
        target, args, work_dir = _resolve_lnk_binary(lnk_path)
        if target and os.path.exists(target):
            result = (target, args, work_dir)
    except Exception:
        pass
    if not result[0]:
        # Binary parse didn't find a usable, existing target (unusual
        # link layout, e.g. network path or IDList-only) -- fall back
        # to the slower but more exhaustive shell-COM resolution.
        result = _resolve_lnk_via_powershell(lnk_path)
    if cache_key is not None and result[0]:
        with _LNK_RESOLVE_CACHE_LOCK:
            _LNK_RESOLVE_CACHE[lnk_path] = (cache_key, result)
    return result

class _ElevatedProc:
    _INFINITE = 4294967295

    def __init__(self, hproc):
        self._hproc = hproc
        self.pid = ctypes.windll.kernel32.GetProcessId(hproc)

    def wait(self, timeout=None):
        ms = self._INFINITE if timeout is None else int(timeout * 1000)
        ctypes.windll.kernel32.WaitForSingleObject(self._hproc, ms)
        code = wintypes.DWORD()
        ctypes.windll.kernel32.GetExitCodeProcess(self._hproc, ctypes.byref(code))
        ctypes.windll.kernel32.CloseHandle(self._hproc)
        return code.value

    def poll(self):
        """subprocess.Popen-compatible: returns None while still running,
        otherwise the exit code. Non-blocking."""
        code = wintypes.DWORD()
        if not ctypes.windll.kernel32.GetExitCodeProcess(self._hproc, ctypes.byref(code)):
            return None
        STILL_ACTIVE = 259
        return None if code.value == STILL_ACTIVE else code.value

    def terminate(self):
        try:
            ctypes.windll.kernel32.TerminateProcess(self._hproc, 1)
        except Exception:
            pass

    def kill(self):
        self.terminate()

def _run_elevated(exe_path: str, cwd: str, args=None):

    class SHELLEXECUTEINFOW(ctypes.Structure):
        _fields_ = [('cbSize', wintypes.DWORD), ('fMask', ctypes.c_ulong), ('hwnd', wintypes.HWND), ('lpVerb', wintypes.LPCWSTR), ('lpFile', wintypes.LPCWSTR), ('lpParameters', wintypes.LPCWSTR), ('lpDirectory', wintypes.LPCWSTR), ('nShow', ctypes.c_int), ('hInstApp', wintypes.HINSTANCE), ('lpIDList', ctypes.c_void_p), ('lpClass', wintypes.LPCWSTR), ('hKeyClass', wintypes.HKEY), ('dwHotKey', wintypes.DWORD), ('hIconOrMonitor', wintypes.HANDLE), ('hProcess', wintypes.HANDLE)]
    SEE_MASK_NOCLOSEPROCESS = 64
    SW_SHOWNORMAL = 1
    sei = SHELLEXECUTEINFOW()
    sei.cbSize = ctypes.sizeof(SHELLEXECUTEINFOW)
    sei.fMask = SEE_MASK_NOCLOSEPROCESS
    sei.hwnd = None
    sei.lpVerb = 'runas'
    sei.lpFile = exe_path
    if args:
        sei.lpParameters = args if isinstance(args, str) else subprocess.list2cmdline(list(args))
    else:
        sei.lpParameters = None
    sei.lpDirectory = cwd
    sei.nShow = SW_SHOWNORMAL
    sei.hInstApp = None
    ok = ctypes.windll.shell32.ShellExecuteExW(ctypes.byref(sei))
    if not ok or not sei.hProcess:
        err = ctypes.get_last_error()
        raise OSError(err, f'ShellExecuteEx(runas) failed for {exe_path}')
    return _ElevatedProc(sei.hProcess)

class _ShellOpenProc:

    def __init__(self):
        self.pid = None

    def wait(self, timeout=None):
        return 0

def _force_discrete_gpu(exe_path: str) -> bool:
    try:
        import winreg
        key_path = 'Software\\Microsoft\\DirectX\\UserGpuPreferences'
        exe_path = os.path.normpath(os.path.abspath(exe_path))
        key = winreg.CreateKeyEx(winreg.HKEY_CURRENT_USER, key_path, 0, winreg.KEY_SET_VALUE)
        winreg.SetValueEx(key, exe_path, 0, winreg.REG_SZ, 'GpuPreference=2;')
        winreg.CloseKey(key)
        return True
    except Exception as e:
        return False


# =================================================================
# FPS Overlay integration -- fps_overlay.py's full source is embedded
# below (gzip+base64) so this launcher ships as a single .py file. At
# first use it is extracted to a real file on disk and launched as its
# own separate process alongside a game, then torn down when the game
# exits or a new launch replaces it. It stays a separate process
# (rather than being imported/exec'd in-process) because it runs its
# own Tk mainloop and tray icon, which cannot safely share this
# process's Qt event loop, and because it needs to be independently
# killable without touching the launcher.
# =================================================================
_FPS_OVERLAY_PROC = None


class _GlobalShiftFHotkey:
    """Windows-wide Shift+F listener used to toggle the FPS overlay.

    RegisterHotKey is used instead of a low-level keyboard hook: it keeps the
    listener small, global, and independent of the launcher's Qt focus.
    """
    _HOTKEY_ID = 0x505346  # "PSF"
    _WM_HOTKEY = 0x0312
    _WM_QUIT = 0x0012
    _MOD_SHIFT = 0x0004
    _MOD_NOREPEAT = 0x4000

    def __init__(self, callback):
        self._callback = callback
        self._running = False
        self._thread = None
        self._thread_id = None

    def start(self):
        if os.name != 'nt' or self._thread is not None:
            return
        self._running = True
        self._thread = threading.Thread(
            target=self._run,
            name='PS5Launcher-ShiftF',
            daemon=True,
        )
        self._thread.start()

    def _run(self):
        if os.name != 'nt':
            return
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        self._thread_id = kernel32.GetCurrentThreadId()
        registered = bool(user32.RegisterHotKey(
            None,
            self._HOTKEY_ID,
            self._MOD_SHIFT | self._MOD_NOREPEAT,
            ord('F'),
        ))
        if not registered:
            self._thread_id = None
            return
        try:
            message = wintypes.MSG()
            while self._running:
                result = user32.GetMessageW(ctypes.byref(message), None, 0, 0)
                if result <= 0:
                    break
                if message.message == self._WM_HOTKEY and message.wParam == self._HOTKEY_ID:
                    try:
                        self._callback()
                    except Exception:
                        pass
        finally:
            user32.UnregisterHotKey(None, self._HOTKEY_ID)
            self._thread_id = None

    def stop(self):
        self._running = False
        thread_id = self._thread_id
        if thread_id and os.name == 'nt':
            try:
                ctypes.windll.user32.PostThreadMessageW(
                    thread_id, self._WM_QUIT, 0, 0)
            except Exception:
                pass
        thread = self._thread
        if thread is not None and thread is not threading.current_thread():
            thread.join(timeout=1.0)
        self._thread = None


# --- Lossless Scaling ("Super Frame") integration -----------------
# Unlike the FPS overlay, Lossless Scaling is a separate, user-owned,
# user-installed third-party app (we never bundle or download it). We
# only ever start/stop *that already-installed* exe, at a path the
# user points us to once in Settings. If Lossless Scaling was already
# running before we launched a game (e.g. the user starts it manually
# and always leaves it open), we leave it running when the game exits
# instead of yanking it out from under them.
_LOSSLESS_SCALING_PROC = None
_LOSSLESS_SCALING_WE_STARTED_IT = False
_LOSSLESS_SCALING_PROC_NAME = None
# Kernel-level safety net: a Windows Job Object with
# JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE, assigned to the Lossless Scaling
# process right after we start it. This guarantees LS gets killed by
# Windows itself the moment the launcher process's last handle to the
# job goes away -- which happens automatically on ANY launcher exit,
# including a hard crash, a native fault, or someone killing the
# launcher from Task Manager. It does NOT depend on our Python
# terminate()/kill() code running at all, so it covers the one case
# _stop_lossless_scaling() can't: the launcher dying before it gets a
# chance to run any cleanup code.
_LOSSLESS_SCALING_JOB_HANDLE = None

