def _fps_overlay_extracted_path() -> 'str | None':
    """Write the embedded fps_overlay.py source to a stable location on
    disk (once; re-used on later launches) and return its path. The
    SHA-256 of the decompressed source is checked before every launch
    so a corrupted/tampered extracted copy is never executed silently --
    it's just re-extracted from the embedded blob instead."""
    import gzip as _gzip, base64 as _base64, hashlib as _hashlib
    try:
        appdata = os.environ.get('APPDATA') or os.path.expanduser('~')
        state_dir = os.path.join(appdata, 'PS5Launcher')
        os.makedirs(state_dir, exist_ok=True)
        out_path = os.path.join(state_dir, 'fps_overlay.py')

        def _extracted_is_current():
            if not os.path.exists(out_path):
                return False
            try:
                with open(out_path, 'rb') as f:
                    return _hashlib.sha256(f.read()).hexdigest() == _FPS_OVERLAY_SOURCE_SHA256
            except Exception:
                return False

        if not _extracted_is_current():
            raw = _gzip.decompress(_base64.b64decode(_FPS_OVERLAY_SOURCE_B64GZIP))
            if _hashlib.sha256(raw).hexdigest() != _FPS_OVERLAY_SOURCE_SHA256:
                return None
            tmp_path = out_path + '.tmp'
            with open(tmp_path, 'wb') as f:
                f.write(raw)
            os.replace(tmp_path, out_path)
        return out_path
    except Exception:
        return None


def _fps_overlay_script_path() -> 'str | None':
    # An fps_overlay.py sitting next to this launcher (dev/debug layout)
    # always takes priority over the embedded copy.
    candidates = []
    try:
        candidates.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'fps_overlay.py'))
    except Exception:
        pass
    try:
        candidates.append(os.path.join(os.path.dirname(os.path.abspath(sys.argv[0])), 'fps_overlay.py'))
    except Exception:
        pass
    for c in candidates:
        if c and os.path.exists(c):
            return c
    return _fps_overlay_extracted_path()


def _patch_fps_overlay_controller_latency(script_path):
    """Add controller and input-to-display latency meters to the overlay.

    The overlay is hash-verified and embedded as a compressed blob.  Keeping
    this small compatibility patch here lets older bundled copies be upgraded
    without duplicating the 650KB PresentMon payload in the launcher source.
    The extracted file is re-created from the blob on the next run, then this
    patch is applied again.
    """
    marker = '# PS5_LAUNCHER_CONTROLLER_LATENCY_PATCH_V4'
    try:
        with open(script_path, 'r', encoding='utf-8') as f:
            source = f.read()
        if marker in source:
            return script_path

        sampler = r'''

# PS5_LAUNCHER_CONTROLLER_LATENCY_PATCH_V4
class ControllerLatencySampler:
    """Measure controller polling and best-effort input-to-present latency.

    PD1/PD2 is the controller polling interval.  ID1/ID2 measures from an
    XInput packet change to the next PresentMon frame-present event for the
    active game, so it includes input detection, game processing, rendering,
    and the present queue.  It is still a software estimate, not a photodiode
    measurement of photons leaving the display.
    """
    def __init__(self, reader, state):
        self.reader = reader
        self.target_state = state
        self._lock = threading.Lock()
        self._running = True
        self._get_state = None
        self._state_type = None
        self._values = [None] * 4
        self._display_values = [None] * 4
        self._connected = [False] * 4
        self._last_ok = [None] * 4
        self._last_packet = [None] * 4
        self._pending_input_at = [None] * 4
        self._last_present_seq = [0] * 4
        self._load_xinput()

    def _load_xinput(self):
        class _XINPUT_GAMEPAD(ctypes.Structure):
            _fields_ = [
                ("wButtons", wintypes.WORD),
                ("bLeftTrigger", wintypes.BYTE),
                ("bRightTrigger", wintypes.BYTE),
                ("sThumbLX", ctypes.c_short),
                ("sThumbLY", ctypes.c_short),
                ("sThumbRX", ctypes.c_short),
                ("sThumbRY", ctypes.c_short),
            ]
        class _XINPUT_STATE(ctypes.Structure):
            _fields_ = [
                ("dwPacketNumber", wintypes.DWORD),
                ("Gamepad", _XINPUT_GAMEPAD),
            ]
        self._state_type = _XINPUT_STATE
        for dll_name in ("xinput1_4.dll", "xinput1_3.dll", "xinput9_1_0.dll"):
            try:
                dll = ctypes.WinDLL(dll_name)
                fn = dll.XInputGetState
                fn.argtypes = [wintypes.DWORD, ctypes.POINTER(_XINPUT_STATE)]
                fn.restype = wintypes.DWORD
                self._get_state = fn
                return
            except Exception:
                continue

    def loop(self):
        if self._get_state is None:
            return
        while self._running:
            now = time.perf_counter()
            for slot in range(4):
                state = self._state_type()
                try:
                    result = int(self._get_state(slot, ctypes.byref(state)))
                except Exception:
                    result = 1167  # ERROR_DEVICE_NOT_CONNECTED
                if result == 0:
                    previous = self._last_ok[slot]
                    gap_ms = None if previous is None else (now - previous) * 1000.0
                    self._last_ok[slot] = now
                    with self._lock:
                        self._connected[slot] = True
                        if gap_ms is not None and 0.05 <= gap_ms <= 1000.0:
                            old = self._values[slot]
                            self._values[slot] = gap_ms if old is None else old * 0.8 + gap_ms * 0.2
                        packet = int(state.dwPacketNumber)
                        if self._last_packet[slot] is None:
                            self._last_packet[slot] = packet
                        elif packet != self._last_packet[slot]:
                            self._last_packet[slot] = packet
                            self._pending_input_at[slot] = now
                    self._capture_input_to_present(slot, now)
                else:
                    with self._lock:
                        self._connected[slot] = False
                        self._values[slot] = None
                        self._display_values[slot] = None
                    self._last_ok[slot] = None
                    self._last_packet[slot] = None
                    self._pending_input_at[slot] = None
            time.sleep(0.004)

    def _capture_input_to_present(self, slot, now):
        with self._lock:
            pending = self._pending_input_at[slot]
        if pending is None:
            return
        if now - pending > 1.0:
            with self._lock:
                self._pending_input_at[slot] = None
            return
        pid = getattr(self.target_state, "pid", None)
        if not pid:
            return
        try:
            with self.reader.lock:
                present = self.reader.last_present_at_by_pid.get(pid)
            if not present:
                return
            sequence, presented_at = present
            with self._lock:
                if presented_at < pending:
                    return
                latency_ms = (presented_at - pending) * 1000.0
                if 0.1 <= latency_ms <= 1000.0:
                    old = self._display_values[slot]
                    self._display_values[slot] = latency_ms if old is None else old * 0.7 + latency_ms * 0.3
                self._last_present_seq[slot] = sequence
                self._pending_input_at[slot] = None
        except Exception:
            return

    def readings(self):
        with self._lock:
            connected = [
                self._values[index]
                for index in range(4)
                if self._connected[index]
            ]
            return [(pad_number, value) for pad_number, value in enumerate(connected, 1)]

    def display_readings(self):
        with self._lock:
            connected = [
                self._display_values[index]
                for index in range(4)
                if self._connected[index]
            ]
            return [(pad_number, value) for pad_number, value in enumerate(connected, 1)]

    def stop(self):
        self._running = False


'''
        replacements = [
            ('        self.frame_times_by_pid = collections.defaultdict(\n'
             '            lambda: collections.deque(maxlen=self.WINDOW)\n'
             '        )\n'
             '        self.status_error = None',
             '        self.frame_times_by_pid = collections.defaultdict(\n'
             '            lambda: collections.deque(maxlen=self.WINDOW)\n'
             '        )\n'
             '        self.present_sequence_by_pid = collections.defaultdict(int)\n'
             '        self.last_present_at_by_pid = {}\n'
             '        self.status_error = None'),
            ('                got_any_data = True\n'
             '                with self.lock:\n'
             '                    self.frame_times_by_pid[pid].append(ms_between)',
             '                got_any_data = True\n'
             '                present_now = time.perf_counter()\n'
             '                with self.lock:\n'
             '                    self.frame_times_by_pid[pid].append(ms_between)\n'
             '                    self.present_sequence_by_pid[pid] += 1\n'
             '                    self.last_present_at_by_pid[pid] = (self.present_sequence_by_pid[pid], present_now)'),
            ('            with self.lock:\n'
             '                self.frame_times_by_pid.clear()',
             '            with self.lock:\n'
             '                self.frame_times_by_pid.clear()\n'
             '                self.present_sequence_by_pid.clear()\n'
             '                self.last_present_at_by_pid.clear()'),
            ('def make_tray_icon(on_quit, visible, on_toggle):', sampler + 'def make_tray_icon(on_quit, visible, on_toggle):'),
            ('OVERLAY_LINES_MAX = 6', 'OVERLAY_LINES_MAX = 14'),
            ('        pystray.MenuItem("GPU Model", _toggle("gpu_model"), checked=_checked("gpu_model")),',
             '        pystray.MenuItem("GPU Model", _toggle("gpu_model"), checked=_checked("gpu_model")),\n'
             '        pystray.MenuItem("PD1", _toggle("pd1"), checked=_checked("pd1")),\n'
             '        pystray.MenuItem("PD2", _toggle("pd2"), checked=_checked("pd2")),\n'
             '        pystray.MenuItem("PD3", _toggle("pd3"), checked=_checked("pd3")),\n'
             '        pystray.MenuItem("PD4", _toggle("pd4"), checked=_checked("pd4")),\n'
             '        pystray.MenuItem("ID", _toggle("id"), checked=_checked("id")),'),
            ('    threading.Thread(target=gpu_model_detector.loop, args=(state,), daemon=True).start()',
             '    threading.Thread(target=gpu_model_detector.loop, args=(state,), daemon=True).start()\n\n'
             '    pad_sampler = ControllerLatencySampler(reader, state)\n'
             '    threading.Thread(target=pad_sampler.loop, daemon=True).start()'),
            ('        "gpu_model": True,\n    }',
             '        "gpu_model": True,\n'
             '        "pd1": True,\n'
             '        "pd2": True,\n'
             '        "pd3": True,\n'
             '        "pd4": True,\n'
             '        "id": True,\n'
             '    }'),
            ('        if visible["fps"]:\n            lines.append(("F :", f"{state.fps:.0f}" if state.fps is not None else "--"))',
             '        if visible["fps"]:\n'
             '            lines.append(("F :", f"{state.fps:.0f}" if state.fps is not None else "--"))\n'
             '        if visible.get("id", True):\n'
             '            for pad_number, latency_ms in pad_sampler.display_readings():\n'
             '                value = "--" if latency_ms is None else f"{latency_ms:.1f}ms"\n'
             '                lines.append((f"ID{pad_number} :", value))'),
            ('        if visible["gpu_temp"]:\n            if gpu_temp_sampler.supported and gpu_temp_sampler.temp_c is not None:\n                lines.append(("GT :", f"{gpu_temp_sampler.temp_c:.0f}°C"))\n            else:\n                lines.append(("GT :", "N/A"))\n        return lines',
             '        if visible["gpu_temp"]:\n            if gpu_temp_sampler.supported and gpu_temp_sampler.temp_c is not None:\n'
             '                lines.append(("GT :", f"{gpu_temp_sampler.temp_c:.0f}°C"))\n'
             '            else:\n                lines.append(("GT :", "N/A"))\n'
             '        if visible.get("pd1", True):\n'
             '            for pad_number, delay_ms in pad_sampler.readings():\n'
             '                key = f"pd{pad_number}"\n'
             '                if visible.get(key, True):\n'
             '                    value = "--" if delay_ms is None else f"{delay_ms:.1f}ms"\n'
             '                    lines.append((f"PD{pad_number} :", value))\n'
             '        return lines'),
            ('        gpu_model_detector.stop()',
             '        gpu_model_detector.stop()\n        pad_sampler.stop()'),
        ]
        for old, new in replacements:
            if old not in source:
                return script_path
            source = source.replace(old, new, 1)
        tmp_path = script_path + '.pd.tmp'
        with open(tmp_path, 'w', encoding='utf-8') as f:
            f.write(source)
        os.replace(tmp_path, script_path)
    except Exception:
        try:
            if os.path.exists(script_path + '.pd.tmp'):
                os.remove(script_path + '.pd.tmp')
        except Exception:
            pass
    return script_path


def _start_fps_overlay(log=None, metrics=None):
    """Start the FPS overlay if it isn't already running. Safe to call
    repeatedly -- a live instance is left alone rather than restarted.

    'metrics', if given, is a dict like {'fps': True, 'cpu': False, ...}
    controlling which items the overlay shows initially (this comes from
    the launcher's General settings). It's passed via an environment
    variable rather than a file so it never touches the hash-verified
    embedded script on disk; the overlay's own tray menu can still be
    used to toggle items per-session same as before."""
    global _FPS_OVERLAY_PROC
    if _FPS_OVERLAY_PROC is not None and _FPS_OVERLAY_PROC.poll() is None:
        return True
    script = _fps_overlay_script_path()
    if not script:
        if log:
            log('FPS Overlay: fps_overlay.py not found and could not be extracted, skipping.')
        return False
    _patch_fps_overlay_controller_latency(script)

    if metrics:
        try:
            os.environ['FPS_OVERLAY_METRICS'] = json.dumps({k: bool(v) for k, v in metrics.items()})
        except Exception:
            pass

    # PresentMon (used by fps_overlay.py) needs Administrator to trace
    # frame-Present ETW events from *other* processes -- that's a Windows
    # restriction on ETW, not something we're choosing. Rather than forcing
    # the whole launcher to run elevated, we only elevate this one helper
    # process, so the user gets a single UAC prompt just for the overlay.
    if os.name == 'nt' and not _is_running_as_admin():
        try:
            # The launcher's own PID is passed as a plain argv flag (not an
            # env var) because ShellExecuteEx's 'runas' elevation spawns the
            # child under a different token/session via the UAC consent
            # process, which does not reliably inherit this process's
            # environment -- argv always gets through regardless of
            # elevation, so this is what the overlay uses to make sure it
            # never mistakes the launcher's own (usually hidden, but
            # sometimes briefly visible/maximized) window for the game.
            _FPS_OVERLAY_PROC = _run_elevated(sys.executable, os.path.dirname(script), ['--fps-overlay-worker', script, '--launcher-pid', str(os.getpid())])
            return True
        except OSError as exc:
            ERROR_CANCELLED = 1223  # user clicked "No" on the UAC prompt
            if getattr(exc, 'winerror', exc.args[0] if exc.args else None) == ERROR_CANCELLED:
                if log:
                    log('FPS Overlay: UAC prompt was declined -- starting without Administrator (some processes may not be traceable).')
            else:
                if log:
                    log(f'FPS Overlay: elevated start failed ({exc}), falling back to normal start.')
        except Exception as exc:
            if log:
                log(f'FPS Overlay: elevated start failed ({exc}), falling back to normal start.')

    try:
        creationflags = getattr(subprocess, 'CREATE_NO_WINDOW', 0) if os.name == 'nt' else 0
        _FPS_OVERLAY_PROC = subprocess.Popen([sys.executable, '--fps-overlay-worker', script, '--launcher-pid', str(os.getpid())], cwd=os.path.dirname(script), creationflags=creationflags, env=os.environ.copy())
        return True
    except Exception as exc:
        if log:
            log(f'FPS Overlay: failed to start ({exc})')
        _FPS_OVERLAY_PROC = None
        return False


def _stop_fps_overlay():
    """Terminate the FPS overlay process if one is running."""
    global _FPS_OVERLAY_PROC
    proc = _FPS_OVERLAY_PROC
    _FPS_OVERLAY_PROC = None
    if proc is None:
        return
    try:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=3)
            except Exception:
                proc.kill()
    except Exception:
        pass


def _lossless_scaling_process_name(ls_path: str) -> str:
    return os.path.basename(ls_path) or 'LosslessScaling.exe'


def _is_process_running_by_name(name: str) -> bool:
    if os.name != 'nt' or not name:
        return False
    try:
        out = subprocess.check_output(
            ['tasklist', '/FI', f'IMAGENAME eq {name}'],
            creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0),
            text=True, errors='ignore')
        return name.lower() in out.lower()
    except Exception:
        return False


def _find_process_images_containing(substr: str) -> list:
    """Returns image names (e.g. 'LosslessScaling.exe') of ALL currently
    running processes whose name contains `substr` (case-insensitive).
    Used as a broad fallback for apps like Lossless Scaling that run
    more than one exe (e.g. a separate render/scaling helper alongside
    the main UI) under a name that doesn't match whatever single path
    the user pointed us to in Settings -- matching on exact filename
    alone silently misses the helper and leaves it running."""
    if os.name != 'nt' or not substr:
        return []
    try:
        out = subprocess.check_output(
            ['tasklist', '/FO', 'CSV', '/NH'],
            creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0),
            text=True, errors='ignore')
    except Exception:
        return []
    names = []
    substr_l = substr.lower()
    for line in out.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            row = next(csv.reader([line]))
        except Exception:
            continue
        if not row:
            continue
        image_name = row[0]
        if substr_l in image_name.lower() and image_name not in names:
            names.append(image_name)
    return names


def force_kill_process_by_name(image_name: str, timeout: float = 5.0, allow_elevation_prompt: bool = True) -> bool:
    """Generic, escalating force-kill by process image name (e.g.
    'LosslessScaling.exe'). Works regardless of who started the process,
    whether it has a "close to tray" mode, or whether it re-execs itself
    under a new PID -- it always re-checks tasklist by name rather than
    trusting a stale PID/handle. Use this for ANY companion app the
    launcher needs to guarantee is closed when a game exits; just call it
    with that app's exe name, no other wiring required.

    Escalation order:
      1) taskkill /F /T /IM <name>            (plain force-kill)
      2) taskkill /F /T /IM <name> via 'runas' (covers an elevated target
         process when the launcher itself isn't elevated) -- SKIPPED when
         allow_elevation_prompt=False, since a UAC dialog raised while a
         fullscreen-exclusive game has focus renders on the secure
         desktop *behind* the game surface: it's real and waiting for a
         click, but invisible, so the caller just appears to hang until
         `timeout` elapses. The PS/Home hold-to-close path passes
         allow_elevation_prompt=False for exactly this reason and relies
         on step 3 instead.
      3) psutil per-PID .kill() sweep          (last-resort fallback)
    """
    if os.name != 'nt' or not image_name:
        return True

    def _still_running() -> bool:
        return _is_process_running_by_name(image_name)

    if not _still_running():
        return True

    try:
        subprocess.run(
            ['taskkill', '/F', '/T', '/IM', image_name],
            capture_output=True, timeout=8,
            creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
    except Exception:
        pass
    if not _still_running():
        return True

    if allow_elevation_prompt:
        try:
            params = f'/F /T /IM {image_name}'
            rc = ctypes.windll.shell32.ShellExecuteW(None, 'runas', 'taskkill.exe', params, None, 0)
            if rc > 32:
                deadline = time.time() + timeout
                while time.time() < deadline:
                    if not _still_running():
                        break
                    time.sleep(0.2)
        except Exception:
            pass
        if not _still_running():
            return True

    try:
        import psutil
        target = image_name.lower()
        for p in psutil.process_iter(['pid', 'name']):
            try:
                if (p.info.get('name') or '').lower() == target:
                    p.kill()
            except Exception:
                pass
        deadline = time.time() + 2.0
        while time.time() < deadline:
            if not _still_running():
                break
            time.sleep(0.2)
    except ImportError:
        pass
    except Exception:
        pass

    return not _still_running()


def force_kill_processes_containing(substr: str, timeout: float = 5.0) -> bool:
    """Same as force_kill_process_by_name, but sweeps every currently
    running process whose image name CONTAINS `substr` (case-insensitive)
    instead of one exact name. Use this for apps that run more than one
    exe (a main UI + a separate helper/render process) under names that
    don't all match a single configured path."""
    if os.name != 'nt' or not substr:
        return True
    ok = True
    for image_name in _find_process_images_containing(substr):
        if not force_kill_process_by_name(image_name, timeout=timeout):
            ok = False
    return ok


def _lossless_scaling_settings_path() -> str:
    local_appdata = os.environ.get('LOCALAPPDATA') or os.path.join(os.path.expanduser('~'), 'AppData', 'Local')
    return os.path.join(local_appdata, 'Lossless Scaling', 'Settings.xml')


def _ls_profile_titles(title_text: str) -> list:
    return [t.strip() for t in (title_text or '').split(';') if t.strip()]


def _ensure_lossless_scaling_autoscale_profile(game_exe_path: str, log=None) -> bool:
    """
    Makes sure Lossless Scaling has an Auto Scale profile matching this
    game, WITHOUT requiring the user to open LS and add the game by
    hand ("Super Frame" should just work the moment a game launches).

    We never invent new scaling settings: a new profile is a straight
    copy of whatever the user already has configured on their
    "Default" profile (so it behaves however they already like LS to
    behave), just scoped to this game's exe name via <Title> (LS
    matches profiles against exe name/path or window title) with
    <AutoScale> turned on.

    Only touches Settings.xml while LS itself is NOT running, since LS
    only reads this file at startup and would silently overwrite our
    edit with its own in-memory copy when it next exits otherwise. If
    LS is already running (e.g. the user always keeps it open), we
    leave the file alone -- the existing instance keeps working with
    whatever it already has, and the new/updated profile takes effect
    starting next time LS is (re)started.
    """
    if os.name != 'nt':
        return False
    settings_path = _lossless_scaling_settings_path()
    if not os.path.exists(settings_path):
        if log:
            log('Super Frame: Lossless Scaling settings not found yet -- run Lossless Scaling once first.')
        return False
    if _is_process_running_by_name('LosslessScaling.exe'):
        # A live instance holds its own in-memory copy of Settings.xml and
        # will overwrite our edit when it exits -- BUT leaving it running
        # and just skipping the edit (old behavior) means the profile
        # never gets our Path/AutoScaleDelay fix and AutoScale silently
        # never triggers. Force-close it (regardless of who started it)
        # so the edit below actually takes effect; _start_lossless_scaling
        # (called right after this function) will bring it back up fresh
        # with the corrected profile.
        try:
            subprocess.run(
                ['taskkill', '/IM', 'LosslessScaling.exe', '/F'],
                creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0),
                capture_output=True, timeout=5)
        except Exception:
            pass
        global _LOSSLESS_SCALING_PROC, _LOSSLESS_SCALING_WE_STARTED_IT
        _LOSSLESS_SCALING_PROC = None
        _LOSSLESS_SCALING_WE_STARTED_IT = False
        deadline = time.time() + 3
        while time.time() < deadline and _is_process_running_by_name('LosslessScaling.exe'):
            time.sleep(0.2)

    game_name = os.path.basename(game_exe_path or '')
    if not game_name:
        return False

    try:
        tree = ET.parse(settings_path)
        root = tree.getroot()
        game_profiles = root.find('GameProfiles')
        if game_profiles is None:
            game_profiles = ET.SubElement(root, 'GameProfiles')

        target_profile = None
        default_profile = None
        for profile in game_profiles.findall('Profile'):
            title_el = profile.find('Title')
            title_text = title_el.text if title_el is not None else ''
            if title_text and title_text.strip().lower() == 'default':
                default_profile = profile
            if game_name.lower() in [n.lower() for n in _ls_profile_titles(title_text)]:
                target_profile = profile
                break

        changed = False

        # MinimizeToTray lives at the root <Settings> level (a sibling of
        # StartAtWindowsStartup/CloseToTray), not per-profile -- it's an
        # app-wide LS setting. Combined with the -StartMinimized launch
        # flag in _start_lossless_scaling(), turning this on means LS
        # never shows a window at all: it goes straight to the tray
        # instead of sitting minimized on the taskbar. We only turn it
        # on, never off, so we're not fighting a preference the user set
        # deliberately in LS itself.
        minimize_to_tray_el = root.find('MinimizeToTray')
        if minimize_to_tray_el is None:
            minimize_to_tray_el = ET.SubElement(root, 'MinimizeToTray')
        if (minimize_to_tray_el.text or '').strip().lower() != 'true':
            minimize_to_tray_el.text = 'true'
            changed = True

        game_exe_full_path = os.path.abspath(game_exe_path) if game_exe_path else ''

        if target_profile is not None:
            autoscale_el = target_profile.find('AutoScale')
            if autoscale_el is None:
                autoscale_el = ET.SubElement(target_profile, 'AutoScale')
            if (autoscale_el.text or '').strip().lower() != 'true':
                autoscale_el.text = 'true'
                changed = True
            # LS matches AutoScale profiles against the full exe <Path>,
            # not just <Title> -- without it, AutoScale silently never
            # triggers even though the profile "exists". Backfill it if
            # missing or stale.
            if game_exe_full_path:
                path_el = target_profile.find('Path')
                if path_el is None:
                    path_el = ET.SubElement(target_profile, 'Path')
                if (path_el.text or '') != game_exe_full_path:
                    path_el.text = game_exe_full_path
                    changed = True
            # Give the game a few seconds to actually reach its main
            # render window before LS starts scaling -- with 0 delay LS
            # can grab/AutoScale too early (game still on a loading/splash
            # frame) and bail out almost immediately.
            delay_el = target_profile.find('AutoScaleDelay')
            if delay_el is None:
                delay_el = ET.SubElement(target_profile, 'AutoScaleDelay')
            if (delay_el.text or '').strip() != '0':
                delay_el.text = '0'
                changed = True
        else:
            source = default_profile if default_profile is not None else game_profiles.find('Profile')
            if source is None:
                if log:
                    log('Super Frame: no existing Lossless Scaling profile to copy settings from.')
                return False
            new_profile = copy.deepcopy(source)
            title_el = new_profile.find('Title')
            if title_el is None:
                title_el = ET.SubElement(new_profile, 'Title')
            title_el.text = game_name
            autoscale_el = new_profile.find('AutoScale')
            if autoscale_el is None:
                autoscale_el = ET.SubElement(new_profile, 'AutoScale')
            autoscale_el.text = 'true'
            if game_exe_full_path:
                path_el = new_profile.find('Path')
                if path_el is None:
                    path_el = ET.SubElement(new_profile, 'Path')
                path_el.text = game_exe_full_path
            delay_el = new_profile.find('AutoScaleDelay')
            if delay_el is None:
                delay_el = ET.SubElement(new_profile, 'AutoScaleDelay')
            delay_el.text = '0'
            game_profiles.append(new_profile)
            changed = True

        if changed:
            try:
                shutil.copyfile(settings_path, settings_path + '.bak')
            except Exception:
                pass
            tree.write(settings_path, encoding='utf-8', xml_declaration=True)
            if log:
                log(f'Super Frame: Lossless Scaling ready for {game_name} (Auto Scale on, minimized to tray).')
        return True
    except Exception as exc:
        if log:
            log(f'Super Frame: could not update Lossless Scaling profile ({exc})')
        return False


def _start_lossless_scaling(ls_path: str, log=None):
    """Start Lossless Scaling if it isn't already running. Safe to call
    repeatedly. Returns True if LS is running afterward (whether we
    started it or it was already up), False if it couldn't be started.

    We only launch the exe the user pointed us to in Settings -- we
    never download or bundle Lossless Scaling ourselves. If it was
    already running (started by the user, or by a previous launch we
    left alive), we note that and won't stop it later."""
    global _LOSSLESS_SCALING_PROC, _LOSSLESS_SCALING_WE_STARTED_IT
    if not ls_path:
        if log:
            log('Super Frame: Lossless Scaling path is not set (Settings > Super Frame).')
        return False
    if not os.path.exists(ls_path):
        if log:
            log(f'Super Frame: Lossless Scaling not found at {ls_path}')
        return False

    proc_name = _lossless_scaling_process_name(ls_path)
    if (_LOSSLESS_SCALING_PROC is not None and _LOSSLESS_SCALING_PROC.poll() is None):
        return True
    if _is_process_running_by_name(proc_name):
        # Already running -- not something we started, so we won't be
        # the one to close it either.
        _LOSSLESS_SCALING_PROC = None
        _LOSSLESS_SCALING_WE_STARTED_IT = False
        return True

    try:
        creationflags = getattr(subprocess, 'CREATE_NO_WINDOW', 0) if os.name == 'nt' else 0
        # -StartMinimized: an LS-native command-line flag that makes it
        # come up minimized instead of popping its window front-and-center
        # over the game. Combined with LS's own "Minimize to Tray" setting
        # (if the user has that on in LS itself), this keeps it out of the
        # way entirely instead of sitting on the taskbar.
        #
        # NOTE: we previously also tried forcing this via Windows'
        # STARTUPINFO/SW_HIDE at process-creation time, to rule out any
        # possible flicker. That turned out to break LS outright -- it
        # relies on its window actually being created (even if shown
        # minimized) to initialize its capture/render pipeline, so
        # SW_HIDE made it fail to start properly. Reverted: -StartMinimized
        # + MinimizeToTray is the combination that's actually confirmed to
        # work, so we stick to that alone.
        _LOSSLESS_SCALING_PROC = subprocess.Popen(
            [ls_path, '-StartMinimized'], cwd=os.path.dirname(ls_path), creationflags=creationflags)
        _LOSSLESS_SCALING_WE_STARTED_IT = True
        global _LOSSLESS_SCALING_PROC_NAME
        _LOSSLESS_SCALING_PROC_NAME = proc_name
        # Tie LS's lifetime to ours at the OS level: even if this launcher
        # is killed outright (crash, native fault, taskkill) before any of
        # our own cleanup code runs, Windows will still kill LS on its
        # own once our last handle to the job object disappears. This is
        # on top of (not instead of) the terminate()/kill() cleanup in
        # _stop_lossless_scaling() below, which handles the normal path.
        global _LOSSLESS_SCALING_JOB_HANDLE
        try:
            _LOSSLESS_SCALING_JOB_HANDLE = _assign_process_tree_job(_LOSSLESS_SCALING_PROC.pid)
        except Exception:
            _LOSSLESS_SCALING_JOB_HANDLE = None
        return True
    except Exception as exc:
        if log:
            log(f'Super Frame: failed to start Lossless Scaling ({exc})')
        _LOSSLESS_SCALING_PROC = None
        _LOSSLESS_SCALING_WE_STARTED_IT = False
        return False


# Companion apps that must be force-closed whenever a game session ends,
# regardless of who started them or how they behave (close-to-tray,
# self re-exec under a new PID, elevated helper processes, etc). To add
# a new app later: just add its exe name (or a distinctive substring) here
# -- no other code changes needed. 'exact' entries match one image name;
# 'contains' entries sweep every running process whose name contains the
# substring (use this for apps that spawn a separately-named helper exe).
GAME_EXIT_COMPANION_PROCESSES = {
    'exact': {'LosslessScaling.exe'},
    'contains': {'lossless'},
}


def close_game_exit_companion_processes(extra_exact=None, extra_contains=None, log=None):
    """Force-close every configured companion process on game exit.
    Always attempts this -- not gated on "did we start it" -- because
    that gate is exactly what let a leftover/pre-existing instance go
    unrecognized and never get closed again for the rest of the session.
    Safe to call even if nothing is running (each kill is a fast no-op
    when the process isn't found)."""
    if os.name != 'nt':
        return
    exact = set(GAME_EXIT_COMPANION_PROCESSES.get('exact', ())) | set(extra_exact or ())
    contains = set(GAME_EXIT_COMPANION_PROCESSES.get('contains', ())) | set(extra_contains or ())
    for image_name in exact:
        try:
            ok = force_kill_process_by_name(image_name)
            if log and not ok:
                log(f'Could not fully close {image_name}')
        except Exception:
            pass
    for substr in contains:
        try:
            force_kill_processes_containing(substr)
        except Exception:
            pass


def _stop_lossless_scaling():
    """Terminate Lossless Scaling. Always force-kills by process name --
    not gated on whether this launcher was the one that started it --
    because LS can (a) have "close to tray" behavior where a normal
    close/terminate signal just hides its window instead of exiting,
    (b) re-exec itself under a fresh PID after our initial Popen
    (first-run setup / single-instance hand-off), leaving our proc
    handle pointing at something already exited, and (c) run a separate
    helper/render process alongside the main UI exe under a different
    image name than whatever single path the user pointed us to in
    Settings. Trusting a stored PID/handle or a "did we start it" flag
    is fragile against all three; matching on process name via
    force_kill_process_by_name/force_kill_processes_containing is not."""
    global _LOSSLESS_SCALING_PROC, _LOSSLESS_SCALING_WE_STARTED_IT, _LOSSLESS_SCALING_JOB_HANDLE, _LOSSLESS_SCALING_PROC_NAME
    job = _LOSSLESS_SCALING_JOB_HANDLE
    proc_name = _LOSSLESS_SCALING_PROC_NAME
    _LOSSLESS_SCALING_PROC = None
    _LOSSLESS_SCALING_WE_STARTED_IT = False
    _LOSSLESS_SCALING_JOB_HANDLE = None
    _LOSSLESS_SCALING_PROC_NAME = None
    # Stop any active game-exit watchdog and clear its watch state so a
    # stale thread can't kill LS for the wrong (or no) game later.
    _LS_WATCHDOG_STOP.set()
    with _LS_WATCHDOG_LOCK:
        _LS_WATCH_GAME_EXE = None
        _LS_WATCH_GAME_PID = None
    # Belt-and-suspenders: closing the job handle triggers
    # JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE, which kills LS immediately if
    # it's still tied to our job object.
    _close_process_tree_job(job)
    extra_exact = {proc_name} if proc_name else None
    close_game_exit_companion_processes(extra_exact=extra_exact)


# ---------------------------------------------------------------------
# Lossless Scaling per-game exit watchdog
# ---------------------------------------------------------------------
# The launcher's own game-exit detection (_poll_game_alive ->
# _restore_after_game) relies on window matching. Lossless Scaling's own
# window/process can be mistaken for the game there (it stays alive after
# the game closes, so the "which window is the game" fallback latches
# onto it and _restore_after_game never fires). The window matchers below
# now exclude LS by image name, and this independent watchdog force-closes
# LS by polling the real game executable as an extra safety net -- so LS
# can never outlive the game session it was started for.
_LOSSLESS_SCALING_EXE_NAMES = ('losslessscaling.exe',)
_LOSSLESS_SCALING_SUBSTRINGS = ('lossless',)
_LS_WATCHDOG_LOCK = threading.Lock()
_LS_WATCH_GAME_EXE = None
_LS_WATCH_GAME_PID = None
_LS_WATCHDOG_GEN = 0
_LS_WATCHDOG_STOP = threading.Event()
_LS_WATCHDOG_GRACE_SEC = 30.0
_LS_WATCHDOG_POLL_SEC = 1.0
_LS_WATCHDOG_GONE_CONFIRM = 3


def _is_lossless_scaling_image_name(base_lower: str) -> bool:
    """True when a process image basename belongs to Lossless Scaling
    (main exe or any of its helper/render processes). Used to keep LS's
    own window from being mistaken for the game window in the launcher's
    window-based game-exit detection."""
    base_lower = (base_lower or '').lower()
    if not base_lower:
        return False
    if base_lower in _LOSSLESS_SCALING_EXE_NAMES:
        return True
    return any(s in base_lower for s in _LOSSLESS_SCALING_SUBSTRINGS)


def _lossless_scaling_watchdog(game_exe: str, game_pid, gen: int):
    """Background thread: while a game session with Super Frame is active,
    poll the real game executable (by pid, then by image name, then by
    window presence) and force-close Lossless Scaling once the game is
    confirmed gone. Never kills LS before the game has been seen alive at
    least once, and gives up silently if the game never appears (the
    launcher's own cleanup still handles that case)."""
    global _LS_WATCH_GAME_EXE, _LS_WATCH_GAME_PID
    game_exe_l = (game_exe or '').lower()
    if not game_exe_l:
        return
    deadline = time.time() + _LS_WATCHDOG_GRACE_SEC
    seen_alive = False
    gone_streak = 0
    while not _LS_WATCHDOG_STOP.is_set():
        with _LS_WATCHDOG_LOCK:
            if _LS_WATCHDOG_GEN != gen:
                return
            if not _LS_WATCH_GAME_EXE:
                return
        alive = False
        if game_pid and _pid_alive(game_pid):
            alive = True
        if not alive and _process_running_by_name(game_exe_l):
            alive = True
        if not alive and _game_window_present(game_exe_l, target_pid=game_pid):
            alive = True
        if alive:
            seen_alive = True
            gone_streak = 0
        else:
            if seen_alive:
                gone_streak += 1
                if gone_streak >= _LS_WATCHDOG_GONE_CONFIRM:
                    with _LS_WATCHDOG_LOCK:
                        if _LS_WATCHDOG_GEN != gen:
                            return
                        _LS_WATCH_GAME_EXE = None
                        _LS_WATCH_GAME_PID = None
                    _stop_lossless_scaling()
                    return
            elif time.time() > deadline:
                return
        _LS_WATCHDOG_STOP.wait(_LS_WATCHDOG_POLL_SEC)


def _arm_lossless_scaling_watchdog(game_exe: str, game_pid):
    """Start (or restart) the per-game LS watchdog for a Super Frame
    launch. Safe to call repeatedly; a stale watchdog from a previous
    session is invalidated via the generation counter."""
    global _LS_WATCHDOG_GEN
    game_exe_l = (game_exe or '').lower()
    if not game_exe_l:
        return
    _LS_WATCHDOG_STOP.set()
    with _LS_WATCHDOG_LOCK:
        _LS_WATCHDOG_GEN += 1
        gen = _LS_WATCHDOG_GEN
        _LS_WATCH_GAME_EXE = game_exe_l
        _LS_WATCH_GAME_PID = game_pid
    _LS_WATCHDOG_STOP.clear()
    threading.Thread(target=_lossless_scaling_watchdog, args=(game_exe_l, game_pid, gen), daemon=True, name='LosslessScalingWatchdog').start()


_BOOSTER_PROC_NAME_BLACKLIST = {'system', 'system idle process', 'registry', 'smss.exe', 'csrss.exe', 'wininit.exe', 'winlogon.exe', 'services.exe', 'lsass.exe', 'lsaiso.exe', 'svchost.exe', 'dwm.exe', 'fontdrvhost.exe', 'sihost.exe', 'explorer.exe', 'taskhostw.exe', 'ctfmon.exe', 'audiodg.exe', 'spoolsv.exe', 'wudfhost.exe', 'runtimebroker.exe', 'shellexperiencehost.exe', 'searchindexer.exe', 'searchapp.exe', 'searchhost.exe', 'dllhost.exe', 'conhost.exe', 'wmiprvse.exe', 'msmpeng.exe', 'nissrv.exe', 'securityhealthservice.exe', 'securityhealthsystray.exe', 'python.exe', 'pythonw.exe'}
_POWER_PLAN_HIGH_PERFORMANCE_GUID = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'

def _list_gpus():
    gpus = []
    try:
        out = subprocess.run(['powershell', '-NoProfile', '-Command', 'Get-CimInstance Win32_VideoController | Select-Object Name,AdapterRAM | ConvertTo-Json -Compress'], capture_output=True, text=True, timeout=6, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        if out.returncode == 0 and out.stdout.strip():
            data = json.loads(out.stdout)
            if isinstance(data, dict):
                data = [data]
            for d in data:
                name = (d.get('Name') or '').strip()
                if not name:
                    continue
                ram = d.get('AdapterRAM') or 0
                try:
                    ram_mb = int(ram) // (1024 * 1024) if ram and int(ram) > 0 else 0
                except (TypeError, ValueError):
                    ram_mb = 0
                gpus.append({'name': name, 'vram_mb': ram_mb})
    except Exception as e:
        pass

    def _norm(s):
        return re.sub('\\s+', ' ', s or '').strip().lower()
    try:
        nv_out = subprocess.run(['nvidia-smi', '--query-gpu=name,memory.total', '--format=csv,noheader,nounits'], capture_output=True, text=True, timeout=6, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        if nv_out.returncode == 0 and nv_out.stdout.strip():
            for line in nv_out.stdout.strip().splitlines():
                parts = [p.strip() for p in line.split(',')]
                if len(parts) != 2:
                    continue
                nv_name, nv_mb_str = parts
                try:
                    nv_mb = int(float(nv_mb_str))
                except (TypeError, ValueError):
                    continue
                if nv_mb <= 0:
                    continue
                nv_norm = _norm(nv_name)
                matched = False
                for g in gpus:
                    gn = _norm(g['name'])
                    if gn == nv_norm or nv_norm in gn or gn in nv_norm:
                        if nv_mb > g['vram_mb']:
                            g['vram_mb'] = nv_mb
                        matched = True
                if not matched:
                    gpus.append({'name': nv_name, 'vram_mb': nv_mb})
    except Exception as e:
        pass
    try:
        reg_out = subprocess.run(['powershell', '-NoProfile', '-Command', "Get-ItemProperty -Path 'HKLM:\\SYSTEM\\CurrentControlSet\\Control\\Class\\{4d36e968-e325-11ce-bfc1-08002be10318}\\*' -Name 'HardwareInformation.qwMemorySize','DriverDesc' -ErrorAction SilentlyContinue | Select-Object DriverDesc,'HardwareInformation.qwMemorySize' | ConvertTo-Json -Compress"], capture_output=True, text=True, timeout=6, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        if reg_out.returncode == 0 and reg_out.stdout.strip():
            reg_data = json.loads(reg_out.stdout)
            if isinstance(reg_data, dict):
                reg_data = [reg_data]
            for rd in reg_data:
                rname = (rd.get('DriverDesc') or '').strip()
                qsize = rd.get('HardwareInformation.qwMemorySize')
                if not rname or not qsize:
                    continue
                try:
                    real_mb = int(qsize) // (1024 * 1024)
                except (TypeError, ValueError):
                    continue
                if real_mb <= 0:
                    continue
                rn_norm = _norm(rname)
                for g in gpus:
                    gn = _norm(g['name'])
                    if (gn == rn_norm or rn_norm in gn or gn in rn_norm) and real_mb > g['vram_mb']:
                        g['vram_mb'] = real_mb
    except Exception as e:
        pass
    return gpus

def _strongest_gpu_name() -> str:
    gpus = _list_gpus()
    if not gpus:
        return 'Not detected'

    def _score(g):
        name_l = g['name'].lower()
        discrete = any((k in name_l for k in ('nvidia', 'geforce', 'rtx', 'gtx', 'quadro', 'radeon', 'amd')))
        integrated = any((k in name_l for k in ('intel', 'microsoft basic', 'uhd graphics', 'iris')))
        return (1 if discrete and (not integrated) else 0, g['vram_mb'])
    best = max(gpus, key=_score)
    if best['vram_mb'] > 0:
        return f"{best['name']}  ({best['vram_mb']} MB VRAM)"
    return best['name']

def _get_active_power_scheme_guid():
    try:
        out = subprocess.run(['powercfg', '/getactivescheme'], capture_output=True, text=True, timeout=5, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        m = re.search('([0-9a-fA-F-]{36})', out.stdout or '')
        return m.group(1) if m else None
    except Exception as e:
        return None

def _set_power_plan(guid: str) -> bool:
    try:
        r = subprocess.run(['powercfg', '/setactive', guid], capture_output=True, text=True, timeout=5, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        return r.returncode == 0
    except Exception as e:
        return False


def _set_process_priority_safe(pid: int, mode: str='above_normal', allow_high: bool=False) -> bool:
    classes = {'normal': 32, 'above_normal': 32768, 'high': 128}
    mode = str(mode or 'above_normal').strip().lower()
    if mode not in classes:
        mode = 'above_normal'
    if mode == 'high' and (not allow_high):
        mode = 'above_normal'
    priority_class = classes[mode]
    PROCESS_SET_INFORMATION = 512
    PROCESS_QUERY_INFORMATION = 1024
    try:
        h = ctypes.windll.kernel32.OpenProcess(PROCESS_SET_INFORMATION | PROCESS_QUERY_INFORMATION, False, int(pid))
        if not h:
            return False
        try:
            return bool(ctypes.windll.kernel32.SetPriorityClass(h, priority_class))
        finally:
            ctypes.windll.kernel32.CloseHandle(h)
    except Exception as e:
        return False

def _assign_process_tree_job(pid: int):
    if os.name != 'nt':
        return None
    try:

        class _BasicLimit(ctypes.Structure):
            _fields_ = [('PerProcessUserTimeLimit', ctypes.c_longlong), ('PerJobUserTimeLimit', ctypes.c_longlong), ('LimitFlags', wintypes.DWORD), ('MinimumWorkingSetSize', ctypes.c_size_t), ('MaximumWorkingSetSize', ctypes.c_size_t), ('ActiveProcessLimit', wintypes.DWORD), ('Affinity', ctypes.c_size_t), ('PriorityClass', wintypes.DWORD), ('SchedulingClass', wintypes.DWORD)]

        class _IoCounters(ctypes.Structure):
            _fields_ = [('ReadOperationCount', ctypes.c_ulonglong), ('WriteOperationCount', ctypes.c_ulonglong), ('OtherOperationCount', ctypes.c_ulonglong), ('ReadTransferCount', ctypes.c_ulonglong), ('WriteTransferCount', ctypes.c_ulonglong), ('OtherTransferCount', ctypes.c_ulonglong)]

        class _ExtendedLimit(ctypes.Structure):
            _fields_ = [('BasicLimitInformation', _BasicLimit), ('IoInfo', _IoCounters), ('ProcessMemoryLimit', ctypes.c_size_t), ('JobMemoryLimit', ctypes.c_size_t), ('PeakProcessMemoryUsed', ctypes.c_size_t), ('PeakJobMemoryUsed', ctypes.c_size_t)]
        job = ctypes.windll.kernel32.CreateJobObjectW(None, None)
        if not job:
            return None
        info = _ExtendedLimit()
        info.BasicLimitInformation.LimitFlags = 8192
        if not ctypes.windll.kernel32.SetInformationJobObject(job, 9, ctypes.byref(info), ctypes.sizeof(info)):
            ctypes.windll.kernel32.CloseHandle(job)
            return None
        process = ctypes.windll.kernel32.OpenProcess(1 | 256, False, int(pid))
        if not process:
            ctypes.windll.kernel32.CloseHandle(job)
            return None
        try:
            if not ctypes.windll.kernel32.AssignProcessToJobObject(job, process):
                ctypes.windll.kernel32.CloseHandle(job)
                return None
        finally:
            ctypes.windll.kernel32.CloseHandle(process)
        return job
    except Exception:
        return None

def _close_process_tree_job(job):
    if not job:
        return
    try:
        if os.name == 'nt':
            ctypes.windll.kernel32.CloseHandle(job)
    except Exception:
        pass

def _sanitized_child_process_path() -> str:
    """
    PyInstaller's onedir bootloader prepends this launcher's own bundled
    runtime folder (sys._MEIPASS, i.e. the "_internal" folder next to
    PS5-Launcher.exe) to *this process's* PATH so its own internal
    ctypes/DLL loads can find things like vcruntime140.dll. That's fine
    for the launcher itself, but PATH is inherited verbatim by every
    game/emulator we spawn (_active_content_environment below used to
    just os.environ.copy() it) -- so a bare, path-less
    LoadLibrary("vcruntime140.dll") call inside a launched game or
    emulator can resolve to OUR bundled copy instead of the correct
    system-wide one, purely because our private folder happened to sit
    earlier on PATH. That's exactly what produced the "vcruntime140.dll
    was incorrectly installed" dialog on some shortcuts: the offending
    file was never in the game/emulator's own folder, it was ours,
    found only because we handed it our PATH. Deleting that file by
    hand "fixed" it once, but every rebuild puts it right back -- so we
    strip our own bundled folders out of the PATH we hand to children
    here instead, which fixes it permanently regardless of what ends up
    inside _internal in future builds.
    """
    raw_path = os.environ.get('PATH', '')
    if not getattr(sys, 'frozen', False):
        return raw_path
    own_dirs = set()
    meipass = getattr(sys, '_MEIPASS', '')
    if meipass:
        own_dirs.add(os.path.normcase(os.path.abspath(meipass)))
    exe_dir = os.path.dirname(os.path.abspath(sys.executable))
    own_dirs.add(os.path.normcase(exe_dir))
    own_dirs.add(os.path.normcase(os.path.join(exe_dir, '_internal')))
    kept = []
    for entry in raw_path.split(os.pathsep):
        if entry and os.path.normcase(os.path.abspath(entry)) not in own_dirs:
            kept.append(entry)
    return os.pathsep.join(kept)


def _active_content_environment(app: dict) -> dict:
    env = os.environ.copy()
    env['PATH'] = _sanitized_child_process_path()
    content = app.get('content_paths') or {}
    enabled = content.get('enabled', {}) or {}
    all_entries = {os.path.abspath(str(path)): key for key in ('patches', 'dlc', 'mods') for path in content.get(key, []) or []}
    saved_order = content.get('load_order') or []
    ordered_paths = [os.path.abspath(str(path)) for path in saved_order if os.path.abspath(str(path)) in all_entries]
    ordered_paths += [path for path in all_entries if path not in ordered_paths]
    ordered_entries = [(all_entries[path], path) for path in ordered_paths if enabled.get(path, True) and os.path.isdir(path)]
    for key, variable in (('dlc', 'GAMESTATION_DLC_PATHS'), ('mods', 'GAMESTATION_MOD_PATHS'), ('patches', 'GAMESTATION_PATCH_PATHS')):
        paths = [os.path.abspath(str(path)) for path in content.get(key) or [] if enabled.get(path, True) and os.path.isdir(path)]
        if paths:
            env[variable] = os.pathsep.join(paths)
    if ordered_entries:
        env['GAMESTATION_CONTENT_ORDER'] = os.pathsep.join((f'{kind}={path}' for kind, path in ordered_entries))
    return env

def _content_conflicts(app: dict):
    content = app.get('content_paths') or {}
    enabled = content.get('enabled', {}) or {}
    by_relative_path = collections.defaultdict(list)
    for kind in ('patches', 'dlc', 'mods'):
        for folder in content.get(kind, []) or []:
            if not enabled.get(folder, True) or not os.path.isdir(folder):
                continue
            for root, _dirs, files in os.walk(folder):
                for name in files:
                    relative = os.path.normcase(os.path.relpath(os.path.join(root, name), folder))
                    by_relative_path[relative].append((kind, folder))
    return {relative: entries for relative, entries in by_relative_path.items() if len(entries) > 1}

def _enum_process_ids():
    arr_size = 4096
    while True:
        arr = (wintypes.DWORD * arr_size)()
        needed = wintypes.DWORD()
        ok = ctypes.windll.psapi.EnumProcesses(ctypes.byref(arr), ctypes.sizeof(arr), ctypes.byref(needed))
        if not ok:
            return []
        count = needed.value // ctypes.sizeof(wintypes.DWORD)
        if count < arr_size:
            return [pid for pid in arr[:count] if pid]
        arr_size *= 2

def _process_name_from_pid(pid: int) -> str:
    PROCESS_QUERY_LIMITED_INFORMATION = 4096
    try:
        h = ctypes.windll.kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, int(pid))
        if not h:
            return ''
        try:
            buf = ctypes.create_unicode_buffer(260)
            size = wintypes.DWORD(260)
            if ctypes.windll.kernel32.QueryFullProcessImageNameW(h, 0, buf, ctypes.byref(size)):
                return os.path.basename(buf.value)
            return ''
        finally:
            ctypes.windll.kernel32.CloseHandle(h)
    except Exception:
        return ''

def _trim_background_memory(exclude_pids: set) -> int:
    PROCESS_SET_QUOTA = 256
    PROCESS_QUERY_INFORMATION = 1024
    trimmed = 0
    my_pid = os.getpid()
    for pid in _enum_process_ids():
        if pid in exclude_pids or pid == my_pid or pid <= 4:
            continue
        name = _process_name_from_pid(pid)
        if not name or name.lower() in _BOOSTER_PROC_NAME_BLACKLIST:
            continue
        try:
            h = ctypes.windll.kernel32.OpenProcess(PROCESS_SET_QUOTA | PROCESS_QUERY_INFORMATION, False, pid)
            if not h:
                continue
            try:
                if ctypes.windll.psapi.EmptyWorkingSet(h):
                    trimmed += 1
            finally:
                ctypes.windll.kernel32.CloseHandle(h)
        except Exception:
            continue
    return trimmed

def _purge_standby_memory() -> bool:
    try:
        TOKEN_ADJUST_PRIVILEGES = 32
        TOKEN_QUERY = 8
        SE_PRIVILEGE_ENABLED = 2

        class LUID(ctypes.Structure):
            _fields_ = [('LowPart', wintypes.DWORD), ('HighPart', wintypes.LONG)]

        class LUID_AND_ATTRIBUTES(ctypes.Structure):
            _fields_ = [('Luid', LUID), ('Attributes', wintypes.DWORD)]

        class TOKEN_PRIVILEGES(ctypes.Structure):
            _fields_ = [('PrivilegeCount', wintypes.DWORD), ('Privileges', LUID_AND_ATTRIBUTES * 1)]
        htoken = wintypes.HANDLE()
        if not ctypes.windll.advapi32.OpenProcessToken(ctypes.windll.kernel32.GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, ctypes.byref(htoken)):
            return False
        try:
            luid = LUID()
            if not ctypes.windll.advapi32.LookupPrivilegeValueW(None, 'SeProfileSingleProcessPrivilege', ctypes.byref(luid)):
                return False
            tp = TOKEN_PRIVILEGES()
            tp.PrivilegeCount = 1
            tp.Privileges[0] = LUID_AND_ATTRIBUTES(luid, SE_PRIVILEGE_ENABLED)
            if not ctypes.windll.advapi32.AdjustTokenPrivileges(htoken, False, ctypes.byref(tp), 0, None, None):
                return False
        finally:
            ctypes.windll.kernel32.CloseHandle(htoken)
        SystemMemoryListInformation = 80
        MemoryPurgeStandbyList = 4
        cmd = ctypes.c_int(MemoryPurgeStandbyList)
        status = ctypes.windll.ntdll.NtSetSystemInformation(SystemMemoryListInformation, ctypes.byref(cmd), ctypes.sizeof(cmd))
        return status == 0
    except Exception as e:
        return False

def _is_running_as_admin() -> bool:
    try:
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except Exception:
        return False

class _MEMORYSTATUSEX(ctypes.Structure):
    _fields_ = [('dwLength', wintypes.DWORD), ('dwMemoryLoad', wintypes.DWORD), ('ullTotalPhys', ctypes.c_uint64), ('ullAvailPhys', ctypes.c_uint64), ('ullTotalPageFile', ctypes.c_uint64), ('ullAvailPageFile', ctypes.c_uint64), ('ullTotalVirtual', ctypes.c_uint64), ('ullAvailVirtual', ctypes.c_uint64), ('ullAvailExtendedVirtual', ctypes.c_uint64)]

def _get_available_memory_mb():
    try:
        stat = _MEMORYSTATUSEX()
        stat.dwLength = ctypes.sizeof(_MEMORYSTATUSEX)
        if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(stat)):
            return stat.ullAvailPhys // (1024 * 1024)
        return None
    except Exception:
        return None

def _set_game_dvr_enabled(enabled: bool) -> bool:
    try:
        import winreg
        ok = True
        try:
            k = winreg.CreateKeyEx(winreg.HKEY_CURRENT_USER, 'System\\GameConfigStore', 0, winreg.KEY_SET_VALUE)
            winreg.SetValueEx(k, 'GameDVR_Enabled', 0, winreg.REG_DWORD, 1 if enabled else 0)
            winreg.CloseKey(k)
        except Exception:
            ok = False
        try:
            k2 = winreg.CreateKeyEx(winreg.HKEY_CURRENT_USER, 'Software\\Microsoft\\Windows\\CurrentVersion\\GameDVR', 0, winreg.KEY_SET_VALUE)
            winreg.SetValueEx(k2, 'AppCaptureEnabled', 0, winreg.REG_DWORD, 1 if enabled else 0)
            winreg.CloseKey(k2)
        except Exception:
            ok = False
        return ok
    except Exception as e:
        return False

def _set_gamebar_controller_button_enabled(enabled: bool) -> bool:
    """Windows' Xbox Game Bar has its own separate hook that opens the
    Game Bar overlay whenever it sees a GUIDE/Xbox-button press on ANY
    XInput-recognized pad -- including our own ViGEm-emulated virtual
    Xbox pad, which is exactly what fires when the PS button is mapped
    to XI_GUIDE for an Xbox-profile game. This is independent of
    GameDVR/AppCaptureEnabled above (that only controls recording, not
    this hook), so disabling GameDVR alone does not stop it. The
    dedicated toggle lives in Xbox Game Bar's own settings ("Open Game
    Bar using this button on a controller") and is stored here."""
    try:
        import winreg
        k = winreg.CreateKeyEx(winreg.HKEY_CURRENT_USER, 'Software\\Microsoft\\GameBar', 0, winreg.KEY_SET_VALUE)
        winreg.SetValueEx(k, 'UseNexusForGameBarEnabled', 0, winreg.REG_DWORD, 1 if enabled else 0)
        winreg.CloseKey(k)
        return True
    except Exception:
        return False

