_POWERCFG_SUB_PROCESSOR = '54533251-82be-4824-96c1-47b60b740d00'
_POWERCFG_CORE_PARKING_MIN_CORES = '0cc5b647-c1df-4637-891a-dec35c318583'

def _get_power_setting_value(sub_guid: str, setting_guid: str):
    try:
        r = subprocess.run(['powercfg', '/query', 'SCHEME_CURRENT', sub_guid], capture_output=True, text=True, timeout=5, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        if r.returncode != 0:
            return None
        in_block = False
        for line in r.stdout.splitlines():
            if setting_guid.lower() in line.lower():
                in_block = True
                continue
            if in_block and 'Current AC Power Setting Index' in line:
                m = re.search('0x([0-9a-fA-F]+)', line)
                return int(m.group(1), 16) if m else None
        return None
    except Exception as e:
        return None

def _set_core_parking_min_cores(percent: int) -> bool:
    try:
        percent = max(0, min(100, int(percent)))
        r1 = subprocess.run(['powercfg', '/setacvalueindex', 'SCHEME_CURRENT', _POWERCFG_SUB_PROCESSOR, _POWERCFG_CORE_PARKING_MIN_CORES, str(percent)], capture_output=True, text=True, timeout=5, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        if r1.returncode != 0:
            return False
        subprocess.run(['powercfg', '/setactive', 'SCHEME_CURRENT'], capture_output=True, text=True, timeout=5, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        return True
    except Exception as e:
        return False

def _get_p_core_affinity_mask():
    try:
        import struct as _struct
        GetSystemCpuSetInformation = ctypes.windll.kernel32.GetSystemCpuSetInformation
        needed = wintypes.DWORD(0)
        GetSystemCpuSetInformation(None, 0, ctypes.byref(needed), None, 0)
        if not needed.value:
            return None
        buf = ctypes.create_string_buffer(needed.value)
        if not GetSystemCpuSetInformation(buf, needed.value, ctypes.byref(needed), None, 0):
            return None
        buf_bytes = buf.raw
        n = len(buf_bytes)
        offset = 0
        efficiency_by_lpindex = {}
        while offset + 32 <= n:
            entry_size = _struct.unpack_from('<I', buf_bytes, offset)[0]
            if entry_size < 32 or offset + entry_size > n:
                break
            lp_index = buf_bytes[offset + 14]
            eff_class = buf_bytes[offset + 18]
            efficiency_by_lpindex[lp_index] = eff_class
            offset += entry_size
        if not efficiency_by_lpindex:
            return None
        max_eff = max(efficiency_by_lpindex.values())
        min_eff = min(efficiency_by_lpindex.values())
        if max_eff == min_eff:
            return None
        mask = 0
        for lp_index, eff in efficiency_by_lpindex.items():
            if eff == max_eff:
                mask |= 1 << lp_index
        return mask or None
    except Exception as e:
        return None

def _set_process_affinity(pid: int, mask: int) -> bool:
    PROCESS_SET_INFORMATION = 512
    PROCESS_QUERY_INFORMATION = 1024
    try:
        h = ctypes.windll.kernel32.OpenProcess(PROCESS_SET_INFORMATION | PROCESS_QUERY_INFORMATION, False, int(pid))
        if not h:
            return False
        try:
            return bool(ctypes.windll.kernel32.SetProcessAffinityMask(h, ctypes.c_size_t(mask)))
        finally:
            ctypes.windll.kernel32.CloseHandle(h)
    except Exception as e:
        return False


