class _SYSTEM_POWER_STATUS(ctypes.Structure):
    _fields_ = [('ACLineStatus', ctypes.c_ubyte), ('BatteryFlag', ctypes.c_ubyte), ('BatteryLifePercent', ctypes.c_ubyte), ('SystemStatusFlag', ctypes.c_ubyte), ('BatteryLifeTime', wintypes.DWORD), ('BatteryFullLifeTime', wintypes.DWORD)]
_BOOSTER_LOW_BATTERY_THRESHOLD = 30

def _get_power_status():
    try:
        status = _SYSTEM_POWER_STATUS()
        if not ctypes.windll.kernel32.GetSystemPowerStatus(ctypes.byref(status)):
            return None
        is_laptop = status.BatteryFlag not in (128, 255)
        on_battery = status.ACLineStatus == 0
        pct = status.BatteryLifePercent if status.BatteryLifePercent <= 100 else None
        return {'is_laptop': is_laptop, 'on_battery': on_battery, 'battery_percent': pct}
    except Exception as e:
        return None
_BOOSTER_PROFILES = {'eco': {'booster_enabled': True, 'booster_trim_ram': True, 'booster_high_priority': False, 'booster_power_plan': False, 'booster_disable_gamedvr': True, 'booster_nvidia_perf_mode': False, 'booster_core_parking_off': False, 'booster_affinity_pcores': False, 'booster_stop_services': False, 'booster_suppress_notifications': False, 'booster_battery_aware': True}, 'balanced': {'booster_enabled': True, 'booster_trim_ram': True, 'booster_high_priority': True, 'booster_power_plan': True, 'booster_disable_gamedvr': True, 'booster_nvidia_perf_mode': True, 'booster_core_parking_off': False, 'booster_affinity_pcores': False, 'booster_stop_services': False, 'booster_suppress_notifications': False, 'booster_battery_aware': True}, 'max': {'booster_enabled': True, 'booster_trim_ram': True, 'booster_high_priority': True, 'booster_power_plan': True, 'booster_disable_gamedvr': True, 'booster_nvidia_perf_mode': True, 'booster_core_parking_off': True, 'booster_affinity_pcores': True, 'booster_stop_services': True, 'booster_suppress_notifications': True, 'booster_battery_aware': True}}
_BOOSTER_PROFILE_LABELS = {'eco': 'Eco (power-saving)', 'balanced': 'Balanced', 'max': 'Max Performance'}

def _resolve_effective_booster_settings(app: dict, global_settings: dict):
    override = (app or {}).get('booster_profile', 'inherit')
    if override == 'off':
        return None
    if not override or override == 'inherit':
        return global_settings
    preset = _BOOSTER_PROFILES.get(override)
    if not preset:
        return global_settings
    merged = dict(global_settings)
    merged.update(preset)
    return merged

class _GameBooster(QObject):
    stats_ready = pyqtSignal(str)
    _PERIODIC_TRIM_INTERVAL_MS = 10 * 60 * 1000

    def __init__(self):
        super().__init__()
        self._active = False
        self._prev_power_guid = None
        self._prev_core_parking_pct = None
        self._prev_gamedvr_enabled = None
        self._prev_toast_enabled = None
        self._closed_app_paths = []
        self._stopped_services = []
        self._last_summary = []
        self._periodic_game_pid = None
        self._periodic_timer = QTimer(self)
        self._periodic_timer.timeout.connect(self._periodic_trim_tick)

    @staticmethod
    def is_game_excluded(exe_path: str, settings: dict) -> bool:
        excluded = settings.get('booster_excluded_games', DEFAULT_SETTINGS['booster_excluded_games'])
        if not excluded or not exe_path:
            return False
        names = {n.strip().lower() for n in excluded.split(',') if n.strip()}
        return os.path.basename(exe_path).lower() in names

    def get_last_summary_text(self) -> str:
        return '\n'.join(self._last_summary) if self._last_summary else 'No game has been launched with Game Booster yet.'

    def recover_from_crash(self):
        state = _load_booster_state()
        if not state:
            return
        try:
            guid = state.get('prev_power_guid')
            if guid:
                _set_power_plan(guid)
            pct = state.get('prev_core_parking_pct')
            if pct is not None:
                _set_core_parking_min_cores(pct)
            prev_dvr = state.get('prev_gamedvr_enabled')
            if prev_dvr is not None:
                _set_game_dvr_enabled(prev_dvr)
            prev_toast = state.get('prev_toast_enabled')
            if prev_toast is not None:
                _set_toast_notifications_enabled(prev_toast)
            paths = state.get('closed_app_paths') or []
            if paths:
                _relaunch_closed_apps(paths)
            for svc in state.get('stopped_services') or []:
                _service_control(svc, 'start')
        except Exception as e:
            pass
        finally:
            _clear_booster_state()

    def _persist_state(self):
        _save_booster_state({'prev_power_guid': self._prev_power_guid, 'prev_core_parking_pct': self._prev_core_parking_pct, 'prev_gamedvr_enabled': self._prev_gamedvr_enabled, 'prev_toast_enabled': self._prev_toast_enabled, 'closed_app_paths': self._closed_app_paths, 'stopped_services': self._stopped_services})

    def boost(self, game_pid: int, settings: dict):
        if self._active:
            return
        self._active = True
        self._prev_power_guid = None
        self._prev_core_parking_pct = None
        self._prev_gamedvr_enabled = None
        self._prev_toast_enabled = None
        self._closed_app_paths = []
        self._stopped_services = []
        self._last_summary = []

        def _mark(applied: bool, label: str):
            self._last_summary.append(('✅ ' if applied else '⏭️ ') + label)
        battery_limited = False
        if settings.get('booster_battery_aware', DEFAULT_SETTINGS['booster_battery_aware']):
            pw = _get_power_status()
            if pw and pw.get('is_laptop') and pw.get('on_battery'):
                pct = pw.get('battery_percent')
                if pct is None or pct < _BOOSTER_LOW_BATTERY_THRESHOLD:
                    battery_limited = True
                    _mark(True, 'On battery with low charge — power-hungry settings (power plan/Core Parking) skipped')
        if settings.get('booster_power_plan', DEFAULT_SETTINGS['booster_power_plan']) and (not battery_limited):
            guid = _get_active_power_scheme_guid()
            if guid and guid.lower() != _POWER_PLAN_HIGH_PERFORMANCE_GUID.lower():
                if _set_power_plan(_POWER_PLAN_HIGH_PERFORMANCE_GUID):
                    self._prev_power_guid = guid
                    _mark(True, "Power plan set to 'High performance'")
                else:
                    _mark(False, 'Setting the power plan failed')
            else:
                _mark(True, "Power plan was already set to 'High performance'")
        if settings.get('booster_core_parking_off', DEFAULT_SETTINGS['booster_core_parking_off']) and (not battery_limited):
            cur = _get_power_setting_value(_POWERCFG_SUB_PROCESSOR, _POWERCFG_CORE_PARKING_MIN_CORES)
            if cur is not None and cur != 100:
                if _set_core_parking_min_cores(100):
                    self._prev_core_parking_pct = cur
                    _mark(True, 'Core Parking turned off')
            else:
                _mark(cur is not None, 'Core Parking could not be read/changed')
        priority_enabled = settings.get('booster_process_priority_enabled', DEFAULT_SETTINGS['booster_process_priority_enabled'])
        legacy_priority = settings.get('booster_high_priority', DEFAULT_SETTINGS['booster_high_priority'])
        if priority_enabled or legacy_priority:
            mode = settings.get('booster_priority_mode', DEFAULT_SETTINGS['booster_priority_mode'])
            if mode == 'high' and (not settings.get('booster_allow_high_priority', DEFAULT_SETTINGS['booster_allow_high_priority'])):
                mode = 'above_normal'
            ok = _set_process_priority_safe(game_pid, mode, allow_high=bool(settings.get('booster_allow_high_priority', DEFAULT_SETTINGS['booster_allow_high_priority'])))
            if ok:
                pass
            _mark(ok, f'Game process priority: {mode}')
        if settings.get('booster_affinity_pcores', DEFAULT_SETTINGS['booster_affinity_pcores']):
            mask = _get_p_core_affinity_mask()
            ok = bool(mask) and _set_process_affinity(game_pid, mask)
            if ok:
                pass
            _mark(ok, 'Pinned to Performance cores')
        if settings.get('booster_disable_gamedvr', DEFAULT_SETTINGS['booster_disable_gamedvr']):
            prev = _get_game_dvr_enabled()
            ok = _set_game_dvr_enabled(False)
            if ok:
                self._prev_gamedvr_enabled = True if prev is None else prev
            _mark(ok, 'Game DVR disabled')
            # Separate hook from GameDVR above: this is what actually pops
            # the Game Bar overlay when the PS button (mapped to XI_GUIDE)
            # is pressed on our virtual Xbox pad. Toggled off/on alongside
            # GameDVR since both are "don't let Windows intercept the
            # controller during a game" and restored on exit the same way.
            self._prev_gamebar_ctrl_enabled = True
            _set_gamebar_controller_button_enabled(False)
        if settings.get('booster_suppress_notifications', DEFAULT_SETTINGS['booster_suppress_notifications']):
            prev = _get_toast_notifications_enabled()
            ok = _set_toast_notifications_enabled(False)
            if ok:
                self._prev_toast_enabled = True if prev is None else prev
            _mark(ok, 'Windows notifications temporarily suppressed')
        if settings.get('booster_nvidia_perf_mode', DEFAULT_SETTINGS['booster_nvidia_perf_mode']):
            ok = _nvidia_set_persistence_mode(True)
            _mark(ok, 'NVIDIA Persistence Mode enabled')
        if settings.get('booster_stop_services', DEFAULT_SETTINGS['booster_stop_services']):
            for svc in _BOOSTER_STOPPABLE_SERVICES:
                if _service_control(svc, 'stop'):
                    self._stopped_services.append(svc)
            if self._stopped_services:
                pass
            _mark(bool(self._stopped_services), f'{len(self._stopped_services)} Windows service(s) stopped')
        self._persist_state()
        if settings.get('booster_trim_ram', DEFAULT_SETTINGS['booster_trim_ram']):
            before_mb = _get_available_memory_mb()

            def _do_trim():
                n = _trim_background_memory({game_pid, os.getpid()})
                _purge_standby_memory()
                after_mb = _get_available_memory_mb()
                if before_mb is not None and after_mb is not None and (after_mb > before_mb):
                    freed = after_mb - before_mb
                    self.stats_ready.emit(f'🚀 Game Booster active — about {freed} MB of RAM freed')
                else:
                    self.stats_ready.emit('🚀 Game Booster active')
            threading.Thread(target=_do_trim, daemon=True).start()
            self._periodic_game_pid = game_pid
            self._periodic_timer.start(self._PERIODIC_TRIM_INTERVAL_MS)
            _mark(True, 'Periodic RAM cleanup enabled — every 10 minutes')

    def _periodic_trim_tick(self):
        pid = self._periodic_game_pid
        if not pid or not self._active:
            self._periodic_timer.stop()
            return

        def _do():
            _trim_background_memory({pid, os.getpid()})
            _purge_standby_memory()
        threading.Thread(target=_do, daemon=True).start()

    def restore(self):
        if not self._active:
            return
        self._active = False
        self._periodic_timer.stop()
        self._periodic_game_pid = None
        if self._prev_power_guid:
            _set_power_plan(self._prev_power_guid)
            self._prev_power_guid = None
        if self._prev_core_parking_pct is not None:
            _set_core_parking_min_cores(self._prev_core_parking_pct)
            self._prev_core_parking_pct = None
        if self._prev_gamedvr_enabled is not None:
            _set_game_dvr_enabled(self._prev_gamedvr_enabled)
            self._prev_gamedvr_enabled = None
        if getattr(self, '_prev_gamebar_ctrl_enabled', None) is not None:
            _set_gamebar_controller_button_enabled(self._prev_gamebar_ctrl_enabled)
            self._prev_gamebar_ctrl_enabled = None
        if self._prev_toast_enabled is not None:
            _set_toast_notifications_enabled(self._prev_toast_enabled)
            self._prev_toast_enabled = None
        if self._closed_app_paths:
            _relaunch_closed_apps(self._closed_app_paths)
            self._closed_app_paths = []
        if self._stopped_services:
            for svc in self._stopped_services:
                _service_control(svc, 'start')
            self._stopped_services = []
        _clear_booster_state()

class _RECT(ctypes.Structure):
    _fields_ = [('left', ctypes.c_long), ('top', ctypes.c_long), ('right', ctypes.c_long), ('bottom', ctypes.c_long)]

class _MONITORINFO(ctypes.Structure):
    _fields_ = [('cbSize', wintypes.DWORD), ('rcMonitor', _RECT), ('rcWork', _RECT), ('dwFlags', wintypes.DWORD)]
_MONITOR_DEFAULTTONEAREST = 2
_PROCESS_QUERY_LIMITED_INFO = 4096
if os.name == 'nt':
    _WNDENUMPROC = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)
    _USER32_DLL.EnumWindows.argtypes = [_WNDENUMPROC, wintypes.LPARAM]
    _USER32_DLL.GetWindowThreadProcessId.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.DWORD)]
    _USER32_DLL.GetWindowThreadProcessId.restype = wintypes.DWORD
    _USER32_DLL.GetWindowRect.argtypes = [wintypes.HWND, ctypes.POINTER(_RECT)]
    _USER32_DLL.GetWindowRect.restype = wintypes.BOOL
    _USER32_DLL.MonitorFromWindow.argtypes = [wintypes.HWND, wintypes.DWORD]
    _USER32_DLL.MonitorFromWindow.restype = wintypes.HANDLE
    _USER32_DLL.GetMonitorInfoW.argtypes = [wintypes.HANDLE, ctypes.POINTER(_MONITORINFO)]
    _USER32_DLL.GetMonitorInfoW.restype = wintypes.BOOL
    _USER32_DLL.IsWindowVisible.argtypes = [wintypes.HWND]
    _USER32_DLL.IsWindowVisible.restype = wintypes.BOOL
    _USER32_DLL.IsIconic.argtypes = [wintypes.HWND]
    _USER32_DLL.IsIconic.restype = wintypes.BOOL
    _USER32_DLL.ShowWindow.argtypes = [wintypes.HWND, ctypes.c_int]
    _USER32_DLL.ShowWindow.restype = wintypes.BOOL
    _USER32_DLL.SetForegroundWindow.argtypes = [wintypes.HWND]
    _USER32_DLL.SetForegroundWindow.restype = wintypes.BOOL
    _KERNEL32_DLL.QueryFullProcessImageNameW.argtypes = [wintypes.HANDLE, wintypes.DWORD, wintypes.LPWSTR, ctypes.POINTER(wintypes.DWORD)]
    _KERNEL32_DLL.QueryFullProcessImageNameW.restype = wintypes.BOOL
    _KERNEL32_DLL.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
    _KERNEL32_DLL.OpenProcess.restype = wintypes.HANDLE
    _KERNEL32_DLL.GetCurrentProcessId.restype = wintypes.DWORD
else:
    _WNDENUMPROC = None

def _process_image_name(pid: int) -> str:
    h = _KERNEL32_DLL.OpenProcess(_PROCESS_QUERY_LIMITED_INFO, False, pid)
    if not h:
        return ''
    try:
        buf = ctypes.create_unicode_buffer(260)
        size = wintypes.DWORD(260)
        if _KERNEL32_DLL.QueryFullProcessImageNameW(h, 0, buf, ctypes.byref(size)):
            return buf.value
        return ''
    finally:
        _KERNEL32_DLL.CloseHandle(h)
_SELF_PID = _KERNEL32_DLL.GetCurrentProcessId() if os.name == 'nt' else os.getpid()
_SHELL_PROCESS_NAMES = {'explorer.exe', 'dwm.exe', 'applicationframehost.exe', 'shellexperiencehost.exe', 'searchhost.exe', 'textinputhost.exe', 'startmenuexperiencehost.exe', 'systemsettings.exe', 'lockapp.exe', 'xboxgamebarwidgets.exe', 'gamebar.exe', 'gamebarftserver.exe', 'gamebarpresencewriter.exe', 'cmd.exe', 'conhost.exe', 'powershell.exe', 'powershell_ise.exe', 'wscript.exe', 'cscript.exe'}

def _rect_area(r) -> int:
    return max(0, r.right - r.left) * max(0, r.bottom - r.top)

def _rect_covers(win_rect, ref_rect, threshold: float=0.9) -> bool:
    ix1, iy1 = (max(win_rect.left, ref_rect.left), max(win_rect.top, ref_rect.top))
    ix2, iy2 = (min(win_rect.right, ref_rect.right), min(win_rect.bottom, ref_rect.bottom))
    inter = max(0, ix2 - ix1) * max(0, iy2 - iy1)
    ref_area = _rect_area(ref_rect)
    return ref_area > 0 and inter / ref_area >= threshold

def _is_helper_process_pid(pid: int) -> bool:
    """True for PIDs that belong to this launcher's own helper processes
    (itself, or the FPS overlay worker) rather than to anything the user
    launched. The FPS overlay is a separate always-on-top process spawned
    from this same executable (--fps-overlay-worker), so without this
    check its own window can get mistaken by the fallback "which window
    is the game" matching below for the game window itself -- especially
    right after launch, before the real game window has appeared yet.
    That misidentification then latches onto the overlay's PID for
    "is the game still running" checks, which never goes false while the
    overlay is alive -- a deadlock where neither the overlay nor the
    game-exit handoff ever completes."""
    if not pid:
        return True
    if pid == _SELF_PID:
        return True
    overlay_proc = globals().get('_FPS_OVERLAY_PROC')
    overlay_pid = getattr(overlay_proc, 'pid', None) if overlay_proc is not None else None
    return bool(overlay_pid) and pid == overlay_pid

def _find_fullscreen_window_for_exe(exe_basename: str, match_out: dict=None, min_start_time: float=None) -> bool:
    target = (exe_basename or '').lower()
    result = {'named': False, 'fallback': False, 'name': None, 'pid': None}

    def _enum(hwnd, _lparam):
        if not _USER32_DLL.IsWindowVisible(hwnd) or _USER32_DLL.IsIconic(hwnd):
            return True
        pid = wintypes.DWORD(0)
        _USER32_DLL.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        if _is_helper_process_pid(pid.value):
            return True
        rect = _RECT()
        if not _USER32_DLL.GetWindowRect(hwnd, ctypes.byref(rect)):
            return True
        mon = _USER32_DLL.MonitorFromWindow(hwnd, _MONITOR_DEFAULTTONEAREST)
        if not mon:
            return True
        mi = _MONITORINFO()
        mi.cbSize = ctypes.sizeof(_MONITORINFO)
        if not _USER32_DLL.GetMonitorInfoW(mon, ctypes.byref(mi)):
            return True
        if not (_rect_covers(rect, mi.rcMonitor) or _rect_covers(rect, mi.rcWork)):
            return True
        name = _process_image_name(pid.value)
        base = os.path.basename(name).lower() if name else ''
        if target and base == target:
            result['named'] = True
            result['name'], result['pid'] = (base, pid.value)
            return False
        if base and base not in _SHELL_PROCESS_NAMES and (not _is_lossless_scaling_image_name(base)):
            if min_start_time is not None:
                started = _process_start_time(pid.value)
                if started is not None and started < min_start_time - 2.0:
                    return True
            result['fallback'] = True
            result['name'], result['pid'] = (base, pid.value)
        return True
    try:
        _USER32_DLL.EnumWindows(_WNDENUMPROC(_enum), 0)
    except Exception as e:
        pass
    if match_out is not None and (result['named'] or result['fallback']):
        match_out['name'] = result['name']
        match_out['pid'] = result['pid']
    return result['named'] or result['fallback']

def _find_any_visible_window_for_exe(exe_basename: str, match_out: dict=None) -> bool:
    """Like _find_fullscreen_window_for_exe, but does NOT require the window
    to cover the whole monitor. Some games (e.g. Unity titles) show a small
    windowed settings/config dialog -- resolution, graphics quality, monitor
    picker -- before the real (often fullscreen) game window appears. That
    dialog never satisfies the fullscreen check, so without this we'd keep
    the always-on-top loading overlay up over it, blocking the user from
    clicking anything in it until the launch timeout elapses."""
    target = (exe_basename or '').lower()
    result = {'found': False, 'name': None, 'pid': None}

    def _enum(hwnd, _lparam):
        if not _USER32_DLL.IsWindowVisible(hwnd) or _USER32_DLL.IsIconic(hwnd):
            return True
        pid = wintypes.DWORD(0)
        _USER32_DLL.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        if _is_helper_process_pid(pid.value):
            return True
        name = _process_image_name(pid.value)
        base = os.path.basename(name).lower() if name else ''
        if _is_lossless_scaling_image_name(base):
            return True
        if target and base == target:
            result['found'] = True
            result['name'], result['pid'] = (base, pid.value)
            return False
        return True
    try:
        _USER32_DLL.EnumWindows(_WNDENUMPROC(_enum), 0)
    except Exception:
        pass
    if match_out is not None and result['found']:
        match_out['name'] = result['name']
        match_out['pid'] = result['pid']
    return result['found']

_SW_MINIMIZE = 6
_SW_RESTORE = 9


def _find_window_hwnd_for_exe(exe_basename: str):
    """Returns the HWND of the first visible top-level window belonging
    to a process named exe_basename, or None. Used by the PS/Home
    minimize-to-launcher toggle to find the running game's window so it
    can be minimized/restored without needing a stored window handle
    from launch time (the game may have created/replaced its window
    since launch, e.g. after a menu/settings screen)."""
    target = (exe_basename or '').lower()
    result = {'hwnd': None}

    def _enum(hwnd, _lparam):
        if not _USER32_DLL.IsWindowVisible(hwnd):
            return True
        pid = wintypes.DWORD(0)
        _USER32_DLL.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        if _is_helper_process_pid(pid.value):
            return True
        name = _process_image_name(pid.value)
        base = os.path.basename(name).lower() if name else ''
        if target and base == target:
            result['hwnd'] = hwnd
            return False
        return True
    try:
        _USER32_DLL.EnumWindows(_WNDENUMPROC(_enum), 0)
    except Exception:
        pass
    return result['hwnd']


_SW_MAXIMIZE = 3


def _win32_force_foreground(hwnd) -> bool:
    """Standalone equivalent of PS5Launcher._win32_claim_foreground() (see
    the long comment on that method) that works on ANY window handle, not
    just the launcher's own -- used to force the actual GAME window to
    the front. Plain SetForegroundWindow() is silently refused by Windows
    unless the calling thread's process was the one that most recently
    received direct user input; by the time our loading overlay closes
    (or the FPS overlay -- itself a separate always-on-top process --
    has grabbed z-order), that's no longer us, so the plain call is a
    no-op. This uses the standard AttachThreadInput trick: temporarily
    share an input queue with whichever thread currently owns the
    foreground window, which makes Windows treat our thread as equally
    eligible, then detach again right after."""
    if not hwnd:
        return False
    user32 = _USER32_DLL
    kernel32 = _KERNEL32_DLL
    attached = False
    fg_thread = 0
    cur_thread = kernel32.GetCurrentThreadId()
    try:
        fg_hwnd = user32.GetForegroundWindow()
        if fg_hwnd and fg_hwnd != hwnd:
            fg_pid = wintypes.DWORD(0)
            fg_thread = user32.GetWindowThreadProcessId(fg_hwnd, ctypes.byref(fg_pid))
            if fg_thread and fg_thread != cur_thread:
                attached = bool(user32.AttachThreadInput(cur_thread, fg_thread, True))
        if user32.IsIconic(hwnd):
            user32.ShowWindow(hwnd, _SW_RESTORE)
        user32.BringWindowToTop(hwnd)
        return bool(user32.SetForegroundWindow(hwnd))
    except Exception:
        return False
    finally:
        if attached:
            try:
                user32.AttachThreadInput(cur_thread, fg_thread, False)
            except Exception:
                pass


def _force_game_to_front(exe_basename: str, maximize: bool=True) -> bool:
    """Forces the running game's window to the absolute front (and
    maximized, by default) even over the launcher and a topmost FPS
    overlay window. Nothing in the launch-handoff path used to do this at
    all -- _handle_launch_handoff/_finish_launch_overlay only ever closed
    the loading overlay and assumed Windows would naturally hand focus to
    the game, which it doesn't reliably do once another always-on-top
    window (our own overlay, or the FPS overlay) was the last thing
    holding foreground/topmost. See _win32_force_foreground()."""
    if os.name != 'nt':
        return False
    hwnd = _find_window_hwnd_for_exe(exe_basename)
    if not hwnd:
        return False
    try:
        _USER32_DLL.ShowWindow(hwnd, _SW_MAXIMIZE if maximize else _SW_RESTORE)
    except Exception:
        pass
    return _win32_force_foreground(hwnd)


def _minimize_window_for_exe(exe_basename: str) -> bool:
    if os.name != 'nt':
        return False
    hwnd = _find_window_hwnd_for_exe(exe_basename)
    if not hwnd:
        return False
    try:
        _USER32_DLL.ShowWindow(hwnd, _SW_MINIMIZE)
        return True
    except Exception:
        return False


def _restore_window_for_exe(exe_basename: str) -> bool:
    if os.name != 'nt':
        return False
    hwnd = _find_window_hwnd_for_exe(exe_basename)
    if not hwnd:
        return False
    try:
        _USER32_DLL.ShowWindow(hwnd, _SW_RESTORE)
        return _win32_force_foreground(hwnd)
    except Exception:
        return False


def _find_any_foreground_window(exclude_names: set=None, min_start_time: float=None):
    exclude = {n.lower() for n in exclude_names or ()}
    result = {'name': None, 'pid': None}

    def _enum(hwnd, _lparam):
        if not _USER32_DLL.IsWindowVisible(hwnd) or _USER32_DLL.IsIconic(hwnd):
            return True
        pid = wintypes.DWORD(0)
        _USER32_DLL.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        if _is_helper_process_pid(pid.value):
            return True
        name = _process_image_name(pid.value)
        base = os.path.basename(name).lower() if name else ''
        if not base or base in _SHELL_PROCESS_NAMES or base in exclude or _is_lossless_scaling_image_name(base):
            return True
        if min_start_time is not None:
            started = _process_start_time(pid.value)
            if started is not None and started < min_start_time - 2.0:
                return True
        result['name'], result['pid'] = (base, pid.value)
        return False
    try:
        _USER32_DLL.EnumWindows(_WNDENUMPROC(_enum), 0)
    except Exception as e:
        pass
    return (result['name'], result['pid'])
_KERNEL32_DLL.GetExitCodeProcess.argtypes = [wintypes.HANDLE, ctypes.POINTER(wintypes.DWORD)]
_KERNEL32_DLL.GetExitCodeProcess.restype = wintypes.BOOL
_STILL_ACTIVE = 259

def _pid_alive(pid: int) -> bool:
    if not pid:
        return False
    h = _KERNEL32_DLL.OpenProcess(_PROCESS_QUERY_LIMITED_INFO, False, pid)
    if not h:
        return False
    try:
        code = wintypes.DWORD(0)
        if _KERNEL32_DLL.GetExitCodeProcess(h, ctypes.byref(code)):
            return code.value == _STILL_ACTIVE
        return True
    finally:
        _KERNEL32_DLL.CloseHandle(h)
_KERNEL32_DLL.GetProcessTimes.argtypes = [wintypes.HANDLE, ctypes.POINTER(wintypes.FILETIME), ctypes.POINTER(wintypes.FILETIME), ctypes.POINTER(wintypes.FILETIME), ctypes.POINTER(wintypes.FILETIME)]
_KERNEL32_DLL.GetProcessTimes.restype = wintypes.BOOL
_FILETIME_EPOCH_OFFSET_SEC = 11644473600

def _process_start_time(pid: int) -> 'float | None':
    if not pid:
        return None
    h = _KERNEL32_DLL.OpenProcess(_PROCESS_QUERY_LIMITED_INFO, False, pid)
    if not h:
        return None
    try:
        creation = wintypes.FILETIME()
        exit_t = wintypes.FILETIME()
        kernel_t = wintypes.FILETIME()
        user_t = wintypes.FILETIME()
        if not _KERNEL32_DLL.GetProcessTimes(h, ctypes.byref(creation), ctypes.byref(exit_t), ctypes.byref(kernel_t), ctypes.byref(user_t)):
            return None
        ft_100ns = creation.dwHighDateTime << 32 | creation.dwLowDateTime
        if ft_100ns == 0:
            return None
        return ft_100ns / 10000000.0 - _FILETIME_EPOCH_OFFSET_SEC
    except Exception:
        return None
    finally:
        _KERNEL32_DLL.CloseHandle(h)

def _game_window_present(exe_basename: str, target_pid: int=None) -> bool:
    target = (exe_basename or '').lower()
    result = {'hit': False}

    def _enum(hwnd, _lparam):
        if not _USER32_DLL.IsWindowVisible(hwnd):
            return True
        pid = wintypes.DWORD(0)
        _USER32_DLL.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        if _is_helper_process_pid(pid.value):
            return True
        if target_pid:
            if pid.value == target_pid:
                result['hit'] = True
                return False
            return True
        name = _process_image_name(pid.value)
        base = os.path.basename(name).lower() if name else ''
        if _is_lossless_scaling_image_name(base):
            return True
        if target and base == target:
            result['hit'] = True
            return False
        return True
    try:
        _USER32_DLL.EnumWindows(_WNDENUMPROC(_enum), 0)
    except Exception as e:
        pass
    return result['hit']

class LaunchOverlay(QWidget):

    def __init__(self, app_data: dict, parent=None):
        super().__init__(parent)
        self.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowStaysOnTopHint)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setWindowOpacity(0.0)
        self.showFullScreen()
        self._title = app_data.get('title', '')
        bg_path = app_data.get('background', '')
        if bg_path and os.path.exists(bg_path):
            self._bg_pix = QPixmap.fromImage(_decode_image_any_format(bg_path))
        else:
            self._bg_pix = QPixmap()
        self._bounce_t = 0.0
        self._anim_timer = QTimer(self)
        self._anim_timer.timeout.connect(self._tick)
        self._anim_timer.start(16)
        self._fade_in_anim = QPropertyAnimation(self, b'windowOpacity', self)
        self._fade_in_anim.setDuration(600)
        self._fade_in_anim.setStartValue(0.0)
        self._fade_in_anim.setEndValue(1.0)
        self._fade_in_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._fade_in_anim.start()

    def _tick(self):
        self._bounce_t += 0.08
        self.update()

    def close_overlay(self):
        self._anim_timer.stop()
        if hasattr(self, '_fade_in_anim'):
            self._fade_in_anim.stop()
        fade_out = QPropertyAnimation(self, b'windowOpacity', self)
        fade_out.setDuration(400)
        fade_out.setStartValue(self.windowOpacity())
        fade_out.setEndValue(0.0)
        fade_out.setEasingCurve(QEasingCurve.Type.InCubic)
        fade_out.finished.connect(self.close)
        fade_out.start(QPropertyAnimation.DeletionPolicy.DeleteWhenStopped)

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        w, h = (self.width(), self.height())
        if not self._bg_pix.isNull():
            scaled = self._bg_pix.scaled(w, h, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
            ox = (scaled.width() - w) // 2
            oy = (scaled.height() - h) // 2
            p.drawPixmap(0, 0, scaled, ox, oy, w, h)
        else:
            p.fillRect(0, 0, w, h, QColor(2, 2, 10))
        p.end()

def _sync_module_settings_from_data(data: dict):
    global MAX_BG_WORKERS, BG_CACHE_TTL_DAYS, GRAPHICS_QUALITY
    settings = data.get('settings', {})
    _set_bg_fit_mode(settings.get('bg_fit_mode', DEFAULT_SETTINGS['bg_fit_mode']))
    _set_enabled_sources(settings.get('enabled_sources', list(_DEFAULT_ENABLED_SOURCES)))
    _set_steamgriddb_api_key(settings.get('steamgriddb_api_key', DEFAULT_SETTINGS['steamgriddb_api_key']))
    _set_igdb_credentials(settings.get('igdb_client_id', DEFAULT_SETTINGS['igdb_client_id']), settings.get('igdb_client_secret', DEFAULT_SETTINGS['igdb_client_secret']))
    _set_rawg_api_key(settings.get('rawg_api_key', DEFAULT_SETTINGS['rawg_api_key']))
    if 'max_bg_workers' in settings:
        MAX_BG_WORKERS = int(settings['max_bg_workers'])
    if 'bg_cache_ttl_days' in settings:
        BG_CACHE_TTL_DAYS = int(settings['bg_cache_ttl_days'])
    _set_cache_memory_limit_mb(settings.get('cache_memory_limit_mb', DEFAULT_SETTINGS['cache_memory_limit_mb']))
    quality = str(settings.get('graphics_quality', DEFAULT_SETTINGS['graphics_quality'])).lower()
    GRAPHICS_QUALITY = quality if quality in {'performance', 'balanced', 'quality'} else 'balanced'
    _start_title_map_auto_update_thread(interval_days=float(settings.get('title_db_update_interval_days', DEFAULT_SETTINGS['title_db_update_interval_days'])), enabled=bool(settings.get('title_db_auto_update_enabled', DEFAULT_SETTINGS['title_db_auto_update_enabled'])))

class PadBatteryIndicator(QWidget):
    _COLOR_FILL = QColor(255, 255, 255, 235)
    _H = 20
    _IDX_W = 13
    _GAP = 5
    _BODY_W = 35
    _BODY_H = 15
    _NUB_W = 3
    _NUB_H = 8
    _RADIUS = 4

    def __init__(self, idx: int, pct: int=100, charging: bool=False, parent=None):
        super().__init__(parent)
        self._idx = idx
        self._pct = pct
        self._charging = charging
        self._blink_on = True
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        total_w = self._IDX_W + self._GAP + self._BODY_W + self._NUB_W + 1
        self.setFixedSize(total_w, self._H)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        self._blink_timer = QTimer(self)
        self._blink_timer.setInterval(500)
        self._blink_timer.timeout.connect(self._blink_tick)
        self._apply(pct)

    def set_level(self, pct: int, charging: bool=False):
        if pct == self._pct and charging == self._charging:
            return
        self._pct = pct
        self._charging = charging
        self._apply(pct)

    def _apply(self, pct: int):
        if pct <= 5:
            if not self._blink_timer.isActive():
                self._blink_on = True
                self._blink_timer.start()
        else:
            self._blink_timer.stop()
            self._blink_on = True
        self.update()

    def _blink_tick(self):
        self._blink_on = not self._blink_on
        self.update()

    def paintEvent(self, event):
        pct = max(0, min(100, self._pct))
        color = self._COLOR_FILL
        critical = pct <= 5
        show_fill = not critical or self._blink_on
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setFont(QFont('Segoe UI', 8, QFont.Weight.Bold))
        p.setPen(QColor(220, 225, 255, 210))
        idx_rect = QRect(0, 0, self._IDX_W, self._H)
        p.drawText(idx_rect, int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight), str(self._idx))
        body_x = self._IDX_W + self._GAP
        body_y = (self._H - self._BODY_H) // 2
        body = QRect(body_x, body_y, self._BODY_W, self._BODY_H)
        p.setPen(QPen(QColor(255, 255, 255, 160), 1.3))
        p.setBrush(QBrush(QColor(255, 255, 255, 110)))
        p.drawRoundedRect(body, self._RADIUS, self._RADIUS)
        nub = QRect(body_x + self._BODY_W, body_y + (self._BODY_H - self._NUB_H) // 2, self._NUB_W, self._NUB_H)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(QColor(255, 255, 255, 100)))
        p.drawRoundedRect(nub, 1, 1)
        if show_fill:
            pad = 2
            inner_w = self._BODY_W - pad * 2
            inner_h = self._BODY_H - pad * 2
            fill_w = max(0, round(inner_w * pct / 100))
            if fill_w > 0:
                fill_rect = QRect(body_x + pad, body_y + pad, fill_w, inner_h)
                fr = max(1, min(self._RADIUS - 1, inner_h // 2))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QBrush(color))
                p.drawRoundedRect(fill_rect, fr, fr)
        p.setFont(QFont('Segoe UI', 8, QFont.Weight.ExtraBold))
        text = str(pct)
        fm = QFontMetrics(p.font())
        text_w = fm.horizontalAdvance(text)
        if self._charging:
            bolt_w, bolt_h = (6, 11)
            bolt_gap = 2
            block_w = bolt_w + bolt_gap + text_w
            block_x = body.x() + (body.width() - block_w) // 2
            bolt_rect = QRect(block_x, body_y + (self._BODY_H - bolt_h) // 2, bolt_w, bolt_h)
            bolt = QPainterPath()
            bolt.moveTo(bolt_rect.x() + bolt_rect.width() * 0.62, bolt_rect.y())
            bolt.lineTo(bolt_rect.x(), bolt_rect.y() + bolt_rect.height() * 0.58)
            bolt.lineTo(bolt_rect.x() + bolt_rect.width() * 0.42, bolt_rect.y() + bolt_rect.height() * 0.58)
            bolt.lineTo(bolt_rect.x() + bolt_rect.width() * 0.38, bolt_rect.y() + bolt_rect.height())
            bolt.lineTo(bolt_rect.x() + bolt_rect.width(), bolt_rect.y() + bolt_rect.height() * 0.42)
            bolt.lineTo(bolt_rect.x() + bolt_rect.width() * 0.58, bolt_rect.y() + bolt_rect.height() * 0.42)
            bolt.closeSubpath()
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(QColor(20, 20, 20, 235)))
            p.drawPath(bolt)
            text_x = block_x + bolt_w + bolt_gap
            text_rect = QRect(text_x, body.y(), text_w, body.height())
            p.setPen(QColor(20, 20, 20, 235))
            flags = int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft)
            p.drawText(text_rect, flags, text)
        else:
            p.setPen(QColor(20, 20, 20, 235))
            flags = int(Qt.AlignmentFlag.AlignCenter)
            p.drawText(body, flags, text)
        p.end()

class PadBatteryRow(QWidget):

    def __init__(self, idx: int, pct: int, charging: bool, on_power_off, parent=None):
        super().__init__(parent)
