class CrashReportDialog(_GlassDialogBase):

    def __init__(self, report_text: str, report_path: str, parent=None):
        super().__init__(parent)
        self._init_glass(min_width=700)
        self.setMinimumSize(700, 480)
        self.setStyleSheet('\n            QLabel { color:#dde0ff; }\n            QTextEdit { background:rgba(255,255,255,8); color:#c8cdff;\n                        border:1px solid rgba(255,255,255,45);\n                        border-radius:10px; font-family:Consolas, monospace;\n                        font-size:11px; padding:8px; }\n            QPushButton { background:rgba(255,255,255,28); color:#dde0ff;\n                          border:1px solid rgba(255,255,255,78);\n                          border-radius:10px; padding:8px 18px; font-size:12px; }\n            QPushButton:hover { background:rgba(255,255,255,48); color:#fff; }\n            QPushButton#close { background:rgba(255,255,255,8);\n                                border-color:rgba(255,255,255,34);\n                                color:rgba(180,190,230,180); }\n            QPushButton#close:hover { background:rgba(255,255,255,15);\n                                      color:#dde0ff; }\n        ')
        self._report_text = report_text
        self._report_path = report_path
        root = QVBoxLayout(self)
        root.setSpacing(10)
        root.setContentsMargins(22, 16, 22, 20)
        root.addWidget(self._make_header('Unexpected Error'))
        hdr = QLabel(f"An unexpected error occurred. The report below was saved automatically:\n<span style='color:#7070b0; font-size:11px'>{report_path}</span>")
        hdr.setTextFormat(Qt.TextFormat.RichText)
        hdr.setWordWrap(True)
        root.addWidget(hdr)
        txt = QTextEdit()
        txt.setReadOnly(True)
        txt.setPlainText(report_text)
        root.addWidget(txt, 1)
        btn_row = QHBoxLayout()
        btn_row.setSpacing(8)
        copy_btn = QPushButton('📋  Copy Report')
        copy_btn.setToolTip('Copy the crash report to clipboard')
        copy_btn.clicked.connect(self._copy_report)
        btn_row.addWidget(copy_btn)
        open_btn = QPushButton('📂  Open File')
        open_btn.setToolTip('Open the crash report file in Explorer')
        open_btn.clicked.connect(self._open_file)
        btn_row.addWidget(open_btn)
        btn_row.addStretch()
        close_btn = QPushButton('Close')
        close_btn.setObjectName('close')
        close_btn.setFixedHeight(40)
        close_btn.clicked.connect(self.accept)
        btn_row.addWidget(close_btn)
        root.addLayout(btn_row)

    def _copy_report(self):
        from PyQt6.QtWidgets import QApplication as _QApp
        _QApp.clipboard().setText(self._report_text)

    def _open_file(self):
        try:
            subprocess.Popen(['explorer', '/select,', os.path.abspath(self._report_path)])
        except Exception:
            pass

class CrashReporter:
    # Previously a path relative to the process's current working
    # directory -- which is NOT reliably the exe's own folder (it depends
    # on how the app was launched: a shortcut's "Start in" field, a
    # different launcher, etc.), so reports could silently land somewhere
    # other than where you'd think to look. Anchored under
    # %APPDATA%\PS5Launcher instead, matching where the app already keeps
    # its other state (deps_installed.flag, freeze_watchdog.log).
    @staticmethod
    def _default_crash_dir():
        return _LOG_DIR

    def __init__(self, qt_app):
        self._app = qt_app
        self.CRASH_DIR = self._default_crash_dir()
        os.makedirs(self.CRASH_DIR, exist_ok=True)
        sys.excepthook = self._excepthook
        # sys.excepthook only ever sees exceptions raised on the MAIN
        # thread. Exceptions raised inside threading.Thread/QThread
        # workers (image download, art fetch, preload, etc.) go to
        # threading.excepthook instead and were previously silently
        # dropped -- which is why crashes that happen while background
        # work (image downloads, preload) overlaps with navigation
        # produced no crash report at all. Route those here too.
        threading.excepthook = self._thread_excepthook

        # sys.excepthook / threading.excepthook only ever fire for a
        # genuine *Python* exception. A hard native fault -- an access
        # violation from a bad ctypes/WinAPI call (the controller HID
        # code does a lot of these), or Qt aborting the process because a
        # widget was touched off the GUI thread -- kills the process at
        # the OS level and NO Python code runs afterward, so neither hook
        # above ever gets a chance to write anything. faulthandler is the
        # one thing that can still catch that: on Windows it installs a
        # handler via SetUnhandledExceptionFilter that dumps the stack of
        # whichever thread actually faulted, straight to a file, right
        # before the process dies. Keep the file handle referenced on
        # self so it isn't garbage-collected/closed.
        try:
            import faulthandler
            _fl = os.path.join(self.CRASH_DIR, 'native_faults.log')
            try:
                if os.path.getsize(_fl) > 1024 * 1024:
                    os.replace(_fl, _fl + '.old')
            except OSError:
                pass
            self._fault_log_fh = open(_fl, 'a', encoding='utf-8', buffering=1)
            faulthandler.enable(file=self._fault_log_fh, all_threads=True)
            try:
                self._fault_log_fh.write('\n===== session start %s pid=%d =====\n' % (time.strftime('%Y-%m-%d %H:%M:%S'), os.getpid()))
            except Exception:
                pass
        except Exception:
            pass

    def _thread_excepthook(self, args):
        self._excepthook(args.exc_type, args.exc_value, args.exc_traceback)

    def _excepthook(self, exc_type, exc_value, exc_tb):
        if issubclass(exc_type, KeyboardInterrupt):
            sys.__excepthook__(exc_type, exc_value, exc_tb)
            return
        import traceback, platform, datetime
        ts = datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
        report_text = self._build_report(exc_type, exc_value, exc_tb, ts, platform)
        report_path = os.path.join(self.CRASH_DIR, f'crash_{ts}.txt')
        try:
            with open(report_path, 'w', encoding='utf-8') as fh:
                fh.write(report_text)
        except Exception as io_err:
            pass

        # Qt widgets may only be created/shown on the GUI (main) thread.
        # _thread_excepthook can call this from a background
        # threading.Thread, and building/exec-ing CrashReportDialog
        # directly there is undefined behavior in Qt -- it can itself
        # crash or hang the process, with the report above already
        # written but the dialog never appearing. Hop back onto the main
        # thread before touching any widget.
        def _show_dialog():
            try:
                dlg = CrashReportDialog(report_text, report_path)
                dlg.exec()
            except Exception as dlg_err:
                pass
        if threading.current_thread() is threading.main_thread():
            _show_dialog()
        else:
            try:
                QTimer.singleShot(0, _show_dialog)
            except Exception:
                pass

    @staticmethod
    def _build_report(exc_type, exc_value, exc_tb, ts, platform_mod) -> str:
        import traceback
        tb_lines = ''.join(traceback.format_tb(exc_tb))
        lines = ['=' * 70, 'PS5 Launcher — Crash Report', '=' * 70, f'Time      : {ts}', f'Platform  : {platform_mod.platform()}', f'Python    : {sys.version}', f'Executable: {sys.executable}', '', f'Exception : {exc_type.__name__}: {exc_value}', '', 'Traceback (most recent call last):', tb_lines.rstrip(), '', '=' * 70, 'If you want to report this bug, please attach this file.', '=' * 70]
        return '\n'.join(lines) + '\n'

class NavHapticCoordinator:

    def __init__(self, launcher: 'PS5Launcher'):
        self._launcher = launcher

    def tick(self, kind: str, context: str | None=None):
        launcher = self._launcher
        lc = getattr(launcher, '_led_ctrl', None)
        if lc is None:
            _haptic_failure('launcher haptic skipped context=%s reason=no_led_controller', context or kind)
            return
        s = launcher.data.get('settings', {})
        if kind == 'category':
            if not s.get('nav_category_haptic_enabled', DEFAULT_SETTINGS['nav_category_haptic_enabled']):
                _haptic_trace('launcher haptic disabled context=%s reason=settings', context or kind)
                return
            intensity = int(s.get('nav_category_haptic_intensity', DEFAULT_SETTINGS['nav_category_haptic_intensity']))
            duration_ms = int(s.get('nav_category_haptic_duration_ms', DEFAULT_SETTINGS['nav_category_haptic_duration_ms']))
        else:
            if not s.get('nav_list_haptic_enabled', DEFAULT_SETTINGS['nav_list_haptic_enabled']):
                _haptic_trace('launcher haptic disabled context=%s reason=settings', context or kind)
                return
            intensity = int(s.get('nav_list_haptic_intensity', DEFAULT_SETTINGS['nav_list_haptic_intensity']))
            duration_ms = int(s.get('nav_list_haptic_duration_ms', DEFAULT_SETTINGS['nav_list_haptic_duration_ms']))
        right = max(0, min(255, int(intensity * 0.7)))
        left = max(0, min(255, intensity))
        event_context = context or ('category' if kind == 'category' else 'list')
        target_title = 'unknown'
        try:
            if launcher.in_preview_row and launcher._preview_items:
                idx = max(0, min(launcher.preview_selected_col, len(launcher._preview_items) - 1))
                target_title = launcher._preview_items[idx].get('title', launcher._preview_items[idx].get('name', 'unknown'))
            elif launcher._all_items:
                idx = max(0, min(launcher.selected_col, len(launcher._all_items) - 1))
                _, target = launcher._all_items[idx]
                target_title = target if isinstance(target, str) else target.get('title', target.get('name', 'unknown'))
        except Exception:
            target_title = 'unknown'
        _haptic_trace('launcher haptic request context=%s target=%r intensity=%d duration=%dms', event_context, target_title, intensity, duration_ms)
        lc._nav_rumble_tick(right=right, left=left, duration_ms=duration_ms, context=event_context)

    def confirm(self):
        launcher = self._launcher
        lc = getattr(launcher, '_led_ctrl', None)
        if lc is None:
            return
        s = launcher.data.get('settings', {})
        if not s.get('confirm_haptic_enabled', DEFAULT_SETTINGS['confirm_haptic_enabled']):
            return
        intensity = int(s.get('confirm_haptic_intensity', DEFAULT_SETTINGS['confirm_haptic_intensity']))
        duration_ms = int(s.get('confirm_haptic_duration_ms', DEFAULT_SETTINGS['confirm_haptic_duration_ms']))
        lc._nav_rumble_tick(right=max(0, min(255, int(intensity * 0.5))), left=max(0, min(255, intensity)), duration_ms=duration_ms, context='confirm')

class GameCarousel(QWidget):
    gameClicked = pyqtSignal(int)
    gameEdit = pyqtSignal(int, str)
    gameSelected = pyqtSignal(int)
    carouselOffsetChanged = pyqtSignal()
    gameContextRequested = pyqtSignal(int)
    wheelNavigate = pyqtSignal(int)
    reorderRequested = pyqtSignal(int, int)
    _TILE_SEL = 200
    _RADIUS = 18
    _SPACING = 150
    _SCALE_PTS = [(0.0, 1.0), (1.0, 0.68), (2.0, 0.56), (3.0, 0.48), (4.0, 0.42), (100.0, 0.38)]
    _OPACITY_PTS = [(0.0, 1.0), (1.0, 0.75), (2.0, 0.6), (3.0, 0.48), (4.0, 0.4), (100.0, 0.34)]
    _MAX_VISIBLE = 1000
    _DRAG_THRESHOLD = 10

    def __init__(self, parent=None):
        super().__init__(parent)
        self._apps = []
        self._selected_idx = 0
        self._offset = 0.0
        self._slot_hitboxes = []
        self._anim = QPropertyAnimation(self, b'carousel_offset', self)
        self._anim.setDuration(320)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, False)
        self.setStyleSheet('background:transparent;')
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setMinimumHeight(self._TILE_SEL + 48)
        self._wheel_accum = 0
        self._wheel_pending_idx = None
        self._wheel_timer = QTimer(self)
        self._wheel_timer.setSingleShot(True)
        self._wheel_timer.timeout.connect(self._commit_wheel_navigation)
        # Mouse drag-to-reorder state. A press records a candidate tile and
        # position; a real drag is only entered once the mouse has moved
        # past _DRAG_THRESHOLD px (mirrors PS5GameTile's own click/drag
        # disambiguation), so ordinary taps/clicks are unaffected.
        self._press_idx = None
        self._press_pos = QPointF()
        self._dragging = False
        self._drag_pos = QPointF()
        self._drag_target_idx = None

    def _get_carousel_offset(self):
        return self._offset

    def _set_carousel_offset(self, v):
        self._offset = float(v)
        self.update()
        # The floating game name is a sibling of the carousel, not part of
        # its paint pass.  Keep it in lockstep with the offset animation.
        self.carouselOffsetChanged.emit()
    carousel_offset = pyqtProperty(float, _get_carousel_offset, _set_carousel_offset)

    def set_games(self, apps, selected_idx, animate=False):
        had_games = bool(self._apps)
        old_offset = self._offset
        self._apps = list(apps)
        new_idx = max(0, min(selected_idx, len(apps) - 1)) if apps else 0
        self._selected_idx = new_idx
        if animate and had_games and self._apps and (abs(old_offset - float(new_idx)) > 0.01):
            if self._anim.state() == QAbstractAnimation.State.Running:
                try:
                    if abs(float(self._anim.endValue()) - float(new_idx)) <= 0.01:
                        return
                except (TypeError, ValueError):
                    pass
            self._anim.stop()
            self._anim.setStartValue(old_offset)
            self._anim.setEndValue(float(new_idx))
            self._anim.start()
        else:
            self._anim.stop()
            self._set_carousel_offset(float(new_idx))

    def navigate_to(self, idx):
        if not self._apps:
            return
        new_idx = max(0, min(idx, len(self._apps) - 1))
        self._selected_idx = new_idx
        self._anim.stop()
        self._anim.setStartValue(self._offset)
        self._anim.setEndValue(float(new_idx))
        self._anim.start()
        self.gameSelected.emit(new_idx)

    def selected_index(self):
        return self._selected_idx

    def selected_tile_rect(self):
        rect = self.tile_rect_for_index(self._selected_idx)
        if rect is None:
            return QRect()
        return rect.toRect()

    def tile_rect_for_index(self, index):
        """Return the current painted rectangle for an item during animation."""
        if not self._apps or not (0 <= index < len(self._apps)):
            return None
        W, H = (self.width(), self.height())
        cx = self._TILE_SEL // 2 + 110
        cy = H / 2.0 - 55
        delta = index - self._offset
        ad = abs(delta)
        gap = max(-1.0, min(1.0, delta / 0.1)) * 12
        sign = 1.0 if delta >= 0 else -1.0
        x = cx + sign * self._cum_spacing(ad) + gap
        tile_size = int(round(self._TILE_SEL * self._falloff(ad, self._SCALE_PTS)))
        if tile_size < 6:
            return None
        main_t = max(0.0, min(1.0, 1.0 - ad / 0.3))
        tx = int(x - tile_size / 2)
        ty = int(cy - tile_size / 2) + int(round(30 * main_t))
        return QRectF(tx, ty, tile_size, tile_size)

    def visible_tile_rects(self):
        """Return the actual painted tile rectangles in carousel coordinates."""
        if not self._apps:
            return []
        W, H = (self.width(), self.height())
        cx = self._TILE_SEL // 2 + 110
        cy = H / 2.0 - 55
        sel_size = self._TILE_SEL
        gap = 12
        cull_half = sel_size / 2 + gap + 40
        rects = []
        for i in range(len(self._apps)):
            rect = self.tile_rect_for_index(i)
            if rect is None:
                continue
            if rect.right() + cull_half < 0 or rect.left() - cull_half > W:
                continue
            rects.append((rect, i))
        return rects

    @staticmethod
    def _falloff(ad, pts):
        if ad <= pts[0][0]:
            return pts[0][1]
        for (a0, v0), (a1, v1) in zip(pts, pts[1:]):
            if ad <= a1:
                if a1 == a0:
                    return v1
                return v0 + (v1 - v0) * (ad - a0) / (a1 - a0)
        return pts[-1][1]
    _GAP_STEP = 10

    @classmethod
    def _cum_spacing(cls, ad):
        pts = cls._SCALE_PTS
        total = 0.0
        for (a0, v0), (a1, v1) in zip(pts, pts[1:]):
            if ad <= a0:
                break
            seg_end = min(ad, a1)
            if seg_end <= a0:
                continue
            v_end = v0 + (v1 - v0) * (seg_end - a0) / (a1 - a0) if a1 != a0 else v0
            total += (v0 + v_end) / 2.0 * (seg_end - a0)
            if seg_end >= ad:
                break
        return total * cls._TILE_SEL + cls._GAP_STEP * ad

    def paintEvent(self, event):
        self._slot_hitboxes = []
        if not self._apps:
            return
        p = QPainter(self)
        try:
            if not p.isActive():
                return
            self._paint_tiles(p)
        finally:
            try:
                if p.isActive():
                    p.end()
            except Exception:
                pass

    def _paint_tiles(self, p):
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        W, H = (self.width(), self.height())
        cx = self._TILE_SEL // 2 + 110
        cy = H / 2.0 - 55
        n = len(self._apps)
        sel_size = self._TILE_SEL
        slots = []
        _GAP = 12
        _cull_half = sel_size / 2 + _GAP + 40
        for i, app in enumerate(self._apps):
            delta = i - self._offset
            ad = abs(delta)
            _GAP_RAMP = 0.1
            gap = max(-1.0, min(1.0, delta / _GAP_RAMP)) * _GAP
            sign = 1.0 if delta >= 0 else -1.0
            x = cx + sign * self._cum_spacing(ad) + gap
            if x + _cull_half < 0 or x - _cull_half > W:
                continue
            scale = self._falloff(ad, self._SCALE_PTS)
            opacity = self._falloff(ad, self._OPACITY_PTS)
            tile_sz = sel_size * scale
            slots.append((ad, i, app, scale, opacity, x, tile_sz))
        slots.sort(key=lambda s: -s[0])
        for ad, i, app, scale, opacity, x, tile_sz in slots:
            tile_sz = int(round(tile_sz))
            if tile_sz < 6:
                continue
            tile_sz = min(tile_sz, 2048)
            _MAIN_BLEND = 0.3
            main_t = max(0.0, min(1.0, 1.0 - ad / _MAIN_BLEND))
            tx = int(x - tile_sz / 2)
            ty = int(cy - tile_sz / 2) + int(round(30 * main_t))
            r = max(_CORNER_RADIUS_MIN, min(_CORNER_RADIUS_MAX, round(tile_sz * _CORNER_RADIUS_FRACTION)))
            p.setOpacity(max(0.0, min(1.0, opacity)))
            path = QPainterPath()
            path.addRoundedRect(tx, ty, tile_sz, tile_sz, r, r)
            if self._dragging and i == self._press_idx:
                # This tile is being dragged -- it's painted separately,
                # "lifted" and following the cursor, by _paint_dragged_tile
                # at the end of this method. Leave a faint empty-slot
                # outline behind so it's clear the slot is temporarily open.
                p.save()
                p.setPen(QPen(QColor(255, 255, 255, 60), 2, Qt.PenStyle.DashLine))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawPath(path)
                p.restore()
                p.setOpacity(1.0)
                self._slot_hitboxes.append((QRectF(tx - 8, ty - 8, tile_sz + 16, tile_sz + 16), i))
                continue
            if self._dragging and self._drag_target_idx == i:
                # Highlight the slot the dragged tile would land in if
                # dropped right now.
                p.save()
                p.setPen(QPen(QColor(90, 170, 255, 220), 3))
                p.setBrush(Qt.BrushStyle.NoBrush)
                target_path = QPainterPath()
                target_path.addRoundedRect(tx - 4, ty - 4, tile_sz + 8, tile_sz + 8, r + 2, r + 2)
                p.drawPath(target_path)
                p.restore()
            icon_path = app.get('icon', '')
            exe_path = app.get('exe', '')
            art_path = icon_path
            pix = _get_prescaled_art_async(icon_path, self._TILE_SEL, _art_repaint_cb(self))
            if pix.isNull():
                art_path = exe_path
                pix = _get_prescaled_art_async(exe_path, self._TILE_SEL, _art_repaint_cb(self))
            filled = None
            if not pix.isNull():
                filled = _get_rounded_tile_art(art_path, pix, tile_sz)
                ix = tx + (tile_sz - filled.width()) // 2
                iy = ty + (tile_sz - filled.height()) // 2
            off = QPixmap(tile_sz, tile_sz) if main_t > 0.0 else None
            if off is not None and off.isNull():
                # تخصیص حافظه شکست خورد؛ روی پیکسمپ null نقاشی نمی‌کنیم
                off = None
                main_t = 0.0
            if main_t > 0.0:
                off.fill(Qt.GlobalColor.transparent)
                op = QPainter(off)
                op.setRenderHint(QPainter.RenderHint.Antialiasing)
                local_path = QPainterPath()
                local_path.addRoundedRect(0, 0, tile_sz, tile_sz, r, r)
                op.setClipPath(local_path)
                if filled is not None:
                    op.drawPixmap(ix - tx, iy - ty, filled)
                op.end()

                def _blend_alpha(stop_alpha, _mt=main_t):
                    return int(round(255 - _mt * (255 - stop_alpha)))
                mask = QPainter(off)
                mask.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationIn)
                fade = QLinearGradient(0, 0, 0, tile_sz)
                fade.setColorAt(0.0, QColor(255, 255, 255, _blend_alpha(255)))
                fade.setColorAt(0.6, QColor(255, 255, 255, _blend_alpha(255)))
                fade.setColorAt(0.64, QColor(255, 255, 255, _blend_alpha(244)))
                fade.setColorAt(0.68, QColor(255, 255, 255, _blend_alpha(215)))
                fade.setColorAt(0.72, QColor(255, 255, 255, _blend_alpha(174)))
                fade.setColorAt(0.76, QColor(255, 255, 255, _blend_alpha(128)))
                fade.setColorAt(0.8, QColor(255, 255, 255, _blend_alpha(81)))
                fade.setColorAt(0.84, QColor(255, 255, 255, _blend_alpha(40)))
                fade.setColorAt(0.88, QColor(255, 255, 255, _blend_alpha(11)))
                fade.setColorAt(0.92, QColor(255, 255, 255, _blend_alpha(0)))
                fade.setColorAt(1.0, QColor(255, 255, 255, _blend_alpha(0)))
                mask.fillRect(0, 0, tile_sz, tile_sz, fade)
                mask.end()
                p.save()
                p.setClipPath(path)
                p.drawPixmap(tx, ty, off)
                if filled is not None:
                    plat = _detect_game_platform_cached(exe_path)
                    plat_label = _PLATFORM_BADGE_LABELS.get(plat)
                    if plat_label:
                        _draw_platform_badge(p, ix, iy, filled.width(), filled.height(), plat_label)
                p.restore()
            elif filled is not None:
                p.save()
                p.setClipPath(path)
                p.drawPixmap(ix, iy, filled)
                plat = _detect_game_platform_cached(exe_path)
                plat_label = _PLATFORM_BADGE_LABELS.get(plat)
                if plat_label:
                    _draw_platform_badge(p, ix, iy, filled.width(), filled.height(), plat_label)
                p.restore()
            p.setOpacity(1.0)
            self._slot_hitboxes.append((QRectF(tx - 8, ty - 8, tile_sz + 16, tile_sz + 16), i))
        if self._dragging and self._press_idx is not None and (0 <= self._press_idx < len(self._apps)):
            self._paint_dragged_tile(p)

    def _paint_dragged_tile(self, p):
        """Draw the tile currently being dragged 'lifted' off the row,
        centered under the cursor, on top of everything else."""
        app = self._apps[self._press_idx]
        tile_sz = int(round(self._TILE_SEL * 0.72))
        r = max(_CORNER_RADIUS_MIN, min(_CORNER_RADIUS_MAX, round(tile_sz * _CORNER_RADIUS_FRACTION)))
        tx = int(self._drag_pos.x() - tile_sz / 2)
        ty = int(self._drag_pos.y() - tile_sz / 2)
        p.save()
        p.setOpacity(1.0)
        shadow_path = QPainterPath()
        shadow_path.addRoundedRect(tx - 3, ty + 10, tile_sz + 6, tile_sz + 6, r, r)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(0, 0, 0, 110))
        p.drawPath(shadow_path)
        path = QPainterPath()
        path.addRoundedRect(tx, ty, tile_sz, tile_sz, r, r)
        icon_path = app.get('icon', '')
        exe_path = app.get('exe', '')
        art_path = icon_path
        pix = _get_prescaled_art_async(icon_path, self._TILE_SEL, _art_repaint_cb(self))
        if pix.isNull():
            art_path = exe_path
            pix = _get_prescaled_art_async(exe_path, self._TILE_SEL, _art_repaint_cb(self))
        p.setClipPath(path)
        if not pix.isNull():
            filled = _get_rounded_tile_art(art_path, pix, tile_sz)
            ix = tx + (tile_sz - filled.width()) // 2
            iy = ty + (tile_sz - filled.height()) // 2
            p.drawPixmap(ix, iy, filled)
        p.setClipping(False)
        p.setPen(QPen(QColor(255, 255, 255, 230), 3))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(path)
        p.restore()

    def _hit_test(self, pt):
        best_idx = None
        best_dist = float('inf')
        for rect, idx in self._slot_hitboxes:
            if rect.contains(pt):
                cx_slot = rect.x() + rect.width() / 2
                dist = abs(cx_slot - pt.x())
                if dist < best_dist:
                    best_dist = dist
                    best_idx = idx
        return best_idx

    def _nearest_slot_for_x(self, x):
        """Closest tile (by center x) to a given x, used while dragging --
        the pointer may be between/above tiles rather than strictly inside
        one, so this doesn't require the point to fall inside a hitbox."""
        best_idx = None
        best_dist = float('inf')
        for rect, idx in self._slot_hitboxes:
            cx_slot = rect.x() + rect.width() / 2
            dist = abs(cx_slot - x)
            if dist < best_dist:
                best_dist = dist
                best_idx = idx
        return best_idx

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.RightButton:
            self._handle_right_click(event)
            return
        if event.button() != Qt.MouseButton.LeftButton:
            super().mousePressEvent(event)
            return
        pos = event.position() if hasattr(event, 'position') else event.pos()
        pt = QPointF(pos) if not isinstance(pos, QPointF) else pos
        # Don't act on click/navigate yet -- wait for mouseReleaseEvent so a
        # press-drag-release can be distinguished from a plain click.
        self._press_idx = self._hit_test(pt)
        self._press_pos = pt
        self._dragging = False
        self._drag_target_idx = None
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._press_idx is None or not (event.buttons() & Qt.MouseButton.LeftButton):
            super().mouseMoveEvent(event)
            return
        pos = event.position() if hasattr(event, 'position') else event.pos()
        pt = QPointF(pos) if not isinstance(pos, QPointF) else pos
        if not self._dragging:
            if (pt - self._press_pos).manhattanLength() < self._DRAG_THRESHOLD:
                return
            self._dragging = True
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
        self._drag_pos = pt
        self._drag_target_idx = self._nearest_slot_for_x(pt.x())
        self.update()

    def mouseReleaseEvent(self, event):
        if event.button() != Qt.MouseButton.LeftButton:
            super().mouseReleaseEvent(event)
            return
        if self._dragging:
            from_idx = self._press_idx
            to_idx = self._drag_target_idx
            self._dragging = False
            self._press_idx = None
            self._drag_target_idx = None
            self.setCursor(Qt.CursorShape.PointingHandCursor)
            self.update()
            if from_idx is not None and to_idx is not None and to_idx != from_idx:
                self.reorderRequested.emit(from_idx, to_idx)
            return
        best_idx = self._press_idx
        self._press_idx = None
        if best_idx is not None:
            if best_idx == self._selected_idx:
                self.gameClicked.emit(best_idx)
            else:
                self.navigate_to(best_idx)
                self.gameClicked.emit(best_idx)
        super().mouseReleaseEvent(event)

    def _handle_right_click(self, event):
        pos = event.position() if hasattr(event, 'position') else event.pos()
        pt = QPointF(pos) if not isinstance(pos, QPointF) else pos
        for rect, idx in self._slot_hitboxes:
            if rect.contains(pt):
                self.gameContextRequested.emit(idx)
                return

    def wheelEvent(self, event):
        if not self._apps:
            event.ignore()
            return
        delta = event.angleDelta().y()
        if delta == 0:
            delta = event.angleDelta().x()
        if delta == 0:
            event.ignore()
            return
        self._wheel_accum += delta
        step = 0
        while abs(self._wheel_accum) >= 120:
            step += 1 if self._wheel_accum > 0 else -1
            self._wheel_accum -= 120 if self._wheel_accum > 0 else -120
        if step == 0:
            event.accept()
            return
        n = len(self._apps)
        base = self._wheel_pending_idx if self._wheel_pending_idx is not None else self._selected_idx
        new_idx = (base - step) % n
        self._wheel_pending_idx = new_idx
        self._selected_idx = new_idx
        self._anim.stop()
        self._anim.setStartValue(self._offset)
        self._anim.setEndValue(float(new_idx))
        self._anim.start()
        self._wheel_timer.start(140)
        event.accept()

    def _commit_wheel_navigation(self):
        if self._wheel_pending_idx is None:
            return
        idx = self._wheel_pending_idx
        self._wheel_pending_idx = None
        if 0 <= idx < len(self._apps):
            self.wheelNavigate.emit(idx)

class CategoryWheel(QWidget):
    categorySelected = pyqtSignal(str)
    # Emitted on drop after a press-and-drag past the threshold, carrying
    # (dragged_key, target_key) -- the mouse-drag counterpart of the
    # existing click-to-select categorySelected signal. Reordering the
    # underlying list is the launcher's job (it owns folder_order); this
    # widget only reports the gesture.
    categoryReordered = pyqtSignal(str, str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._tabs = []
        self._active_index = 0
        self._offset = 0.0
        self._anim = QPropertyAnimation(self, b'offset', self)
        self._anim.setDuration(360)
        self._anim.setEasingCurve(QEasingCurve.Type.OutBack)
        self._slot_hitboxes = []
        self._wheel_accum = 0
        self._wheel_pending_index = None
        self._wheel_timer = QTimer(self)
        self._wheel_timer.setSingleShot(True)
        self._wheel_timer.timeout.connect(self._commit_wheel_selection)
        self.setFixedHeight(40)
        self.setMinimumWidth(320)
        self.setMaximumWidth(560)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, False)
        self.setStyleSheet('background:transparent;')
        self.setMouseTracking(True)
        # Drag-to-reorder state. _press_key/_press_pos are recorded on
        # mousePressEvent (mirroring PS5FolderTile/PS5GameTile); a real
        # drag only starts once mouseMoveEvent sees the mouse move past a
        # small threshold, so a plain click still just selects the tab
        # (see mouseReleaseEvent).
        self._press_key = None
        self._press_pos = QPointF()
        self._dragging = False
        self._drag_target_key = None
        self._drag_mouse_x = 0.0

    def _get_offset(self):
        return self._offset

    def _set_offset(self, v):
        self._offset = float(v)
        self.update()
    offset = pyqtProperty(float, _get_offset, _set_offset)

    def set_categories(self, tabs, active_key, animate=True):
        self._tabs = list(tabs)
        try:
            new_index = next((i for i, (_, k) in enumerate(self._tabs) if k == active_key))
        except StopIteration:
            new_index = 0
        if not animate:
            self._active_index = new_index
            self._anim.stop()
            self._set_offset(float(new_index))
            return
        if self._active_index == new_index:
            if self._anim.state() == QPropertyAnimation.State.Running:
                if self._anim.endValue() == float(new_index):
                    return
            else:
                self._anim.stop()
                self._set_offset(float(new_index))
                return
        self._active_index = new_index
        start = self._offset
        self._anim.stop()
        self._anim.setStartValue(start)
        self._anim.setEndValue(float(new_index))
        self._anim.start()

    def paintEvent(self, event):
        self._slot_hitboxes = []
        if not self._tabs:
            return
        # Font-family lookup is a relatively expensive native call; doing it
        # once per widget instance instead of once per visible tab per frame
        # cuts a lot of repeated Qt/OS font-system traffic during animation,
        # which is when this widget repaints most rapidly (up to ~60x/sec
        # while the offset animation is running).
        if not hasattr(self, '_font_family_cache'):
            try:
                self._font_family_cache = 'Vazirmatn' if 'Vazirmatn' in QFontDatabase.families() else 'Segoe UI'
            except Exception:
                self._font_family_cache = 'Segoe UI'
        font_family = self._font_family_cache
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setRenderHint(QPainter.RenderHint.TextAntialiasing)
        cx = self.width() * 0.2
        cy = self.height() / 2.0
        base_size = 15
        min_size = 6
        max_visible_delta = 3.0
        base_spacing = 92.0

        def _falloff(ad_, pts):
            if ad_ <= pts[0][0]:
                return pts[0][1]
            for (a0, v0), (a1, v1) in zip(pts, pts[1:]):
                if ad_ <= a1:
                    if a1 == a0:
                        return v1
                    frac = (ad_ - a0) / (a1 - a0)
                    return v0 + (v1 - v0) * frac
            return pts[-1][1]
        _SCALE_PTS = [(0.0, 1.0), (1.0, 0.62), (2.0, 0.4), (3.0, 0.25)]
        _OPACITY_PTS = [(0.0, 1.0), (1.0, 0.58), (2.0, 0.22), (3.0, 0.0)]
        n = len(self._tabs)
        slots = []
        for i, (label, key) in enumerate(self._tabs):
            delta = i - self._offset
            if delta > n / 2.0:
                delta -= n
            elif delta < -n / 2.0:
                delta += n
            ad = abs(delta)
            if ad > max_visible_delta:
                continue
            scale = _falloff(ad, _SCALE_PTS)
            opacity = _falloff(ad, _OPACITY_PTS)
            sign = 1 if delta > 0 else -1 if delta < 0 else 0
            x = cx + sign * (base_spacing * ad - 4.0 * ad * ad)
            slots.append((ad, i, label, key, scale, opacity, x))
        slots.sort(key=lambda s: -s[0])
        for ad, i, label, key, scale, opacity, x in slots:
            font_size = max(min_size, base_size * scale)
            weight = QFont.Weight.Bold if ad < 0.001 else QFont.Weight.DemiBold
            font = QFont('Vazirmatn', int(round(font_size)), weight)
            if 'Vazirmatn' not in QFontDatabase.families():
                font = QFont('Segoe UI', int(round(font_size)), weight)
            p.setFont(font)
            fm = p.fontMetrics()
            text_w = fm.horizontalAdvance(label)
            text_h = fm.height()
            if ad < 0.001:
                color = QColor(255, 255, 255, 255)
            else:
                base_a = int(210 * opacity)
                color = QColor(200, 205, 235, max(0, base_a))
            p.setOpacity(max(0.0, min(1.0, opacity if ad >= 0.001 else 1.0)))
            p.setPen(color)
            rect = QRectF(x - text_w / 2.0, cy - text_h / 2.0, text_w, text_h)
            p.drawText(rect, Qt.AlignmentFlag.AlignCenter, label)
            p.setOpacity(1.0)
            hit = QRectF(x - max(text_w, 30) / 2.0 - 6, 0, max(text_w, 30) + 12, self.height())
            self._slot_hitboxes.append((hit, key))
        if self._dragging and self._press_key:
            # Drop-target hint: highlight whichever slot the drag is
            # currently nearest to, same "you'll land here" feedback as
            # the blue frame used for game-tile drag targets.
            if self._drag_target_key:
                for rect, key in self._slot_hitboxes:
                    if key == self._drag_target_key:
                        hi = QRectF(rect.left() + 2, cy - 17, rect.width() - 4, 34)
                        pen = QPen(QColor(150, 180, 255, 210))
                        pen.setWidth(2)
                        p.setPen(pen)
                        p.setBrush(QColor(120, 150, 255, 45))
                        p.drawRoundedRect(hi, 8, 8)
                        break
            # The picked-up tab itself, lifted off the wheel and following
            # the cursor horizontally -- mirrors how a dragged game tile
            # follows the mouse in the main row.
            dragged_label = next((lbl for lbl, key in self._tabs if key == self._press_key), None)
            if dragged_label:
                lift_font = QFont('Vazirmatn', base_size, QFont.Weight.Bold)
                if 'Vazirmatn' not in QFontDatabase.families():
                    lift_font = QFont('Segoe UI', base_size, QFont.Weight.Bold)
                p.setFont(lift_font)
                fm = p.fontMetrics()
                text_w = fm.horizontalAdvance(dragged_label)
                text_h = fm.height()
                gx = max(text_w / 2.0 + 8, min(self.width() - text_w / 2.0 - 8, self._drag_mouse_x))
                pad_x, pad_y = (14, 6)
                pill = QRectF(gx - text_w / 2.0 - pad_x, cy - text_h / 2.0 - pad_y, text_w + 2 * pad_x, text_h + 2 * pad_y)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(35, 38, 80, 225))
                p.drawRoundedRect(pill, pill.height() / 2.0, pill.height() / 2.0)
                p.setPen(QColor(255, 255, 255, 255))
                p.drawText(QRectF(gx - text_w / 2.0, cy - text_h / 2.0, text_w, text_h), Qt.AlignmentFlag.AlignCenter, dragged_label)

    def mousePressEvent(self, event):
        if event.button() != Qt.MouseButton.LeftButton:
            super().mousePressEvent(event)
            return
        pos = event.position() if hasattr(event, 'position') else event.pos()
        pt = QPointF(pos) if not isinstance(pos, QPointF) else pos
        self._press_pos = pt
        self._press_key = None
        for rect, key in self._slot_hitboxes:
            if rect.contains(pt):
                self._press_key = key
                break
        self._dragging = False
        self._drag_target_key = None

    def mouseMoveEvent(self, event):
        if not (event.buttons() & Qt.MouseButton.LeftButton) or self._press_key is None:
            super().mouseMoveEvent(event)
            return
        pos = event.position() if hasattr(event, 'position') else event.pos()
        pt = QPointF(pos) if not isinstance(pos, QPointF) else pos
        if not self._dragging:
            delta = pt - self._press_pos
            if abs(delta.x()) + abs(delta.y()) < 10:
                return
            # Picked up past the click threshold -- from here this is a
            # drag, not a click, same convention as PS5FolderTile /
            # PS5GameTile's manhattanLength() check.
            self._dragging = True
        self._drag_mouse_x = pt.x()
        nearest_key, nearest_dist = (None, None)
        for rect, key in self._slot_hitboxes:
            d = abs(rect.center().x() - pt.x())
            if nearest_dist is None or d < nearest_dist:
                nearest_dist = d
                nearest_key = key
        self._drag_target_key = nearest_key
        self.update()

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            if self._dragging:
                if self._drag_target_key and self._press_key and (self._drag_target_key != self._press_key):
                    self.categoryReordered.emit(self._press_key, self._drag_target_key)
            else:
                pos = event.position() if hasattr(event, 'position') else event.pos()
                pt = QPointF(pos) if not isinstance(pos, QPointF) else pos
                for rect, key in self._slot_hitboxes:
                    if rect.contains(pt):
                        self.categorySelected.emit(key)
                        break
            self._dragging = False
            self._press_key = None
            self._drag_target_key = None
            self.update()
        super().mouseReleaseEvent(event)

    def wheelEvent(self, event):
        if not self._tabs:
            super().wheelEvent(event)
            return
        n = len(self._tabs)
        delta = event.angleDelta().y()
        if delta == 0:
            delta = event.angleDelta().x()
        if delta == 0:
            super().wheelEvent(event)
            return
        self._wheel_accum += delta
        step = 0
        while abs(self._wheel_accum) >= 120:
            step += -1 if self._wheel_accum > 0 else 1
            self._wheel_accum -= 120 if self._wheel_accum > 0 else -120
        if step == 0:
            event.accept()
            return
        base = self._wheel_pending_index if self._wheel_pending_index is not None else self._active_index
        new_index = (base + step) % n
        self._wheel_pending_index = new_index
        self._active_index = new_index
        start = self._offset
        self._anim.stop()
        self._anim.setStartValue(start)
        self._anim.setEndValue(float(new_index))
        self._anim.start()
        self._wheel_timer.start(140)
        event.accept()

    def _commit_wheel_selection(self):
        if self._wheel_pending_index is None:
            return
        idx = self._wheel_pending_index
        self._wheel_pending_index = None
        if 0 <= idx < len(self._tabs):
            key = self._tabs[idx][1]
            self.categorySelected.emit(key)

class _PressWarpPlayButton(QPushButton):
    _SEESAW_MAX_ANGLE = 16.0
    _PERSPECTIVE_DEPTH = 220.0
    _SHADE_MAX_ALPHA = 80
    _ANIM_STEP = 0.22
    _EDGE_PAD_X = 34
    _EDGE_PAD_Y = 26

    def __init__(self, text: str='', parent=None, edge_pad_x: 'float | None'=None, edge_pad_y: 'float | None'=None, corner_radius: 'float | None'=None, max_angle: 'float | None'=None, depth: 'float | None'=None):
        super().__init__(text, parent)
        self.setMouseTracking(True)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground, True)
        self.setAutoFillBackground(False)
        self._max_angle = self._SEESAW_MAX_ANGLE if max_angle is None else max_angle
        self.edge_pad_x = self._EDGE_PAD_X if edge_pad_x is None else edge_pad_x
        self.edge_pad_y = self._EDGE_PAD_Y if edge_pad_y is None else edge_pad_y
        self.corner_radius = corner_radius
        self._depth = self._PERSPECTIVE_DEPTH if depth is None else depth
        self._seesaw_pixmap = None
        self._no_chrome = False
        self._manual_glass_fill = None
        self._edge_fade = True
        self._edge_fade_vertical = False
        self._edge_fade_width = 38.0
        self._edge_fade_alpha = 210
        self._edge_fade_height = 18.0
        self._dx_target, self._dx_cur = (0.0, 0.0)
        self._dy_target, self._dy_cur = (0.0, 0.0)
        self._warp_timer = QTimer(self)
        self._warp_timer.setInterval(16)
        self._warp_timer.timeout.connect(self._tick_warp)
        self._entrance_alpha = 1.0

    def _get_entrance_alpha(self):
        return self._entrance_alpha

    def _set_entrance_alpha(self, value):
        self._entrance_alpha = float(value)
        self.update()
    entranceAlpha = pyqtProperty(float, _get_entrance_alpha, _set_entrance_alpha)

    def set_seesaw_icon(self, pix) -> None:
        self._seesaw_pixmap = pix
        self.update()

    def enterEvent(self, event):
        if not self._warp_timer.isActive():
            self._warp_timer.start()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._dx_target = 0.0
        self._dy_target = 0.0
        if not self._warp_timer.isActive():
            self._warp_timer.start()
        super().leaveEvent(event)

    def mouseMoveEvent(self, event):
        pos = event.position() if hasattr(event, 'position') else event.pos()
        vis = self._visible_rect()
        vw, vh = (vis.width(), vis.height())
        if vw > 0:
            self._dx_target = max(-1.0, min(1.0, (pos.x() - vis.left() - vw / 2.0) / (vw / 2.0)))
        if vh > 0:
            self._dy_target = max(-1.0, min(1.0, (pos.y() - vis.top() - vh / 2.0) / (vh / 2.0)))
        if not self._warp_timer.isActive():
            self._warp_timer.start()
        self._refresh_underlying_background()
        self.update()
        super().mouseMoveEvent(event)

    def _refresh_underlying_background(self):
        # یادآوری: این تابع نباید حذف شود و هرگز نباید با CompositionMode_Source روی
        # بوم خودِ ویجت جایگزین شود (آن روش باعث می‌شود پس‌زمینه‌ی زیر دکمه به‌طور کامل
        # مشکی/سیاه دیده شود). علت واقعی «کادر مشکی» این بود که سایه‌ی هاور هر فریم
        # روی فریم قبلی جمع (accumulate) می‌شد چون والد زیرش دوباره رسم نمی‌شد؛ اینجا
        # با وادار کردن والد به رسم دوباره‌ی همان ناحیه، از تیره‌شدن تجمعی جلوگیری می‌کنیم.
        parent = self.parentWidget()
        if parent is not None:
            parent.update(self.geometry())

    def _tick_warp(self):
        settled = True
        for attr, target_attr in (('_dx_cur', '_dx_target'), ('_dy_cur', '_dy_target')):
            cur, target = (getattr(self, attr), getattr(self, target_attr))
            if abs(cur - target) < 0.003:
                setattr(self, attr, target)
                if target != 0.0:
                    settled = False
            else:
                setattr(self, attr, cur + (target - cur) * self._ANIM_STEP)
                settled = False
        if settled:
            self._warp_timer.stop()
        self._refresh_underlying_background()
        self.update()

    def _visible_rect(self) -> 'QRectF':
        return QRectF(self.edge_pad_x, self.edge_pad_y, max(1, self.width() - 2 * self.edge_pad_x), max(1, self.height() - 2 * self.edge_pad_y))

    def _local_visible_rect(self) -> 'QRectF':
        vis = self._visible_rect()
        return QRectF(0, 0, vis.width(), vis.height())

    def _draw_chrome(self, painter):
        from PyQt6.QtWidgets import QStyleOptionButton, QStyle
        opt = QStyleOptionButton()
        self.initStyleOption(opt)
        opt.rect = self._local_visible_rect().toRect()
        opt.state &= ~(QStyle.StateFlag.State_Sunken | QStyle.StateFlag.State_MouseOver)
        self.style().drawControl(QStyle.ControlElement.CE_PushButtonBevel, opt, painter, self)

    def _draw_label(self, painter):
        from PyQt6.QtWidgets import QStyleOptionButton, QStyle
        opt = QStyleOptionButton()
        self.initStyleOption(opt)
        opt.rect = self._local_visible_rect().toRect()
        opt.state &= ~(QStyle.StateFlag.State_Sunken | QStyle.StateFlag.State_MouseOver)
        self.style().drawControl(QStyle.ControlElement.CE_PushButtonLabel, opt, painter, self)

    @staticmethod
    def _mat_mul(a, b):
        a11, a12, a13, a21, a22, a23, a31, a32, a33 = a
        b11, b12, b13, b21, b22, b23, b31, b32, b33 = b
        return (a11 * b11 + a12 * b21 + a13 * b31, a11 * b12 + a12 * b22 + a13 * b32, a11 * b13 + a12 * b23 + a13 * b33, a21 * b11 + a22 * b21 + a23 * b31, a21 * b12 + a22 * b22 + a23 * b32, a21 * b13 + a22 * b23 + a23 * b33, a31 * b11 + a32 * b21 + a33 * b31, a31 * b12 + a32 * b22 + a33 * b32, a31 * b13 + a32 * b23 + a33 * b33)

    def _seesaw_transform(self, w: float, h: float, theta_deg: float, phi_deg: float, ox: float=0.0, oy: float=0.0) -> 'QTransform':
        from PyQt6.QtGui import QTransform
        theta = math.radians(theta_deg)
        phi = math.radians(phi_deg)
        d = self._depth
        cx, cy = (w / 2.0, h / 2.0)
        to_origin = (1, 0, 0, 0, 1, 0, -cx, -cy, 1)
        perspective = (math.cos(theta), math.sin(theta) * math.sin(phi), -math.sin(theta) * math.cos(phi) / d, 0.0, math.cos(phi), math.sin(phi) / d, 0.0, 0.0, 1.0)
        back = (1, 0, 0, 0, 1, 0, cx + ox, cy + oy, 1)
        m = self._mat_mul(to_origin, perspective)
        m = self._mat_mul(m, back)
        return QTransform(*m)

    def hitButton(self, pos) -> bool:
        return self._visible_rect().adjusted(-4, -4, 4, 4).contains(QPointF(pos))

    def paintEvent(self, event):
        w, h = (self.width(), self.height())
        if w <= 0 or h <= 0:
            return
        vis = self._visible_rect()
        vw, vh = (vis.width(), vis.height())
        box_rect = QRectF(0, 0, vw, vh)
        box_path = QPainterPath()
        radius = vh / 2.0 if self.corner_radius is None else self.corner_radius
        box_path.addRoundedRect(box_rect, radius, radius)
        # نکته‌ی مهم: مستقیماً روی QPainter(self) نقاشی نکن. سطح رسم خودِ ویجت
        # کانال آلفای واقعی ندارد، پس CompositionMode_DestinationOut (که پایین‌تر
        # برای محو شدن لبه‌ها استفاده می‌شود) به‌جای شفاف‌شدن، آن ناحیه را مشکیِ
        # کدر می‌کند — همان «کادر مشکی» دور دکمه‌ی Play Game و دور لوگوی اسم بازی.
        # برای همین همه‌چیز را اول روی یک QImage با آلفای واقعی می‌کشیم و در پایان
        # همان تصویر ترکیب‌شده را روی ویجت می‌گذاریم.
        buf = QImage(max(1, w), max(1, h), QImage.Format.Format_ARGB32_Premultiplied)
        buf.fill(Qt.GlobalColor.transparent)
        painter = QPainter(buf)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        dx, dy = (self._dx_cur, self._dy_cur)
        active = dx * dx + dy * dy > 0.0001
        theta = -self._max_angle * dx if active else 0.0
        phi = self._max_angle * dy if active else 0.0
        painter.setTransform(self._seesaw_transform(vw, vh, theta, phi, vis.left(), vis.top()))
        painter.setClipPath(box_path)
        if self._manual_glass_fill is not None:
            grad = QLinearGradient(0.0, 0.0, 0.0, vh)
            for stop, color in self._manual_glass_fill:
                grad.setColorAt(stop, color)
            painter.setPen(Qt.PenStyle.NoPen)
            painter.fillPath(box_path, QBrush(grad))
        elif not self._no_chrome:
            self._draw_chrome(painter)
        if active and (not self._no_chrome):
            mag = min(1.0, math.hypot(dx, dy))
            recede = QPointF(vw / 2.0 + dx * (vw / 2.0), vh / 2.0 + dy * (vh / 2.0))
            forward = QPointF(vw / 2.0 - dx * (vw / 2.0), vh / 2.0 - dy * (vh / 2.0))
            shade = QLinearGradient(recede, forward)
            shade.setColorAt(0.0, QColor(0, 0, 0, int(self._SHADE_MAX_ALPHA * mag)))
            shade.setColorAt(1.0, QColor(0, 0, 0, 0))
            painter.setPen(Qt.PenStyle.NoPen)
            painter.fillRect(box_rect, QBrush(shade))
        if self._seesaw_pixmap is not None and (not self._seesaw_pixmap.isNull()):
            iw = self._seesaw_pixmap.width()
            ih = self._seesaw_pixmap.height()
            ix = int((vw - iw) / 2.0)
            iy = int((vh - ih) / 2.0)
            painter.drawPixmap(ix, iy, self._seesaw_pixmap)
        else:
            self._draw_label(painter)
        if self._edge_fade:
            fade_w = min(self._edge_fade_width, vw / 2.0)
            fade_alpha = self._edge_fade_alpha
            painter.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationOut)
            _lg = QLinearGradient(0.0, 0.0, fade_w, 0.0)
            _lg.setColorAt(0.0, QColor(0, 0, 0, fade_alpha))
            _lg.setColorAt(1.0, QColor(0, 0, 0, 0))
            painter.fillRect(QRectF(0.0, 0.0, fade_w, vh), QBrush(_lg))
            _rg = QLinearGradient(vw - fade_w, 0.0, vw, 0.0)
            _rg.setColorAt(0.0, QColor(0, 0, 0, 0))
            _rg.setColorAt(1.0, QColor(0, 0, 0, fade_alpha))
            painter.fillRect(QRectF(vw - fade_w, 0.0, fade_w, vh), QBrush(_rg))
            if self._edge_fade_vertical:
                fade_h = min(self._edge_fade_height, vh / 2.0)
                _tg = QLinearGradient(0.0, 0.0, 0.0, fade_h)
                _tg.setColorAt(0.0, QColor(0, 0, 0, fade_alpha))
                _tg.setColorAt(1.0, QColor(0, 0, 0, 0))
                painter.fillRect(QRectF(0.0, 0.0, vw, fade_h), QBrush(_tg))
                _bg = QLinearGradient(0.0, vh - fade_h, 0.0, vh)
                _bg.setColorAt(0.0, QColor(0, 0, 0, 0))
                _bg.setColorAt(1.0, QColor(0, 0, 0, fade_alpha))
                painter.fillRect(QRectF(0.0, vh - fade_h, vw, fade_h), QBrush(_bg))
            painter.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceOver)
        painter.end()
        widget_painter = QPainter(self)
        widget_painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        if self._entrance_alpha < 0.999:
            widget_painter.setOpacity(max(0.0, min(1.0, self._entrance_alpha)))
        widget_painter.drawImage(QPointF(0.0, 0.0), buf)
        widget_painter.end()

class SmartPreloadManager(QObject):

    def __init__(self, launcher, parent=None):
        super().__init__(parent)
        self.launcher = launcher
        self.worker = None
        self.generation = 0
        self.cache = collections.OrderedDict()
        self.inflight = set()
        self.status = 'Idle'
        self._retiring = []

    def _retire_worker(self, worker):
        # Never drop the last Python reference to a QThread while its
        # underlying OS thread may still be running -- that causes a
        # native "QThread: Destroyed while thread is still running"
        # abort that bypasses sys.excepthook entirely (no crash report).
        # Instead, disconnect it so late results can't touch our state,
        # then keep it alive in _retiring until its finished signal
        # actually fires.
        try:
            worker.item_ready.disconnect(self._on_ready)
        except Exception:
            pass
        try:
            worker.item_failed.disconnect(self._on_failed)
        except Exception:
            pass
        try:
            worker.finished.disconnect(self._on_finished)
        except Exception:
            pass
        self._retiring.append(worker)

        def _cleanup(w=worker):
            if w in self._retiring:
                self._retiring.remove(w)
            w.deleteLater()
        worker.finished.connect(_cleanup)
        worker.cancel()
        if worker.isRunning():
            worker.wait(120)

    def _settings(self):
        return self.launcher.data.get('settings', {}) or {}

    def schedule(self, apps, selected_index):
        settings = self._settings()
        if not settings.get('preload_enabled', True):
            self.status = 'Disabled'
            return
        count = max(0, int(settings.get('preload_count', 2) or 2))
        if settings.get('preload_performance_mode', False):
            count = min(count, 1)
        start = max(0, int(selected_index) - count)
        end = min(len(apps), int(selected_index) + count + 1)
        nearby = [app for app in list(apps)[start:end] if id(app) not in self.inflight]
        self.generation += 1
        generation = self.generation
        if self.worker is not None:
            self._retire_worker(self.worker)
            self.worker = None
        if not nearby:
            self.status = 'Ready'
            return
        self.inflight.update((id(app) for app in nearby))
        self.status = f'Loading {len(nearby)} nearby item(s)'
        self.worker = _SmartPreloadWorker(nearby, generation, self)
        self.worker.item_ready.connect(self._on_ready)
        self.worker.item_failed.connect(self._on_failed)
        self.worker.finished.connect(self._on_finished)
        self.worker.start()

    def _on_ready(self, payload):
        if not isinstance(payload, dict) or payload.get('generation') != self.generation:
            return
        key = str(payload.get('title') or '')
        self.cache[key] = payload
        self.cache.move_to_end(key)
        settings = self._settings()
        limit = max(8, int(settings.get('preload_cache_limit_count', 120) or 120))
        while len(self.cache) > limit:
            self.cache.popitem(last=False)
        byte_limit = max(16, int(settings.get('preload_cache_limit_mb', 256) or 256)) * 1024 * 1024

        def _payload_bytes(value):
            total = 0
            for image in (value.get('images', {}) or {}).values():
                if isinstance(image, tuple) and len(image) > 1:
                    try:
                        total += int(image[1].sizeInBytes())
                    except Exception:
                        pass
            return total
        while sum((_payload_bytes(item) for item in self.cache.values())) > byte_limit:
            if not self.cache:
                break
            self.cache.popitem(last=False)

    def _on_failed(self, title, message):
        pass

    def _on_finished(self):
        self.inflight.clear()
        self.status = 'Ready'

    def close(self):
        if self.worker is not None:
            self._retire_worker(self.worker)
            self.worker = None
        for w in list(self._retiring):
            w.cancel()
            w.wait(500)

class GameProfileDialog(_GlassDialogBase):
    saved = pyqtSignal(object)
    duplicate_requested = pyqtSignal(object)

    def __init__(self, app, parent=None):
        super().__init__(parent)
        self.app = app
        self.profile = _default_game_profile(app)
        self._init_glass(760)
        root = QVBoxLayout(self)
        root.setContentsMargins(24, 18, 24, 22)
        root.addWidget(self._make_header('Game Profile'))
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        body = QWidget()
        form = QFormLayout(body)
        form.setHorizontalSpacing(18)
        form.setVerticalSpacing(9)
        self.fields = {}

        def line(key, label):
            edit = QLineEdit(str(self.profile.get(key, '') or ''))
            edit.setMinimumWidth(420)
            self.fields[key] = edit
            form.addRow(label, edit)
        for key, label in (('title', 'Name'), ('alias', 'Alias'), ('game_root', 'Game root'), ('exe', 'Executable'), ('args', 'Launch arguments'), ('working_directory', 'Working directory'), ('language', 'Language'), ('resolution', 'Resolution'), ('fps_limit', 'FPS limit'), ('tags', 'Tags'), ('genre', 'Genre'), ('description', 'Description'), ('save_dir', 'Save path'), ('backup_dir', 'Backup path'), ('cover', 'Cover image'), ('background', 'Background image'), ('affinity', 'CPU affinity'), ('emulator_name', 'Emulator profile'), ('emulator_path', 'Emulator executable'), ('emulator_args', 'Emulator arguments'), ('routing_delay_ms', 'Controller handoff delay (ms)'), ('player_slot', 'Player slot (1-4)'), ('physical_controller', 'Physical controller path')):
            line(key, label)

        def combo(key, label, values):
            box = QComboBox()
            for value, text in values:
                box.addItem(text, value)
            current = self.profile.get(key, values[0][0] if values else '')
            index = max(0, box.findData(current))
            box.setCurrentIndex(index)
            self.fields[key] = box
            form.addRow(label, box)
        combo('input_type', 'Input type', [('auto', 'Auto'), ('native', 'Native Input'), ('xinput', 'XInput'), ('directinput', 'DirectInput'), ('generic_hid', 'Generic HID'), ('xbox360', 'Virtual Xbox 360'), ('ps4', 'Virtual PS4'), ('disabled', 'Disabled'), ('custom', 'Custom')])
        combo('safe_mode', 'Safe Mode', SAFE_MODE_OPTIONS)
        combo('controller_output', 'Controller output', [('auto', 'Default'), ('native', 'Native'), ('xbox360', 'Virtual Xbox 360'), ('ps4', 'Virtual PS4'), ('disabled', 'Disabled')])
        combo('display_mode', 'Display mode', [('fullscreen', 'Fullscreen'), ('borderless', 'Borderless'), ('windowed', 'Windowed')])
        combo('process_priority', 'Process priority', [('normal', 'Normal'), ('above_normal', 'Above normal'), ('high', 'High (explicit per game)')])
        combo('controller_profile', 'Controller profile', [('auto', 'Auto')] + [(key, key) for key in self.app.get('_controller_profile_choices') or []])
        for key, label in (('fullscreen', 'Fullscreen'), ('borderless', 'Borderless'), ('vsync', 'VSync'), ('overlay', 'Overlay'), ('run_as_admin', 'Run as Administrator'), ('preload_enabled', 'Enable Preload'), ('rumble_enabled', 'Enable Rumble')):
            check = QCheckBox()
            check.setChecked(bool(self.profile.get(key, False)))
            self.fields[key] = check
            form.addRow(label, check)
        scroll.setWidget(body)
        root.addWidget(scroll, 1)
        buttons = QHBoxLayout()
        save = QPushButton('Save Profile')
        cancel = QPushButton('Cancel')
        reset = QPushButton('Reset Profile')
        duplicate = QPushButton('Duplicate')
        export = QPushButton('Export')
        import_button = QPushButton('Import')
        for button in (save, cancel, reset, duplicate, export, import_button):
            button.setStyleSheet(self._OK_QSS if button is save else self._DANGER_QSS if button is reset else self._CANCEL_QSS)
        save.clicked.connect(self._save)
        cancel.clicked.connect(self.reject)
        reset.clicked.connect(self._reset)
        duplicate.clicked.connect(self._duplicate)
        export.clicked.connect(self._export)
        import_button.clicked.connect(self._import)
        buttons.addWidget(duplicate)
        buttons.addWidget(export)
        buttons.addWidget(import_button)
        buttons.addWidget(reset)
        buttons.addStretch(1)
        buttons.addWidget(cancel)
        buttons.addWidget(save)
        root.addLayout(buttons)
        self._center_on_parent()

    def _reset(self):
        if _GlassMessageDialog.question(self, 'Reset Profile', "Reset this game's profile to defaults?"):
            self.profile = _default_game_profile(self.app)
            self.accept()
            self.saved.emit(self.profile)

    def _save(self):
        profile = self._read_profile()
        profile['schema_version'] = GAME_PROFILE_SCHEMA
        self.saved.emit(profile)
        self.accept()

    def _duplicate(self):
        self.duplicate_requested.emit(dict(self._read_profile()))
        self.accept()

    def _read_profile(self):
        profile = dict(self.profile)
        for key, widget in self.fields.items():
            if isinstance(widget, QComboBox):
                profile[key] = widget.currentData()
            elif isinstance(widget, QCheckBox):
                profile[key] = widget.isChecked()
            else:
                profile[key] = widget.text()
        profile['schema_version'] = GAME_PROFILE_SCHEMA
        return profile

    def _export(self):
        path, _ = QFileDialog.getSaveFileName(self, 'Export Game Profile', '', 'Game Profile (*.json)')
        if not path:
            return
        try:
            with open(path, 'w', encoding='utf-8') as stream:
                json.dump(_sanitize_export(self._read_profile()), stream, ensure_ascii=False, indent=2)
        except OSError as exc:
            _GlassMessageDialog.warning(self, 'Profile Export', str(exc))

    def _import(self):
        path, _ = QFileDialog.getOpenFileName(self, 'Import Game Profile', '', 'Game Profile (*.json)')
        if not path:
            return
        try:
            with open(path, 'r', encoding='utf-8') as stream:
                profile = json.load(stream)
            if not isinstance(profile, dict):
                raise ValueError('Invalid profile schema.')
            self.profile.update(_sanitize_export(profile))
            for key, widget in self.fields.items():
                value = self.profile.get(key, '')
                if isinstance(widget, QComboBox):
                    index = widget.findData(value)
                    if index >= 0:
                        widget.setCurrentIndex(index)
                elif isinstance(widget, QCheckBox):
                    widget.setChecked(bool(value))
                else:
                    widget.setText(str(value or ''))
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            _GlassMessageDialog.warning(self, 'Profile Import', str(exc))

class EmulatorProfileDialog(_GlassDialogBase):
    saved = pyqtSignal(object)

    def __init__(self, profile=None, parent=None):
        super().__init__(parent)
        self.profile = dict(profile or {})
        self._init_glass(720)
        root = QVBoxLayout(self)
        root.setContentsMargins(24, 18, 24, 22)
        root.addWidget(self._make_header('Emulator Profile Wizard'))
        form = QFormLayout()
        self.fields = {}

        def line(key, label):
            edit = QLineEdit(str(self.profile.get(key, '') or ''))
            self.fields[key] = edit
            form.addRow(label, edit)
        combo = QComboBox()
        for name in ('RPCS3', 'PCSX2', 'Dolphin', 'Cemu', 'Ryujinx', 'RetroArch', 'PPSSPP', 'DuckStation', 'Custom'):
            combo.addItem(name, name)
        combo.setCurrentText(str(self.profile.get('type', 'Custom')))
        self.fields['type'] = combo
        form.addRow('Emulator type', combo)
        for key, label in (('name', 'Name'), ('path', 'Executable path'), ('version', 'Version'), ('working_directory', 'Working directory'), ('default_args', 'Default arguments'), ('game_args', 'Game arguments'), ('bios_path', 'BIOS path'), ('firmware_path', 'Firmware path'), ('save_path', 'Save path'), ('shader_cache_path', 'Shader cache'), ('config_path', 'Config path'), ('portable_root', 'Portable root'), ('sample_game', 'Sample game'), ('input_type', 'Input type'), ('output_type', 'Output type')):
            line(key, label)
        root.addLayout(form)
        status = QLabel('Path status: not checked')
        status.setWordWrap(True)
        root.addWidget(status)
        buttons = QHBoxLayout()
        validate = QPushButton('Validate / Detect Version')
        test = QPushButton('Test Emulator')
        test_sample = QPushButton('Test Sample Game')
        cancel = QPushButton('Cancel')
        save = QPushButton('Save')
        for button in (validate, test, test_sample, save):
            button.setStyleSheet(self._OK_QSS)
        cancel.setStyleSheet(self._CANCEL_QSS)
        validate.clicked.connect(lambda: self._validate(status))
        test.clicked.connect(lambda: self._test(status))
        test_sample.clicked.connect(lambda: self._test_sample(status))
        cancel.clicked.connect(self.reject)
        save.clicked.connect(self._save)
        buttons.addWidget(validate)
        buttons.addWidget(test)
        buttons.addWidget(test_sample)
        buttons.addStretch(1)
        buttons.addWidget(cancel)
        buttons.addWidget(save)
        root.addLayout(buttons)
        self._center_on_parent()

    def _validate(self, status):
        path = self.fields['path'].text()
        result = _validate_path(path, 'emulator', 'executable')
        if result['status'] == 'Valid':
            try:
                output = subprocess.check_output([path, '--version'], stderr=subprocess.STDOUT, timeout=4, text=True, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
                self.fields['version'].setText(output.strip().splitlines()[0][:180])
            except Exception:
                status.setText('Path: Valid · Version: Unsupported / not detected')
                return
        status.setText(f"Path: {result['status']} — {result['reason'] or 'OK'}")

    def _test(self, status):
        path = self.fields['path'].text()
        result = _validate_path(path, 'emulator', 'executable')
        status.setText('Test skipped: ' + result['status'])
        if result['status'] != 'Valid':
            return
        try:
            subprocess.Popen([path], cwd=os.path.dirname(path))
            status.setText('Test started successfully.')
        except Exception as exc:
            status.setText('Test failed: ' + str(exc))

    def _test_sample(self, status):
        emulator = self.fields['path'].text().strip()
        sample = self.fields['sample_game'].text().strip()
        emulator_check = _validate_path(emulator, 'emulator', 'executable')
        sample_check = _validate_path(sample, 'sample game', 'file')
        if emulator_check['status'] != 'Valid':
            status.setText('Sample test skipped: emulator ' + emulator_check['status'])
            return
        if sample_check['status'] != 'Valid':
            status.setText('Sample test skipped: sample game ' + sample_check['status'])
            return
        try:
            template = self.fields['game_args'].text().strip() or '{game}'
            args = shlex.split(_format_emulator_args(template, sample))
            cwd = self.fields['working_directory'].text().strip() or os.path.dirname(emulator)
            subprocess.Popen([emulator] + args, cwd=cwd)
            status.setText('Sample game test started successfully.')
        except Exception as exc:
            status.setText('Sample test failed: ' + str(exc))

    def _save(self):
        profile = {}
        for key, widget in self.fields.items():
            profile[key] = widget.currentData() if isinstance(widget, QComboBox) else widget.text()
        profile['schema_version'] = 1
        path_status = _validate_path(profile.get('path'), 'emulator', 'executable')
        profile['status'] = path_status['status']
        self.saved.emit(profile)
        self.accept()

class SystemStatusDialog(_GlassDialogBase):

    def __init__(self, launcher, parent=None):
        super().__init__(parent)
        self.launcher = launcher
        self._init_glass(720)
        root = QVBoxLayout(self)
        root.setContentsMargins(24, 18, 24, 22)
        root.addWidget(self._make_header('System Status Dashboard'))
        self.text = QTextEdit()
        self.text.setReadOnly(True)
        self.text.setStyleSheet('QTextEdit{color:#dce2ff;background:rgba(0,0,0,40);border:none;}')
        root.addWidget(self.text, 1)
        row = QHBoxLayout()
        refresh = QPushButton('Refresh')
        export = QPushButton('Export Report')
        close = QPushButton('Close')
        for button in (refresh, export):
            button.setStyleSheet(self._OK_QSS)
        close.setStyleSheet(self._CANCEL_QSS)
        refresh.clicked.connect(self.refresh)
        export.clicked.connect(self.export_report)
        close.clicked.connect(self.accept)
        row.addWidget(refresh)
        row.addWidget(export)
        row.addStretch(1)
        row.addWidget(close)
        root.addLayout(row)
        self.refresh()
        self._refresh_timer = QTimer(self)
        self._refresh_timer.setInterval(5000)
        self._refresh_timer.timeout.connect(self.refresh)
        self._refresh_timer.start()
        self._center_on_parent()

    def closeEvent(self, event):
        if hasattr(self, '_refresh_timer'):
            self._refresh_timer.stop()
        super().closeEvent(event)

    def refresh(self):
        snapshot = self.launcher._system_status_snapshot()
        self.text.setPlainText(json.dumps(snapshot, ensure_ascii=False, indent=2))

    def export_report(self):
        path, _ = QFileDialog.getSaveFileName(self, 'Export Status Report', '', 'JSON (*.json);;Text (*.txt)')
        if not path:
            return
        try:
            with open(path, 'w', encoding='utf-8') as stream:
                stream.write(self.text.toPlainText())
        except OSError as exc:
            _GlassMessageDialog.warning(self, 'Export', str(exc))

def _one_time_reset_gamepad_button_mapping(data: dict) -> None:
    """One-time cleanup: wipe any saved gamepad face-button remap so the
    controller goes back to its default (unmapped) behaviour.

    This clears both the global Settings -> Game pad -> Button Mapping
    ('gamepad_mapping') and any per-device 'mapping' entry saved by the
    Controller Calibration wizard ('controller_profiles'), since either
    one alone is enough to make a button (e.g. Triangle) act like a
    different one in-game. It only runs once per save file -- guarded by
    the 'gamepad_button_mapping_reset_v1' marker -- so it never fights a
    mapping the user deliberately sets up again afterwards."""
    try:
        settings = data.setdefault('settings', {})
        if settings.get('gamepad_button_mapping_reset_v1'):
            return
        settings['gamepad_mapping'] = {}
        profiles = data.get('controller_profiles')
        if isinstance(profiles, dict):
            for profile in profiles.values():
                if isinstance(profile, dict) and profile.get('mapping'):
                    profile['mapping'] = {}
        settings['gamepad_button_mapping_reset_v1'] = True
    except Exception:
        pass


class PS5Launcher(QMainWindow):
    _TOP_BAR_H = 56
    _game_process_exited = pyqtSignal()
    _fps_overlay_hotkey_pressed = pyqtSignal()
    _LAUNCH_HANDOFF_BUFFER_SEC = 1.5
    _LAUNCH_FALLBACK_GIVEUP_SEC = 120.0
    _LAUNCH_FULLSCREEN_TIMEOUT_SEC = 90
    # If the game process disappears this soon after launch (crashed on
    # startup, anti-cheat/overlay conflict on first try, etc.) the
    # launcher retries automatically instead of giving up, without
    # tearing down the loading overlay -- up to _AUTO_RELAUNCH_MAX_ATTEMPTS
    # times per launch.
    _AUTO_RELAUNCH_WINDOW_SEC = 8.0
    _AUTO_RELAUNCH_MAX_ATTEMPTS = 3

    def __init__(self):
        super().__init__()
        self._game_process_exited.connect(self._restore_after_game)
        self.data = self._load_data()
        _sync_module_settings_from_data(self.data)
        self._booster = _GameBooster()
        self._booster.stats_ready.connect(self._on_booster_stats)
        self._booster.recover_from_crash()
        self._controller_guard_paths = []
        self._controller_guard_timer = QTimer(self)
        self._controller_guard_timer.timeout.connect(self._enforce_controller_guard)
        self.selected_col = 0
        self._startup_idle = True
        self._shutting_down = False
        self._folder_overlay = None
        self._all_items = []
        self._move_mode = False
        self._move_from_col = 0
        self._edit_overlay = None
        # Widget-reuse cache for refresh_tiles(): keyed by a stable identity
        # per folder/game so a refresh that doesn't actually add/remove
        # items (most calls -- filter re-render, selection-adjacent state
        # changes, move-mode toggles, etc.) updates existing tile widgets
        # in place instead of destroying and rebuilding every tile in the
        # library from scratch every time. See refresh_tiles().
        self._tile_cache = {}
        _startup_folders = []
        for _app in self.data.get('apps', []):
            _fn = _app.get('folder', '')
            if _fn and _fn not in _startup_folders:
                _startup_folders.append(_fn)
        _order = self.data.get('folder_order', [])
        _ordered_startup = [f for f in _order if f in _startup_folders]
        for _f in sorted(_startup_folders, key=str.lower):
            if _f not in _ordered_startup:
                _ordered_startup.append(_f)
        _has_startup_other = any(not (_app.get('folder') or '').strip() for _app in self.data.get('apps', []))
        self._active_filter = _ordered_startup[0] if _ordered_startup else ('__other__' if _has_startup_other else None)
        self.in_preview_row = True
        self.preview_selected_col = 0
        self._preview_items = []
        self._preview_move_mode = False
        self._preview_move_from = 0
        self._grabbed_item = None
        self._grabbed_orig_folder = None
        self._dir_size_cache = {}
        self._game_running = False
        self._game_minimized_to_launcher = False
        self._launcher_suppressed = False
        self._restore_pending = False
        self._game_alive_poll_timer = None
        self._launch_watch_exe = ''
        self._launch_window_seen = False
        self._launch_proc_exited = False
        self._launch_proc_exit_time = None
