        self._launch_real_pid = None
        self._launch_seen_alive_once = False
        self._hotkey_overlay_active = False
        self._active_play_session = None
        self._save_backup_timer = None
        self._save_backup_worker = None
        self._pending_trainer_path = None
        self._bg_dl_queue = []
        self._bg_dl_active = {}
        self._bg_fail_since = {}
        self._bg_last_notify = {}
        self._audio_theme_inflight = set()
        self._audio_theme_preview_key = None
        self._audio_theme_session_app = None
        self._audio_theme_session_path = ''
        self._audio_theme_session_reason = ''
        self._audio_theme_session_started_at = 0.0
        self._audio_theme_session_offset = 0.0
        self._audio_theme_paused = False
        self._audio_theme_transition_token = 0
        self._audio_theme_route = ''
        self._audio_theme_route_since = 0.0
        self._system_theme_fade_anim = None
        self._audio_progress_generation = 0
        self._audio_progress_container = None
        self._audio_progress_bar = None
        self._audio_progress_label = None
        self._system_theme_player = None
        self._system_theme_output = None
        if QMediaPlayer is not None and QAudioOutput is not None:
            try:
                self._system_theme_output = QAudioOutput(self)
                self._system_theme_output.setVolume(float(self.data.get('settings', {}).get('audio_theme_volume', DEFAULT_SETTINGS['audio_theme_volume'])))
                self._system_theme_player = QMediaPlayer(self)
                self._system_theme_player.setAudioOutput(self._system_theme_output)
            except Exception:
                self._system_theme_player = None
        self._repaired_title_count = self._auto_repair_internal_folder_titles()
        self._current_selected_app = None
        self._input_ready = False
        self._startup_scan_prompted = False
        self._led_resume_app = None
        self._ctrl_mgr = ControllerEmulationManager.instance()
        self._preload = SmartPreloadManager(self, self)
        self._recovery_restarts = {}
