        self._cursor_watch_timer.timeout.connect(self._check_cursor_moved)
        self._cursor_watch_timer.start()
        os.makedirs(BG_CACHE_DIR, exist_ok=True)
        os.makedirs(LOGO_CACHE_DIR, exist_ok=True)
        os.makedirs(ICON_CACHE_DIR, exist_ok=True)
        os.makedirs(TILE_CACHE_DIR, exist_ok=True)
        os.makedirs(AUDIO_CACHE_DIR, exist_ok=True)
        # No WindowStaysOnTopHint here on purpose: that flag would force the
        # launcher to stay glued above every other window at all times
        # (games, task manager, etc. included), even after it lost focus.
        # We only want it to come to the front at the moment it's brought
        # back from the tray -- that's handled by raise_()/activateWindow()
        # calls in _show_launcher()/_wake_launcher_window()/_claim_launcher_input(),
        # not by a persistent always-on-top flag.
        self.setWindowFlags(Qt.WindowType.FramelessWindowHint)
        self.setAcceptDrops(True)
        self._setup_tray()
