    def _show_settings_panel(self, category):
        # The panel can also be opened through keyboard/gamepad/tray paths,
        # which do not pass through the mouse filter below.  Make sure the
        # panel never remains visually open while the launcher is still in
        # the input-swallowing startup-idle state.
        if getattr(self, '_startup_idle', False) and self.isVisible():
            self._exit_startup_idle()
        if getattr(self, '_settings_panel', None) is None:
            self._settings_panel = _SettingsGlassPanel(self.central)
            self._settings_panel.closeRequested.connect(self._close_settings_panel)
        panel = self._settings_panel
        panel.rebuild(category, self)
        self._settings_panel_open = True
        drawer = getattr(self, '_settings_drawer', None)
        if drawer is None or not drawer.isVisible() or drawer.maximumHeight() == 0:
            self._toggle_settings_drawer()
        panel.show()
        panel.raise_()
        self._audio_play_event('settings')
        QTimer.singleShot(0, self._finalize_panel_geometry)
        ct = getattr(self, '_ct_widget', None)
        if ct is not None:
            try:
                ct._timer.start(16)
            except Exception:
                pass

    def _close_settings_panel(self):
        panel = getattr(self, '_settings_panel', None)
        if panel is not None:
            panel.hide()
        self._settings_panel_open = False
        ct = getattr(self, '_ct_widget', None)
        if ct is not None:
            try:
                ct._timer.stop()
            except Exception:
                pass
        try:
            self.setFocus(Qt.FocusReason.OtherFocusReason)
        except RuntimeError:
            pass

    def _finalize_panel_geometry(self):
        panel = getattr(self, '_settings_panel', None)
        if panel is None or not panel.isVisible():
            return
        central = self.central
        margin = 48
        max_pw = max(560, central.width() - margin * 2)
        # Shrink the panel (the big black glass box) to only as wide as its
        # content actually needs, instead of always stretching out to the
        # full available width -- still capped at max_pw so it never
        # overflows the window, and never below a sane minimum.
        outer_m = panel.layout().contentsMargins()
        scrollbar_allowance = 24
        content_w = panel._flow.natural_width() + outer_m.left() + outer_m.right() + scrollbar_allowance
        pw = max(320, min(max_pw, content_w))
        panel.setFixedWidth(pw)
        vw = panel._scroll.viewport().width()
        if vw > 40 and panel._flow.count():
            flow_h = panel._flow.heightForWidth(vw)
        else:
            flow_h = 360
        max_h = int(central.height() * 0.74)
        h = max(240, min(72 + flow_h, max_h))
        panel.setFixedHeight(h)
        drawer = getattr(self, '_settings_drawer', None)
        y = (drawer.y() + drawer._expanded_height + 12) if drawer is not None else 60
        panel.move(margin, max(10, y))
        panel.raise_()

    def _set_overlay_metric(self, key, value):
        """Persist exactly one FPS-overlay metric.

        Merges into the CURRENT stored dict (never a copy captured when the
        panel was built), touches only `key`, and uses the debounced
        _save_data().  It deliberately does not go through _apply_settings():
        that re-syncs unrelated module state on the UI thread."""
        try:
            st = self.data.setdefault('settings', {})
            m = dict(DEFAULT_SETTINGS['fps_overlay_metrics'])
            m.update(st.get('fps_overlay_metrics', {}) or {})
            m[key] = bool(value)
            st['fps_overlay_metrics'] = m
            self._save_data()
        except Exception:
            pass

    def _save_setting_now(self, **kw):
        s = dict(self.data.get('settings', {}))
        s.update(kw)
        self._apply_settings(s, quiet=True)

    def _panel_action_button(self, text, slot, danger=False):
        b = QPushButton(text)
        b.setFixedHeight(42)
        b.setFont(QFont('Segoe UI', 10))
        b.setCursor(Qt.CursorShape.PointingHandCursor)
        b.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        b.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, False)
        if danger:
            base = 'QPushButton{color:#ffb3b3;background:rgba(170,35,35,40);border:1px solid rgba(220,80,80,50);border-radius:10px;padding:0 16px;}QPushButton:hover{background:rgba(200,45,45,150);color:#fff;}'
        else:
            base = 'QPushButton{color:#e4e8ff;background:rgba(255,255,255,7);border:1px solid rgba(255,255,255,18);border-radius:10px;padding:0 16px;}QPushButton:hover{background:rgba(255,255,255,20);color:#fff;}'
        b.setStyleSheet(base + _BTN_GP_FOCUS_QSS)
        # Keep the button on Qt's normal clicked path.  The previous
        # implementation deferred every action through QTimer.singleShot().
        # On some Windows/PyQt6 builds the settings panel was rebuilt or
        # hidden before that zero-delay callback ran, so Add Game, Category
        # and Scan appeared completely inert.  Modal actions explicitly
        # defer themselves through _run_library_modal_action below; ordinary
        # settings actions should simply run when clicked.
        def _activate(_checked=False, fn=slot):
            try:
                fn()
            except RuntimeError:
                pass
        b.clicked.connect(_activate)
        return b

    def _run_library_modal_action(self, action):
        """Close the Library panel, then launch exactly one modal action.

        The panel is a child of the main window, while the explorer and scan
        dialogs are modal top-level windows.  The old implementation left
        several shared/deferred paths in between the click and the dialog.
        This entry point is now the only hand-off: disable and hide the panel,
        invoke the requested operation, and restore input ownership after it
        returns.
        """
        if getattr(self, '_library_modal_action_running', False):
            return
        self._library_modal_action_running = True
        panel = getattr(self, '_settings_panel', None)
        if panel is not None:
            panel.setEnabled(False)
            self._close_settings_panel()
            panel.hide()
        try:
            action()
        except Exception as exc:
            # Never make a failed action look like a dead button.  The
            # specific failure is useful on machines missing a dependency or
            # a readable folder, and the panel can be reopened normally.
            try:
                _GlassMessageDialog.warning(self, 'Library action failed', f'{type(exc).__name__}: {exc}')
            except Exception:
                pass
        finally:
            if panel is not None:
                try:
                    panel.setEnabled(True)
                except RuntimeError:
                    pass
            self._library_modal_action_running = False
            try:
                self._claim_launcher_input()
            except Exception:
                pass

    def _panel_toggle(self, panel, text, key, default, section=None, container=None):
        cb = ToggleSwitchRow(text)
        cb.setChecked(bool(self.data.get('settings', {}).get(key, default)))
        cb.toggled.connect(lambda c, k=key: _safe_call(lambda: self._save_setting_now(**{k: cb.isChecked()})))
        block = QWidget()
        bl = QVBoxLayout(block)
        bl.setContentsMargins(10, 6, 10, 6)
        bl.setSpacing(0)
        bl.addWidget(cb)
        self._panel_card(block)
        if container is not None:
            container.addWidget(block)
        else:
            panel.add(block, section)
        return cb

    def _panel_slider(self, panel, text, key, lo, hi, default, section=None, unit=''):
        block = QWidget()
        bl = QVBoxLayout(block)
        bl.setContentsMargins(10, 8, 10, 8)
        bl.setSpacing(2)
        cap = QLabel(text)
        cap.setFont(QFont('Segoe UI', 9, QFont.Weight.Bold))
        cap.setStyleSheet('color:#c6d0f5;background:transparent;border:none;')
        bl.addWidget(cap)
        row = QHBoxLayout()
        row.setSpacing(8)
        sl = _GlassSlider(Qt.Orientation.Horizontal)
        sl.setRange(lo, hi)
        sl.setValue(int(self.data.get('settings', {}).get(key, default)))
        sl.setMinimumWidth(170)
        val = QLabel(str(sl.value()) + unit)
        val.setFixedWidth(52)
        val.setAlignment(Qt.AlignmentFlag.AlignCenter)
        val.setStyleSheet('color:#cdd8ff;font-size:10px;font-weight:bold;background:transparent;border:none;')

        def _on_slider(v, l=val, u=unit, k=key):
            l.setText(str(v) + u)
            _safe_call(lambda: self._save_setting_now(**{k: sl.value()}))
        sl.valueChanged.connect(_on_slider)
        row.addWidget(sl, 1)
        row.addWidget(val)
        bl.addLayout(row)
        self._panel_card(block)
        panel.add(block, section)
        return block

    def _panel_combo(self, panel, text, key, options, default, section=None):
        block = QWidget()
        bl = QVBoxLayout(block)
        bl.setContentsMargins(10, 8, 10, 8)
        bl.setSpacing(2)
        cap = QLabel(text)
        cap.setFont(QFont('Segoe UI', 9, QFont.Weight.Bold))
        cap.setStyleSheet('color:#c6d0f5;background:transparent;border:none;')
        bl.addWidget(cap)
        combo = QComboBox()
        for label, data in options:
            combo.addItem(label, data)
        idx = combo.findData(self.data.get('settings', {}).get(key, default))
        combo.setCurrentIndex(max(0, idx))
        combo.setMinimumWidth(150)
        combo.setStyleSheet(_PANEL_COMBO_QSS)
        combo.currentIndexChanged.connect(lambda i, k=key: _safe_call(lambda: self._save_setting_now(**{k: combo.currentData()})))
        bl.addWidget(combo)
        self._panel_card(block)
        panel.add(block, section)
        return combo

    def _panel_edit(self, panel, text, key, placeholder='', password=False, section=None, container=None):
        block = QWidget()
        bl = QVBoxLayout(block)
        bl.setContentsMargins(10, 8, 10, 8)
        bl.setSpacing(2)
        cap = QLabel(text)
        cap.setFont(QFont('Segoe UI', 9, QFont.Weight.Bold))
        cap.setStyleSheet('color:#c6d0f5;background:transparent;border:none;')
        bl.addWidget(cap)
        e = QLineEdit(str(self.data.get('settings', {}).get(key, '') or ''))
        e.setPlaceholderText(placeholder)
        e.setFixedHeight(36)
        e.setMinimumWidth(170)
        if password:
            e.setEchoMode(QLineEdit.EchoMode.Password)
        e.setStyleSheet("QLineEdit{background:rgba(255,255,255,6);color:#e4e8ff;border:1px solid rgba(255,255,255,16);border-radius:9px;padding:6px 10px;font-family:'Segoe UI';font-size:11px;}QLineEdit:focus{border:1px solid rgba(255,255,255,55);}")
        e.textEdited.connect(lambda t, k=key: _safe_call(lambda: self._save_setting_now(**{k: t.strip()})))
        bl.addWidget(e)
        self._panel_card(block)
        if container is not None:
            container.addWidget(block)
        else:
            panel.add(block, section)
        return e

    def _save_mapping_now(self):
        mp = {}
        for key, cb in getattr(self, '_map_panel_combos', []):
            d = cb.currentData()
            if d != 'default':
                mp[key] = str(d)
        self._save_setting_now(gamepad_mapping=mp)

    def _reset_mapping_now(self):
        for key, cb in getattr(self, '_map_panel_combos', []):
            cb.blockSignals(True)
            cb.setCurrentIndex(0)
            cb.blockSignals(False)
        self._save_setting_now(gamepad_mapping={})

    def _panel_preview_switching_audio(self, key):
        path = str(self.data.get('settings', {}).get('switching_audio_%s_file' % key, '') or '')
        engine = getattr(self, '_bt_audio', None)
        if not path or not os.path.exists(path) or engine is None or not getattr(engine, 'available', False):
            return
        try:
            engine.stop()
            engine.play_file(path)
        except Exception:
            pass

    def _panel_choose_switching_audio(self, key, refresh_lbl):
        path, _ = QFileDialog.getOpenFileName(self, 'Select Switching Audio', '', 'Audio files (*.wav *.mp3 *.ogg *.oga *.flac *.aiff *.aif)')
        if not path:
            return
        try:
            if os.path.getsize(path) > AUDIO_MAX_BYTES:
                raise ValueError('The audio file is larger than the allowed limit.')
            with open(path, 'rb') as stream:
                decoded = _decode_audio_to_wav(stream.read(), path)
            if not decoded:
                raise ValueError('The selected audio file could not be decoded.')
            wav_bytes, _duration, _rate = decoded
            os.makedirs(AUDIO_CACHE_DIR, exist_ok=True)
            norm = os.path.join(AUDIO_CACHE_DIR, '_switching_%s.wav' % key)
            part = norm + ('.%s.part' % os.getpid())
            with open(part, 'wb') as stream:
                stream.write(wav_bytes)
            os.replace(part, norm)
            self._save_setting_now(**{'switching_audio_%s_file' % key: norm})
        except (OSError, ValueError) as exc:
            _GlassMessageDialog.warning(self, 'Switching Audio', str(exc))
            return
        refresh_lbl()

    def _panel_clear_switching_audio(self, key, refresh_lbl):
        old = str(self.data.get('settings', {}).get('switching_audio_%s_file' % key, '') or '')
        if old.startswith(os.path.abspath(AUDIO_CACHE_DIR) + os.sep):
            try:
                os.remove(old)
            except OSError:
                pass
        self._save_setting_now(**{'switching_audio_%s_file' % key: ''})
        refresh_lbl()

    def _build_panel_category(self, panel, category):
        s = dict(self.data.get('settings', {}))
        if category == 'library':
            self._build_panel_library(panel, s)
        elif category == 'audio':
            self._build_panel_audio(panel, s)
        elif category == 'system':
            self._build_panel_system(panel, s)

    def _build_panel_library(self, panel, s):
        # These controls are deliberately rebuilt as one dedicated row.  The
        # old implementation added three unrelated buttons directly to the
        # wrapping flow and routed all of them through the generic settings
        # action helper; when that helper/filter lost a press, all three
        # appeared dead together.
        action_row = QWidget()
        action_row.setObjectName('libraryActionRow')
        action_row.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, False)
        action_layout = QHBoxLayout(action_row)
        action_layout.setContentsMargins(0, 0, 0, 0)
        action_layout.setSpacing(8)
        action_layout.addWidget(_LibraryActionButton(
            'Add Game',
            lambda: self._run_library_modal_action(self._add_game),
            action_row,
        ))
        action_layout.addWidget(_LibraryActionButton(
            'Category',
            lambda: self._run_library_modal_action(self._add_folder),
            action_row,
        ))
        action_layout.addWidget(_LibraryActionButton(
            'Scan for Games',
            lambda: self._run_library_modal_action(self._scan_for_games),
            action_row,
        ))
        action_layout.addStretch(1)
        panel.add(action_row)

        auto = ToggleSwitchRow('Auto-search trainers')
        auto.setChecked(bool(s.get('trainer_auto_search', DEFAULT_SETTINGS['trainer_auto_search'])))
        auto.toggled.connect(lambda c: _safe_call(lambda: self._save_setting_now(trainer_auto_search=auto.isChecked())))
        # Hidden from the panel per request (with its "Trainer" section
        # header) -- the toggle and its saved setting still work, it's
        # just not shown in the UI anymore.

        apps = [a for a in self.data.get('apps', []) if a.get('exe')]
        has_apps = bool(apps)
        combo = QComboBox()
        for a in apps:
            combo.addItem(a.get('title') or a.get('name') or os.path.basename(a.get('exe', '')), len(combo))
        combo.setMinimumWidth(240)
        combo.setStyleSheet(_PANEL_COMBO_QSS)
        combo.setEnabled(has_apps)
        status = QLabel('')
        status.setWordWrap(True)
        status.setStyleSheet('color:#aebdff;background:transparent;border:none;font-size:10px;')
        status.setMinimumWidth(220)

        list_refresh = {'fn': lambda: None}

        # "Set" and "Clear" now live inside the same card as the game picker
        # instead of floating as separate flow items, so it reads as one
        # self-contained "pick a game, manage its trainer" unit. Clear is only
        # ever enabled when there's actually something to clear.
        set_btn = self._panel_action_button('Set Trainer File', lambda: choose_trainer())
        clear_btn = self._panel_action_button('Clear Trainer File', lambda: clear_trainer())
        set_btn.setFixedHeight(32)
        clear_btn.setFixedHeight(32)
        set_btn.setEnabled(has_apps)

        def refresh_trainer(idx):
            if 0 <= idx < len(apps):
                tp = apps[idx].get('trainer_path', '')
                if tp and os.path.exists(tp):
                    status.setText(os.path.basename(tp))
                elif tp:
                    status.setText('Missing: %s' % tp)
                else:
                    status.setText('No trainer file set')
                clear_btn.setEnabled(bool(tp))
            else:
                status.setText('No games')
                clear_btn.setEnabled(False)
        combo.currentIndexChanged.connect(refresh_trainer)

        def choose_trainer():
            idx = combo.currentIndex()
            if not (0 <= idx < len(apps)):
                return
            path, _ = QFileDialog.getOpenFileName(self, 'Select Trainer', '', 'Executable (*.exe);;All files (*)')
            if path:
                apps[idx]['trainer_path'] = path
                self._save_data()
                refresh_trainer(idx)
                list_refresh['fn']()

        def clear_trainer():
            idx = combo.currentIndex()
            if 0 <= idx < len(apps):
                apps[idx]['trainer_path'] = ''
                self._save_data()
                refresh_trainer(idx)
                list_refresh['fn']()

        trainer_card = QWidget()
        trainer_l = QVBoxLayout(trainer_card)
        trainer_l.setContentsMargins(10, 8, 10, 8)
        trainer_l.setSpacing(6)
        trainer_l.addWidget(combo)
        trainer_l.addWidget(status)
        trainer_btn_row = QHBoxLayout()
        trainer_btn_row.setSpacing(6)
        trainer_btn_row.addWidget(set_btn)
        trainer_btn_row.addWidget(clear_btn)
        trainer_l.addLayout(trainer_btn_row)
        self._panel_card(trainer_card)
        panel.add(trainer_card)
        if combo.count():
            combo.setCurrentIndex(0)
        refresh_trainer(combo.currentIndex())

        # Downloaded-trainers card: title, count and the "download all" action
        # share one header row instead of the title, the button and its status
        # text each floating as their own separate flow item.
        downloaded_block = QWidget()
        downloaded_layout = QVBoxLayout(downloaded_block)
        downloaded_layout.setContentsMargins(10, 8, 10, 8)
        downloaded_layout.setSpacing(6)
        downloaded_header = QHBoxLayout()
        downloaded_header.setSpacing(8)
        downloaded_title = QLabel('Downloaded Trainers')
        downloaded_title.setFont(QFont('Segoe UI', 9, QFont.Weight.Bold))
        downloaded_title.setStyleSheet('color:#c6d0f5;background:transparent;border:none;')
        downloaded_header.addWidget(downloaded_title)
        downloaded_header.addStretch(1)
        bulk_btn = self._panel_action_button('Download All', lambda: _start_bulk_download())
        bulk_btn.setFixedHeight(30)
        downloaded_header.addWidget(bulk_btn)
        downloaded_layout.addLayout(downloaded_header)
        downloaded_list = QListWidget()
        downloaded_list.setMinimumWidth(260)
        downloaded_list.setFixedHeight(150)
        downloaded_list.setVerticalScrollMode(QAbstractItemView.ScrollMode.ScrollPerPixel)
        downloaded_list.setStyleSheet(_dialog_list_qss())
        downloaded_layout.addWidget(downloaded_list)
        bulk_status = QLabel('')
        bulk_status.setWordWrap(True)
        bulk_status.setStyleSheet('color:#9fb3ff;background:transparent;border:none;font-size:10px;')
        bulk_status.setVisible(False)
        downloaded_layout.addWidget(bulk_status)
        self._panel_card(downloaded_block)

        def _set_bulk_status(text):
            bulk_status.setText(text)
            bulk_status.setVisible(bool(text))

        def _refresh_downloaded_trainers():
            downloaded_list.clear()
            found = 0
            for app_ref in self.data.get('apps', []):
                trainer_path = str(app_ref.get('trainer_path') or '').strip()
                if not trainer_path:
                    continue
                found += 1
                title = app_ref.get('title') or app_ref.get('name') or os.path.basename(app_ref.get('exe', '')) or 'Unknown game'
                filename = os.path.basename(trainer_path) or trainer_path
                if os.path.exists(trainer_path):
                    text = f'{title}  —  {filename}'
                else:
                    text = f'{title}  —  Missing: {filename}'
                item = QListWidgetItem(text)
                item.setToolTip(trainer_path)
                downloaded_list.addItem(item)
            downloaded_title.setText(f'Downloaded Trainers ({found})' if found else 'Downloaded Trainers')
            if not found:
                placeholder = QListWidgetItem('No trainers downloaded yet')
                placeholder.setFlags(Qt.ItemFlag.NoItemFlags)
                downloaded_list.addItem(placeholder)

        list_refresh['fn'] = _refresh_downloaded_trainers

        def _start_bulk_download():
            if bulk_btn.text().startswith('Cancel'):
                bulk_state['cancel'] = True
                _set_bulk_status('Cancelling…')
                return
            all_apps = [a for a in self.data.get('apps', []) if (a.get('title') or a.get('name') or a.get('exe'))]
            if not all_apps:
                _set_bulk_status('No games in your library yet.')
                return
            bulk_state['cancel'] = False
            bulk_btn.setText('Cancel')

            def _worker():
                total = len(all_apps)
                downloaded = skipped = failed = 0
                manager = TrainerManager.instance()
                settings = self.data.get('settings', {})
                for index, app_ref in enumerate(all_apps, start=1):
                    if bulk_state['cancel']:
                        break
                    title = (app_ref.get('title') or app_ref.get('name') or os.path.basename(app_ref.get('exe', '')) or '').strip()
                    if not title:
                        continue
                    existing = str(app_ref.get('trainer_path') or '').strip()
                    if existing and os.path.exists(existing):
                        skipped += 1
                        _UI_INVOKER.invoke(lambda i=index, t=total, name=title: _set_bulk_status(f'({i}/{t}) Already downloaded: {name}'))
                        continue
                    _UI_INVOKER.invoke(lambda i=index, t=total, name=title: _set_bulk_status(f'({i}/{t}) Searching: {name}…'))
                    destination = ''
                    try:
                        candidates = manager.search_trainer_candidates(title)
                        if candidates:
                            destination = manager.download_trainer_candidates(candidates, title, settings)
                    except Exception:
                        destination = ''
                    if destination:
                        downloaded += 1
                        app_ref['trainer_path'] = destination
                        self._save_data()
                        _UI_INVOKER.invoke(lambda i=index, t=total, name=title: _set_bulk_status(f'({i}/{t}) Downloaded: {name}'))
                        _UI_INVOKER.invoke(_refresh_downloaded_trainers)
                    else:
                        failed += 1
                        _UI_INVOKER.invoke(lambda i=index, t=total, name=title: _set_bulk_status(f'({i}/{t}) No trainer found: {name}'))

                def _finish_bulk():
                    bulk_btn.setText('Download All')
                    if bulk_state['cancel']:
                        _set_bulk_status(f'Cancelled — downloaded {downloaded}, skipped {skipped}, failed {failed}.')
                    else:
                        _set_bulk_status(f'Finished — downloaded {downloaded}, skipped {skipped}, failed {failed} of {total}.')
                    _refresh_downloaded_trainers()
                    refresh_trainer(combo.currentIndex())
                _UI_INVOKER.invoke(_finish_bulk)

            threading.Thread(target=_worker, daemon=True, name='PanelTrainerBulkDownload').start()

        bulk_state = {'cancel': False}
        panel.add(downloaded_block)
        _refresh_downloaded_trainers()

    def _build_panel_audio(self, panel, s):
        # Each cue (toggle + current file + its three actions) used to be five
        # separate flow items, so the flow-wrap could split a cue across rows
        # and butt its "Remove" button up against the next cue's toggle,
        # making them look like they belonged together. Now each cue is one
        # self-contained card, so a row break can only ever fall between
        # cues, never inside one.
        def add_cue(key, title):
            enabled_key = 'switching_audio_%s_enabled' % key
            file_key = 'switching_audio_%s_file' % key

            cb = ToggleSwitchRow(title)
            cb.setChecked(bool(s.get(enabled_key, True)))
            cb.toggled.connect(lambda c, k=enabled_key: _safe_call(lambda: self._save_setting_now(**{k: cb.isChecked()})))

            lbl = QLabel('')
            lbl.setWordWrap(True)
            lbl.setMinimumWidth(200)
            lbl.setStyleSheet('color:#9eabd8;background:rgba(255,255,255,7);border:1px solid rgba(255,255,255,22);border-radius:8px;padding:6px 9px;font-size:10px;')

            choose_btn = self._panel_action_button('Choose File', lambda k=key: self._panel_choose_switching_audio(k, refresh_lbl))
            preview_btn = self._panel_action_button('Preview', lambda k=key: self._panel_preview_switching_audio(k))
            remove_btn = self._panel_action_button('Remove', lambda k=key: self._panel_clear_switching_audio(k, refresh_lbl))
            for b in (choose_btn, preview_btn, remove_btn):
                b.setFixedHeight(32)

            def refresh_lbl():
                p2 = str(self.data.get('settings', {}).get(file_key, '') or '')
                lbl.setText(os.path.basename(p2) if p2 else 'Built-in tone')
                # Nothing to remove once it's already the built-in tone.
                remove_btn.setEnabled(bool(p2))

            cue_card = QWidget()
            cue_l = QVBoxLayout(cue_card)
            cue_l.setContentsMargins(10, 8, 10, 8)
            cue_l.setSpacing(6)
            cue_l.addWidget(cb)
            cue_l.addWidget(lbl)
            btn_row = QHBoxLayout()
            btn_row.setSpacing(6)
            btn_row.addWidget(choose_btn)
            btn_row.addWidget(preview_btn)
            btn_row.addWidget(remove_btn)
            cue_l.addLayout(btn_row)
            self._panel_card(cue_card)
            panel.add(cue_card)
            refresh_lbl()
        add_cue('navigation', 'Game Switch')
        add_cue('category', 'Category Switch')
        add_cue('launch', 'Game Launch')
        add_cue('settings', 'Settings Open')

    def _panel_section_column(self, panel, title):
        """
        One self-contained column per section. Title labels are no longer
        rendered (removed per request) -- only the stacked options for
        each column are shown; columns still sit side by side via the
        FlowLayout since this widget carries no fullWidth flag.
        """
        col = QWidget()
        col_l = QVBoxLayout(col)
        col_l.setContentsMargins(0, 0, 0, 0)
        col_l.setSpacing(8)
        panel.add(col)
        return col, col_l

    def _build_panel_system(self, panel, s):
        # --- Auto rotation ---------------------------------------------------
        rot_col, rot_l = self._panel_section_column(panel, 'Auto rotation')
        rot = self._panel_toggle(panel, 'Rotate background automatically', 'app_bg_rotate_enabled', False, container=rot_l)
        rot.toggled.disconnect()
        # Toggle widget hidden from the panel per request, but the setting
        # and rotation logic keep working off its (unseen) checked state.
        rot.parent().setVisible(False)
        rot.parent().setMaximumHeight(0)

        def rot_changed(c):
            _safe_call(lambda: self._save_setting_now(app_bg_rotate_enabled=rot.isChecked(), app_bg_rotate_last_ts=0.0))
            if rot.isChecked():
                self._maybe_rotate_app_background(force=True)
        rot.toggled.connect(rot_changed)
        spin = QSpinBox()
        spin.setRange(1, 720)
        spin.setSuffix(' h')
        spin.setValue(int(s.get('app_bg_rotate_interval_hours', 24) or 24))
        spin.setFixedHeight(36)
        spin.setMinimumWidth(150)
        spin.setStyleSheet('QSpinBox{background:rgba(255,255,255,10);color:#e4e8ff;border:1px solid rgba(255,255,255,40);border-radius:9px;padding:6px 10px;}QSpinBox:focus{border:1px solid rgba(255,255,255,115);}')
        spin.valueChanged.connect(lambda v: _safe_call(lambda: self._save_setting_now(app_bg_rotate_interval_hours=spin.value(), app_bg_rotate_last_ts=0.0)))
        _spin_cap = QLabel('Change every')
        _spin_cap.setFont(QFont('Segoe UI', 9, QFont.Weight.Bold))
        _spin_cap.setStyleSheet('color:#c6d0f5;background:transparent;border:none;')
        _spin_block = QWidget()
        _spin_l = QVBoxLayout(_spin_block)
        _spin_l.setContentsMargins(10, 8, 10, 8)
        _spin_l.setSpacing(2)
        _spin_l.addWidget(_spin_cap)
        _spin_l.addWidget(spin)
        self._panel_card(_spin_block)
        rot_l.addWidget(_spin_block)
        rot_l.addWidget(self._panel_action_button('Change Now (Wallpaper)', lambda: self._apply_random_app_background()))

        # --- FPS overlay ---------------------------------------------------
        # Rewritten from scratch.  One source of truth (settings dict), one
        # widget class (OverlayMetricToggle), one write path
        # (_set_overlay_metric).  Every switch is its own block directly in
        # the column so gamepad up/down moves through them one by one.
        fps_col, fps_l = self._panel_section_column(panel, 'FPS overlay')
        self._fps_panel_cbs = {}
        _fps_defs = [('fps', 'FPS'), ('cpu', 'CPU Usage'), ('cpu_temp', 'CPU Temperature'), ('gpu', 'GPU Usage'), ('gpu_temp', 'GPU Temperature'), ('gpu_model', 'GPU Model'), ('pd1', 'PD1'), ('id', 'ID (Input → Display)')]
        current = dict(DEFAULT_SETTINGS['fps_overlay_metrics'])
        current.update(self.data.get('settings', {}).get('fps_overlay_metrics', {}) or {})
        for key, label in _fps_defs:
            tg = OverlayMetricToggle(label)
            tg.set_state_silent(bool(current.get(key, True)))
            # Connected AFTER the initial state is set, and only ever fires
            # for real user activations (see OverlayMetricToggle).
            tg.toggled.connect(lambda checked, k=key: self._set_overlay_metric(k, checked))
            block = QWidget()
            bl = QVBoxLayout(block)
            bl.setContentsMargins(10, 6, 10, 6)
            bl.setSpacing(0)
            bl.addWidget(tg)
            self._panel_card(block)
            fps_l.addWidget(block)
            self._fps_panel_cbs[key] = tg

        # --- Lossless Scaling ---------------------------------------------------
        ls_col, ls_l = self._panel_section_column(panel, 'Lossless Scaling')
        ls = self._panel_edit(panel, 'Lossless Scaling path', 'lossless_scaling_path', r'C:\Program Files\Lossless Scaling\LosslessScaling.exe', container=ls_l)

        def browse_ls():
            path, _ = QFileDialog.getOpenFileName(self, 'Select Lossless Scaling executable', ls.text() or '', 'Executable (*.exe)')
            if path:
                ls.setText(path)
                self._save_setting_now(lossless_scaling_path=path)
        ls_l.addWidget(self._panel_action_button('Browse…', browse_ls))

        # --- Download APIs ---------------------------------------------------
        api_col, api_l = self._panel_section_column(panel, 'Download APIs')
        self._panel_edit(panel, 'SteamGridDB API key', 'steamgriddb_api_key', container=api_l)
        self._panel_edit(panel, 'IGDB Client ID', 'igdb_client_id', container=api_l)
        self._panel_edit(panel, 'IGDB Client Secret', 'igdb_client_secret', password=True, container=api_l)
        self._panel_edit(panel, 'RAWG API key', 'rawg_api_key', password=True, container=api_l)

        # --- Game booster ---------------------------------------------------
        gb_col, gb_l = self._panel_section_column(panel, 'Game booster')
        _sub = ('booster_enabled', 'booster_trim_ram', 'booster_process_priority_enabled', 'booster_allow_high_priority', 'booster_power_plan', 'booster_disable_gamedvr', 'booster_nvidia_perf_mode', 'booster_core_parking_off', 'booster_affinity_pcores', 'booster_stop_services', 'booster_suppress_notifications', 'booster_battery_aware', 'process_tree_isolation')
        _sub_def = {'booster_battery_aware': False}
        master_on = all(bool(s.get(k, _sub_def.get(k, True))) for k in _sub) and str(s.get('booster_priority_mode', 'normal')) == 'high'
        master = ToggleSwitchRow('Booster')
        master.setChecked(master_on)

        def on_master(c):
            s2 = dict(self.data.get('settings', {}))
            for k in _sub:
                s2[k] = bool(c)
            s2['booster_priority_mode'] = 'high' if c else 'normal'
            self._apply_settings(s2, quiet=True)
        master.toggled.connect(on_master)
        _master_block = QWidget()
        _master_l = QVBoxLayout(_master_block)
        _master_l.setContentsMargins(10, 6, 10, 6)
        _master_l.setSpacing(0)
        _master_l.addWidget(master)
        self._panel_card(_master_block)
        gb_l.addWidget(_master_block)
        mem = QSpinBox()
        mem.setLocale(QLocale(QLocale.Language.English, QLocale.Country.UnitedStates))
        mem.setRange(0, 65536)
        mem.setSuffix(' MB')
        mem.setSpecialValueText('Unlimited')
        mem.setValue(int(s.get('cache_memory_limit_mb', DEFAULT_SETTINGS['cache_memory_limit_mb'])))
        mem.setFixedHeight(36)
        mem.setMinimumWidth(170)
        mem.setStyleSheet('QSpinBox{background:rgba(255,255,255,10);color:#e4e8ff;border:1px solid rgba(255,255,255,40);border-radius:9px;padding:6px 10px;}QSpinBox:focus{border:1px solid rgba(255,255,255,115);}')
        mem.valueChanged.connect(lambda v: _safe_call(lambda: self._save_setting_now(cache_memory_limit_mb=mem.value())))
        _mem_cap = QLabel('Cache memory limit')
        _mem_cap.setFont(QFont('Segoe UI', 9, QFont.Weight.Bold))
        _mem_cap.setStyleSheet('color:#c6d0f5;background:transparent;border:none;')
        _mem_block = QWidget()
        _mem_l = QVBoxLayout(_mem_block)
        _mem_l.setContentsMargins(10, 8, 10, 8)
        _mem_l.setSpacing(2)
        _mem_l.addWidget(_mem_cap)
        _mem_l.addWidget(mem)
        self._panel_card(_mem_block)
        gb_l.addWidget(_mem_block)
        gb_l.addWidget(self._panel_action_button('Purge Cache Now', lambda: (_purge_all_caches(), self._show_slide_toast('Cache purged!', hold_ms=1500)), danger=True))

    def _set_nav_section(self, key):
        self._active_section = key
        self._update_nav_section_styles()

    def _update_nav_section_styles(self):
        for key, btn in self._nav_sections:
            if key == self._active_section:
                btn.setStyleSheet("QPushButton {  font-family:'Vazirmatn','Segoe UI'; font-size:14px; font-weight:bold;  color:#ffffff; background:rgba(255,255,255,12);  border:none; border-left:3px solid rgba(180,200,255,230);  text-align:left; padding-left:10px; border-radius:4px;}")
            else:
                btn.setStyleSheet("QPushButton {  font-family:'Vazirmatn','Segoe UI'; font-size:14px; font-weight:bold;  color:rgba(255,255,255,140); background:transparent;  border:none; text-align:left; padding-left:10px;}QPushButton:hover{color:#ffffff;background:rgba(255,255,255,10);border-radius:6px;}")

    def _rebuild_left_nav_categories(self):
        if not hasattr(self, '_cat_wheel'):
            return
        # Respect the same manual order the main library row uses
        # (folder_order, reorderable there by dragging folder tiles, and
        # here by dragging wheel tabs -- both write to the same list, so
        # reordering in either place keeps them in sync). Any folder not
        # yet in folder_order (e.g. just created) falls back to
        # alphabetical, appended after the ones already ordered.
        ordered = self._ordered_category_folders()
        tabs = [(f, f) for f in ordered if f != '__other__']
        if '__other__' in ordered:
            tabs.append(('Other', '__other__'))
        if self._active_filter not in ordered:
            self._active_filter = ordered[0] if ordered else None
        self._cat_wheel.set_categories(tabs, self._active_filter)

    def _on_category_reorder(self, from_key, to_key):
        """Handle CategoryWheel.categoryReordered (mouse drag on a wheel
        tab). '__other__' is a virtual, non-reorderable tab (there's no
        real folder behind it), so any drag involving it is ignored.
        Otherwise this is the same move-and-shift used for folder_order
        elsewhere, keyed by folder name instead of row index since the
        wheel only knows about folders that currently have apps in them."""
        if from_key == to_key or from_key == '__other__' or to_key == '__other__':
            return
        order = self.data.setdefault('folder_order', [])
        if from_key not in order or to_key not in order:
            # Not yet tracked (e.g. brand-new folder) -- seed it from the
            # wheel's current alphabetical-fallback order so the drag has
            # something concrete to reposition within.
            folders_used = []
            for app in self.data.get('apps', []):
                fn = app.get('folder', '')
                if fn and fn not in folders_used:
                    folders_used.append(fn)
            ordered_names = [f for f in order if f in folders_used]
            for f in sorted(folders_used, key=str.lower):
                if f not in ordered_names:
                    ordered_names.append(f)
            order[:] = ordered_names
            if from_key not in order or to_key not in order:
                return
        ai = order.index(from_key)
        bi = order.index(to_key)
        orig_ai, orig_bi = (ai, bi)
        order.pop(ai)
        if ai < bi:
            bi -= 1
        insert_at = bi if orig_ai > orig_bi else bi + 1
        order.insert(insert_at, from_key)
        self._save_data()
        self._rebuild_left_nav_categories()
        self.refresh_tiles()

    def _make_right_info_panel(self):
        w = QWidget()
        w.setFixedWidth(310)
        w.setStyleSheet('background:transparent;')
        vl = QVBoxLayout(w)
        vl.setContentsMargins(16, 20, 36, 24)
        vl.setSpacing(8)

        def _shadow(blur=8, alpha=160):
            fx = QGraphicsDropShadowEffect()
            fx.setBlurRadius(blur)
            fx.setColor(QColor(0, 0, 0, alpha))
            fx.setOffset(1, 1)
            return fx
        self._right_cover_lbl = QLabel()
        self._right_cover_lbl.setFixedSize(258, 148)
        self._right_cover_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self._right_cover_lbl.setStyleSheet('background:rgba(255,255,255,7);border:1px solid rgba(255,255,255,18);border-radius:14px;color:rgba(180,180,220,120);font-size:32px;')
        cover_shadow = QGraphicsDropShadowEffect()
        cover_shadow.setBlurRadius(30)
        cover_shadow.setColor(QColor(0, 0, 0, 120))
        cover_shadow.setOffset(0, 4)
        self._right_cover_lbl.setGraphicsEffect(cover_shadow)
        vl.addWidget(self._right_cover_lbl)
        self._ps5_title_lbl = QLabel('')
