    def _play_selected_game(self):
        if self._current_selected_app:
            self._launch(self._current_selected_app)

    def _turn_off_pad(self, path: str, pid: int, idx: int):
        _haptic_failure('turn-off REQUESTED path=%s pid=%s idx=%s', path, pid, idx)

        def _worker():
            result = _pad_turn_off(path, pid)
            _haptic_failure('turn-off RESULT=%s path=%s', result, path)
            if result == 'usb_only':
                _UI_INVOKER.invoke(lambda: self._show_turnoff_notice(idx))
            elif result != 'ok':
                _UI_INVOKER.invoke(lambda: self._show_turnoff_failure(idx, result))
        threading.Thread(target=_worker, daemon=True, name=f'TurnOff-{idx}').start()

    def _turn_off_pad_by_path(self, path: str, idx: int):
        pid = dict(self._connected_pads).get(path)
        if pid is None:
            _haptic_failure('turn-off ABORTED path=%s not found in _connected_pads=%r', path, self._connected_pads)
            return
        self._turn_off_pad(path, pid, idx)

    @pyqtSlot(str)
    def _on_pad_mute(self, path: str):
        _haptic_failure('mute SIGNAL RECEIVED in UI path=%s', path)
        row = self._batt_indicators.get(path)
        idx = row.indicator._idx if row is not None else 0
        self._turn_off_pad_by_path(path, idx)

    def _show_turnoff_notice(self, idx: int):
        self._show_slide_toast(f'Controller {idx} is connected via USB', subtitle='Power-off is only possible over Bluetooth.', hold_ms=3750)

    def _show_turnoff_failure(self, idx: int, reason: str):
        messages = {'no_privilege': ('Could not power off Controller {0}', 'Try running the launcher as Administrator.'), 'not_found': ('Could not power off Controller {0}', 'Windows Bluetooth did not report the pad as connected. See pad_debug.log.'), 'error': ('Could not power off Controller {0}', 'Unexpected error — check pad_debug.log for details.')}
        title, subtitle = messages.get(reason, ('Could not power off Controller {0}', f'Reason: {reason}'))
        self._show_slide_toast(title.format(idx), subtitle=subtitle, hold_ms=4500)

    def _tick(self):
        self._refresh_playtime_label()

    def _refresh_playtime_label(self):
        app = getattr(self, '_current_selected_app', None)
        secs = int((app or {}).get('play_seconds', 0) or 0)
        if secs >= 3600:
            time_txt = f'{secs // 3600}h {secs % 3600 // 60}m'
        elif secs >= 60:
            time_txt = f'{secs // 60} min'
        elif secs > 0:
            time_txt = f'{secs} sec'
        else:
            time_txt = ''
        self.time_lbl.setText(time_txt)

    def _set_category_filter(self, key):
        self._active_filter = key
        self.in_preview_row = True
        self.preview_selected_col = 0
        self.selected_col = 0
        self._rebuild_left_nav_categories()
        self._audio_play_event('category', self._current_selected_app)
        if not hasattr(self, '_cat_filter_timer'):
            self._cat_filter_timer = QTimer(self)
            self._cat_filter_timer.setSingleShot(True)
            self._cat_filter_timer.timeout.connect(self.refresh_tiles)
        self._cat_filter_timer.start(80)

    def _apply_edge_adaptive_trigger(self, edge: str):
        lc = getattr(self, '_led_ctrl', None)
        if lc is None:
            return
        s = self.data.get('settings', {})
        if not s.get('adaptive_trigger_enabled', DEFAULT_SETTINGS['adaptive_trigger_enabled']):
            return
        mode = s.get('adaptive_trigger_mode', DEFAULT_SETTINGS['adaptive_trigger_mode'])
        strength = int(s.get('adaptive_trigger_strength', DEFAULT_SETTINGS['adaptive_trigger_strength']))
        if edge == 'first':
            lc.set_adaptive_triggers(l2_mode=mode, l2_strength=strength)
        else:
            lc.set_adaptive_triggers(r2_mode=mode, r2_strength=strength)
        lc._atrig_reset_gen = getattr(lc, '_atrig_reset_gen', 0) + 1
        _my_atrig_gen = lc._atrig_reset_gen
        QTimer.singleShot(600, lambda: lc.set_adaptive_triggers() if getattr(lc, '_atrig_reset_gen', 0) == _my_atrig_gen else None)

    def _ordered_category_folders(self):
        """Folder list in the user's manual folder_order (same ordering
        _rebuild_left_nav_categories uses for the mouse-driven wheel),
        with any folder not yet tracked in folder_order appended
        alphabetically, plus the virtual '__other__' tab at the end.
        Shared by every category-navigation entry point (wheel click,
        gamepad shoulder/dpad step, jump-to-edge) so they can't drift
        out of sync with each other again."""
        folders_used = []
        for app in self.data.get('apps', []):
            fn = app.get('folder', '')
            if fn and fn not in folders_used:
                folders_used.append(fn)
        order = self.data.get('folder_order', [])
        ordered_names = [f for f in order if f in folders_used]
        for f in sorted(folders_used, key=str.lower):
            if f not in ordered_names:
                ordered_names.append(f)
        if any(not (app.get('folder') or '').strip() for app in self.data.get('apps', [])):
            ordered_names.append('__other__')
        return ordered_names

    def _category_jump_to_edge(self, edge: str):
        folders = self._ordered_category_folders()
        if len(folders) <= 1:
            return
        target = folders[0] if edge == 'first' else folders[-1]
        cur = self._active_filter if self._active_filter in folders else folders[0]
        if cur == target:
            self._apply_edge_adaptive_trigger(edge)
            return
        self._set_category_filter(target)
        self._nav_haptic('category')
        self._apply_edge_adaptive_trigger(edge)

    def _category_navigate(self, delta: int, context: str | None=None):
        self._nav_haptic('category', context=context or ('category-left' if delta < 0 else 'category-right'))
        folders = self._ordered_category_folders()
        if len(folders) <= 1:
            return
        cur = self._active_filter if self._active_filter in folders else folders[0]
        idx = folders.index(cur)
        new_idx = (idx + delta) % len(folders)
        self._set_category_filter(folders[new_idx])
        if new_idx == 0:
            self._apply_edge_adaptive_trigger('first')
        elif new_idx == len(folders) - 1:
            self._apply_edge_adaptive_trigger('last')

    def _nav_haptic(self, kind: str, context: str | None=None):
        self._haptic.tick(kind, context=context)

