    def _auto_repair_internal_folder_titles(self) -> int:
        fixed = 0
        for app in self.data.get('apps', []):
            exe = app.get('exe') or ''
            old_title = (app.get('title') or '').strip()
            if not exe or not old_title or (not os.path.exists(exe)):
                continue
            real_path = _real_path_for_root_detection(exe)
            cur = os.path.dirname(os.path.abspath(real_path))
            suspect = False
            for _ in range(8):
                name = os.path.basename(cur).strip()
                if not name:
                    break
                if name.lower() in _INTERNAL_SUBFOLDER_NAMES:
                    cleaned = _clean_folder_name_to_title(name)
                    alias_title = canonical_title(name) if is_known_game(name) else None
                    cleaned_l = cleaned.lower() if cleaned else ''
                    old_l = old_title.lower()
                    trailing_ok = False
                    if cleaned_l and old_l.startswith(cleaned_l):
                        remainder = old_title[len(cleaned):].strip()
                        trailing_ok = remainder == '' or remainder.isdigit()
                    if cleaned and cleaned_l == old_l or (alias_title and alias_title.lower() == old_l) or trailing_ok:
                        suspect = True
                        break
                parent = os.path.dirname(cur)
                if not parent or parent == cur:
                    break
                cur = parent
            if not suspect:
                continue
            game_root = _find_game_root_folder(real_path)
            new_title = _scan_guess_title(real_path, game_root=game_root)
            new_title = (new_title or '').strip()
            if new_title and new_title.lower() != old_title.lower():
                app['title'] = new_title
                fixed += 1
                try:
                    self._queue_auto_background(app, force=True)
                except Exception:
                    pass
        if fixed:
            self._save_data()
        return fixed

    def _load_data(self) -> dict:
        load_path = DB_FILE
        if not os.path.exists(load_path) and os.path.exists(LEGACY_DB_FILE):
            load_path = LEGACY_DB_FILE
        if os.path.exists(load_path):
            try:
                with open(load_path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    data.setdefault('apps', [])
                    data.setdefault('folders', {})
                    data.setdefault('folder_order', [])
                    data.setdefault('settings', {})
                    _one_time_reset_gamepad_button_mapping(data)
                    if load_path != DB_FILE:
                        try:
                            shutil.copyfile(load_path, DB_FILE)
                        except Exception:
                            pass
                    return data
            except Exception as e:
                try:
                    backup_path = load_path + '.corrupt'
                    import shutil as _shutil
                    _shutil.copyfile(load_path, backup_path)
                except Exception as backup_err:
                    pass
                recovery_path = load_path + '.bak'
                if os.path.exists(recovery_path):
                    try:
                        with open(recovery_path, 'r', encoding='utf-8') as f:
                            recovered = json.load(f)
                        if isinstance(recovered, dict):
                            recovered.setdefault('apps', [])
                            recovered.setdefault('folders', {})
                            recovered.setdefault('folder_order', [])
                            recovered.setdefault('settings', {})
                            _one_time_reset_gamepad_button_mapping(recovered)
                            return recovered
                    except Exception as recovery_err:
                        pass
        return {'apps': [], 'folders': {}, 'folder_order': [], 'settings': {}}

    def _save_data(self):
        if threading.current_thread() is not threading.main_thread():
            _UI_INVOKER.invoke(self._save_data)
            return
        if getattr(self, '_shutting_down', False):
            # Shutdown already started (and already did a synchronous
            # flush) -- don't arm a new debounce timer that would fire
            # after the storage pool is gone. Write synchronously instead
            # so nothing gets lost.
            self._data_dirty = True
            self._flush_data_save(force_sync=True)
            return
        self._data_dirty = True
        if not hasattr(self, '_save_debounce_timer'):
            self._save_debounce_timer = QTimer(self)
            self._save_debounce_timer.setSingleShot(True)
            self._save_debounce_timer.timeout.connect(self._flush_data_save)
        self._save_debounce_timer.start(600)

    def _flush_data_save(self, force_sync: bool=False):
        if not getattr(self, '_data_dirty', False):
            return
        self._data_dirty = False
        if hasattr(self, '_save_debounce_timer'):
            self._save_debounce_timer.stop()
        if not hasattr(self, '_data_save_lock'):
            self._data_save_lock = threading.Lock()
        import copy
        try:
            snapshot = copy.deepcopy(self.data)
        except Exception as e:
            return

        def _write():
            with self._data_save_lock:
                tmp_path = None
                try:
                    dir_name = os.path.dirname(os.path.abspath(DB_FILE)) or '.'
                    fd, tmp_path = _tempfile.mkstemp(prefix='.apps_', suffix='.tmp', dir=dir_name)
                    with os.fdopen(fd, 'w', encoding='utf-8') as f:
                        json.dump(snapshot, f, ensure_ascii=False, indent=2)
                        f.flush()
                        os.fsync(f.fileno())
                    if os.path.exists(DB_FILE):
                        try:
                            shutil.copy2(DB_FILE, DB_FILE + '.bak')
                        except OSError as backup_err:
                            pass
                    os.replace(tmp_path, DB_FILE)
                except Exception as e:
                    if tmp_path and os.path.exists(tmp_path):
                        try:
                            os.remove(tmp_path)
                        except OSError:
                            pass
        if force_sync:
            _write()
        else:
            try:
                _STORAGE_POOL.submit(_write)
            except RuntimeError:
                # Storage pool was already shut down (app closing) between
                # the debounce timer being armed and firing -- write
                # synchronously instead of dropping the save or crashing.
                _write()

    def _get_ordered(self):
        order = self.data.get('folder_order', [])
        all_folders = list(self.data.get('folders', {}).keys())
        for fn in all_folders:
            if fn not in order:
                order.append(fn)
        folders = [f for f in order if f in self.data.get('folders', {})]
        uncategorized = [a for a in self.data.get('apps', []) if not a.get('folder')]
        return (folders, uncategorized)

    def _add_folder(self):
        self._create_folder()

    def _reload_refresh(self):
        self.data = self._load_data()
        _sync_module_settings_from_data(self.data)
        self.refresh_tiles()

    def _enter_startup_idle_audio(self):
        if not getattr(self, '_startup_idle', False):
            return
        if hasattr(self, 'central'):
            self.central.set_background('')
        self._startup_idle_audio_pending = False

    def _enter_bare_bg_mode(self):
        if hasattr(self, '_top_bar_widget'):
            self._top_bar_widget.hide()
        if hasattr(self, '_main_area'):
            self._main_area.hide()
        if hasattr(self, '_bottom_bar_widget'):
            self._bottom_bar_widget.hide()
        # If the settings drawer was left open, it's the only child left
        # visible in the central layout once the widgets above are hidden,
        # so it ends up floating alone in the middle of the screen the next
        # time the window is shown. Snap it closed immediately instead of
        # letting it linger open while hidden in the tray.
        drawer = getattr(self, '_settings_drawer', None)
        if drawer is not None:
            anim = getattr(self, '_settings_drawer_anim', None)
            if anim is not None and anim.state() == QAbstractAnimation.State.Running:
                anim.stop()
            self._settings_layout_generation = getattr(self, '_settings_layout_generation', 0) + 1
            self._settings_layout_transition = False
            self._apply_settings_drawer_dim(False)
            drawer.setMaximumHeight(0)
            drawer.setMinimumHeight(0)
            drawer.hide()
        if hasattr(self, '_name_logo_lbl'):
            self._name_logo_lbl.hide()
            self._logo_needs_entrance = True
        if hasattr(self, '_tile_name_lbl'):
            self._tile_name_lbl.hide()
            self._tile_name_needs_entrance = True
        if hasattr(self, '_float_play_btn'):
            self._float_play_btn.hide()
            self._play_btn_needs_entrance = True
        if hasattr(self, 'time_lbl'):
            self.time_lbl.hide()
        if hasattr(self, '_batt_container'):
            self._batt_container.hide()

    def _fade_widget_in_opacity_only(self, widget, duration=260):
        """Fade-only entrance for a widget that is itself managed by a
        layout (e.g. a direct child of central's QVBoxLayout). Animating
        such a widget's pos/geometry directly fights the layout manager,
        which keeps resetting it back to its computed slot — that fight is
        what caused the persistent jitter, not the easing curve. Opacity
        is a paint-time property, so it doesn't touch geometry and is safe
        to animate on a layout-managed widget."""
        if widget is None:
            return
        try:
            if not widget.isVisible():
                return
        except RuntimeError:
            return
        effect = QGraphicsOpacityEffect(widget)
        effect.setOpacity(0.0)
        widget.setGraphicsEffect(effect)
        anim = QPropertyAnimation(effect, b'opacity', effect)
        anim.setDuration(duration)
        anim.setStartValue(0.0)
        anim.setEndValue(1.0)
        anim.setEasingCurve(QEasingCurve.Type.OutCubic)

        def _clear_effect(w=widget):
            try:
                w.setGraphicsEffect(None)
            except RuntimeError:
                pass
        anim.finished.connect(_clear_effect)
        widget._entrance_anim = anim
        anim.start()

    def _exit_bare_bg_mode(self):
        _entrance_widgets = []
        if hasattr(self, '_top_bar_widget'):
            self._top_bar_widget.show()
            self._fade_widget_in_opacity_only(self._top_bar_widget, duration=260)
        if hasattr(self, '_main_area'):
            # _main_area (and the top/bottom bars above/below) are direct
            # children of central's QVBoxLayout, so — same reasoning as
            # the tiles inside it — it must never be pos-animated. Its
            # tiles already fade themselves in individually, so just show
            # it plainly.
            self._main_area.show()
        if hasattr(self, '_bottom_bar_widget'):
            self._bottom_bar_widget.show()
            self._fade_widget_in_opacity_only(self._bottom_bar_widget, duration=260)
        if hasattr(self, 'time_lbl'):
            self.time_lbl.show()
            self.time_lbl.raise_()
            self._reposition_clock()
            _entrance_widgets.append(self.time_lbl)
        if hasattr(self, '_batt_container') and getattr(self, '_batt_indicators', None):
            self._batt_container.show()
            self._batt_container.raise_()
            self._reposition_batt_container()
            _entrance_widgets.append(self._batt_container)
        self.in_preview_row = True
        self.selected_col = 0
        self.preview_selected_col = 0
        self._pending_idle_exit_entrance = True
        if _entrance_widgets:
            # time_lbl and _batt_container are floating children of
            # `central` directly (positioned manually via _reposition_*),
            # not layout children, so a real pos+fade entrance is safe
            # for them.
            self._animate_widgets_in(_entrance_widgets, stagger=40, rise=42, duration=260, opacity_duration=260, bounce=False)

    def _exit_startup_idle(self):
        self._startup_idle = False
        self._exit_bare_bg_mode()
        self._stop_audio_theme(clear_session=False)
        self._suppress_info_panel_audio = True
        self.refresh_tiles()
        self._suppress_info_panel_audio = False
        if getattr(self, 'in_preview_row', False):
            items = getattr(self, '_preview_items', [])
            idx = getattr(self, 'preview_selected_col', 0)
            if 0 <= idx < len(items):
                self._play_audio_theme(items[idx], reason='preview', allow_inactive=True)
        else:
            items = getattr(self, '_all_items', [])
            idx = getattr(self, 'selected_col', 0)
            if 0 <= idx < len(items) and items[idx][0] == 'game':
                self._play_audio_theme(items[idx][1], reason='preview', allow_inactive=True)

    def refresh_tiles(self):
        self._rebuild_left_nav_categories()
        # Widget reuse: pull every tile currently in the row layouts out
        # into a "previous" map keyed by its cache key, WITHOUT deleting
        # them yet. Below, each item that still exists gets its existing
        # widget updated in place (data/selection/signal rebind) instead
        # of a fresh PS5FolderTile/PS5GameTile being constructed -- that
        # construction is the expensive part (image decode/scale, new
        # QPropertyAnimation objects, a new QTimer, etc.), and previously
        # happened for the ENTIRE library on every single refresh_tiles()
        # call, even ones that don't add/remove/reorder anything (e.g.
        # toggling move-mode, exiting the idle screen, a filter re-render
        # with the same items). Only genuinely new/removed items now pay
        # that cost. Layout order/count/positions end up identical to the
        # old destroy-and-rebuild-everything behavior, so scroll position
        # math, keyboard/gamepad navigation (_fast_nav_main/_fast_nav_preview)
        # and everything else that indexes into the layout is unaffected.
        for layout in (self.row_layout, self.preview_row_layout):
            while layout.count():
                it = layout.takeAt(0)
                if it.widget() and layout is self.preview_row_layout:
                    # Preview-row tiles aren't tracked in self._tile_cache
                    # (see _update_preview_row, which still rebuilds them
                    # fresh every call) -- only the main row's tiles are
                    # reused, so preview-row widgets pulled out here must
                    # still be destroyed or they'd leak.
                    it.widget().deleteLater()
        folders, uncategorized = self._get_ordered()
        self._all_items = []
        _new_tiles = []
        _used_keys = set()
        for i, fname in enumerate(folders):
            apps_in = [a for a in self.data.get('apps', []) if a.get('folder') == fname]
            sel = not self.in_preview_row and self.selected_col == i and (self._folder_overlay is None) and (not self._startup_idle)
            key = ('folder', fname)
            _used_keys.add(key)
            tile = self._tile_cache.get(key)
            is_new = tile is None or not isinstance(tile, PS5FolderTile)
            if is_new:
                tile = PS5FolderTile(fname, apps_in, i, selected=sel)
                self._tile_cache[key] = tile
                _new_tiles.append(tile)
            else:
                tile.apps = apps_in
                tile.folder_index = i
                tile.set_selected(sel)
                for sig in (tile.clicked_signal, tile.edit_signal, tile.drop_game, tile.reorder_signal):
                    try:
                        sig.disconnect()
                    except TypeError:
                        pass
            tile.setStyleSheet('border: 2px solid #ff8800; border-radius: 16px;' if self._move_mode and self._move_from_col == i else '')
            tile.clicked_signal.connect(self._open_folder)
            tile.edit_signal.connect(self._folder_edit)
            tile.drop_game.connect(self._drop_to_folder)
            tile.reorder_signal.connect(self._on_row_reorder)
            self.row_layout.addWidget(tile)
            self._all_items.append(('folder', fname))
        if self._active_filter == '__other__':
            uncategorized = [a for a in uncategorized if not a.get('folder')]
        elif self._active_filter is not None:
            uncategorized = [a for a in uncategorized if a.get('folder', '') == self._active_filter]
        for j, app in enumerate(uncategorized):
            global_idx = len(folders) + j
            sel = not self.in_preview_row and self.selected_col == global_idx and (self._folder_overlay is None) and (not self._startup_idle)
            key = ('game', id(app))
            _used_keys.add(key)
            tile = self._tile_cache.get(key)
            is_new = tile is None or not isinstance(tile, PS5GameTile)
            if is_new:
                tile = PS5GameTile(app, j, selected=sel)
                self._tile_cache[key] = tile
                _new_tiles.append(tile)
            else:
                tile.app_data = app
                tile.index = j
                tile.set_selected(sel)
                for sig in (tile.clicked_signal, tile.edit_signal, tile.reorder_signal):
                    try:
                        sig.disconnect()
                    except TypeError:
                        pass
            tile.row_col = global_idx
            tile.setStyleSheet('border: 2px solid #ff8800; border-radius: 16px;' if self._move_mode and self._move_from_col == global_idx else '')
            tile.clicked_signal.connect(lambda _, idx=j, gidx=global_idx, lst=uncategorized: self._on_main_tile_click(gidx, lst[idx]))
            tile.edit_signal.connect(lambda game_idx, action, lst=uncategorized: self._game_edit_dispatch(lst, game_idx, action))
            tile.reorder_signal.connect(self._on_row_reorder)
            self.row_layout.addWidget(tile)
            self.row_layout.setAlignment(tile, Qt.AlignmentFlag.AlignBottom if sel else Qt.AlignmentFlag.AlignTop)
            if sel:
                QTimer.singleShot(0, tile.raise_)
            self._all_items.append(('game', app))
        # Anything left in the cache wasn't reused above -- it's a
        # folder/game that no longer exists in this render (deleted,
        # moved out, filtered out). Drop it from the cache and actually
        # destroy its widget now.
        _stale_keys = [k for k in self._tile_cache if k not in _used_keys]
        for k in _stale_keys:
            self._tile_cache.pop(k).deleteLater()
        if self._preview_move_mode:
            self.hint_lbl.setText('✕ Confirm     ○ Cancel     ↑ Exit Folder     ← →  Move Game')
            self.hint_lbl.setStyleSheet('color:#cc8800; background:transparent; padding:8px 52px; font-weight:bold;')
        elif self._move_mode:
            self.hint_lbl.setText('✕ Drop to Folder     ○ Cancel     ← →  Move Game')
            self.hint_lbl.setStyleSheet('color:#cc8800; background:transparent; padding:8px 52px; font-weight:bold;')
        elif self.in_preview_row:
            self.hint_lbl.setText('↑ Top Bar     ← →  Navigate     ✕ Run     □ Edit     ○ Back')
            self.hint_lbl.setStyleSheet('color:#4455aa; background:transparent; padding:8px 52px;')
        else:
            self.hint_lbl.setText('← →  Navigate     ↓ Bottom Bar     ✕ Run/Folder     □ Edit     △ Refresh')
            self.hint_lbl.setStyleSheet('color:#333355; background:transparent; padding:8px 52px;')
        spacing, margin_h, margin_v = (0, 20, 4)
        TILE_W, TILE_H = (153, 153)
        TILE_H_SEL = int(TILE_H * 1.3) + int(TILE_H * 0.01)
        self.row_layout.setSpacing(spacing)
        self.row_layout.setContentsMargins(margin_h, 4, margin_h, 4)
        n_main = self.row_layout.count()
        TILE_W_SEL = int(TILE_W * 1.3)
        main_tw = margin_h + n_main * TILE_W + max(0, n_main - 1) * spacing + margin_h + (TILE_W_SEL - TILE_W)
        main_th = margin_v + TILE_H_SEL + margin_v
        self.row_widget.setFixedSize(max(main_tw, max(self.scroll.viewport().width(), 1)), max(main_th, 1))
        self.scroll.setFixedHeight(main_th)
        self._update_preview_row()
        if self._startup_idle:
            self._clear_right_panel()
            self.info_panel.hide()
        else:
            self._update_info_panel()
        if self._all_items:
            self.selected_col = max(0, min(self.selected_col, len(self._all_items) - 1))
        else:
            self.selected_col = 0
        QTimer.singleShot(0, self._scroll_to_sel)
        self._schedule_tile_name_reposition()
        QTimer.singleShot(0, self.setFocus)
        if _new_tiles and not getattr(self, '_pending_idle_exit_entrance', False):
            self._animate_widgets_in(_new_tiles, stagger=15, rise=34, duration=260, fade=False)
            _sel_new_tile = None
            for _t in _new_tiles:
                if getattr(_t, '_selected', False):
                    _sel_new_tile = _t
                    break
            if _sel_new_tile is not None:
                QTimer.singleShot(1, lambda t=_sel_new_tile: self._hook_entrance_finish_reposition(t))
        self._pending_idle_exit_entrance = False
        self._input_ready = True
        if hasattr(self, '_preload'):
            self._preload.schedule([app for kind, app in self._all_items if kind == 'game'], self.preview_selected_col)

    def _game_edit_dispatch(self, lst, idx, action):
        if 0 <= idx < len(lst):
            self._game_edit(lst[idx], action)

    def _update_preview_row(self):
        spacing, margin_h, margin_v = (0, 20, 4)
        TILE_W, TILE_H = (153, 153)
        TILE_H_SEL = int(TILE_H * 1.3) + int(TILE_H * 0.01)
        self.preview_row_layout.setSpacing(spacing)
        self.preview_row_layout.setContentsMargins(margin_h, 4, margin_h, 4)
        self._preview_items = []
        while self.preview_row_layout.count():
            it = self.preview_row_layout.takeAt(0)
            if it.widget():
                it.widget().deleteLater()
        all_apps = self.data.get('apps', [])
        if self._active_filter == '__other__':
            apps_in = [a for a in all_apps if not a.get('folder')]
        elif self._active_filter is not None:
            apps_in = [a for a in all_apps if a.get('folder', '') == self._active_filter]
        else:
            apps_in = list(all_apps)
        label = 'Other' if self._active_filter == '__other__' else self._active_filter or 'Other'
        if not apps_in:
            self.preview_lbl.setText(f'📁  {label}  —  Empty')
            self.preview_section.show()
            self.preview_scroll.setFixedHeight(0)
            self._game_carousel.set_games([], 0, animate=False)
            self._game_carousel.setFixedHeight(0)
            self._audio_play_event('settings')
            return
        self._preview_items = apps_in
        if self.preview_selected_col >= len(apps_in):
            self.preview_selected_col = max(0, len(apps_in) - 1)
        for k, app in enumerate(apps_in):
            sel = self.preview_selected_col == k and (not self._startup_idle)
            tile = PS5GameTile(app, k, selected=sel)
            if self._preview_move_mode and k == self.preview_selected_col:
                tile.setStyleSheet('border: 2px solid #ff8800; border-radius: 16px;')
            tile.clicked_signal.connect(lambda _, idx=k, lst=apps_in: self._on_preview_tile_click(idx, lst[idx]))
            tile.edit_signal.connect(lambda game_idx, action, lst=apps_in: self._game_edit_dispatch(lst, game_idx, action))
            self.preview_row_layout.addWidget(tile)
            self.preview_row_layout.setAlignment(tile, Qt.AlignmentFlag.AlignBottom if sel else Qt.AlignmentFlag.AlignTop)
            if sel:
                QTimer.singleShot(0, tile.raise_)
        n = len(apps_in)
        TILE_W_SEL = int(TILE_W * 1.3)
        tw = margin_h + n * TILE_W + max(0, n - 1) * spacing + margin_h + (TILE_W_SEL - TILE_W)
        th = margin_v + TILE_H_SEL + margin_v
        self.preview_row_widget.setFixedSize(max(tw, max(self.preview_scroll.viewport().width(), 1)), max(th, 1))
        self.preview_scroll.setFixedHeight(th)
        self.preview_lbl.setText(f'📁  {label}')
        self._game_carousel.set_games(apps_in, self.preview_selected_col, animate=True)
        self._game_carousel.setFixedHeight(GameCarousel._TILE_SEL + 48)
        self.preview_section.show()
        self._schedule_tile_name_reposition()

    def _update_info_panel(self):
        if self.in_preview_row:
            if 0 <= self.preview_selected_col < len(self._preview_items):
                item = self._preview_items[self.preview_selected_col]
                kind = 'game'
            else:
                self._clear_right_panel()
                self.info_panel.hide()
                return
        elif 0 <= self.selected_col < len(self._all_items):
            kind, item = self._all_items[self.selected_col]
        else:
            self._clear_right_panel()
            self.info_panel.hide()
            return
        if kind != 'game':
            self._clear_right_panel()
            self.info_panel.hide()
            return
        self._current_selected_app = item
        if getattr(self, '_suppress_info_panel_audio', False):
            self._suppress_info_panel_audio = False
        else:
            self._play_audio_theme(item, reason='preview')
        exe = item.get('exe', '')
        folder_path = self._find_game_root(exe) if exe else ''
        folder_txt = f'📂  {folder_path}' if folder_path else '📂  Unknown'
        secs = item.get('play_seconds', 0)
        if secs >= 3600:
            time_txt = f'{secs // 3600}h {secs % 3600 // 60}m'
        elif secs >= 60:
            time_txt = f'{secs // 60} min'
        elif secs > 0:
            time_txt = f'{secs} sec'
        else:
            time_txt = 'Not Played Yet'
        self.info_title_lbl.setText(item.get('title', ''))
        self.info_path_lbl.setText(folder_txt)
        self.info_time_lbl.setText(time_txt)
        self._refresh_playtime_label()
        self.info_panel.hide()
        name = item.get('name') or item.get('title') or os.path.basename(item.get('exe', ''))
        if hasattr(self, '_tile_name_lbl'):
            _name_lbl_was_hidden = getattr(self, '_tile_name_needs_entrance', False)
            self._tile_name_needs_entrance = False
            self._tile_name_lbl.setText(name)
            self._tile_name_lbl.adjustSize()
            # The content/layout widgets are still settling during the first
            # startup reveal.  Showing the label before its first valid
            # position makes it briefly appear at the widget's old (0, 0)
            # position, on top of the selected tile.  Keep it hidden until
            # _reposition_tile_name_lbl has a real tile geometry; that method
            # also handles the entrance fade.
            if _name_lbl_was_hidden:
                self._tile_name_lbl.hide()
            self._schedule_tile_name_reposition()
        secs = item.get('play_seconds', 0)
        if secs >= 3600:
            _t = f'{secs // 3600}h {secs % 3600 // 60}m'
        elif secs >= 60:
            _t = f'{secs // 60}m'
        elif secs > 0:
            _t = f'{secs}s'
        else:
            _t = 'Not played yet'
        _exe = item.get('exe', '')
        _path_short = self._find_game_root(_exe) if _exe else ''
        _row2 = _path_short if _path_short else ''
        self._ps5_sub_lbl.setText(_row2)
        self._ps5_time_lbl.setText('')
        self.central.set_background(item.get('background', ''))
        if hasattr(self, '_led_ctrl'):
            self._led_ctrl.request_color(_controller_led_image_for_app(item))
        if hasattr(self, '_preload'):
            # Deliberately AFTER set_background()/request_color() above, not before: this
            # is a best-effort optimization that warms the cache for nearby games, and it
            # used to sit ahead of them guarded only by `except ValueError`. Any other
            # exception here (SmartPreloadManager/QThread state, a bad app entry, etc.)
            # would propagate out of _update_info_panel() and silently abort the rest of
            # the function -- which meant the background image and controller lightbar
            # for the newly-selected game were never requested at all. Since this method
            # re-runs from scratch on every navigation, a game selected while preloading
            # was mid-failure would just look like "the color stopped updating" from then
            # on. Catching Exception (not just ValueError) means a failure here can no
            # longer take the actual selection update down with it.
            visible_games = [app for kind, app in self._all_items if kind == 'game']
            try:
                self._preload.schedule(visible_games, visible_games.index(item))
            except Exception:
                pass
        if hasattr(self, '_name_logo_lbl'):
            self._update_name_logo(item, name)
            self._reposition_name_logo_lbl()
        if hasattr(self, '_right_cover_lbl'):
            self._update_right_cover(item)
        if hasattr(self, '_right_play_btn'):
            self._right_play_btn.setEnabled(True)
        if hasattr(self, '_float_play_btn'):
            self._float_play_btn.setEnabled(True)
            _play_btn_was_hidden = getattr(self, '_play_btn_needs_entrance', False)
            self._play_btn_needs_entrance = False
            self.central.update(self._float_play_btn.geometry())
            self._float_play_btn.show()
            self._float_play_btn.raise_()
            self._float_play_btn._refresh_underlying_background()
            self._reposition_play_btn_float()
            QTimer.singleShot(0, self._reposition_play_btn_float)
            if _play_btn_was_hidden:
                QTimer.singleShot(0, lambda: self._animate_widget_fade_in(self._float_play_btn, duration=900))
        if folder_path and os.path.isdir(folder_path):
            if folder_path in self._dir_size_cache:
                _sz = self._fmt_size(self._dir_size_cache[folder_path])
                self._ps5_size_lbl.setText(_sz)
                self.info_size_lbl.setText(_sz)
            else:
                self._ps5_size_lbl.setText('Calculating…')
                self.info_size_lbl.setText('Calculating…')
                self._calc_dir_size_async(folder_path)
        else:
            self._ps5_size_lbl.setText('')
            self.info_size_lbl.setText('')

    def _hook_entrance_finish_reposition(self, tile):
        anim = getattr(tile, '_entrance_anim', None)
        if anim is None:
            return
        try:
            anim.finished.disconnect(self._reposition_tile_name_lbl)
        except TypeError:
            pass
        anim.finished.connect(self._reposition_tile_name_lbl)

    def _schedule_tile_name_reposition(self):
        """Retry after layout/entrance animations have produced real geometry."""
        generation = getattr(self, '_settings_layout_generation', 0)
        # A drawer animation changes the height of the central layout, and
        # Qt may propagate that change through the scroll-area/layout chain
        # one turn after the animation's finished signal.  The old schedule
        # could show the label using the stale tile position on the first
        # open/close cycle; navigating to another game happened to correct it.
        for delay in (0, 16, 35, 80, 150, 250, 500, 900, 1200):
            QTimer.singleShot(delay, lambda g=generation: self._reposition_tile_name_for_generation(g))

    def _reposition_tile_name_for_generation(self, generation):
        if generation != getattr(self, '_settings_layout_generation', 0):
            return
        self._reposition_tile_name_lbl()

    def _reposition_tile_name_lbl(self):
        lbl = self._tile_name_lbl
        if not lbl.text() or getattr(self, '_startup_idle', False) or getattr(self, '_settings_layout_transition', False):
            lbl.hide()
            return
        # Make sure the geometry used below belongs to the current drawer
        # state, not to the previous event-loop pass.
        self._reposition_tile_name_after_layout()

    def _position_tile_name_lbl(self):
        """Position the floating game name using the current tile geometry."""
        lbl = self._tile_name_lbl
        if not lbl.text() or getattr(self, '_startup_idle', False) or getattr(self, '_settings_layout_transition', False):
            lbl.hide()
            return
        if self.in_preview_row:
            car = self._game_carousel
            if car is None or car.width() <= 0 or car.height() <= 0:
                return
            # Keep one fixed anchor for the whole carousel animation.  Do not
            # move the label to collision-avoidance candidates here: while
            # navigating, neighbouring tiles pass underneath this area and
            # those candidates make the perceived gap grow on every step.
            tile_rect_f = car.tile_rect_for_index(car.selected_index())
            if tile_rect_f is None:
                return
            tile_rect = tile_rect_f.toRect()
            lbl.adjustSize()
            tile_top_left = car.mapTo(self.central, tile_rect.topLeft())
            selected_rect = QRect(tile_top_left, tile_rect.size())
            # These are the same fixed offsets used by the original closed
            # drawer position.  Calculate them from the current painted tile
            # so the distance remains unchanged while the tile animates.
            x = selected_rect.right() + 10
            # Keep the title close to the selected tile.  The previous
            # positive gap put it noticeably too low after the drawer was
            # opened; use the same compact visual anchor in both states.
            y = max(4, selected_rect.bottom() - 18 - lbl.height())
            # The carousel can still report a stale width/height for one or
            # more event-loop turns right after the settings drawer closes
            # (its own resize lags behind the outer layout activation done
            # in _reposition_tile_name_after_layout).  When that happens the
            # anchor above is computed from the wrong tile geometry and the
            # label lands on top of a neighbouring tile.  Guard against that
            # by checking the anchor against every currently painted tile
            # and nudging it clear if it overlaps one.
            name_rect = QRect(x, y, lbl.width(), lbl.height())
            other_rects = []
            for rect, idx in car.visible_tile_rects():
                if idx == car.selected_index():
                    continue
                top_left = car.mapTo(self.central, rect.toRect().topLeft())
                other_rects.append(QRect(top_left, rect.toRect().size()))
            if any(name_rect.intersects(r) for r in other_rects):
                fallback_y = max(4, selected_rect.bottom() + 12)
                fallback_rect = QRect(x, fallback_y, lbl.width(), lbl.height())
                if not any(fallback_rect.intersects(r) for r in other_rects):
                    y = fallback_y
                else:
                    x = selected_rect.left()
                    y = max(4, selected_rect.top() - 12 - lbl.height())
            lbl.move(x, y)
            _name_lbl_was_hidden = not lbl.isVisible()
            lbl.show()
            lbl.raise_()
            if _name_lbl_was_hidden:
                self._animate_widget_fade_in(lbl, duration=900)
            return
        selected_tile = None
        layout = self.row_layout
        for i in range(layout.count()):
            it = layout.itemAt(i)
            w = it.widget() if it else None
            if isinstance(w, PS5GameTile) and w._selected:
                selected_tile = w
                break
        if selected_tile is None:
            lbl.hide()
            return
        if selected_tile.width() <= 0 or selected_tile.height() <= 0:
            return
        right_center = selected_tile.mapTo(self.central, QPoint(selected_tile.width() + 30, selected_tile.height() + 20))
        lbl.adjustSize()
        x = right_center.x()
        y = max(4, right_center.y() - lbl.height())
        # Never allow the floating name to overlap the selected tile.  This
        # is especially important after the settings drawer changes the
        # parent layout: a late geometry update can otherwise leave the text
        # painted over the tile for one or more event-loop turns.
        tile_top_left = selected_tile.mapTo(self.central, QPoint(0, 0))
        tile_rect = QRect(tile_top_left, selected_tile.size())
        occupied_rects = [tile_rect]
        for i in range(layout.count()):
            other = layout.itemAt(i).widget()
            if other is None or other is selected_tile or not other.isVisible():
                continue
            other_top_left = other.mapTo(self.central, QPoint(0, 0))
            occupied_rects.append(QRect(other_top_left, other.size()))
        name_rect = QRect(x, y, lbl.width(), lbl.height())
        if any(name_rect.intersects(rect) for rect in occupied_rects):
            candidates = (
                (tile_rect.right() + 30, max(4, tile_rect.bottom() + 20 - lbl.height())),
                (tile_rect.left() - 30 - lbl.width(), max(4, tile_rect.bottom() + 20 - lbl.height())),
                (tile_rect.center().x() - lbl.width() // 2, tile_rect.bottom() + 30),
                (tile_rect.center().x() - lbl.width() // 2, tile_rect.top() - 30 - lbl.height()),
            )
            central_rect = self.central.rect()
            placed = False
            for candidate_x, candidate_y in candidates:
                candidate = QRect(candidate_x, candidate_y, lbl.width(), lbl.height())
                if central_rect.contains(candidate) and not any(candidate.intersects(rect) for rect in occupied_rects):
                    x, y = candidate_x, candidate_y
                    placed = True
                    break
            if not placed:
                x = max(0, min(central_rect.width() - lbl.width(), tile_rect.center().x() - lbl.width() // 2))
                y = max(0, tile_rect.bottom() + 30)
        lbl.move(x, y)
        _name_lbl_was_hidden = not lbl.isVisible()
        lbl.show()
        lbl.raise_()
        if _name_lbl_was_hidden:
            self._animate_widget_fade_in(lbl, duration=900)
    _LOGO_BOX_X0 = 0.0
    _LOGO_BOX_X1 = 0.39
    _LOGO_BOX_Y0 = 0.556
    _LOGO_BOX_Y1 = 0.743

    def _reposition_name_logo_lbl(self):
        lbl = self._name_logo_lbl
        cw, ch = (self.central.width(), self.central.height())
        if cw <= 0 or ch <= 0:
            return
        x0 = int(cw * self._LOGO_BOX_X0)
        x1 = int(cw * self._LOGO_BOX_X1)
        y0 = int(ch * self._LOGO_BOX_Y0)
        y1 = int(ch * self._LOGO_BOX_Y1)
        lbl.setGeometry(x0, y0, max(1, x1 - x0), max(1, y1 - y0))
        self._apply_name_logo_scaled()
        if not self._name_logo_raw_pix.isNull() and (not getattr(self, '_startup_idle', False)):
            _logo_was_hidden = getattr(self, '_logo_needs_entrance', False) or not lbl.isVisible()
            self._logo_needs_entrance = False
            lbl.show()
            if _logo_was_hidden:
                QTimer.singleShot(0, lambda: self._animate_widget_fade_in(lbl, duration=900))
        lbl.raise_()
        self._reposition_play_btn_float()

    def _reposition_play_btn_float(self):
        btn = self._float_play_btn
        lbl = self._name_logo_lbl
        cw, ch = (self.central.width(), self.central.height())
        if cw <= 0 or ch <= 0:
            return
        lbl_x = lbl.x()
        if lbl.width() <= 1:
            lbl_x = int(cw * self._LOGO_BOX_X0)
        logo_visual_w = getattr(self, '_name_logo_visible_w', 0)
        if not logo_visual_w:
            logo_visual_w = int(cw * (self._LOGO_BOX_X1 - self._LOGO_BOX_X0))
        logo_cx = lbl_x + logo_visual_w // 2
        btn_w, btn_h = (200, 58)
        x = logo_cx - btn_w // 2
        y = int(ch * (self._LOGO_BOX_Y1 + 0.015))
        pad_x, pad_y = (btn.edge_pad_x, btn.edge_pad_y)
        btn.setGeometry(x - pad_x, y - pad_y, btn_w + 2 * pad_x, btn_h + 2 * pad_y)
        btn.raise_()

    @staticmethod
    def _trim_transparent_margins(pix: 'QPixmap', alpha_threshold: int=12) -> 'QPixmap':
        return _trim_transparent_margins(pix, alpha_threshold)
    _LOGO_TARGET_W_FRAC = 1.0
    _LOGO_TARGET_H_FRAC = 1.0
    _LOGO_ZOOM_FACTOR = 0.6

    def _apply_name_logo_scaled(self):
        lbl = self._name_logo_lbl
        pix = self._name_logo_raw_pix
        if pix.isNull() or lbl.width() <= 0 or lbl.height() <= 0:
            lbl.set_seesaw_icon(QPixmap())
            self._name_logo_visible_w = 0
            return
        box_w = max(1, int(lbl.width() * self._LOGO_TARGET_W_FRAC))
        box_h = max(1, int(lbl.height() * self._LOGO_TARGET_H_FRAC))
        target_w = max(1, int(box_w * self._LOGO_ZOOM_FACTOR))
        target_h = max(1, int(box_h * self._LOGO_ZOOM_FACTOR))
        target_area = target_w * target_h
        src_w, src_h = (pix.width(), pix.height())
        src_area = max(1, src_w * src_h)
        scale = (target_area / src_area) ** 0.5
        new_w = max(1, round(src_w * scale))
        new_h = max(1, round(src_h * scale))
        fitted = pix.scaled(new_w, new_h, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
        if fitted.width() > box_w or fitted.height() > box_h:
            fitted = fitted.scaled(box_w, box_h, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
        canvas = QPixmap(box_w, box_h)
        canvas.fill(Qt.GlobalColor.transparent)
        painter = QPainter(canvas)
        painter.drawPixmap((box_w - fitted.width()) // 2, (box_h - fitted.height()) // 2, fitted)
        painter.end()
        lbl.set_seesaw_icon(canvas)
        self._name_logo_visible_w = box_w

    @staticmethod
    def _logo_is_predominantly_black(pix: 'QPixmap') -> bool:
        if pix.isNull():
            return False
        img = pix.toImage()
        w, h = (img.width(), img.height())
        if w <= 0 or h <= 0:
            return False
        STEPS = 20
        step_x = max(1, w // STEPS)
        step_y = max(1, h // STEPS)
        dark = visible = 0
        for x in range(0, w, step_x):
            for y in range(0, h, step_y):
                color = img.pixelColor(x, y)
                if color.alpha() < 30:
                    continue
                visible += 1
                if 0.299 * color.red() + 0.587 * color.green() + 0.114 * color.blue() < 40:
                    dark += 1
        return visible > 0 and dark / visible >= 0.7

    def _set_name_logo_pixmap(self, pix: 'QPixmap'):
        self._name_logo_raw_pix = pix
        if pix.isNull():
            self._name_logo_lbl.hide()
            self._name_logo_lbl.set_seesaw_icon(QPixmap())
        else:
            self._apply_name_logo_scaled()
            _logo_was_hidden = getattr(self, '_logo_needs_entrance', False) or not self._name_logo_lbl.isVisible()
            self._logo_needs_entrance = False
            self.central.update(self._name_logo_lbl.geometry())
            self._name_logo_lbl.show()
            self._name_logo_lbl.raise_()
            self._name_logo_lbl._refresh_underlying_background()
            if _logo_was_hidden:
                QTimer.singleShot(0, lambda: self._animate_widget_fade_in(self._name_logo_lbl, duration=900))
            if hasattr(self, '_float_play_btn'):
                self._reposition_play_btn_float()

    def _update_right_cover(self, item: dict):
        preload = getattr(self, '_preload', None)
        payload = preload.cache.get(str(item.get('title', ''))) if preload else None
        cached_cover = (payload or {}).get('images', {}).get('cover')
        if isinstance(cached_cover, tuple) and len(cached_cover) > 1:
            cached_image = cached_cover[1]
            if not cached_image.isNull():
                pix = QPixmap.fromImage(cached_image)
                scaled = pix.scaled(70, 70, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
                self._right_cover_lbl.setPixmap(_round_corners_by_size(scaled, already_round=_looks_like_circular_badge(scaled)))
                self._right_cover_lbl.setText('')
                return
        icon_path = item.get('icon', '')
        exe_path = item.get('exe', '')
        self_ref = weakref.ref(self)

        def _apply(cov: 'QPixmap'):
            ref = self_ref()
            if ref is None or not hasattr(ref, '_right_cover_lbl'):
                return
            if ref._current_selected_app is not item:
                return
            if not cov.isNull():
                cov.setDevicePixelRatio(1.0)
                scaled = cov.scaled(70, 70, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
                scaled = _round_corners_by_size(scaled, already_round=_looks_like_circular_badge(scaled))
                ref._right_cover_lbl.setPixmap(scaled)
                ref._right_cover_lbl.setText('')
            else:
                ref._right_cover_lbl.setPixmap(QPixmap())
                ref._right_cover_lbl.setText('🎮')
                ref._right_cover_lbl.setFont(QFont('Segoe UI', 22))

        def _on_icon(cov: 'QPixmap'):
            if not cov.isNull():
                _apply(cov)
            else:
                _prefetch_pixmap_async(exe_path, 258, 148, _apply)
        self._right_cover_lbl.setPixmap(QPixmap())
        self._right_cover_lbl.setText('')
        _prefetch_pixmap_async(icon_path, 258, 148, _on_icon)

    def _update_name_logo(self, item: dict, name: str):
        manual_logo = item.get('name_logo', '')
        if manual_logo and os.path.exists(manual_logo):
            cached = self._logo_pixmap_cache.get(manual_logo)
            if cached is not None:
                self._set_name_logo_pixmap(cached)
                return
            if manual_logo not in self._logo_inflight:
                self._logo_inflight.add(manual_logo)
                self_ref = weakref.ref(self)

                def _decode(manual_logo=manual_logo):
                    try:
                        img = _decode_image_any_format(manual_logo)
                        img = img if not img.isNull() else None
                    except Exception:
                        img = None

                    def _apply():
                        ref = self_ref()
                        if ref is None:
                            return
                        ref._logo_inflight.discard(manual_logo)
                        if img is None:
                            return
                        pix = QPixmap.fromImage(img)
                        if pix.isNull():
                            return
                        pix = ref._trim_transparent_margins(pix)
                        ref._logo_pixmap_cache[manual_logo] = pix
                        cur = ref._current_selected_app
                        cur_name = cur.get('name') or cur.get('title') or '' if cur else ''
                        if cur_name == name:
                            ref._set_name_logo_pixmap(pix)
                    _UI_INVOKER.invoke(_apply)
                _IMAGE_DECODE_POOL.submit(_decode)
            self._set_name_logo_pixmap(QPixmap())
            return
        dest_path = _logo_dest_path(item, name)
        cached_pix = self._logo_pixmap_cache.get(dest_path)
        if cached_pix is not None:
            self._set_name_logo_pixmap(cached_pix)
            return
        if os.path.exists(dest_path) and dest_path not in self._logo_inflight:
            self._logo_inflight.add(dest_path)
            self_ref = weakref.ref(self)

            def _decode():
                try:
                    img = _decode_image_any_format(dest_path)
                    img = img if not img.isNull() else None
                except Exception:
                    img = None

                def _apply():
                    ref = self_ref()
                    if ref is None:
                        return
                    ref._logo_inflight.discard(dest_path)
                    if img is None:
                        return
                    pix = QPixmap.fromImage(img)
                    if pix.isNull():
                        return
                    pix = ref._trim_transparent_margins(pix)
                    ref._logo_pixmap_cache[dest_path] = pix
                    cur = ref._current_selected_app
                    cur_name = cur.get('name') or cur.get('title') or '' if cur else ''
                    if cur_name == name:
                        ref._set_name_logo_pixmap(pix)
                    else:
                        pass
                _UI_INVOKER.invoke(_apply)
            self._set_name_logo_pixmap(QPixmap())
            _IMAGE_DECODE_POOL.submit(_decode)
            return
        self._set_name_logo_pixmap(QPixmap())
        if dest_path in self._logo_inflight:
            return
        self._logo_inflight.add(dest_path)
        self_ref = weakref.ref(self)

        def _worker():
            try:
                _excl = set(item.get('name_logo_rejected_hashes') or [])
                result = _download_name_logo(name, dest_path, exclude_hashes=_excl)
            except Exception as e:
                result = ''

            def _update():
                ref = self_ref()
                if ref is None:
                    return
                ref._logo_inflight.discard(dest_path)
                if not result or not os.path.exists(result):
                    return
                pix = QPixmap(result)
                if pix.isNull():
                    return
                pix = ref._trim_transparent_margins(pix)
                ref._logo_pixmap_cache[dest_path] = pix
                cur = ref._current_selected_app
                cur_name = cur.get('name') or cur.get('title') or '' if cur else ''
                if cur_name == name:
                    ref._set_name_logo_pixmap(pix)
                else:
                    pass
            _UI_INVOKER.invoke(_update)
        threading.Thread(target=_worker, daemon=True).start()

    def _clear_right_panel(self):
        self._current_selected_app = None
        self._stop_audio_theme()
        if hasattr(self, 'central'):
            self.central.set_background('')
        if hasattr(self, '_led_ctrl'):
            self._led_ctrl.request_color('')
        if hasattr(self, '_tile_name_lbl'):
            self._tile_name_lbl.setText('')
            self._tile_name_lbl.hide()
        if hasattr(self, '_name_logo_lbl'):
            self._set_name_logo_pixmap(QPixmap())
        if hasattr(self, '_right_cover_lbl'):
            self._right_cover_lbl.setPixmap(QPixmap())
            self._right_cover_lbl.setText('')
        if hasattr(self, '_ps5_title_lbl'):
            self._ps5_title_lbl.setText('')
            self._ps5_sub_lbl.setText('')
            self._ps5_size_lbl.setText('')
        if hasattr(self, '_right_play_btn'):
            self._right_play_btn.setEnabled(False)
        if hasattr(self, '_float_play_btn'):
            self._float_play_btn.setEnabled(False)
            self._float_play_btn.hide()

    @staticmethod
    def _find_game_root(exe_path: str) -> str:
        _INNER = {'bin', 'bins', 'binaries', 'binary', 'x64', 'x86', 'win64', 'win32', 'win', 'amd64', 'engine', 'content', 'data', 'redist', 'prerequisites', 'retail', 'release', 'debug', 'shipping', '_commonredist', 'directx', 'vcredist', 'sources', 'source'}
        _STOP_AT = {'steamapps', 'common', 'program files', 'program files (x86)', 'games', 'gog games', 'epic games', 'ubisoft game launcher'}
        current = os.path.dirname(exe_path)
        best = current
        while True:
            parent = os.path.dirname(current)
            if parent == current:
                break
            parent_name = os.path.basename(parent).lower()
            cur_name = os.path.basename(current).lower()
            if parent_name in _STOP_AT:
                best = current
                break
            if cur_name not in _INNER:
                best = current
                break
            current = parent
        return best

    @staticmethod
    def _fmt_size(sz: int) -> str:
        if sz >= 1073741824:
            return f'{sz / 1073741824:.1f} GB'
        elif sz >= 1048576:
            return f'{sz / 1048576:.0f} MB'
        elif sz > 0:
            return f'{sz / 1024:.0f} KB'
        return 'Unknown'

    def _calc_dir_size_async(self, folder_path: str):
        self_ref = weakref.ref(self)

        def _worker():
            total = 0
            try:
                for dp, _, files in os.walk(folder_path):
                    for fn in files:
                        try:
                            total += os.path.getsize(os.path.join(dp, fn))
                        except OSError:
                            pass
            except Exception:
                pass
            self._dir_size_cache[folder_path] = total

            def _update():
                ref = self_ref()
                if ref is not None:
                    size_txt = ref._fmt_size(total)
                    ref.info_size_lbl.setText(size_txt)
                    ref._ps5_size_lbl.setText(size_txt)
            _UI_INVOKER.invoke(_update)
        threading.Thread(target=_worker, daemon=True).start()

    def _scroll_to_sel(self):
        if self.in_preview_row:
            col = max(0, min(self.preview_selected_col, self.preview_row_layout.count() - 1))
            item = self.preview_row_layout.itemAt(col)
            sa = self.preview_scroll
            other_sa = self.scroll
        else:
            col = max(0, min(self.selected_col, self.row_layout.count() - 1))
            item = self.row_layout.itemAt(col)
            sa = self.scroll
            other_sa = self.preview_scroll
        if item and item.widget():
            wgt = item.widget()
            vw = sa.viewport().width()
            target = max(0, wgt.x() + wgt.width() // 2 - vw // 2)
            self._animate_scroll(sa, target)
            self._animate_scroll(other_sa, target)

    def _animate_scroll(self, scroll_area: QScrollArea, target: int):
        key = id(scroll_area)
        anims = getattr(self, '_scroll_anims', {})
        if key in anims and anims[key].state() == QPropertyAnimation.State.Running:
            anims[key].stop()
        bar = scroll_area.horizontalScrollBar()
        anim = QPropertyAnimation(bar, b'value', self)
        anim.setDuration(120)
        anim.setStartValue(bar.value())
        anim.setEndValue(target)
        anim.setEasingCurve(QEasingCurve.Type.OutExpo)
        anim.start()
        if not hasattr(self, '_scroll_anims'):
            self._scroll_anims = {}
        self._scroll_anims[key] = anim

    def _open_folder(self, name):
        apps = [a for a in self.data.get('apps', []) if a.get('folder') == name]
        if not apps:
            self._audio_play_event('settings')
        ov = FolderOverlay(name, apps, self)
        ov.closed.connect(self._close_folder)
        ov.game_launched.connect(self._launch)
        ov.game_edit.connect(self._game_edit)
        ov.show()
        ov.raise_()
        self._folder_overlay = ov

    def _close_folder(self):
        if self._folder_overlay:
            self._folder_overlay.hide()
            self._folder_overlay.deleteLater()
            self._folder_overlay = None
        self.setFocus()

    def _folder_edit(self, name, action):
        folders = self.data.get('folders', {})
        order = self.data.get('folder_order', [])
        if action == 'rename':
            new, ok = _RenameDialog.get_text(self, current_text=name)
            if ok and new and (new != name):
                folders[new] = folders.pop(name)
                for a in self.data.get('apps', []):
                    if a.get('folder') == name:
                        a['folder'] = new
                if name in order:
                    order[order.index(name)] = new
                self._save_data()
                self.refresh_tiles()
        elif action == 'delete':
            if name in folders:
                del folders[name]
                for a in self.data.get('apps', []):
                    if a.get('folder') == name:
                        a['folder'] = None
                if name in order:
                    order.remove(name)
                self._save_data()
                self.refresh_tiles()

    def _drop_to_folder(self, game_idx, folder_name):
        uncategorized = [a for a in self.data.get('apps', []) if not a.get('folder')]
        if 0 <= game_idx < len(uncategorized):
            uncategorized[game_idx]['folder'] = folder_name
            self._save_data()
            self.refresh_tiles()

    def _on_main_tile_click(self, global_idx, app):
        self.in_preview_row = False
        self.selected_col = global_idx
        selected_tile = None
        for i in range(self.row_layout.count()):
            w = self.row_layout.itemAt(i).widget()
            if w and hasattr(w, 'set_selected'):
                sel = i == global_idx
                w.set_selected(sel)
                self.row_layout.setAlignment(w, Qt.AlignmentFlag.AlignBottom if sel else Qt.AlignmentFlag.AlignTop)
                if sel:
                    selected_tile = w
        self._update_info_panel()
        self._audio_play_event('navigation', self._current_selected_app)
        if selected_tile is not None:
            try:
                selected_tile._size_anim.finished.disconnect(self._reposition_tile_name_lbl)
            except TypeError:
                pass
            selected_tile._size_anim.finished.connect(self._reposition_tile_name_lbl)

    def _on_preview_tile_click(self, col_idx, app):
        self.in_preview_row = True
        self.preview_selected_col = col_idx
        carousel = getattr(self, '_game_carousel', None)
        if carousel is not None and carousel.selected_index() != col_idx:
            carousel.navigate_to(col_idx)
        selected_tile = None
        for i in range(self.preview_row_layout.count()):
            w = self.preview_row_layout.itemAt(i).widget()
            if w and hasattr(w, 'set_selected'):
                sel = i == col_idx
                w.set_selected(sel)
                self.preview_row_layout.setAlignment(w, Qt.AlignmentFlag.AlignBottom if sel else Qt.AlignmentFlag.AlignTop)
                if sel:
                    selected_tile = w
        self._update_info_panel()
        self._audio_play_event('navigation', app)
        if selected_tile is not None:
            try:
                selected_tile._size_anim.finished.disconnect(self._reposition_tile_name_lbl)
            except TypeError:
                pass
            selected_tile._size_anim.finished.connect(self._reposition_tile_name_lbl)

    def _on_carousel_game_clicked(self, idx):
        if 0 <= idx < len(self._preview_items):
            self._on_preview_tile_click(idx, self._preview_items[idx])

    def _on_carousel_wheel_settled(self, idx):
        self._on_carousel_game_clicked(idx)

    def _on_carousel_game_edit(self, idx, action):
        self._game_edit_dispatch(self._preview_items, idx, action)

    def _on_carousel_context_menu(self, idx):
        self._on_carousel_game_clicked(idx)
        self._gamepad_edit_menu()

    def _on_carousel_reorder(self, from_idx, to_idx):
        """Mouse drag-and-drop reorder from GameCarousel: move the tile at
        from_idx to sit at to_idx within the currently browsed category."""
        if not self.in_preview_row:
            return
        if self._reorder_preview_item(from_idx, to_idx):
            self.preview_selected_col = to_idx
            self.refresh_tiles()

    @staticmethod
    def _audio_genre(app):
        if not isinstance(app, dict):
            return ''
        return app.get('genre', app.get('genres', app.get('tags', '')))

    def _audio_play_event(self, event: str, app=None, genre=None):
        if not self.isVisible() or self.isMinimized():
            return False
        # Once a launch has been committed to (or a game is already
        # running), the controller's audio channel belongs to the launch
        # cue and then the game/emulator -- never to a leftover
        # navigation/category/settings blip from input that was still
        # in flight when Play was pressed. The 'launch' cue itself is the
        # one event still allowed through during _launch_in_progress.
        if event != 'launch' and (getattr(self, '_launch_in_progress', False) or getattr(self, '_game_running', False)):
            return False
        engine = getattr(self, '_bt_audio', None)
        if engine is None:
            return False
        settings = self.data.get('settings', {})
        key_map = {'navigation': 'navigation', 'category': 'category', 'launch': 'launch', 'settings': 'settings'}
        cue_key = key_map.get(event)
        if cue_key:
            enabled_key = f'switching_audio_{cue_key}_enabled'
            file_key = f'switching_audio_{cue_key}_file'
            if not settings.get(enabled_key, True):
                return False
            custom_path = str(settings.get(file_key, '') or '').strip()
            if custom_path:
                if not os.path.exists(custom_path):
                    return False
                try:
                    return bool(engine.play_file(custom_path))
                except Exception as exc:
                    return False
        try:
            return bool(engine.play_ui_event(event, genre=self._audio_genre(app) if genre is None else genre))
        except Exception as exc:
            return False

    def _stop_audio_theme(self, clear_session=True):
        self._audio_theme_generation = getattr(self, '_audio_theme_generation', 0) + 1
        self._audio_theme_transition_token += 1
        self._audio_theme_preview_key = None
        if clear_session:
            self._audio_theme_session_app = None
            self._audio_theme_session_path = ''
            self._audio_theme_session_reason = ''
            self._audio_theme_session_started_at = 0.0
            self._audio_theme_session_offset = 0.0
            self._audio_theme_paused = False
        preview_temp = getattr(self, '_audio_theme_preview_temp', None)
        self._audio_theme_preview_temp = None
        engine = getattr(self, '_bt_audio', None)
        if engine is not None:
            try:
                engine.stop()
            except Exception:
                pass
        player = getattr(self, '_system_theme_player', None)
        fade_anim = getattr(self, '_system_theme_fade_anim', None)
        if fade_anim is not None:
            try:
                fade_anim.stop()
            except Exception:
                pass
            self._system_theme_fade_anim = None
        if player is not None:
            try:
                player.stop()
            except Exception:
                pass
            try:
                player.setSource(QUrl())
            except Exception:
                pass
        output = getattr(self, '_system_theme_output', None)
        if output is not None:
            try:
                output.setVolume(float(self.data.get('settings', {}).get('audio_theme_volume', DEFAULT_SETTINGS['audio_theme_volume'])))
            except Exception:
                pass
        if preview_temp:
            try:
                os.remove(preview_temp)
            except OSError:
                pass

    def _pause_audio_theme(self):
        if getattr(self, '_audio_theme_paused', False):
            return
        app = getattr(self, '_audio_theme_session_app', None)
        path = getattr(self, '_audio_theme_session_path', '')
        if app is None or not path:
            return
        player = getattr(self, '_system_theme_player', None)
        player_position = 0.0
        if player is not None:
            try:
                player_position = max(0.0, float(player.position()) / 1000.0)
            except Exception:
                pass
        if player_position > 0:
            self._audio_theme_session_offset = player_position
        else:
            started = getattr(self, '_audio_theme_session_started_at', 0.0)
            if started:
                self._audio_theme_session_offset += max(0.0, time.monotonic() - started)
        self._audio_theme_paused = True
        engine = getattr(self, '_bt_audio', None)
        if engine is not None:
            try:
                if engine.fade_out_and_stop(duration=0.32):
                    return
            except Exception as exc:
                pass
        player = getattr(self, '_system_theme_player', None)
        output = getattr(self, '_system_theme_output', None)
        if player is not None and output is not None:
            try:
                self._audio_theme_transition_token += 1
                token = self._audio_theme_transition_token
                animation = QPropertyAnimation(output, b'volume', self)
                animation.setDuration(320)
                animation.setStartValue(float(output.volume()))
                animation.setEndValue(0.0)
                animation.setEasingCurve(QEasingCurve.Type.InOutQuad)

                def finish_pause():
                    if token != self._audio_theme_transition_token:
                        return
                    try:
                        player.stop()
                        player.setSource(QUrl())
                        output.setVolume(float(self.data.get('settings', {}).get('audio_theme_volume', DEFAULT_SETTINGS['audio_theme_volume'])))
                    except Exception:
                        pass
                    self._system_theme_fade_anim = None
                animation.finished.connect(finish_pause)
                self._system_theme_fade_anim = animation
                animation.start()
                return
            except Exception as exc:
                pass
        self._stop_audio_theme(clear_session=False)

    def _stop_controller_audio_for_launch(self):
        """Hard-cut every sound heading to the controller (DualSense
        speaker) the instant a game/emulator is about to take over, so
        it gets the controller's audio channel completely to itself.

        This is deliberately NOT _pause_audio_theme(): that method calls
        engine.fade_out_and_stop(), a soft ~320ms fade driven by the
        engine's _crossfade_request field. If the player navigated to a
        different tile a moment before pressing Play, that tile's
        crossfade can already be committed (mid-blend) inside the
        engine's producer thread, and the producer only looks at a new
        _crossfade_request when it isn't already mid-transition -- so
        the fade-to-silence request can lose that race and the OTHER
        game's theme keeps streaming to the controller right through
        (and past) the launch cue. engine.stop() instead bumps
        _playback_generation and drains both the prepare and play
        queues; every part of the engine's loops checks the generation
        unconditionally on each pass, so nothing already in flight --
        crossfading or not -- can survive it.
        """
        app = getattr(self, '_audio_theme_session_app', None)
        path = getattr(self, '_audio_theme_session_path', '')
        if app is not None and path and (not getattr(self, '_audio_theme_paused', False)):
            player = getattr(self, '_system_theme_player', None)
            player_position = 0.0
            if player is not None:
                try:
                    player_position = max(0.0, float(player.position()) / 1000.0)
                except Exception:
                    pass
            if player_position > 0:
                self._audio_theme_session_offset = player_position
            else:
                started = getattr(self, '_audio_theme_session_started_at', 0.0)
                if started:
                    self._audio_theme_session_offset += max(0.0, time.monotonic() - started)
        self._audio_theme_paused = True
        self._audio_theme_transition_token += 1
        fade_anim = getattr(self, '_system_theme_fade_anim', None)
        if fade_anim is not None:
            try:
                fade_anim.stop()
            except Exception:
                pass
            self._system_theme_fade_anim = None
        engine = getattr(self, '_bt_audio', None)
        if engine is not None:
            try:
                engine.stop(clear_queue=True)
            except Exception:
                pass
        player = getattr(self, '_system_theme_player', None)
        if player is not None:
            try:
                player.stop()
            except Exception:
                pass
        output = getattr(self, '_system_theme_output', None)
        if output is not None:
            try:
                output.setVolume(float(self.data.get('settings', {}).get('audio_theme_volume', DEFAULT_SETTINGS['audio_theme_volume'])))
            except Exception:
                pass

    def _resume_audio_theme(self):
        if getattr(self, '_game_running', False) or getattr(self, '_launcher_suppressed', False) or (not self.isVisible()):
            return False
        app = getattr(self, '_audio_theme_session_app', None)
        if app is not None and getattr(self, '_audio_theme_paused', False):
            return self._play_audio_theme(app, reason=getattr(self, '_audio_theme_session_reason', 'preview'), start_offset=getattr(self, '_audio_theme_session_offset', 0.0), resume_session=True)
        if app is None:
            if getattr(self, 'in_preview_row', False):
                items = getattr(self, '_preview_items', [])
                index = getattr(self, 'preview_selected_col', 0)
                if 0 <= index < len(items):
                    app = items[index]
            else:
                items = getattr(self, '_all_items', [])
                index = getattr(self, 'selected_col', 0)
                if 0 <= index < len(items) and items[index][0] == 'game':
                    app = items[index][1]
        if app is None:
            return False
        return self._play_audio_theme(app, reason='preview', start_offset=0.0)

    def _controller_audio_route_ok(self):
        """True when theme audio should be sent to the DualSense speaker:
        a Bluetooth pad is connected, or is visible and still opening its
        HID audio handle. Otherwise the theme plays through the system
        output. Asks the hub to rescan first, so a pad that was switched on
        after the launcher started is picked up right now instead of after
        the next periodic rescan (previously the theme fell back to the
        system player and then never moved over to the pad)."""
        engine = getattr(self, '_bt_audio', None)
        if engine is None or (not getattr(engine, 'available', False)):
            _log_bt_audio_availability_once()
            return False
        try:
            if engine.connected:
                return True
            now = time.monotonic()
            if now - float(getattr(self, '_audio_route_last_scan', 0.0) or 0.0) >= 1.5:
                self._audio_route_last_scan = now
                engine.connect_async()
            return bool(getattr(engine, 'has_pad', False))
        except Exception:
            return False

    def _audio_theme_route_check(self):
        """Runs once a second: moves a playing theme to the controller when
        one becomes available, and back to the system output when it goes
        away (or never manages to open its audio handle)."""
        if getattr(self, '_shutting_down', False):
            return
        app = getattr(self, '_audio_theme_session_app', None)
        if app is None or getattr(self, '_audio_theme_paused', False):
            return
        if getattr(self, '_game_running', False) or getattr(self, '_launch_in_progress', False) or getattr(self, '_launcher_suppressed', False):
            return
        engine = getattr(self, '_bt_audio', None)
        if engine is None or (not getattr(engine, 'available', False)):
            return
        route = getattr(self, '_audio_theme_route', '')
        if not route:
            return
        try:
            connected = bool(engine.connected)
            want = None
            if route == 'system':
                if connected:
                    want = 'controller'
            elif not connected:
                waited = time.monotonic() - float(getattr(self, '_audio_theme_route_since', 0.0) or 0.0)
                if (not getattr(engine, 'has_pad', False)) or waited > 6.0:
                    want = 'system'
            if want is None:
                return
            if route == 'system':
                player = getattr(self, '_system_theme_player', None)
                try:
                    offset = max(0.0, float(player.position()) / 1000.0) if player is not None else 0.0
                except Exception:
                    offset = 0.0
                if offset <= 0:
                    offset = float(getattr(self, '_audio_theme_session_offset', 0.0) or 0.0) + max(0.0, time.monotonic() - float(getattr(self, '_audio_theme_session_started_at', 0.0) or time.monotonic()))
            else:
                offset = float(getattr(self, '_audio_theme_session_offset', 0.0) or 0.0) + max(0.0, time.monotonic() - float(getattr(self, '_audio_theme_session_started_at', 0.0) or time.monotonic()))
            self._audio_theme_route_force = want
            try:
                self._play_audio_theme(app, reason=getattr(self, '_audio_theme_session_reason', 'preview') or 'preview', start_offset=offset, resume_session=True, allow_inactive=True)
            finally:
                self._audio_theme_route_force = None
        except Exception:
            self._audio_theme_route_force = None

    def _play_audio_theme(self, app, reason='preview', start_offset=0.0, resume_session=False, allow_inactive=False):
        if not isinstance(app, dict):
            return False
        if reason == 'preview' and (getattr(self, '_launcher_suppressed', False) or getattr(self, '_game_running', False) or getattr(self, '_launch_in_progress', False) or (not self.isVisible()) or (not allow_inactive and (not self.isActiveWindow()))):
            return False
        settings = self.data.get('settings', {})
        if not settings.get('audio_theme_enabled', DEFAULT_SETTINGS['audio_theme_enabled']):
            return False
        if reason == 'preview' and (not settings.get('audio_theme_preview', DEFAULT_SETTINGS['audio_theme_preview'])):
            return False
        if reason == 'launch' and (not settings.get('audio_theme_on_launch', DEFAULT_SETTINGS['audio_theme_on_launch'])):
            return False
        title = (app.get('title') or app.get('name') or '').strip()
        path = (app.get('audio_theme') or '').strip()
        if not path:
            path = _audio_dest_path(app, title)
        preview_key = (_bg_identity_key(app), os.path.abspath(path))
        if reason == 'preview' and (not resume_session) and preview_key == getattr(self, '_audio_theme_preview_key', None):
            return True
        if not title or not _audio_file_matches_title(path, title):
            if reason == 'preview':
                self._stop_audio_theme()
            return False
        preserving_session = bool(resume_session and getattr(self, '_audio_theme_session_path', '') == os.path.abspath(path))
        engine = getattr(self, '_bt_audio', None)
        _forced_route = getattr(self, '_audio_theme_route_force', None)
        if _forced_route:
            use_controller = _forced_route == 'controller'
        else:
            use_controller = self._controller_audio_route_ok()
        _raw_old_path = getattr(self, '_audio_theme_session_path', '') or ''
        # os.path.abspath('') resolves to the current working directory, not
        # an empty string, which used to make the very first playback (when
        # no session path has ever been set) look like a switch away from a
        # real previous track.  That sent it down the crossfade/fade-out
        # path instead of a plain fresh start, and fading from a track that
        # was never actually playing produced no audible sound.
        old_path = os.path.abspath(_raw_old_path) if _raw_old_path else ''
        new_path = os.path.abspath(path)
        if use_controller and reason == 'preview' and (not preserving_session) and old_path and (old_path != new_path) and (engine is not None) and getattr(engine, 'available', False):
            try:
                if engine.crossfade_file(new_path, start_offset=float(start_offset or 0.0), duration=0.32):
                    self._audio_theme_session_app = app
                    self._audio_theme_session_path = new_path
                    self._audio_theme_session_reason = reason
                    self._audio_theme_session_offset = float(start_offset or 0.0)
                    self._audio_theme_session_started_at = time.monotonic()
                    self._audio_theme_paused = False
                    self._audio_theme_preview_key = preview_key
                    self._audio_theme_route = 'controller'
                    self._audio_theme_route_since = time.monotonic()
                    return True
            except Exception as exc:
                pass
        player = getattr(self, '_system_theme_player', None)
        output = getattr(self, '_system_theme_output', None)
        old_system_active = False
        if player is not None:
            try:
                old_system_active = player.playbackState() == QMediaPlayer.PlaybackState.PlayingState
            except Exception:
                old_system_active = False
        if (not use_controller) and reason == 'preview' and (not preserving_session) and old_path and (old_path != new_path) and old_system_active and (player is not None) and (output is not None):
            try:
                self._audio_theme_transition_token += 1
                token = self._audio_theme_transition_token
                old_fade = getattr(self, '_system_theme_fade_anim', None)
                if old_fade is not None:
                    old_fade.stop()
                target_volume = float(settings.get('audio_theme_volume', DEFAULT_SETTINGS['audio_theme_volume']))
                fade_out = QPropertyAnimation(output, b'volume', self)
                fade_out.setDuration(160)
                fade_out.setStartValue(float(output.volume()))
                fade_out.setEndValue(0.0)
                fade_out.setEasingCurve(QEasingCurve.Type.InOutQuad)

                def switch_to_new_theme():
                    if token != self._audio_theme_transition_token:
                        return
                    try:
                        player.stop()
                        player.setSource(QUrl.fromLocalFile(new_path))
                        if float(start_offset or 0.0) > 0:
                            player.setPosition(int(float(start_offset) * 1000))
                        output.setVolume(0.0)
                        player.play()
                        fade_in = QPropertyAnimation(output, b'volume', self)
                        fade_in.setDuration(160)
                        fade_in.setStartValue(0.0)
                        fade_in.setEndValue(target_volume)
                        fade_in.setEasingCurve(QEasingCurve.Type.InOutQuad)
                        fade_in.finished.connect(lambda: setattr(self, '_system_theme_fade_anim', None))
                        self._system_theme_fade_anim = fade_in
                        fade_in.start()
                    except Exception as exc:
                        pass
                fade_out.finished.connect(switch_to_new_theme)
                self._system_theme_fade_anim = fade_out
                fade_out.start()
                self._audio_theme_session_app = app
                self._audio_theme_session_path = new_path
                self._audio_theme_session_reason = reason
                self._audio_theme_session_offset = float(start_offset or 0.0)
                self._audio_theme_session_started_at = time.monotonic()
                self._audio_theme_paused = False
                self._audio_theme_preview_key = preview_key
                self._audio_theme_route = 'system'
                self._audio_theme_route_since = time.monotonic()
                return True
            except Exception as exc:
                pass
        self._stop_audio_theme(clear_session=not preserving_session)
        if use_controller and engine is not None and getattr(engine, 'available', False):
            try:
                engine.set_target('speaker')
                if engine.play_file(path, start_offset=float(start_offset or 0.0)):
                    self._audio_theme_route = 'controller'
                    self._audio_theme_route_since = time.monotonic()
                    self._audio_theme_session_app = app
                    self._audio_theme_session_path = os.path.abspath(path)
                    self._audio_theme_session_reason = reason
                    self._audio_theme_session_offset = float(start_offset or 0.0)
                    self._audio_theme_session_started_at = time.monotonic()
                    self._audio_theme_paused = False
                    if reason == 'preview':
                        self._audio_theme_preview_key = preview_key
                    return True
            except Exception as exc:
                pass
        player = getattr(self, '_system_theme_player', None)
        output = getattr(self, '_system_theme_output', None)
        if player is None or output is None:
            return False
        try:
            output.setVolume(float(settings.get('audio_theme_volume', DEFAULT_SETTINGS['audio_theme_volume'])))
            player.setSource(QUrl.fromLocalFile(os.path.abspath(path)))
            if float(start_offset or 0.0) > 0:
                player.setPosition(int(float(start_offset) * 1000))
            player.play()
            self._audio_theme_route = 'system'
            self._audio_theme_route_since = time.monotonic()
            self._audio_theme_session_app = app
            self._audio_theme_session_path = os.path.abspath(path)
            self._audio_theme_session_reason = reason
            self._audio_theme_session_offset = float(start_offset or 0.0)
            self._audio_theme_session_started_at = time.monotonic()
            self._audio_theme_paused = False
            if reason == 'preview':
                self._audio_theme_preview_key = preview_key
            return True
        except Exception as exc:
            return False

    def _toggle_audio_theme_preview(self, app, path=None, start=0.0, end=None):
        title = (app.get('title') or app.get('name') or '').strip()
        path = (path or app.get('audio_theme') or _audio_dest_path(app, title)).strip()
        try:
            start = max(0.0, float(start or 0.0))
            end = float(end) if end is not None else 0.0
        except (TypeError, ValueError):
            start, end = (0.0, 0.0)
        key = (_bg_identity_key(app), os.path.abspath(path), round(start, 3), round(end, 3))
        if key == getattr(self, '_audio_theme_preview_key', None):
            self._stop_audio_theme()
            return False
        preview_path = path
        if end > start + 0.001:
            preview_path = f'{path}.preview.{os.getpid()}.wav'
            try:
                shutil.copyfile(path, preview_path)
                _trim_wav_file(preview_path, start, end)
                _write_audio_sidecar(preview_path, title, duration=end - start)
            except (OSError, ValueError, wave.Error):
                try:
                    if os.path.exists(preview_path):
                        os.remove(preview_path)
                except OSError:
                    pass
                preview_path = path
        preview_app = dict(app)
        preview_app['audio_theme'] = preview_path
        played = self._play_audio_theme(preview_app, reason='preview', allow_inactive=True)
        if played:
            if preview_path != path:
                self._audio_theme_preview_temp = preview_path
            self._audio_theme_preview_key = key
        elif preview_path != path:
            try:
                os.remove(preview_path)
            except OSError:
                pass
        return played

    def _launch(self, app, with_fps=False, with_super_frame=False, _auto_relaunch=False):
        if not _auto_relaunch and getattr(self, '_game_running', False) and getattr(self, '_game_minimized_to_launcher', False):
            running_app = getattr(self, '_launch_app_obj', None)
            same_game = isinstance(running_app, dict) and isinstance(app, dict) and running_app.get('exe') == app.get('exe') and (running_app.get('game_root') == app.get('game_root'))
            if same_game:
                # Re-selecting the game that's already minimized in the
                # background -- just bring it back instead of asking to
                # close it and "relaunch" itself.
                self._restore_minimized_game()
                return
            running_title = str(running_app.get('title', 'The current game')) if isinstance(running_app, dict) else 'The current game'
            if not _GlassMessageDialog.question(self, 'Game Running', f'{running_title} is still running in the background. Close it and launch this game?'):
                return
            self._close_minimized_game_for_relaunch()
        if not _auto_relaunch and (getattr(self, '_game_running', False) or getattr(self, '_launch_in_progress', False)):
            return
        if not _auto_relaunch:
            self._launch_auto_relaunch_count = 0
        self._launch_in_progress = True
        try:
            app['game_profile'] = _default_game_profile(app)
            safe_mode = str(app.get('safe_mode', 'normal') or 'normal')
            no_controller_emulation = safe_mode in ('no_controller_emulation', 'native_input_only')
            if hasattr(self, '_ctrl_mgr') and (not no_controller_emulation):

                def _continue_after_vgamepad(ready, message, _with_fps=with_fps):
                    if not ready:
                        self._launch_in_progress = False
                        _GlassMessageDialog.warning(self, 'Controller setup', message)
                        return
                    self._launch_in_progress = False
                    self._launch(app, with_fps=_with_fps)
                if not self._ctrl_mgr.prepare_vgamepad_for_game(app, _continue_after_vgamepad):
                    self._show_slide_toast('Preparing controller support', 'Installing vgamepad before launching the game…', hold_ms=4000)
                    return
            exe = app.get('exe', '')
            if not exe:
                self._launch_in_progress = False
                return
            exe_check = _validate_path(exe, 'exe', 'file')
            if exe_check['status'] not in ('Valid', 'Read-only'):
                self._launch_in_progress = False
                _GlassMessageDialog.warning(self, 'Launch blocked', f"Game path status: {exe_check['status']}\n{exe_check['path']}\n{exe_check['reason']}")
                return
            backup_cfg = app.get('save_backup') or {}
            if backup_cfg.get('enabled') and backup_cfg.get('before_launch', True):
                ok, detail = _create_save_backup(app, self.data.get('settings', {}), 'before_launch')
                if ok:
                    _record_stat_event(self.data, 'backup_count')
                    self._save_data()
            _run_with_exe = (app.get('run_with_exe') or '').strip()
            if _run_with_exe:
                if not os.path.exists(_run_with_exe):
                    self._launch_in_progress = False
                    _GlassMessageDialog.warning(self, 'Error', f'"Run With" file not found:\n{_run_with_exe}')
                    return
                exe = _run_with_exe
            _emulator_cfg = app.get('emulator')
            _emulator_args = []
            if isinstance(_emulator_cfg, dict) and _emulator_cfg.get('path'):
                _emulator_path = os.path.abspath(os.path.expanduser(str(_emulator_cfg.get('path', '')).strip()))
                if not os.path.exists(_emulator_path):
                    self._launch_in_progress = False
                    _GlassMessageDialog.warning(self, 'Emulator Error', f'Emulator file not found:\n{_emulator_path}')
                    return
                emulator_check = _validate_path(_emulator_path, 'emulator', 'file')
                if emulator_check['status'] not in ('Valid', 'Read-only'):
                    self._launch_in_progress = False
                    _GlassMessageDialog.warning(self, 'Emulator blocked', f"Emulator path status: {emulator_check['status']}\n{_emulator_path}\n{emulator_check['reason']}")
                    return
                _game_argument = os.path.abspath(os.path.expanduser(str(app.get('exe', '')).strip()))
                _template = str(_emulator_cfg.get('args', '{game}'))
                _template = _format_emulator_args(_template, _game_argument)
                _emulator_args = shlex.split(_template, posix=False)
                exe = _emulator_path
            _active_conflicts = _content_conflicts(app)
            if _active_conflicts:
                preview = []
                for relative, entries in list(_active_conflicts.items())[:8]:
                    preview.append(f'{relative}  (' + ', '.join((kind.upper() for kind, _folder in entries)) + ')')
                remaining = len(_active_conflicts) - len(preview)
                if remaining > 0:
                    preview.append(f'... and {remaining} more')
                if not _GlassMessageDialog.question(self, 'Content conflicts', 'Enabled DLC/Mod/Patch folders contain duplicate files. The saved load order will determine which content wins.\n\n' + '\n'.join(preview) + '\n\nContinue launching the game?'):
                    self._launch_in_progress = False
                    return
            self._launch_with_super_frame = with_super_frame
            if with_super_frame:
                # Start Lossless Scaling (and make sure its AutoScale profile
                # for this game is in place) BEFORE we spawn the game itself.
                # This used to happen AFTER the game process was already
                # launched (see below, where with_super_frame was previously
                # handled) -- by the time LS finished booting (especially
                # after _ensure_lossless_scaling_autoscale_profile taskkills
                # and restarts an already-running LS instance, which alone
                # can take a few seconds), the game had often already reached
                # its main window. Lossless Scaling's AutoScale only reliably
                # picks up a target process at the moment it's launched, not
                # one that was already running before LS started watching --
                # confirmed by testing: a manually-launched game with LS
                # already open auto-scales fine, but a game launched by us
                # (LS starting late) did not, even with an identical,
                # correctly-configured profile. Doing this first, and giving
                # LS a moment to actually come up, fixes that ordering.
                _ls_path = str(self.data.get('settings', {}).get('lossless_scaling_path', '') or '').strip()
                # We don't have `watch_exe` yet (it's only resolved further
                # down, alongside actually spawning the game) -- resolve the
                # .lnk ourselves here if needed so the profile targets the
                # real game exe, not the shortcut. For the emulator-wrapped
                # case the true game exe isn't known until after the emulator
                # branch runs below, so we fall back to whatever `exe` is here
                # (matches this function's pre-existing behavior for that
                # case).
                _ls_target_exe = exe
                if os.path.splitext(exe)[1].lower() == '.lnk':
                    try:
                        _resolved_target, _resolved_args, _resolved_wd = _resolve_lnk(exe)
                        if _resolved_target and os.path.exists(_resolved_target):
                            _ls_target_exe = _resolved_target
                    except Exception:
                        pass
                _ensure_lossless_scaling_autoscale_profile(_ls_target_exe, log=lambda msg: self._show_slide_toast('Super Frame', msg, hold_ms=4000))
                _ls_started = _start_lossless_scaling(_ls_path, log=lambda msg: self._show_slide_toast('Super Frame', msg, hold_ms=4000))
                if _ls_started:
                    # Arm an independent watchdog that force-closes Lossless
                    # Scaling as soon as the game process is gone -- a safety
                    # net on top of the launcher's own window-based exit
                    # detection, so LS can never outlive the game session.
                    _arm_lossless_scaling_watchdog(os.path.basename(_ls_target_exe), None)
                # Give LS a beat to finish coming up (window created, capture
                # pipeline initialized) before the game starts, while still
                # keeping the UI responsive.
                _ls_wait_until = time.monotonic() + 1.5
                while time.monotonic() < _ls_wait_until:
                    try:
                        QApplication.processEvents()
                    except Exception:
                        pass
                    time.sleep(0.01)
            self._stop_controller_audio_for_launch()
            self._audio_play_event('launch', app)
            self._led_resume_app = app
            if hasattr(self, '_led_ctrl'):
                hs = self.data.get('settings', {})
                if hs.get('haptic_enabled', DEFAULT_SETTINGS['haptic_enabled']):
                    h_right = int(hs.get('haptic_right', DEFAULT_SETTINGS['haptic_right']))
                    h_left = int(hs.get('haptic_left', DEFAULT_SETTINGS['haptic_left']))
                    h_dur = int(hs.get('haptic_duration_ms', DEFAULT_SETTINGS['haptic_duration_ms']))
                    h_pat = hs.get('haptic_pattern', DEFAULT_SETTINGS['haptic_pattern'])
                    max_dur = h_dur if h_pat == 'single' else h_dur + 50
                    self._led_ctrl.haptic_play_pattern(pattern=h_pat, right=h_right, left=h_left, duration_ms=h_dur, context='launch:' + str(app.get('title', 'unknown')))
                    QTimer.singleShot(max_dur + 120, self._led_ctrl.suspend)
                else:
                    self._led_ctrl.suspend()
            watch_exe = exe
            _launching_path = exe
            _ext = os.path.splitext(exe)[1].lower()
            _launch_env = _active_content_environment(app)
        except Exception as _pre_launch_err:
            # Everything above -- building the per-game profile,
            # validating the exe/emulator paths, the before-launch save
            # backup, the content-conflict check, Super Frame/Lossless
            # Scaling setup, the launch audio cue, and LED haptics --
            # used to run with nothing catching an unexpected error.
            # If any of it raised (e.g. a corrupted per-game save-backup
            # path, a bad controller-routing value, Lossless Scaling
            # missing, an audio/haptics failure), the launch died
            # silently with NO dialog shown, and _launch_in_progress was
            # left stuck True forever -- which made every later Play
            # Game click (for ANY game) a silent no-op until the app was
            # restarted. Catch it, restore paused LED/audio state,
            # surface the real error, and reset the flag.
            self._launch_in_progress = False
            if hasattr(self, '_led_ctrl'):
                self._led_ctrl.resume()
            self._led_resume_app = None
            QTimer.singleShot(80, self._resume_audio_theme)
            _GlassMessageDialog.warning(self, 'Launch Error', f'Failed to prepare the launch (before starting the game):\n{_pre_launch_err}')
            return
        try:
            if _emulator_cfg and _emulator_args:
                emulator_target = exe
                emulator_cwd = os.path.dirname(os.path.abspath(exe))
                emulator_ext = os.path.splitext(exe)[1].lower()
                if emulator_ext == '.lnk':
                    resolved, shortcut_args, shortcut_cwd = _resolve_lnk(exe)
                    if resolved and os.path.exists(resolved):
                        emulator_target = resolved
                        emulator_cwd = shortcut_cwd if shortcut_cwd and os.path.isdir(shortcut_cwd) else os.path.dirname(os.path.abspath(resolved))
                        _emulator_args = shlex.split(shortcut_args, posix=False) + _emulator_args
                        emulator_ext = os.path.splitext(resolved)[1].lower()
                _force_discrete_gpu(emulator_target)
                _launching_path = emulator_target
                if emulator_ext in ('.bat', '.cmd'):
                    proc = subprocess.Popen(['cmd.exe', '/d', '/c', emulator_target] + _emulator_args, shell=False, cwd=emulator_cwd, env=_launch_env, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
                    self._launch_direct_process = False
                elif emulator_ext == '.lnk' and (not os.path.exists(emulator_target)):
                    os.startfile(emulator_target)
                    proc = _ShellOpenProc()
                    self._launch_direct_process = False
                else:
                    proc = subprocess.Popen([emulator_target] + _emulator_args, shell=False, cwd=emulator_cwd, env=_launch_env)
                    self._launch_direct_process = True
                watch_exe = emulator_target
            elif _ext == '.lnk':
                # Mirror an actual desktop double-click as closely as
                # possible: hand the .lnk itself to the shell (ShellExecute
                # via os.startfile) instead of manually resolving the
                # target and spawning it ourselves. Manually resolving and
                # subprocess.Popen()-ing the target changes the parent
                # process (python/this launcher instead of explorer.exe)
                # and can silently drop things a real double-click gets
                # for free: the shortcut's own embedded "Run as
                # administrator" compatibility flag, working-directory /
                # environment quirks some installers rely on, and -- most
                # commonly -- anti-cheat (EAC/BattlEye/Denuvo) or DRM
                # checks that refuse to start unless their process was
                # launched by explorer.exe. Only when the launcher's own
                # "Run as admin" toggle is explicitly set do we still need
                # to resolve the target ourselves, since ShellExecuteEx's
                # 'runas' verb needs a real target path (a .lnk can't take
                # the 'runas' verb directly for elevated launch).
                _want_admin = bool(app.get('run_as_admin'))
                if _want_admin:
                    target, args, work_dir = _resolve_lnk(exe)
                    if target and os.path.exists(target):
                        _force_discrete_gpu(target)
                        cwd = work_dir if work_dir and os.path.isdir(work_dir) else os.path.dirname(os.path.abspath(target))
                        _launching_path = target
                        _target_ext = os.path.splitext(target)[1].lower()
                        if _target_ext in ('.bat', '.cmd'):
                            proc = _run_elevated('cmd.exe', cwd, ['/d', '/c', target] + shlex.split(args, posix=False))
                        else:
                            proc = _run_elevated(target, cwd, shlex.split(args, posix=False))
                        self._launch_direct_process = True
                        watch_exe = target
                    else:
                        _force_discrete_gpu(exe)
                        _launching_path = exe
                        proc = _run_elevated(exe, os.path.dirname(os.path.abspath(exe)), [])
                        self._launch_direct_process = True
                else:
                    _force_discrete_gpu(exe)
                    _launching_path = exe
                    try:
                        os.startfile(exe)
                    except OSError:
                        subprocess.Popen(f'start "" "{exe}"', shell=True, cwd=os.path.dirname(os.path.abspath(exe)), env=_launch_env, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
                    proc = _ShellOpenProc()
                    self._launch_direct_process = False
                    # We didn't spawn the target ourselves, so for process
                    # tracking (window matching, "is it still running")
                    # try to resolve what the shortcut points at just to
                    # know its name -- this doesn't affect how it was
                    # launched, only what we watch for afterward.
                    _watch_target, _watch_args, _watch_wd = _resolve_lnk(exe)
                    if _watch_target and os.path.exists(_watch_target):
                        watch_exe = _watch_target
            elif _ext in ('.bat', '.cmd'):
                _launching_path = exe
                cwd = os.path.dirname(os.path.abspath(exe))
                proc = subprocess.Popen(exe, shell=True, cwd=cwd, env=_launch_env, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
                self._launch_direct_process = False
            elif _ext == '.url':
                _launching_path = exe
                cwd = os.path.dirname(os.path.abspath(exe))
                proc = subprocess.Popen(exe, shell=True, cwd=cwd, env=_launch_env, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
                self._launch_direct_process = False
            elif _ext in ('.bin', '.elf', '.oelf', '.self'):
                _force_discrete_gpu(exe)
                _launching_path = exe
                cwd = os.path.dirname(os.path.abspath(exe))
                proc = subprocess.Popen(exe, shell=True, cwd=cwd, env=_launch_env, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
                self._launch_direct_process = False
            else:
                _force_discrete_gpu(exe)
                _launching_path = exe
                if bool(app.get('run_as_admin')):
                    proc = _run_elevated(exe, os.path.dirname(os.path.abspath(exe)), _emulator_args)
                    self._launch_direct_process = True
                else:
                    try:
                        _native_cmd = [exe] + _emulator_args
                        proc = subprocess.Popen(_native_cmd, shell=False, cwd=os.path.dirname(os.path.abspath(exe)), env=_launch_env)
                        self._launch_direct_process = True
                    except OSError as spawn_err:
                        _we = getattr(spawn_err, 'winerror', None)
                        if _we == 740:
                            proc = _run_elevated(exe, os.path.dirname(os.path.abspath(exe)), _emulator_args)
                            self._launch_direct_process = True
                        elif _we == 193:
                            proc = subprocess.Popen(exe, shell=True, cwd=os.path.dirname(os.path.abspath(exe)), env=_launch_env, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
                            self._launch_direct_process = False
                        else:
                            raise
        except Exception as err:
            self._launch_in_progress = False
            if hasattr(self, '_led_ctrl'):
                self._led_ctrl.resume()
            self._led_resume_app = None
            QTimer.singleShot(80, self._resume_audio_theme)
            _err_detail = str(err)
            _err_detail += f'\n\nFile: {_launching_path}'
            if _ext == '.lnk' and _launching_path != exe:
                _err_detail += f'\nShortcut (.lnk): {exe}'
            _GlassMessageDialog.warning(self, 'Launch Error', _err_detail)
            return
        self._stop_gamepad_for_game()
        self._launch_with_fps = with_fps
        if with_fps:
            _fps_metrics = dict(DEFAULT_SETTINGS['fps_overlay_metrics'])
            _fps_metrics.update(self.data.get('settings', {}).get('fps_overlay_metrics', {}) or {})
            _start_fps_overlay(log=lambda msg: self._show_slide_toast('FPS Overlay', msg, hold_ms=4000), metrics=_fps_metrics)
        else:
            _stop_fps_overlay()
        # Give the freshly-spawned process a brief moment to initialize
        # before we start controller emulation for it. This used to be a
        # plain time.sleep(0.15), which froze the whole UI (no repaint,
        # no input) for 150ms on every single game launch. Pumping the
        # Qt event loop while we wait keeps the window responsive during
        # that same 150ms instead of blocking it.
        _wait_until = time.monotonic() + 0.15
        while time.monotonic() < _wait_until:
            try:
                QApplication.processEvents()
            except Exception:
                pass
            time.sleep(0.01)
        if hasattr(self, '_ctrl_mgr') and (not no_controller_emulation):
            self._ctrl_mgr._gamepad_settings = dict(self.data.get('settings', {}))
            self._ctrl_mgr._launcher_data = self.data
            self._ctrl_mgr.start_for_game(app)
        launch_settings = self.data.get('settings', {})
        if launch_settings.get('process_tree_isolation', DEFAULT_SETTINGS['process_tree_isolation']):
            self._game_job_handle = _assign_process_tree_job(getattr(proc, 'pid', 0))
        hs = self.data.get('settings', {})
        effective_hs = _resolve_effective_booster_settings(app, hs)
        if safe_mode != 'minimal_services' and effective_hs is not None and effective_hs.get('booster_enabled', DEFAULT_SETTINGS['booster_enabled']) and (not _GameBooster.is_game_excluded(watch_exe, effective_hs)):
            try:
                self._booster.boost(proc.pid, effective_hs)
            except Exception:
                pass
        self._launch_in_progress = False
        self._game_running = True
        self._launcher_suppressed = True
        self._restore_pending = True
        if self._cursor_hidden_by_pad:
            self._cursor_hidden_by_pad = False
            _cursor_override_pop('pad_blank')
        if self._folder_overlay:
            self._folder_overlay.hide()
        if not _auto_relaunch or getattr(self, '_launch_overlay', None) is None:
            self._launch_overlay = LaunchOverlay(app)
        if safe_mode == 'no_overlay':
            self._launch_overlay.hide()
        self._launch_app_obj = app
        self._launch_relaunch_with_fps = with_fps
        self._launch_relaunch_with_super_frame = with_super_frame
        self._launch_exe_seen_alive = False
        self._launch_watch_fallback_candidate = None
        self._launch_watch_exe = os.path.basename(watch_exe)
        self._launch_started = time.time()
        self._launch_window_seen = False
        self._windowed_seen_streak = 0
        self._launch_proc_exited = False
        self._start_scheduled_save_backups(app)
        self._launch_proc_exit_time = None
        self._launch_real_pid = None
        self._active_process_record = {'title': str(app.get('title', '')), 'path': str(_launching_path), 'pid': int(getattr(proc, 'pid', 0) or 0), 'started_at': time.strftime('%Y-%m-%dT%H:%M:%S')}
        self._game_gone_streak = 0
        self._launch_seen_alive_once = False
        self._fs_poll_timer = QTimer(self)
        self._fs_poll_timer.timeout.connect(self._poll_game_fullscreen)
        self._fs_poll_timer.start(250)
        self.setWindowOpacity(1.0)
        self._on_fade_out_done()
        launch_time = time.time()
        self._active_play_session = {'app': app, 'started_at': launch_time, 'last_alive_at': launch_time if self._launch_direct_process else None, 'seen_alive': bool(self._launch_direct_process), 'closed': False, 'after_exit_done': False, 'elapsed_seconds': 0}

        def _watch():
            try:
                ended_at = time.time()
                return_code = proc.wait()
                ended_at = time.time()
                elapsed = int(ended_at - launch_time)
                if self._launch_direct_process:
                    _UI_INVOKER.invoke(lambda a=app, code=return_code, seconds=elapsed: self._record_process_exit(a, code, seconds))
                    _UI_INVOKER.invoke(lambda a=app, ts=ended_at: self._finalize_play_session(a, ended_at=ts, run_after_exit_tasks=True))
            except Exception:
                pass
            self._launch_proc_exited = True
            self._launch_proc_exit_time = time.time()
            if self._launch_direct_process and (not self._launch_window_seen) and self._should_auto_relaunch():
                _UI_INVOKER.invoke(self._relaunch_after_early_exit)
                return
            if self._launch_direct_process and getattr(self, '_launch_with_fps', False):
                # Only trust proc.wait() as a real "game exited" signal for
                # processes we actually spawned ourselves. For shortcut
                # (.lnk) launches handled via os.startfile(), proc is a
                # _ShellOpenProc whose wait() returns immediately -- that's
                # ShellExecute returning, not the game closing. Stopping the
                # overlay here for that case kills it within milliseconds of
                # launch, before the real game window even appears. For
                # those launches, the overlay is instead stopped once the
                # window-based watcher (_poll_game_alive) confirms the game
                # has actually exited, via _restore_after_game().
                _stop_fps_overlay()
                self._launch_with_fps = False
            if self._launch_direct_process and self._launch_window_seen:
                _relaunch_wait_secs = 3.0
                _relaunch_check_interval = 0.25
                _elapsed = 0.0
                while _elapsed < _relaunch_wait_secs:
                    time.sleep(_relaunch_check_interval)
                    _elapsed += _relaunch_check_interval
                    if not self._restore_pending:
                        return
                    if _process_running_by_name(self._launch_watch_exe):
                        self._launch_proc_exited = False
                        return
                if self._restore_pending:
                    self._game_process_exited.emit()
        threading.Thread(target=_watch, daemon=True).start()

    def _note_play_session_alive(self, app=None, when=None):
        session = getattr(self, '_active_play_session', None)
        if not isinstance(session, dict):
            return
        target = session.get('app')
        if app is not None and target is not None and target is not app:
            return
        ts = float(when if when is not None else time.time())
        last_alive = float(session.get('last_alive_at') or 0.0)
        if ts > last_alive:
            session['last_alive_at'] = ts
        session['seen_alive'] = True

    def _refresh_current_playtime_views(self, app):
        if app is None:
            return
        secs = int(app.get('play_seconds', 0) or 0)
        if secs >= 3600:
            short_txt = f'{secs // 3600}h {secs % 3600 // 60}m'
        elif secs >= 60:
            short_txt = f'{secs // 60} min'
        elif secs > 0:
            short_txt = f'{secs} sec'
        else:
            short_txt = '0'
        detail_txt = short_txt if secs > 0 else 'Not Played Yet'
        if getattr(self, '_current_selected_app', None) is app:
            if hasattr(self, 'info_time_lbl'):
                self.info_time_lbl.setText(detail_txt)
            self._refresh_playtime_label()

    def _finalize_play_session(self, app=None, ended_at=None, run_after_exit_tasks=False):
        session = getattr(self, '_active_play_session', None)
        if not isinstance(session, dict):
            return 0
        target = session.get('app')
        if app is not None and target is not None and target is not app:
            return 0
        if target is None:
            self._active_play_session = None
            return 0
        if ended_at is None:
            ended_at = session.get('last_alive_at')
        if ended_at is None and session.get('seen_alive'):
            ended_at = time.time()
        elapsed = 0
        if session.get('seen_alive') and ended_at is not None:
            started_at = float(session.get('started_at') or ended_at)
            elapsed = max(0, int(round(float(ended_at) - started_at)))
        changed = False
        if elapsed > 0:
            target['play_seconds'] = int(target.get('play_seconds', 0) or 0) + elapsed
            history = target.setdefault('play_history', [])
            history.append({'date': time.strftime('%Y-%m-%d'), 'seconds': elapsed})
            del history[:-90]
            session['elapsed_seconds'] = elapsed
            changed = True
            self._refresh_current_playtime_views(target)
        if run_after_exit_tasks and not session.get('after_exit_done'):
            cfg = target.get('save_backup') or {}
            if cfg.get('enabled') and cfg.get('after_exit', True):
                ok, detail = _create_save_backup(target, self.data.get('settings', {}), 'after_exit')
                if ok:
                    _record_stat_event(self.data, 'backup_count')
                    changed = True
            session['after_exit_done'] = True
        session['closed'] = True
        self._active_play_session = None
        if changed:
            self._save_data()
        return elapsed

    def _record_process_exit(self, app, return_code, elapsed):
        crashed = return_code not in (None, 0)
        record = dict(self._active_process_record or {})
        record.update({'exit_code': return_code, 'ended_at': time.strftime('%Y-%m-%dT%H:%M:%S'), 'elapsed_seconds': int(elapsed or 0), 'cause': 'crash' if crashed else 'normal', 'bridge': self._ctrl_mgr.status_snapshot() if hasattr(self, '_ctrl_mgr') else {}})
        history = self.data.setdefault('process_history', [])
        history.append(_sanitize_export(record))
        del history[:-100]
        self._active_process_record = None
        if not crashed:
            return
        recovery = self.data.setdefault('recovery', {})
        title = str(app.get('title', ''))
        count = int(recovery.get(title, 0) or 0)
        max_restarts = max(0, int(self.data.get('settings', {}).get('max_recovery_restarts', DEFAULT_SETTINGS['max_recovery_restarts']) or 0))
        recovery[title] = count + 1
        if self.data.get('settings', {}).get('auto_restart_recovery', False) and count < max_restarts:
            delay = max(1, int(self.data.get('settings', {}).get('recovery_backoff_seconds', DEFAULT_SETTINGS['recovery_backoff_seconds']) or 1))
            self._pending_recovery_app = app
            QTimer.singleShot(delay * 1000, self._try_recovery_restart)
        self._save_data()

    def _try_recovery_restart(self):
        app = getattr(self, '_pending_recovery_app', None)
        self._pending_recovery_app = None
        if app is None or self._game_running or self._launch_in_progress:
            return
        self._launch(app)

    def _on_fade_out_done(self):
        self._launcher_suppressed = True

    def _start_scheduled_save_backups(self, app):
        if self._save_backup_timer is not None:
            self._save_backup_timer.stop()
            self._save_backup_timer.deleteLater()
            self._save_backup_timer = None
        cfg = app.get('save_backup') or {}
        minutes = int(cfg.get('scheduled_minutes', 0) or 0)
        if not cfg.get('enabled') or minutes <= 0:
            return
        self._save_backup_timer = QTimer(self)
        self._save_backup_timer.setInterval(max(1, minutes) * 60 * 1000)
        self._save_backup_timer.timeout.connect(lambda: self._scheduled_save_backup(app))
        self._save_backup_timer.start()

    def _scheduled_save_backup(self, app):
        if not self._game_running or self._save_backup_worker is not None:
            return
        self._save_backup_worker = SaveBackupWorker(app, self.data.get('settings', {}), 'scheduled', self)
        self._save_backup_worker.completed.connect(lambda ok, detail: self._on_save_backup_worker_done(ok, detail))
        self._save_backup_worker.finished.connect(self._save_backup_worker.deleteLater)
        self._save_backup_worker.start()

    def _on_save_backup_worker_done(self, ok, detail):
        self._save_backup_worker = None
        if ok:
            _record_stat_event(self.data, 'backup_count')
            self._save_data()

    def _poll_game_fullscreen(self):
        if not getattr(self, '_launch_overlay', None):
            self._fs_poll_timer.stop()
            return
        if not self._launch_direct_process:
            # For shell/.lnk launches, proc.wait() already returned the
            # instant ShellExecute handed off, so it can't tell us
            # whether the actual game later crashed on startup -- watch
            # the resolved target exe by name instead, same as
            # _poll_game_alive does post-overlay, just early enough to
            # retry without ever closing the loading screen.
            #
            # IMPORTANT: none of this ever changes HOW the game gets
            # (re)launched. It only ever decides WHEN to call
            # _relaunch_after_early_exit(), which always re-runs
            # self._launch(app, ...) from scratch -- and _launch() always
            # re-reads app['exe'] itself (still the .lnk path, unchanged)
            # and re-does the exact original os.startfile()-on-the-.lnk
            # launch. Nothing here ever executes a resolved/discovered
            # target exe directly -- for games that must only ever be
            # started via their shortcut, that's still exactly what
            # happens on every retry.
            try:
                exe_alive = _process_running_by_name(self._launch_watch_exe)
            except Exception:
                exe_alive = False
            if not exe_alive and not getattr(self, '_launch_exe_seen_alive', False):
                # _launch_watch_exe came from _resolve_lnk() statically
                # parsing the shortcut before we ever launched anything --
                # when that couldn't pin down a real, existing target,
                # watch_exe silently fell back to the .lnk file's own
                # name (see _launch()), which can never match a running
                # process, so exe_alive would be False forever and this
                # early-crash check could never fire for that shortcut at
                # all. Before giving up, look for whatever new process
                # actually appeared since launch -- purely to know THAT
                # something is alive (never to launch it). Require it to
                # still be there on the *next* poll too (~250ms later)
                # before trusting it, so some unrelated, short-lived
                # background process starting at the same coincidental
                # moment can't get mistaken for the game and cause a
                # bogus "it crashed" a moment later.
                new_name, new_pid = _find_any_new_process(exclude_names={self._launch_watch_exe}, min_start_time=self._launch_started)
                prev_candidate = getattr(self, '_launch_watch_fallback_candidate', None)
                if new_name and prev_candidate == new_name:
                    self._launch_watch_exe = new_name
                    self._launch_real_pid = new_pid
                    exe_alive = True
                self._launch_watch_fallback_candidate = new_name
            if exe_alive:
                self._launch_exe_seen_alive = True
            elif getattr(self, '_launch_exe_seen_alive', False) and self._should_auto_relaunch():
                self._relaunch_after_early_exit()
                return
        match_info = {}
        try:
            is_fullscreen = _find_fullscreen_window_for_exe(self._launch_watch_exe, match_info, min_start_time=self._launch_started)
        except Exception as e:
            is_fullscreen = False
        timed_out = time.time() - self._launch_started > self._LAUNCH_FULLSCREEN_TIMEOUT_SEC
        if is_fullscreen:
            self._windowed_seen_streak = 0
            self._handle_launch_handoff(match_info.get('name'), match_info.get('pid'))
            return
        # Some games (e.g. Unity titles) show a small windowed settings/config
        # dialog -- resolution, graphics quality, monitor picker -- before the
        # real game window appears. That dialog never covers the full monitor,
        # so it never satisfies the fullscreen check above, and without this
        # the always-on-top loading overlay stays up over it for up to
        # _LAUNCH_FULLSCREEN_TIMEOUT_SEC, blocking the user from clicking
        # anything in it. Require it to be visible for a couple of consecutive
        # polls (~0.5s) first, so a one-frame splash window doesn't trigger a
        # premature handoff right before the real (often fullscreen) window
        # replaces it.
        windowed_match = {}
        if _find_any_visible_window_for_exe(self._launch_watch_exe, windowed_match):
            self._windowed_seen_streak = getattr(self, '_windowed_seen_streak', 0) + 1
            if self._windowed_seen_streak >= 2:
                self._handle_launch_handoff(windowed_match.get('name'), windowed_match.get('pid'))
                return
        else:
            self._windowed_seen_streak = 0
        if not self._launch_window_seen and self._launch_proc_exited:
            since_exit = time.time() - (self._launch_proc_exit_time or time.time())
            if since_exit > self._LAUNCH_HANDOFF_BUFFER_SEC:
                name, pid = _find_any_foreground_window(exclude_names={self._launch_watch_exe}, min_start_time=self._launch_started)
                if name:
                    self._handle_launch_handoff(name, pid)
                    return
        if timed_out:
            self._fs_poll_timer.stop()
            self._hide_launch_overlay()
            # No window was ever positively matched (fullscreen, windowed,
            # or any-foreground fallback) before the timeout -- this path
            # used to just give up and close the overlay with nothing
            # forcing the game forward at all, leaving it behind the
            # launcher with no retry. Try anyway: _launch_watch_exe is
            # still the best guess at the target exe, and if a window for
            # it exists now (or shows up in the next few seconds) this
            # will find and force it, same as the normal handoff path.
            self._force_game_foreground_retries(0)

    def _should_auto_relaunch(self) -> bool:
        if getattr(self, '_launch_overlay', None) is None:
            return False
        if getattr(self, '_launch_app_obj', None) is None:
            return False
        if time.time() - getattr(self, '_launch_started', 0) > self._AUTO_RELAUNCH_WINDOW_SEC:
            return False
        if getattr(self, '_launch_auto_relaunch_count', 0) >= self._AUTO_RELAUNCH_MAX_ATTEMPTS:
            return False
        return True

    def _relaunch_after_early_exit(self):
        """The game process disappeared within _AUTO_RELAUNCH_WINDOW_SEC of
        launch and never showed a window -- likely crashed on startup
        rather than a deliberate close. Retry the same launch, reusing
        the existing LaunchOverlay instance (never recreated/closed
        here) so the loading screen stays up across the retry instead
        of flickering closed and reopening."""
        app = getattr(self, '_launch_app_obj', None)
        if app is None or getattr(self, '_launch_overlay', None) is None:
            return
        if not self._should_auto_relaunch():
            return
        self._launch_auto_relaunch_count = getattr(self, '_launch_auto_relaunch_count', 0) + 1
        with_fps = getattr(self, '_launch_relaunch_with_fps', False)
        with_super_frame = getattr(self, '_launch_relaunch_with_super_frame', False)
        self._show_slide_toast('Relaunching', f"{app.get('title', 'Game')} closed right away — retrying ({self._launch_auto_relaunch_count}/{self._AUTO_RELAUNCH_MAX_ATTEMPTS})…", hold_ms=2500)
        self._game_running = False
        self._game_minimized_to_launcher = False
        _set_game_input_paused(False)
        self._launch_in_progress = False
        self._restore_pending = False
        if getattr(self, '_fs_poll_timer', None):
            self._fs_poll_timer.stop()
        if getattr(self, '_game_alive_poll_timer', None):
            self._game_alive_poll_timer.stop()
        self._launch(app, with_fps=with_fps, with_super_frame=with_super_frame, _auto_relaunch=True)

    _FORCE_GAME_FRONT_DELAYS_MS = (0, 300, 900, 1800, 3200, 5000)

    def _force_game_foreground_retries(self, idx=0):
        """Repeatedly forces the game window to the front/maximized for a
        few seconds after handoff. One shot isn't enough: the FPS overlay
        is spawned as its own always-on-top process (see
        --fps-overlay-worker) and can grab topmost/z-order again right as
        it starts drawing, right after we just forced the game forward --
        so this keeps re-asserting for a few seconds rather than trusting
        a single call to win the race permanently. Stops early once the
        game session is no longer the active one (closed, or user
        launched something else), AND once the user has deliberately
        minimized the game to the launcher (PS/Home tap) -- without that
        second check, a PS tap during this window got silently undone a
        moment later by one of the still-queued retries re-maximizing
        and re-foregrounding the game right back over the launcher."""
        if idx >= len(self._FORCE_GAME_FRONT_DELAYS_MS):
            return
        delay = self._FORCE_GAME_FRONT_DELAYS_MS[idx]

        def _go():
            if not getattr(self, '_restore_pending', False):
                return
            if getattr(self, '_game_minimized_to_launcher', False):
                return
            try:
                _force_game_to_front(self._launch_watch_exe, maximize=True)
            except Exception:
                pass
            self._force_game_foreground_retries(idx + 1)
        QTimer.singleShot(delay, _go)

    def _handle_launch_handoff(self, matched_name, matched_pid):
        self._launch_window_seen = True
        self._note_play_session_alive(app=getattr(self, '_launch_app_obj', None), when=time.time())
        if matched_name and matched_name != self._launch_watch_exe.lower():
            self._launch_watch_exe = matched_name
            self._launch_real_pid = matched_pid
        elif matched_name:
            self._launch_real_pid = matched_pid
        self._fs_poll_timer.stop()
        overlay_ref = self._launch_overlay
        QTimer.singleShot(3000, lambda: self._finish_launch_overlay(overlay_ref))
        # Closing the loading overlay does NOT by itself bring the actual
        # game window to the front -- Windows doesn't reliably hand focus
        # to a process just because our overlay stopped being topmost, and
        # an FPS overlay running alongside can itself be sitting topmost.
        # Force it explicitly, with a few retries to outlast that race.
        self._force_game_foreground_retries(0)

    def _finish_launch_overlay(self, overlay_ref):
        if getattr(self, '_launch_overlay', None) is overlay_ref:
            self._hide_launch_overlay()

    def _hide_launch_overlay(self):
        if hasattr(self, '_fs_poll_timer') and self._fs_poll_timer:
            self._fs_poll_timer.stop()
        if hasattr(self, '_launch_overlay') and self._launch_overlay:
            self._launch_overlay.close_overlay()
            self._launch_overlay = None
        self._launcher_suppressed = True
        if self._game_alive_poll_timer is None:
            self._game_alive_poll_timer = QTimer(self)
            self._game_alive_poll_timer.timeout.connect(self._poll_game_alive)
        self._game_alive_poll_timer.start(100)
        if getattr(self, '_pending_trainer_path', None):
            _tp = self._pending_trainer_path
            self._pending_trainer_path = None
            TrainerManager.instance().launch_trainer(_tp, delay_ms=1000, still_running_cb=lambda: self._restore_pending)
            self._start_trainer_close_watchdog()

    def _start_trainer_close_watchdog(self):

        def _watch():
            pid = None
            watch_name = None
            for _ in range(60):
                if not self._restore_pending:
                    return
                pid = self._launch_real_pid
                watch_name = self._launch_watch_exe
                if pid or watch_name:
                    break
                time.sleep(0.5)
            if not pid and (not watch_name):
                return
            while self._restore_pending:
                pid = self._launch_real_pid or pid
                watch_name = self._launch_watch_exe or watch_name
                if pid:
                    alive = _pid_alive(pid)
                elif watch_name:
                    alive = _process_running_by_name(watch_name)
                else:
                    return
                if not alive:
                    TrainerManager.instance().kill_active_trainer()
                    return
                time.sleep(1.0)
            time.sleep(1.0)
            mgr = TrainerManager.instance()
            with mgr._active_proc_lock:
                leftover_proc = mgr._active_proc
                leftover_path = mgr._active_proc_path
                if leftover_proc is not None:
                    mgr._active_proc = None
                    mgr._active_proc_path = ''
            if leftover_proc is not None:
                threading.Thread(target=mgr._kill_proc_now, args=(leftover_proc, leftover_path), daemon=True, name='TrainerKillRetry').start()
        threading.Thread(target=_watch, daemon=True, name='TrainerCloseWatchdog').start()
    _GAME_GONE_CONFIRM_POLLS = 20
    _LAUNCH_STARTUP_GRACE_SEC = 25.0

    def _poll_game_alive(self):
        """Watch the resolved target executable itself (task-manager style,
        by process name / PID) rather than window presence. This tracks the
        real .exe regardless of how it was launched -- shortcut (.lnk),
        direct .exe, or any other launcher/wrapper indirection -- since
        _launch_watch_exe is already resolved to the real target's basename
        before this poller starts. Window-based detection was dropped
        because loading screens, exclusive-fullscreen transitions, and
        launcher/anti-cheat wrappers that swap PIDs could all make the
        window vanish for a few seconds while the game process was still
        very much alive, which was closing games out from under the user."""
        if not self._restore_pending:
            self._game_alive_poll_timer.stop()
            return
        try:
            alive = _process_running_by_name(self._launch_watch_exe)
            if not alive and self._launch_real_pid:
                alive = _pid_alive(self._launch_real_pid)
        except Exception:
            alive = True
        if alive:
            self._launch_seen_alive_once = True
            self._game_gone_streak = 0
            self._note_play_session_alive(app=getattr(self, '_launch_app_obj', None), when=time.time())
            return
        if not self._launch_seen_alive_once:
            # The target exe hasn't shown up in the process list yet -- for
            # shortcut (.lnk) launches handed off to ShellExecute, or any
            # launcher/wrapper indirection, that can take a few seconds
            # (UAC prompt, wrapper spawning the real game, slow startup).
            # Don't treat "not found yet" as "already exited" until it's
            # had a real chance to appear, or a fast poll interval closes
            # the game out from under the user before it ever got going.
            if time.time() - self._launch_started < self._LAUNCH_STARTUP_GRACE_SEC:
                return
        self._game_gone_streak += 1
        if self._game_gone_streak < self._GAME_GONE_CONFIRM_POLLS:
            return
        self._game_alive_poll_timer.stop()
        self._restore_after_game()

    def _toggle_fps_overlay_from_hotkey(self):
        """Toggle the overlay from the global Shift+F shortcut."""
        if getattr(self, '_shutting_down', False):
            return
        proc = globals().get('_FPS_OVERLAY_PROC')
        is_running = proc is not None and proc.poll() is None
        if is_running:
            _stop_fps_overlay()
            self._hotkey_overlay_active = False
            self._show_slide_toast('FPS Overlay', 'Overlay stopped', hold_ms=1800)
            return
        metrics = dict(DEFAULT_SETTINGS['fps_overlay_metrics'])
        metrics.update(self.data.get('settings', {}).get('fps_overlay_metrics', {}) or {})
        started = _start_fps_overlay(
            log=lambda msg: self._show_slide_toast('FPS Overlay', msg, hold_ms=4000),
            metrics=metrics,
        )
        self._hotkey_overlay_active = bool(started)
        self._show_slide_toast(
            'FPS Overlay',
            'Overlay started — Shift+F to stop' if started else 'Overlay could not start',
            hold_ms=2200,
        )

    def _on_booster_stats(self, msg: str):
        if hasattr(self, '_tray'):
            self._tray.showMessage('Game Station', msg, QSystemTrayIcon.MessageIcon.Information, 3000)

    def _restore_after_game(self):
        if not self._restore_pending:
            return
        self._restore_pending = False
        if self._game_job_handle:
            _close_process_tree_job(self._game_job_handle)
            self._game_job_handle = None
        self._pending_trainer_path = None
        TrainerManager.instance().kill_active_trainer()
        if getattr(self, '_launch_with_fps', False) or getattr(self, '_hotkey_overlay_active', False):
            _stop_fps_overlay()
            self._launch_with_fps = False
            self._hotkey_overlay_active = False
        if getattr(self, '_launch_with_super_frame', False):
            _stop_lossless_scaling()
            self._launch_with_super_frame = False
        if hasattr(self, '_booster'):
            try:
                self._booster.restore()
            except Exception:
                pass
        self._game_running = False
        self._game_minimized_to_launcher = False
        _set_game_input_paused(False)
        if self._save_backup_timer is not None:
            self._save_backup_timer.stop()
            self._save_backup_timer.deleteLater()
            self._save_backup_timer = None
        if self._game_alive_poll_timer:
            self._game_alive_poll_timer.stop()
        self._finalize_play_session(app=getattr(self, '_launch_app_obj', None), run_after_exit_tasks=True)
        if getattr(self, '_launch_overlay', None):
            self._hide_launch_overlay()
        if self._folder_overlay:
            self._folder_overlay.show()
        self._launcher_suppressed = False
        # See _force_fullscreen_and_front()/_force_to_absolute_front() for
        # why plain activateWindow()/raise_() aren't enough right after a
        # game closes (Windows refuses to hand foreground to a process
        # that wasn't just the foreground one), and why this now goes
        # through the same hardened, self-verifying restore path the tray
        # uses instead of a thinner one-off copy of it.
        self._force_fullscreen_and_front()
        QTimer.singleShot(150, self._claim_launcher_input)
        QTimer.singleShot(500, self._claim_launcher_input)
        if hasattr(self, '_ctrl_mgr'):
            self._ctrl_mgr.stop_for_game()
        resume_app = self._led_resume_app
        self._led_resume_app = None
        self._hard_reset_controller_and_gamepad(resume_app)
        if hasattr(self, '_led_ctrl'):
            hs = self.data.get('settings', {})
            if hs.get('return_haptic_enabled', DEFAULT_SETTINGS['return_haptic_enabled']):
                r_int = int(hs.get('return_haptic_intensity', DEFAULT_SETTINGS['return_haptic_intensity']))
                r_dur = int(hs.get('return_haptic_duration_ms', DEFAULT_SETTINGS['return_haptic_duration_ms']))
                r_right = max(0, min(255, int(r_int * 0.4)))
                r_left = max(0, min(255, r_int))

                def _do_return_pulse():
                    time.sleep(0.08)
                    try:
                        self._led_ctrl.haptic_pulse(right=r_right, left=r_left, duration_ms=r_dur, context='return:' + str((resume_app or {}).get('title', 'unknown')))
                    except Exception as exc:
                        _haptic_failure('return haptic exception game=%r error=%r', (resume_app or {}).get('title', 'unknown'), exc)
                threading.Thread(target=_do_return_pulse, daemon=True, name='ds-return-haptic').start()
        QTimer.singleShot(260, self._resume_audio_theme)

    def _hard_reset_controller_and_gamepad(self, resume_app=None):
        old_led = getattr(self, '_led_ctrl', None)
        if old_led is not None:
            try:
                old_led.close()
            except Exception as e:
                pass
        self._led_ctrl = DualSenseLEDController(self)
        if getattr(self, '_bt_audio', None) is not None:
            self._bt_audio.set_stream_state_callback(self._led_ctrl.set_audio_stream_active)
            self._led_ctrl.attach_audio_transport(self._bt_audio)
        if resume_app is not None:
            self._led_ctrl.request_color(_controller_led_image_for_app(resume_app))
        old_worker = getattr(self, '_worker', None)
        old_thread = getattr(self, '_gthread', None)
        if old_worker is not None:
            try:
                old_worker.stop()
            except Exception as e:
                pass
        if old_thread is not None:
            try:
                old_thread.quit()
                finished = old_thread.wait(2000)
            except Exception as e:
                pass
        self._start_gamepad()

    def _edit_game_profile(self, app):
        profile = _default_game_profile(app)
        choices = list((self.data.get('controller_profiles') or {}).keys())
        dialog = GameProfileDialog({**app, **profile, '_controller_profile_choices': choices}, self)
        dialog.saved.connect(lambda value, target=app: self._apply_profile_edit(target, value))
        dialog.duplicate_requested.connect(lambda value, target=app: self._duplicate_game_profile(target, value))
        dialog.exec()

    def _duplicate_game_profile(self, source, profile):
        title, ok = QInputDialog.getText(self, 'Duplicate Game Profile', 'New game name:', text=f"{source.get('title', 'Game')} Copy")
        if not ok or not title.strip():
            return
        duplicate = dict(source)
        duplicate.pop('id', None)
        duplicate['title'] = title.strip()
        duplicate['alias'] = ''
        duplicate['game_profile'] = dict(profile)
        duplicate['game_profile']['title'] = duplicate['title']
        duplicate['profile_schema_version'] = GAME_PROFILE_SCHEMA
        duplicate['play_seconds'] = 0
        duplicate['play_history'] = []
        duplicate['process_history'] = []
        self.data.setdefault('apps', []).append(duplicate)
        self._save_data()
        self.refresh_tiles()

    def _apply_profile_edit(self, app, profile):
        _apply_game_profile(app, profile)
        self._save_data()
        self.refresh_tiles()

    def _show_system_status(self):
        SystemStatusDialog(self, self).exec()

    def _show_activity(self):
        pass

    def _configure_preload(self):
        settings = self.data.setdefault('settings', {})
        enabled, ok = QInputDialog.getItem(self, 'Preload Settings', 'Preload artwork and metadata:', ['Enabled', 'Disabled'], 0 if settings.get('preload_enabled', True) else 1, False)
        if not ok:
            return
        count, ok = QInputDialog.getInt(self, 'Preload Settings', 'Nearby games to preload:', max(0, int(settings.get('preload_count', 2) or 2)), 0, 12)
        if not ok:
            return
        mode, ok = QInputDialog.getItem(self, 'Preload Settings', 'Performance mode:', ['Normal', 'Low impact (one nearby game)'], 1 if settings.get('preload_performance_mode', False) else 0, False)
        if not ok:
            return
        settings['preload_enabled'] = enabled == 'Enabled'
        settings['preload_count'] = count
        settings['preload_performance_mode'] = mode != 'Normal'
        self._save_data()
        if hasattr(self, '_preload'):
            self._preload.schedule([a for kind, a in self._all_items if kind == 'game'], self.preview_selected_col)

    def _system_status_snapshot(self):
        settings = self.data.get('settings', {}) or {}
        apps = self.data.get('apps', []) or []
        try:
            usage = shutil.disk_usage(_APP_DATA_DIR)
            disk = {'free_bytes': usage.free, 'total_bytes': usage.total}
        except OSError:
            disk = {'free_bytes': 0, 'total_bytes': 0}
        cache_bytes = 0
        for base in (BG_CACHE_DIR, LOGO_CACHE_DIR, ICON_CACHE_DIR, TILE_CACHE_DIR):
            for root, _dirs, files in os.walk(base):
                for name in files:
                    try:
                        cache_bytes += os.path.getsize(os.path.join(root, name))
                    except OSError:
                        pass
        emulator_status = []
        for name, profile in (self.data.get('emulator_profiles') or {}).items():
            check = _validate_path((profile or {}).get('path'), 'emulator', 'executable')
            emulator_status.append({'name': name, 'status': check['status']})
        resources = _system_resource_snapshot()
        bridge_status = self._ctrl_mgr.status_snapshot()
        process_history = self.data.get('process_history', []) or []
        last_process = process_history[-1] if process_history else {}
        active = self._current_selected_app or {}
        launch_started = float(getattr(self, '_launch_started', 0) or 0)
        duration = max(0, int(time.time() - launch_started)) if getattr(self, '_game_running', False) and launch_started else 0
        recent_errors = []
        try:
            pass
        except OSError:
            pass
        recent_errors = recent_errors[-10:]
        last_backup = (self.data.get('statistics') or {}).get('last_backup_at', '')
        services = {'backup_worker': {'status': 'Running' if getattr(self, '_save_backup_worker', None) else 'Idle'}, 'preload_worker': {'status': str(getattr(getattr(self, '_preload', None), 'status', 'Unavailable'))}, 'search_index': {'status': 'Ready' if getattr(self, '_search_index', None) is not None else 'Not Built'}, 'json_save_queue': {'status': 'Pending' if getattr(self, '_data_dirty', False) else 'Idle'}}
        installed_games = sum((1 for app in apps if _validate_path(app.get('exe', ''), 'game', 'executable')['status'] == 'Valid'))
        overall = 'Healthy'
        if resources.get('status') == 'Not Available' or (disk.get('total_bytes') and disk.get('free_bytes', 0) < disk['total_bytes'] * 0.05):
            overall = 'Warning'
        if recent_errors or bridge_status.get('errors', 0):
            overall = 'Warning'
        return _sanitize_export({'time': time.strftime('%Y-%m-%dT%H:%M:%S'), 'overall_status': overall, 'resources': resources, 'library': {'games': len(apps), 'installed_games': installed_games, 'folders': len(self.data.get('folders', {}) or {})}, 'disk': disk, 'cache_bytes': cache_bytes, 'backups_created': int((self.data.get('statistics') or {}).get('backup_count', 0) or 0), 'backups_restored': int((self.data.get('statistics') or {}).get('restore_count', 0) or 0), 'emulators': emulator_status, 'controllers': [{'path': path, 'pid': pid} for path, pid in getattr(self, '_connected_pads', {}).items()] if isinstance(getattr(self, '_connected_pads', {}), dict) else [], 'controller_bridge': bridge_status, 'preload': {'status': getattr(getattr(self, '_preload', None), 'status', 'Unavailable'), 'cached_items': len(getattr(getattr(self, '_preload', None), 'cache', {})), 'enabled': bool(settings.get('preload_enabled', True))}, 'services': services, 'last_backup': last_backup, 'last_game': last_process.get('game') or active.get('title', ''), 'current_game_duration_seconds': duration, 'recent_errors': recent_errors, 'recovery': self.data.get('recovery', {})})

    def _portable_export(self):
        path, _ = QFileDialog.getSaveFileName(self, 'Portable Export', 'gamestation-portable.zip', 'Portable archive (*.zip)')
        if not path:
            return
        include_saves, ok = QInputDialog.getItem(self, 'Portable Export', 'Include save/backup configuration:', ['Yes', 'No'], 0, False)
        if not ok:
            return
        include_cache, ok = QInputDialog.getItem(self, 'Portable Export', 'Include artwork cache metadata:', ['Yes', 'No'], 0, False)
        if not ok:
            return
        scope, ok = QInputDialog.getItem(self, 'Portable Export', 'Export scope:', ['All launcher data', 'Selected games', 'Emulator profiles', 'Controller profiles'], 0, False)
        if not ok:
            return
        selected_titles = None
        scope_key = 'all'
        if scope == 'Selected games':
            titles = [str(app.get('title', '')) for app in self.data.get('apps', []) or []]
            selected_titles, ok = QInputDialog.getItem(self, 'Portable Export', 'Select game:', titles, 0, False)
            if not ok:
                return
            selected_titles = [selected_titles]
            scope_key = 'selected'
        elif scope == 'Emulator profiles':
            scope_key = 'emulators'
        elif scope == 'Controller profiles':
            scope_key = 'controllers'
        if self._portable_worker is not None and self._portable_worker.isRunning():
            _GlassMessageDialog.information(self, 'Portable Export', 'An export is already running.')
            return
        self._portable_worker = PortableExportWorker(self.data, path, include_cache == 'Yes', include_saves == 'Yes', selected_titles, scope_key, self)
        self._portable_worker.completed.connect(self._on_portable_export_done)
        self._portable_worker.finished.connect(self._portable_worker.deleteLater)
        self._portable_worker.start()

    def _on_portable_export_done(self, success, detail):
        self._portable_worker = None
        if success:
            _GlassMessageDialog.information(self, 'Portable Export', f'Export completed:\n{detail}')
        else:
            _GlassMessageDialog.warning(self, 'Portable Export', str(detail))

    def _portable_import(self):
        path, _ = QFileDialog.getOpenFileName(self, 'Portable Import', '', 'Portable archive (*.zip)')
        if not path:
            return
        mode, ok = QInputDialog.getItem(self, 'Portable Import', 'Import mode:', ['Merge by game title', 'Replace launcher data'], 0, False)
        if not ok:
            return
        valid, result = _import_portable_data(path, self.data, 'replace' if mode.startswith('Replace') else 'merge')
        if not valid:
            _GlassMessageDialog.warning(self, 'Portable Import', str(result))
            return
        if not _GlassMessageDialog.question(self, 'Confirm Import', 'A rollback copy of current data will be kept. Apply import now?'):
            return
        backup = DB_FILE + '.before_import_' + time.strftime('%Y%m%d_%H%M%S')
        try:
            if os.path.exists(DB_FILE):
                shutil.copy2(DB_FILE, backup)
            self.data = result
            _sync_module_settings_from_data(self.data)
            self._save_data()
            self.refresh_tiles()
            _GlassMessageDialog.information(self, 'Portable Import', 'Import completed. A rollback copy was kept beside the data file.')
        except Exception as exc:
            try:
                if os.path.exists(backup):
                    shutil.copy2(backup, DB_FILE)
            except OSError:
                pass
            _GlassMessageDialog.warning(self, 'Portable Import', str(exc))

    def _game_edit(self, app, action):
        if action == 'game_profile':
            self._edit_game_profile(app)
            return
        if action == 'emulator_profile':
            self._configure_emulator(app)
            return
        if action == 'content_manager':
            self._manage_game_content(app)
            return
        if action == 'run_with_trainer':
            self._run_with_trainer(app)
            return
        if action == 'run_with':
            self._run_with(app)
            return
        if action == 'launch_fps':
            self._launch(app, with_fps=True)
            return
        if action == 'launch_super_frame':
            self._launch(app, with_super_frame=True)
            return
        if action == 'rename':
            new, ok = _RenameDialog.get_text(self, current_text=app.get('title', ''))
            if ok and new:
                old_title = app.get('title', '')
                app['title'] = new
                self._save_data()
                self._post_edit()
                if new != old_title or not os.path.exists(app.get('background') or ''):
                    self._queue_auto_background(app, force=new != old_title)
        elif action == 'change_icon':
            _sel = []
            _dlg = ExplorerDialog(window_title='🖼️  Select Icon Image', filter_exts=ExplorerDialog._IMAGE_EXTS, parent=self)
            _dlg.file_selected.connect(_sel.append)
            _dlg.exec()
            if _sel:
                path = _sel[0]
                app['icon'] = path
                self._save_data()
                self._post_edit()
        elif action == 'change_background':
            _sel = []
            _dlg = ExplorerDialog(window_title='🎨  Select Background Image', filter_exts=ExplorerDialog._IMAGE_EXTS, parent=self)
            _dlg.file_selected.connect(_sel.append)
            _dlg.exec()
            if _sel:
                app['background'] = _sel[0]
                self._save_data()
                self._post_edit()
        elif action == 'change_name_logo':
            _sel = []
            _dlg = ExplorerDialog(window_title='🔤  Select Name Logo Image', filter_exts=ExplorerDialog._IMAGE_EXTS, parent=self)
            _dlg.file_selected.connect(_sel.append)
            _dlg.exec()
            if _sel:
                app['name_logo'] = _sel[0]
                self._save_data()
                dest_path = _logo_dest_path(app, app.get('name') or app.get('title', ''))
                self._logo_pixmap_cache.pop(dest_path, None)
                self._update_info_panel()
        elif action == 'change_audio_theme':
            self._choose_audio_theme_file(app)
        elif action == 'change_audio_file':
            self._choose_audio_theme_file(app)
        elif action == 'trim_audio_theme':
            self._trim_existing_audio_theme(app)
        elif action == 'change_game_run':
            cur_exe = app.get('exe', '')
            start_dir = os.path.dirname(cur_exe) if cur_exe else ''
            if not (start_dir and os.path.isdir(start_dir)):
                start_dir = ''
            _sel = []
            _dlg = ExplorerDialog(start_path=start_dir, window_title='▶️  Select Run File', filter_exts=None, parent=self)
            _dlg.file_selected.connect(_sel.append)
            _dlg.exec()
            if _sel:
                app['exe'] = _sel[0]
                self._save_data()
                self._post_edit()
        elif action == 'auto_background':
            self._queue_auto_background_manual(app)
        elif action == 'download_icon':
            self._queue_auto_icon(app, force=True)
        elif action == 'download_tile_art':
            self._queue_auto_tile_art(app, force=True)
        elif action == 'download_name_logo':
            self._queue_auto_logo(app, force=True)
        elif action == 'download_youtube_audio_theme':
            def _yt_audio_after_search(ok, app=app):
                if ok:
                    return
                ref = self
                existing_pin = str(app.get('youtube_audio_pinned_url') or '').strip()
                title_disp = app.get('title', '') or app.get('name', '')
                url, ok2 = QInputDialog.getText(ref, 'YouTube Audio Theme', f'No matching YouTube audio was found for «{title_disp}».\nYouTube video URL:', text=existing_pin)
                url = (url or '').strip()
                if ok2 and url:
                    if not _youtube_url_is_supported(url):
                        _GlassMessageDialog.warning(ref, 'YouTube Audio Theme', 'That does not look like a valid YouTube video URL.')
                    else:
                        app['youtube_audio_pinned_url'] = url
                        app['youtube_audio_pin_source'] = 'manual'
                        ref._save_data()
                        ref._queue_youtube_audio_theme(app, manual_url=url)
            self._queue_youtube_audio_theme(app, done_cb=_yt_audio_after_search, suppress_failure_dialog=True)
        elif action == 'bg_from_store':
            dlg = StorePickerDialog(app.get('title', ''), self)
            dlg.store_selected.connect(lambda store, a=app: self._queue_auto_background_store(a, store))
            dlg.exec()
        elif action == 'open_file_location':
            # Prefer selecting the configured executable in Explorer; this
            # makes Path useful even when several files share the game folder.
            # Imported records can point at a directory, so keep a folder
            # fallback for those entries.
            raw_path = str(app.get('exe') or app.get('folder') or '').strip()
            path = os.path.abspath(os.path.expanduser(raw_path)) if raw_path else ''
            if path and os.path.isdir(path):
                target = path
            elif path and os.path.isfile(path):
                target = os.path.dirname(path)
            else:
                target = ''
            if target and os.path.isdir(target):
                try:
                    if os.path.isfile(path):
                        subprocess.Popen(['explorer', '/select,', os.path.normpath(path)])
                    else:
                        subprocess.Popen(['explorer', os.path.normpath(target)])
                except OSError:
                    try:
                        os.startfile(target)
                    except (OSError, AttributeError):
                        _GlassMessageDialog.warning(self, 'Open File Location', 'Could not open the game location.')
            else:
                _GlassMessageDialog.warning(self, 'Open File Location', 'Game location not found.')
        elif action == 'move_to_folder':
            fnames = list(self.data.get('folders', {}).keys())
            if not fnames:
                _GlassMessageDialog.information(self, 'Info', 'Create a folder first.')
                return
            fname, ok = _MoveToFolderDialog.get_folder(self, fnames, current_folder=app.get('folder') or '')
            if ok:
                app['folder'] = fname
                self._save_data()
                if self._folder_overlay:
                    self._close_folder()
                self.refresh_tiles()
        elif action == 'controller_profile':
            dlg = ControllerProfileDialog(app, parent=self)

            def _apply_profile(p, a=app):
                ProfileManager.set(a, p)
                self._save_data()
                if hasattr(self, '_tray'):
                    self._tray.showMessage('Game Station', f"Controller profile for «{a.get('title', '')}» set to: {ProfileManager.label(p)}", QSystemTrayIcon.MessageIcon.Information, 2000)
            dlg.profile_selected.connect(_apply_profile)
            dlg.exec()
        elif action == 'safe_mode':
            labels = [label for _key, label in SAFE_MODE_OPTIONS]
            current = str(app.get('safe_mode', 'normal'))
            current_label = dict(SAFE_MODE_OPTIONS).get(current, 'Normal')
            selected, ok = QInputDialog.getItem(self, 'Safe Mode', 'Launch mode for this game:', labels, labels.index(current_label) if current_label in labels else 0, False)
            if ok:
                app['safe_mode'] = next((key for key, label in SAFE_MODE_OPTIONS if label == selected), 'normal')
                self._save_data()
                self._post_edit()
                self._show_slide_toast(f'Safe Mode: {selected}', hold_ms=1800)
        elif action == 'save_backup':
            self._configure_save_backup(app)
        elif action == 'delete':
            apps = self.data.get('apps', [])
            if app in apps:
                apps.remove(app)
                self._save_data()
            if self._folder_overlay:
                self._close_folder()
            self.refresh_tiles()

    def _configure_save_backup(self, app):
        cfg = app.setdefault('save_backup', {})
        settings = self.data.setdefault('settings', {})
        choices = ['Enable / configure automatic backup', 'Create backup now', 'Restore a backup', 'Delete a backup', 'Open backup folder', 'Disable automatic backup']
        action, ok = QInputDialog.getItem(self, 'Save Backup', 'Choose an action:', choices, 0, False)
        if not ok:
            return
        if action == 'Enable / configure automatic backup':
            modes = ['auto', 'manual', 'next_to_exe', 'appdata', 'documents', 'emulator']
            mode, ok = QInputDialog.getItem(self, 'Save location', 'Location mode:', modes, modes.index(str(cfg.get('path_mode', 'auto'))) if cfg.get('path_mode', 'auto') in modes else 0, False)
            if not ok:
                return
            cfg['path_mode'] = mode
            if mode == 'manual':
                selected = QFileDialog.getExistingDirectory(self, 'Select save folder', str(cfg.get('save_dir') or ''))
                if not selected:
                    return
                cfg['save_dir'] = selected
            retention, ok = QInputDialog.getInt(self, 'Retention', 'Keep how many snapshots?', int(cfg.get('retention', settings.get('save_backup_keep_count', 10)) or 10), 1, 200, 1)
            if not ok:
                return
            cfg['retention'] = retention
            cfg['enabled'] = True
            cfg['before_launch'] = True
            cfg['after_exit'] = True
            interval, interval_ok = QInputDialog.getInt(self, 'Scheduled backup', 'Create another snapshot every how many minutes? (0 = off)', int(cfg.get('scheduled_minutes', 0) or 0), 0, 1440, 5)
            if interval_ok:
                cfg['scheduled_minutes'] = interval
            cfg['compress'] = bool(settings.get('save_backup_compress', True))
            self._save_data()
            self._show_slide_toast('Save backup enabled', hold_ms=1800)
        elif action == 'Create backup now':
            success, result = _create_save_backup(app, settings, 'manual')
            if success:
                _record_stat_event(self.data, 'backup_count')
                self._save_data()
                self._show_slide_toast('Save backup created', hold_ms=1800)
            else:
                _GlassMessageDialog.warning(self, 'Save Backup', str(result))
        elif action == 'Restore a backup':
            backups = _list_save_backups(app, settings)
            if not backups:
                _GlassMessageDialog.information(self, 'Save Backup', 'No backup snapshots were found.')
                return
            infos = [_save_backup_info(path) for path in backups]
            labels = [f"{info['name']} · {info['created_at'] or 'unknown date'} · {info['files']} files · {info['size'] / 1024:.0f} KB" for info in infos]
            selected, ok = QInputDialog.getItem(self, 'Restore Save', 'Choose a snapshot:', labels, 0, False)
            if not ok:
                return
            if not _GlassMessageDialog.question(self, 'Confirm Restore', 'A safety backup will be created before replacing files. Restore this snapshot?'):
                return
            chosen = backups[labels.index(selected)]
            success, result = _restore_save_backup(app, settings, chosen)
            if success:
                _record_stat_event(self.data, 'restore_count')
                self._save_data()
                self._show_slide_toast('Save restored safely', hold_ms=2200)
            else:
                _GlassMessageDialog.warning(self, 'Restore failed', str(result))
        elif action == 'Delete a backup':
            backups = _list_save_backups(app, settings)
            if not backups:
                _GlassMessageDialog.information(self, 'Save Backup', 'No backup snapshots were found.')
                return
            infos = [_save_backup_info(path) for path in backups]
            labels = [f"{info['name']} · {info['created_at'] or 'unknown date'} · {info['files']} files · {info['size'] / 1024:.0f} KB" for info in infos]
            selected, ok = QInputDialog.getItem(self, 'Delete Save Backup', 'Choose a snapshot:', labels, 0, False)
            if not ok:
                return
            chosen = backups[labels.index(selected)]
            if _GlassMessageDialog.question(self, 'Confirm Delete', 'Delete this backup permanently?'):
                success, detail = _delete_save_backup(chosen)
                if success:
                    self._show_slide_toast('Backup deleted', hold_ms=1800)
                else:
                    _GlassMessageDialog.warning(self, 'Delete failed', detail)
        elif action == 'Open backup folder':
            folder = _save_backup_root(app, settings)
            os.makedirs(folder, exist_ok=True)
            try:
                os.startfile(folder)
            except Exception:
                subprocess.Popen(['explorer', folder])
        elif action == 'Disable automatic backup':
            cfg['enabled'] = False
            self._save_data()
            self._show_slide_toast('Save backup disabled', hold_ms=1800)

    def _run_with_trainer(self, app):
        trainer_path = app.get('trainer_path', '')
        if trainer_path and os.path.exists(trainer_path):
            self._pending_trainer_path = trainer_path
            self._launch(app)
            return
        s = self.data.get('settings', {})
        if not s.get('trainer_auto_search', DEFAULT_SETTINGS['trainer_auto_search']):
            self._show_trainer_not_found_notice()
            return
        title = (app.get('title') or app.get('name') or '').strip()
        if not title:
            self._show_trainer_not_found_notice()
            return
        s = dict(s)
        game_exe = (app.get('exe') or app.get('path') or '').strip()
        if game_exe:
            try:
                game_dir = os.path.dirname(game_exe)
                if game_dir:
                    s['trainer_save_dir'] = os.path.join(os.path.abspath(game_dir), 'Trainer')
            except (OSError, ValueError):
                pass
        self._show_slide_toast(f'Searching for trainer: {title}...', subtitle='Please wait.', hold_ms=2750)
        self_ref = weakref.ref(self)

        def _search_worker():
            mgr = TrainerManager.instance()
            candidates = mgr.search_trainer_candidates(title)
            if not candidates:

                def _no_trainer():
                    ref = self_ref()
                    if ref:
                        ref._show_trainer_not_found_notice()
                _UI_INVOKER.invoke(_no_trainer)
                return
            dest = mgr.download_trainer_candidates(candidates, title, s)
            if not dest:

                def _dl_fail():
                    ref = self_ref()
                    if ref:
                        ref._show_trainer_not_found_notice()
                _UI_INVOKER.invoke(_dl_fail)
                return

            def _launch_with_trainer(dest=dest):
                ref = self_ref()
                if not ref:
                    return
                ref._set_trainer_path_silent(app, dest)
                ref._pending_trainer_path = dest
                ref._launch(app)
                ref._show_trainer_installed_notice(title)
            _UI_INVOKER.invoke(_launch_with_trainer)
        threading.Thread(target=_search_worker, daemon=True, name='TrainerSearch').start()

    def _run_with(self, app):
        cur = app.get('run_with_exe', '')
        start_dir = os.path.dirname(cur) if cur else os.path.dirname(app.get('exe', '') or '')
        if not (start_dir and os.path.isdir(start_dir)):
            start_dir = ''
        _sel = []
        _dlg = ExplorerDialog(start_path=start_dir, window_title='▶️  Run With — Select Executable', filter_exts={'.exe', '.lnk', '.bat', '.cmd'}, parent=self)
        _dlg.file_selected.connect(_sel.append)
        _dlg.exec()
        if _sel:
            app['run_with_exe'] = _sel[0]
            self._save_data()
            self._post_edit()

    def _show_trainer_not_found_notice(self):
        notice = QDialog(self)
        notice.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.Dialog | Qt.WindowType.WindowStaysOnTopHint)
        notice.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        notice.setModal(False)
        vl = QVBoxLayout(notice)
        vl.setContentsMargins(0, 0, 0, 0)
        frame = _SharedGlassFrame(radius=22, parent=notice)
        frame.setObjectName('tnf')
        fl = QVBoxLayout(frame)
        fl.setContentsMargins(30, 20, 30, 20)
        fl.setSpacing(5)
        msg_lbl = QLabel('Trainer Not Available')
        msg_lbl.setFont(QFont('Segoe UI', 13, QFont.Weight.Bold))
        msg_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        msg_lbl.setStyleSheet('color:#dde0ff; background:transparent; border:none;')
        fl.addWidget(msg_lbl)
        sub_lbl = QLabel('No trainer was found for this game.')
        sub_lbl.setFont(QFont('Segoe UI', 9))
        sub_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        sub_lbl.setStyleSheet('color:rgba(200,210,255,180); background:transparent; border:none;')
        fl.addWidget(sub_lbl)
        vl.addWidget(frame)
        notice.adjustSize()
        screen = self.screen()
        if screen:
            sg = screen.geometry()
            notice.move(sg.center() - QPoint(notice.width() // 2, notice.height() // 2))
        notice.setWindowOpacity(0.0)
        notice.show()
        fade_in = QPropertyAnimation(notice, b'windowOpacity', notice)
        fade_in.setDuration(150)
        fade_in.setStartValue(0.0)
        fade_in.setEndValue(1.0)
        fade_in.setEasingCurve(QEasingCurve.Type.OutCubic)
        fade_in.start()
        notice._fade_in = fade_in

        def _begin_fade_out():
            fade_out = QPropertyAnimation(notice, b'windowOpacity', notice)
            fade_out.setDuration(250)
            fade_out.setStartValue(1.0)
            fade_out.setEndValue(0.0)
            fade_out.setEasingCurve(QEasingCurve.Type.InCubic)
            fade_out.finished.connect(notice.close)
            fade_out.start()
            notice._fade_out = fade_out
        QTimer.singleShot(750, _begin_fade_out)

    def _show_trainer_installed_notice(self, title: str=''):
        notice = QDialog(self)
        notice.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.Dialog | Qt.WindowType.WindowStaysOnTopHint)
        notice.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        notice.setModal(False)
        vl = QVBoxLayout(notice)
        vl.setContentsMargins(0, 0, 0, 0)
        frame = _SharedGlassFrame(radius=22, parent=notice)
        frame.setObjectName('tins')
        fl = QVBoxLayout(frame)
        fl.setContentsMargins(30, 20, 30, 20)
        fl.setSpacing(5)
        head = QLabel('Trainer Ready')
        head.setFont(QFont('Segoe UI', 13, QFont.Weight.Bold))
        head.setAlignment(Qt.AlignmentFlag.AlignCenter)
        head.setStyleSheet('color:#dde0ff; background:transparent; border:none;')
        fl.addWidget(head)
        if title:
            sub_text = f'Trainer for {title} will launch after the game starts.'
        else:
            sub_text = 'Trainer will launch automatically after the game starts.'
        sub = QLabel(sub_text)
        sub.setFont(QFont('Segoe UI', 9))
        sub.setAlignment(Qt.AlignmentFlag.AlignCenter)
        sub.setStyleSheet('color:rgba(200,210,255,180); background:transparent; border:none;')
        fl.addWidget(sub)
        vl.addWidget(frame)
        notice.adjustSize()
        screen = self.screen()
        if screen:
            sg = screen.geometry()
            notice.move(sg.center() - QPoint(notice.width() // 2, notice.height() // 2))
        notice.setWindowOpacity(0.0)
        notice.show()
        fade_in = QPropertyAnimation(notice, b'windowOpacity', notice)
        fade_in.setDuration(150)
        fade_in.setStartValue(0.0)
        fade_in.setEndValue(1.0)
        fade_in.setEasingCurve(QEasingCurve.Type.OutCubic)
        fade_in.start()
        notice._fade_in = fade_in

        def _begin_fade_out():
            fade_out = QPropertyAnimation(notice, b'windowOpacity', notice)
            fade_out.setDuration(250)
            fade_out.setStartValue(1.0)
            fade_out.setEndValue(0.0)
            fade_out.setEasingCurve(QEasingCurve.Type.InCubic)
            fade_out.finished.connect(notice.close)
            fade_out.start()
            notice._fade_out = fade_out
        QTimer.singleShot(750, _begin_fade_out)

    def _show_slide_toast(self, text: str='Finished', subtitle: str='', hold_ms: int=750):
        toast = QDialog(self)
        toast.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.Dialog | Qt.WindowType.WindowStaysOnTopHint)
        toast.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        toast.setModal(False)
        vl = QVBoxLayout(toast)
        vl.setContentsMargins(0, 0, 0, 0)
        frame = _SharedGlassFrame(radius=18, parent=toast)
        frame.setObjectName('slideToast')
        fl = QVBoxLayout(frame)
        fl.setContentsMargins(26, 14, 26, 14)
        fl.setSpacing(3)
        msg_lbl = QLabel(text)
        msg_lbl.setFont(QFont('Segoe UI', 11, QFont.Weight.Bold))
        msg_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        msg_lbl.setStyleSheet('color:#dde0ff; background:transparent; border:none;')
        fl.addWidget(msg_lbl)
        if subtitle:
            sub_lbl = QLabel(subtitle)
            sub_lbl.setFont(QFont('Segoe UI', 8))
            sub_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            sub_lbl.setStyleSheet('color:rgba(200,210,255,180); background:transparent; border:none;')
            fl.addWidget(sub_lbl)
        vl.addWidget(frame)
        toast.adjustSize()
        screen = self.screen() or QApplication.primaryScreen()
        sg = screen.availableGeometry() if screen else QRect(0, 0, 1920, 1080)
        margin = 12
        max_w = max(1, sg.width() - margin * 2)
        if toast.width() > max_w:
            toast.setMaximumWidth(max_w)
            toast.adjustSize()
        toast_w = min(toast.width(), max_w)
        toast_h = toast.height()
        x = max(sg.left() + margin, min(sg.right() - toast_w - margin, sg.right() - toast_w - margin))
        start_y = sg.top() - toast.height() - 10
        rest_y_abs = max(sg.top() + margin, min(sg.bottom() - toast_h - margin, sg.top() + margin))
        toast.move(int(x), int(start_y))
        toast.setWindowOpacity(1.0)
        toast.show()
        slide_in = QPropertyAnimation(toast, b'pos', toast)
        slide_in.setDuration(280)
        slide_in.setStartValue(QPoint(int(x), int(start_y)))
        slide_in.setEndValue(QPoint(int(x), int(rest_y_abs)))
        slide_in.setEasingCurve(QEasingCurve.Type.OutCubic)
        slide_in.start()
        toast._slide_in = slide_in

        def _begin_slide_out():
            if not toast.isVisible():
                return
            group_pos = QPropertyAnimation(toast, b'pos', toast)
            group_pos.setDuration(250)
            group_pos.setStartValue(toast.pos())
            group_pos.setEndValue(QPoint(int(x), int(start_y)))
            group_pos.setEasingCurve(QEasingCurve.Type.InCubic)
            fade_out = QPropertyAnimation(toast, b'windowOpacity', toast)
            fade_out.setDuration(250)
            fade_out.setStartValue(1.0)
            fade_out.setEndValue(0.0)
            fade_out.setEasingCurve(QEasingCurve.Type.InCubic)
            fade_out.finished.connect(toast.close)
            group_pos.start()
            fade_out.start()
            toast._slide_out = group_pos
            toast._fade_out = fade_out
        QTimer.singleShot(max(0, int(hold_ms)), _begin_slide_out)

    def _retry_bg_manual_if_not_stopped(self, app, gen):
        if getattr(self, '_dl_stop_gen', 0) != gen:
            return
        self._queue_auto_background_manual_impl(app)

    def _stop_all_downloads(self):
        self._icon_inflight.clear()
        if hasattr(self, '_tile_art_inflight'):
            self._tile_art_inflight.clear()
        self._logo_inflight.clear()
        if not hasattr(self, '_audio_theme_abandoned'):
            self._audio_theme_abandoned = set()
        self._audio_theme_abandoned.update(getattr(self, '_audio_theme_inflight', set()))
        self._audio_theme_inflight.clear()
        prefetch = self.__dict__.get('_candidate_prefetch', {})
        for entry in prefetch.values():
            entry['cancelled'] = True
        self._candidate_prefetch = {}
        if not hasattr(self, '_bg_dl_abandoned'):
            self._bg_dl_abandoned = set()
        self._bg_dl_abandoned.update(self._bg_dl_active.keys())
        self._bg_dl_active = {}
        self._bg_dl_queue = []
        self._bg_confirm_pending = set()
        self._bg_fail_count = {}
        self._bg_next_ok_at = {}
        self._bg_fail_since = {}
        self._bg_last_notify = {}
        self._bg_manual_retry_count = {}
        self._dl_stop_gen = getattr(self, '_dl_stop_gen', 0) + 1
        _manual_priority_force_reset()
        for sp in list(getattr(self, '_active_dl_spinners', [])):
            try:
                sp.stop()
            except Exception:
                pass
        self._active_dl_spinners = []
        if hasattr(self, '_tray'):
            self._tray.showMessage('Game Station', 'All downloads stopped', QSystemTrayIcon.MessageIcon.Information, 2000)
        self._show_slide_toast('Stopped')

    def _set_trainer_path_silent(self, app, path):
        app['trainer_path'] = path
        self._save_data()

    def _auto_confirm_game_titles(self):
        pending = [a for a in self.data.get('apps', []) if a.get('title_confirm_version') != _TITLE_CONFIRM_VERSION and (a.get('exe') or '').strip()]
        if not pending:
            return
        self_ref = weakref.ref(self)
        _appdata_dbg = os.environ.get('APPDATA') or os.path.expanduser('~')
        _title_debug_log = os.path.join(_appdata_dbg, 'PS5Launcher', 'title_confirm_debug.log')
        try:
            os.makedirs(os.path.dirname(_title_debug_log), exist_ok=True)
        except Exception:
            pass

        def _worker():
            resolved = {}
            target_counts = {}
            for app in pending:
                exe = (app.get('exe') or '').strip()
                if not exe:
                    continue
                real_path = _real_path_for_root_detection(exe)
                resolved[id(app)] = real_path
                if exe.lower().endswith('.lnk') and real_path != exe:
                    target_counts[real_path] = target_counts.get(real_path, 0) + 1
            for app in pending:
                exe = (app.get('exe') or '').strip()
                if not exe or not os.path.exists(exe):
                    continue
                try:
                    real_path = resolved.get(id(app), exe)
                    skip_sfo = False
                    if exe.lower().endswith('.lnk') and _looks_like_shared_launcher_target(real_path, target_counts):
                        raw_name = os.path.splitext(os.path.basename(exe))[0]
                        game_root = None
                    else:
                        root_folder = _find_game_root_folder(real_path)
                        bin_id_root = _bin_content_id_root(real_path, root_folder)
                        if bin_id_root:
                            root_folder, _bin_id_name = bin_id_root
                            skip_sfo = True
                        raw_name = os.path.basename(root_folder.rstrip('\\/')) or exe
                        game_root = root_folder
                    title, source = _resolve_standard_title(raw_name, game_root=game_root, skip_sfo=skip_sfo)
                    try:
                        with open(_title_debug_log, 'a', encoding='utf-8') as f:
                            f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] exe={exe!r} game_root={game_root!r} raw_name={raw_name!r} -> title={title!r} source={source!r}\n")
                    except Exception:
                        pass
                except Exception as e:
                    try:
                        with open(_title_debug_log, 'a', encoding='utf-8') as f:
                            f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {exe!r}: ERROR {type(e).__name__}: {e}\n")
                    except Exception:
                        pass
                    continue

                def _apply(app=app, title=title, source=source, raw_name=raw_name):
                    ref = self_ref()
                    if ref is None:
                        return
                    if source == 'unconfirmed':
                        return
                    old_title = (app.get('title') or '').strip()
                    app['title_confirmed'] = True
                    app['title_confirm_source'] = source
                    app['title_confirm_version'] = _TITLE_CONFIRM_VERSION
                    changed = bool(title) and title != old_title
                    if changed:
                        app['title'] = title
                    ref._save_data()
                    if changed:
                        ref._post_edit()
                        try:
                            with open(_title_debug_log, 'a', encoding='utf-8') as f:
                                f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {raw_name!r} -> {title!r} (source: {source})\n")
                        except Exception:
                            pass
                        if hasattr(ref, '_tray'):
                            ref._tray.showMessage('Game Station', f'Title “{old_title or raw_name}” corrected to the standard name “{title}”.', QSystemTrayIcon.MessageIcon.Information, 3000)
                _UI_INVOKER.invoke(_apply)
                time.sleep(0.3)
        threading.Thread(target=_worker, daemon=True, name='TitleAutoConfirm').start()

    def _app_bg_rotate_cache_dir(self) -> str:
        # Versioned so old loremflickr/picsum stock photos are never reused
        # after upgrading the launcher.
        d = os.path.join(_APP_DATA_DIR, 'app_background_rotation_v2')
        try:
            os.makedirs(d, exist_ok=True)
        except Exception:
            pass
        return d

    def _app_bg_rotate_batch_dir(self, batch_num: int) -> str:
        d = os.path.join(self._app_bg_rotate_cache_dir(), f'batch_{batch_num:03d}')
        try:
            os.makedirs(d, exist_ok=True)
        except Exception:
            pass
        return d

    def _app_bg_rotate_predownload_batch(self, batch_num: int):
        """Downloads all 100 images for `batch_num` into its local cache
        folder up front, skipping any already present & valid, then
        marks the batch complete. Runs entirely in the background --
        rotation itself never blocks on the network. Safe to call
        repeatedly (e.g. once per timer tick while a batch is still
        being prepared): a batch already downloading or already
        complete is a no-op."""
        if not hasattr(self, '_bg_batches_downloading'):
            self._bg_batches_downloading = set()
        batch_dir = self._app_bg_rotate_batch_dir(batch_num)
        complete_flag = os.path.join(batch_dir, 'complete.flag')
        if os.path.exists(complete_flag) or batch_num in self._bg_batches_downloading:
            return
        self._bg_batches_downloading.add(batch_num)
        self_ref = weakref.ref(self)

        def _fetch_one(item):
            idx, (primary, fallback) = item
            out_path = os.path.join(batch_dir, f'{idx:03d}.jpg')
            if os.path.exists(out_path):
                return
            for candidate_url in (primary, fallback):
                try:
                    raw = _http_get_bytes(candidate_url, timeout=30, retries=3)
                    tmp_path = out_path + '.tmp'
                    with open(tmp_path, 'wb') as f:
                        f.write(raw)
                    # QImage, not QPixmap -- this runs on a background
                    # thread and QPixmap must only be touched on the GUI
                    # thread.
                    probe_img = QImage(tmp_path)
                    if probe_img.isNull():
                        raise ValueError(f'downloaded file is not a valid image: {candidate_url}')
                    width, height = probe_img.width(), probe_img.height()
                    if min(width, height) < 720:
                        raise ValueError(f'image is too small ({width}x{height})')
                    if abs((width / height) - (16 / 9)) / (16 / 9) > 0.12:
                        raise ValueError(f'image is not a suitable landscape wallpaper ({width}x{height})')
                    if _has_padding_bars(probe_img):
                        raise ValueError('image contains padding bars')
                    os.replace(tmp_path, out_path)
                    return
                except Exception as exc:
                    try:
                        with open(_asset_search_log_path(), 'a', encoding='utf-8') as log:
                            log.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] app background batch {batch_num} #{idx}: FAILED {candidate_url}: {type(exc).__name__}: {exc}\n")
                    except Exception:
                        pass
                    continue

        def _worker():
            try:
                # URL discovery includes network requests, so keep it off the
                # Qt/UI thread just like the actual image downloads.
                pairs = _app_bg_batch_urls(batch_num)
                if not pairs:
                    try:
                        with open(_asset_search_log_path(), 'a', encoding='utf-8') as log:
                            log.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] app background batch {batch_num}: no PS5/gaming image URLs found\n")
                    except Exception:
                        pass
                    return
                with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
                    list(pool.map(_fetch_one, enumerate(pairs, start=1)))
                downloaded = len([f for f in os.listdir(batch_dir) if f.endswith('.jpg')])
                if downloaded >= len(pairs):
                    try:
                        with open(complete_flag, 'w', encoding='utf-8') as f:
                            f.write(str(downloaded))
                    except Exception:
                        pass
            finally:
                ref = self_ref()
                if ref is not None and hasattr(ref, '_bg_batches_downloading'):
                    ref._bg_batches_downloading.discard(batch_num)
        threading.Thread(target=_worker, daemon=True, name=f'AppBgBatchDownload-{batch_num}').start()

    def _maybe_rotate_app_background(self, force: bool=False):
        """Automatically swap the launcher's OWN background (not a
        per-game background) to the next image in the local batch
        cache, at most once per app_bg_rotate_interval_hours (default
        24h). Runs on a periodic timer so it also catches up after the
        app was closed/asleep past the interval.

        Images are pre-downloaded a full batch of 100 at a time (see
        _app_bg_rotate_predownload_batch) -- once that batch is on
        disk, rotation just points the background at the next local
        file each time and never re-downloads. Only once all 100 in
        the current batch have been used does it move on to a fresh
        batch of 100, which is fetched ahead of time so it's usually
        already ready when needed.

        The "has enough time passed" check is anchored to the real
        system clock/calendar (datetime.now(), i.e. Windows' own date
        and time) rather than any in-process/monotonic timer, so it
        survives app restarts, sleep, and being closed for days
        correctly. If Windows' clock ever moves backward relative to
        the last recorded rotation (timezone change, DST correction,
        manual clock edit), last_ts can end up in the future -- that's
        treated as "never rotated" instead of silently waiting up to
        another full interval."""
        if getattr(self, '_shutting_down', False):
            return
        import datetime as _dt
        settings = self.data.get('settings', {})
        if not force and not bool(settings.get('app_bg_rotate_enabled', False)):
            return
        interval_s = max(1.0, float(settings.get('app_bg_rotate_interval_hours', 24) or 24)) * 3600.0
        last_ts = float(settings.get('app_bg_rotate_last_ts', 0) or 0)
        now_ts = _dt.datetime.now().timestamp()
        elapsed = now_ts - last_ts if now_ts >= last_ts else float('inf')
        if not force and elapsed < interval_s:
            return
        batch_num = int(settings.get('app_bg_rotate_batch', 1) or 1)
        idx = int(settings.get('app_bg_rotate_index', 0) or 0) % 100
        batch_dir = self._app_bg_rotate_batch_dir(batch_num)
        img_path = os.path.join(batch_dir, f'{idx + 1:03d}.jpg')
        if not os.path.exists(img_path):
            # This batch isn't (fully) downloaded to disk yet -- kick off
            # (or keep waiting on) its download and just try again next
            # tick instead of hitting the network synchronously here.
            self._app_bg_rotate_predownload_batch(batch_num)
            return
        next_idx = idx + 1
        next_batch = batch_num
        if next_idx >= 100:
            # This batch is fully used up -- move to a brand new set of
            # 100 next time.
            next_idx = 0
            next_batch = batch_num + 1
        # Once we're on the last few images of the batch, start fetching
        # the next 100 in the background so they're ready and waiting
        # locally by the time this batch runs out.
        if idx >= 95:
            self._app_bg_rotate_predownload_batch(batch_num + 1)
        s2 = dict(settings)
        s2['default_background_path'] = img_path
        s2['app_bg_rotate_index'] = next_idx
        s2['app_bg_rotate_batch'] = next_batch
        s2['app_bg_rotate_last_ts'] = time.time()
        self.data['settings'] = s2
        self._save_data()
        if hasattr(self, 'central') and hasattr(self.central, 'set_default_path'):
            self.central.set_default_path(img_path)

    def _apply_random_app_background(self):
        """"Change Now" action: immediately switches to a random already
        -downloaded image from the current local batch, without waiting
        for the scheduled interval. Also re-syncs the rotation
        index/timestamp so the next scheduled rotation continues
        cleanly from here instead of re-picking the same image."""
        settings = self.data.get('settings', {})
        batch_num = int(settings.get('app_bg_rotate_batch', 1) or 1)
        batch_dir = self._app_bg_rotate_batch_dir(batch_num)
        try:
            available = sorted(f for f in os.listdir(batch_dir) if f.endswith('.jpg'))
        except Exception:
            available = []
        if not available:
            # Nothing downloaded yet for this batch -- kick off the
            # download and let the user know, rather than silently doing
            # nothing.
            self._app_bg_rotate_predownload_batch(batch_num)
            if hasattr(self, '_show_slide_toast'):
                self._show_slide_toast('Preparing backgrounds', subtitle='Downloading the image set for the first time — try again in a moment.', hold_ms=3000)
            return
        choice = random.choice(available)
        idx = int(os.path.splitext(choice)[0])  # 1-based file number
        img_path = os.path.join(batch_dir, choice)
        next_idx = idx % 100
        next_batch = batch_num
        if next_idx == 0:
            next_batch = batch_num + 1
        if idx >= 95:
            self._app_bg_rotate_predownload_batch(batch_num + 1)
        s2 = dict(settings)
        s2['default_background_path'] = img_path
        s2['app_bg_rotate_index'] = next_idx
        s2['app_bg_rotate_batch'] = next_batch
        s2['app_bg_rotate_last_ts'] = time.time()
        self.data['settings'] = s2
        self._save_data()
        if hasattr(self, 'central') and hasattr(self.central, 'set_default_path'):
            self.central.set_default_path(img_path)

    def _auto_fill_missing_backgrounds(self):
        _manual_priority_watchdog_reset_if_stuck()
        for app in self.data.get('apps', []):
            self._queue_auto_background(app, force=False)

    def _auto_fill_missing_logos(self):
        pending = []
        for app in self.data.get('apps', []):
            title = (app.get('title') or app.get('name') or '').strip()
            if not title:
                continue
            dest_path = _logo_dest_path(app, title)
            if os.path.exists(dest_path):
                continue
            if dest_path in self._logo_inflight:
                continue
            self._logo_inflight.add(dest_path)
            pending.append((title, dest_path))
        if not pending:
            return
        self_ref = weakref.ref(self)
        dp_to_title = {dp: title for title, dp in pending}

        def _bulk_worker():
            with concurrent.futures.ThreadPoolExecutor(max_workers=min(MAX_LOGO_WORKERS, len(pending))) as pool:
                futs = {pool.submit(_download_name_logo, name, dp): dp for name, dp in pending}
                for fut in concurrent.futures.as_completed(futs):
                    dp = futs[fut]
                    try:
                        result = fut.result()
                    except Exception:
                        result = ''

                    def _ui_cleanup(dp=dp, result=result):
                        ref = self_ref()
                        if ref is None:
                            return
                        ref._logo_inflight.discard(dp)
                        if not result or not os.path.exists(result):
                            return
                        cur = ref._current_selected_app
                        cur_name = cur.get('name') or cur.get('title') or '' if cur else ''
                        if cur_name != dp_to_title.get(dp, ''):
                            return
                        pix = ref._logo_pixmap_cache.get(dp)
                        if pix is None:
                            pix = QPixmap(result)
                            if pix.isNull():
                                return
                            pix = ref._trim_transparent_margins(pix)
                            ref._logo_pixmap_cache[dp] = pix
                        ref._set_name_logo_pixmap(pix)
                    _UI_INVOKER.invoke(_ui_cleanup)
        threading.Thread(target=_bulk_worker, daemon=True).start()

    def _auto_fill_missing_icons(self):
        # The scan below calls _icon_quality_is_acceptable(), which decodes
        # the image and runs a sharpness measurement per app -- for a large
        # library this is real CPU work and used to run synchronously on
        # the UI thread (visible as a multi-second freeze ~14s after
        # startup). Do the whole scan on a worker thread instead; only the
        # small pieces that touch self.data / self._icon_inflight / disk
        # writes are marshalled back to the UI thread.
        self_ref = weakref.ref(self)

        def _scan_worker():
            ref = self_ref()
            if ref is None:
                return
            pending = []
            found_existing = []
            for app in ref.data.get('apps', []):
                title = (app.get('title') or app.get('name') or '').strip()
                if not title:
                    continue
                manual_icon = (app.get('icon') or '').strip()
                dest_path = _icon_dest_path(app, title)
                if manual_icon and manual_icon != dest_path and _icon_quality_is_acceptable(manual_icon):
                    continue
                if os.path.exists(dest_path) and _bg_file_matches_title(dest_path, title) and _icon_quality_is_acceptable(dest_path):
                    _existing_img = QImage(dest_path)
                    if not _existing_img.isNull() and _is_valid_game_icon(_existing_img):
                        if app.get('icon') != dest_path:
                            found_existing.append((app, dest_path))
                        continue
                if dest_path in ref._icon_inflight:
                    continue
                pending.append((app, title, dest_path))

            def _apply_scan():
                ref2 = self_ref()
                if ref2 is None:
                    return
                if found_existing:
                    for app, dest_path in found_existing:
                        app['icon'] = dest_path
                    ref2._save_data()
                still_pending = []
                for app, title, dest_path in pending:
                    if dest_path in ref2._icon_inflight:
                        continue
                    ref2._icon_inflight.add(dest_path)
                    still_pending.append((app, title, dest_path))
                if still_pending:
                    ref2._start_icon_bulk_download(still_pending)
            _UI_INVOKER.invoke(_apply_scan)
        threading.Thread(target=_scan_worker, daemon=True, name='IconAutoScan').start()

    def _start_icon_bulk_download(self, pending):
        self_ref = weakref.ref(self)

        def _bulk_worker():
            with concurrent.futures.ThreadPoolExecutor(max_workers=min(MAX_ICON_WORKERS, len(pending))) as pool:

                def _submit_icon(app, title, dp):
                    exclude = set(app.get('icon_rejected_hashes') or [])
                    return _download_icon(title, dp, exclude_hashes=exclude)
                futs = {pool.submit(_submit_icon, app, title, dp): (app, title, dp) for app, title, dp in pending}
                for fut in concurrent.futures.as_completed(futs):
                    app, title, dp = futs[fut]
                    try:
                        result = fut.result()
                    except Exception:
                        result = ''

                    def _ui_cleanup(app=app, title=title, dp=dp, result=result):
                        ref = self_ref()
                        if ref is None:
                            return
                        ref._icon_inflight.discard(dp)
                        if not result or not os.path.exists(result):
                            return
                        _write_bg_sidecar(dp, title)
                        cur_manual = (app.get('icon') or '').strip()
                        if cur_manual and cur_manual != dp and _icon_quality_is_acceptable(cur_manual):
                            return
                        _evict_cached_art(result)
                        app['icon'] = result
                        ref._save_data()
                        ref._post_edit()
                    _UI_INVOKER.invoke(_ui_cleanup)
        threading.Thread(target=_bulk_worker, daemon=True, name='IconAutoDownload').start()

    def _auto_fill_missing_tile_art(self):
        if not hasattr(self, '_tile_art_inflight'):
            self._tile_art_inflight = set()
        pending = []
        for app in self.data.get('apps', []):
            title = (app.get('title') or app.get('name') or '').strip()
            if not title:
                continue
            dest_path = _tile_dest_path(app, title)
            if os.path.exists(dest_path) and _bg_file_matches_title(dest_path, title):
                if app.get('tile_art') != dest_path:
                    app['tile_art'] = dest_path
                    self._save_data()
                continue
            if dest_path in self._tile_art_inflight:
                continue
            self._tile_art_inflight.add(dest_path)
            pending.append((app, title, dest_path))
        if not pending:
            return
        self_ref = weakref.ref(self)

        def _bulk_worker():
            with concurrent.futures.ThreadPoolExecutor(max_workers=min(MAX_TILE_WORKERS, len(pending))) as pool:

                def _submit(app, title, dp):
                    exclude = set(app.get('tile_art_rejected_hashes') or [])
                    return _download_tile_art(title, dp, exclude_hashes=exclude)
                futs = {pool.submit(_submit, app, title, dp): (app, title, dp) for app, title, dp in pending}
                for fut in concurrent.futures.as_completed(futs):
                    app, title, dp = futs[fut]
                    try:
                        result = fut.result()
                    except Exception:
                        result = ''

                    def _ui_cleanup(app=app, title=title, dp=dp, result=result):
                        ref = self_ref()
                        if ref is None:
                            return
                        ref._tile_art_inflight.discard(dp)
                        if not result or not os.path.exists(result):
                            return
                        _write_bg_sidecar(dp, title)
                        cur_tile = (app.get('tile_art') or '').strip()
                        if cur_tile and cur_tile != dp:
                            return
                        app['tile_art'] = dp
                        _evict_cached_art(dp)
                        ref._save_data()
                        ref._post_edit()
                    _UI_INVOKER.invoke(_ui_cleanup)
        threading.Thread(target=_bulk_worker, daemon=True, name='TileArtAutoDownload').start()

    def _show_asset_spinner(self, kind: str, app: dict=None):
        try:
            if kind in ('icon', 'tile_art'):
                carousel = getattr(self, '_game_carousel', None)
                if carousel is None or not carousel.isVisible():
                    return None
                rect = carousel.selected_tile_rect()
                spin = _MiniSpinner(carousel)
                spin.move(rect.center().x() - spin.width() // 2, rect.center().y() - spin.height() // 2)
            elif kind == 'name_logo':
                lbl = getattr(self, '_name_logo_lbl', None)
                if lbl is None:
                    return None
                parent = lbl.parentWidget() or lbl
                geo = lbl.geometry()
                spin = _MiniSpinner(parent)
                spin.move(geo.center().x() - spin.width() // 2, geo.center().y() - spin.height() // 2)
            elif kind == 'background':
                central = getattr(self, 'central', None)
                if central is None:
                    return None
                spin = _MiniSpinner(central)
                spin.move(central.width() // 2 - spin.width() // 2, central.height() // 2 - spin.height() // 2)
            else:
                return None
            spin.show()
            spin.raise_()
            if not hasattr(self, '_active_dl_spinners'):
                self._active_dl_spinners = []
            self._active_dl_spinners.append(spin)
            return spin
        except Exception:
            return None

    @staticmethod
    def _hide_asset_spinner(spin):
        if spin is not None:
            try:
                spin.stop()
            except Exception:
                pass

    def _queue_auto_tile_art(self, app, force=True):
        title = (app.get('title') or app.get('name') or '').strip()
        if not title:
            return
        dest_path = _tile_dest_path(app, title)
        if not hasattr(self, '_tile_art_inflight'):
            self._tile_art_inflight = set()
        if dest_path in self._tile_art_inflight:
            return
        self._tile_art_inflight.add(dest_path)
        _backup_asset_file(dest_path)
        exclude = set(app.get('tile_art_rejected_hashes') or [])
        self_ref = weakref.ref(self)
        spin = self._show_asset_spinner('tile_art', app)
        self._show_slide_toast('Downloading')

        def _worker():
            try:
                candidates = _fetch_candidates_with_escalation(_fetch_all_tile_art_candidates, title, exclude_hashes=exclude, max_rounds=8, progress_cb=_asset_search_progress_cb(self_ref, title, 'tile art'))
            except Exception:
                candidates = []

            def _ui_cleanup(candidates=candidates):
                _manual_priority_end()
                ref = self_ref()
                if ref is None:
                    return
                ref._hide_asset_spinner(spin)
                if candidates:
                    ref._confirm_with_candidate_queue(app, 'tile_art', dest_path, candidates)
                else:
                    ref._tile_art_inflight.discard(dest_path)
                    _discard_asset_backup(dest_path)
                    if hasattr(ref, '_tray'):
                        ref._tray.showMessage('Game Station', f"Couldn't find matching tile art for {title}", QSystemTrayIcon.MessageIcon.Warning, 2500)
                    ref._show_slide_toast('Failed')
            _UI_INVOKER.invoke(_ui_cleanup)
        _manual_priority_begin()
        threading.Thread(target=_worker, daemon=True, name='TileArtManualDownload').start()

